// ─── ControlPanel ────────────────────────────────────────────
// Printer connection controls: connect/disconnect, e-stop, print controls, homing.

import { useState } from 'react'
import { Settings, AlertTriangle, Play, Pause, Square } from 'lucide-react'
import { printerApi } from '@/services/printer-api'
import { getErrorMessage } from '@/utils/helpers'
import type { Printer, PrinterCommand } from '@core/types/printer'

export function ControlPanel({ printer }: { printer: Printer }) {
  const [loading, setLoading] = useState<string | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [success, setSuccess] = useState<string | null>(null)

  const sendCommand = async (command: PrinterCommand, label: string) => {
    setLoading(label); setError(null); setSuccess(null)
    try {
      await printerApi.sendCommand(printer.id, command)
      setSuccess(`${label} sent`)
      setTimeout(() => setSuccess(null), 2000)
    } catch (err) {
      setError(`Failed to ${label}: ${getErrorMessage(err)}`)
    } finally { setLoading(null) }
  }

  const handleConnect = async () => {
    setLoading('connect'); setError(null); setSuccess(null)
    try {
      await printerApi.connect(printer.id)
      setSuccess('Connecting...')
      setTimeout(() => setSuccess(null), 3000)
    } catch (err) {
      setError(`Connect failed: ${getErrorMessage(err)}`)
    } finally { setLoading(null) }
  }

  const handleDisconnect = async () => {
    setLoading('disconnect'); setError(null)
    try { await printerApi.disconnect(printer.id) }
    catch (err) { setError(`Disconnect failed: ${getErrorMessage(err)}`) }
    finally { setLoading(null) }
  }

  const isConnected = printer.status !== 'disconnected' && printer.status !== 'error'
  const isPrinting = printer.status === 'printing'
  const isPaused = printer.status === 'paused'
  // subStatus 'cancelling' = transient printer state (cancel sent, awaiting adapter).
  // Different from job.status 'cancelling' — this is printer-level, not job-level.
  const isCancelling = printer.subStatus === 'cancelling'

  return (
    <div className="space-y-3">
      <div className="bg-gray-900/50 border border-gray-700 rounded-lg p-3">
        <h3 className="flex items-center gap-2 text-xs font-semibold text-gray-200 mb-2">
          <Settings className="w-3 h-3 text-gray-400" />Controls
        </h3>

        {/* Connection row */}
        <div className="flex items-center justify-between mb-2 p-1.5 bg-gray-800/50 rounded border border-gray-700">
          <div className="flex items-center gap-2">
            <div className={`w-1.5 h-1.5 rounded-full ${isConnected ? 'bg-green-400 animate-pulse' : 'bg-gray-500'}`} />
            <span className="text-[10px] text-gray-400">
              {printer.status === 'disconnected' ? 'Disconnected' : printer.status === 'connecting' ? 'Connecting...' : printer.status === 'error' ? 'Error' : 'Connected'}
            </span>
            <span className="text-[10px] text-gray-600">({printer.adapterType})</span>
          </div>
          {isConnected ? (
            <button onClick={handleDisconnect} disabled={loading !== null || isPrinting}
              className="px-2 py-0.5 text-[10px] bg-gray-700 text-gray-300 border border-gray-600 rounded hover:bg-gray-600 disabled:opacity-50">
              {loading === 'disconnect' ? '...' : 'Disconnect'}
            </button>
          ) : (
            <button onClick={handleConnect} disabled={loading !== null}
              className="px-2 py-0.5 text-[10px] bg-cyan-500/20 text-cyan-400 border border-cyan-500/50 rounded hover:bg-cyan-500/30 disabled:opacity-50">
              {loading === 'connect' ? 'Connecting...' : '⚡ Connect'}
            </button>
          )}
        </div>

        {/* E-STOP */}
        <button
          onClick={() => sendCommand({ type: 'emergency_stop' }, 'E-STOP')}
          disabled={loading !== null}
          className="w-full flex items-center justify-center gap-1.5 px-3 py-2 text-sm bg-red-600/30 text-red-300 border border-red-500 rounded-lg hover:bg-red-600/50 font-bold mb-2 disabled:opacity-50"
        >
          <AlertTriangle className="w-4 h-4" />E-STOP
        </button>

        {/* Print controls */}
        {(isPrinting || isPaused) && (
          <div className="flex gap-2 mb-2">
            {isPaused && (
              <button onClick={() => sendCommand({ type: 'resume' }, 'resume')} disabled={loading !== null}
                className="flex-1 flex items-center justify-center gap-1 px-2 py-1.5 text-xs bg-green-500/20 text-green-400 border border-green-500/50 rounded hover:bg-green-500/30 disabled:opacity-50">
                <Play className="w-3 h-3" />{loading === 'resume' ? '...' : 'Resume'}
              </button>
            )}
            {isPrinting && (
              <button onClick={() => sendCommand({ type: 'pause' }, 'pause')} disabled={loading !== null}
                className="flex-1 flex items-center justify-center gap-1 px-2 py-1.5 text-xs bg-yellow-500/20 text-yellow-400 border border-yellow-500/50 rounded hover:bg-yellow-500/30 disabled:opacity-50">
                <Pause className="w-3 h-3" />{loading === 'pause' ? '...' : 'Pause'}
              </button>
            )}
            <button
              onClick={() => sendCommand({ type: 'cancel' }, 'cancel')}
              disabled={loading !== null || isCancelling}
              title={isCancelling ? 'Cancel command already sent — waiting for printer' : 'Cancel print'}
              className="flex-1 flex items-center justify-center gap-1 px-2 py-1.5 text-xs bg-red-500/20 text-red-400 border border-red-500/50 rounded hover:bg-red-500/30 disabled:opacity-50">
              <Square className="w-3 h-3" />
              {isCancelling ? 'Cancelling…' : loading === 'cancel' ? '…' : 'Cancel'}
            </button>
          </div>
        )}

        {/* Quick actions */}
        <div className="grid grid-cols-2 gap-1.5">
          {[
            { label: '🏠 Home All', cmd: { type: 'home' as const } },
            { label: 'Home X', cmd: { type: 'home-x' as any } },
            { label: 'Home Y', cmd: { type: 'home-y' as any } },
            { label: 'Home Z', cmd: { type: 'home-z' as any } },
          ].map(({ label, cmd }) => (
            <button key={label} onClick={() => sendCommand(cmd, label)} disabled={loading !== null || isPrinting}
              className="px-2 py-1.5 text-[10px] bg-gray-800 text-gray-300 border border-gray-600 rounded hover:bg-gray-700 disabled:opacity-50">
              {label}
            </button>
          ))}
        </div>

        {success && <div className="mt-2 text-[10px] text-green-400 bg-green-500/10 border border-green-500/30 rounded p-1.5">✓ {success}</div>}
        {error && <div className="mt-2 text-[10px] text-red-400 bg-red-500/10 border border-red-500/30 rounded p-1.5">{error}</div>}
      </div>
    </div>
  )
}
