import React, { useState, useEffect, useCallback, useRef } from 'react'
import { createPortal } from 'react-dom'
import { Info, XCircle, Printer as PrinterIcon } from 'lucide-react'
import type { DiagnosticTestResult } from './ai-types'

// ── Tab ──────────────────────────────────────────────────────
export function Tab({ active, onClick, icon, label, badge }: {
  active: boolean; onClick: () => void; icon: React.ReactNode; label: string; badge?: number | string
}) {
  return (
    <button onClick={onClick}
      className={`relative flex items-center gap-2 px-4 py-2.5 rounded-xl text-sm font-medium transition-all border ${active ? 'bg-gray-800/60 text-white border-gray-700/50 shadow-sm' : 'bg-gray-900/20 text-gray-400 border-gray-800/30 hover:text-gray-300 hover:bg-gray-800/40'}`}>
      {icon}{label}
      {badge != null && <span className="ml-0.5 bg-cyan-500 text-black text-[10px] font-bold rounded-full px-1.5 min-w-[18px] text-center">{badge}</span>}
    </button>
  )
}

// ── PrinterItem ───────────────────────────────────────────────
export function PrinterItem({ label, subtitle, selected, onClick }: {
  label: string; subtitle: string; selected: boolean; onClick: () => void
}) {
  return (
    <button onClick={onClick}
      className={`w-full px-2 py-1.5 text-left rounded-lg transition-all flex items-center gap-1.5 ${selected ? 'bg-gray-800/60 border-l-2 border-cyan-500' : 'hover:bg-gray-800/40'}`}>
      <PrinterIcon className="w-3 h-3 text-gray-500 flex-shrink-0" />
      <div className="flex-1 min-w-0">
        <div className="text-xs font-medium text-white truncate">{label}</div>
        <div className="text-[10px] text-gray-500 capitalize truncate">{subtitle}</div>
      </div>
    </button>
  )
}

// ── Section ───────────────────────────────────────────────────
export function Section({ title, icon, children, action }: {
  title: string; icon?: React.ReactNode; children: React.ReactNode; action?: React.ReactNode
}) {
  return (
    <div className="rounded-xl border border-gray-700 bg-gray-900/40 overflow-hidden">
      <div className="flex items-center justify-between px-4 py-2.5 border-b border-gray-700 bg-gray-900/30">
        <div className="flex items-center gap-2 text-sm font-semibold text-gray-200">{icon}{title}</div>
        {action}
      </div>
      <div className="p-4">{children}</div>
    </div>
  )
}

// ── EmptyMessage ─────────────────────────────────────────────
export function EmptyMessage({ children }: { children: React.ReactNode }) {
  return <p className="text-xs text-gray-500 text-center py-4">{children}</p>
}

// ── Tooltip ───────────────────────────────────────────────────
export function Tooltip({ text }: { text: string }) {
  return (
    <div className="group relative inline-flex cursor-default select-none">
      <Info className="w-3.5 h-3.5 text-gray-500 hover:text-gray-300 transition-colors" />
      <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 px-3 py-2 bg-gray-900 border border-gray-600 rounded-lg text-xs text-gray-200 max-w-xs w-max opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all pointer-events-none shadow-xl z-50 leading-relaxed">
        {text}
      </div>
    </div>
  )
}

// ── ToggleRow ─────────────────────────────────────────────────
export function ToggleRow({ label, desc, tooltip, value, onChange }: {
  label: string; desc: string; tooltip?: string; value: boolean; onChange: (v: boolean) => void
}) {
  const id = `ai-toggle-${label.toLowerCase().replace(/\s+/g, '-')}`
  return (
    <div className="flex items-center justify-between cursor-pointer py-2 first:pt-0 last:pb-0" onClick={() => onChange(!value)}>
      <div className="flex items-center gap-2">
        <div>
          <div className="text-sm text-gray-200">{label}</div>
          <div className="text-xs text-gray-400 mt-0.5">{desc}</div>
        </div>
        {tooltip && <Tooltip text={tooltip} />}
      </div>
      <input
        type="checkbox"
        id={id}
        name={id}
        checked={value}
        onChange={e => { e.stopPropagation(); onChange(e.target.checked) }}
        onClick={e => e.stopPropagation()}
        className="sr-only"
      />
      <div
        role="switch"
        aria-checked={value}
        className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors flex-shrink-0 flex-shrink-0 ${value ? 'bg-cyan-500' : 'bg-gray-700'}`}
      >
        <span className={`inline-block h-4 w-4 rounded-full bg-white shadow transition-transform ${value ? 'translate-x-6' : 'translate-x-1'}`} />
      </div>
    </div>
  )
}

// ── Slider ────────────────────────────────────────────────────
export function Slider({ label, value, onChange, min = 50, max = 100, step = 5, unit = '%', desc, tooltip }: {
  label: string; value: number; onChange: (v: number) => void
  min?: number; max?: number; step?: number; unit?: string; desc?: string; tooltip?: string
}) {
  const pct = ((value - min) / (max - min)) * 100
  return (
    <div className="space-y-1">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-1.5">
          <span className="text-sm text-gray-200">{label}</span>
          {tooltip && <Tooltip text={tooltip} />}
        </div>
        <span className="text-sm font-mono font-bold text-cyan-400">{value}{unit}</span>
      </div>
      {desc && <p className="text-[10px] text-gray-500">{desc}</p>}
      <input type="range" id={`ai-slider-${label.toLowerCase().replace(/\s+/g, '-')}`} name={`ai-slider-${label.toLowerCase().replace(/\s+/g, '-')}`} min={min} max={max} step={step} value={value}
        onChange={e => onChange(Number(e.target.value))}
        className="w-full h-2 rounded-lg appearance-none cursor-pointer"
        style={{ background: `linear-gradient(to right, #22d3ee 0%, #22d3ee ${pct}%, #1f2937 ${pct}%, #1f2937 100%)` }} />
      <div className="flex justify-between text-[10px] text-gray-500"><span>{min}{unit}</span><span>{max}{unit}</span></div>
    </div>
  )
}

// ── WarningBadge ─────────────────────────────────────────────
export function WarningBadge({ icon, label, colorClass, title, details }: {
  icon: React.ReactNode
  label: string
  colorClass: string
  title: string
  details: { label: string; value: string }[]
}) {
  const [open, setOpen] = useState(false)
  const [pos, setPos] = useState({ top: 0, left: 0 })
  const btnRef = useRef<HTMLButtonElement>(null)
  const popupRef = useRef<HTMLDivElement>(null)
  const [openDir, setOpenDir] = useState<'below' | 'above'>('below')

  const updatePos = useCallback(() => {
    if (!btnRef.current) return
    const r = btnRef.current.getBoundingClientRect()
    setOpenDir('below')
    setPos({
      top: r.bottom + 6,
      left: Math.min(Math.max(r.left, 8), window.innerWidth - 296),
    })
  }, [])

  const toggle = () => {
    if (!open) updatePos()
    setOpen(o => !o)
  }

  useEffect(() => {
    if (!open) return
    const onDown = (e: MouseEvent) => {
      if (
        btnRef.current && !btnRef.current.contains(e.target as Node) &&
        popupRef.current && !popupRef.current.contains(e.target as Node)
      ) setOpen(false)
    }
    const onScroll = () => { updatePos() }
    document.addEventListener('mousedown', onDown)
    window.addEventListener('scroll', onScroll, true)
    return () => {
      document.removeEventListener('mousedown', onDown)
      window.removeEventListener('scroll', onScroll, true)
    }
  }, [open, updatePos])

  const popup = open ? createPortal(
    <div
      ref={popupRef}
      style={{ position: 'fixed', top: pos.top, left: pos.left, transform: openDir === 'above' ? 'translateY(-100%)' : 'none', zIndex: 9999, width: 288 }}
      className="rounded-xl border border-gray-600 bg-gray-950 shadow-2xl overflow-hidden"
    >
      <div className="flex items-center justify-between px-3 py-2 border-b border-gray-700 bg-gray-900">
        <div className="flex items-center gap-1.5 text-sm font-semibold text-gray-100">{icon}{title}</div>
        <button onClick={() => setOpen(false)} className="text-gray-500 hover:text-gray-300 transition-colors">
          <XCircle className="w-4 h-4" />
        </button>
      </div>
      <div className="px-3 py-2.5 space-y-2.5">
        {details.map((d, i) => (
          <div key={i}>
            <div className="text-[10px] font-semibold text-gray-500 uppercase tracking-wider mb-0.5">{d.label}</div>
            <div className="text-xs text-gray-200 leading-relaxed">{d.value}</div>
          </div>
        ))}
      </div>
    </div>,
    document.body
  ) : null

  return (
    <>
      <button
        ref={btnRef}
        onClick={toggle}
        className={`text-[11px] flex items-center gap-1 px-2 py-0.5 rounded-full border cursor-pointer hover:brightness-125 active:scale-95 transition-all ${colorClass}`}
      >
        {icon}{label}
        <Info className="w-2.5 h-2.5 opacity-60 ml-0.5" />
      </button>
      {popup}
    </>
  )
}

// ── AnalysisMetricCard ────────────────────────────────────────
export function AnalysisMetricCard({ label, value, unit, sub, color, icon }: {
  label: string; value: string; unit?: string; sub?: string; color: string; icon?: React.ReactNode
}) {
  return (
    <div className="rounded-lg bg-gray-800/50 border border-gray-700/50 px-3 py-2 flex flex-col justify-between min-h-[3.25rem]">
      <div className="flex items-center gap-1 text-[10px] text-gray-500 mb-1">
        {icon && <span className="text-gray-600">{icon}</span>}
        {label}
      </div>
      <div className="flex items-baseline gap-0.5">
        <span className={`text-lg font-bold leading-none ${color}`}>{value}</span>
        {unit && <span className={`text-xs ${color} opacity-70`}>{unit}</span>}
        {sub && <span className="ml-1 text-[10px] text-gray-500 font-medium">{sub}</span>}
      </div>
    </div>
  )
}

// ── StatusPill ────────────────────────────────────────────────
export function StatusPill({ status, score, source }: {
  status: DiagnosticTestResult['status']; score: number; source?: DiagnosticTestResult['source']
}) {
  const sourceBadge =
    source === 'live_gcode'
      ? <span className="ml-1 text-[9px] px-1 py-0.5 rounded bg-green-500/20 text-green-400 border border-green-500/30 font-bold">⚡ GCODE</span>
      : source === 'live_telemetry' || source === 'live'
      ? <span className="ml-1 text-[9px] px-1 py-0.5 rounded bg-cyan-500/20 text-cyan-400 border border-cyan-500/30">● LIVE</span>
      : source === 'estimated'
      ? <span className="ml-1 text-[9px] px-1 py-0.5 rounded bg-gray-500/20 text-gray-500 border border-gray-600">~ EST</span>
      : null
  if (status === 'running') return (
    <span className="text-[10px] px-2 py-0.5 rounded-full bg-cyan-500/20 text-cyan-400 border border-cyan-500/30 animate-pulse">Running…</span>
  )
  if (status === 'pass') return (
    <span className="inline-flex items-center gap-1 text-[10px] px-2 py-0.5 rounded-full bg-green-500/20 text-green-400 border border-green-500/30">✓ Pass {score}/100{sourceBadge}</span>
  )
  if (status === 'warning') return (
    <span className="inline-flex items-center gap-1 text-[10px] px-2 py-0.5 rounded-full bg-yellow-500/20 text-yellow-400 border border-yellow-500/30">⚠ Warning {score}/100{sourceBadge}</span>
  )
  return (
    <span className="inline-flex items-center gap-1 text-[10px] px-2 py-0.5 rounded-full bg-red-500/20 text-red-400 border border-red-500/30">✗ Fail {score}/100{sourceBadge}</span>
  )
}
