import { useState } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { 
  AlertCircle, RefreshCw, Printer, Activity, CheckCircle, AlertTriangle, 
  X, WifiOff, Layers
} from 'lucide-react'
import { AIStatusIndicator } from '@features/ai-panel'
import { useNavigate } from 'react-router-dom'
import { 
  usePrinterStore, 
  selectPrintersArray,
  selectIsLoading,
  selectPrintersByStatus,
} from '@core/state/printerStore'
import { usePrintersFetch } from '@core/hooks/usePrintersFetch'
import type { Printer as PrinterType } from '@core/types'

type ActivePanel = 'printers' | 'printing' | 'idle' | 'errors' | null

// ─── Status config ─────────────────────────────────────────────
const STATUS_CONFIG: Record<string, { label: string; color: string; dot: string }> = {
  idle:         { label: 'Idle',         color: 'text-green-400',  dot: 'bg-green-400' },
  printing:     { label: 'Printing',     color: 'text-blue-400',   dot: 'bg-blue-400' },
  paused:       { label: 'Paused',       color: 'text-yellow-400', dot: 'bg-yellow-400' },
  error:        { label: 'Error',        color: 'text-red-400',    dot: 'bg-red-400' },
  disconnected: { label: 'Offline',      color: 'text-gray-500',   dot: 'bg-gray-500' },
  maintenance:  { label: 'Maintenance',  color: 'text-purple-400', dot: 'bg-purple-400' },
  ai_action:    { label: 'AI Action',    color: 'text-cyan-400',   dot: 'bg-cyan-400' },
}

// ─── Single printer row ─────────────────────────────────────────
function PrinterRow({ printer, onClick }: { printer: PrinterType; onClick?: () => void }) {
  const cfg = STATUS_CONFIG[printer.status] ?? STATUS_CONFIG.disconnected
  const temps = printer.liveState?.temperatures
  const progress = printer.liveState?.progress

  return (
    <div
      onClick={onClick}
      className="bg-gray-800/60 border border-gray-700 rounded-lg p-3 flex flex-col gap-2 cursor-pointer hover:border-cyan-500/50 hover:bg-gray-800 transition-all"
    >
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2 min-w-0">
          <Printer className="w-3.5 h-3.5 text-cyan-400 flex-shrink-0" />
          <span className="text-sm font-semibold text-gray-100 truncate">{printer.name}</span>
          <span className="text-[10px] text-gray-500 capitalize">{printer.adapterType}</span>
        </div>
        <div className="flex items-center gap-1.5 flex-shrink-0">
          <div className={`w-1.5 h-1.5 rounded-full ${cfg.dot} animate-pulse`} />
          <span className={`text-[11px] font-medium ${cfg.color}`}>{cfg.label}</span>
        </div>
      </div>

      {/* Temps */}
      {temps && (
        <div className="flex gap-3 text-[11px] text-gray-400">
          <span className="flex items-center gap-1">
            🔥 <span className="text-orange-300">{temps.hotend?.current?.toFixed(1) ?? '—'}°</span>
            {temps.hotend?.target > 0 && <span className="text-gray-500">/ {temps.hotend.target}°</span>}
          </span>
          <span className="flex items-center gap-1">
            🟦 <span className="text-blue-300">{temps.bed?.current?.toFixed(1) ?? '—'}°</span>
            {temps.bed?.target > 0 && <span className="text-gray-500">/ {temps.bed.target}°</span>}
          </span>
        </div>
      )}

      {/* Progress bar if printing */}
      {printer.status === 'printing' && progress && (
        <div>
          <div className="flex justify-between text-[10px] text-gray-500 mb-1">
            <span className="flex items-center gap-1">
              <Layers className="w-3 h-3" />
              {progress.filename ?? 'Unknown file'}
            </span>
            <span>{progress.percentage?.toFixed(1) ?? 0}%</span>
          </div>
          <div className="h-1 bg-gray-700 rounded-full overflow-hidden">
            <div
              className="h-full bg-gradient-to-r from-cyan-500 to-blue-500 rounded-full transition-all duration-500"
              style={{ width: `${progress.percentage ?? 0}%` }}
            />
          </div>
        </div>
      )}

      {/* Error message */}
      {printer.status === 'error' && (
        <div className="text-[11px] text-red-400 bg-red-500/10 border border-red-500/20 rounded px-2 py-1">
          ⚠ Printer error
        </div>
      )}
    </div>
  )
}

// ─── Modal/Drawer ───────────────────────────────────────────────
interface PanelModalProps {
  panel: ActivePanel
  printers: PrinterType[]
  onClose: () => void
}

const PANEL_META = {
  printers: { title: 'All Printers',     icon: Printer,       color: 'text-cyan-400',  border: 'border-cyan-500/40' },
  printing: { title: 'Currently Printing', icon: Activity,    color: 'text-blue-400',  border: 'border-blue-500/40' },
  idle:     { title: 'Idle Printers',    icon: CheckCircle,   color: 'text-green-400', border: 'border-green-500/40' },
  errors:   { title: 'Printers w/ Errors', icon: AlertTriangle, color: 'text-red-400', border: 'border-red-500/40' },
}

function PanelModal({ panel, printers, onClose }: PanelModalProps) {
  const navigate = useNavigate()
  if (!panel) return null
  const meta = PANEL_META[panel]
  const Icon = meta.icon

  return (
    <AnimatePresence>
      {/* Overlay */}
      <motion.div
        key="overlay"
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        style={{ position: 'fixed', inset: 0, zIndex: 9998 }}
        className="bg-black/60 backdrop-blur-sm"
        onClick={onClose}
      />
      {/* Modal centered */}
      <div
        style={{
          position: 'fixed',
          inset: 0,
          zIndex: 9999,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          pointerEvents: 'none',
        }}
      >
      <motion.div
        key="panel"
        initial={{ opacity: 0, y: 24, scale: 0.97 }}
        animate={{ opacity: 1, y: 0, scale: 1 }}
        exit={{ opacity: 0, y: 24, scale: 0.97 }}
        transition={{ duration: 0.2, ease: 'easeOut' }}
        style={{ pointerEvents: 'auto' }}
        className={`w-[560px] max-w-[95vw] max-h-[75vh]
          bg-gray-900 border ${meta.border} rounded-xl shadow-2xl shadow-black/60
          flex flex-col overflow-hidden`}
      >
        {/* Header */}
        <div className="flex items-center justify-between px-4 py-3 border-b border-gray-700 flex-shrink-0">
          <div className={`flex items-center gap-2 ${meta.color}`}>
            <Icon className="w-4 h-4" />
            <span className="text-sm font-bold tracking-wide uppercase">{meta.title}</span>
            <span className="text-xs bg-gray-800 text-gray-300 rounded-full px-2 py-0.5 font-mono">
              {printers.length}
            </span>
          </div>
          <button
            onClick={onClose}
            className="text-gray-500 hover:text-gray-200 transition-colors p-1 rounded hover:bg-gray-800"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        {/* Body */}
        <div className="flex-1 overflow-y-auto p-4">
          {printers.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-12 text-gray-500">
              <WifiOff className="w-8 h-8 mb-2 opacity-40" />
              <p className="text-sm">No printers in this category</p>
            </div>
          ) : (
            <div className="flex flex-col gap-2">
              {printers.map((p) => (
                <PrinterRow
                  key={p.id}
                  printer={p}
                  onClick={() => { onClose(); navigate(`/printers/${p.id}`) }}
                />
              ))}
            </div>
          )}
        </div>
      </motion.div>
      </div>
    </AnimatePresence>
  )
}

// ═══════════════════════════════════════════════════════════════
// MAIN PAGE
// ═══════════════════════════════════════════════════════════════

export default function DashboardPage() {
  const printersArray = usePrinterStore(selectPrintersArray)
  const isLoading = usePrinterStore(selectIsLoading)
  const { error, refresh } = usePrintersFetch()

  const [activePanel, setActivePanel] = useState<ActivePanel>(null)

  const printingPrinters = usePrinterStore((state) => selectPrintersByStatus('printing')(state))
  const idlePrinters     = usePrinterStore((state) => selectPrintersByStatus('idle')(state))
  const errorPrinters    = usePrinterStore((state) => selectPrintersByStatus('error')(state))

  const stats = {
    total:    printersArray.length,
    printing: printingPrinters.length,
    idle:     idlePrinters.length,
    errors:   errorPrinters.length,
  }

  const getPanelPrinters = (): PrinterType[] => {
    switch (activePanel) {
      case 'printers': return printersArray
      case 'printing': return printingPrinters
      case 'idle':     return idlePrinters
      case 'errors':   return errorPrinters
      default:         return []
    }
  }

  const togglePanel = (panel: ActivePanel) => {
    setActivePanel(activePanel === panel ? null : panel)
  }

  if (error && printersArray.length === 0) {
    return (
      <div className="flex items-center justify-center h-full">
        <div className="text-center max-w-md">
          <AlertCircle className="w-10 h-10 text-red-400 mx-auto mb-2" />
          <h2 className="text-base font-bold text-gray-200 mb-1">Failed to Load Printers</h2>
          <p className="text-xs text-gray-400 mb-3">{error.message}</p>
          <button
            onClick={refresh}
            disabled={isLoading}
            className="inline-flex items-center gap-1.5 px-3 py-1.5 text-xs bg-cyan-500/20 text-cyan-400 border border-cyan-500/50 rounded hover:bg-cyan-500/30 transition-colors disabled:opacity-50"
          >
            <RefreshCw className={`w-3 h-3 ${isLoading ? 'animate-spin' : ''}`} />
            Retry
          </button>
        </div>
      </div>
    )
  }

  return (
    <div className="flex flex-col h-full gap-2 overflow-hidden relative">
      {/* AI Status */}
      <div className="flex justify-end flex-shrink-0">
        <AIStatusIndicator />
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-4 gap-2 flex-shrink-0">
        <StatCard
          icon={<Printer className="w-3.5 h-3.5" />}
          label="Total Printers"
          value={stats.total}
          subtitle={`${stats.total} connected`}
          color="primary"
          isLoading={isLoading}
          onClick={() => togglePanel('printers')}
          isActive={activePanel === 'printers'}
        />
        <StatCard
          icon={<Activity className="w-3.5 h-3.5" />}
          label="Printing"
          value={stats.printing}
          color="info"
          isLoading={isLoading}
          onClick={() => togglePanel('printing')}
          isActive={activePanel === 'printing'}
        />
        <StatCard
          icon={<CheckCircle className="w-3.5 h-3.5" />}
          label="Idle"
          value={stats.idle}
          color="success"
          isLoading={isLoading}
          onClick={() => togglePanel('idle')}
          isActive={activePanel === 'idle'}
        />
        <StatCard
          icon={<AlertTriangle className="w-3.5 h-3.5" />}
          label="Errors"
          value={stats.errors}
          color="error"
          isLoading={isLoading}
          onClick={() => togglePanel('errors')}
          isActive={activePanel === 'errors'}
        />
      </div>

      {/* Error banner */}
      {error && printersArray.length > 0 && (
        <div className="flex-shrink-0 bg-yellow-500/10 border border-yellow-500/30 rounded px-3 py-2 flex items-center gap-2 text-xs">
          <AlertCircle className="w-3.5 h-3.5 text-yellow-400 flex-shrink-0" />
          <span className="text-yellow-400 flex-1">Warning: Failed to refresh printer data. Showing cached data.</span>
          <button onClick={refresh} className="text-yellow-400 hover:text-yellow-300 font-medium">
            Retry
          </button>
        </div>
      )}

      {/* Modāls logs */}
      {activePanel && (
        <PanelModal
          panel={activePanel}
          printers={getPanelPrinters()}
          onClose={() => setActivePanel(null)}
        />
      )}
    </div>
  )
}

// ═══════════════════════════════════════════════════════════════
// STAT CARD
// ═══════════════════════════════════════════════════════════════

interface StatCardProps {
  icon: React.ReactNode
  label: string
  value: number | string
  subtitle?: string
  color: 'primary' | 'success' | 'info' | 'error' | 'warning' | 'secondary'
  isLoading?: boolean
  onClick: () => void
  isActive: boolean
}

function StatCard({ icon, label, value, subtitle, color, isLoading, onClick, isActive }: StatCardProps) {
  const colorClasses = {
    primary:   'text-cyan-400',
    success:   'text-green-400',
    info:      'text-blue-400',
    error:     'text-red-400',
    warning:   'text-yellow-400',
    secondary: 'text-purple-400',
  }

  const glowColors = {
    primary:   'rgba(0, 245, 255, 0.15)',
    success:   'rgba(34, 197, 94, 0.15)',
    info:      'rgba(59, 130, 246, 0.15)',
    error:     'rgba(239, 68, 68, 0.15)',
    warning:   'rgba(234, 179, 8, 0.15)',
    secondary: 'rgba(139, 92, 246, 0.15)',
  }

  return (
    <motion.button
      onClick={onClick}
      whileHover={{ boxShadow: `0 0 16px ${glowColors[color]}` }}
      whileTap={{ scale: 0.97 }}
      transition={{ duration: 0.15 }}
      className={`bg-gray-900/50 border rounded-lg p-2.5 text-left transition-all hover:bg-gray-800/50 cursor-pointer ${
        isActive
          ? `ring-1 ring-cyan-500/50 border-cyan-500/50 bg-gray-800/60`
          : 'border-gray-700'
      }`}
    >
      <div className={`flex items-center gap-1.5 mb-1 ${colorClasses[color]}`}>
        {icon}
        <span className="text-[10px] text-gray-400 uppercase tracking-wide">{label}</span>
      </div>
      {isLoading ? (
        <div className="w-8 h-5 bg-gray-800 animate-pulse rounded" />
      ) : (
        <div className="text-xl font-display font-bold text-gray-100">{value}</div>
      )}
      {subtitle && (
        <p className="text-[10px] text-gray-500 mt-0.5">{subtitle}</p>
      )}
      <p className={`text-[9px] mt-1 ${colorClasses[color]} opacity-60`}>Click to view →</p>
    </motion.button>
  )
}
