// ═══════════════════════════════════════════════════════════════
// PRESTIGE DASHBOARD - UI STORE (Zustand)
// ═══════════════════════════════════════════════════════════════

import { create } from 'zustand'
import { devtools, persist } from 'zustand/middleware'
import type { ThemeMode, LanguageCode, Toast } from '@core/types'

// ═══════════════════════════════════════════════════════════════
// TYPES
// ═══════════════════════════════════════════════════════════════

type ModalType = 
  | 'printer-add'
  | 'printer-edit'
  | 'printer-delete'
  | 'settings'
  | 'ai-recommendation'
  | 'emergency-stop'
  | 'confirm'
  | null

interface ModalState {
  type: ModalType
  data?: unknown
}

interface UIState {
  // Sidebar
  sidebarOpen: boolean
  sidebarCollapsed: boolean
  
  // Theme
  theme: ThemeMode
  
  // Language
  language: LanguageCode
  
  // Modals
  modal: ModalState
  
  // Toasts
  toasts: Toast[]
  
  // View preferences
  printerViewMode: 'grid' | 'list'
  dashboardLayout: 'default' | 'compact' | 'expanded'
  
  // Mobile
  isMobile: boolean
  mobileMenuOpen: boolean
  
  // Loading overlay
  globalLoading: boolean
  globalLoadingMessage: string | null

  // Virtual Assistant
  assistantOpen: boolean
}

interface UIActions {
  // Sidebar
  toggleSidebar: () => void
  setSidebarOpen: (open: boolean) => void
  toggleSidebarCollapsed: () => void
  setSidebarCollapsed: (collapsed: boolean) => void
  
  // Theme
  setTheme: (theme: ThemeMode) => void
  
  // Language
  setLanguage: (language: LanguageCode) => void
  
  // Modals
  openModal: (type: ModalType, data?: unknown) => void
  closeModal: () => void
  
  // Toasts
  addToast: (toast: Omit<Toast, 'id'>) => void
  removeToast: (id: string) => void
  clearToasts: () => void
  
  // Notifications (alias for toasts for backward compatibility)
  addNotification: (toast: Omit<Toast, 'id'>) => void
  removeNotification: (id: string) => void
  
  // View preferences
  setPrinterViewMode: (mode: 'grid' | 'list') => void
  setDashboardLayout: (layout: 'default' | 'compact' | 'expanded') => void
  
  // Mobile
  setIsMobile: (isMobile: boolean) => void
  toggleMobileMenu: () => void
  setMobileMenuOpen: (open: boolean) => void
  
  // Loading overlay
  setGlobalLoading: (loading: boolean, message?: string) => void

  // Virtual Assistant
  openAssistant: () => void
  closeAssistant: () => void
}

type UIStore = UIState & UIActions

// ═══════════════════════════════════════════════════════════════
// INITIAL STATE
// ═══════════════════════════════════════════════════════════════

const initialState: UIState = {
  sidebarOpen: true,
  sidebarCollapsed: false,
  theme: 'dark',
  language: 'lv',
  modal: { type: null },
  toasts: [],
  printerViewMode: 'grid',
  dashboardLayout: 'default',
  isMobile: false,
  mobileMenuOpen: false,
  globalLoading: false,
  globalLoadingMessage: null,
  assistantOpen: false,
}

// ═══════════════════════════════════════════════════════════════
// HELPERS
// ═══════════════════════════════════════════════════════════════

const generateToastId = () => `toast-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`

// ═══════════════════════════════════════════════════════════════
// STORE
// ═══════════════════════════════════════════════════════════════

export const useUIStore = create<UIStore>()(
  devtools(
    persist(
      (set, get) => ({
        ...initialState,

        // ─────────────────────────────────────────────────────────
        // Sidebar
        // ─────────────────────────────────────────────────────────
        
        toggleSidebar: () => {
          set((state) => ({ sidebarOpen: !state.sidebarOpen }))
        },

        setSidebarOpen: (open) => {
          set({ sidebarOpen: open })
        },

        toggleSidebarCollapsed: () => {
          set((state) => ({ sidebarCollapsed: !state.sidebarCollapsed }))
        },

        setSidebarCollapsed: (collapsed) => {
          set({ sidebarCollapsed: collapsed })
        },

        // ─────────────────────────────────────────────────────────
        // Theme
        // ─────────────────────────────────────────────────────────
        
        setTheme: (theme) => {
          set({ theme })
          // Apply theme to document
          if (theme === 'dark') {
            document.documentElement.classList.add('dark')
          } else {
            document.documentElement.classList.remove('dark')
          }
        },

        // ─────────────────────────────────────────────────────────
        // Language
        // ─────────────────────────────────────────────────────────
        
        setLanguage: (language) => {
          set({ language })
        },

        // ─────────────────────────────────────────────────────────
        // Modals
        // ─────────────────────────────────────────────────────────
        
        openModal: (type, data) => {
          set({ modal: { type, data } })
        },

        closeModal: () => {
          set({ modal: { type: null } })
        },

        // ─────────────────────────────────────────────────────────
        // Toasts
        // ─────────────────────────────────────────────────────────
        
        addToast: (toast) => {
          const id = generateToastId()
          const newToast: Toast = {
            ...toast,
            id,
            duration: toast.duration ?? 5000,
          }
          
          set((state) => ({
            toasts: [...state.toasts, newToast],
          }))
          
          // Auto-remove after duration
          if (newToast.duration && newToast.duration > 0) {
            setTimeout(() => {
              get().removeToast(id)
            }, newToast.duration)
          }
        },

        removeToast: (id) => {
          set((state) => ({
            toasts: state.toasts.filter((t) => t.id !== id),
          }))
        },

        clearToasts: () => {
          set({ toasts: [] })
        },

        // ─────────────────────────────────────────────────────────
        // Notifications (aliases)
        // ─────────────────────────────────────────────────────────
        
        addNotification: (toast) => {
          get().addToast(toast)
        },

        removeNotification: (id) => {
          get().removeToast(id)
        },

        // ─────────────────────────────────────────────────────────
        // View preferences
        // ─────────────────────────────────────────────────────────
        
        setPrinterViewMode: (mode) => {
          set({ printerViewMode: mode })
        },

        setDashboardLayout: (layout) => {
          set({ dashboardLayout: layout })
        },

        // ─────────────────────────────────────────────────────────
        // Mobile
        // ─────────────────────────────────────────────────────────
        
        setIsMobile: (isMobile) => {
          set({ isMobile })
          if (isMobile) {
            set({ sidebarCollapsed: true })
          }
        },

        toggleMobileMenu: () => {
          set((state) => ({ mobileMenuOpen: !state.mobileMenuOpen }))
        },

        setMobileMenuOpen: (open) => {
          set({ mobileMenuOpen: open })
        },

        // ─────────────────────────────────────────────────────────
        // Loading overlay
        // ─────────────────────────────────────────────────────────
        
        setGlobalLoading: (loading, message) => {
          set({ 
            globalLoading: loading, 
            globalLoadingMessage: message ?? null 
          })
        },

        openAssistant: () => set({ assistantOpen: true }),
        closeAssistant: () => set({ assistantOpen: false }),
      }),
      {
        name: 'ui-store',
        partialize: (state) => ({
          theme: state.theme,
          language: state.language,
          sidebarCollapsed: state.sidebarCollapsed,
          printerViewMode: state.printerViewMode,
          dashboardLayout: state.dashboardLayout,
        }),
      }
    ),
    { name: 'ui-store' }
  )
)

// ═══════════════════════════════════════════════════════════════
// SELECTORS
// ═══════════════════════════════════════════════════════════════

export const selectSidebarOpen = (state: UIStore) => state.sidebarOpen
export const selectSidebarCollapsed = (state: UIStore) => state.sidebarCollapsed
export const selectTheme = (state: UIStore) => state.theme
export const selectLanguage = (state: UIStore) => state.language
export const selectModal = (state: UIStore) => state.modal
export const selectToasts = (state: UIStore) => state.toasts
export const selectPrinterViewMode = (state: UIStore) => state.printerViewMode
export const selectDashboardLayout = (state: UIStore) => state.dashboardLayout
export const selectIsMobile = (state: UIStore) => state.isMobile
export const selectGlobalLoading = (state: UIStore) => state.globalLoading
export const selectAssistantOpen = (state: UIStore) => state.assistantOpen

// Computed
export const selectSidebarWidth = (state: UIStore) => 
  state.sidebarCollapsed ? 72 : 280

export default useUIStore
