// ═══════════════════════════════════════════════════════════════
// PRESTIGE DASHBOARD - ENHANCED PRINTER CARD COMPONENT
// FE-02: Full visual enhancement with metrics, AI status, animations
// ═══════════════════════════════════════════════════════════════

import React, { useMemo, useState, memo } from 'react'
import { Settings, Play, Pause, X, AlertTriangle } from 'lucide-react'
import type { Printer } from '../../types/printer'
import { parseConnectionHost } from '../../types/printer'
import type {
  PrinterCardProps,
  PrinterCardSize,
  PrinterCardLayout,
  QuickAction,
} from './PrinterCard.types'
import { StatusIndicator } from '../StatusIndicator'
import { QualityScore } from '../QualityScore'
import { PrinterCardMetrics } from './PrinterCardMetrics'
import { PrinterCardAI } from './PrinterCardAI'
import { 
  getStatusVisualConfig, 
  getCardContainerStyle, 
  getActionButtonStyle,
  HOVER_CLASSES 
} from './styles'

/**
 * Size configuration
 */
const SIZE_CONFIG: Record<PrinterCardSize, { padding: string; gap: string; text: string }> = {
  sm: {
    padding: 'p-3',
    gap: 'gap-2',
    text: 'text-sm',
  },
  md: {
    padding: 'p-4',
    gap: 'gap-3',
    text: 'text-base',
  },
  lg: {
    padding: 'p-5',
    gap: 'gap-4',
    text: 'text-lg',
  },
}

/**
 * Enhanced PrinterCard Component
 * 
 * New Features (FE-02):
 * - Temperature displays with icons and mini progress bars
 * - Enhanced progress bar with ETA and layer info
 * - Print job name display
 * - AI status indicator
 * - Status-specific border colors and glows
 * - Smooth animations for state transitions
 * - Quick action buttons with hover effects
 */
export const PrinterCard: React.FC<PrinterCardProps> = ({
  printer,
  size = 'md',
  layout = 'standard',
  actions,
  showQualityScore = true,
  showTemperatures = true,
  showProgress = true,
  showActions = true,
  className = '',
}) => {
  const [isHovered, setIsHovered] = useState(false)
  const [hoveredButton, setHoveredButton] = useState<string | null>(null)
  
  const sizeConfig = SIZE_CONFIG[size]
  const visualConfig = getStatusVisualConfig(printer.status)

  // Generate quick actions based on printer status
  const quickActions = useMemo<QuickAction[]>(() => {
    const baseActions: QuickAction[] = []

    // Settings button (always available)
    if (actions?.onSettings) {
      baseActions.push({
        id: 'settings',
        label: '',
        icon: <Settings className="w-4 h-4" />,
        onClick: () => actions.onSettings!(printer),
        variant: 'secondary',
      })
    }

    if (printer.status === 'printing' && actions?.onPause) {
      baseActions.push({
        id: 'pause',
        label: 'Pause',
        icon: <Pause className="w-4 h-4" />,
        onClick: () => actions.onPause!(printer),
        variant: 'secondary',
      })
    }

    if (printer.status === 'paused' && actions?.onResume) {
      baseActions.push({
        id: 'resume',
        label: 'Resume',
        icon: <Play className="w-4 h-4" />,
        onClick: () => actions.onResume!(printer),
        variant: 'primary',
      })
    }

    if ((printer.status === 'printing' || printer.status === 'paused') && actions?.onCancel) {
      baseActions.push({
        id: 'cancel',
        label: 'Cancel',
        icon: <X className="w-4 h-4" />,
        onClick: () => actions.onCancel!(printer),
        variant: 'danger',
      })
    }

    if (printer.status !== 'disconnected' && actions?.onEmergencyStop) {
      baseActions.push({
        id: 'estop',
        label: 'E-STOP',
        icon: <AlertTriangle className="w-4 h-4" />,
        onClick: () => actions.onEmergencyStop!(printer),
        variant: 'danger',
      })
    }

    return baseActions
  }, [printer, actions])

  // Card click handler
  const handleCardClick = () => {
    if (actions?.onView) {
      actions.onView(printer)
    }
  }

  // Check if printer has AI enabled
  const hasAI = printer.aiConfig?.enabled && (printer.aiConfig?.level ?? 0) > 0

  // Determine AI status
  const getAIStatus = () => {
    if (!hasAI) return 'disabled'
    if (printer.status === 'ai_action') return 'action-taken'
    return 'monitoring'
  }

  // Compact layout
  if (layout === 'compact') {
    return (
      <div
        className={`relative flex flex-col ${sizeConfig.gap} ${sizeConfig.padding} rounded-xl border-2 backdrop-blur-sm cursor-pointer ${HOVER_CLASSES.card} ${className}`}
        style={getCardContainerStyle(printer.status, isHovered)}
        onClick={handleCardClick}
        onMouseEnter={() => setIsHovered(true)}
        onMouseLeave={() => setIsHovered(false)}
      >
        {/* Header with status icon */}
        <div className="flex items-start justify-between gap-2">
          <div className="flex items-center gap-2 flex-1 min-w-0">
            <span className={`text-2xl ${visualConfig.iconColor}`}>
              {visualConfig.icon}
            </span>
            <div className="flex-1 min-w-0">
              <h3 className={`font-bold ${sizeConfig.text} text-white truncate`}>
                {printer.name}
              </h3>
              <p className="text-xs text-gray-400 truncate">{printer.adapterType}</p>
            </div>
          </div>
          <StatusIndicator status={printer.status} size="sm" mode="badge" />
        </div>

        {/* AI indicator (compact) */}
        {hasAI && (
          <PrinterCardAI
            aiEnabled={printer.aiConfig?.enabled}
            aiLevel={printer.aiConfig?.level}
            aiStatus={getAIStatus()}
            compact
          />
        )}

        {/* Progress (if printing) */}
        {showProgress && printer.liveState?.progress && (
          <PrinterCardMetrics
            progress={printer.liveState.progress}
            showTemperatures={false}
            showProgress={true}
          />
        )}
      </div>
    )
  }

  // Detailed layout
  if (layout === 'detailed') {
    return (
      <div
        className={`relative flex flex-col ${sizeConfig.gap} ${sizeConfig.padding} rounded-xl border-2 backdrop-blur-sm ${HOVER_CLASSES.card} ${className}`}
        style={getCardContainerStyle(printer.status, isHovered)}
        onMouseEnter={() => setIsHovered(true)}
        onMouseLeave={() => setIsHovered(false)}
      >
        {/* Header with large status icon */}
        <div className="flex items-start justify-between gap-3">
          <div className="flex items-center gap-3 flex-1 min-w-0">
            <div 
              className="w-12 h-12 rounded-xl flex items-center justify-center text-3xl"
              style={{ 
                backgroundColor: 'rgba(255, 255, 255, 0.05)',
                borderWidth: '2px',
                borderColor: visualConfig.borderColor,
              }}
            >
              {visualConfig.icon}
            </div>
            <div className="flex-1 min-w-0">
              <h3 className={`font-bold ${sizeConfig.text} text-white truncate`}>
                {printer.name}
              </h3>
              <p className="text-sm text-gray-400 truncate">{printer.adapterType}</p>
              {printer.connectionUrl && (
                <p className="text-xs text-gray-500">
                  {printer.adapterType} • {parseConnectionHost(printer.connectionUrl)}
                </p>
              )}
            </div>
          </div>
          <div className="flex flex-col items-end gap-2">
            <StatusIndicator status={printer.status} size="md" mode="badge" />
            {printer.lastSeenAt && (
              <span className="text-xs text-gray-500">
                {new Date(printer.lastSeenAt).toLocaleTimeString()}
              </span>
            )}
          </div>
        </div>

        {/* AI Status (full) */}
        {hasAI && (
          <PrinterCardAI
            aiEnabled={printer.aiConfig?.enabled}
            aiLevel={printer.aiConfig?.level}
            aiStatus={getAIStatus()}
            compact={false}
          />
        )}

        {/* Metrics (Temperatures + Progress) */}
        <PrinterCardMetrics
          temperatures={printer.liveState?.temperatures}
          progress={printer.liveState?.progress}
          showTemperatures={showTemperatures}
          showProgress={showProgress}
        />

        {/* Quality Score */}
        {showQualityScore && printer.qualityScore !== undefined && (
          <div className="flex items-center justify-between p-3 rounded-lg bg-gray-800/30 border border-gray-700/50">
            <span className="text-sm font-medium text-gray-300">Quality Score</span>
            <QualityScore score={printer.qualityScore} size="sm" mode="compact" />
          </div>
        )}

        {/* Quick Actions */}
        {showActions && quickActions.length > 0 && (
          <div className="flex items-center gap-2 pt-2 border-t border-gray-700/50">
            {quickActions.map((action) => (
              <button
                key={action.id}
                onClick={(e) => {
                  e.stopPropagation()
                  action.onClick()
                }}
                disabled={action.disabled}
                className={`flex-1 flex items-center justify-center gap-2 px-3 py-2 rounded-lg text-sm font-medium border transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed ${HOVER_CLASSES.button}`}
                style={getActionButtonStyle(
                  action.variant, 
                  hoveredButton === action.id
                )}
                onMouseEnter={() => setHoveredButton(action.id)}
                onMouseLeave={() => setHoveredButton(null)}
              >
                {action.icon}
                {action.label && <span>{action.label}</span>}
              </button>
            ))}
          </div>
        )}

        {/* Footer info */}
        <div className="flex items-center justify-between text-xs text-gray-500 pt-2 border-t border-gray-700/30">
          <span>ID: {printer.id.slice(0, 8)}</span>
          {printer.firmwareVersion && <span>FW: {printer.firmwareVersion}</span>}
        </div>
      </div>
    )
  }

  // Standard layout (default) - FE-02 COMPLIANT
  return (
    <div
      className={`relative flex flex-col ${sizeConfig.gap} ${sizeConfig.padding} rounded-xl border-2 backdrop-blur-sm cursor-pointer ${HOVER_CLASSES.card} ${className}`}
      style={getCardContainerStyle(printer.status, isHovered)}
      onClick={handleCardClick}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      {/* Header with PRINTER ICON BOX + Quick Actions */}
      <div className="flex items-start justify-between gap-2">
        <div className="flex items-center gap-2.5 flex-1 min-w-0">
          {/* Printer Icon Box - FE-02 spec */}
          <div 
            className="w-12 h-12 rounded-lg flex items-center justify-center text-2xl flex-shrink-0"
            style={{ 
              backgroundColor: 'rgba(255, 255, 255, 0.03)',
              borderWidth: '1px',
              borderColor: 'rgba(255, 255, 255, 0.1)',
            }}
          >
            🖨️
          </div>
          <div className="flex-1 min-w-0">
            <h3 className={`font-bold ${sizeConfig.text} text-white truncate`}>
              {printer.name}
            </h3>
            <p className="text-sm text-gray-400 truncate">{printer.adapterType}</p>
          </div>
        </div>
        
        {/* Quick Actions + Status Badge - FE-02 spec: always visible in top right */}
        <div className="flex items-center gap-2">
          <StatusIndicator status={printer.status} size="md" mode="badge" />
          {showActions && quickActions.length > 0 && (
            <div className="flex items-center gap-1">
              {quickActions.slice(0, 2).map((action) => (
                <button
                  key={action.id}
                  onClick={(e) => {
                    e.stopPropagation()
                    action.onClick()
                  }}
                  disabled={action.disabled}
                  className="p-2 rounded-lg text-sm font-medium border transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed"
                  style={getActionButtonStyle(
                    action.variant,
                    hoveredButton === action.id
                  )}
                  onMouseEnter={() => setHoveredButton(action.id)}
                  onMouseLeave={() => setHoveredButton(null)}
                  title={action.label || action.id}
                >
                  {action.icon}
                </button>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* AI Status */}
      {hasAI && (
        <PrinterCardAI
          aiEnabled={printer.aiConfig?.enabled}
          aiLevel={printer.aiConfig?.level}
          aiStatus={getAIStatus()}
          compact={false}
        />
      )}

      {/* Metrics (Temperatures + Progress) */}
      <PrinterCardMetrics
        temperatures={printer.liveState?.temperatures}
        progress={printer.liveState?.progress}
        showTemperatures={showTemperatures}
        showProgress={showProgress}
      />

      {/* Quality Score */}
      {showQualityScore && printer.qualityScore !== undefined && (
        <div className="flex items-center justify-between">
          <span className="text-sm text-gray-400">Quality</span>
          <QualityScore score={printer.qualityScore} size="sm" mode="compact" />
        </div>
      )}

      {/* Additional Quick Actions on Hover (if more than 2) */}
      {showActions && quickActions.length > 2 && isHovered && (
        <div className="flex items-center gap-2 pt-2 border-t border-gray-700/50 animate-fade-in">
          {quickActions.slice(2).map((action) => (
            <button
              key={action.id}
              onClick={(e) => {
                e.stopPropagation()
                action.onClick()
              }}
              disabled={action.disabled}
              className={`flex-1 flex items-center justify-center gap-1.5 px-2 py-1.5 rounded-lg text-xs font-medium border transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed ${HOVER_CLASSES.button}`}
              style={getActionButtonStyle(
                action.variant,
                hoveredButton === action.id
              )}
              onMouseEnter={() => setHoveredButton(action.id)}
              onMouseLeave={() => setHoveredButton(null)}
            >
              {action.icon}
              {action.label && <span className="hidden sm:inline">{action.label}</span>}
            </button>
          ))}
        </div>
      )}
    </div>
  )
}

PrinterCard.displayName = 'PrinterCard'

/**
 * Phase 4: memo wrapper with custom equality.
 *
 * Re-render only when the printer object or the action callbacks change.
 * Temperature ticks that don't affect THIS printer are ignored, which
 * prevents the entire grid from re-rendering 50+ times per second.
 */
export const PrinterCardMemo = memo(PrinterCard, (prev, next) => {
  // Different reference = must re-render
  if (prev.printer !== next.printer)     return false
  if (prev.actions  !== next.actions)    return false
  if (prev.size     !== next.size)       return false
  if (prev.layout   !== next.layout)     return false
  if (prev.className !== next.className) return false
  // Nothing changed — skip re-render
  return true
})
PrinterCardMemo.displayName = 'PrinterCardMemo'

export default PrinterCard
