// ─── PrinterInfoPanel ──────────────────────────────────────────
// Displays static info about a printer (type, connection, firmware, etc.)

import type { Printer } from '@core/types/printer'
import { parseConnectionHost, parseConnectionPort } from '@core/types/printer'

export function PrinterInfoPanel({ printer }: { printer: Printer }) {
  const host = parseConnectionHost(printer.connectionUrl)
  const port = parseConnectionPort(printer.connectionUrl)
  const hostDisplay = port ? `${host}:${port}` : host

  return (
    <div className="bg-gray-900/50 border border-gray-700 rounded-lg p-4">
      <h3 className="text-sm font-semibold text-gray-200 mb-3">Printer Info</h3>
      <div className="space-y-2 text-xs">
        <InfoRow label="Adapter" value={printer.adapterType} />
        <InfoRow label="Model" value={printer.printerModel || 'Unknown'} />
        <InfoRow label="Host" value={hostDisplay} mono />
        <InfoRow label="Firmware" value={printer.firmwareVersion || printer.firmwareName || 'N/A'} />
        <InfoRow label="Last Seen" value={printer.lastSeenAt ? new Date(printer.lastSeenAt).toLocaleString() : 'N/A'} />
        {printer.qualityScore !== undefined && (
          <div className="flex justify-between">
            <span className="text-gray-400">Quality Score</span>
            <span className={`font-bold ${printer.qualityScore >= 80 ? 'text-green-400' : printer.qualityScore >= 50 ? 'text-yellow-400' : 'text-red-400'}`}>
              {printer.qualityScore}/100
            </span>
          </div>
        )}
      </div>
    </div>
  )
}

function InfoRow({ label, value, mono }: { label: string; value: string; mono?: boolean }) {
  return (
    <div className="flex justify-between">
      <span className="text-gray-400">{label}</span>
      <span className={`text-gray-200 ${mono ? 'font-mono' : ''}`}>{value}</span>
    </div>
  )
}
