import { useState } from 'react'
import { HelpCircle } from 'lucide-react'
import { faqs, faqCategories } from './faqData'
import { FAQItem } from './FAQItem'

export function FAQSection() {
  const [activeCategory, setActiveCategory] = useState<string>('All')
  const [search, setSearch] = useState('')

  const allCategories = ['All', ...faqCategories]

  const filtered = faqs.filter((f) => {
    const matchCat = activeCategory === 'All' || f.category === activeCategory
    const q = search.toLowerCase()
    const matchSearch =
      !q ||
      f.question.toLowerCase().includes(q) ||
      f.answer.toLowerCase().includes(q) ||
      f.steps?.some((s) => s.toLowerCase().includes(q))
    return matchCat && matchSearch
  })

  return (
    <section>
      <h2 className="text-sm font-semibold text-gray-400 uppercase tracking-widest mb-3">
        Frequently Asked Questions
      </h2>

      <div className="relative mb-4">
        <HelpCircle size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-500" />
        <input
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          placeholder="Search questions…"
          className="w-full bg-gray-900 border border-gray-800 rounded-xl pl-9 pr-4 py-2.5 text-sm text-white placeholder-gray-600 focus:outline-none focus:border-cyan-500 transition-colors"
        />
      </div>

      <div className="flex flex-wrap gap-2 mb-5">
        {allCategories.map((cat) => (
          <button
            key={cat}
            onClick={() => setActiveCategory(cat)}
            className={`px-3 py-1.5 rounded-full text-xs font-medium transition-all ${
              activeCategory === cat
                ? 'bg-cyan-500 text-gray-900 shadow-lg shadow-cyan-500/30'
                : 'bg-gray-800 text-gray-400 hover:bg-gray-700 hover:text-white'
            }`}
          >
            {cat}
            <span className="ml-1.5 opacity-60">
              {cat === 'All' ? faqs.length : faqs.filter((f) => f.category === cat).length}
            </span>
          </button>
        ))}
      </div>

      {filtered.length === 0 ? (
        <div className="text-center py-12 text-gray-600 text-sm">No questions match your search.</div>
      ) : (
        <div className="space-y-2">
          {filtered.map((faq) => <FAQItem key={faq.id} faq={faq} />)}
        </div>
      )}

      <p className="mt-3 text-xs text-gray-600 text-right">
        {filtered.length} of {faqs.length} questions
      </p>
    </section>
  )
}
