// ═══════════════════════════════════════════════════════════════
// PRESTIGE DASHBOARD - EMERGENCY CONTROLS (COMPACT & MODERN)
// ═══════════════════════════════════════════════════════════════

import React, { useState, useMemo } from 'react'
import type {
  EmergencyControlsProps,
  EmergencyAction,
  EmergencyActionType,
  ConfirmationDialogProps,
  EmergencyButtonProps,
} from './EmergencyControls.types'

/**
 * Emergency actions configuration
 */
const EMERGENCY_ACTIONS: Record<EmergencyActionType, EmergencyAction> = {
  estop: {
    type: 'estop',
    label: 'E-STOP',
    icon: '⚠',
    description: 'Emergency stop - immediately halts all printer operations',
    requiresConfirmation: true,
    confirmMessage: 'This will IMMEDIATELY stop all printer operations. This action cannot be undone. Continue?',
    color: '#f00',
    glowColor: 'rgba(255, 0, 0, 0.5)',
  },
  halt_all: {
    type: 'halt_all',
    label: 'HALT ALL',
    icon: '⏹',
    description: 'Stop all active print jobs',
    requiresConfirmation: true,
    confirmMessage: 'This will stop ALL active print jobs. Continue?',
    color: '#f00',
    glowColor: 'rgba(255, 0, 0, 0.5)',
  },
  pause_all: {
    type: 'pause_all',
    label: 'PAUSE ALL',
    icon: '⏸',
    description: 'Pause all active print jobs',
    requiresConfirmation: true,
    confirmMessage: 'This will pause ALL active print jobs. Continue?',
    color: '#ff0',
    glowColor: 'rgba(255, 255, 0, 0.5)',
  },
  resume_all: {
    type: 'resume_all',
    label: 'RESUME ALL',
    icon: '▶',
    description: 'Resume all paused print jobs',
    requiresConfirmation: false,
    confirmMessage: '',
    color: '#0f0',
    glowColor: 'rgba(0, 255, 0, 0.5)',
  },
  cancel_all: {
    type: 'cancel_all',
    label: 'CANCEL ALL',
    icon: '✕',
    description: 'Cancel all print jobs',
    requiresConfirmation: true,
    confirmMessage: 'This will CANCEL ALL print jobs. This action cannot be undone. Continue?',
    color: '#f00',
    glowColor: 'rgba(255, 0, 0, 0.5)',
  },
}

/**
 * Position classes
 */
const POSITION_CLASSES = {
  'bottom-right': 'bottom-20 right-6',
  'bottom-left': 'bottom-20 left-6',
  'top-right': 'top-6 right-6',
  'top-left': 'top-6 left-6',
}

/**
 * Confirmation Dialog Component
 */
const ConfirmationDialog: React.FC<ConfirmationDialogProps> = ({
  isOpen,
  title,
  message,
  confirmLabel = 'Confirm',
  cancelLabel = 'Cancel',
  danger = false,
  onConfirm,
  onCancel,
}) => {
  if (!isOpen) return null

  return (
    <div className="fixed inset-0 z-[9999] flex items-center justify-center bg-black/80 backdrop-blur-sm">
      <div className="relative max-w-md w-full mx-4 p-6 rounded-lg border bg-gray-900 border-gray-700 shadow-2xl">
        {/* Header */}
        <div className="flex items-center gap-3 mb-4">
          <span className="text-3xl">{danger ? '⚠️' : '❓'}</span>
          <h3 className="text-xl font-bold text-white">{title}</h3>
        </div>

        {/* Message */}
        <p className="text-gray-300 mb-6 leading-relaxed">{message}</p>

        {/* Actions */}
        <div className="flex items-center gap-3">
          <button
            onClick={onCancel}
            className="flex-1 px-4 py-2 rounded-lg border border-gray-700 bg-gray-800 text-gray-300 font-medium hover:bg-gray-750 hover:border-gray-600 transition-all"
          >
            {cancelLabel}
          </button>
          <button
            onClick={onConfirm}
            className="flex-1 px-4 py-2 rounded-lg border font-medium transition-all"
            style={{
              backgroundColor: danger ? 'rgba(255, 0, 0, 0.2)' : 'rgba(0, 255, 255, 0.2)',
              borderColor: danger ? 'rgba(255, 0, 0, 0.5)' : 'rgba(0, 255, 255, 0.5)',
              color: danger ? '#f00' : '#0ff',
            }}
          >
            {confirmLabel}
          </button>
        </div>
      </div>
    </div>
  )
}

/**
 * Emergency Button Component
 */
const EmergencyButton: React.FC<EmergencyButtonProps> = ({
  action,
  onClick,
  loading = false,
  disabled = false,
  size = 'md',
}) => {
  const sizeClasses = {
    sm: 'px-3 py-2 text-sm',
    md: 'px-4 py-3 text-base',
    lg: 'px-6 py-4 text-lg',
  }

  return (
    <button
      onClick={onClick}
      disabled={disabled || loading}
      className={`${sizeClasses[size]} rounded-lg border-2 font-bold transition-all disabled:opacity-50 disabled:cursor-not-allowed hover:scale-105 active:scale-95`}
      style={{
        backgroundColor: `${action.color}20`,
        borderColor: action.color,
        color: action.color,
        boxShadow: `0 0 20px ${action.glowColor}`,
      }}
      title={action.description}
    >
      <div className="flex items-center justify-center gap-2">
        <span className="text-xl">{action.icon}</span>
        <span>{loading ? 'Processing...' : action.label}</span>
      </div>
    </button>
  )
}

/**
 * EmergencyControls Component - COMPACT & MODERN
 */
export const EmergencyControls: React.FC<EmergencyControlsProps & { embedded?: boolean; sidebarCollapsed?: boolean }> = ({
  printers = [],
  handlers,
  position = 'bottom-right',
  defaultExpanded = false,
  showPrinterList = false,
  className = '',
  embedded = false,
  sidebarCollapsed = false,
}) => {
  const [isExpanded, setIsExpanded] = useState(defaultExpanded)
  const [loadingAction, setLoadingAction] = useState<EmergencyActionType | null>(null)
  const [confirmDialog, setConfirmDialog] = useState<{
    isOpen: boolean
    action: EmergencyAction | null
    handler: (() => void | Promise<void>) | null
  }>({
    isOpen: false,
    action: null,
    handler: null,
  })

  // Count active printers
  const activePrinters = useMemo(
    () => printers.filter((p) => p.status === 'printing' || p.status === 'paused'),
    [printers]
  )

  // Handle action click
  const handleActionClick = async (action: EmergencyAction, handler?: () => void | Promise<void>) => {
    if (!handler) return

    if (action.requiresConfirmation) {
      setConfirmDialog({
        isOpen: true,
        action,
        handler,
      })
    } else {
      await executeAction(action.type, handler)
    }
  }

  // Execute action
  const executeAction = async (type: EmergencyActionType, handler: () => void | Promise<void>) => {
    try {
      setLoadingAction(type)
      await handler()
    } catch (error) {
      console.error('Emergency action failed:', error)
    } finally {
      setLoadingAction(null)
    }
  }

  // Handle confirmation
  const handleConfirm = async () => {
    if (confirmDialog.action && confirmDialog.handler) {
      await executeAction(confirmDialog.action.type, confirmDialog.handler)
    }
    setConfirmDialog({ isOpen: false, action: null, handler: null })
  }

  // Handle cancel
  const handleCancel = () => {
    setConfirmDialog({ isOpen: false, action: null, handler: null })
  }

  // Expanded panel — centered modal
  const expandedPanel = isExpanded && (
    <div className="fixed inset-0 z-[199] bg-black/60 backdrop-blur-sm" onClick={() => setIsExpanded(false)}>
    <div
      className="fixed z-[200] p-4 rounded-lg border-2 bg-gray-900/95 backdrop-blur-md shadow-2xl"
      style={{
        top: '50%',
        left: '50%',
        transform: 'translate(-50%, -50%)',
        borderColor: '#f00',
        boxShadow: '0 0 60px rgba(255, 0, 0, 0.4)',
        minWidth: '340px',
        width: '340px',
      }}
      onClick={(e) => e.stopPropagation()}
    >
      {/* Header */}
      <div className="flex items-center justify-between mb-4 pb-3 border-b border-gray-800">
        <div className="flex items-center gap-2">
          <span className="text-2xl">⚠️</span>
          <h3 className="text-lg font-bold text-red-500">EMERGENCY CONTROLS</h3>
        </div>
        <button
          onClick={() => setIsExpanded(false)}
          className="text-gray-400 hover:text-gray-200 transition-colors"
        >
          ✕
        </button>
      </div>

      {activePrinters.length > 0 && (
        <div className="mb-4 p-2 rounded bg-gray-800/50 border border-gray-700">
          <span className="text-xs text-gray-400">
            {activePrinters.length} active {activePrinters.length === 1 ? 'printer' : 'printers'}
          </span>
        </div>
      )}

      <div className="flex flex-col gap-3 min-w-[280px]">
        <EmergencyButton
          action={EMERGENCY_ACTIONS.estop}
          onClick={() => handleActionClick(EMERGENCY_ACTIONS.estop, handlers.onEmergencyStop)}
          loading={loadingAction === 'estop'}
          size="lg"
        />
        <div className="grid grid-cols-2 gap-2">
          {handlers.onHaltAll && (
            <EmergencyButton
              action={EMERGENCY_ACTIONS.halt_all}
              onClick={() => handleActionClick(EMERGENCY_ACTIONS.halt_all, handlers.onHaltAll)}
              loading={loadingAction === 'halt_all'}
              size="sm"
              disabled={activePrinters.length === 0}
            />
          )}
          {handlers.onPauseAll && (
            <EmergencyButton
              action={EMERGENCY_ACTIONS.pause_all}
              onClick={() => handleActionClick(EMERGENCY_ACTIONS.pause_all, handlers.onPauseAll)}
              loading={loadingAction === 'pause_all'}
              size="sm"
              disabled={activePrinters.filter((p) => p.status === 'printing').length === 0}
            />
          )}
          {handlers.onResumeAll && (
            <EmergencyButton
              action={EMERGENCY_ACTIONS.resume_all}
              onClick={() => handleActionClick(EMERGENCY_ACTIONS.resume_all, handlers.onResumeAll)}
              loading={loadingAction === 'resume_all'}
              size="sm"
              disabled={activePrinters.filter((p) => p.status === 'paused').length === 0}
            />
          )}
          {handlers.onCancelAll && (
            <EmergencyButton
              action={EMERGENCY_ACTIONS.cancel_all}
              onClick={() => handleActionClick(EMERGENCY_ACTIONS.cancel_all, handlers.onCancelAll)}
              loading={loadingAction === 'cancel_all'}
              size="sm"
              disabled={activePrinters.length === 0}
            />
          )}
        </div>
      </div>
    </div>
    </div>
  )

  // Trigger button
  const triggerButton = (
    <button
      onClick={() => setIsExpanded(!isExpanded)}
      className={`group relative flex items-center justify-center rounded-xl transition-all duration-200 hover:scale-105 active:scale-95 ${
        embedded && !sidebarCollapsed ? 'w-full gap-3 px-3' : ''
      }`}
      style={{
        width: embedded && !sidebarCollapsed ? '100%' : '48px',
        height: '48px',
        background: isExpanded
          ? 'linear-gradient(135deg, rgba(239, 68, 68, 0.3), rgba(220, 38, 38, 0.2))'
          : 'linear-gradient(135deg, rgba(239, 68, 68, 0.15), rgba(220, 38, 38, 0.1))',
        border: '1.5px solid rgba(239, 68, 68, 0.4)',
        boxShadow: '0 0 20px rgba(239, 68, 68, 0.2), 0 4px 12px rgba(0, 0, 0, 0.5), inset 0 1px 0 rgba(255, 255, 255, 0.1)',
        backdropFilter: 'blur(12px)',
        justifyContent: embedded && !sidebarCollapsed ? 'flex-start' : 'center',
      }}
      title="Emergency Controls"
    >
      <div
        className="absolute inset-0 rounded-xl animate-pulse"
        style={{
          border: '1.5px solid rgba(239, 68, 68, 0.3)',
          animation: 'pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite',
        }}
      />
      <span
        className="text-xl relative z-10 transition-transform group-hover:scale-110 flex-shrink-0"
        style={{
          color: '#ef4444',
          filter: 'drop-shadow(0 0 4px rgba(239, 68, 68, 0.6))',
        }}
      >
        ⚠
      </span>
      {embedded && !sidebarCollapsed && (
        <span
          className="relative z-10 text-sm font-bold tracking-wider"
          style={{ color: '#ef4444' }}
        >
          EMERGENCY
        </span>
      )}
    </button>
  )

  if (embedded) {
    return (
      <>
        {expandedPanel}
        {triggerButton}
        {confirmDialog.action && (
          <ConfirmationDialog
            isOpen={confirmDialog.isOpen}
            title={confirmDialog.action.label}
            message={confirmDialog.action.confirmMessage}
            confirmLabel="EXECUTE"
            cancelLabel="Cancel"
            danger={confirmDialog.action.type === 'estop' || confirmDialog.action.type === 'cancel_all'}
            onConfirm={handleConfirm}
            onCancel={handleCancel}
          />
        )}
      </>
    )
  }

  return (
    <>
      {/* Floating wrapper */}
      <div
        className={`fixed ${POSITION_CLASSES[position]} z-50 ${className}`}
        style={{ pointerEvents: 'auto' }}
      >
        {triggerButton}
      </div>

      {/* Expanded panel (fixed, above button) */}
      {expandedPanel}

      {/* Confirmation Dialog */}
      {confirmDialog.action && (
        <ConfirmationDialog
          isOpen={confirmDialog.isOpen}
          title={confirmDialog.action.label}
          message={confirmDialog.action.confirmMessage}
          confirmLabel="EXECUTE"
          cancelLabel="Cancel"
          danger={confirmDialog.action.type === 'estop' || confirmDialog.action.type === 'cancel_all'}
          onConfirm={handleConfirm}
          onCancel={handleCancel}
        />
      )}
    </>
  )
}

EmergencyControls.displayName = 'EmergencyControls'

export default EmergencyControls
