import { api } from './api'

export interface DiscoveredPrinter {
  host: string
  port: number
  type: 'moonraker' | 'octoprint' | 'unknown'
  connectionUrl: string
  name?: string
  version?: string
  reachable: boolean
}

export interface DiscoveryResult {
  found: DiscoveredPrinter[]
  scanned: number
  durationMs: number
  networkBase: string
}

export const discoveryApi = {
  /**
   * Scan the full subnet for printers
   */
  scan: async (range?: string): Promise<DiscoveryResult> => {
    const params = range ? `?range=${encodeURIComponent(range)}` : ''
    return api.get<DiscoveryResult>(`/api/discovery${params}`)
  },

  /**
   * Probe a single host
   */
  probe: async (host: string, port?: number): Promise<DiscoveredPrinter | null> => {
    return api.post<DiscoveredPrinter | null>('/api/discovery/probe', { host, port })
  },
}
