// ═══════════════════════════════════════════════════════════════
// PRESTIGE DASHBOARD - PRINTER API SERVICE
// ═══════════════════════════════════════════════════════════════

import { api } from './api'
import type { Printer, PrinterCommand, PrinterLiveState, PrintJob } from '../core/types'

/**
 * Printer API endpoints
 */
const ENDPOINTS = {
  printers: '/api/printers',
  printer: (id: string) => `/api/printers/${id}`,
  printerState: (id: string) => `/api/printers/${id}/state`,
  printerCommand: (id: string) => `/api/printers/${id}/command`,
  // NOTE: Backend exposes job history via /jobs (Moonraker proxy), not /history.
  // /history did not exist in backend — corrected to match printer-proxy.routes.ts.
  printerJobs: (id: string) => `/api/printers/${id}/jobs`,
  addPrinter: '/api/printers',
  removePrinter: (id: string) => `/api/printers/${id}`,
}

/**
 * Printer API service
 */
export const printerApi = {
  /**
   * Get all printers
   */
  getAll: async (): Promise<Printer[]> => {
    return api.get<Printer[]>(ENDPOINTS.printers)
  },

  /**
   * Get single printer by ID
   */
  getById: async (id: string): Promise<Printer> => {
    return api.get<Printer>(ENDPOINTS.printer(id))
  },

  /**
   * Get printer state (real-time data)
   */
  getState: async (id: string): Promise<PrinterLiveState> => {
    return api.get<PrinterLiveState>(ENDPOINTS.printerState(id))
  },

  /**
   * Send command to printer
   */
  sendCommand: async (id: string, command: PrinterCommand): Promise<void> => {
    return api.post<void>(ENDPOINTS.printerCommand(id), command)
  },

  /**
   * Pause print
   */
  pause: async (id: string): Promise<void> => {
    return printerApi.sendCommand(id, { type: 'pause' })
  },

  /**
   * Resume print
   */
  resume: async (id: string): Promise<void> => {
    return printerApi.sendCommand(id, { type: 'resume' })
  },

  /**
   * Cancel print
   */
  cancel: async (id: string): Promise<void> => {
    return printerApi.sendCommand(id, { type: 'cancel' })
  },

  /**
   * Emergency stop
   */
  emergencyStop: async (id: string): Promise<void> => {
    return printerApi.sendCommand(id, { type: 'emergency_stop' })
  },

  /**
   * Get printer job history (via Moonraker proxy).
   * Backend endpoint: GET /api/printers/:id/jobs
   * Returns jobs from Moonraker history, mapped to a normalised shape.
   */
  getHistory: async (
    id: string,
    options?: { limit?: number; start?: number }
  ): Promise<{ jobs: PrintJob[]; total: number }> => {
    return api.get(ENDPOINTS.printerJobs(id), { params: options as Record<string, string | number | boolean> })
  },

  /**
   * Add new printer.
   * Body matches backend createPrinterSchema exactly:
   *   name, adapterType, connectionUrl (optional), apiKey (optional),
   *   enabled (default true), autoReconnect (default true), pollingIntervalMs (default 1000).
   */
  add: async (printer: {
    name: string
    adapterType: 'mock' | 'moonraker' | 'octoprint'
    connectionUrl?: string
    apiKey?: string
    enabled?: boolean
    autoReconnect?: boolean
    pollingIntervalMs?: number
  }): Promise<Printer> => {
    return api.post<Printer>(ENDPOINTS.addPrinter, printer)
  },

  /**
   * Remove printer
   */
  remove: async (id: string): Promise<void> => {
    return api.delete<void>(ENDPOINTS.removePrinter(id))
  },

  /**
   * Connect printer
   */
  connect: async (id: string): Promise<void> => {
    return api.post<void>(`/api/printers/${id}/connect`, {})
  },

  /**
   * Disconnect printer
   */
  disconnect: async (id: string): Promise<void> => {
    return api.post<void>(`/api/printers/${id}/disconnect`, {})
  },

  /**
   * Update printer settings (full, including adapterType)
   */
  update: async (
    id: string,
    updates: Partial<Pick<Printer, 'name' | 'adapterType' | 'connectionUrl' | 'apiKey' | 'enabled' | 'autoReconnect' | 'pollingIntervalMs' | 'notes' | 'tags'>>
  ): Promise<Printer> => {
    return api.put<Printer>(ENDPOINTS.printer(id), updates)
  },

  /**
   * Fetch build volume via backend proxy (avoids CORS — never call Moonraker directly from the browser).
   * Backend endpoint: GET /api/printers/:id/build-volume
   * The backend queries Moonraker's configfile.settings.stepper_x/y/z.position_max
   * and returns { buildVolume: { x, y, z }, source }.
   * Falls back to null so the caller can use its own default.
   */
  fetchBuildVolume: async (printerId: string): Promise<{ x: number; y: number; z: number } | null> => {
    try {
      const data = await api.get<{ buildVolume: { x: number; y: number; z: number } | null; source: string }>(
        `/api/printers/${printerId}/build-volume`
      )

      if (!data?.buildVolume) {
        console.log(`ℹ️ No build volume from backend (source: ${data?.source ?? 'unknown'}) — using default`)
        return null
      }

      const { x, y, z } = data.buildVolume
      console.log(`✅ Fetched build volume via backend (source: ${data.source}):`, { x, y, z })
      return { x, y, z }
    } catch (error: any) {
      console.warn('⚠️ Could not fetch build volume:', error?.message ?? error)
      return null
    }
  },

  /**
   * Save build volume manually (persisted to printer capabilities in DB).
   * Backend endpoint: PATCH /api/printers/:id/build-volume
   */
  saveBuildVolume: async (
    printerId: string,
    volume: { x: number; y: number; z: number }
  ): Promise<void> => {
    await api.patch(`/api/printers/${printerId}/build-volume`, volume)
  },
}

export default printerApi
