// ═══════════════════════════════════════════════════════════════
// PRESTIGE DASHBOARD - Login / Register Page
// ═══════════════════════════════════════════════════════════════

import { useState, useEffect } from 'react'
import { useNavigate, useLocation } from 'react-router-dom'
import { motion, AnimatePresence } from 'framer-motion'
import {
  Eye, EyeOff, Mail, Lock, User,
  AlertCircle, CheckCircle, Loader2, ArrowRight, KeyRound,
} from 'lucide-react'
import { useAuthStore } from '@core/state'

type Mode = 'login' | 'register' | 'forgot'

interface FormState {
  email:    string
  password: string
  fullName: string
  confirm:  string
}

// ─── Validation ───────────────────────────────────────────────

function validate(form: FormState, mode: Mode): string | null {
  if (!form.email.match(/^[^\s@]+@[^\s@]+\.[^\s@]+$/))
    return 'Invalid email address'
  if (mode === 'forgot') return null
  if (form.password.length < 8)
    return 'Password must be at least 8 characters'
  if (mode === 'register') {
    if (!form.fullName.trim()) return 'Please enter your name'
    if (form.password !== form.confirm) return 'Passwords do not match'
  }
  return null
}

// ─── Background (shared) ──────────────────────────────────────

const BG_GRID_STYLE = {
  backgroundImage:
    'linear-gradient(rgba(0,212,255,0.03) 1px, transparent 1px),' +
    'linear-gradient(90deg, rgba(0,212,255,0.03) 1px, transparent 1px)',
  backgroundSize: '48px 48px',
}

function PageBackground() {
  return (
    <>
      <div className="absolute inset-0 pointer-events-none" style={BG_GRID_STYLE} />
      <div className="absolute top-1/3 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[600px] h-[600px] bg-cyan-500/5 rounded-full blur-3xl pointer-events-none" />
    </>
  )
}

function Logo() {
  return (
    <div className="flex flex-col items-center mb-10">
      <div className="w-16 h-16 rounded-2xl bg-gradient-to-br from-cyan-500 to-blue-600 flex items-center justify-center shadow-2xl shadow-cyan-500/30 mb-4">
        <span className="text-white font-bold text-2xl">P</span>
      </div>
      <h1
        className="text-2xl font-bold text-white tracking-widest"
        style={{ fontFamily: "'Share Tech Mono', monospace" }}
      >
        PRESTILON
      </h1>
    </div>
  )
}

// ─── Input ────────────────────────────────────────────────────

interface InputProps {
  icon:        React.ReactNode
  type:        string
  placeholder: string
  value:       string
  onChange:    (v: string) => void
  disabled?:   boolean
  action?:     React.ReactNode
  error?:      boolean
}

function AuthInput({ icon, type, placeholder, value, onChange, disabled, action, error }: InputProps) {
  return (
    <div
      className={`
        flex items-center gap-3 px-4 py-3.5 rounded-xl border bg-gray-900/80
        transition-colors duration-200
        ${error
          ? 'border-red-500/50 focus-within:border-red-400'
          : 'border-gray-700/60 focus-within:border-cyan-500/60'
        }
      `}
    >
      <span className={`flex-shrink-0 ${error ? 'text-red-400' : 'text-gray-500'}`}>{icon}</span>
      <input
        type={type}
        placeholder={placeholder}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        disabled={disabled}
        autoComplete={
          type === 'email'    ? 'email'            :
          type === 'password' ? 'current-password' :
          'off'
        }
        className="flex-1 bg-transparent text-sm text-white placeholder-gray-500 outline-none disabled:opacity-50"
      />
      {action}
    </div>
  )
}

// ─── Submit button ────────────────────────────────────────────

function SubmitButton({ loading, label }: { loading: boolean; label: string }) {
  return (
    <button
      type="submit"
      disabled={loading}
      className="
        w-full flex items-center justify-center gap-2 py-3.5 rounded-xl
        bg-gradient-to-r from-cyan-600 to-blue-600
        hover:from-cyan-500 hover:to-blue-500
        text-white font-semibold text-sm
        disabled:opacity-50 disabled:cursor-not-allowed
        transition-all duration-200 shadow-lg shadow-cyan-500/20
        active:scale-[0.98]
      "
    >
      {loading
        ? <><Loader2 size={16} className="animate-spin" /><span>Please wait...</span></>
        : <><span>{label}</span><ArrowRight size={16} /></>
      }
    </button>
  )
}

// ─── Error banner ─────────────────────────────────────────────

function ErrorBanner({ message }: { message: string | null }) {
  return (
    <AnimatePresence>
      {message && (
        <motion.div
          initial={{ opacity: 0, y: 4 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0 }}
          className="flex items-start gap-2.5 px-4 py-3 rounded-xl bg-red-500/10 border border-red-500/20 text-red-400 text-sm"
        >
          <AlertCircle size={15} className="flex-shrink-0 mt-0.5" />
          <span>{message}</span>
        </motion.div>
      )}
    </AnimatePresence>
  )
}

// ─── Main component ───────────────────────────────────────────

export default function LoginPage() {
  const navigate = useNavigate()
  const location = useLocation()
  const { signIn, signUp, session, isInitialized } = useAuthStore()

  const [mode, setMode]           = useState<Mode>('login')
  const [showPass, setShowPass]   = useState(false)
  const [showConf, setShowConf]   = useState(false)
  const [submitted, setSubmitted] = useState(false)   // email verify screen
  const [resetSent, setResetSent] = useState(false)   // forgot pw screen
  const [formError, setFormError] = useState<string | null>(null)
  const [loading, setLoading]     = useState(false)

  const [form, setForm] = useState<FormState>({
    email: '', password: '', fullName: '', confirm: '',
  })

  const from = (location.state as { from?: string })?.from ?? '/'

  useEffect(() => {
    if (isInitialized && session) navigate(from, { replace: true })
  }, [isInitialized, session, navigate, from])

  const field = (key: keyof FormState) => (v: string) => {
    setForm((f) => ({ ...f, [key]: v }))
    setFormError(null)
  }

  const switchMode = (m: Mode) => {
    setMode(m)
    setFormError(null)
    setForm({ email: '', password: '', fullName: '', confirm: '' })
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setFormError(null)

    const err = validate(form, mode)
    if (err) { setFormError(err); return }

    setLoading(true)
    try {
      if (mode === 'login') {
        const { error } = await signIn(form.email, form.password)
        if (error) setFormError(translateError(error))

      } else if (mode === 'register') {
        const { error } = await signUp(form.email, form.password, form.fullName)
        if (error) { setFormError(translateError(error)); return }
        const store = useAuthStore.getState()
        if (store.session) navigate(from, { replace: true })
        else setSubmitted(true)

      } else {
        // forgot password — call Supabase reset
        const SUPABASE_URL     = (import.meta.env.VITE_SUPABASE_URL     as string) ?? ''
        const SUPABASE_ANON_KEY = (import.meta.env.VITE_SUPABASE_ANON_KEY as string) ?? ''
        const res = await fetch(`${SUPABASE_URL}/auth/v1/recover`, {
          method:  'POST',
          headers: { 'Content-Type': 'application/json', apikey: SUPABASE_ANON_KEY },
          body:    JSON.stringify({ email: form.email, redirectTo: 'https://prestilon.com/reset-password' }),
        })
        if (!res.ok) {
          const j = await res.json().catch(() => ({}))
          setFormError(j.message ?? 'Failed to send reset email')
        } else {
          setResetSent(true)
        }
      }
    } finally {
      setLoading(false)
    }
  }

  // ── Email verify screen ──────────────────────────────────────
  if (submitted) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-950 p-4 relative overflow-hidden">
        <PageBackground />
        <motion.div
          initial={{ opacity: 0, y: 24 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.35, ease: 'easeOut' }}
          className="relative z-10 w-full max-w-sm"
        >
          <Logo />
          <div className="rounded-2xl border border-gray-800 bg-gray-900/80 p-8 text-center">
            <div className="w-16 h-16 mx-auto mb-5 rounded-full bg-green-500/10 border border-green-500/30 flex items-center justify-center">
              <CheckCircle className="w-8 h-8 text-green-400" />
            </div>
            <h2 className="text-xl font-bold text-white mb-2">Verify your email</h2>
            <p className="text-gray-400 text-sm mb-1">A confirmation link has been sent to</p>
            <p className="text-cyan-400 font-medium text-sm mb-5 break-all">{form.email}</p>
            <p className="text-gray-500 text-xs mb-7">
              Click the link in the email to activate your account, then sign in.
            </p>
            <button
              onClick={() => { setSubmitted(false); switchMode('login') }}
              className="w-full py-3 bg-gradient-to-r from-cyan-600 to-blue-600 hover:from-cyan-500 hover:to-blue-500 text-white rounded-xl text-sm font-semibold transition-all duration-200 shadow-lg shadow-cyan-500/20"
            >
              Back to Sign In
            </button>
          </div>
        </motion.div>
      </div>
    )
  }

  // ── Password reset sent screen ───────────────────────────────
  if (resetSent) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-950 p-4 relative overflow-hidden">
        <PageBackground />
        <motion.div
          initial={{ opacity: 0, y: 24 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.35, ease: 'easeOut' }}
          className="relative z-10 w-full max-w-sm"
        >
          <Logo />
          <div className="rounded-2xl border border-gray-800 bg-gray-900/80 p-8 text-center">
            <div className="w-16 h-16 mx-auto mb-5 rounded-full bg-cyan-500/10 border border-cyan-500/30 flex items-center justify-center">
              <KeyRound className="w-8 h-8 text-cyan-400" />
            </div>
            <h2 className="text-xl font-bold text-white mb-2">Check your inbox</h2>
            <p className="text-gray-400 text-sm mb-1">A password reset link has been sent to</p>
            <p className="text-cyan-400 font-medium text-sm mb-5 break-all">{form.email}</p>
            <p className="text-gray-500 text-xs mb-7">
              Follow the link in the email to set a new password.
            </p>
            <button
              onClick={() => { setResetSent(false); switchMode('login') }}
              className="w-full py-3 bg-gradient-to-r from-cyan-600 to-blue-600 hover:from-cyan-500 hover:to-blue-500 text-white rounded-xl text-sm font-semibold transition-all duration-200 shadow-lg shadow-cyan-500/20"
            >
              Back to Sign In
            </button>
          </div>
        </motion.div>
      </div>
    )
  }

  // ── Main form ────────────────────────────────────────────────
  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-950 p-4 relative overflow-hidden">
      <PageBackground />

      <motion.div
        initial={{ opacity: 0, y: 24 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.35, ease: 'easeOut' }}
        className="relative z-10 w-full max-w-sm"
      >
        <Logo />

        {/* ── Forgot password view ───────────────────────── */}
        <AnimatePresence mode="wait">
          {mode === 'forgot' ? (
            <motion.div
              key="forgot"
              initial={{ opacity: 0, y: 8 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -8 }}
              transition={{ duration: 0.2 }}
            >
              <div className="mb-6">
                <h2 className="text-xl font-bold text-white">Reset password</h2>
                <p className="text-gray-500 text-sm mt-1">
                  Enter your email and we'll send you a reset link
                </p>
              </div>
              <form onSubmit={handleSubmit} className="space-y-3" noValidate>
                <AuthInput
                  icon={<Mail size={16} />}
                  type="email"
                  placeholder="email@example.com"
                  value={form.email}
                  onChange={field('email')}
                  disabled={loading}
                />
                <SubmitButton loading={loading} label="Send Reset Link" />
                <ErrorBanner message={formError} />
              </form>
              <p className="text-center text-sm text-gray-500 mt-6">
                <button
                  onClick={() => switchMode('login')}
                  className="text-cyan-400 hover:text-cyan-300 font-medium transition-colors"
                >
                  ← Back to Sign In
                </button>
              </p>
            </motion.div>

          ) : (
            /* ── Sign In / Register view ──────────────────── */
            <motion.div
              key="auth"
              initial={{ opacity: 0, y: 8 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -8 }}
              transition={{ duration: 0.2 }}
            >
              {/* Mode tabs */}
              <div className="flex rounded-xl bg-gray-900 border border-gray-800 p-1 mb-8">
                {(['login', 'register'] as Mode[]).map((m) => (
                  <button
                    key={m}
                    type="button"
                    onClick={() => switchMode(m)}
                    className={`
                      flex-1 py-2.5 rounded-lg text-sm font-medium transition-all duration-200
                      ${mode === m
                        ? 'bg-cyan-600 text-white shadow-lg'
                        : 'text-gray-400 hover:text-white'
                      }
                    `}
                  >
                    {m === 'login' ? 'Sign In' : 'Register'}
                  </button>
                ))}
              </div>

              {/* Heading */}
              <AnimatePresence mode="wait">
                <motion.div
                  key={mode}
                  initial={{ opacity: 0, y: 6 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -6 }}
                  transition={{ duration: 0.18 }}
                  className="mb-6"
                >
                  <h2 className="text-xl font-bold text-white">
                    {mode === 'login' ? 'Welcome back!' : 'Create an account'}
                  </h2>
                  <p className="text-gray-500 text-sm mt-1">
                    {mode === 'login'
                      ? 'Sign in to your PRESTILON account'
                      : 'Register to get started with PRESTILON'
                    }
                  </p>
                </motion.div>
              </AnimatePresence>

              {/* Form */}
              <form onSubmit={handleSubmit} className="space-y-3" noValidate>
                {/* Full name (register only) */}
                <AnimatePresence>
                  {mode === 'register' && (
                    <motion.div
                      initial={{ opacity: 0, height: 0 }}
                      animate={{ opacity: 1, height: 'auto' }}
                      exit={{ opacity: 0, height: 0 }}
                      transition={{ duration: 0.2 }}
                    >
                      <AuthInput
                        icon={<User size={16} />}
                        type="text"
                        placeholder="Full Name"
                        value={form.fullName}
                        onChange={field('fullName')}
                        disabled={loading}
                        error={!!formError && !form.fullName.trim()}
                      />
                    </motion.div>
                  )}
                </AnimatePresence>

                <AuthInput
                  icon={<Mail size={16} />}
                  type="email"
                  placeholder="email@example.com"
                  value={form.email}
                  onChange={field('email')}
                  disabled={loading}
                  error={!!formError && !form.email.match(/^[^\s@]+@[^\s@]+\.[^\s@]+$/)}
                />

                <AuthInput
                  icon={<Lock size={16} />}
                  type={showPass ? 'text' : 'password'}
                  placeholder="Password"
                  value={form.password}
                  onChange={field('password')}
                  disabled={loading}
                  action={
                    <button
                      type="button"
                      tabIndex={-1}
                      onClick={() => setShowPass((v) => !v)}
                      className="text-gray-500 hover:text-gray-300 transition-colors"
                    >
                      {showPass ? <EyeOff size={16} /> : <Eye size={16} />}
                    </button>
                  }
                />

                {/* Confirm password (register only) */}
                <AnimatePresence>
                  {mode === 'register' && (
                    <motion.div
                      initial={{ opacity: 0, height: 0 }}
                      animate={{ opacity: 1, height: 'auto' }}
                      exit={{ opacity: 0, height: 0 }}
                      transition={{ duration: 0.2 }}
                    >
                      <AuthInput
                        icon={<Lock size={16} />}
                        type={showConf ? 'text' : 'password'}
                        placeholder="Confirm password"
                        value={form.confirm}
                        onChange={field('confirm')}
                        disabled={loading}
                        error={!!formError && form.password !== form.confirm}
                        action={
                          <button
                            type="button"
                            tabIndex={-1}
                            onClick={() => setShowConf((v) => !v)}
                            className="text-gray-500 hover:text-gray-300 transition-colors"
                          >
                            {showConf ? <EyeOff size={16} /> : <Eye size={16} />}
                          </button>
                        }
                      />
                    </motion.div>
                  )}
                </AnimatePresence>

                {/* Forgot password link (login only) */}
                {mode === 'login' && (
                  <div className="flex justify-end">
                    <button
                      type="button"
                      tabIndex={-1}
                      onClick={() => switchMode('forgot')}
                      className="text-xs text-gray-500 hover:text-cyan-400 transition-colors"
                    >
                      Forgot password?
                    </button>
                  </div>
                )}

                {/* Submit */}
                <SubmitButton
                  loading={loading}
                  label={mode === 'login' ? 'Sign In' : 'Create Account'}
                />

                {/* Error — below button, doesn't push fields */}
                <ErrorBanner message={formError} />
              </form>

              {/* Switch mode */}
              <p className="text-center text-sm text-gray-500 mt-6">
                {mode === 'login' ? "Don't have an account? " : 'Already have an account? '}
                <button
                  type="button"
                  onClick={() => switchMode(mode === 'login' ? 'register' : 'login')}
                  className="text-cyan-400 hover:text-cyan-300 font-medium transition-colors"
                >
                  {mode === 'login' ? 'Register' : 'Sign In'}
                </button>
              </p>
            </motion.div>
          )}
        </AnimatePresence>
      </motion.div>
    </div>
  )
}

// ─── Error translation ────────────────────────────────────────

function translateError(err: string): string {
  const lower = err.toLowerCase()
  if (lower.includes('invalid login credentials'))   return 'Incorrect email or password'
  if (lower.includes('email not confirmed'))         return 'Email not confirmed. Please check your inbox.'
  if (lower.includes('user already registered'))     return 'This email is already registered'
  if (lower.includes('password should be at least')) return 'Password is too short (min. 6 characters)'
  if (lower.includes('signup_disabled'))             return 'Registration is currently disabled'
  if (lower.includes('rate_limit') || lower.includes('too many'))
                                                     return 'Too many attempts. Please wait a moment.'
  if (lower.includes('network') || lower.includes('fetch'))
                                                     return 'Network error. Check your connection.'
  return err
}
