// ═══════════════════════════════════════════════════════════════
// PRESTIGE DASHBOARD - MAINTENANCE PAGE
// Route: /maintenance
// Tabs: Tasks (AI predictions) | Register Change | Change History
// ═══════════════════════════════════════════════════════════════

import { useState, useEffect, useMemo, useCallback } from 'react'
import {
  Wrench, CheckCircle2, AlertTriangle, ChevronDown, ChevronUp,
  Droplets, Cog, Zap, Plus, History as HistoryIcon, RefreshCw,
  FlaskConical,
} from 'lucide-react'
import { usePrinterStore, selectPrintersArray } from '@core/state/printerStore'
import { ManualChangeForm } from '@features/maintenance/ManualChangeForm'
import { MaintenanceHistory } from '@features/maintenance/MaintenanceHistory'
import { PrinterSelectorBar } from '@core/components/PrinterSelectorBar'
import { aiApi } from '@/services/ai-api'

// ─── API response types (mirror backend MaintenancePredictionResult) ──────────

interface ComponentHealthData {
  component: string
  healthPercent: number
  estimatedLifeRemaining: number | null
  lastMaintenance: string | null
  printHoursSinceMaintenance: number
  wearIndicators: string[]
  recommendedAction: string | null
}

interface MaintenancePredData {
  componentHealth: ComponentHealthData[]
  overallMaintenanceScore: number
  nextScheduledMaintenance: {
    type: string
    estimatedDate: string | null
    urgency: 'low' | 'medium' | 'high' | 'critical'
  } | null
  totalPrintHours: number
}

// ─── Internal UI types ─────────────────────────────────────────────────────

interface MaintenanceTask {
  id: string
  printerId: string
  printerName: string
  task: string
  category: 'lubrication' | 'cleaning' | 'calibration' | 'replacement' | 'inspection'
  status: 'pending' | 'due' | 'overdue' | 'completed'
  interval: string
  lastCompleted?: string
  nextDue?: string
  /** Backend component name — used when marking task complete */
  componentKey: string
}

type TabView = 'tasks' | 'register' | 'history'

// ─── Mapping helpers ────────────────────────────────────────────────────────

function componentToCategory(component: string): MaintenanceTask['category'] {
  const c = component.toLowerCase()
  if (/nozzle|hotend|extrud|filament/.test(c)) return 'replacement'
  if (/belt|tension/.test(c))                  return 'inspection'
  if (/rail|linear|rod|bearing|lubricat/.test(c)) return 'lubrication'
  if (/bed|level|mesh|calibrat/.test(c))       return 'calibration'
  if (/clean/.test(c))                         return 'cleaning'
  return 'inspection'
}

function componentToMaintenanceType(component: string): string {
  const c = component.toLowerCase()
  if (/nozzle/.test(c))              return 'NOZZLE_CHANGE'
  if (/belt/.test(c))                return 'BELT_TENSION'
  if (/rail|linear|rod|bearing|lubricat/.test(c)) return 'LUBRICATION'
  if (/bed|level|mesh/.test(c))      return 'BED_LEVELING'
  if (/hotend|extrud/.test(c))       return 'HOTEND_CHANGE'
  return 'OTHER'
}

/** health % → task status */
function healthToStatus(health: number): MaintenanceTask['status'] {
  if (health >= 90) return 'pending'
  if (health >= 65) return 'due'
  if (health >= 1)  return 'overdue'
  return 'completed'  // health = 0 means no component data, treat as N/A → pending
}

/** Format hours remaining as a human-readable interval string */
function hoursToInterval(hours: number | null): string {
  if (hours === null) return 'Check schedule'
  if (hours <= 0)     return 'Overdue'
  if (hours < 10)     return `~${Math.round(hours)}h remaining`
  if (hours < 100)    return `~${Math.round(hours / 5) * 5}h remaining`
  return `~${Math.round(hours / 50) * 50}h remaining`
}

const CATEGORY_ICONS: Record<string, React.ReactNode> = {
  lubrication:  <Droplets   className="w-4 h-4" />,
  cleaning:     <Wrench     className="w-4 h-4" />,
  calibration:  <Cog        className="w-4 h-4" />,
  replacement:  <Zap        className="w-4 h-4" />,
  inspection:   <AlertTriangle className="w-4 h-4" />,
}

// ─── Map API prediction → task list ────────────────────────────────────────

function predictionToTasks(
  printerId: string,
  printerName: string,
  pred: MaintenancePredData,
): MaintenanceTask[] {
  return pred.componentHealth
    .filter(ch => ch.component && ch.healthPercent >= 0)
    .map(ch => {
      const status = healthToStatus(ch.healthPercent)
      return {
        id:           `mt-${printerId}-${ch.component}`,
        printerId,
        printerName,
        componentKey: ch.component,
        task:         ch.recommendedAction ?? `Inspect ${ch.component.replace(/_/g, ' ')}`,
        category:     componentToCategory(ch.component),
        status,
        interval:     hoursToInterval(ch.estimatedLifeRemaining),
        lastCompleted: ch.lastMaintenance ?? undefined,
        nextDue:       pred.nextScheduledMaintenance?.estimatedDate ?? undefined,
      }
    })
}

// ─── Component ────────────────────────────────────────────────

export default function MaintenancePage() {
  const printersList   = usePrinterStore(selectPrintersArray)
  const [tasks, setTasks] = useState<MaintenanceTask[]>([])
  const [filter, setFilter] = useState<string>('all')
  const [selectedPrinter, setSelectedPrinter] = useState<string>('all')
  const [expandedTask, setExpandedTask] = useState<string | null>(null)
  const [loading, setLoading] = useState(false)
  const [fetchError, setFetchError] = useState<string | null>(null)
  const [activeTab, setActiveTab] = useState<TabView>('tasks')
  const [markingId, setMarkingId] = useState<string | null>(null)

  // ── Fetch predictions whenever we switch to Tasks tab or printers change ──
  const fetchTasks = useCallback(async () => {
    if (printersList.length === 0) {
      setTasks([])
      setLoading(false)
      return
    }

    setLoading(true)
    setFetchError(null)

    const targets = selectedPrinter === 'all'
      ? printersList
      : printersList.filter(p => p.id === selectedPrinter)

    try {
      const results = await Promise.allSettled(
        targets.map(printer =>
          aiApi.getMaintenancePredictions(printer.id).then(res => ({ printer, res }))
        )
      )

      const allTasks: MaintenanceTask[] = []
      for (const r of results) {
        if (r.status === 'rejected') continue
        const { printer, res } = r.value
        // api.get unwraps the { success, data } envelope — res IS the payload
        const pred = res as unknown as MaintenancePredData
        if (!pred?.componentHealth?.length) continue
        allTasks.push(...predictionToTasks(printer.id, printer.name, pred))
      }

      setTasks(allTasks)
    } catch (err) {
      setFetchError(err instanceof Error ? err.message : 'Failed to load maintenance data')
    } finally {
      setLoading(false)
    }
  }, [printersList, selectedPrinter])

  useEffect(() => {
    if (activeTab === 'tasks') {
      fetchTasks()
    }
  }, [activeTab, fetchTasks])

  // ── Filtered view ──────────────────────────────────────────────────────────
  const filteredTasks = useMemo(() => {
    let result = tasks
    if (selectedPrinter !== 'all') result = result.filter(t => t.printerId === selectedPrinter)
    if (filter !== 'all')          result = result.filter(t => t.status === filter)
    return result
  }, [tasks, filter, selectedPrinter])

  const stats = useMemo(() => {
    const scope = selectedPrinter === 'all' ? tasks : tasks.filter(t => t.printerId === selectedPrinter)
    return {
      total:     scope.length,
      overdue:   scope.filter(t => t.status === 'overdue').length,
      due:       scope.filter(t => t.status === 'due').length,
      pending:   scope.filter(t => t.status === 'pending').length,
      completed: scope.filter(t => t.status === 'completed').length,
    }
  }, [tasks, selectedPrinter])

  // ── Mark task complete via AI maintenance API ──────────────────────────────
  const markComplete = useCallback(async (task: MaintenanceTask) => {
    setMarkingId(task.id)
    try {
      await aiApi.recordMaintenance(task.printerId, {
        type:        componentToMaintenanceType(task.componentKey),
        description: `${task.task} — marked complete via Maintenance page`,
      })
      // Optimistic update: flip status locally, then re-fetch in background
      setTasks(prev =>
        prev.map(t =>
          t.id === task.id
            ? { ...t, status: 'completed' as const, lastCompleted: new Date().toISOString() }
            : t
        )
      )
      // Background refresh to get updated predictions from backend
      fetchTasks()
    } catch {
      // Non-fatal — optimistic update is already applied, user can retry
    } finally {
      setMarkingId(null)
    }
  }, [fetchTasks])

  const formatDate = (iso?: string) => {
    if (!iso) return '—'
    return new Date(iso).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
  }

  const statusColor = (s: string) => {
    switch (s) {
      case 'overdue':   return 'var(--color-error)'
      case 'due':       return 'var(--color-warning)'
      case 'pending':   return 'var(--color-info)'
      case 'completed': return 'var(--color-success)'
      default:          return 'var(--color-text-muted)'
    }
  }

  // ── Render ─────────────────────────────────────────────────────────────────

  return (
    <div className="p-6 space-y-4">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-display font-bold text-text flex items-center gap-3">
            <Wrench className="w-7 h-7 text-secondary" />
            Maintenance
          </h1>
          <p className="text-sm text-text-muted mt-1">Track and register printer maintenance</p>
        </div>
      </div>

      {/* ═══ TABS: Tasks / Register Change / History ═══ */}
      <div className="flex gap-1 p-1 bg-surface rounded-lg border border-border">
        {([
          { id: 'tasks',    icon: <Wrench className="w-3.5 h-3.5" />,        label: 'Tasks'          },
          { id: 'register', icon: <Plus className="w-3.5 h-3.5" />,          label: 'Register Change'},
          { id: 'history',  icon: <HistoryIcon className="w-3.5 h-3.5" />,   label: 'Change History' },
        ] as const).map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id)}
            className={`flex items-center gap-1.5 flex-1 px-3 py-2.5 rounded-md text-sm font-medium transition-all ${
              activeTab === tab.id ? 'bg-primary/10 text-primary' : 'text-text-muted hover:text-text'
            }`}
          >
            {tab.icon} {tab.label}
          </button>
        ))}
      </div>

      {/* ═══ TAB: Register Manual Change ═══ */}
      {activeTab === 'register' && (
        <ManualChangeForm
          printerId={selectedPrinter !== 'all' ? selectedPrinter : printersList[0]?.id}
          printerName={
            selectedPrinter !== 'all'
              ? printersList.find(p => p.id === selectedPrinter)?.name
              : printersList[0]?.name
          }
          onSuccess={() => setActiveTab('history')}
        />
      )}

      {/* ═══ TAB: Change History ═══ */}
      {activeTab === 'history' && (
        <MaintenanceHistory
          printerId={selectedPrinter !== 'all' ? selectedPrinter : undefined}
        />
      )}

      {/* ═══ TAB: Maintenance Tasks (AI Predictions) ═══ */}
      {activeTab === 'tasks' && (
        <div className="space-y-4">
          {/* Printer Selector */}
          <PrinterSelectorBar
            printers={printersList}
            selected={selectedPrinter}
            onSelect={(id) => { setSelectedPrinter(id); setFilter('all') }}
            showAll
          />

          {/* Error banner */}
          {fetchError && (
            <div className="flex items-center gap-3 px-4 py-3 rounded-lg bg-red-500/10 border border-red-500/30 text-red-400 text-sm">
              <AlertTriangle className="w-4 h-4 shrink-0" />
              <span>{fetchError}</span>
              <button
                onClick={fetchTasks}
                className="ml-auto flex items-center gap-1.5 px-2 py-1 rounded bg-red-500/20 hover:bg-red-500/30 transition-colors text-xs"
              >
                <RefreshCw className="w-3 h-3" /> Retry
              </button>
            </div>
          )}

          {/* Stats */}
          {!loading && !fetchError && tasks.length > 0 && (
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
              {[
                { label: 'Overdue',   value: stats.overdue,   color: 'var(--color-error)'   },
                { label: 'Due Soon',  value: stats.due,       color: 'var(--color-warning)'  },
                { label: 'Upcoming',  value: stats.pending,   color: 'var(--color-info)'     },
                { label: 'Completed', value: stats.completed, color: 'var(--color-success)'  },
              ].map(s => (
                <div key={s.label} className="p-3 rounded-lg border border-border bg-surface text-center">
                  <div className="text-2xl font-bold" style={{ color: s.color }}>{s.value}</div>
                  <div className="text-xs text-text-muted mt-1">{s.label}</div>
                </div>
              ))}
            </div>
          )}

          {/* Status filter */}
          {!loading && !fetchError && tasks.length > 0 && (
            <div className="flex gap-1 p-1 bg-surface rounded-lg border border-border">
              {(['all', 'overdue', 'due', 'pending', 'completed'] as const).map(f => (
                <button
                  key={f}
                  onClick={() => setFilter(f)}
                  className={`flex-1 px-3 py-2 rounded-md text-xs font-medium transition-all capitalize ${
                    filter === f ? 'bg-primary/10 text-primary' : 'text-text-muted hover:text-text'
                  }`}
                >
                  {f === 'all' ? 'All' : f}
                </button>
              ))}
            </div>
          )}

          {/* ── Content states ── */}

          {/* Loading */}
          {loading && (
            <div className="flex items-center justify-center py-16">
              <div className="w-8 h-8 border-2 border-primary border-t-transparent rounded-full animate-spin" />
            </div>
          )}

          {/* No printers */}
          {!loading && !fetchError && printersList.length === 0 && (
            <div className="text-center py-16 text-text-muted">
              <Wrench className="w-12 h-12 mx-auto mb-3 opacity-30" />
              <p className="font-medium">No printers added</p>
              <p className="text-sm mt-1">Add a printer to track maintenance tasks</p>
            </div>
          )}

          {/* AI analysis not run yet (empty predictions) */}
          {!loading && !fetchError && printersList.length > 0 && tasks.length === 0 && (
            <div className="text-center py-16 text-text-muted">
              <FlaskConical className="w-12 h-12 mx-auto mb-3 opacity-30" />
              <p className="font-medium text-text">No maintenance data yet</p>
              <p className="text-sm mt-1 max-w-xs mx-auto">
                Maintenance tasks are generated from AI analysis. Connect your printer and
                let the AI collect some telemetry, then come back here.
              </p>
              <button
                onClick={fetchTasks}
                className="mt-4 inline-flex items-center gap-1.5 px-3 py-1.5 rounded-md text-sm bg-primary/10 text-primary border border-primary/20 hover:bg-primary/20 transition-colors"
              >
                <RefreshCw className="w-3.5 h-3.5" /> Refresh
              </button>
            </div>
          )}

          {/* Empty filter result */}
          {!loading && !fetchError && tasks.length > 0 && filteredTasks.length === 0 && (
            <div className="text-center py-16 text-text-muted">
              <CheckCircle2 className="w-12 h-12 mx-auto mb-3 opacity-30" />
              <p>No tasks match this filter</p>
            </div>
          )}

          {/* Task list */}
          {!loading && !fetchError && filteredTasks.length > 0 && (
            <div className="space-y-2">
              {filteredTasks.map(task => {
                const isExpanded = expandedTask === task.id
                const color      = statusColor(task.status)
                const isMarking  = markingId === task.id

                return (
                  <div key={task.id} className="rounded-lg border border-border bg-surface overflow-hidden">
                    <button
                      onClick={() => setExpandedTask(isExpanded ? null : task.id)}
                      className="w-full flex items-center gap-3 px-4 py-3 text-left hover:bg-surface-elevated transition-colors"
                    >
                      <div className="text-text-muted">
                        {CATEGORY_ICONS[task.category] ?? <Wrench className="w-4 h-4" />}
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="text-sm font-medium text-text truncate">{task.task}</div>
                        <div className="text-xs text-text-muted">{task.printerName} · {task.interval}</div>
                      </div>
                      <span
                        className="px-2 py-0.5 rounded-full text-xs font-medium capitalize"
                        style={{
                          backgroundColor: `color-mix(in srgb, ${color} 15%, transparent)`,
                          color,
                          border: `1px solid color-mix(in srgb, ${color} 25%, transparent)`,
                        }}
                      >
                        {task.status}
                      </span>
                      {isExpanded
                        ? <ChevronUp   className="w-4 h-4 text-text-muted" />
                        : <ChevronDown className="w-4 h-4 text-text-muted" />
                      }
                    </button>

                    {isExpanded && (
                      <div className="px-4 pb-4 pt-1 border-t border-border space-y-3">
                        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 text-sm">
                          <div>
                            <div className="text-xs text-text-muted">Category</div>
                            <div className="text-text capitalize">{task.category}</div>
                          </div>
                          <div>
                            <div className="text-xs text-text-muted">Until next</div>
                            <div className="text-text">{task.interval}</div>
                          </div>
                          <div>
                            <div className="text-xs text-text-muted">Last done</div>
                            <div className="text-text">{formatDate(task.lastCompleted)}</div>
                          </div>
                          <div>
                            <div className="text-xs text-text-muted">Next due</div>
                            <div className="text-text">{formatDate(task.nextDue)}</div>
                          </div>
                        </div>

                        {task.status !== 'completed' && (
                          <button
                            onClick={e => { e.stopPropagation(); markComplete(task) }}
                            disabled={isMarking}
                            className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium rounded-md bg-green-400/10 text-green-400 border border-green-400/30 hover:bg-green-400/20 transition-all disabled:opacity-50"
                          >
                            {isMarking
                              ? <><div className="w-3 h-3 border border-green-400 border-t-transparent rounded-full animate-spin" /> Saving…</>
                              : <><CheckCircle2 className="w-3.5 h-3.5" /> Mark Complete</>
                            }
                          </button>
                        )}
                      </div>
                    )}
                  </div>
                )
              })}
            </div>
          )}
        </div>
      )}
    </div>
  )
}
