export function getChangeTypesByCategory(category: ChangeCategory): ChangeTypeDefinition[] {
  return CHANGE_TYPES.filter(ct => ct.category === category)
}

export function getChangeTypeDefinition(type: string): ChangeTypeDefinition | undefined {
  return CHANGE_TYPES.find(ct => ct.type === type)
}
