// ═══════════════════════════════════════════════════════════════
// JSZIP LOADER (lazy — only when 3MF files are opened)
// ═══════════════════════════════════════════════════════════════

let JSZipLoaded = false

async function loadJSZip(): Promise<void> {
  if (JSZipLoaded || (window as any).JSZip) {
    JSZipLoaded = true
    return
  }
  
  return new Promise((resolve, reject) => {
    const script = document.createElement('script')
    script.src = 'https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js'
    script.onload = () => {
      JSZipLoaded = true
      resolve()
    }
    script.onerror = () => reject(new Error('Failed to load JSZip'))
    document.head.appendChild(script)
  })
}

// ═══════════════════════════════════════════════════════════════
// G-CODE PARSER
// ═══════════════════════════════════════════════════════════════

function parseGCode(text: string): { moves: GCodeMove[]; buildPlate: BuildPlate } {
  const moves: GCodeMove[] = []
  let cx = 0, cy = 0, cz = 0, cf = 1500, ce = 0
  let layer = 0, featureType = 'Perimeter', relative = false, relativeE = false
  
  let buildPlate: BuildPlate = { width: 220, depth: 220, height: 250 }
  
  const firstLines = text.split('\n').slice(0, 50).join('\n')
  
  const volumeMatch = firstLines.match(/printer_model = ([^;\n]+)/i) ||
                      firstLines.match(/machine_name = ([^;\n]+)/i)
  
  const widthMatch = firstLines.match(/machine_width|bed_size_x|print_bed_x.*?(\d+)/i)
  const depthMatch = firstLines.match(/machine_depth|bed_size_y|print_bed_y.*?(\d+)/i)
  
  if (widthMatch) buildPlate.width = parseInt(widthMatch[1])
  if (depthMatch) buildPlate.depth = parseInt(depthMatch[1])
  
  if (volumeMatch) {
    const model = volumeMatch[1].toLowerCase()
    if (model.includes('ender 3')) buildPlate = { width: 220, depth: 220, height: 250 }
    else if (model.includes('bambu')) buildPlate = { width: 256, depth: 256, height: 256 }
  }

  for (const rawLine of text.split('\n')) {
    const line = rawLine.split(';')[0].trim()
    const comment = rawLine.includes(';') ? rawLine.split(';').slice(1).join(';').trim() : ''

    if (comment) {
      const c = comment.toUpperCase()
      if (c.includes('LAYER') || c.includes('LAYER:')) {
        const match = comment.match(/LAYER[:\s]*(\d+)/i)
        if (match) layer = parseInt(match[1])
      }
      if (c.includes('TYPE:')) {
        const typeMatch = comment.match(/TYPE:([A-Z-]+)/i)
        if (typeMatch) {
          const type = typeMatch[1].toUpperCase()
          if (type.includes('WALL')) featureType = 'Perimeter'
          else if (type.includes('FILL')) featureType = 'Infill'
          else if (type.includes('SKIN')) featureType = 'Top/Bottom'
          else if (type.includes('SUPPORT')) featureType = 'Support'
        }
      }
    }
    
    if (!line) continue
    
    const cmd = line.split(' ')[0].toUpperCase()
    if (cmd === 'G91') { relative = true; continue }
    if (cmd === 'G90') { relative = false; continue }
    if (cmd === 'M82') { relativeE = false; continue }
    if (cmd === 'M83') { relativeE = true; continue }
    if (cmd !== 'G0' && cmd !== 'G1') continue

    let nx = cx, ny = cy, nz = cz, hasE = false, ne = ce
    const parts = line.split(' ')
    
    for (const p of parts) {
      if (!p || p.length < 2) continue
      const ch = p[0].toUpperCase()
      const val = parseFloat(p.slice(1))
      if (isNaN(val)) continue
      
      if (ch === 'X') nx = relative ? cx + val : val
      else if (ch === 'Y') ny = relative ? cy + val : val
      else if (ch === 'Z') nz = relative ? cz + val : val
      else if (ch === 'E') {
        ne = relativeE ? ce + val : val
        hasE = ne > ce
      }
      else if (ch === 'F') cf = val
    }
    
    if (Math.abs(nx - cx) > 0.001 || Math.abs(ny - cy) > 0.001 || Math.abs(nz - cz) > 0.001) {
      moves.push({ 
        x: nx, y: ny, z: nz, 
        extrude: hasE && cmd === 'G1', 
        speed: cf, 
        layer: Math.max(0, layer), 
        featureType 
      })
      cx = nx; cy = ny; cz = nz; ce = ne
    }
  }
  
  console.log(`✓ Parsed ${moves.length} moves, ${layer} layers`)
  return { moves, buildPlate }
}

// ═══════════════════════════════════════════════════════════════
// 3D MODEL PARSERS
// ═══════════════════════════════════════════════════════════════

async function parseSTL(file: File): Promise<MeshData> {
  const buffer = await file.arrayBuffer()
  const view = new DataView(buffer)
  const header = new TextDecoder().decode(buffer.slice(0, 5))
  if (header === 'solid') return parseSTLAscii(await file.text())
  else return parseSTLBinary(view)
}

function parseSTLBinary(view: DataView): MeshData {
  const triangles: Triangle[] = []
  const numTriangles = view.getUint32(80, true)
  let offset = 84
  for (let i = 0; i < numTriangles; i++) {
    const normal: Vec3 = [view.getFloat32(offset, true), view.getFloat32(offset + 4, true), view.getFloat32(offset + 8, true)]
    offset += 12
    const v1: Vec3 = [view.getFloat32(offset, true), view.getFloat32(offset + 4, true), view.getFloat32(offset + 8, true)]
    offset += 12
    const v2: Vec3 = [view.getFloat32(offset, true), view.getFloat32(offset + 4, true), view.getFloat32(offset + 8, true)]
    offset += 12
    const v3: Vec3 = [view.getFloat32(offset, true), view.getFloat32(offset + 4, true), view.getFloat32(offset + 8, true)]
    offset += 14
    triangles.push({ v1, v2, v3, normal })
  }
  return { triangles, bounds: calculateBounds(triangles) }
}

function parseSTLAscii(text: string): MeshData {
  const triangles: Triangle[] = []
  const lines = text.split('\n')
  let i = 0
  while (i < lines.length) {
    const line = lines[i].trim()
    if (line.startsWith('facet normal')) {
      const normalMatch = line.match(/facet normal\s+([-\d.e]+)\s+([-\d.e]+)\s+([-\d.e]+)/)
      const normal: Vec3 = normalMatch ? [parseFloat(normalMatch[1]), parseFloat(normalMatch[2]), parseFloat(normalMatch[3])] : [0, 0, 1]
      i += 2
      const v1Match = lines[i].trim().match(/vertex\s+([-\d.e]+)\s+([-\d.e]+)\s+([-\d.e]+)/)
      i++
      const v2Match = lines[i].trim().match(/vertex\s+([-\d.e]+)\s+([-\d.e]+)\s+([-\d.e]+)/)
      i++
      const v3Match = lines[i].trim().match(/vertex\s+([-\d.e]+)\s+([-\d.e]+)\s+([-\d.e]+)/)
      if (v1Match && v2Match && v3Match) {
        const v1: Vec3 = [parseFloat(v1Match[1]), parseFloat(v1Match[2]), parseFloat(v1Match[3])]
        const v2: Vec3 = [parseFloat(v2Match[1]), parseFloat(v2Match[2]), parseFloat(v2Match[3])]
        const v3: Vec3 = [parseFloat(v3Match[1]), parseFloat(v3Match[2]), parseFloat(v3Match[3])]
        triangles.push({ v1, v2, v3, normal })
      }
    }
    i++
  }
  return { triangles, bounds: calculateBounds(triangles) }
}

async function parse3MF(file: File): Promise<MeshData> {
  await loadJSZip()
  const JSZip = (window as any).JSZip
  if (!JSZip) throw new Error('JSZip failed to load')
  
  const zip = await JSZip.loadAsync(await file.arrayBuffer())
  const modelFile = zip.file('3D/3dmodel.model')
  if (!modelFile) throw new Error('Invalid 3MF')
  const xmlText = await modelFile.async('text')
  const parser = new DOMParser()
  const xmlDoc = parser.parseFromString(xmlText, 'text/xml')
  const triangles: Triangle[] = []
  const meshes = xmlDoc.getElementsByTagName('mesh')
  
  for (let m = 0; m < meshes.length; m++) {
    const vertices: Vec3[] = []
    const vertexElements = meshes[m].getElementsByTagName('vertex')
    for (let i = 0; i < vertexElements.length; i++) {
      const v = vertexElements[i]
      vertices.push([
        parseFloat(v.getAttribute('x') || '0'), 
        parseFloat(v.getAttribute('y') || '0'), 
        parseFloat(v.getAttribute('z') || '0')
      ])
    }
    const triangleElements = meshes[m].getElementsByTagName('triangle')
    for (let i = 0; i < triangleElements.length; i++) {
      const t = triangleElements[i]
      const v1Idx = parseInt(t.getAttribute('v1') || '0')
      const v2Idx = parseInt(t.getAttribute('v2') || '0')
      const v3Idx = parseInt(t.getAttribute('v3') || '0')
      if (vertices[v1Idx] && vertices[v2Idx] && vertices[v3Idx]) {
        const v1 = vertices[v1Idx], v2 = vertices[v2Idx], v3 = vertices[v3Idx]
        triangles.push({ v1, v2, v3, normal: calculateNormal(v1, v2, v3) })
      }
    }
  }
  return { triangles, bounds: calculateBounds(triangles) }
}

async function parseOBJ(file: File): Promise<MeshData> {
  const text = await file.text()
  const lines = text.split('\n')
  const vertices: Vec3[] = []
  const triangles: Triangle[] = []
  for (const line of lines) {
    const parts = line.trim().split(/\s+/)
    if (parts[0] === 'v') {
      vertices.push([parseFloat(parts[1]), parseFloat(parts[2]), parseFloat(parts[3])])
    } else if (parts[0] === 'f') {
      const indices = parts.slice(1).map(p => parseInt(p.split('/')[0]) - 1)
      for (let i = 1; i < indices.length - 1; i++) {
        const v1 = vertices[indices[0]], v2 = vertices[indices[i]], v3 = vertices[indices[i + 1]]
        if (v1 && v2 && v3) triangles.push({ v1, v2, v3, normal: calculateNormal(v1, v2, v3) })
      }
    }
  }
  return { triangles, bounds: calculateBounds(triangles) }
}

async function parsePLY(file: File): Promise<MeshData> {
  const text = await file.text()
  const lines = text.split('\n')
  let vertexCount = 0, faceCount = 0, headerEnd = 0
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line.startsWith('element vertex')) vertexCount = parseInt(line.split(' ')[2])
    else if (line.startsWith('element face')) faceCount = parseInt(line.split(' ')[2])
    else if (line === 'end_header') { headerEnd = i + 1; break }
  }
  const vertices: Vec3[] = []
  const triangles: Triangle[] = []
  for (let i = 0; i < vertexCount; i++) {
    const parts = lines[headerEnd + i].trim().split(/\s+/)
    vertices.push([parseFloat(parts[0]), parseFloat(parts[1]), parseFloat(parts[2])])
  }
  for (let i = 0; i < faceCount; i++) {
    const parts = lines[headerEnd + vertexCount + i].trim().split(/\s+/)
    const numVerts = parseInt(parts[0])
    const indices = parts.slice(1, numVerts + 1).map(p => parseInt(p))
    for (let j = 1; j < indices.length - 1; j++) {
      const v1 = vertices[indices[0]], v2 = vertices[indices[j]], v3 = vertices[indices[j + 1]]
      if (v1 && v2 && v3) triangles.push({ v1, v2, v3, normal: calculateNormal(v1, v2, v3) })
    }
  }
  return { triangles, bounds: calculateBounds(triangles) }
}

function calculateNormal(v1: Vec3, v2: Vec3, v3: Vec3): Vec3 {
  const u: Vec3 = [v2[0] - v1[0], v2[1] - v1[1], v2[2] - v1[2]]
  const v: Vec3 = [v3[0] - v1[0], v3[1] - v1[1], v3[2] - v1[2]]
  const n: Vec3 = [u[1] * v[2] - u[2] * v[1], u[2] * v[0] - u[0] * v[2], u[0] * v[1] - u[1] * v[0]]
  const len = Math.sqrt(n[0] * n[0] + n[1] * n[1] + n[2] * n[2])
  return len > 0 ? [n[0] / len, n[1] / len, n[2] / len] : [0, 0, 1]
}

function calculateBounds(triangles: Triangle[]): { min: Vec3; max: Vec3 } {
  if (triangles.length === 0) return { min: [0, 0, 0], max: [0, 0, 0] }
  let minX = Infinity, minY = Infinity, minZ = Infinity
  let maxX = -Infinity, maxY = -Infinity, maxZ = -Infinity
  for (const t of triangles) {
    for (const v of [t.v1, t.v2, t.v3]) {
      minX = Math.min(minX, v[0]); minY = Math.min(minY, v[1]); minZ = Math.min(minZ, v[2])
      maxX = Math.max(maxX, v[0]); maxY = Math.max(maxY, v[1]); maxZ = Math.max(maxZ, v[2])
    }
  }
  return { min: [minX, minY, minZ], max: [maxX, maxY, maxZ] }
}

