import type { WebSocketMessage, WebSocketEventType } from '../core/types/websocket'

/**
 * WebSocket configuration
 */
/**
 * Derive WebSocket URL from current page origin so the connection
 * goes through the Vite proxy (/ws → ws://localhost:3002) instead
 * of trying to reach localhost:3002 directly from the browser.
 * Falls back to VITE_WS_URL only if explicitly set.
 */
function getWsUrl(): string {
  if (import.meta.env.VITE_WS_URL) return import.meta.env.VITE_WS_URL
  const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:'
  return `${protocol}//${window.location.host}/ws`
}

const WS_CONFIG = {
  url: getWsUrl(),
  reconnectInterval: 5000,
  maxReconnectAttempts: 20,
  heartbeatInterval: 30000,
}

/**
 * WebSocket connection state
 */
export type ConnectionState = 'connecting' | 'connected' | 'disconnected' | 'error' | 'reconnecting'

/**
 * Message handler function
 */
export type MessageHandler = (message: WebSocketMessage) => void

/**
 * Connection state handler
 */
export type StateHandler = (state: ConnectionState) => void

/**
 * WebSocket Service
 * Manages WebSocket connection with auto-reconnect
 */
class WebSocketService {
  private ws: WebSocket | null = null
  private connectionState: ConnectionState = 'disconnected'
  private reconnectAttempts = 0
  private reconnectTimer: NodeJS.Timeout | null = null
  private heartbeatTimer: NodeJS.Timeout | null = null
  private messageHandlers: Map<WebSocketEventType | '*', Set<MessageHandler>> = new Map()
  private stateHandlers: Set<StateHandler> = new Set()

  /**
   * Connect to WebSocket server
   */
  connect(): void {
    if (this.ws?.readyState === WebSocket.OPEN) {
      console.warn('WebSocket already connected')
      return
    }

    this.setConnectionState('connecting')

    try {
      this.ws = new WebSocket(WS_CONFIG.url)

      this.ws.onopen = () => {
        console.log('WebSocket connected')
        this.setConnectionState('connected')
        this.reconnectAttempts = 0
        this.startHeartbeat()
      }

      this.ws.onmessage = (event) => {
        try {
          const message = JSON.parse(event.data) as WebSocketMessage
          this.handleMessage(message)
        } catch (error) {
          console.error('Failed to parse WebSocket message:', error)
        }
      }

      this.ws.onerror = (error) => {
        console.error('WebSocket error:', error)
        this.setConnectionState('error')
      }

      this.ws.onclose = (event) => {
        console.log('WebSocket closed:', event.code, event.reason)
        this.stopHeartbeat()
        this.setConnectionState('disconnected')

        // Auto-reconnect if not closed intentionally
        if (event.code !== 1000 && this.reconnectAttempts < WS_CONFIG.maxReconnectAttempts) {
          this.scheduleReconnect()
        }
      }
    } catch (error) {
      console.error('Failed to create WebSocket connection:', error)
      this.setConnectionState('error')
      this.scheduleReconnect()
    }
  }

  /**
   * Disconnect from WebSocket server
   */
  disconnect(): void {
    if (this.reconnectTimer) {
      clearTimeout(this.reconnectTimer)
      this.reconnectTimer = null
    }

    this.stopHeartbeat()

    if (this.ws) {
      // Close with code 1000 (normal closure) to prevent auto-reconnect
      this.ws.close(1000, 'Client disconnect')
      this.ws = null
    }

    this.setConnectionState('disconnected')
    this.reconnectAttempts = 0
  }

  /**
   * Send message to server
   */
  send(message: Partial<WebSocketMessage>): void {
    if (this.ws?.readyState !== WebSocket.OPEN) {
      console.warn('WebSocket not connected, cannot send message')
      return
    }

    const fullMessage: WebSocketMessage = {
      type: message.type || 'ping',
      data: message.data,
      timestamp: message.timestamp || new Date().toISOString(),
    }

    this.ws.send(JSON.stringify(fullMessage))
  }

  /**
   * Subscribe to messages of specific type
   */
  subscribe(eventType: WebSocketEventType | '*', handler: MessageHandler): () => void {
    if (!this.messageHandlers.has(eventType)) {
      this.messageHandlers.set(eventType, new Set())
    }

    this.messageHandlers.get(eventType)!.add(handler)

    // Return unsubscribe function
    return () => {
      this.messageHandlers.get(eventType)?.delete(handler)
    }
  }

  /**
   * Subscribe to connection state changes
   */
  onStateChange(handler: StateHandler): () => void {
    this.stateHandlers.add(handler)

    // Immediately call with current state
    handler(this.connectionState)

    // Return unsubscribe function
    return () => {
      this.stateHandlers.delete(handler)
    }
  }

  /**
   * Get current connection state
   */
  getState(): ConnectionState {
    return this.connectionState
  }

  /**
   * Check if connected
   */
  isConnected(): boolean {
    return this.ws?.readyState === WebSocket.OPEN
  }

  /**
   * Handle incoming message
   */
  private handleMessage(message: WebSocketMessage): void {
    // Call wildcard handlers
    this.messageHandlers.get('*')?.forEach((handler) => {
      try {
        handler(message)
      } catch (error) {
        console.error('Error in wildcard message handler:', error)
      }
    })

    // Call type-specific handlers
    this.messageHandlers.get(message.type)?.forEach((handler) => {
      try {
        handler(message)
      } catch (error) {
        console.error(`Error in ${message.type} message handler:`, error)
      }
    })
  }

  /**
   * Set connection state and notify handlers
   */
  private setConnectionState(state: ConnectionState): void {
    if (this.connectionState === state) return

    this.connectionState = state

    this.stateHandlers.forEach((handler) => {
      try {
        handler(state)
      } catch (error) {
        console.error('Error in state change handler:', error)
      }
    })
  }

  /**
   * Schedule reconnect attempt
   */
  private scheduleReconnect(): void {
    if (this.reconnectTimer) return

    this.reconnectAttempts++
    this.setConnectionState('reconnecting')

    const delay = WS_CONFIG.reconnectInterval * Math.min(this.reconnectAttempts, 5)

    console.log(`Reconnecting in ${delay}ms (attempt ${this.reconnectAttempts}/${WS_CONFIG.maxReconnectAttempts})`)

    this.reconnectTimer = setTimeout(() => {
      this.reconnectTimer = null
      this.connect()
    }, delay)
  }

  /**
   * Start heartbeat to keep connection alive
   */
  private startHeartbeat(): void {
    this.stopHeartbeat()

    this.heartbeatTimer = setInterval(() => {
      if (this.isConnected()) {
        this.send({ type: 'ping' })
      }
    }, WS_CONFIG.heartbeatInterval)
  }

  /**
   * Stop heartbeat
   */
  private stopHeartbeat(): void {
    if (this.heartbeatTimer) {
      clearInterval(this.heartbeatTimer)
      this.heartbeatTimer = null
    }
  }
}

// Create singleton instance
export const websocketService = new WebSocketService()

// Auto-connect on module load (can be disabled if needed)
if (typeof window !== 'undefined') {
  websocketService.connect()
}

export default websocketService
