// ═══════════════════════════════════════════════════════════════
// PRESTIGE DASHBOARD - AI SETTINGS
// ═══════════════════════════════════════════════════════════════

import React from 'react'
import { useAIStore, selectAISettings, selectAIEnabled, selectAutonomyLevel } from '@core/state'
import { Brain, Zap, Settings } from 'lucide-react'
import { SettingsSection } from './SettingsSection'

export interface AISettingsProps {
  className?: string
}

export const AISettings: React.FC<AISettingsProps> = ({ className = '' }) => {
  const aiEnabled = useAIStore(selectAIEnabled)
  const autonomyLevel = useAIStore(selectAutonomyLevel)
  const settings = useAIStore(selectAISettings)
  const { toggleAI, setAutonomyLevel, updateAISettings } = useAIStore()

  return (
    <SettingsSection
      title="AI Configuration"
      description="Configure AI behavior and autonomy settings"
      icon={<Brain className="w-5 h-5" />}
      className={className}
    >
      <div className="space-y-6">
        {/* AI Enable/Disable */}
        <div className="flex items-center justify-between">
          <div>
            <h4 className="text-sm font-medium text-gray-200">Enable AI</h4>
            <p className="text-xs text-gray-400">Activate AI monitoring and recommendations</p>
          </div>
          <button
            onClick={toggleAI}
            className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${
              aiEnabled ? 'bg-cyan-500' : 'bg-gray-600'
            }`}
          >
            <span
              className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${
                aiEnabled ? 'translate-x-6' : 'translate-x-1'
              }`}
            />
          </button>
        </div>

        {/* Autonomy Level */}
        {aiEnabled && (
          <>
            <div>
              <h4 className="text-sm font-medium text-gray-200 mb-2">Autonomy Level</h4>
              <div className="grid grid-cols-3 gap-2">
                {(['L0', 'L1', 'L2'] as const).map(
                  (level) => (
                    <button
                      key={level}
                      onClick={() => setAutonomyLevel(level)}
                      className={`px-3 py-2 rounded-lg text-sm font-medium transition-all ${
                        autonomyLevel === level
                          ? 'bg-cyan-500/20 text-cyan-400 border border-cyan-500/50'
                          : 'bg-gray-800/50 text-gray-400 border border-gray-700 hover:border-cyan-500/30'
                      }`}
                    >
                      {level === 'L0' ? 'Monitoring' : level === 'L1' ? 'Advisory' : 'Semi-Auto'}
                    </button>
                  )
                )}
              </div>
            </div>

            {/* Additional Settings */}
            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <div>
                  <h4 className="text-sm font-medium text-gray-200">Auto-accept Recommendations</h4>
                  <p className="text-xs text-gray-400">Automatically apply low-risk suggestions</p>
                </div>
                <button
                  onClick={() =>
                    updateAISettings({
                      autoAcceptRecommendations: !settings.autoAcceptRecommendations,
                    })
                  }
                  className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${
                    settings.autoAcceptRecommendations ? 'bg-cyan-500' : 'bg-gray-600'
                  }`}
                >
                  <span
                    className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${
                      settings.autoAcceptRecommendations ? 'translate-x-6' : 'translate-x-1'
                    }`}
                  />
                </button>
              </div>

              <div className="flex items-center justify-between">
                <div>
                  <h4 className="text-sm font-medium text-gray-200">Predictive Alerts</h4>
                  <p className="text-xs text-gray-400">Show predictions before issues occur</p>
                </div>
                <button
                  onClick={() =>
                    updateAISettings({
                      predictiveAlerts: !settings.predictiveAlerts,
                    })
                  }
                  className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${
                    settings.predictiveAlerts ? 'bg-cyan-500' : 'bg-gray-600'
                  }`}
                >
                  <span
                    className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${
                      settings.predictiveAlerts ? 'translate-x-6' : 'translate-x-1'
                    }`}
                  />
                </button>
              </div>
            </div>
          </>
        )}
      </div>
    </SettingsSection>
  )
}

export default AISettings
