// ═══════════════════════════════════════════════════════════════
// PRESTIGE DASHBOARD - useAIStatus Hook
// ═══════════════════════════════════════════════════════════════
//
// FIX: Module-level guard prevents StrictMode's triple effect-
//      invocation from firing multiple concurrent fetch chains.
//      Retry logic removed — backend-down errors are not transient.

import { useEffect, useRef, useState } from 'react'
import { useAIStore, selectAIEnabled, selectAIStatus } from '@core/state/aiStore'
import { aiApi } from '@/services/ai-api'
import type { AIStatusResponse } from '@/services/ai-api'

// Module-level guard — see usePrintersFetch.ts for full explanation.
let _aiFetchOwned = false

/**
 * Hook to fetch and manage AI status.
 *
 * Single source of truth: AIStore.
 * BackendAIStatus fields are mapped into AIStore via updateAIStatus()
 * so every consumer reads from one place — no local/store desync.
 */
export function useAIStatus() {
  const aiEnabled  = useAIStore(selectAIEnabled)
  const aiStatus   = useAIStore(selectAIStatus)
  const { updateAIStatus, setAIEnabled } = useAIStore()

  const [isLoading, setIsLoading] = useState(true)
  const [error, setError]         = useState<Error | null>(null)
  const _isRefreshing              = useRef(false)

  // ── Map BackendAIStatus → AIStore (single write path) ────────
  const applyToStore = (data: AIStatusResponse) => {
    setAIEnabled(data.enabled)
    updateAIStatus({
      enabled:            data.enabled,
      status:             data.healthy ? 'operational' : 'offline',
      activeAnalyses:     data.activePrinters,
      printersMonitored:  data.activePrinters,
      anomaliesDetected:  data.activeAnomalies,
      stats: {
        totalRecommendations:   data.pendingRecommendations,
        pendingRecommendations: data.pendingRecommendations,
        approvedToday:          0,
        rejectedToday:          0,
        autoExecutedToday:      0,
      },
    })
  }

  // ── Fetch on mount ────────────────────────────────────────────
  useEffect(() => {
    // If another instance already owns the fetch (StrictMode double-mount),
    // resolve loading immediately so the app doesn't hang on the spinner.
    if (_aiFetchOwned) {
      setIsLoading(false)
      return
    }
    _aiFetchOwned = true

    let mounted = true

    const timeoutId = setTimeout(() => {
      if (mounted) {
        console.warn('AI status fetch timed out after 5s')
        setIsLoading(false)
        setError(new Error('AI status fetch timed out'))
        updateAIStatus({ status: 'offline' })
      }
    }, 5000)

    const fetchStatus = async () => {
      try {
        setIsLoading(true)
        setError(null)

        const data = await aiApi.getStatus()

        if (mounted) {
          clearTimeout(timeoutId)
          applyToStore(data)
        }
      } catch (err) {
        if (mounted) {
          clearTimeout(timeoutId)
          const error = err instanceof Error ? err : new Error('Failed to fetch AI status')
          setError(error)
          console.error('Failed to fetch AI status:', error)
          updateAIStatus({ status: 'offline' })
          console.warn('AI status: backend unavailable — use the refresh button to retry')
        }
      } finally {
        if (mounted) {
          setIsLoading(false)
        }
      }
    }

    fetchStatus()

    return () => {
      mounted = false
      clearTimeout(timeoutId)
      // Intentionally NOT releasing _aiFetchOwned — see usePrintersFetch.ts
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  // ── Refresh ───────────────────────────────────────────────────
  const refresh = async () => {
    if (_isRefreshing.current) return
    _isRefreshing.current = true
    _aiFetchOwned = false
    try {
      setIsLoading(true)
      setError(null)

      const data = await aiApi.getStatus()
      applyToStore(data)
    } catch (err) {
      const error = err instanceof Error ? err : new Error('Failed to refresh AI status')
      setError(error)
      console.error('Failed to refresh AI status:', error)
      updateAIStatus({ status: 'offline' })
    } finally {
      setIsLoading(false)
      _aiFetchOwned = true
      _isRefreshing.current = false
    }
  }

  return {
    aiEnabled,
    aiStatus,
    isLoading,
    error,
    refresh,
  }
}

export default useAIStatus
