const SUPABASE_URL     = (import.meta.env.VITE_SUPABASE_URL     as string) ?? ''
const SUPABASE_ANON_KEY = (import.meta.env.VITE_SUPABASE_ANON_KEY as string) ?? ''

// ─── Types (mirrors prestige-backend/src/auth/types.ts) ──────

export type SubscriptionStatus = 'active' | 'expired' | 'cancelled' | 'trial'
export type SubscriptionPlan   = 'starter' | 'professional' | 'enterprise'

export interface SupabaseUser {
  id: string
  email?: string
  created_at?: string
  user_metadata?: Record<string, unknown>
}

export interface SupabaseSession {
  access_token: string
  refresh_token: string
  token_type: string
  expires_in: number
  expires_at?: number
  user: SupabaseUser
}

export interface SupabaseAuthResponse {
  data: { user: SupabaseUser | null; session: SupabaseSession | null }
  error: { message: string; status?: number } | null
}

export interface Profile {
  id: string
  email: string
  full_name: string | null
  created_at: string
  updated_at: string
}

export interface HardwareBinding {
  id: string
  user_id: string
  hwid: string
  label: string | null
  bound_at: string    // matches backend: bound_at
  last_seen: string   // matches backend: last_seen
}

export interface Subscription {
  id: string
  user_id: string
  status: SubscriptionStatus
  plan: SubscriptionPlan
  valid_until: string | null
  printer_limit: number
  created_at: string
  updated_at: string
}

// ─── HTTP helpers ─────────────────────────────────────────────

function headers(token?: string): Record<string, string> {
  return {
    'Content-Type': 'application/json',
    apikey: SUPABASE_ANON_KEY,
    Authorization: `Bearer ${token || SUPABASE_ANON_KEY}`,
  }
}

async function sbPost<T>(
  path: string,
  body: unknown,
  token?: string,
): Promise<{ data: T | null; error: string | null }> {
  try {
    const res = await fetch(`${SUPABASE_URL}${path}`, {
      method: 'POST',
      headers: headers(token),
      body: JSON.stringify(body),
    })
    const json = await res.json()
    if (!res.ok) {
      return {
        data: null,
        error: json.error_description || json.msg || json.message || `HTTP ${res.status}`,
      }
    }
    return { data: json as T, error: null }
  } catch (e) {
    return { data: null, error: (e as Error).message }
  }
}

async function sbGet<T>(
  path: string,
  token: string,
  params?: string,
): Promise<{ data: T | null; error: string | null }> {
  try {
    const url = `${SUPABASE_URL}${path}${params ? `?${params}` : ''}`
    const res = await fetch(url, { headers: headers(token) })
    const json = await res.json()
    if (!res.ok) return { data: null, error: json.message || `HTTP ${res.status}` }
    return { data: json as T, error: null }
  } catch (e) {
    return { data: null, error: (e as Error).message }
  }
}

async function sbUpsert<T>(
  path: string,
  body: unknown,
  token: string,
): Promise<{ data: T | null; error: string | null }> {
  try {
    const res = await fetch(`${SUPABASE_URL}${path}`, {
      method: 'POST',
      headers: {
        ...headers(token),
        Prefer: 'resolution=merge-duplicates,return=representation',
      },
      body: JSON.stringify(body),
    })
    const json = await res.json()
    if (!res.ok) return { data: null, error: json.message || `HTTP ${res.status}` }
    const result = Array.isArray(json) ? json[0] : json
    return { data: result as T, error: null }
  } catch (e) {
    return { data: null, error: (e as Error).message }
  }
}

// ─── HWID Generation (browser fingerprint) ───────────────────
// Backend uses SHA-256 of hardware identifiers (hwid.ts).
// Frontend generates a stable browser fingerprint stored in localStorage.

export function generateHWID(): string {
  const STORAGE_KEY = 'prestige_hwid'
  const cached = localStorage.getItem(STORAGE_KEY)
  if (cached) return cached

  const components = [
    navigator.userAgent,
    navigator.language,
    `${screen.width}x${screen.height}x${screen.colorDepth}`,
    Intl.DateTimeFormat().resolvedOptions().timeZone,
    String(navigator.hardwareConcurrency ?? 0),
    // Unique random suffix per installation
    Math.random().toString(36).slice(2),
  ]

  let hash = 0
  const raw = components.join('|')
  for (let i = 0; i < raw.length; i++) {
    hash = Math.imul(31, hash) + raw.charCodeAt(i) | 0
  }

  const hwid = `WEB-${Math.abs(hash).toString(16).toUpperCase().padStart(8, '0')}-${Date.now().toString(36).toUpperCase()}`
  localStorage.setItem(STORAGE_KEY, hwid)
  return hwid
}

// ─── Auth ─────────────────────────────────────────────────────

export const supabaseAuth = {
  async signUp(
    email: string,
    password: string,
    fullName?: string,
  ): Promise<SupabaseAuthResponse> {
    const { data, error } = await sbPost<{
      user: SupabaseUser
      session: SupabaseSession | null
    }>('/auth/v1/signup', {
      email,
      password,
      data: fullName ? { full_name: fullName } : undefined,
    })
    if (error) return { data: { user: null, session: null }, error: { message: error } }
    return {
      data: { user: data?.user ?? null, session: data?.session ?? null },
      error: null,
    }
  },

  async signIn(email: string, password: string): Promise<SupabaseAuthResponse> {
    // Supabase /token endpoint returns the session fields at root level (not nested under 'session')
    const { data, error } = await sbPost<SupabaseSession & { user: SupabaseUser }>(
      '/auth/v1/token?grant_type=password',
      { email, password },
    )
    if (error) return { data: { user: null, session: null }, error: { message: error } }
    if (!data?.access_token) return { data: { user: null, session: null }, error: null }
    const session: SupabaseSession = {
      access_token:  data.access_token,
      refresh_token: data.refresh_token,
      token_type:    data.token_type,
      expires_in:    data.expires_in,
      expires_at:    data.expires_at,
      user:          data.user,
    }
    return {
      data: { user: data.user ?? null, session },
      error: null,
    }
  },

  async signOut(token: string): Promise<void> {
    await fetch(`${SUPABASE_URL}/auth/v1/logout`, {
      method: 'POST',
      headers: headers(token),
    }).catch(() => { /* ignore */ })
  },

  async refreshSession(refreshToken: string): Promise<SupabaseAuthResponse> {
    // Same as signIn — token endpoint returns session fields at root level
    const { data, error } = await sbPost<SupabaseSession & { user: SupabaseUser }>(
      '/auth/v1/token?grant_type=refresh_token',
      { refresh_token: refreshToken },
    )
    if (error) return { data: { user: null, session: null }, error: { message: error } }
    if (!data?.access_token) return { data: { user: null, session: null }, error: null }
    const session: SupabaseSession = {
      access_token:  data.access_token,
      refresh_token: data.refresh_token,
      token_type:    data.token_type,
      expires_in:    data.expires_in,
      expires_at:    data.expires_at,
      user:          data.user,
    }
    return {
      data: { user: data.user ?? null, session },
      error: null,
    }
  },
}

// ─── Database ─────────────────────────────────────────────────

export const supabaseDB = {
  async getProfile(
    userId: string,
    token: string,
  ): Promise<{ data: Profile | null; error: string | null }> {
    const { data, error } = await sbGet<Profile[]>(
      '/rest/v1/profiles',
      token,
      `id=eq.${userId}&select=*`,
    )
    return { data: Array.isArray(data) ? (data[0] ?? null) : null, error }
  },

  async upsertProfile(
    profile: Partial<Profile> & { id: string },
    token: string,
  ): Promise<{ data: Profile | null; error: string | null }> {
    return sbUpsert<Profile>('/rest/v1/profiles', profile, token)
  },

  async bindHWID(
    userId: string,
    hwid: string,
    token: string,
  ): Promise<{ data: HardwareBinding | null; error: string | null }> {
    const now = new Date().toISOString()
    // Matches backend schema: bound_at, last_seen (not first_seen_at / last_seen_at)
    return sbUpsert<HardwareBinding>(
      '/rest/v1/hardware_bindings',
      {
        user_id:   userId,
        hwid,
        label:     `Web (${navigator.platform || 'Browser'})`,
        bound_at:  now,
        last_seen: now,
      },
      token,
    )
  },

  async getSubscription(
    userId: string,
    token: string,
  ): Promise<{ data: Subscription | null; error: string | null }> {
    const { data, error } = await sbGet<Subscription[]>(
      '/rest/v1/subscriptions',
      token,
      `user_id=eq.${userId}&select=*&order=created_at.desc&limit=1`,
    )
    return { data: Array.isArray(data) ? (data[0] ?? null) : null, error }
  },
}

export default { auth: supabaseAuth, db: supabaseDB, generateHWID }
