// ═══════════════════════════════════════════════════════════════

import { useState } from 'react'
import { useTranslation } from 'react-i18next'
import { Grid3x3 } from 'lucide-react'
import { usePrinterStore, selectPrintersArray } from '@core/state/printerStore'
import { BedMeshView } from '@features/bed-mesh'
import { PrinterSelectorBar } from '@core/components/PrinterSelectorBar'

export default function BedMeshPage() {
  const { t } = useTranslation()
  const printers = usePrinterStore(selectPrintersArray)
  const [selectedId, setSelectedId] = useState<string>(printers[0]?.id ?? '')

  const printer = usePrinterStore(s => selectedId ? s.printers[selectedId] : undefined)

  return (
    <div className="p-6 space-y-6">
      <div>
        <h1 className="text-2xl font-display font-bold text-text flex items-center gap-3">
          <Grid3x3 className="w-7 h-7 text-primary" />
          {t('bedMesh.title', 'Bed Mesh')}
        </h1>
        <p className="text-sm text-text-muted mt-1">
          {t('bedMesh.subtitle', 'Visualize bed mesh leveling data for each printer')}
        </p>
      </div>

      <PrinterSelectorBar printers={printers} selected={selectedId} onSelect={setSelectedId} />

      {printers.length === 0 ? (
        <div className="text-center py-16 text-text-muted">
          <Grid3x3 className="w-12 h-12 mx-auto mb-3 opacity-30" />
          <p className="text-lg">No printers connected</p>
          <p className="text-sm mt-1">Connect a printer to view bed mesh data</p>
        </div>
      ) : selectedId ? (
        <BedMeshView printerId={selectedId} printerName={printer?.name} />
      ) : (
        <div className="text-center py-16 text-text-muted">
          <p className="text-sm">Select a printer above</p>
        </div>
      )}
    </div>
  )
}
