// ═══════════════════════════════════════════════════════════════
// PRESTIGE DASHBOARD - Printer Status Normalization
// Single source of truth for backend → frontend status mapping.
//
// Previously duplicated in three places with diverging maps:
//   printerStore.ts       — normalizeStatusValue()  (10 aliases + VALID_STATUSES set)
//   useWebSocketIntegration.tsx — normalizeStatus()  (19 entries, valid statuses inlined)
//   usePrinterUpdates.ts  — no function, raw strings used directly
//
// Strategy: VALID_STATUSES set (O(1) hit) + ALIAS_MAP for unknown strings.
// Any raw string that is already a valid PrinterStatus passes through
// unchanged. Unknown strings are mapped via ALIAS_MAP, defaulting to 'idle'.
// ═══════════════════════════════════════════════════════════════

import type { PrinterStatus } from '@core/types'

// ─────────────────────────────────────────────────────────────
// Valid frontend statuses — these pass through as-is.
// ─────────────────────────────────────────────────────────────
export const VALID_PRINTER_STATUSES = new Set<PrinterStatus>([
  'idle',
  'printing',
  'paused',
  'error',
  'disconnected',
  'maintenance',
  'ai_action',
])

// ─────────────────────────────────────────────────────────────
// Alias map — backend/Moonraker/OctoPrint strings that are NOT
// valid PrinterStatus values, mapped to the closest equivalent.
// ─────────────────────────────────────────────────────────────
const ALIAS_MAP: Record<string, PrinterStatus> = {
  // Moonraker / Klipper
  standby:   'idle',
  ready:     'idle',
  startup:   'idle',
  shutdown:  'disconnected',
  cancelled: 'idle',
  complete:  'idle',
  // OctoPrint
  operational: 'idle',
  finishing:   'printing',
  cancelling:  'idle',
  connecting:  'idle',
  offline:     'disconnected',
}

/**
 * Normalizes any backend status string to a valid PrinterStatus.
 *
 * @example
 * normalizePrinterStatus('standby')     // → 'idle'
 * normalizePrinterStatus('printing')    // → 'printing'
 * normalizePrinterStatus('operational') // → 'idle'
 * normalizePrinterStatus(undefined)     // → 'disconnected'
 * normalizePrinterStatus('unknown_val') // → 'idle'
 */
export function normalizePrinterStatus(
  raw: string | null | undefined
): PrinterStatus {
  if (!raw) return 'disconnected'
  const lower = raw.toLowerCase().trim()
  if (VALID_PRINTER_STATUSES.has(lower as PrinterStatus)) return lower as PrinterStatus
  return ALIAS_MAP[lower] ?? 'idle'
}
