// ═══════════════════════════════════════════════════════════════
// SHARED: PAGE TOAST DISPLAY
// Renders toasts returned by useToast() hook.
// Eliminates the duplicated toast block from BackupPage, PrintersPage, PrinterDetailPage.
// ═══════════════════════════════════════════════════════════════

import { motion, AnimatePresence } from 'framer-motion'
import { CheckCircle, AlertCircle, ShieldCheck } from 'lucide-react'

interface LocalToast {
  id: string
  msg: string
  type: 'success' | 'error' | 'info' | 'warning'
}

interface PageToastsProps {
  toasts: LocalToast[]
}

export function PageToasts({ toasts }: PageToastsProps) {
  if (toasts.length === 0) return null

  return (
    <div className="fixed bottom-6 right-6 flex flex-col gap-2 z-[9999] pointer-events-none">
      <AnimatePresence>
        {toasts.map((t) => (
          <motion.div
            key={t.id}
            initial={{ opacity: 0, x: 40 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: 40 }}
            className={`flex items-center gap-2 px-4 py-2.5 rounded-lg border text-sm shadow-xl pointer-events-auto ${
              t.type === 'success'
                ? 'bg-green-900/80 border-green-500/50 text-green-300'
                : t.type === 'error'
                ? 'bg-red-900/80 border-red-500/50 text-red-300'
                : 'bg-gray-800 border-gray-600 text-gray-200'
            }`}
          >
            {t.type === 'success' && <CheckCircle className="w-4 h-4" />}
            {t.type === 'error' && <AlertCircle className="w-4 h-4" />}
            {t.type === 'info' && <ShieldCheck className="w-4 h-4" />}
            {t.msg}
          </motion.div>
        ))}
      </AnimatePresence>
    </div>
  )
}
