// ═══════════════════════════════════════════════════════════════
// PRESTIGE DASHBOARD - HISTORY PAGE (REBUILT)
// Route: /history — Uses features/history/ components
// Integrates: HistoryList, PrintDetails, Statistics
// ═══════════════════════════════════════════════════════════════

import { useState, useEffect } from 'react'
import { useTranslation } from 'react-i18next'
import { Clock, BarChart3, List } from 'lucide-react'
import { printerApi } from '@services/printer-api'
import { usePrinterStore, selectPrintersArray } from '@core/state/printerStore'
import { HistoryList } from '@features/history/HistoryList'
import { Statistics } from '@features/history/Statistics'
import type { PrintJob } from '@features/history/HistoryList'

type ViewMode = 'list' | 'statistics'

export default function HistoryPage() {
  const { t } = useTranslation()
  const [viewMode, setViewMode] = useState<ViewMode>('list')
  const [jobs, setJobs] = useState<PrintJob[]>([])
  const [jobsLoading, setJobsLoading] = useState(true)
  const printers = usePrinterStore(selectPrintersArray)

  // Fetch job history from each printer separately and merge.
  // Backend has no global history endpoint — only GET /api/printers/:id/jobs.
  useEffect(() => {
    if (printers.length === 0) {
      setJobsLoading(false)
      return
    }
    const fetchJobs = async () => {
      setJobsLoading(true)
      try {
        const results = await Promise.allSettled(
          printers.map(p => printerApi.getHistory(p.id, { limit: 200 }))
        )
        const merged: PrintJob[] = []
        results.forEach(r => {
          if (r.status === 'fulfilled') merged.push(...(r.value.jobs as PrintJob[]))
        })
        // Sort newest first across all printers
        merged.sort((a, b) => new Date(b.startTime).getTime() - new Date(a.startTime).getTime())
        setJobs(merged)
      } catch {
        // Graceful fallback — both views will show empty state
      } finally {
        setJobsLoading(false)
      }
    }
    fetchJobs()
  }, [printers])

  return (
    <div className="p-6 space-y-4">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-display font-bold text-text flex items-center gap-3">
            <Clock className="w-7 h-7 text-primary" />
            {t('history.title', 'Print History')}
          </h1>
          <p className="text-sm text-text-muted mt-1">
            {t('history.subtitle', 'View past print jobs and statistics')}
          </p>
        </div>

        {/* View mode toggle */}
        <div className="flex rounded-lg border border-border overflow-hidden">
          <button
            onClick={() => setViewMode('list')}
            className={`flex items-center gap-1.5 px-3 py-2 text-xs transition-colors ${
              viewMode === 'list' ? 'bg-primary/10 text-primary' : 'text-text-muted hover:text-text'
            }`}
          >
            <List className="w-3.5 h-3.5" />
            List
          </button>
          <button
            onClick={() => setViewMode('statistics')}
            className={`flex items-center gap-1.5 px-3 py-2 text-xs transition-colors ${
              viewMode === 'statistics' ? 'bg-primary/10 text-primary' : 'text-text-muted hover:text-text'
            }`}
          >
            <BarChart3 className="w-3.5 h-3.5" />
            Statistics
          </button>
        </div>
      </div>

      {/* Content */}
      {viewMode === 'list' ? (
        // Pass pre-fetched jobs — HistoryList skips its own fetch
        <HistoryList jobs={jobsLoading ? undefined : jobs} />
      ) : (
        <Statistics jobs={jobs} />
      )}
    </div>
  )
}
