// ═══════════════════════════════════════════════════════════════
// PRESTIGE DASHBOARD - BACKUP SETTINGS
// Lightweight status widget — full management at /backup
// ═══════════════════════════════════════════════════════════════

import React from 'react'
import { useNavigate } from 'react-router-dom'
import { useSystemStore, selectBackupInfo } from '@core/state'
import { Database, ExternalLink, Loader2, AlertCircle } from 'lucide-react'
import { SettingsSection } from './SettingsSection'

export interface BackupSettingsProps {
  className?: string
}

export const BackupSettings: React.FC<BackupSettingsProps> = ({ className = '' }) => {
  const navigate = useNavigate()
  const backupInfo = useSystemStore(selectBackupInfo)

  return (
    <SettingsSection
      title="Backup & Restore"
      description="Manage system backups and data restoration"
      icon={<Database className="w-5 h-5" />}
      className={className}
    >
      <div className="space-y-4">

        {/* Status summary from store */}
        <div className="bg-gray-800/30 rounded-lg p-4 border border-cyan-500/20 space-y-3">

          <div className="grid grid-cols-2 gap-4">
            <div>
              <span className="text-xs text-gray-400">Last Backup</span>
              <p className="text-sm font-medium text-gray-200 mt-1">
                {backupInfo.lastBackup || 'Never'}
              </p>
            </div>
            <div>
              <span className="text-xs text-gray-400">Next Scheduled</span>
              <p className="text-sm font-medium text-gray-200 mt-1">
                {backupInfo.nextScheduledBackup || 'Not scheduled'}
              </p>
            </div>
          </div>

          {backupInfo.backupInProgress && (
            <div className="flex items-center gap-2 text-cyan-400 text-sm">
              <Loader2 className="w-4 h-4 animate-spin flex-shrink-0" />
              Backup in progress...
            </div>
          )}

          {backupInfo.backupError && (
            <div className="flex items-center gap-2 text-red-400 text-sm">
              <AlertCircle className="w-4 h-4 flex-shrink-0" />
              {backupInfo.backupError}
            </div>
          )}
        </div>

        {/* Redirect to full Backup page — single source of truth */}
        <button
          onClick={() => navigate('/backup')}
          className="w-full flex items-center justify-center gap-2 px-4 py-2.5
            bg-cyan-500/10 text-cyan-400 border border-cyan-500/40 rounded-lg
            hover:bg-cyan-500/20 transition-colors text-sm font-medium"
        >
          <Database className="w-4 h-4" />
          Open Backup Manager
          <ExternalLink className="w-3.5 h-3.5 opacity-60" />
        </button>
        <p className="text-[11px] text-gray-500 text-center">
          Create, restore, verify and schedule backups from the dedicated Backup page.
        </p>

      </div>
    </SettingsSection>
  )
}

export default BackupSettings
