// ═══════════════════════════════════════════════════════════════
// PRESTIGE — AI SETTINGS TAB
// AI system config: autonomy level, thresholds, notifications
// ═══════════════════════════════════════════════════════════════

import React, { useState, useEffect } from 'react'
import { Brain, CheckCircle, BarChart3, AlertCircle, Cpu, Trash2, ShieldAlert, XCircle, RefreshCw } from 'lucide-react'
import { AIControlToggle } from './AIControlToggle'
import { Section, ToggleRow, Slider } from './AIPagePrimitives'
import { apiFetch } from './ai-types'
import { useAIStore } from '@core/state/aiStore'
import { usePrinterStore } from '@core/state/printerStore'
import { useAsyncAction } from '@core/hooks/useAsyncAction'

const SETTINGS_KEY = 'prestige_ai_settings'
const DEFAULT_CFG = {
  globalConfidence: 70, speedReduceThreshold: 70, accelReduceThreshold: 75,
  pauseThreshold: 85, safeModeThreshold: 90,
  autoAnalysis: true, analysisInterval: 30,
  notifyOnAnomaly: true, notifyOnRecommendation: true,
}

function loadSettings() {
  try { const r = localStorage.getItem(SETTINGS_KEY); if (r) return { ...DEFAULT_CFG, ...JSON.parse(r) } } catch {}
  return DEFAULT_CFG
}

export interface AISettingsTabProps {
  selectedPrinter: string
  currentLevel: number
  isEnabled: boolean
  printers: any[]
}

export function AISettingsTab({ selectedPrinter, currentLevel, isEnabled, printers }: AISettingsTabProps) {
  const [cfg, setCfg] = useState(loadSettings)
  const [saved, setSaved] = useState(false)

  useEffect(() => {
    apiFetch<Record<string, any>>('/api/ai/config').then(d => {
      if (!d) return
      setCfg(prev => ({
        ...prev,
        globalConfidence: d.confidenceThreshold != null ? Math.round(d.confidenceThreshold * 100) : prev.globalConfidence,
        autoAnalysis: d.autoAnalysis ?? prev.autoAnalysis,
        analysisInterval: d.analysisInterval ?? prev.analysisInterval,
        notifyOnAnomaly: d.notifyOnAnomaly ?? prev.notifyOnAnomaly,
        notifyOnRecommendation: d.notifyOnRecommendation ?? prev.notifyOnRecommendation,
        speedReduceThreshold: d.actionThresholds?.speed_reduce != null ? Math.round(d.actionThresholds.speed_reduce * 100) : prev.speedReduceThreshold,
        accelReduceThreshold: d.actionThresholds?.acceleration_reduce != null ? Math.round(d.actionThresholds.acceleration_reduce * 100) : prev.accelReduceThreshold,
        pauseThreshold: d.actionThresholds?.pause != null ? Math.round(d.actionThresholds.pause * 100) : prev.pauseThreshold,
        safeModeThreshold: d.actionThresholds?.safe_mode != null ? Math.round(d.actionThresholds.safe_mode * 100) : prev.safeModeThreshold,
      }))
    })
  }, [])

  const saveAction = useAsyncAction(async () => {
    const payload = {
      confidenceThreshold: cfg.globalConfidence / 100,
      autoAnalysis: cfg.autoAnalysis,
      analysisInterval: cfg.analysisInterval,
      notifyOnAnomaly: cfg.notifyOnAnomaly,
      notifyOnRecommendation: cfg.notifyOnRecommendation,
      actionThresholds: {
        speed_reduce: cfg.speedReduceThreshold / 100,
        acceleration_reduce: cfg.accelReduceThreshold / 100,
        pause: cfg.pauseThreshold / 100,
        safe_mode: cfg.safeModeThreshold / 100,
      },
    }
    localStorage.setItem(SETTINGS_KEY, JSON.stringify(cfg))
    const res = await fetch('/api/ai/config', {
      method: 'PUT', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    })
    if (!res.ok) throw new Error('Backend save failed')
    setSaved(true)
    setTimeout(() => setSaved(false), 2500)
  })

  return (
    <div className="space-y-5">
      {/* Autonomy level */}
      <Section title="Autonomy Level" icon={<Brain className="w-4 h-4 text-cyan-400" />}>
        {selectedPrinter === 'all' && (
          <div className="mb-3 text-[11px] text-cyan-400 bg-cyan-500/10 border border-cyan-500/30 rounded px-2 py-1">
            ⚡ Applies to ALL printers at once
          </div>
        )}
        <AIControlToggle
          currentLevel={currentLevel}
          printerId={selectedPrinter !== 'all' ? selectedPrinter : undefined}
          skipApiCall={selectedPrinter === 'all'}
          onLevelChange={async (level: number) => {
            const store = useAIStore.getState()
            if (selectedPrinter !== 'all') {
              store.setPrinterLevel(selectedPrinter, level)
              try {
                const res = await fetch(`/api/printers/${selectedPrinter}/ai-level`, {
                  method: 'PUT', headers: { 'Content-Type': 'application/json' },
                  body: JSON.stringify({ level }),
                })
                if (!res.ok) console.error(`[AI] Failed to save ai-level for ${selectedPrinter}: HTTP ${res.status}`)
              } catch (err) {
                console.error(`[AI] Network error saving ai-level for ${selectedPrinter}:`, err)
              }
            } else {
              const lvlMap: Record<number, string> = { 0: 'monitoring', 1: 'advisory', 2: 'semi-autonomous' }
              store.setAutonomyLevel((lvlMap[level] ?? 'advisory') as any)
              const globalSave = fetch('/api/ai/settings', {
                method: 'PUT', headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ autonomyLevel: level }),
              }).then(res => {
                if (!res.ok) console.error(`[AI] Failed to save global autonomy level: HTTP ${res.status}`)
              }).catch(err => console.error('[AI] Network error saving global autonomy level:', err))
              const printerSaves = Object.keys(usePrinterStore.getState().printers).map(id => {
                store.setPrinterLevel(id, level)
                return fetch(`/api/printers/${id}/ai-level`, {
                  method: 'PUT', headers: { 'Content-Type': 'application/json' },
                  body: JSON.stringify({ level }),
                }).then(res => {
                  if (!res.ok) console.error(`[AI] Failed to save ai-level for printer ${id}: HTTP ${res.status}`)
                }).catch(err => console.error(`[AI] Network error saving ai-level for printer ${id}:`, err))
              })
              await Promise.all([globalSave, ...printerSaves])
            }
          }}
        />
      </Section>

      {/* Master toggle */}
      <Section title="System" icon={<Cpu className="w-4 h-4 text-cyan-400" />}>
        <ToggleRow
          label="Enable AI System"
          desc="Master switch for AI monitoring and analysis"
          tooltip="When enabled, AI monitors printer telemetry and generates recommendations."
          value={isEnabled}
          onChange={() => useAIStore.getState().setAIEnabled(!isEnabled)}
        />
        <ToggleRow
          label="Auto Analysis"
          desc="Continuously analyze printer telemetry"
          tooltip="When enabled, AI continuously monitors at the configured interval."
          value={cfg.autoAnalysis}
          onChange={v => setCfg(p => ({ ...p, autoAnalysis: v }))}
        />
        {cfg.autoAnalysis && (
          <Slider label="Analysis Interval" value={cfg.analysisInterval}
            onChange={v => setCfg(p => ({ ...p, analysisInterval: v }))}
            min={5} max={300} step={5} unit="s"
            desc="How often to analyze telemetry"
            tooltip="30–60s recommended. Lower = more CPU." />
        )}
      </Section>

      {/* Confidence thresholds */}
      <Section title="Confidence Thresholds" icon={<BarChart3 className="w-4 h-4 text-cyan-400" />}>
        <p className="text-xs text-gray-400 mb-3">Minimum confidence required before AI takes each action. Higher = fewer false positives.</p>
        <Slider label="Global Threshold" value={cfg.globalConfidence} onChange={v => setCfg(p => ({ ...p, globalConfidence: v }))} desc="Default for all actions" tooltip="Baseline confidence for any AI action." />
        <div className="border-t border-gray-700 pt-3 mt-3 space-y-3">
          <div className="text-xs font-semibold text-gray-500 uppercase tracking-wider">Per-Action Overrides</div>
          <Slider label="Speed Reduction" value={cfg.speedReduceThreshold} onChange={v => setCfg(p => ({ ...p, speedReduceThreshold: v }))} desc="Reduce speed on vibration" tooltip="Triggers speed reduction when vibration exceeds threshold." />
          <Slider label="Acceleration Reduction" value={cfg.accelReduceThreshold} onChange={v => setCfg(p => ({ ...p, accelReduceThreshold: v }))} desc="Reduce acceleration for quality" tooltip="Reduces acceleration when ringing/quality issues detected." />
          <Slider label="Print Pause" value={cfg.pauseThreshold} onChange={v => setCfg(p => ({ ...p, pauseThreshold: v }))} desc="Pause on serious issue" tooltip="Pauses print when dangerous issues detected." />
          <Slider label="Safe Mode" value={cfg.safeModeThreshold} onChange={v => setCfg(p => ({ ...p, safeModeThreshold: v }))} desc="Safe mode for critical failures" tooltip="Emergency stop + cooldown on critical failure." />
        </div>
      </Section>

      {/* Notifications */}
      <Section title="Notifications" icon={<AlertCircle className="w-4 h-4 text-cyan-400" />}>
        <ToggleRow label="Anomaly Alerts" desc="Notify when anomalies are detected" tooltip="Notifications for unusual patterns like temperature spikes." value={cfg.notifyOnAnomaly} onChange={v => setCfg(p => ({ ...p, notifyOnAnomaly: v }))} />
        <ToggleRow label="Recommendation Alerts" desc="Notify on new recommendations" tooltip="Notifications whenever AI creates a recommendation." value={cfg.notifyOnRecommendation} onChange={v => setCfg(p => ({ ...p, notifyOnRecommendation: v }))} />
      </Section>

      {/* ── Danger Zone: Reset Printer Data ── */}
      {selectedPrinter !== 'all' && (
        <ResetPrinterDataSection printerId={selectedPrinter} printerName={printers.find(p => p.id === selectedPrinter)?.name ?? selectedPrinter} />
      )}

      <div className="flex items-center justify-end gap-3">
        {saved && <span className="text-xs text-green-400 flex items-center gap-1"><CheckCircle className="w-3.5 h-3.5" /> Saved to database</span>}
        {saveAction.error && <span className="text-xs text-red-400">Save failed — check backend connection</span>}
        <button onClick={() => saveAction.execute()} disabled={saveAction.loading}
          className="px-5 py-2.5 rounded-lg bg-cyan-500/20 text-cyan-400 border border-cyan-500/50 font-medium text-sm hover:bg-cyan-500/30 transition-colors disabled:opacity-50">
          {saveAction.loading ? 'Saving...' : 'Save Settings'}
        </button>
      </div>
    </div>
  )
}

// ═══════════════════════════════════════════════════════════════
// RESET PRINTER DATA — Danger Zone section
// ═══════════════════════════════════════════════════════════════

const DANGER_REASONS = [
  {
    icon: '📉',
    title: 'All analysis history will be lost',
    body: 'Every analysis run accumulates data about printer health, trends and calibration quality over time. Once deleted, the AI can no longer detect degradation by comparing against the printer’s previous baseline.',
  },
  {
    icon: '🔍',
    title: 'AI becomes blind at first',
    body: 'The first analyses after a reset operate with 0 telemetry points — meaning inaccurate estimates and potentially misleading recommendations until data is collected again.',
  },
  {
    icon: '🏆',
    title: 'Diagnostic test results will be gone',
    body: 'All saved Printer Status Check, Extrusion, Movement, Temperature and Retraction test results will be permanently deleted. Every test will need to be re-run from scratch.',
  },
  {
    icon: '📊',
    title: 'Industry Comparison scores reset to zero',
    body: 'The Health score, Quality score, Fail Risk and Clog Risk comparison against the industry average will be cleared. The new-printer diagnostic baseline journey starts over.',
  },
]

function ResetPrinterDataSection({ printerId, printerName }: { printerId: string; printerName: string }) {
  const [showConfirm, setShowConfirm] = useState(false)
  const [resetting, setResetting] = useState(false)
  const [done, setDone] = useState(false)
  const [typedName, setTypedName] = useState('')
  const nameMatches = typedName.trim().toLowerCase() === printerName.trim().toLowerCase()

  const handleReset = async () => {
    if (!nameMatches || resetting) return
    setResetting(true)
    try {
      // 1. Clear local browser storage
      localStorage.removeItem(`prestige_analysis_${printerId}`)
      localStorage.removeItem(`prestige_diag_${printerId}`)

      // 2. Attempt backend reset (best-effort — don't block if endpoint missing)
      try {
        await fetch(`/api/ai/printers/${printerId}/reset`, { method: 'DELETE' })
      } catch { /* silent — local clear always succeeds */ }

      setDone(true)
      setShowConfirm(false)
      setTypedName('')
      setTimeout(() => setDone(false), 5000)
    } finally {
      setResetting(false)
    }
  }


  return (
    <>
      {/* ── Section card ── */}
      <div className="rounded-xl border border-red-500/25 bg-red-500/5 overflow-hidden">
        <div className="flex items-center gap-2 px-4 py-2.5 border-b border-red-500/20">
          <ShieldAlert className="w-4 h-4 text-red-400" />
          <span className="text-sm font-semibold text-red-300">Danger Zone</span>
        </div>
        <div className="px-4 py-3 flex items-center justify-between gap-4">
          <div>
            <p className="text-sm font-semibold text-gray-200">Reset Printer Data</p>
            <p className="text-xs text-gray-400 mt-0.5">
              Erase all saved analysis, diagnostics and benchmark data for <strong className="text-gray-300">{printerName}</strong>.
              The printer will be treated as brand new by the AI.
            </p>
          </div>
          <button
            onClick={() => { setShowConfirm(true); setTypedName('') }}
            className="flex-shrink-0 flex items-center gap-1.5 px-3 py-2 rounded-lg text-xs font-semibold
              bg-red-500/15 text-red-400 border border-red-500/30
              hover:bg-red-500/25 transition-colors active:scale-95"
          >
            <Trash2 className="w-3.5 h-3.5" /> Reset
          </button>
        </div>
        {done && (
          <div className="px-4 pb-3 flex items-center gap-2 text-xs text-green-400">
            <CheckCircle className="w-3.5 h-3.5" />
            All data for <strong>{printerName}</strong> has been erased. AI will start collecting data from scratch.
          </div>
        )}
      </div>

      {/* ── Confirmation modal ── */}
      {showConfirm && (
        <div
          className="fixed inset-0 z-[9999] flex items-center justify-center"
          style={{ backgroundColor: 'rgba(0,0,0,0.75)' }}
          onClick={() => !resetting && setShowConfirm(false)}
        >
          <div
            className="relative w-full max-w-lg mx-4 rounded-2xl border border-red-500/40 bg-gray-950 shadow-2xl overflow-hidden"
            onClick={e => e.stopPropagation()}
          >
            {/* Header */}
            <div className="flex items-center gap-3 px-5 py-4 border-b border-red-500/30 bg-red-500/10">
              <Trash2 className="w-5 h-5 text-red-400 flex-shrink-0" />
              <div className="flex-1 min-w-0">
                <p className="text-sm font-bold text-red-300">Reset Printer Data</p>
                <p className="text-xs text-gray-400 mt-0.5">Printeris: <strong className="text-gray-200">{printerName}</strong></p>
              </div>
              <button onClick={() => setShowConfirm(false)} disabled={resetting}
                className="text-gray-500 hover:text-gray-200 transition-colors p-1 rounded-lg hover:bg-gray-700/50">
                <XCircle className="w-5 h-5" />
              </button>
            </div>

            {/* Why not to do this */}
            <div className="px-5 py-4 space-y-3">
              <p className="text-sm font-semibold text-gray-200">⚠️ Why you should think twice:</p>
              <div className="space-y-2.5">
                {DANGER_REASONS.map(r => (
                  <div key={r.title} className="flex items-start gap-2.5 rounded-lg bg-gray-900/60 border border-gray-700/60 px-3 py-2.5">
                    <span className="text-lg leading-none flex-shrink-0 mt-0.5">{r.icon}</span>
                    <div>
                      <p className="text-xs font-semibold text-gray-200">{r.title}</p>
                      <p className="text-[11px] text-gray-400 mt-0.5 leading-relaxed">{r.body}</p>
                    </div>
                  </div>
                ))}
              </div>

              {/* Name confirmation */}
              <div className="rounded-lg bg-red-500/8 border border-red-500/30 px-4 py-3 space-y-2">
                <p className="text-xs font-semibold text-red-300">
                  To confirm, type the printer name: <strong className="text-white">{printerName}</strong>
                </p>
                <input
                  type="text"
                  value={typedName}
                  onChange={e => setTypedName(e.target.value)}
                  placeholder={`Type "${printerName}" here…`}
                  disabled={resetting}
                  className="w-full rounded-lg bg-gray-900 border border-gray-600 focus:border-red-500 text-gray-100
                    text-sm px-3 py-2 outline-none placeholder-gray-600 transition-colors disabled:opacity-50"
                />
              </div>
            </div>

            {/* Footer */}
            <div className="flex items-center justify-end gap-3 px-5 py-3 border-t border-gray-700 bg-gray-900/80">
              <button
                onClick={() => setShowConfirm(false)}
                disabled={resetting}
                className="px-4 py-2 rounded-lg text-xs font-semibold text-gray-400 border border-gray-700 hover:bg-gray-800 transition-colors disabled:opacity-50"
              >
                Cancel
              </button>
              <button
                onClick={handleReset}
                disabled={!nameMatches || resetting}
                className="flex items-center gap-1.5 px-4 py-2 rounded-lg text-xs font-bold
                  bg-red-500/20 text-red-400 border border-red-500/40
                  hover:bg-red-500/30 transition-colors active:scale-95
                  disabled:opacity-35 disabled:cursor-not-allowed"
              >
                {resetting
                  ? <><RefreshCw className="w-3.5 h-3.5 animate-spin" /> Erasing…</>
                  : <><Trash2 className="w-3.5 h-3.5" /> Yes, erase all data</>}
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  )
}

export default AISettingsTab
