// ═══════════════════════════════════════════════════════════════
// PRESTIGE DASHBOARD - AI STATUS INDICATOR
// Spec: frontend implementacijass plans.txt §6
// Shows: "🤖 AI: Active (Level 1)" / "AI: Disabled" / "AI: Offline"
//
// FIX: Removed independent aiApi.getStatus() polling from this component.
//      AI status is now read exclusively from AIStore, which is populated
//      by the useAIStatus hook (called once at app startup via
//      useDataInitialization). This eliminates duplicate API calls.
// ═══════════════════════════════════════════════════════════════

import React from 'react'
import { useAIStore, selectAIEnabled, selectAIStatus, selectAISettings } from '@core/state'
import { Brain, Activity, AlertTriangle, CheckCircle } from 'lucide-react'

export interface AIStatusIndicatorProps {
  className?: string
  showLabel?: boolean
}

export const AIStatusIndicator: React.FC<AIStatusIndicatorProps> = ({
  className = '',
  showLabel = true,
}) => {
  const aiEnabled  = useAIStore(selectAIEnabled)
  const aiStatus   = useAIStore(selectAIStatus)
  const settings   = useAIStore(selectAISettings)

  // Determine display state purely from store — no local fetching
  const getDisplay = () => {
    if (!aiEnabled) {
      return {
        icon: Brain,
        color: 'text-gray-500',
        bgColor: 'bg-gray-500/10',
        borderColor: 'border-gray-500/30',
        label: 'AI Disabled',
        pulse: false,
      }
    }

    // BackendAIStatus uses `healthy: boolean`; store normalises this to a
    // `status` string ('active' | 'offline' | 'degraded' | 'initializing').
    const statusStr: string =
      typeof aiStatus === 'string'
        ? aiStatus
        : (aiStatus as any)?.status ?? 'unknown'

    const isHealthy =
      (aiStatus as any)?.healthy === true ||
      statusStr === 'active' ||
      statusStr === 'operational'

    if (isHealthy) {
      const level = settings?.autonomyLevel ?? 1
      return {
        icon: CheckCircle,
        color: 'text-green-400',
        bgColor: 'bg-green-500/10',
        borderColor: 'border-green-500/30',
        label: `Active (Level ${level})`,
        pulse: false,
      }
    }

    if (statusStr === 'degraded') {
      return {
        icon: AlertTriangle,
        color: 'text-yellow-400',
        bgColor: 'bg-yellow-500/10',
        borderColor: 'border-yellow-500/30',
        label: 'Degraded',
        pulse: true,
      }
    }

    if (statusStr === 'initializing') {
      return {
        icon: Activity,
        color: 'text-cyan-400',
        bgColor: 'bg-cyan-500/10',
        borderColor: 'border-cyan-500/30',
        label: 'Initializing...',
        pulse: true,
      }
    }

    // offline / unknown
    return {
      icon: Activity,
      color: 'text-red-400',
      bgColor: 'bg-red-500/10',
      borderColor: 'border-red-500/30',
      label: 'Offline',
      pulse: false,
    }
  }

  const display = getDisplay()
  const Icon = display.icon

  // Pending recommendations count from store
  const pendingCount: number =
    (aiStatus as any)?.stats?.pendingRecommendations ?? 0

  return (
    <div
      className={`flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg border text-xs ${display.bgColor} ${display.borderColor} ${className}`}
    >
      <Brain className={`w-4 h-4 ${display.color}`} />
      <span className={`font-medium ${display.color}`}>AI</span>
      {showLabel && (
        <>
          <span className="text-gray-500">:</span>
          <span
            className={`font-medium ${display.color} ${display.pulse ? 'animate-pulse' : ''}`}
          >
            {display.label}
          </span>
        </>
      )}
      {pendingCount > 0 && (
        <span className="ml-1 px-1.5 py-0.5 bg-cyan-500/20 text-cyan-400 rounded-full text-[10px] font-bold">
          {pendingCount}
        </span>
      )}
    </div>
  )
}

export default AIStatusIndicator
