import { useEffect, useRef } from 'react'
import { Routes, Route, Navigate, useLocation } from 'react-router-dom'
import { AnimatePresence } from 'framer-motion'
import { PageTransition } from '@core/components/PageTransition'
import { AppShell } from '@layout/AppShell'
import { WebSocketProvider } from '@core/hooks/useWebSocketIntegration'
import { useDataInitialization } from '@core/hooks'
import { ThemeProvider } from '@/themes/ThemeProvider'
import { systemApi } from '@/services/system-api'
import { useAuthStore } from '@core/state'

// Pages
import LoginPage from './pages/LoginPage'
import ResetPasswordPage from './pages/ResetPasswordPage'
import SubscriptionPage from './pages/SubscriptionPage'
import DashboardPage from './pages/DashboardPage'
import PrintersPage from './pages/PrintersPage'
import PrinterDetailPage from './pages/PrinterDetailPage'
import HistoryPage from './pages/HistoryPage'
import AIControlPage from './pages/AIControlPage'
import SettingsPage from './pages/SettingsPage'
import MonitoringPage from './pages/MonitoringPage'
import MaintenancePage from './pages/MaintenancePage'
import BackupPage from './pages/BackupPage'
import GCodePage from './pages/GCodePage'
import BedMeshPage from './pages/BedMeshPage'
import SupportPage from './pages/SupportPage'
import DiscoveryPage from './pages/DiscoveryPage'
import ArchitecturePage from './pages/ArchitecturePage'

// ─── Auth-protected route ─────────────────────────────────────

function ProtectedRoute({ children }: { children: React.ReactNode }) {
  const { session, isInitialized } = useAuthStore()
  const location = useLocation()

  if (!isInitialized) {
    return (
      <div className="flex items-center justify-center h-screen bg-gray-950">
        <div className="text-center">
          <div className="w-12 h-12 border-4 border-cyan-500 border-t-transparent rounded-full animate-spin mx-auto mb-3" />
          <p className="text-cyan-400 text-sm">Autentificējas...</p>
        </div>
      </div>
    )
  }

  if (!session) {
    return <Navigate to="/login" state={{ from: location.pathname }} replace />
  }

  return <>{children}</>
}

// ─── Inner app (needs WebSocket + data init) ──────────────────

function AppContent() {
  const { isInitialized, isLoading, error } = useDataInitialization()
  const location = useLocation()

  const healthCheckRan = useRef(false)
  useEffect(() => {
    if (healthCheckRan.current) return
    healthCheckRan.current = true
    systemApi.getHealth().catch(() => {
      console.warn('[App] Initial health check failed — backend may be offline')
    })
  }, [])

  if (isLoading) {
    return (
      <AppShell>
        <div className="flex items-center justify-center h-screen">
          <div className="text-center">
            <div className="w-16 h-16 border-4 border-cyan-500 border-t-transparent rounded-full animate-spin mx-auto mb-4" />
            <p className="text-cyan-400 text-lg">Ielādē PRESTIGE Dashboard...</p>
            <p className="text-gray-500 text-sm mt-2">Savienojas ar backend...</p>
          </div>
        </div>
      </AppShell>
    )
  }

  if (error && !isInitialized) {
    console.error('Initialization error:', error)
  }

  return (
    <AppShell>
      <AnimatePresence mode="wait" initial={false}>
        <PageTransition routeKey={location.pathname}>
          <Routes location={location}>
            <Route path="/" element={<DashboardPage />} />
            <Route path="/printers" element={<PrintersPage />} />
            <Route path="/printers/:id" element={<PrinterDetailPage />} />
            <Route path="/history" element={<HistoryPage />} />
            <Route path="/monitoring" element={<MonitoringPage />} />
            <Route path="/ai" element={<AIControlPage />} />
            <Route path="/maintenance" element={<MaintenancePage />} />
            <Route path="/backup" element={<BackupPage />} />
            <Route path="/gcode" element={<GCodePage />} />
            <Route path="/bed-mesh" element={<BedMeshPage />} />
            <Route path="/settings" element={<SettingsPage />} />
            <Route path="/settings/:section" element={<SettingsPage />} />
            <Route path="/support" element={<SupportPage />} />
            <Route path="/discovery" element={<DiscoveryPage />} />
            <Route path="/arch-admin" element={<ArchitecturePage />} />
            <Route path="/subscription" element={<SubscriptionPage />} />
            <Route path="/ai/arch-admin" element={<Navigate to="/arch-admin" replace />} />
          </Routes>
        </PageTransition>
      </AnimatePresence>
    </AppShell>
  )
}

// ─── Root App ─────────────────────────────────────────────────

function App() {
  const { initialize, isInitialized } = useAuthStore()

  // Bootstrap auth state on every app load
  useEffect(() => {
    if (!isInitialized) void initialize()
  }, [initialize, isInitialized])

  return (
    <ThemeProvider>
      <Routes>
        {/* Public routes — no AppShell, no WebSocket */}
        <Route path="/login" element={<LoginPage />} />
        <Route path="/reset-password" element={<ResetPasswordPage />} />

        {/* All protected routes */}
        <Route
          path="/*"
          element={
            <ProtectedRoute>
              <WebSocketProvider>
                <AppContent />
              </WebSocketProvider>
            </ProtectedRoute>
          }
        />
      </Routes>
    </ThemeProvider>
  )
}

export default App
