// ═══════════════════════════════════════════════════════════════
// PRESTIGE DASHBOARD - DELETE PRINTER DIALOG + HOOK
// ═══════════════════════════════════════════════════════════════

import { useState, useCallback } from 'react'
import { useNavigate } from 'react-router-dom'
import { Trash2, AlertTriangle, Loader2, X } from 'lucide-react'
import { usePrinterStore } from '@core/state/printerStore'

/** Wipes all AI-related data for a printer from localStorage and backend. */
async function purgeAIData(id: string): Promise<void> {
  // 1. Browser storage (always works)
  localStorage.removeItem(`prestige_analysis_${id}`)
  localStorage.removeItem(`prestige_diag_${id}`)
  // 2. Backend AI reset (best-effort — printer may already be deleted by the time we call this)
  try { await fetch(`/api/ai/printers/${id}/reset`, { method: 'DELETE' }) } catch { /* silent */ }
}

export function useDeletePrinter() {
  const removePrinter = usePrinterStore((s) => s.removePrinter)
  const [deleting, setDeleting] = useState<string | null>(null)

  const deletePrinter = useCallback(
    async (id: string, name: string): Promise<boolean> => {
      setDeleting(id)
      try {
        const res = await fetch(`/api/printers/${id}`, { method: 'DELETE' })
        if (!res.ok) {
          const data = await res.json().catch(() => ({}))
          throw new Error((data as any)?.error?.message || `HTTP ${res.status}`)
        }
        // Purge AI monitoring data so the AI store no longer tracks this printer
        await purgeAIData(id)
        removePrinter(id)
        return true
      } catch (err: any) {
        console.error('[DeletePrinter] Failed:', err)
        return false
      } finally {
        setDeleting(null)
      }
    },
    [removePrinter]
  )

  return { deletePrinter, deleting }
}

interface DeletePrinterDialogProps {
  printerId: string
  printerName: string
  onClose: () => void
  navigateAfter?: boolean
}

export function DeletePrinterDialog({
  printerId,
  printerName,
  onClose,
  navigateAfter = false,
}: DeletePrinterDialogProps) {
  const navigate = useNavigate()
  const { deletePrinter, deleting } = useDeletePrinter()
  const [error, setError] = useState<string | null>(null)
  const [confirm, setConfirm] = useState('')

  const isLoading = deleting === printerId
  const confirmed = confirm.trim().toLowerCase() === printerName.trim().toLowerCase()

  const handleDelete = async () => {
    setError(null)
    const ok = await deletePrinter(printerId, printerName)
    if (ok) {
      onClose()
      if (navigateAfter) navigate('/printers', { replace: true })
    } else {
      setError('Failed to delete printer. Please try again.')
    }
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-sm">
      <div className="w-full max-w-md mx-4 rounded-xl border border-red-500/40 bg-[var(--color-surface,#12121a)] shadow-2xl">
        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-[var(--color-border-muted)]">
          <div className="flex items-center gap-2 text-red-400">
            <Trash2 className="w-5 h-5" />
            <h2 className="text-lg font-semibold">Delete Printer</h2>
          </div>
          <button
            onClick={onClose}
            disabled={isLoading}
            className="text-[var(--color-text-muted)] hover:text-[var(--color-text)] transition-colors disabled:opacity-50"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        <div className="px-6 py-5 space-y-4">
          {/* Warning */}
          <div className="flex gap-3 p-3 rounded-lg bg-red-500/10 border border-red-500/30">
            <AlertTriangle className="w-5 h-5 text-red-400 flex-shrink-0 mt-0.5" />
            <div className="text-sm text-[var(--color-text-muted)] space-y-1">
              <p className="text-red-300 font-medium">This action is irreversible!</p>
              <p>Printer <strong className="text-[var(--color-text)]">"{printerName}"</strong> will be permanently deleted from the system, including:</p>
              <ul className="list-disc list-inside space-y-0.5 text-xs mt-1">
                <li>Printer database record</li>
                <li>All print history &amp; event logs</li>
                <li>AI recommendations &amp; anomaly history</li>
                <li>AI health scores, diagnostics &amp; benchmarks</li>
                <li>Industry Comparison data</li>
              </ul>
            </div>
          </div>

          {/* Confirm by typing name */}
          <div>
            <label className="block text-sm text-[var(--color-text-muted)] mb-1.5">
              To confirm, type the printer name:{' '}
              <strong className="text-[var(--color-text)]">{printerName}</strong>
            </label>
            <input
              type="text"
              value={confirm}
              onChange={(e) => setConfirm(e.target.value)}
              placeholder={printerName}
              className="input w-full"
              disabled={isLoading}
              autoFocus
              onKeyDown={(e) => e.key === 'Enter' && confirmed && handleDelete()}
            />
          </div>

          {error && (
            <div className="text-sm text-red-400 bg-red-500/10 border border-red-500/30 rounded-lg px-3 py-2">
              {error}
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="flex justify-end gap-3 px-6 py-4 border-t border-[var(--color-border-muted)]">
          <button
            onClick={onClose}
            disabled={isLoading}
            className="px-4 py-2 text-sm font-medium text-[var(--color-text-muted)] hover:text-[var(--color-text)] transition-colors disabled:opacity-50"
          >
            Cancel
          </button>
          <button
            onClick={handleDelete}
            disabled={!confirmed || isLoading}
            className="flex items-center gap-1.5 px-4 py-2 text-sm font-medium rounded-lg bg-red-600 text-white hover:bg-red-700 transition-all disabled:opacity-40 disabled:cursor-not-allowed"
          >
            {isLoading ? (
              <Loader2 className="w-4 h-4 animate-spin" />
            ) : (
              <Trash2 className="w-4 h-4" />
            )}
            Delete Printer
          </button>
        </div>
      </div>
    </div>
  )
}

interface DeletePrinterButtonProps {
  printerId: string
  printerName: string
  navigateAfter?: boolean
  className?: string
  variant?: 'icon' | 'full'
}

export function DeletePrinterButton({
  printerId,
  printerName,
  navigateAfter = false,
  className = '',
  variant = 'full',
}: DeletePrinterButtonProps) {
  const [open, setOpen] = useState(false)

  return (
    <>
      <button
        onClick={() => setOpen(true)}
        title="Delete printer"
        className={
          variant === 'icon'
            ? `p-2 rounded-lg text-[var(--color-text-muted)] hover:text-red-400 hover:bg-red-500/10 transition-all ${className}`
            : `flex items-center gap-1.5 px-3 py-1.5 text-sm rounded-lg border border-red-500/40 text-red-400 bg-red-500/10 hover:bg-red-500/20 transition-all ${className}`
        }
      >
        <Trash2 className="w-4 h-4" />
        {variant === 'full' && <span>Delete</span>}
      </button>

      {open && (
        <DeletePrinterDialog
          printerId={printerId}
          printerName={printerName}
          navigateAfter={navigateAfter}
          onClose={() => setOpen(false)}
        />
      )}
    </>
  )
}

export default DeletePrinterDialog
