// ═══════════════════════════════════════════════════════════════
// PRESTIGE - G-CODE CONSOLE
// Direct Moonraker WebSocket for real-time responses.
// Commands sent via backend /gcode-direct (no CORS).
// Lines + command history persisted to localStorage per printer.
// ═══════════════════════════════════════════════════════════════

import { useState, useCallback, useRef, useEffect, useMemo } from 'react'
import { Terminal, Send, Trash2, Filter, Copy, X, Wifi, WifiOff } from 'lucide-react'

// ─── Types ────────────────────────────────────────────────────

interface ConsoleLine {
  id: string
  type: 'command' | 'response' | 'error' | 'info'
  text: string
  timestamp: number
}

interface GCodeConsoleProps {
  printerId: string
  printerName?: string
}

// ─── Persistence helpers ──────────────────────────────────────

const MAX_STORED_LINES = 500
const MAX_STORED_HISTORY = 100

function storageKey(printerId: string, suffix: string) {
  return `gcode_console_${printerId}_${suffix}`
}

function loadLines(printerId: string): ConsoleLine[] {
  try {
    const raw = localStorage.getItem(storageKey(printerId, 'lines'))
    if (!raw) return []
    return JSON.parse(raw) as ConsoleLine[]
  } catch { return [] }
}

function saveLines(printerId: string, lines: ConsoleLine[]) {
  try {
    const toStore = lines.slice(-MAX_STORED_LINES)
    localStorage.setItem(storageKey(printerId, 'lines'), JSON.stringify(toStore))
  } catch { /* storage full — ignore */ }
}

function saveClearedAt(printerId: string) {
  try {
    localStorage.setItem(storageKey(printerId, 'cleared_at'), String(Date.now() / 1000))
  } catch { /* ignore */ }
}

function loadClearedAt(printerId: string): number {
  try {
    return parseFloat(localStorage.getItem(storageKey(printerId, 'cleared_at')) ?? '0') || 0
  } catch { return 0 }
}

function loadHistory(printerId: string): string[] {
  try {
    const raw = localStorage.getItem(storageKey(printerId, 'history'))
    if (!raw) return []
    return JSON.parse(raw) as string[]
  } catch { return [] }
}

function saveHistory(printerId: string, history: string[]) {
  try {
    localStorage.setItem(storageKey(printerId, 'history'), JSON.stringify(history.slice(0, MAX_STORED_HISTORY)))
  } catch { /* ignore */ }
}

// ─── GCode suggestions ───────────────────────────────────────

const GCODE_SUGGESTIONS = [
  'G28', 'G28 X Y', 'G28 Z', 'G29',
  'G0', 'G1', 'G90', 'G91',
  'M104', 'M109', 'M140', 'M190',
  'M106', 'M107', 'M112', 'M114', 'M115', 'M119',
  'M220', 'M221', 'M400', 'M503',
  'FIRMWARE_RESTART', 'RESTART', 'STATUS',
  'BED_MESH_CALIBRATE', 'BED_MESH_OUTPUT',
  'PID_CALIBRATE', 'SAVE_CONFIG',
  'GET_POSITION', 'QUERY_ENDSTOPS',
  'SET_FAN_SPEED', 'SET_HEATER_TEMPERATURE',
]

// ─── Moonraker JSON-RPC helper ────────────────────────────────

let rpcId = 1
function makeRpc(method: string, params?: Record<string, unknown>) {
  return JSON.stringify({ jsonrpc: '2.0', method, params, id: rpcId++ })
}

// ═══════════════════════════════════════════════════════════════

export function GCodeConsole({ printerId, printerName }: GCodeConsoleProps) {
  // Load persisted state on mount
  const [lines, setLines] = useState<ConsoleLine[]>(() => {
    const saved = loadLines(printerId)
    if (saved.length > 0) return saved
    return [{ id: 'welcome', type: 'info', text: `Terminal ready — ${printerName || printerId}`, timestamp: Date.now() }]
  })
  const [commandHistory, setCommandHistory] = useState<string[]>(() => loadHistory(printerId))

  const [input, setInput] = useState('')
  const [filterText, setFilterText] = useState('')
  const [filterVisible, setFilterVisible] = useState(false)
  const [useRegex, setUseRegex] = useState(false)
  const [historyIndex, setHistoryIndex] = useState(-1)
  const [suggestions, setSuggestions] = useState<string[]>([])
  const [showSuggestions, setShowSuggestions] = useState(false)
  const [sending, setSending] = useState(false)
  const [wsStatus, setWsStatus] = useState<'connecting' | 'connected' | 'disconnected'>('disconnected')

  const scrollRef = useRef<HTMLDivElement>(null)
  const inputRef = useRef<HTMLInputElement>(null)
  const backendWsRef = useRef<WebSocket | null>(null)
  const reconnectTimer = useRef<ReturnType<typeof setTimeout> | null>(null)
  const disposedRef = useRef(false)
  const lastStoreTsRef = useRef<number>(loadClearedAt(printerId))

  const baseUrl = import.meta.env.VITE_API_URL || 'http://localhost:3002'

  // ─── Auto-scroll ────────────────────────────────────────────
  useEffect(() => {
    if (scrollRef.current)
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight
  }, [lines])

  useEffect(() => { inputRef.current?.focus() }, [])

  // ─── Persist lines on change ─────────────────────────────────
  useEffect(() => {
    saveLines(printerId, lines)
  }, [printerId, lines])

  // ─── Persist history on change ───────────────────────────────
  useEffect(() => {
    saveHistory(printerId, commandHistory)
  }, [printerId, commandHistory])

  const addLine = useCallback((type: ConsoleLine['type'], text: string) => {
    setLines(prev => {
      const next = [...prev, {
        id: `${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
        type, text, timestamp: Date.now(),
      }]
      // Keep only last MAX_STORED_LINES in memory too
      return next.length > MAX_STORED_LINES ? next.slice(-MAX_STORED_LINES) : next
    })
  }, [])

  // ─── Fetch full gcode store via backend proxy ─────────────────
  // Goes through backend so no Private Network Access warning
  const fetchGcodeStore = useCallback(async () => {
    try {
      const res = await fetch(`${baseUrl}/api/printers/${printerId}/gcode-store?count=200`)
      if (!res.ok) return
      const data = await res.json()
      const entries: Array<{ message: string; time: number; type: 'command' | 'response' }> =
        data?.result?.gcode_store ?? []

      if (entries.length === 0) return

      // Only add entries newer than what we already loaded
      const newEntries = entries.filter(e => e.time > lastStoreTsRef.current)
      if (newEntries.length === 0) return

      // Update last timestamp
      lastStoreTsRef.current = Math.max(...newEntries.map(e => e.time))

      // Convert to console lines
      const newLines: ConsoleLine[] = newEntries.map(entry => ({
        id: `store-${entry.time}-${Math.random().toString(36).slice(2, 5)}`,
        // Moonraker marks commands as 'command', responses as 'response'
        type: entry.type === 'command' ? 'command' : 'response',
        // Commands get '>' prefix to match our style
        text: entry.type === 'command' ? `> ${entry.message}` : entry.message,
        timestamp: entry.time * 1000,
      }))

      setLines(prev => {
        // Merge: insert store lines before any lines we added ourselves after last store time
        const merged = [...prev, ...newLines]
          .sort((a, b) => a.timestamp - b.timestamp)
          // Deduplicate by text+timestamp proximity
          .filter((line, i, arr) => {
            if (i === 0) return true
            const prev = arr[i - 1]
            return !(prev.text === line.text && Math.abs(prev.timestamp - line.timestamp) < 500)
          })
        return merged.slice(-MAX_STORED_LINES)
      })
    } catch { /* Moonraker not reachable */ }
  }, [printerId, baseUrl])

  // ─── Backend WebSocket (relays notify_gcode_response from Moonraker) ───────
  // Connects to our backend WS instead of Moonraker directly — no Private Network Access warning
  useEffect(() => {
    disposedRef.current = false
    const wsUrl = baseUrl.replace(/^http/, 'ws') + '/ws'

    const connectBackend = () => {
      if (disposedRef.current) return
      setWsStatus('connecting')

      let ws: WebSocket
      try {
        ws = new WebSocket(wsUrl)
        backendWsRef.current = ws
      } catch {
        setWsStatus('disconnected')
        return
      }

      ws.onopen = () => {
        if (disposedRef.current) return
        setWsStatus('connected')
        // Subscribe to this printer's room so we get gcode_response events
        ws.send(JSON.stringify({ type: 'subscribe', payload: { printerId } }))
        // Load history once connected
        fetchGcodeStore()
      }

      ws.onmessage = (evt) => {
        if (disposedRef.current) return
        try {
          const msg = JSON.parse(evt.data)
          // Backend relays Moonraker gcode_response as { type: 'gcode_response', payload: { response } }
          if (msg.type === 'gcode_response') {
            const response: string = msg.payload?.response ?? ''
            if (response.trim()) {
              response.split('\n')
                .map((l: string) => l.trim())
                .filter(Boolean)
                .forEach((line: string) => addLine('response', line))
              fetchGcodeStore()
            }
          }
        } catch { /* ignore */ }
      }

      ws.onerror = () => {
        if (!disposedRef.current) setWsStatus('disconnected')
      }

      ws.onclose = () => {
        if (disposedRef.current) return
        setWsStatus('disconnected')
        reconnectTimer.current = setTimeout(connectBackend, 4000)
      }
    }

    connectBackend()

    return () => {
      disposedRef.current = true
      if (reconnectTimer.current) clearTimeout(reconnectTimer.current)
      backendWsRef.current?.close()
      backendWsRef.current = null
    }
  }, [printerId, baseUrl, addLine])

  // ─── Send GCode ──────────────────────────────────────────────
  const handleSend = useCallback(async () => {
    const cmd = input.trim()
    if (!cmd || sending) return

    setCommandHistory(prev => {
      const next = [cmd, ...prev.filter(h => h !== cmd)].slice(0, MAX_STORED_HISTORY)
      return next
    })
    setHistoryIndex(-1)
    setInput('')
    setShowSuggestions(false)
    setSending(true)
    addLine('command', `> ${cmd}`)

    try {
      // Primary: backend proxy (no CORS, bypasses connection check)
      const res = await fetch(`${baseUrl}/api/printers/${printerId}/gcode-direct`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ gcode: cmd }),
      })

      if (!res.ok) {
        const data = await res.json().catch(() => ({}))
        addLine('error', `Error: ${data.error || `HTTP ${res.status}`}`)
      }

      // If WS not connected, show fallback OK
      if (wsStatus !== 'connected') {
        setTimeout(() => addLine('response', 'ok'), 500)
      }
    } catch (err) {
      addLine('error', `Network error: ${err instanceof Error ? err.message : 'Unknown'}`)
    } finally {
      setSending(false)
    }
  }, [input, printerId, baseUrl, addLine, sending, wsStatus])

  // ─── Keyboard ────────────────────────────────────────────────
  const handleKeyDown = useCallback((e: React.KeyboardEvent) => {
    if (e.key === 'Enter') { e.preventDefault(); handleSend() }
    else if (e.key === 'ArrowUp') {
      e.preventDefault()
      const newIdx = Math.min(historyIndex + 1, commandHistory.length - 1)
      setHistoryIndex(newIdx)
      setInput(commandHistory[newIdx] || '')
    } else if (e.key === 'ArrowDown') {
      e.preventDefault()
      if (historyIndex > 0) { setHistoryIndex(historyIndex - 1); setInput(commandHistory[historyIndex - 1] || '') }
      else { setHistoryIndex(-1); setInput('') }
    } else if (e.key === 'Tab') {
      e.preventDefault()
      if (suggestions.length > 0) { setInput(suggestions[0]); setShowSuggestions(false) }
    } else if (e.key === 'Escape') {
      setShowSuggestions(false)
    }
  }, [handleSend, commandHistory, historyIndex, suggestions])

 
  const updateSuggestions = (val: string) => {
    if (!val.trim()) {
      setSuggestions([])
      setShowSuggestions(false)
      return
    }
    const upper = val.toUpperCase()
    const matches = GCODE_SUGGESTIONS.filter(s => s.toUpperCase().startsWith(upper))
    setSuggestions(matches.slice(0, 8))
    setShowSuggestions(matches.length > 0)
  }

  const handleInputChange = (val: string) => {
    setInput(val); setHistoryIndex(-1); updateSuggestions(val)
  }

  const filteredLines = useMemo(() => {
    if (!filterText) return lines
    try {
      if (useRegex) {
        const re = new RegExp(filterText, 'i')
        return lines.filter(l => re.test(l.text))
      }
      const lower = filterText.toLowerCase()
      return lines.filter(l => l.text.toLowerCase().includes(lower))
    } catch { return lines }
  }, [lines, filterText, useRegex])

  const clearConsole = () => {
    // Set cutoff to NOW — fetchGcodeStore will ignore everything older
    const nowSeconds = Date.now() / 1000
    lastStoreTsRef.current = nowSeconds
    saveClearedAt(printerId)

    const cleared: ConsoleLine[] = [{ id: 'cleared', type: 'info', text: 'Console cleared.', timestamp: Date.now() }]
    setLines(cleared)
    saveLines(printerId, cleared)
  }

  const copyToClipboard = () =>
    navigator.clipboard?.writeText(filteredLines.map(l => l.text).join('\n'))

  const lineColor = (type: ConsoleLine['type']) => {
    switch (type) {
      case 'command':  return 'text-cyan-400'
      case 'response': return 'text-gray-200'
      case 'error':    return 'text-red-400'
      case 'info':     return 'text-gray-500 italic'
    }
  }

  const wsIndicator = wsStatus === 'connected'
    ? { icon: <Wifi className="w-3 h-3" />, color: 'text-green-400', label: 'Live' }
    : wsStatus === 'connecting'
    ? { icon: <Wifi className="w-3 h-3 animate-pulse" />, color: 'text-yellow-400', label: 'Connecting...' }
    : { icon: <WifiOff className="w-3 h-3" />, color: 'text-gray-500', label: 'Disconnected' }

  return (
    <div className="flex flex-col h-full bg-gray-900/50 border border-gray-700 rounded-lg overflow-hidden">
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-2.5 border-b border-gray-700">
        <div className="flex items-center gap-2 min-w-0">
          <Terminal className="w-4 h-4 text-cyan-400 flex-shrink-0" />
          <span className="text-sm font-semibold text-gray-200">G-Code Console</span>
          <span className="text-xs text-gray-500">({filteredLines.length} lines)</span>
          <span className={`flex items-center gap-1 text-[10px] font-mono ${wsIndicator.color} ml-1 truncate`}>
            {wsIndicator.icon}
            {wsIndicator.label}
          </span>
        </div>
        <div className="flex items-center gap-1 flex-shrink-0">
          <button onClick={() => setFilterVisible(!filterVisible)}
            className={`p-1.5 rounded transition-colors ${filterVisible ? 'text-cyan-400 bg-cyan-500/10' : 'text-gray-400 hover:text-gray-200'}`}
            title="Filter">
            <Filter className="w-3.5 h-3.5" />
          </button>
          <button onClick={copyToClipboard} className="p-1.5 rounded text-gray-400 hover:text-gray-200 transition-colors" title="Copy all">
            <Copy className="w-3.5 h-3.5" />
          </button>
          <button onClick={clearConsole} className="p-1.5 rounded text-gray-400 hover:text-red-400 transition-colors" title="Clear">
            <Trash2 className="w-3.5 h-3.5" />
          </button>
        </div>
      </div>

      {/* Filter bar */}
      {filterVisible && (
        <div className="flex items-center gap-2 px-4 py-2 border-b border-gray-700 bg-gray-800/50">
          <Filter className="w-3.5 h-3.5 text-gray-400 flex-shrink-0" />
          <input id="gcode-filter" name="gcode-filter" type="text" value={filterText} onChange={e => setFilterText(e.target.value)}
            placeholder={useRegex ? 'Regex pattern...' : 'Filter output...'}
            className="flex-1 bg-transparent text-sm text-gray-200 placeholder:text-gray-500 outline-none font-mono" />
          <button onClick={() => setUseRegex(!useRegex)}
            className={`px-2 py-0.5 text-xs rounded font-mono border transition-colors ${useRegex ? 'border-cyan-500 text-cyan-400 bg-cyan-500/10' : 'border-gray-600 text-gray-400'}`}>
            .*
          </button>
          {filterText && (
            <button onClick={() => setFilterText('')} className="p-0.5 text-gray-400 hover:text-gray-200">
              <X className="w-3.5 h-3.5" />
            </button>
          )}
        </div>
      )}

      {/* Console output */}
      <div ref={scrollRef} className="flex-1 overflow-y-auto p-3 font-mono text-xs space-y-0.5 min-h-0 bg-gray-950">
        {filteredLines.map(line => (
          <div key={line.id} className={`${lineColor(line.type)} leading-relaxed whitespace-pre-wrap break-all`}>
            {line.text}
          </div>
        ))}
        {sending && <div className="text-gray-500 animate-pulse">Sending...</div>}
      </div>

      {/* Input bar */}
      <div className="relative border-t border-gray-700 bg-gray-900/80">
        {showSuggestions && suggestions.length > 0 && (
          <div className="absolute bottom-full left-0 right-0 bg-gray-800 border border-gray-700 rounded-t-lg shadow-lg max-h-40 overflow-y-auto z-10">
            {suggestions.map((s, i) => (
              <button key={s}
                onClick={() => { setInput(s); setShowSuggestions(false); inputRef.current?.focus() }}
                className={`w-full text-left px-4 py-1.5 text-xs font-mono hover:bg-cyan-500/10 transition-colors ${i === 0 ? 'text-cyan-400' : 'text-gray-400'}`}>
                {s}
              </button>
            ))}
          </div>
        )}
        <div className="flex items-center gap-2 px-3 py-2.5">
          <span className="text-cyan-400 text-sm font-mono font-bold flex-shrink-0">&gt;</span>
          <input ref={inputRef} id="gcode-command" name="gcode-command" type="text" value={input}
            onChange={e => handleInputChange(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="Type G-Code command..."
            className="flex-1 bg-transparent text-sm text-gray-200 placeholder:text-gray-500 outline-none font-mono"
            autoComplete="off" spellCheck={false} />
          <button onClick={handleSend} disabled={sending || !input.trim()}
            className="p-1.5 rounded text-cyan-400 hover:bg-cyan-500/10 disabled:opacity-30 disabled:cursor-not-allowed transition-colors flex-shrink-0">
            <Send className="w-4 h-4" />
          </button>
        </div>
      </div>
    </div>
  )
}

export default GCodeConsole
