// PRESTIGE DASHBOARD - PRINTER CARD STYLES
// Visual effects, borders, glows, and animations
// ═══════════════════════════════════════════════════════════════

import { PrinterStatus } from '../../types/printer'

/**
 * Status-specific visual configuration
 */
export interface StatusVisualConfig {
  borderColor: string
  glowColor?: string
  bgGradient?: string
  animation?: string
  icon: string
  iconColor: string
}

/**
 * Get visual configuration for printer status
 */
export const getStatusVisualConfig = (status: PrinterStatus): StatusVisualConfig => {
  switch (status) {
    case 'idle':
      return {
        borderColor: 'var(--state-idle)',
        glowColor: 'var(--glow-success)',
        bgGradient: 'linear-gradient(135deg, rgba(34, 197, 94, 0.05) 0%, transparent 50%)',
        animation: 'none',
        icon: '✓',
        iconColor: 'text-green-400',
      }

    case 'printing':
      return {
        borderColor: 'var(--state-printing)',
        glowColor: 'var(--glow-cyan-md)',
        bgGradient: 'linear-gradient(135deg, rgba(0, 245, 255, 0.05) 0%, transparent 50%)',
        animation: 'pulse-glow 2s ease-in-out infinite',
        icon: '▶',
        iconColor: 'text-cyan-400',
      }

    case 'paused':
      return {
        borderColor: 'var(--state-paused)',
        glowColor: 'var(--glow-warning)',
        bgGradient: 'linear-gradient(135deg, rgba(234, 179, 8, 0.05) 0%, transparent 50%)',
        animation: 'breathing 3s ease-in-out infinite',
        icon: '⏸',
        iconColor: 'text-yellow-400',
      }

    case 'error':
      return {
        borderColor: 'var(--state-error)',
        glowColor: 'var(--glow-error)',
        bgGradient: 'linear-gradient(135deg, rgba(239, 68, 68, 0.08) 0%, transparent 50%)',
        animation: 'pulse-fast 1s ease-in-out infinite',
        icon: '⚠',
        iconColor: 'text-red-400',
      }

    case 'disconnected':
      return {
        borderColor: 'var(--state-disconnected)',
        glowColor: undefined,
        bgGradient: 'linear-gradient(135deg, rgba(107, 114, 128, 0.03) 0%, transparent 50%)',
        animation: 'none',
        icon: '✕',
        iconColor: 'text-gray-500',
      }

    case 'ai_action':
      return {
        borderColor: 'var(--state-ai-action)',
        glowColor: 'var(--glow-ai)',
        bgGradient: 'linear-gradient(135deg, rgba(139, 92, 246, 0.08) 0%, transparent 50%)',
        animation: 'pulse-glow 2s ease-in-out infinite',
        icon: '🤖',
        iconColor: 'text-purple-400',
      }

    default:
      return {
        borderColor: 'var(--border-default)',
        glowColor: undefined,
        bgGradient: 'transparent',
        animation: 'none',
        icon: '•',
        iconColor: 'text-gray-400',
      }
  }
}

/**
 * Card container style generator
 */
export const getCardContainerStyle = (
  status: PrinterStatus,
  isHovered: boolean = false
): React.CSSProperties => {
  const config = getStatusVisualConfig(status)

  return {
    borderColor: config.borderColor,
    backgroundImage: config.bgGradient,
    boxShadow: isHovered && config.glowColor 
      ? `${config.glowColor}, 0 4px 12px rgba(0, 0, 0, 0.3)` 
      : config.glowColor || '0 2px 8px rgba(0, 0, 0, 0.2)',
    animation: config.animation,
  }
}

/**
 * Quick action button style generator
 */
export const getActionButtonStyle = (
  variant: 'primary' | 'secondary' | 'danger',
  isHovered: boolean = false
): React.CSSProperties => {
  const styles = {
    primary: {
      backgroundColor: isHovered ? 'rgba(0, 245, 255, 0.2)' : 'rgba(0, 245, 255, 0.1)',
      borderColor: isHovered ? 'rgba(0, 245, 255, 0.5)' : 'rgba(0, 245, 255, 0.3)',
      color: 'var(--accent-cyan)',
      boxShadow: isHovered ? 'var(--glow-cyan-sm)' : 'none',
    },
    secondary: {
      backgroundColor: isHovered ? 'rgba(234, 179, 8, 0.2)' : 'rgba(234, 179, 8, 0.1)',
      borderColor: isHovered ? 'rgba(234, 179, 8, 0.5)' : 'rgba(234, 179, 8, 0.3)',
      color: 'var(--semantic-warning)',
      boxShadow: isHovered ? 'var(--glow-warning)' : 'none',
    },
    danger: {
      backgroundColor: isHovered ? 'rgba(239, 68, 68, 0.2)' : 'rgba(239, 68, 68, 0.1)',
      borderColor: isHovered ? 'rgba(239, 68, 68, 0.5)' : 'rgba(239, 68, 68, 0.3)',
      color: 'var(--semantic-error)',
      boxShadow: isHovered ? 'var(--glow-error)' : 'none',
    },
  }

  return styles[variant]
}

/**
 * CSS Animations (to be added to global styles or component)
 */
export const CARD_ANIMATIONS = `
@keyframes pulse-glow {
  0%, 100% {
    box-shadow: var(--glow-cyan-sm);
  }
  50% {
    box-shadow: var(--glow-cyan-md);
  }
}

@keyframes breathing {
  0%, 100% {
    opacity: 1;
    box-shadow: var(--glow-warning-sm);
  }
  50% {
    opacity: 0.7;
    box-shadow: none;
  }
}

@keyframes pulse-fast {
  0%, 100% {
    box-shadow: var(--glow-error-sm);
    transform: scale(1);
  }
  50% {
    box-shadow: var(--glow-error-md);
    transform: scale(1.01);
  }
}
`

