// PRESTIGE DASHBOARD - MANUAL CHANGE FORM
// SPEC: PAPILDINĀJUMS — MANUĀLĀS IZMAIŅAS §7 — ManualChangeForm
// Register manual printer changes so AI resets baselines properly
// ═══════════════════════════════════════════════════════════════

import { useState, useMemo } from 'react'
import { Wrench, Info, AlertTriangle, CheckCircle, X } from 'lucide-react'
import { useAsyncAction } from '@core/hooks/useAsyncAction'
import {
  CHANGE_CATEGORIES,
  CHANGE_TYPES,
  getChangeTypesByCategory,
  getChangeTypeDefinition,
  type ChangeCategory,
} from './ManualChangeTypes'

interface ManualChangeFormProps {
  printerId: string
  printerName: string
  /** Close the form/dialog */
  onClose?: () => void
  /** Called after successful registration */
  onSuccess?: () => void
}

export function ManualChangeForm({ printerId, printerName, onClose, onSuccess }: ManualChangeFormProps) {
  const [category, setCategory] = useState<ChangeCategory | ''>('')
  const [changeType, setChangeType] = useState('')
  const [description, setDescription] = useState('')
  const [success, setSuccess] = useState(false)

  const availableTypes = useMemo(() => {
    if (!category) return []
    return getChangeTypesByCategory(category as ChangeCategory)
  }, [category])

  const selectedDef = useMemo(() => {
    return getChangeTypeDefinition(changeType)
  }, [changeType])

  const submitAction = useAsyncAction(async () => {
    const baseUrl = import.meta.env.VITE_API_URL || 'http://localhost:3002'
    const res = await fetch(`${baseUrl}/api/ai/printers/${printerId}/maintenance`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        type: changeType,
        description: (description.trim() || selectedDef?.label || changeType),
        notes: category ? `Category: ${category}` : undefined,
      }),
    })
    if (!res.ok) {
      const data = await res.json().catch(() => ({}))
      throw new Error(data.error?.message || `HTTP ${res.status}`)
    }
    setSuccess(true)
    onSuccess?.()
    return res.json()
  })

  if (success) {
    return (
      <div className="space-y-2 p-2">
        <div className="text-center py-4">
          <CheckCircle className="w-10 h-10 text-green-400 mx-auto mb-2" />
          <h3 className="text-base font-semibold text-gray-200">Change Registered</h3>
          <p className="text-sm text-gray-400 mt-2">
            AI has been notified and will start learning new baselines.
            {selectedDef && (
              <> Estimated learning time: <span className="font-semibold text-cyan-400">~{selectedDef.learningHours} print hours</span>.</>
            )}
          </p>
        </div>
        <button onClick={onClose} className="w-full py-2 text-sm font-semibold rounded-lg bg-cyan-500/20 text-cyan-400 hover:bg-cyan-500/30 transition-colors">
          Close
        </button>
      </div>
    )
  }

  return (
    <div className="space-y-3">
      {/* Category selector */}
      <div>
        <label className="text-xs text-gray-400 block mb-2">Category</label>
        <div className="grid grid-cols-2 gap-2">
          {CHANGE_CATEGORIES.map(cat => (
            <button
              key={cat.value}
              onClick={() => { setCategory(cat.value); setChangeType('') }}
              className={`flex items-center gap-2 p-3 rounded-lg border text-left transition-all ${
                category === cat.value
                  ? 'border-cyan-500 bg-cyan-500/10 text-cyan-400'
                  : 'border-gray-700 text-gray-400 hover:border-gray-600 hover:text-gray-200'
              }`}
            >
              <span className="text-base">{cat.icon}</span>
              <span className="text-xs font-semibold">{cat.label}</span>
            </button>
          ))}
        </div>
      </div>

      {/* Change type selector */}
      {category && (
        <div>
          <label className="text-xs text-gray-400 block mb-2">Change Type</label>
          <select
            id="change-type"
            name="change-type"
            value={changeType}
            onChange={e => setChangeType(e.target.value)}
            className="w-full px-3 py-2 rounded-lg bg-gray-800 border border-gray-700 text-sm text-gray-200 focus:border-cyan-500 outline-none"
          >
            <option value="">Select type...</option>
            {availableTypes.map(ct => (
              <option key={ct.type} value={ct.type}>{ct.label}</option>
            ))}
          </select>
        </div>
      )}

      {/* Description */}
      {changeType && (
        <div>
          <label className="text-xs text-gray-400 block mb-2">Description (optional)</label>
          <textarea
            id="change-description"
            name="change-description"
            value={description}
            onChange={e => setDescription(e.target.value)}
            placeholder="e.g., Tightened Y-axis belt, it was too loose..."
            rows={2}
            className="w-full px-3 py-2 rounded-lg bg-gray-800 border border-gray-700 text-sm text-gray-200 placeholder:text-gray-500 focus:border-cyan-500 outline-none resize-none"
          />
        </div>
      )}

      {/* AI info box */}
      {selectedDef && (
        <div className="flex items-start gap-2 p-3 rounded-lg bg-cyan-500/5 border border-cyan-500/20 text-xs">
          <Info className="w-4 h-4 text-cyan-400 mt-0.5 flex-shrink-0" />
          <div className="text-gray-400 space-y-1">
            <p>AI will use this information to:</p>
            <ul className="list-disc list-inside space-y-0.5 ml-1">
              <li>Not confuse new data with old baselines</li>
              <li>Learn the new state correctly</li>
              <li>Not treat the change as a problem</li>
            </ul>
            {selectedDef.affectedComponents.length > 0 && (
              <p className="pt-1">
                Affected AI models: <span className="text-cyan-400 font-mono">{selectedDef.affectedComponents.join(', ')}</span>
              </p>
            )}
            <p>
              Estimated learning: <span className="text-cyan-400 font-semibold">~{selectedDef.learningHours} print hours</span>
            </p>
          </div>
        </div>
      )}

      {/* Error */}
      {submitAction.error && (
        <div className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 border border-red-500/30 text-xs text-red-400">
          <AlertTriangle className="w-4 h-4 flex-shrink-0" />
          {submitAction.error}
        </div>
      )}

      {/* Actions */}
      <div className="flex gap-2 pt-1">
        {onClose && (
          <button onClick={onClose} className="flex-1 py-2 text-sm rounded-lg border border-gray-700 text-gray-400 hover:text-gray-200 transition-colors">
            Cancel
          </button>
        )}
        <button
          onClick={() => submitAction.execute()}
          disabled={!changeType || submitAction.loading}
          className="flex-1 py-2 text-sm font-semibold rounded-lg bg-cyan-500 text-gray-900 hover:bg-cyan-400 disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
        >
          {submitAction.loading ? 'Registering...' : '✓ Register Change'}
        </button>
      </div>
    </div>
  )
}

export default ManualChangeForm
