import { useState } from 'react'
import { CheckCircle } from 'lucide-react'

export function ContactForm() {
  const [form, setForm] = useState({ name: '', email: '', subject: '', message: '' })
  const [submitted, setSubmitted] = useState(false)

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) =>
    setForm((prev) => ({ ...prev, [e.target.name]: e.target.value }))

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    setSubmitted(true)
  }

  const handleReset = () => {
    setSubmitted(false)
    setForm({ name: '', email: '', subject: '', message: '' })
  }

  if (submitted) {
    return (
      <div className="flex flex-col items-center justify-center py-12 text-center gap-4">
        <div className="w-16 h-16 rounded-full bg-green-500/20 flex items-center justify-center">
          <CheckCircle size={32} className="text-green-400" />
        </div>
        <h3 className="text-lg font-semibold text-white">Message Sent!</h3>
        <p className="text-gray-400 text-sm max-w-xs">
          Thanks for reaching out. We'll get back to you as soon as possible.
        </p>
        <button
          onClick={handleReset}
          className="mt-2 px-4 py-2 rounded-lg bg-cyan-500/20 text-cyan-400 text-sm hover:bg-cyan-500/30 transition-colors"
        >
          Send another message
        </button>
      </div>
    )
  }

  return (
    <form onSubmit={handleSubmit} className="space-y-4">
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <div>
          <label htmlFor="contact-name" className="block text-xs text-gray-400 mb-1.5">Name</label>
          <input
            id="contact-name" required name="name" autoComplete="name"
            value={form.name} onChange={handleChange}
            placeholder="Your name"
            className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-sm text-white placeholder-gray-500 focus:outline-none focus:border-cyan-500 transition-colors"
          />
        </div>
        <div>
          <label htmlFor="contact-email" className="block text-xs text-gray-400 mb-1.5">Email</label>
          <input
            id="contact-email" required type="email" name="email" autoComplete="email"
            value={form.email} onChange={handleChange}
            placeholder="you@example.com"
            className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-sm text-white placeholder-gray-500 focus:outline-none focus:border-cyan-500 transition-colors"
          />
        </div>
      </div>

      <div>
        <label htmlFor="contact-subject" className="block text-xs text-gray-400 mb-1.5">Subject</label>
        <select
          id="contact-subject" name="subject" autoComplete="off"
          value={form.subject} onChange={handleChange} required
          className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-sm text-white focus:outline-none focus:border-cyan-500 transition-colors"
        >
          <option value="">Select a topic…</option>
          <option value="bug">Bug Report</option>
          <option value="feature">Feature Request</option>
          <option value="connectivity">Connectivity Issue</option>
          <option value="ai">AI / Insights Question</option>
          <option value="other">Other</option>
        </select>
      </div>

      <div>
        <label htmlFor="contact-message" className="block text-xs text-gray-400 mb-1.5">Message</label>
        <textarea
          id="contact-message" required name="message" autoComplete="off"
          value={form.message} onChange={handleChange}
          rows={5}
          placeholder="Describe your issue or question in detail…"
          className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-sm text-white placeholder-gray-500 focus:outline-none focus:border-cyan-500 transition-colors resize-none"
        />
      </div>

      <button
        type="submit"
        className="w-full py-2.5 rounded-lg bg-cyan-500 hover:bg-cyan-400 text-gray-900 font-semibold text-sm transition-colors"
      >
        Send Message
      </button>
    </form>
  )
}
