// ═══════════════════════════════════════════════════════════════
// PRESTIGE DASHBOARD - HISTORY LIST
// SPEC: features/history/ — HistoryList
// Displays print job history with filtering and sorting
// ═══════════════════════════════════════════════════════════════

import { useState, useEffect, useMemo } from 'react'
import { History, Clock, CheckCircle, XCircle, AlertTriangle, Pause, Search, ChevronRight, ArrowLeft } from 'lucide-react'
import type { PrintJob } from '@core/types'

// ─── Types ────────────────────────────────────────────────────

// PrintJob imported from @core/types — single source of truth
export type { PrintJob } from '@core/types'

interface HistoryListProps {
  /** Filter by printer, or show all */
  printerId?: string
  /** Pre-fetched jobs — if provided, skips internal fetch (avoids duplicate API calls) */
  jobs?: PrintJob[]
}

// ─── Helpers ──────────────────────────────────────────────────

const STATUS_CONFIG: Record<string, { icon: typeof CheckCircle; color: string; label: string }> = {
  completed:  { icon: CheckCircle,   color: 'text-green-400',  label: 'Completed'  },
  failed:     { icon: XCircle,       color: 'text-red-400',   label: 'Failed'     },
  cancelled:  { icon: AlertTriangle, color: 'text-yellow-400', label: 'Cancelled'  },
  // 'cancelling' = JOB transient state: cancel requested, not yet finalised.
  // Distinct from printer.subStatus 'cancelling' which is a printer-level concept.
  cancelling: { icon: Pause,         color: 'text-orange-400', label: 'Cancelling' },
  printing:   { icon: Clock,         color: 'text-cyan-400',  label: 'Printing'   },
}

function formatDuration(seconds: number): string {
  const h = Math.floor(seconds / 3600)
  const m = Math.floor((seconds % 3600) / 60)
  if (h > 0) return `${h}h ${m}m`
  return `${m}m`
}

// ─── Component ────────────────────────────────────────────────

export function HistoryList({ printerId, jobs: jobsProp }: HistoryListProps) {
  const [jobs, setJobs] = useState<PrintJob[]>(jobsProp ?? [])
  const [loading, setLoading] = useState(jobsProp === undefined)
  const [searchQuery, setSearchQuery] = useState('')
  const [statusFilter, setStatusFilter] = useState<string>('all')
  const [selectedJob, setSelectedJob] = useState<PrintJob | null>(null)

  // Sync if parent updates the prop (e.g. re-fetch)
  useEffect(() => {
    if (jobsProp !== undefined) {
      setJobs(jobsProp)
      setLoading(false)
    }
  }, [jobsProp])

  // Only fetch internally when no jobs prop is provided
  useEffect(() => {
    if (jobsProp !== undefined) return
    const fetchHistory = async () => {
      setLoading(true)
      try {
        // NOTE: Backend has no global history endpoint.
        // HistoryList without printerId should receive pre-fetched jobs from parent (HistoryPage).
        // If called standalone without printerId, silently return empty — do not call a 404 route.
        if (!printerId) { setLoading(false); return }
        const url = `/api/printers/${printerId}/jobs`
        const res = await fetch(url)
        if (res.ok) {
          const data = await res.json()
          // Backend wraps in { data: ... } — unwrap if needed
          const payload = data?.data ?? data
          setJobs(payload?.jobs ?? (Array.isArray(payload) ? payload : []))
        }
        // Non-OK (e.g. 404) — stay with empty list, no throw
      } catch {
        // Network error — stay with empty list
      } finally {
        setLoading(false)
      }
    }
    fetchHistory()
  }, [printerId, jobsProp])

  const filteredJobs = useMemo(() => {
    let result = jobs
    if (statusFilter !== 'all') {
      result = result.filter(j => j.status === statusFilter)
    }
    if (searchQuery.trim()) {
      const q = searchQuery.toLowerCase()
      result = result.filter(j =>
        j.filename.toLowerCase().includes(q) ||
        j.printerName?.toLowerCase().includes(q)
      )
    }
    // Sort by start time descending
    return result.sort((a, b) => new Date(b.startTime).getTime() - new Date(a.startTime).getTime())
  }, [jobs, statusFilter, searchQuery])

  // Stats
  const stats = useMemo(() => ({
    total: jobs.length,
    completed: jobs.filter(j => j.status === 'completed').length,
    failed: jobs.filter(j => j.status === 'failed').length,
    totalTime: jobs.reduce((s, j) => s + (j.duration || 0), 0),
    successRate: jobs.length > 0
      ? ((jobs.filter(j => j.status === 'completed').length / jobs.length) * 100).toFixed(0)
      : '0',
  }), [jobs])

  // Detail view
  if (selectedJob) {
    return (
      <div className="space-y-4">
        <button
          onClick={() => setSelectedJob(null)}
          className="flex items-center gap-2 text-sm text-gray-400 hover:text-gray-200 transition-colors"
        >
          <ArrowLeft className="w-4 h-4" /> Back to history
        </button>
        <div className="bg-gray-900/50 border border-gray-700 rounded-lg p-4 space-y-3">
          <h2 className="text-base font-semibold text-gray-200 truncate">{selectedJob.filename}</h2>
          <div className="grid grid-cols-2 gap-3 text-sm">
            <div><span className="text-gray-400">Printer: </span><span className="text-gray-200">{selectedJob.printerName}</span></div>
            <div><span className="text-gray-400">Status: </span><span className={`font-medium ${STATUS_CONFIG[selectedJob.status]?.color ?? 'text-gray-200'}`}>{STATUS_CONFIG[selectedJob.status]?.label ?? selectedJob.status}</span></div>
            <div><span className="text-gray-400">Started: </span><span className="text-gray-200">{new Date(selectedJob.startTime).toLocaleString()}</span></div>
            {selectedJob.endTime && <div><span className="text-gray-400">Ended: </span><span className="text-gray-200">{new Date(selectedJob.endTime).toLocaleString()}</span></div>}
            {selectedJob.duration && <div><span className="text-gray-400">Duration: </span><span className="text-gray-200">{formatDuration(selectedJob.duration)}</span></div>}
            {selectedJob.progress !== undefined && <div><span className="text-gray-400">Progress: </span><span className="text-gray-200">{selectedJob.progress}%</span></div>}
            {selectedJob.filamentUsed && <div><span className="text-gray-400">Filament: </span><span className="text-gray-200">{selectedJob.filamentUsed.toFixed(0)} mm</span></div>}
          </div>
          {selectedJob.metadata && (
            <div className="pt-2 border-t border-gray-700 text-sm space-y-1">
              {selectedJob.metadata.layerHeight && <div><span className="text-gray-400">Layer height: </span><span className="text-gray-200">{selectedJob.metadata.layerHeight} mm</span></div>}
              {selectedJob.metadata.totalLayers && <div><span className="text-gray-400">Total layers: </span><span className="text-gray-200">{selectedJob.metadata.totalLayers}</span></div>}
            </div>
          )}
        </div>
      </div>
    )
  }

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="bg-gray-900/50 border border-gray-700 rounded-lg p-4">
        <div className="flex items-center gap-2 mb-4">
          <History className="w-5 h-5 text-cyan-400" />
          <h2 className="text-sm font-semibold text-gray-200">Print History</h2>
          <span className="text-xs text-gray-400">({filteredJobs.length})</span>
        </div>

        {/* Stats */}
        <div className="grid grid-cols-4 gap-3">
          {[
            { label: 'TOTAL PRINTS', value: stats.total, color: 'text-gray-200' },
            { label: 'SUCCESS RATE', value: `${stats.successRate}%`, color: 'text-green-400' },
            { label: 'FAILED', value: stats.failed, color: 'text-red-400' },
            { label: 'TOTAL TIME', value: formatDuration(stats.totalTime), color: 'text-yellow-400' },
          ].map(s => (
            <div key={s.label} className="bg-gray-800/50 rounded-lg p-3 text-center">
              <div className="text-xs text-gray-400 mb-1">{s.label}</div>
              <div className={`text-xl font-bold font-mono ${s.color}`}>{s.value}</div>
            </div>
          ))}
        </div>
      </div>

      {/* Search + Filter */}
      <div className="flex gap-2">
        <div className="flex-1 flex items-center gap-2 px-3 py-2 rounded-lg border border-gray-700 bg-gray-900/50">
          <Search className="w-3.5 h-3.5 text-gray-400" />
          <input
            id="history-search"
            name="history-search"
            type="text"
            value={searchQuery}
            onChange={e => setSearchQuery(e.target.value)}
            placeholder="Search by filename..."
            className="flex-1 bg-transparent text-sm text-gray-200 placeholder:text-gray-500 outline-none"
          />
        </div>
        <div className="flex rounded-lg border border-gray-700 bg-gray-900/50 overflow-hidden">
          {['all', 'completed', 'failed', 'cancelled'].map(f => (
            <button
              key={f}
              onClick={() => setStatusFilter(f)}
              className={`px-3 py-2 text-xs transition-colors ${
                statusFilter === f ? 'bg-cyan-500/20 text-cyan-400' : 'text-gray-400 hover:text-gray-200'
              }`}
            >
              {f === 'all' ? 'All' : f.charAt(0).toUpperCase() + f.slice(1)}
            </button>
          ))}
        </div>
      </div>

      {/* Job list */}
      {loading ? (
        <div className="py-8 text-center text-gray-400 text-sm">Loading history...</div>
      ) : filteredJobs.length === 0 ? (
        <div className="py-8 text-center text-gray-400">
          <History className="w-10 h-10 mx-auto mb-2 opacity-20" />
          <p className="text-sm">No print jobs found</p>
        </div>
      ) : (
        <div className="space-y-2">
          {filteredJobs.map(job => {
            const cfg = STATUS_CONFIG[job.status] || STATUS_CONFIG.completed
            const StatusIcon = cfg.icon
            const date = new Date(job.startTime)

            return (
              <button
                key={job.id}
                onClick={() => setSelectedJob(job)}
                className="w-full flex items-center gap-3 px-4 py-3 rounded-lg border border-gray-700 bg-gray-900/50 hover:bg-gray-800/50 transition-colors text-left"
              >
                <StatusIcon className={`w-4 h-4 flex-shrink-0 ${cfg.color}`} />
                <div className="flex-1 min-w-0">
                  <div className="text-sm text-gray-200 truncate">{job.filename}</div>
                  <div className="text-xs text-gray-400">
                    {job.printerName && <>{job.printerName} · </>}
                    {date.toLocaleDateString(undefined, { month: 'short', day: 'numeric' })}
                    {job.duration && <> · {formatDuration(job.duration)}</>}
                  </div>
                </div>
                <ChevronRight className="w-4 h-4 text-gray-400 flex-shrink-0" />
              </button>
            )
          })}
        </div>
      )}
    </div>
  )
}

export default HistoryList
