import React, { useState, useMemo } from 'react'
import { RouteCard } from './RouteCard'
import { ROUTES, ROUTE_MODULES, CRITS, critColor, methodColor, moduleColor, moduleLabel } from './arch-data'
import type { Criticality, HttpMethod, RouteModule } from './arch-types'

type MethodFilter = HttpMethod | 'ALL'
type CritFilter   = Criticality | 'ALL'
type ModFilter    = RouteModule | 'ALL'

export function RouteExplorer() {
  const [expanded, setExpanded]   = useState<Set<string>>(new Set())
  const [search, setSearch]       = useState('')
  const [filterMod, setFilterMod] = useState<ModFilter>('ALL')
  const [filterCrit, setFilterCrit] = useState<CritFilter>('ALL')

  const toggle = (id: string) =>
    setExpanded(prev => { const s = new Set(prev); s.has(id) ? s.delete(id) : s.add(id); return s })

  const filtered = useMemo(() => {
    const q = search.toLowerCase()
    return ROUTES.filter(r => {
      if (filterMod  !== 'ALL' && r.module      !== filterMod)  return false
      if (filterCrit !== 'ALL' && r.criticality !== filterCrit) return false
      if (!q) return true
      return (
        r.path.toLowerCase().includes(q) ||
        r.description.toLowerCase().includes(q) ||
        (r.frontendService ?? '').toLowerCase().includes(q) ||
        (r.frontendPages ?? []).some(p => p.toLowerCase().includes(q))
      )
    })
  }, [search, filterMod, filterCrit])

  const warnCount = ROUTES.filter(r => r.warnings?.length).length

  return (
    <div style={{ display: 'flex', height: '100%', overflow: 'hidden', fontFamily: "'Consolas','Fira Code',monospace" }}>

      {/* ── Left sidebar ────────────────────────────────────────────────────── */}
      <div style={{
        width: '180px', flexShrink: 0,
        background: '#07111f',
        borderRight: '1px solid #1a3550',
        overflowY: 'auto', padding: '8px 0',
      }}>
        {/* Modules */}
        <div style={{ padding: '4px 12px 6px', fontSize: '8px', color: '#1e3a5f', letterSpacing: '0.2em', fontWeight: 'bold' }}>
          MODULES
        </div>
        {(['ALL', ...ROUTE_MODULES] as ModFilter[]).map(m => {
          const color = m === 'ALL' ? '#22d3ee' : moduleColor(m)
          const count = m === 'ALL' ? ROUTES.length : ROUTES.filter(r => r.module === m).length
          const active = filterMod === m
          return (
            <button key={m} onClick={() => setFilterMod(m)} style={{
              width: '100%', background: active ? `${color}10` : 'transparent',
              border: 'none', borderLeft: active ? `2px solid ${color}` : '2px solid transparent',
              padding: '6px 12px', cursor: 'pointer',
              display: 'flex', alignItems: 'center', gap: '6px',
              fontSize: '10.5px', color: active ? color : '#334155',
              textAlign: 'left', transition: 'all 0.1s',
            }}>
              <span style={{ width: 5, height: 5, borderRadius: '50%', background: color, flexShrink: 0 }} />
              <span style={{ flex: 1, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                {m === 'ALL' ? 'All routes' : moduleLabel(m)}
              </span>
              <span style={{ fontSize: '9px', color, background: `${color}15`, padding: '0 4px', borderRadius: '3px' }}>{count}</span>
            </button>
          )
        })}

        {/* Criticality */}
        <div style={{ padding: '10px 12px 6px', fontSize: '8px', color: '#1e3a5f', letterSpacing: '0.2em', fontWeight: 'bold' }}>
          CRITICALITY
        </div>
        {(['ALL', ...CRITS] as CritFilter[]).map(c => {
          const color = c === 'ALL' ? '#22d3ee' : critColor(c)
          const count = c === 'ALL' ? ROUTES.length : ROUTES.filter(r => r.criticality === c).length
          const active = filterCrit === c
          return (
            <button key={c} onClick={() => setFilterCrit(c)} style={{
              width: '100%', background: active ? `${color}10` : 'transparent',
              border: 'none', borderLeft: active ? `2px solid ${color}` : '2px solid transparent',
              padding: '6px 12px', cursor: 'pointer',
              display: 'flex', alignItems: 'center',
              fontSize: '10.5px', color: active ? color : '#334155',
              textAlign: 'left', transition: 'all 0.1s',
            }}>
              <span style={{ flex: 1 }}>{c === 'ALL' ? 'All' : c}</span>
              <span style={{ fontSize: '9px', color, background: `${color}15`, padding: '0 4px', borderRadius: '3px' }}>{count}</span>
            </button>
          )
        })}

        {/* Warnings shortcut */}
        <div style={{ padding: '10px 12px 6px', fontSize: '8px', color: '#1e3a5f', letterSpacing: '0.2em', fontWeight: 'bold' }}>
          ⚠ WARNINGS ({warnCount})
        </div>
        {ROUTES.filter(r => r.warnings?.length).map(r => (
          <button key={r.id}
            onClick={() => setExpanded(s => { const n = new Set(s); n.add(r.id); return n })}
            style={{
              width: '100%', background: 'transparent', border: 'none',
              padding: '4px 12px', cursor: 'pointer', textAlign: 'left',
              fontSize: '9.5px', color: '#f59e0b',
              overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
            }}
          >
            ⚠ {r.path.replace('/api/', '')}
          </button>
        ))}
      </div>

      {/* ── Main content ─────────────────────────────────────────────────────── */}
      <div style={{ flex: 1, display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>

        {/* Toolbar */}
        <div style={{
          padding: '10px 14px', borderBottom: '1px solid #0f1e30',
          display: 'flex', gap: '8px', alignItems: 'center', flexShrink: 0,
        }}>
          <input
            style={{
              background: '#0a1525', border: '1px solid #1a3550', borderRadius: '6px',
              padding: '6px 12px', color: '#c8d8e8', fontFamily: 'inherit', fontSize: '11.5px',
              outline: 'none', flex: 1,
            }}
            placeholder="🔍  Search by path, service, page..."
            value={search}
            onChange={e => setSearch(e.target.value)}
          />
          <button
            onClick={() => setExpanded(new Set(filtered.map(r => r.id)))}
            style={{
              background: '#0a1525', border: '1px solid #22d3ee30', color: '#22d3ee',
              padding: '6px 12px', borderRadius: '6px', cursor: 'pointer',
              fontFamily: 'inherit', fontSize: '10.5px', whiteSpace: 'nowrap',
            }}
          >
            Expand all
          </button>
          <button
            onClick={() => setExpanded(new Set())}
            style={{
              background: '#0a1525', border: '1px solid #1a3550', color: '#475569',
              padding: '6px 12px', borderRadius: '6px', cursor: 'pointer',
              fontFamily: 'inherit', fontSize: '10.5px', whiteSpace: 'nowrap',
            }}
          >
            Collapse
          </button>
          <span style={{ fontSize: '10px', color: '#334155', whiteSpace: 'nowrap' }}>
            {filtered.length} / {ROUTES.length}
          </span>
        </div>

        {/* Route list */}
        <div style={{ flex: 1, overflowY: 'auto', padding: '12px 14px' }}>
          {filtered.map(route => (
            <RouteCard
              key={route.id}
              route={route}
              expanded={expanded.has(route.id)}
              onToggle={() => toggle(route.id)}
            />
          ))}

          {filtered.length === 0 && (
            <div style={{ textAlign: 'center', padding: '50px', color: '#1e3a5f', fontSize: '12px' }}>
              No routes match the current filters
            </div>
          )}

          {/* WebSocket events */}
          <div style={{ marginTop: '20px', background: '#0a1525', border: '1px solid #1a3550', borderRadius: '8px', padding: '14px' }}>
            <div style={{ fontSize: '9px', color: '#8b5cf6', letterSpacing: '0.2em', marginBottom: '10px', fontWeight: 'bold' }}>
              ⚡ WEBSOCKET EVENTS
            </div>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(175px, 1fr))', gap: '6px' }}>
              {[
                ['printer_state_update', 'BE→FE', 'State changes'],
                ['printer_connected',    'BE→FE', 'Printer connected'],
                ['printer_disconnected', 'BE→FE', 'Printer disconnected'],
                ['print_started',        'BE→FE', 'Print job started'],
                ['print_completed',      'BE→FE', 'Print job done'],
                ['ai_recommendation',    'BE→FE', 'New AI recommendation'],
                ['anomaly_detected',     'BE→FE', 'Anomaly found'],
                ['ping',                 'FE→BE', 'Heartbeat 30s'],
                ['pong',                 'BE→FE', 'Heartbeat reply'],
              ].map(([ev, dir, desc]) => (
                <div key={ev} style={{ background: '#060e18', border: '1px solid #1a3550', borderRadius: '4px', padding: '6px 8px' }}>
                  <code style={{ color: '#8b5cf6', fontSize: '9.5px', display: 'block' }}>{ev}</code>
                  <div style={{ fontSize: '8.5px', color: '#38bdf8', marginTop: 2 }}>{dir}</div>
                  <div style={{ fontSize: '8.5px', color: '#1e3a5f' }}>{desc}</div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}
