import React from 'react'
import { useTranslation } from 'react-i18next'
import { Settings } from 'lucide-react'
import { SettingsSection } from './SettingsSection'

export interface GeneralSettingsProps {
  className?: string
}

export const GeneralSettings: React.FC<GeneralSettingsProps> = ({ className = '' }) => {
  const { t, i18n } = useTranslation()

  // Normalize language code (e.g., 'lv-LV' → 'lv')
  const currentLang = (i18n.language || 'lv').split('-')[0]

  const handleLanguageChange = async (lang: string) => {
    await i18n.changeLanguage(lang)
    // Use same key as i18n config detection (prestige_language)
    localStorage.setItem('prestige_language', lang)
  }

  return (
    <SettingsSection
      title={t('settings.general.title', 'General Settings')}
      description={t('settings.general.description', 'Language and interface preferences')}
      icon={<Settings className="w-5 h-5" />}
      className={className}
    >
      <div className="space-y-6">
        {/* Language */}
        <div>
          <label className="block text-sm font-medium text-gray-200 mb-2">
            {t('settings.general.language', 'Language')}
          </label>
          <select
            value={currentLang}
            onChange={(e) => handleLanguageChange(e.target.value)}
            className="input max-w-xs"
          >
            <option value="lv">Latviešu</option>
            <option value="en">English</option>
          </select>
        </div>
      </div>
    </SettingsSection>
  )
}

export default GeneralSettings
