// ═══════════════════════════════════════════════════════════════
// PRESTIGE DASHBOARD - TOAST NOTIFICATIONS
// ═══════════════════════════════════════════════════════════════

import React, { useEffect } from 'react'
import { X, CheckCircle, AlertCircle, AlertTriangle, Info, Activity } from 'lucide-react'
import { useUIStore, selectToasts } from '@core/state/uiStore'
import type { Toast } from '@core/types'

const typeConfig = {
  success: {
    icon: CheckCircle,
    bgColor: 'bg-green-500/10',
    borderColor: 'border-green-500/30',
    textColor: 'text-green-400',
    iconColor: 'text-green-400',
  },
  error: {
    icon: AlertCircle,
    bgColor: 'bg-red-500/10',
    borderColor: 'border-red-500/30',
    textColor: 'text-red-400',
    iconColor: 'text-red-400',
  },
  warning: {
    icon: AlertTriangle,
    bgColor: 'bg-yellow-500/10',
    borderColor: 'border-yellow-500/30',
    textColor: 'text-yellow-400',
    iconColor: 'text-yellow-400',
  },
  info: {
    icon: Info,
    bgColor: 'bg-cyan-500/10',
    borderColor: 'border-cyan-500/30',
    textColor: 'text-cyan-400',
    iconColor: 'text-cyan-400',
  },
}

interface ToastItemProps {
  toast: Toast
  onDismiss: (id: string) => void
}

function ToastItem({ toast, onDismiss }: ToastItemProps) {
  const config = typeConfig[toast.type]
  const Icon = config.icon

  // Auto-dismiss after duration
  useEffect(() => {
    if (toast.duration && toast.duration > 0) {
      const timer = setTimeout(() => {
        onDismiss(toast.id)
      }, toast.duration)

      return () => clearTimeout(timer)
    }
  }, [toast.id, toast.duration, onDismiss])

  return (
    <div
      className={`${config.bgColor} ${config.borderColor} border rounded-lg p-4 shadow-lg backdrop-blur-sm mb-3 min-w-[320px] max-w-md animate-slide-in-right`}
      role="alert"
    >
      <div className="flex items-start gap-3">
        <Icon className={`w-5 h-5 ${config.iconColor} flex-shrink-0 mt-0.5`} />
        
        <div className="flex-1 min-w-0">
          <h4 className={`font-semibold ${config.textColor} text-sm`}>
            {toast.title}
          </h4>
          {toast.message && (
            <p className="text-gray-300 text-sm mt-1">
              {toast.message}
            </p>
          )}
          
          {toast.actions && toast.actions.length > 0 && (
            <div className="flex gap-2 mt-3">
              {toast.actions.map((action, idx) => (
                <button
                  key={idx}
                  onClick={() => {
                    action.onClick()
                    onDismiss(toast.id)
                  }}
                  className={`px-3 py-1 text-xs font-medium ${config.textColor} border ${config.borderColor} rounded hover:bg-white/5 transition-colors`}
                >
                  {action.label}
                </button>
              ))}
            </div>
          )}
        </div>

        <button
          onClick={() => onDismiss(toast.id)}
          className="text-gray-400 hover:text-gray-200 transition-colors flex-shrink-0"
          aria-label="Dismiss notification"
        >
          <X className="w-4 h-4" />
        </button>
      </div>

      {/* Progress bar for timed toasts */}
      {toast.duration && toast.duration > 0 && (
        <div className="mt-3 h-1 bg-gray-700 rounded-full overflow-hidden">
          <div
            className={`h-full ${config.bgColor.replace('/10', '/50')} animate-progress`}
            style={{
              animation: `progress ${toast.duration}ms linear`,
            }}
          />
        </div>
      )}
    </div>
  )
}

export function ToastContainer() {
  const toasts = useUIStore(selectToasts)
  const { removeNotification } = useUIStore()

  if (toasts.length === 0) return null

  return (
    <div className="fixed top-6 right-6 z-50 pointer-events-none">
      <div className="pointer-events-auto">
        {toasts.map((toast) => (
          <ToastItem
            key={toast.id}
            toast={toast}
            onDismiss={removeNotification}
          />
        ))}
      </div>
    </div>
  )
}

export default ToastContainer
