// ═══════════════════════════════════════════════════════════════
// PRESTIGE DASHBOARD - TEMPERATURE GAUGE COMPONENT
// ═══════════════════════════════════════════════════════════════

import React, { useMemo } from 'react'
import type {
  TemperatureGaugeProps,
  TempComponentType,
  TempGaugeSize,
  TempGaugeMode,
  TempStatus,
  TempColorConfig,
  TempComponentConfig,
} from './TemperatureGauge.types'

/**
 * Component-specific configuration
 */
const COMPONENT_CONFIG: Record<TempComponentType, TempComponentConfig> = {
  hotend: {
    icon: '🔥',
    label: 'Hotend',
    defaultMax: 300,
    warningThreshold: 250,
    dangerThreshold: 280,
  },
  bed: {
    icon: '🟦',
    label: 'Bed',
    defaultMax: 120,
    warningThreshold: 100,
    dangerThreshold: 110,
  },
  chamber: {
    icon: '📦',
    label: 'Chamber',
    defaultMax: 70,
    warningThreshold: 60,
    dangerThreshold: 65,
  },
}

/**
 * Size configuration
 */
const SIZE_CONFIG: Record<TempGaugeSize, { text: string; bar: string; icon: string; gap: string }> = {
  sm: {
    text: 'text-xs',
    bar: 'h-1.5',
    icon: 'text-sm',
    gap: 'gap-1',
  },
  md: {
    text: 'text-sm',
    bar: 'h-2',
    icon: 'text-base',
    gap: 'gap-1.5',
  },
  lg: {
    text: 'text-base',
    bar: 'h-2.5',
    icon: 'text-lg',
    gap: 'gap-2',
  },
  xl: {
    text: 'text-lg',
    bar: 'h-3',
    icon: 'text-xl',
    gap: 'gap-2.5',
  },
}

/**
 * Calculate temperature status
 */
const getTempStatus = (current: number, target: number): TempStatus => {
  const diff = Math.abs(current - target)
  const tolerance = 2 // degrees

  if (target === 0) {
    return current < 40 ? 'cold' : 'cooling'
  }

  if (diff <= tolerance) {
    return 'ready'
  }

  if (current < target) {
    return 'heating'
  }

  return 'cooling'
}

/**
 * Get color configuration based on temperature and status
 */
const getColorConfig = (
  current: number,
  target: number,
  status: TempStatus,
  maxTemp: number
): TempColorConfig => {
  // Error state (over max)
  if (current > maxTemp) {
    return {
      color: '#f00',
      glowColor: 'rgba(255, 0, 0, 0.5)',
      bgColor: 'rgba(255, 0, 0, 0.1)',
      borderColor: 'rgba(255, 0, 0, 0.3)',
      label: 'ERROR',
    }
  }

  // Temperature-based coloring (cold to hot)
  const ratio = current / maxTemp

  if (ratio < 0.2) {
    // Cold - Blue
    return {
      color: '#0ff',
      glowColor: 'rgba(0, 255, 255, 0.3)',
      bgColor: 'rgba(0, 255, 255, 0.05)',
      borderColor: 'rgba(0, 255, 255, 0.2)',
      label: 'COLD',
    }
  }

  if (ratio < 0.5) {
    // Warming - Cyan/Green
    return {
      color: '#0f0',
      glowColor: 'rgba(0, 255, 0, 0.3)',
      bgColor: 'rgba(0, 255, 0, 0.05)',
      borderColor: 'rgba(0, 255, 0, 0.2)',
      label: status === 'heating' ? 'HEATING' : 'WARM',
    }
  }

  if (ratio < 0.75) {
    // Hot - Yellow/Orange
    return {
      color: '#ff0',
      glowColor: 'rgba(255, 255, 0, 0.3)',
      bgColor: 'rgba(255, 255, 0, 0.05)',
      borderColor: 'rgba(255, 255, 0, 0.2)',
      label: status === 'ready' ? 'READY' : 'HOT',
    }
  }

  // Very hot - Red/Orange
  return {
    color: '#f80',
    glowColor: 'rgba(255, 136, 0, 0.3)',
    bgColor: 'rgba(255, 136, 0, 0.05)',
    borderColor: 'rgba(255, 136, 0, 0.2)',
    label: status === 'ready' ? 'READY' : 'V.HOT',
  }
}

/**
 * TemperatureGauge Component
 * Displays temperature readings with visual gauge
 */
export const TemperatureGauge: React.FC<TemperatureGaugeProps> = ({
  type,
  reading,
  size = 'md',
  mode = 'full',
  showPower = true,
  showLabel = true,
  maxTemp,
  className = '',
  onClick,
}) => {
  const config = COMPONENT_CONFIG[type]
  const sizeConfig = SIZE_CONFIG[size]
  const effectiveMaxTemp = maxTemp || config.defaultMax

  const { current = 0, target = 0, power } = reading ?? {}

  // Calculate status and colors
  const status = useMemo(() => getTempStatus(current, target), [current, target])
  const colorConfig = useMemo(
    () => getColorConfig(current, target, status, effectiveMaxTemp),
    [current, target, status, effectiveMaxTemp]
  )

  // Calculate progress percentage
  const progress = Math.min((current / effectiveMaxTemp) * 100, 100)
  const targetProgress = Math.min((target / effectiveMaxTemp) * 100, 100)

  // Minimal mode (just numbers)
  if (mode === 'minimal') {
    return (
      <div
        className={`inline-flex items-center ${sizeConfig.gap} ${className}`}
        onClick={onClick}
        style={{ cursor: onClick ? 'pointer' : 'default' }}
      >
        <span className={sizeConfig.icon}>{config.icon}</span>
        <span
          className={`font-mono font-bold ${sizeConfig.text}`}
          style={{ color: colorConfig.color }}
        >
          {current.toFixed(1)}°
        </span>
        {target > 0 && (
          <span className={`font-mono ${sizeConfig.text} text-gray-500`}>
            / {target.toFixed(0)}°
          </span>
        )}
      </div>
    )
  }

  // Compact mode (small gauge)
  if (mode === 'compact') {
    return (
      <div
        className={`flex flex-col ${sizeConfig.gap} ${className}`}
        onClick={onClick}
        style={{ cursor: onClick ? 'pointer' : 'default' }}
      >
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-1.5">
            <span className={sizeConfig.icon}>{config.icon}</span>
            {showLabel && (
              <span className={`font-medium ${sizeConfig.text} text-gray-400`}>
                {config.label}
              </span>
            )}
          </div>
          <div className="flex items-center gap-1.5">
            <span
              className={`font-mono font-bold ${sizeConfig.text}`}
              style={{ color: colorConfig.color }}
            >
              {current.toFixed(1)}°
            </span>
            {target > 0 && (
              <span className={`font-mono ${sizeConfig.text} text-gray-500`}>
                / {target.toFixed(0)}°
              </span>
            )}
          </div>
        </div>
        
        {/* Progress bar */}
        <div
          className={`relative w-full ${sizeConfig.bar} rounded-full overflow-hidden`}
          style={{
            backgroundColor: 'rgba(255, 255, 255, 0.05)',
            border: `1px solid ${colorConfig.borderColor}`,
          }}
        >
          {/* Target indicator */}
          {target > 0 && (
            <div
              className="absolute top-0 w-0.5 h-full bg-gray-500"
              style={{ left: `${targetProgress}%` }}
            />
          )}
          {/* Current temperature bar */}
          <div
            className={`h-full transition-all duration-300 ${status === 'heating' ? 'animate-pulse' : ''}`}
            style={{
              width: `${progress}%`,
              backgroundColor: colorConfig.color,
              boxShadow: `0 0 8px ${colorConfig.glowColor}`,
            }}
          />
        </div>

        {/* Power indicator */}
        {showPower && power !== undefined && (
          <div className="flex items-center justify-end gap-1">
            <span className="text-xs text-gray-500">PWR:</span>
            <span className="text-xs font-mono" style={{ color: colorConfig.color }}>
              {(power * 100).toFixed(0)}%
            </span>
          </div>
        )}
      </div>
    )
  }

  // Full mode (detailed display)
  return (
    <div
      className={`flex flex-col ${sizeConfig.gap} p-3 rounded-lg border ${className}`}
      onClick={onClick}
      style={{
        backgroundColor: colorConfig.bgColor,
        borderColor: colorConfig.borderColor,
        cursor: onClick ? 'pointer' : 'default',
      }}
    >
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <span className={sizeConfig.icon}>{config.icon}</span>
          <span className={`font-medium ${sizeConfig.text} text-gray-300`}>
            {config.label}
          </span>
        </div>
        <span
          className={`text-xs font-bold px-2 py-0.5 rounded`}
          style={{
            color: colorConfig.color,
            backgroundColor: colorConfig.bgColor,
            border: `1px solid ${colorConfig.borderColor}`,
          }}
        >
          {colorConfig.label}
        </span>
      </div>

      {/* Temperature display */}
      <div className="flex items-baseline gap-2">
        <span
          className={`font-mono font-bold text-2xl`}
          style={{
            color: colorConfig.color,
            textShadow: `0 0 10px ${colorConfig.glowColor}`,
          }}
        >
          {current.toFixed(1)}°C
        </span>
        {target > 0 && (
          <>
            <span className="text-gray-500">/</span>
            <span className="font-mono text-lg text-gray-400">
              {target.toFixed(0)}°C
            </span>
          </>
        )}
      </div>

      {/* Progress bar */}
      <div
        className={`relative w-full ${sizeConfig.bar} rounded-full overflow-hidden`}
        style={{
          backgroundColor: 'rgba(255, 255, 255, 0.05)',
          border: `1px solid ${colorConfig.borderColor}`,
        }}
      >
        {/* Target indicator */}
        {target > 0 && (
          <div
            className="absolute top-0 w-1 h-full bg-gray-400 z-10"
            style={{ left: `${targetProgress}%` }}
            title={`Target: ${target}°C`}
          />
        )}
        {/* Current temperature bar */}
        <div
          className={`h-full transition-all duration-500 ${status === 'heating' ? 'animate-pulse' : ''}`}
          style={{
            width: `${progress}%`,
            backgroundColor: colorConfig.color,
            boxShadow: `0 0 12px ${colorConfig.glowColor}`,
          }}
        />
      </div>

      {/* Footer info */}
      <div className="flex items-center justify-between text-xs">
        <span className="text-gray-500">
          Max: {effectiveMaxTemp}°C
        </span>
        {showPower && power !== undefined && (
          <div className="flex items-center gap-1.5">
            <span className="text-gray-500">Power:</span>
            <span className="font-mono font-medium" style={{ color: colorConfig.color }}>
              {(power * 100).toFixed(0)}%
            </span>
          </div>
        )}
      </div>
    </div>
  )
}

TemperatureGauge.displayName = 'TemperatureGauge'

export default TemperatureGauge
