// PRESTIGE DASHBOARD - PRINT STATISTICS
// SPEC: features/history/ — Statistics
// Visual charts and aggregated stats for print history
// Uses recharts (already in project for PrinterDetailPage)
// ═══════════════════════════════════════════════════════════════

import { useState, useMemo, useEffect } from 'react'
import {
  BarChart3, TrendingUp, Clock, CheckCircle, XCircle, Printer as PrinterIcon,
  Calendar, ChevronDown,
} from 'lucide-react'

// ─── Types ────────────────────────────────────────────────────

interface PrintJob {
  id: string
  printerId: string
  printerName: string
  filename: string
  status: 'completed' | 'failed' | 'cancelled' | 'cancelling' | 'printing'
  startTime: string
  endTime?: string
  duration?: number
  filamentUsed?: number
}

interface StatisticsProps {
  /** All print jobs to analyze */
  jobs: PrintJob[]
  /** Time period for analysis */
  period?: '7d' | '30d' | '90d' | 'all'
  /** Optional printer filter */
  printerId?: string
}

type Period = '7d' | '30d' | '90d' | 'all'

// ─── Helpers ──────────────────────────────────────────────────

function formatDuration(seconds: number): string {
  const h = Math.floor(seconds / 3600)
  const m = Math.floor((seconds % 3600) / 60)
  if (h > 0) return `${h}h ${m}m`
  return `${m}m`
}

function formatFilament(mm: number): string {
  if (mm >= 1000) return `${(mm / 1000).toFixed(1)}m`
  return `${mm.toFixed(0)}mm`
}

function getDaysAgo(days: number): Date {
  const d = new Date()
  d.setDate(d.getDate() - days)
  d.setHours(0, 0, 0, 0)
  return d
}

function getWeekLabel(date: Date): string {
  return date.toLocaleDateString(undefined, { month: 'short', day: 'numeric' })
}

// ─── Computed analytics ───────────────────────────────────────

function computeAnalytics(jobs: PrintJob[], period: Period) {
  // Filter by period
  let cutoff: Date | null = null
  if (period === '7d') cutoff = getDaysAgo(7)
  else if (period === '30d') cutoff = getDaysAgo(30)
  else if (period === '90d') cutoff = getDaysAgo(90)

  const filtered = cutoff
    ? jobs.filter(j => new Date(j.startTime) >= cutoff!)
    : jobs

  // Basic counts
  const total = filtered.length
  const completed = filtered.filter(j => j.status === 'completed').length
  const failed = filtered.filter(j => j.status === 'failed').length
  const cancelled = filtered.filter(j => j.status === 'cancelled').length
  const successRate = total > 0 ? (completed / total) * 100 : 0

  // Time totals
  const totalPrintTime = filtered.reduce((s, j) => s + (j.duration || 0), 0)
  const avgPrintTime = completed > 0
    ? filtered.filter(j => j.status === 'completed').reduce((s, j) => s + (j.duration || 0), 0) / completed
    : 0

  // Filament
  const totalFilament = filtered.reduce((s, j) => s + (j.filamentUsed || 0), 0)

  // Per-printer breakdown
  const printerMap = new Map<string, { name: string; total: number; completed: number; failed: number; time: number }>()
  for (const j of filtered) {
    const key = j.printerId
    const existing = printerMap.get(key) || { name: j.printerName, total: 0, completed: 0, failed: 0, time: 0 }
    existing.total++
    if (j.status === 'completed') existing.completed++
    if (j.status === 'failed') existing.failed++
    existing.time += j.duration || 0
    printerMap.set(key, existing)
  }
  const printerBreakdown = Array.from(printerMap.entries())
    .map(([id, data]) => ({ id, ...data, successRate: data.total > 0 ? (data.completed / data.total) * 100 : 0 }))
    .sort((a, b) => b.total - a.total)

  // Daily activity (last N days based on period)
  const dayCount = period === '7d' ? 7 : period === '30d' ? 30 : period === '90d' ? 90 : 30
  const dailyActivity: Array<{ date: string; completed: number; failed: number; cancelled: number }> = []
  for (let i = dayCount - 1; i >= 0; i--) {
    const d = getDaysAgo(i)
    const dayStr = d.toISOString().split('T')[0]
    const dayLabel = d.toLocaleDateString(undefined, { month: 'short', day: 'numeric' })
    const dayJobs = filtered.filter(j => j.startTime.startsWith(dayStr))
    dailyActivity.push({
      date: dayLabel,
      completed: dayJobs.filter(j => j.status === 'completed').length,
      failed: dayJobs.filter(j => j.status === 'failed').length,
      cancelled: dayJobs.filter(j => j.status === 'cancelled').length,
    })
  }

  // Busiest day of week
  const dayOfWeekCounts = new Array(7).fill(0)
  const dayNames = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']
  for (const j of filtered) {
    dayOfWeekCounts[new Date(j.startTime).getDay()]++
  }
  const busiestDay = dayNames[dayOfWeekCounts.indexOf(Math.max(...dayOfWeekCounts))]

  // Peak hour
  const hourCounts = new Array(24).fill(0)
  for (const j of filtered) {
    hourCounts[new Date(j.startTime).getHours()]++
  }
  const peakHour = hourCounts.indexOf(Math.max(...hourCounts))

  return {
    total, completed, failed, cancelled, successRate,
    totalPrintTime, avgPrintTime, totalFilament,
    printerBreakdown, dailyActivity,
    busiestDay, peakHour,
  }
}

// ─── Component ────────────────────────────────────────────────

export function Statistics({ jobs, period: initialPeriod = '30d', printerId }: StatisticsProps) {
  const [period, setPeriod] = useState<Period>(initialPeriod)

  const filteredJobs = useMemo(() => {
    return printerId ? jobs.filter(j => j.printerId === printerId) : jobs
  }, [jobs, printerId])

  const analytics = useMemo(() => computeAnalytics(filteredJobs, period), [filteredJobs, period])

  const maxDaily = useMemo(() => {
    return Math.max(1, ...analytics.dailyActivity.map(d => d.completed + d.failed + d.cancelled))
  }, [analytics.dailyActivity])

  return (
    <div className="space-y-4">
      {/* Header + period selector */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <BarChart3 className="w-5 h-5 text-primary" />
          <h2 className="text-lg font-semibold text-text">Statistics</h2>
        </div>
        <div className="flex rounded-lg border border-border overflow-hidden">
          {(['7d', '30d', '90d', 'all'] as Period[]).map(p => (
            <button
              key={p}
              onClick={() => setPeriod(p)}
              className={`px-3 py-1.5 text-xs transition-colors ${
                period === p ? 'bg-primary/10 text-primary' : 'text-text-muted hover:text-text'
              }`}
            >
              {p === 'all' ? 'All' : p}
            </button>
          ))}
        </div>
      </div>

      {/* Key metrics */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
        <StatCard label="Total Prints" value={analytics.total} icon={BarChart3} />
        <StatCard
          label="Success Rate"
          value={`${analytics.successRate.toFixed(0)}%`}
          icon={CheckCircle}
          accent={analytics.successRate >= 90 ? 'green' : analytics.successRate >= 70 ? 'yellow' : 'red'}
        />
        <StatCard label="Print Time" value={formatDuration(analytics.totalPrintTime)} icon={Clock} />
        <StatCard label="Filament" value={formatFilament(analytics.totalFilament)} icon={TrendingUp} />
      </div>

      {/* Secondary metrics */}
      <div className="grid grid-cols-3 gap-2">
        <MiniStat label="Avg Print Time" value={formatDuration(analytics.avgPrintTime)} />
        <MiniStat label="Busiest Day" value={analytics.busiestDay} />
        <MiniStat label="Peak Hour" value={`${analytics.peakHour}:00`} />
      </div>

      {/* Daily activity chart (CSS-only bar chart) */}
      <div className="p-3 rounded-lg border border-border bg-surface">
        <h3 className="text-xs font-medium text-text-muted uppercase tracking-wider mb-3">Daily Activity</h3>
        <div className="flex items-end gap-px h-24">
          {analytics.dailyActivity.map((day, i) => {
            const total = day.completed + day.failed + day.cancelled
            const heightPercent = (total / maxDaily) * 100
            const completedH = total > 0 ? (day.completed / total) * heightPercent : 0
            const failedH = total > 0 ? (day.failed / total) * heightPercent : 0
            const cancelledH = total > 0 ? (day.cancelled / total) * heightPercent : 0

            return (
              <div
                key={i}
                className="flex-1 flex flex-col justify-end group relative"
                title={`${day.date}: ${day.completed} OK, ${day.failed} fail, ${day.cancelled} cancel`}
              >
                {/* Tooltip on hover */}
                <div className="absolute -top-8 left-1/2 -translate-x-1/2 hidden group-hover:block z-10
                  px-2 py-1 rounded bg-surface-elevated border border-border shadow-lg text-[9px] text-text whitespace-nowrap">
                  {day.date}: {total}
                </div>

                {cancelledH > 0 && (
                  <div
                    className="w-full bg-yellow-400/60 rounded-t-sm"
                    style={{ height: `${cancelledH}%` }}
                  />
                )}
                {failedH > 0 && (
                  <div
                    className="w-full bg-red-400/60"
                    style={{ height: `${failedH}%` }}
                  />
                )}
                {completedH > 0 && (
                  <div
                    className="w-full bg-green-400/70 rounded-t-sm"
                    style={{ height: `${completedH}%` }}
                  />
                )}
                {total === 0 && (
                  <div className="w-full bg-border/30 rounded-t-sm" style={{ height: '2%' }} />
                )}
              </div>
            )
          })}
        </div>
        {/* Legend */}
        <div className="flex items-center gap-4 mt-2 text-[10px] text-text-muted">
          <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-sm bg-green-400/70" /> Completed</span>
          <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-sm bg-red-400/60" /> Failed</span>
          <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-sm bg-yellow-400/60" /> Cancelled</span>
        </div>
      </div>

      {/* Status breakdown */}
      <div className="p-3 rounded-lg border border-border bg-surface">
        <h3 className="text-xs font-medium text-text-muted uppercase tracking-wider mb-2">Status Breakdown</h3>
        <div className="space-y-2">
          <BreakdownBar label="Completed" count={analytics.completed} total={analytics.total} color="bg-green-400" />
          <BreakdownBar label="Failed" count={analytics.failed} total={analytics.total} color="bg-red-400" />
          <BreakdownBar label="Cancelled" count={analytics.cancelled} total={analytics.total} color="bg-yellow-400" />
        </div>
      </div>

      {/* Per-printer table */}
      {analytics.printerBreakdown.length > 1 && (
        <div className="p-3 rounded-lg border border-border bg-surface">
          <h3 className="text-xs font-medium text-text-muted uppercase tracking-wider mb-2">Per Printer</h3>
          <div className="space-y-1">
            {analytics.printerBreakdown.map(p => (
              <div key={p.id} className="flex items-center gap-3 px-2 py-1.5 rounded-md hover:bg-surface-elevated transition-colors">
                <PrinterIcon className="w-3.5 h-3.5 text-text-muted flex-shrink-0" />
                <div className="flex-1 min-w-0">
                  <div className="text-sm text-text truncate">{p.name}</div>
                </div>
                <div className="text-xs font-mono text-text-muted">{p.total} prints</div>
                <div className={`text-xs font-mono ${p.successRate >= 90 ? 'text-green-400' : p.successRate >= 70 ? 'text-yellow-400' : 'text-red-400'}`}>
                  {p.successRate.toFixed(0)}%
                </div>
                <div className="text-xs font-mono text-text-muted">{formatDuration(p.time)}</div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  )
}

// ─── Sub-components ───────────────────────────────────────────

function StatCard({ label, value, icon: Icon, accent }: {
  label: string; value: string | number; icon: typeof BarChart3; accent?: 'green' | 'yellow' | 'red'
}) {
  const color = accent === 'green' ? 'text-green-400'
    : accent === 'yellow' ? 'text-yellow-400'
    : accent === 'red' ? 'text-red-400'
    : 'text-text'

  return (
    <div className="p-2.5 rounded-lg border border-border bg-surface">
      <div className="flex items-center gap-1.5 mb-1">
        <Icon className="w-3 h-3 text-text-muted" />
        <span className="text-[10px] text-text-muted uppercase tracking-wider">{label}</span>
      </div>
      <div className={`text-sm font-bold font-mono ${color}`}>{value}</div>
    </div>
  )
}

function MiniStat({ label, value }: { label: string; value: string }) {
  return (
    <div className="px-3 py-2 rounded-lg border border-border bg-surface text-center">
      <div className="text-[10px] text-text-muted uppercase">{label}</div>
      <div className="text-xs font-bold font-mono text-text">{value}</div>
    </div>
  )
}

function BreakdownBar({ label, count, total, color }: {
  label: string; count: number; total: number; color: string
}) {
  const pct = total > 0 ? (count / total) * 100 : 0
  return (
    <div className="flex items-center gap-3">
      <span className="text-xs text-text-muted w-20">{label}</span>
      <div className="flex-1 h-2 rounded-full bg-surface-elevated overflow-hidden">
        <div
          className={`h-full rounded-full ${color} transition-all duration-300`}
          style={{ width: `${pct}%` }}
        />
      </div>
      <span className="text-xs font-mono text-text w-8 text-right">{count}</span>
      <span className="text-[10px] text-text-muted w-10 text-right">{pct.toFixed(0)}%</span>
    </div>
  )
}

export default Statistics
