// ═══════════════════════════════════════════════════════════════
// PRESTIGE DASHBOARD - PRINTER STORE (Zustand)
// ═══════════════════════════════════════════════════════════════

import { create } from 'zustand'
import { devtools, subscribeWithSelector } from 'zustand/middleware'
import type { 
  Printer, 
  PrinterStatus, 
  PrinterFilters, 
  PrinterSort,
  PrinterCommand 
} from '@core/types'
import { printerApi } from '@services/printer-api'
import { normalizePrinterStatus as normalizeStatusValue } from '@core/utils/normalizePrinterStatus'

// ─────────────────────────────────────────────────────────────
// Wraps the shared utility to normalize a full Printer object.
// ─────────────────────────────────────────────────────────────
function normalizePrinter(printer: Printer): Printer {
  const normalized = normalizeStatusValue(printer.status as string)
  if (normalized === printer.status) return printer
  return { ...printer, status: normalized }
}

// ═══════════════════════════════════════════════════════════════
// TYPES
// ═══════════════════════════════════════════════════════════════

interface PrinterState {
  // Data
  printers: Record<string, Printer>
  selectedPrinterId: string | null
  
  // Filters & Sort
  filters: PrinterFilters
  sort: PrinterSort
  
  // Loading states
  isLoading: boolean
  isRefreshing: boolean
  error: string | null
  
  // Command queue
  pendingCommands: Record<string, PrinterCommand>
}

interface PrinterActions {
  // Printer CRUD
  setPrinters: (printers: Printer[]) => void
  addPrinter: (printer: Printer) => void
  updatePrinter: (id: string, updates: Partial<Printer>) => void
  removePrinter: (id: string) => void
  
  // Selection
  selectPrinter: (id: string | null) => void
  
  // Filters & Sort
  setFilters: (filters: Partial<PrinterFilters>) => void
  clearFilters: () => void
  setSort: (sort: PrinterSort) => void
  
  // Loading
  setLoading: (isLoading: boolean) => void
  setRefreshing: (isRefreshing: boolean) => void
  setError: (error: string | null) => void
  
  // Commands
  queueCommand: (printerId: string, command: PrinterCommand) => void
  clearCommand: (printerId: string) => void
  
  // Bulk operations
  updatePrinterStatus: (id: string, status: PrinterStatus) => void
  
  // Emergency controls
  pauseAllPrinters: () => void
  resumeAllPrinters: () => void
  emergencyStopAll: () => void
}

type PrinterStore = PrinterState & PrinterActions

// ═══════════════════════════════════════════════════════════════
// INITIAL STATE
// ═══════════════════════════════════════════════════════════════

const initialState: PrinterState = {
  printers: {},
  selectedPrinterId: null,
  filters: {},
  sort: { field: 'name', direction: 'asc' },
  isLoading: false,
  isRefreshing: false,
  error: null,
  pendingCommands: {},
}

// ═══════════════════════════════════════════════════════════════
// STORE
// ═══════════════════════════════════════════════════════════════

export const usePrinterStore = create<PrinterStore>()(
  devtools(
    subscribeWithSelector((set, get) => ({
      ...initialState,

      // ─────────────────────────────────────────────────────────
      // Printer CRUD
      // ─────────────────────────────────────────────────────────
      
      setPrinters: (printers) => {
        const printersMap = printers.reduce((acc, printer) => {
          acc[printer.id] = normalizePrinter(printer)
          return acc
        }, {} as Record<string, Printer>)
        
        set({ printers: printersMap, isLoading: false, error: null })
      },

      addPrinter: (printer) => {
        set((state) => ({
          printers: { ...state.printers, [printer.id]: normalizePrinter(printer) },
        }))
      },

      updatePrinter: (id, updates) => {
        set((state) => {
          const existing = state.printers[id]
          if (!existing) return state

          // Deep-merge liveState — position/temps/progress never overwrite each other
          let merged: Partial<Printer> = { ...updates }
          if (updates.liveState !== undefined) {
            const newLive = updates.liveState as any
            const oldLive = (existing.liveState as any) ?? {}

            // Equality check — skip re-render if nothing meaningful changed
            const onlyLiveState = Object.keys(updates).length === 1
            if (onlyLiveState) {
              const newT = newLive?.temperatures
              const oldT = oldLive?.temperatures
              const newPos = newLive?.position
              const oldPos = oldLive?.position
              const newP = newLive?.progress
              const oldP = oldLive?.progress

              // Use `actual ?? current` — backend sends actual, WS layer mirrors both
              const tempsSame = !newT || !oldT || (
                Math.abs(((newT.hotend?.actual ?? newT.hotend?.current) ?? 0) - ((oldT.hotend?.actual ?? oldT.hotend?.current) ?? 0)) < 0.1 &&
                (newT.hotend?.target ?? 0) === (oldT.hotend?.target ?? 0) &&
                Math.abs(((newT.bed?.actual ?? newT.bed?.current) ?? 0) - ((oldT.bed?.actual ?? oldT.bed?.current) ?? 0)) < 0.1 &&
                (newT.bed?.target ?? 0) === (oldT.bed?.target ?? 0)
              )
              const progressSame = !newP || !oldP || (
                Math.abs((newP.percentage ?? 0) - (oldP.percentage ?? 0)) < 0.1
              )
              // Position is NOT throttled — movements must always show in real time
              if (tempsSame && progressSame && !newPos) return state
            }

            // Deep-merge nested liveState fields so they don't clobber each other
            merged = {
              ...updates,
              liveState: {
                ...oldLive,
                ...newLive,
                temperatures: newLive.temperatures
                  ? { ...oldLive.temperatures, ...newLive.temperatures }
                  : oldLive.temperatures,
                position: newLive.position
                  ? { ...oldLive.position, ...newLive.position }
                  : oldLive.position,
                fans: newLive.fans
                  ? { ...oldLive.fans, ...newLive.fans }
                  : oldLive.fans,
                speed: newLive.speed
                  ? { ...oldLive.speed, ...newLive.speed }
                  : oldLive.speed,
              } as Printer['liveState'],
            }
          }
          
          return {
            printers: {
              ...state.printers,
              [id]: { ...existing, ...merged, updatedAt: new Date().toISOString() },
            },
          }
        })
      },

      removePrinter: (id) => {
        set((state) => {
          const { [id]: removed, ...rest } = state.printers
          return {
            printers: rest,
            selectedPrinterId: state.selectedPrinterId === id ? null : state.selectedPrinterId,
          }
        })
      },

      // ─────────────────────────────────────────────────────────
      // Selection
      // ─────────────────────────────────────────────────────────
      
      selectPrinter: (id) => {
        set({ selectedPrinterId: id })
      },

      // ─────────────────────────────────────────────────────────
      // Filters & Sort
      // ─────────────────────────────────────────────────────────
      
      setFilters: (filters) => {
        set((state) => ({
          filters: { ...state.filters, ...filters },
        }))
      },

      clearFilters: () => {
        set({ filters: {} })
      },

      setSort: (sort) => {
        set({ sort })
      },

      // ─────────────────────────────────────────────────────────
      // Loading
      // ─────────────────────────────────────────────────────────
      
      setLoading: (isLoading) => {
        set({ isLoading })
      },

      setRefreshing: (isRefreshing) => {
        set({ isRefreshing })
      },

      setError: (error) => {
        set({ error, isLoading: false })
      },

      // ─────────────────────────────────────────────────────────
      // Commands
      // ─────────────────────────────────────────────────────────
      
      queueCommand: (printerId, command) => {
        set((state) => ({
          pendingCommands: { ...state.pendingCommands, [printerId]: command },
        }))
      },

      clearCommand: (printerId) => {
        set((state) => {
          const { [printerId]: removed, ...rest } = state.pendingCommands
          return { pendingCommands: rest }
        })
      },

      // ─────────────────────────────────────────────────────────
      // Bulk Operations
      // ─────────────────────────────────────────────────────────
      
      updatePrinterStatus: (id, status) => {
        set((state) => {
          const existing = state.printers[id]
          if (!existing) return state
          // Normalize to valid PrinterStatus (handles 'standby', 'ready', etc.)
          const normalized = normalizeStatusValue(status as string)
          // Skip re-render if nothing changed
          if (existing.status === normalized) return state
          
          return {
            printers: {
              ...state.printers,
              [id]: { ...existing, status: normalized, updatedAt: new Date().toISOString() },
            },
          }
        })
      },

      // ─────────────────────────────────────────────────────────
      // Emergency Controls
      // ─────────────────────────────────────────────────────────
      
      pauseAllPrinters: () => {
        const printing = Object.values(get().printers).filter((p) => p.status === 'printing')
        printing.forEach((printer) => {
          printerApi.pause(printer.id).catch((err) =>
            console.error(`pauseAllPrinters: failed for ${printer.id}`, err)
          )
        })
      },

      resumeAllPrinters: () => {
        const paused = Object.values(get().printers).filter((p) => p.status === 'paused')
        paused.forEach((printer) => {
          printerApi.resume(printer.id).catch((err) =>
            console.error(`resumeAllPrinters: failed for ${printer.id}`, err)
          )
        })
      },

      emergencyStopAll: () => {
        Object.values(get().printers).forEach((printer) => {
          printerApi.emergencyStop(printer.id).catch((err) =>
            console.error(`emergencyStopAll: failed for ${printer.id}`, err)
          )
        })
      },
    })),
    { name: 'printer-store' }
  )
)

// ═══════════════════════════════════════════════════════════════
// SELECTORS (for optimized re-renders)
// ═══════════════════════════════════════════════════════════════

export const selectPrinters = (state: PrinterStore) => state.printers
export const selectPrintersArray = (state: PrinterStore) => Object.values(state.printers)
export const selectSelectedPrinter = (state: PrinterStore) => 
  state.selectedPrinterId ? state.printers[state.selectedPrinterId] : null
export const selectPrinterById = (id: string) => (state: PrinterStore) => state.printers[id]
export const selectFilters = (state: PrinterStore) => state.filters
export const selectSort = (state: PrinterStore) => state.sort
export const selectIsLoading = (state: PrinterStore) => state.isLoading

// Computed selectors
export const selectPrintersByStatus = (status: PrinterStatus) => (state: PrinterStore) =>
  Object.values(state.printers).filter((p) => p.status === status)

export const selectOnlinePrinters = (state: PrinterStore) =>
  Object.values(state.printers).filter((p) => p.status !== 'disconnected')

export const selectPrintingPrinters = (state: PrinterStore) =>
  Object.values(state.printers).filter((p) => p.status === 'printing')

export const selectPrintersWithErrors = (state: PrinterStore) =>
  Object.values(state.printers).filter((p) => p.status === 'error')

export const selectFilteredPrinters = (state: PrinterStore) => {
  let printers = Object.values(state.printers)
  const { filters, sort } = state
  
  // Apply filters
  if (filters.status?.length) {
    printers = printers.filter((p) => filters.status!.includes(p.status))
  }
  if (filters.type?.length) {
    printers = printers.filter((p) => filters.type!.includes(p.adapterType))
  }
  if (filters.tags?.length) {
    printers = printers.filter((p) => 
      p.tags?.some((tag) => filters.tags!.includes(tag))
    )
  }
  if (filters.search) {
    const search = filters.search.toLowerCase()
    printers = printers.filter((p) =>
      p.name.toLowerCase().includes(search) ||
      (p.adapterType ?? '').toLowerCase().includes(search)
    )
  }
  
  // Apply sort
  printers.sort((a, b) => {
    let comparison = 0
    switch (sort.field) {
      case 'name':
        comparison = a.name.localeCompare(b.name)
        break
      case 'status':
        comparison = a.status.localeCompare(b.status)
        break
      case 'type':
        comparison = (a.adapterType ?? '').localeCompare(b.adapterType ?? '')
        break
      case 'lastSeenAt':
        comparison = (a.lastSeenAt || '').localeCompare(b.lastSeenAt || '')
        break
      case 'qualityScore':
        comparison = (a.qualityScore || 0) - (b.qualityScore || 0)
        break
    }
    return sort.direction === 'asc' ? comparison : -comparison
  })
  
  return printers
}

export default usePrinterStore
