// ═══════════════════════════════════════════════════════════════
// PRESTIGE DASHBOARD - usePrintersFetch Hook
// Internal hook: fetch printers on mount + error/loading state
// Used by: useDataInitialization (app startup sequence)
//
// NOT the same as usePrinters() from usePrinterUpdates.ts:
//   usePrintersFetch — fetch on mount, timeout, mock fallback
//   usePrinters      — store subscription, filtering, stats
//
// FIX: Module-level guard prevents StrictMode's triple effect-
//      invocation (mount→cleanup→remount + commitDoubleInvoke)
//      from firing multiple concurrent fetch chains.
//      Retry logic removed — backend-down errors are not transient
//      and retries only produced log spam + race conditions.
// ═══════════════════════════════════════════════════════════════

import { useEffect, useState } from 'react'
import { usePrinterStore, selectPrintersArray, selectIsLoading } from '@core/state/printerStore'
import { printerApi } from '@/services/printer-api'

// Mock data is NOT available in this project.
// USE_MOCK_DATA and mockPrinters were referenced but never implemented.
// All printer data comes from the real backend via printerApi.

// Module-level guard — holds true from the moment a fetch starts until it
// fully completes (success or failure). Shared across ALL React instances of
// this hook so StrictMode double-invocations are no-ops after the first mount.
let _fetchOwned = false

export function usePrintersFetch() {
  const printers = usePrinterStore(selectPrintersArray)
  const isLoading = usePrinterStore(selectIsLoading)
  const { setPrinters, setLoading } = usePrinterStore()

  const [error, setError] = useState<Error | null>(null)

  useEffect(() => {
    // Grab the lock. If another instance already owns it, do nothing.
    if (_fetchOwned) return
    _fetchOwned = true

    let mounted = true

    const timeoutId = setTimeout(() => {
      console.warn('Printer fetch timed out after 5s')
      setLoading(false)  // Zustand global — safe without mounted check
      if (mounted) {
        setError(new Error('Printer fetch timed out'))  // local useState — needs mounted check
      }
    }, 5000)

    const fetchPrinters = async () => {
      try {
        setLoading(true)
        // Note: setError is local useState — keep mounted check for that.
        // setPrinters / setLoading are Zustand global store — no mounted check needed:
        // updating the global store is always safe even if this component unmounts.

        const fetchedPrinters = await printerApi.getAll()

        // Always update the global store — even if this component already unmounted
        // (StrictMode cleanup). The Zustand store is app-global and persists.
        clearTimeout(timeoutId)
        setPrinters(fetchedPrinters)
      } catch (err) {
        clearTimeout(timeoutId)
        const error = err instanceof Error ? err : new Error('Failed to fetch printers')
        // setError is local useState — guard with mounted
        if (mounted) {
          setError(error)
        }
        console.error('Failed to fetch printers:', error)
        console.warn('Printers: backend unavailable — use the refresh button to retry')
      } finally {
        // setLoading is Zustand global — safe to call regardless of mounted state
        setLoading(false)
      }
    }

    fetchPrinters()

    return () => {
      mounted = false
      clearTimeout(timeoutId)
      // Do NOT release _fetchOwned here. If we're in StrictMode's cleanup
      // between the real remount and commitDoubleInvokeEffectsInDEV, we want
      // the double-invoke to be blocked. The lock is permanent once a fetch
      // completes; manual refresh() resets it explicitly.
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  const refresh = async () => {
    _fetchOwned = false  // Allow a new fetch
    try {
      setLoading(true)
      setError(null)

      const fetchedPrinters = await printerApi.getAll()
      setPrinters(fetchedPrinters)
    } catch (err) {
      const error = err instanceof Error ? err : new Error('Failed to fetch printers')
      setError(error)
      console.error('Failed to refresh printers:', error)
    } finally {
      setLoading(false)
      _fetchOwned = true
    }
  }

  return {
    printers,
    isLoading,
    error,
    refresh,
  }
}

export default usePrintersFetch
