// ═══════════════════════════════════════════════════════════════
// PRESTIGE DASHBOARD - Reset Password Page
//
// FLOW:
//   1. User clicks reset link in email
//   2. Supabase redirects to: /reset-password#access_token=...&type=recovery
//   3. This page parses the hash, exchanges token for a session
//   4. User sets a new password via supabase.auth.updateUser()
//   5. Secure password change: re-auth required (email link confirmation)
//
// Supabase → Authentication → URL Configuration:
//   Site URL:      https://prestilon.com
//   Redirect URL:  https://prestilon.com/reset-password
// ═══════════════════════════════════════════════════════════════

import { useState, useEffect, useRef } from 'react'
import { useNavigate } from 'react-router-dom'
import { motion } from 'framer-motion'
import {
  Lock, Eye, EyeOff, CheckCircle,
  AlertCircle, Loader2, ArrowRight, ShieldCheck,
} from 'lucide-react'

// ─── Env ──────────────────────────────────────────────────────

const SUPABASE_URL      = (import.meta.env.VITE_SUPABASE_URL      as string) ?? ''
const SUPABASE_ANON_KEY = (import.meta.env.VITE_SUPABASE_ANON_KEY as string) ?? ''

function sbHeaders(token?: string): Record<string, string> {
  return {
    'Content-Type':  'application/json',
    apikey:           SUPABASE_ANON_KEY,
    Authorization:   `Bearer ${token ?? SUPABASE_ANON_KEY}`,
  }
}

// ─── Token state machine ──────────────────────────────────────

type PageState =
  | 'parsing'      // reading hash from URL
  | 'invalid'      // no valid token in URL
  | 'expired'      // token rejected by Supabase
  | 'ready'        // token exchanged — show new-password form
  | 'saving'       // calling updateUser
  | 'done'         // password changed successfully

// ─── Shared UI pieces ─────────────────────────────────────────

const BG_GRID_STYLE = {
  backgroundImage:
    'linear-gradient(rgba(0,212,255,0.03) 1px, transparent 1px),' +
    'linear-gradient(90deg, rgba(0,212,255,0.03) 1px, transparent 1px)',
  backgroundSize: '48px 48px',
}

function PageBackground() {
  return (
    <>
      <div className="absolute inset-0 pointer-events-none" style={BG_GRID_STYLE} />
      <div className="absolute top-1/3 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[600px] h-[600px] bg-cyan-500/5 rounded-full blur-3xl pointer-events-none" />
    </>
  )
}

function Logo() {
  return (
    <div className="flex flex-col items-center mb-10">
      <div className="w-16 h-16 rounded-2xl bg-gradient-to-br from-cyan-500 to-blue-600 flex items-center justify-center shadow-2xl shadow-cyan-500/30 mb-4">
        <span className="text-white font-bold text-2xl">P</span>
      </div>
      <h1
        className="text-2xl font-bold text-white tracking-widest"
        style={{ fontFamily: "'Share Tech Mono', monospace" }}
      >
        PRESTILON
      </h1>
    </div>
  )
}

interface PasswordInputProps {
  placeholder: string
  inputRef:    React.RefObject<HTMLInputElement>
  show:        boolean
  onToggle:    () => void
  disabled?:   boolean
}

function PasswordInput({ placeholder, inputRef, show, onToggle, disabled }: PasswordInputProps) {
  return (
    <div className="flex items-center gap-3 px-4 py-3.5 rounded-xl border border-gray-700/60 bg-gray-900/80 focus-within:border-cyan-500/60 transition-colors duration-200">
      <Lock size={16} className="flex-shrink-0 text-gray-500" />
      <input
        ref={inputRef}
        type={show ? 'text' : 'password'}
        placeholder={placeholder}
        disabled={disabled}
        autoComplete="new-password"
        autoCorrect="off"
        autoCapitalize="off"
        spellCheck={false}
        data-form-type="other"
        data-lpignore="true"
        data-1p-ignore
        className="flex-1 bg-transparent text-sm text-white placeholder-gray-500 outline-none disabled:opacity-50"
      />
      <span
        role="button"
        tabIndex={-1}
        onMouseDown={(e) => { e.preventDefault(); onToggle() }}
        className="text-gray-500 hover:text-gray-300 transition-colors cursor-pointer select-none"
      >
        {show ? <EyeOff size={16} /> : <Eye size={16} />}
      </span>
    </div>
  )
}

// ─── Password strength ────────────────────────────────────────

function strengthInfo(pw: string): { score: number; label: string; color: string } {
  let score = 0
  if (pw.length >= 8)  score++
  if (pw.length >= 12) score++
  if (/[A-Z]/.test(pw)) score++
  if (/[0-9]/.test(pw)) score++
  if (/[^A-Za-z0-9]/.test(pw)) score++
  if (score <= 1) return { score, label: 'Weak',   color: 'bg-red-500' }
  if (score <= 2) return { score, label: 'Fair',   color: 'bg-amber-500' }
  if (score <= 3) return { score, label: 'Good',   color: 'bg-yellow-400' }
  return              { score, label: 'Strong', color: 'bg-green-500' }
}

function StrengthBar({ password }: { password: string }) {
  if (!password) return null
  const { score, label, color } = strengthInfo(password)
  return (
    <div className="space-y-1">
      <div className="flex gap-1">
        {[1, 2, 3, 4, 5].map((i) => (
          <div
            key={i}
            className={`h-1 flex-1 rounded-full transition-all duration-300 ${
              i <= score ? color : 'bg-gray-700'
            }`}
          />
        ))}
      </div>
      <p className={`text-xs text-right ${
        score <= 1 ? 'text-red-400' :
        score <= 2 ? 'text-amber-400' :
        score <= 3 ? 'text-yellow-400' :
        'text-green-400'
      }`}>
        {label}
      </p>
    </div>
  )
}

// ─── Main component ───────────────────────────────────────────

export default function ResetPasswordPage() {
  const navigate = useNavigate()

  const [pageState, setPageState] = useState<PageState>('parsing')
  const [accessToken, setAccessToken] = useState('')

  const passwordRef = useRef<HTMLInputElement>(null)
  const confirmRef  = useRef<HTMLInputElement>(null)
  const [showPw, setShowPw]       = useState(false)
  const [showCf, setShowCf]       = useState(false)
  const [error, setError]         = useState<string | null>(null)

  // ── Step 1: Parse URL hash & exchange token ─────────────────
  useEffect(() => {
    const hash   = window.location.hash.substring(1)          // strip leading #
    const params = new URLSearchParams(hash)

    const type    = params.get('type')
    const token   = params.get('access_token')
    const refresh = params.get('refresh_token')

    if (!token || type !== 'recovery') {
      setPageState('invalid')
      return
    }

    // Use the access_token directly from the recovery link
    void (async () => {
      try {
        // First try to establish a proper session via refresh_token
        const res = await fetch(`${SUPABASE_URL}/auth/v1/token?grant_type=refresh_token`, {
          method:  'POST',
          headers: sbHeaders(),
          body:    JSON.stringify({ refresh_token: refresh }),
        })

        const data = await res.json()
        // Use exchanged token if available, otherwise fall back to raw access_token
        const at = (res.ok && data.access_token) ? data.access_token : token
        setAccessToken(at)

        // Clean the hash from URL so the token isn't visible
        window.history.replaceState(null, '', window.location.pathname)
        setPageState('ready')
      } catch {
        // Even on error, try with the raw token
        setAccessToken(token)
        window.history.replaceState(null, '', window.location.pathname)
        setPageState('ready')
      }
    })()
  }, [])

  // ── Step 2: Update password ─────────────────────────────────
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setError(null)

    const password = passwordRef.current?.value ?? ''
    const confirm  = confirmRef.current?.value ?? ''

    if (password.length < 8) {
      setError('Password must be at least 8 characters')
      return
    }
    if (password !== confirm) {
      setError('Passwords do not match')
      return
    }

    const { score } = strengthInfo(password)
    if (score < 2) {
      setError('Password is too weak. Use uppercase, numbers or symbols.')
      return
    }

    setPageState('saving')

    try {
      const res = await fetch(`${SUPABASE_URL}/auth/v1/user`, {
        method:  'PUT',
        headers: sbHeaders(accessToken),
        body:    JSON.stringify({ password }),
      })

      if (!res.ok) {
        const j = await res.json().catch(() => ({}))
        const msg = (j as { message?: string }).message ?? 'Failed to update password'
        setError(msg)
        setPageState('ready')
        return
      }

      setPageState('done')
    } catch {
      setError('Network error. Please try again.')
      setPageState('ready')
    }
  }

  // ── Render states ────────────────────────────────────────────

  const renderCard = (content: React.ReactNode) => (
    <div className="min-h-screen flex items-center justify-center bg-gray-950 p-4 relative overflow-hidden">
      <PageBackground />
      <motion.div
        initial={{ opacity: 0, y: 24 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.35, ease: 'easeOut' }}
        className="relative z-10 w-full max-w-sm"
      >
        <Logo />
        {content}
      </motion.div>
    </div>
  )

  // Parsing…
  if (pageState === 'parsing') {
    return renderCard(
      <div className="rounded-2xl border border-gray-800 bg-gray-900/80 p-8 text-center">
        <Loader2 className="w-10 h-10 text-cyan-400 animate-spin mx-auto mb-4" />
        <p className="text-gray-400 text-sm">Verifying reset link...</p>
      </div>
    )
  }

  // Invalid link
  if (pageState === 'invalid') {
    return renderCard(
      <div className="rounded-2xl border border-red-500/20 bg-gray-900/80 p-8 text-center">
        <div className="w-16 h-16 mx-auto mb-5 rounded-full bg-red-500/10 border border-red-500/30 flex items-center justify-center">
          <AlertCircle className="w-8 h-8 text-red-400" />
        </div>
        <h2 className="text-xl font-bold text-white mb-2">Invalid link</h2>
        <p className="text-gray-400 text-sm mb-7">
          This password reset link is invalid or has already been used.
          Please request a new one.
        </p>
        <button
          onClick={() => navigate('/login')}
          className="w-full py-3 bg-gradient-to-r from-cyan-600 to-blue-600 hover:from-cyan-500 hover:to-blue-500 text-white rounded-xl text-sm font-semibold transition-all duration-200 shadow-lg shadow-cyan-500/20"
        >
          Back to Sign In
        </button>
      </div>
    )
  }

  // Expired
  if (pageState === 'expired') {
    return renderCard(
      <div className="rounded-2xl border border-amber-500/20 bg-gray-900/80 p-8 text-center">
        <div className="w-16 h-16 mx-auto mb-5 rounded-full bg-amber-500/10 border border-amber-500/30 flex items-center justify-center">
          <AlertCircle className="w-8 h-8 text-amber-400" />
        </div>
        <h2 className="text-xl font-bold text-white mb-2">Link expired</h2>
        <p className="text-gray-400 text-sm mb-7">
          This reset link has expired (valid for 1 hour).
          Please request a new password reset.
        </p>
        <button
          onClick={() => navigate('/login')}
          className="w-full py-3 bg-gradient-to-r from-cyan-600 to-blue-600 hover:from-cyan-500 hover:to-blue-500 text-white rounded-xl text-sm font-semibold transition-all duration-200 shadow-lg shadow-cyan-500/20"
        >
          Request New Link
        </button>
      </div>
    )
  }

  // Success
  if (pageState === 'done') {
    return renderCard(
      <div className="rounded-2xl border border-green-500/20 bg-gray-900/80 p-8 text-center">
        <div className="w-16 h-16 mx-auto mb-5 rounded-full bg-green-500/10 border border-green-500/30 flex items-center justify-center">
          <CheckCircle className="w-8 h-8 text-green-400" />
        </div>
        <h2 className="text-xl font-bold text-white mb-2">Password updated</h2>
        <p className="text-gray-400 text-sm mb-7">
          Your password has been changed successfully.
          You can now sign in with your new password.
        </p>
        <button
          onClick={() => navigate('/login')}
          className="w-full py-3 bg-gradient-to-r from-cyan-600 to-blue-600 hover:from-cyan-500 hover:to-blue-500 text-white rounded-xl text-sm font-semibold transition-all duration-200 shadow-lg shadow-cyan-500/20"
        >
          Sign In
        </button>
      </div>
    )
  }

  // Form (ready | saving)
  return renderCard(
    <div className="rounded-2xl border border-gray-800 bg-gray-900/80 p-8">
      {/* Header */}
      <div className="flex items-center gap-3 mb-6">
        <div className="w-10 h-10 rounded-xl bg-cyan-500/10 border border-cyan-500/30 flex items-center justify-center">
          <ShieldCheck size={18} className="text-cyan-400" />
        </div>
        <div>
          <h2 className="text-lg font-bold text-white">Set new password</h2>
          <p className="text-gray-500 text-xs mt-0.5">
            This link is valid once · secured by email confirmation
          </p>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="space-y-3" noValidate>
        <PasswordInput
          placeholder="New password"
          inputRef={passwordRef}
          show={showPw}
          onToggle={() => setShowPw((s) => !s)}
          disabled={pageState === 'saving'}
        />

        <PasswordInput
          placeholder="Confirm new password"
          inputRef={confirmRef}
          show={showCf}
          onToggle={() => setShowCf((s) => !s)}
          disabled={pageState === 'saving'}
        />

        <ul className="space-y-1 px-1">
          {[
            'At least 8 characters',
            'One uppercase letter',
            'One number',
            'One special character',
          ].map((text) => (
            <li key={text} className="flex items-center gap-2 text-xs">
              <span className="w-1.5 h-1.5 rounded-full flex-shrink-0 bg-gray-600" />
              <span className="text-gray-500">{text}</span>
            </li>
          ))}
        </ul>

        {/* Submit */}
        <button
          type="submit"
          disabled={pageState === 'saving'}
          className="
            w-full flex items-center justify-center gap-2 py-3.5 rounded-xl
            bg-gradient-to-r from-cyan-600 to-blue-600
            hover:from-cyan-500 hover:to-blue-500
            text-white font-semibold text-sm
            disabled:opacity-50 disabled:cursor-not-allowed
            transition-all duration-200 shadow-lg shadow-cyan-500/20
            active:scale-[0.98]
          "
        >
          {pageState === 'saving'
            ? <><Loader2 size={16} className="animate-spin" /><span>Saving...</span></>
            : <><span>Update Password</span><ArrowRight size={16} /></>
          }
        </button>

        {/* Error */}
        {error && (
          <motion.div
            initial={{ opacity: 0, y: 4 }}
            animate={{ opacity: 1, y: 0 }}
            className="flex items-start gap-2.5 px-4 py-3 rounded-xl bg-red-500/10 border border-red-500/20 text-red-400 text-sm"
          >
            <AlertCircle size={15} className="flex-shrink-0 mt-0.5" />
            <span>{error}</span>
          </motion.div>
        )}
      </form>
    </div>
  )
}
