// PRESTIGE DASHBOARD - useDataInitialization Hook
// ═══════════════════════════════════════════════════════════════

import { useEffect } from 'react'
import { usePrintersFetch } from './usePrintersFetch'
import { useAIStatus } from './useAIStatus'

/**
 * Central hook to initialize all data on app startup
 * Combines printer fetching, AI status, and other initial data loads
 * 
 * FIXED: Added timeout protection to prevent infinite loading
 */
export function useDataInitialization() {
  const {
    printers,
    isLoading: printersLoading,
    error: printersError,
  } = usePrintersFetch()

  const {
    aiEnabled,
    aiStatus,
    isLoading: aiLoading,
    error: aiError,
  } = useAIStatus()

  // Both sub-hooks have their own 5s timeouts internally.
  // isInitialized = true once both stop loading (success, error, OR internal timeout).
  const bothDone = !printersLoading && !aiLoading

  // Log non-critical AI error once when it settles
  useEffect(() => {
    if (bothDone && aiError) {
      console.warn('AI initialization failed (non-critical):', aiError)
    }
  }, [bothDone, aiError])

  return {
    isInitialized: bothDone,
    isLoading: !bothDone,
    error: printersError ?? null,   // only printer errors are critical
    timedOut: false,                // sub-hooks handle their own timeouts
    data: { printers, aiEnabled, aiStatus },
  }
}

export default useDataInitialization
