// ═══════════════════════════════════════════════════════════════
// PRESTIGE DASHBOARD - Sidebar Component (with Auth + Subscription)
// ═══════════════════════════════════════════════════════════════

import { useLocation, useNavigate } from 'react-router-dom'
import {
  LayoutDashboard,
  Printer,
  Brain,
  Database,
  ChevronLeft,
  HelpCircle,
  ScanLine,
  CreditCard,
  LogOut,
  User,
  CheckCircle,
  AlertCircle,
  Loader2,
} from 'lucide-react'
import { useState } from 'react'
import { useUIStore, usePrinterStore, selectSidebarCollapsed } from '@core/state'
import { useAuthStore } from '@core/state'
import { EmergencyControls } from '@core/components/EmergencyControls'
import type { EmergencyControlHandlers } from '@core/components/EmergencyControls/EmergencyControls.types'

interface SidebarProps {
  isConnected: boolean
  emergencyHandlers?: EmergencyControlHandlers
}

// Navigation items
const navItems = [
  { id: 'dashboard',    path: '/',             icon: LayoutDashboard, label: 'Dashboard' },
  { id: 'printers',     path: '/printers',     icon: Printer,         label: 'Printers' },
  { id: 'discovery',    path: '/discovery',    icon: ScanLine,        label: 'Discover' },
  { id: 'ai',           path: '/ai',           icon: Brain,           label: 'AI Insights' },
  { id: 'backup',       path: '/backup',       icon: Database,        label: 'Backup' },
  { id: 'subscription', path: '/subscription', icon: CreditCard,      label: 'Abonements' },
  { id: 'support',      path: '/support',      icon: HelpCircle,      label: 'Support' },
]

export function Sidebar({ isConnected, emergencyHandlers }: SidebarProps) {
  const location      = useLocation()
  const navigate      = useNavigate()
  const collapsed     = useUIStore(selectSidebarCollapsed)
  const { toggleSidebarCollapsed } = useUIStore()
  const printers      = usePrinterStore((s) => Object.values(s.printers))
  const printingCount = printers.filter((p) => p.status === 'printing').length

  const { user, profile, subscription, signOut } = useAuthStore()
  const [signingOut, setSigningOut] = useState(false)

  const isActive = subscription?.status === 'active' || subscription?.status === 'trial'
  const sidebarWidth = collapsed ? 72 : 280

  const displayName = profile?.full_name
    ?? user?.email?.split('@')[0]
    ?? 'Lietotājs'

  const handleSignOut = async () => {
    setSigningOut(true)
    await signOut()
    navigate('/login', { replace: true })
  }

  return (
    <aside
      className="fixed left-0 top-0 bottom-0 z-50 flex flex-col bg-gray-900 border-r border-gray-800 transition-all duration-300 overflow-hidden"
      style={{ width: sidebarWidth }}
    >
      {/* ── Logo ─────────────────────────────────────────── */}
      <div className="h-16 px-4 flex items-center justify-between border-b border-gray-800 flex-shrink-0">
        <div className="flex items-center gap-3">
          <div className="relative">
            <div className="w-10 h-10 rounded-lg bg-gradient-to-br from-cyan-500 to-blue-600 flex items-center justify-center shadow-lg shadow-cyan-500/30">
              <span className="text-white font-bold text-base">P</span>
            </div>
            {!collapsed && (
              <div
                className={`
                  absolute -bottom-0.5 -right-0.5 w-3 h-3 rounded-full border-2 border-gray-900
                  ${isConnected ? 'bg-green-400' : 'bg-red-400 animate-pulse'}
                `}
              />
            )}
          </div>
          {!collapsed && (
            <div>
              <h1 className="font-bold text-white text-base tracking-wide">PRESTILON</h1>
              <p className="text-[10px] text-gray-500 uppercase tracking-widest">Dashboard</p>
            </div>
          )}
        </div>
      </div>

      {/* ── Navigation ───────────────────────────────────── */}
      <nav className="flex-1 p-3 space-y-1 overflow-y-auto overflow-x-hidden [&::-webkit-scrollbar]:hidden [-ms-overflow-style:none] [scrollbar-width:none]">
        {navItems.map((item) => {
          const isItemActive = location.pathname === item.path ||
            (item.path !== '/' && location.pathname.startsWith(item.path))
          const Icon = item.icon
          const showBadge = item.id === 'printers' && printingCount > 0

          // Subscription indicator
          const isSubItem = item.id === 'subscription'
          const subBadge  = isSubItem && subscription && !isActive ? '!' : null

          return (
            <button
              key={item.id}
              onClick={() => navigate(item.path)}
              className={`
                relative w-full flex items-center gap-3 px-3 py-2.5 rounded-xl
                transition-all duration-200 group
                ${isItemActive
                  ? 'bg-cyan-500/20 text-cyan-400 shadow-lg shadow-cyan-500/20'
                  : 'text-gray-400 hover:bg-gray-800 hover:text-white'
                }
              `}
            >
              {isItemActive && (
                <span
                  className="absolute left-0 top-1/2 -translate-y-1/2 w-[3px] h-5 rounded-r-full bg-cyan-400"
                  style={{ boxShadow: '0 0 8px rgba(0,245,255,0.6)' }}
                />
              )}
              <Icon size={20} />

              {!collapsed && (
                <>
                  <span className="flex-1 text-left text-sm font-medium">{item.label}</span>
                  {showBadge && (
                    <span className="px-2 py-0.5 rounded-full text-xs font-mono bg-cyan-500/20 text-cyan-400">
                      {printingCount}
                    </span>
                  )}
                  {subBadge && (
                    <span className="w-5 h-5 rounded-full bg-amber-500 text-black text-xs font-bold flex items-center justify-center">
                      !
                    </span>
                  )}
                </>
              )}

              {collapsed && (
                <div className="absolute left-full ml-2 px-3 py-1.5 bg-gray-800 border border-gray-700 rounded-lg text-sm text-white opacity-0 group-hover:opacity-100 pointer-events-none whitespace-nowrap z-50 transition-opacity shadow-lg">
                  {item.label}
                </div>
              )}
            </button>
          )
        })}
      </nav>

      {/* ── Emergency Controls ────────────────────────────── */}
      {emergencyHandlers && (
        <div className="px-3 pt-3 border-t border-gray-800 flex-shrink-0">
          <EmergencyControls
            handlers={emergencyHandlers}
            embedded={true}
            sidebarCollapsed={collapsed}
          />
        </div>
      )}

      {/* ── User / Subscription info ──────────────────────── */}
      {!collapsed && (
        <div className="px-3 py-3 border-t border-gray-800 flex-shrink-0 space-y-2">
          {/* Subscription status pill */}
          <div
            className="flex items-center gap-2 px-3 py-2 rounded-xl bg-gray-800/60 cursor-pointer hover:bg-gray-800 transition-colors"
            onClick={() => navigate('/subscription')}
          >
            {isActive ? (
              <CheckCircle size={13} className="text-green-400 flex-shrink-0" />
            ) : (
              <AlertCircle size={13} className="text-amber-400 flex-shrink-0 animate-pulse" />
            )}
            <div className="flex-1 min-w-0">
              <p className="text-xs text-gray-400 truncate">
                {subscription
                  ? `${subscription.plan.charAt(0).toUpperCase() + subscription.plan.slice(1)} Plan`
                  : 'No subscription'
                }
              </p>
              <p className={`text-[10px] font-medium ${isActive ? 'text-green-400' : 'text-amber-400'}`}>
                {isActive ? 'Active' : 'Inactive — click to upgrade'}
              </p>
            </div>
          </div>

          {/* User row */}
          <div className="flex items-center gap-2 px-3 py-2 rounded-xl">
            <div className="w-7 h-7 rounded-full bg-gradient-to-br from-cyan-600 to-blue-700 flex items-center justify-center flex-shrink-0">
              <User size={13} className="text-white" />
            </div>
            <div className="flex-1 min-w-0">
              <p className="text-xs text-white font-medium truncate">{displayName}</p>
              <p className="text-[10px] text-gray-500 truncate">{user?.email ?? ''}</p>
            </div>
            <button
              onClick={handleSignOut}
              disabled={signingOut}
              title="Sign out"
              className="flex-shrink-0 p-1.5 rounded-lg text-gray-500 hover:text-red-400 hover:bg-red-500/10 transition-colors disabled:opacity-50"
            >
              {signingOut
                ? <Loader2 size={14} className="animate-spin" />
                : <LogOut size={14} />
              }
            </button>
          </div>
        </div>
      )}

      {/* ── Collapse / Sign-out (collapsed state) ─────────── */}
      {collapsed && (
        <div className="px-3 py-2 border-t border-gray-800 flex-shrink-0 space-y-1">
          <button
            onClick={handleSignOut}
            disabled={signingOut}
            title="Iziet"
            className="w-full flex items-center justify-center p-2.5 rounded-lg text-gray-500 hover:text-red-400 hover:bg-red-500/10 transition-colors disabled:opacity-50"
          >
            {signingOut
              ? <Loader2 size={16} className="animate-spin" />
              : <LogOut size={16} />
            }
          </button>
        </div>
      )}

      {/* ── Collapse button ───────────────────────────────── */}
      <div className="p-3 flex-shrink-0">
        <button
          onClick={toggleSidebarCollapsed}
          className="w-full flex items-center justify-center gap-2 px-3 py-2 rounded-lg text-gray-400 hover:bg-gray-800 hover:text-white transition-colors"
        >
          <ChevronLeft size={18} className={collapsed ? 'rotate-180' : ''} />
          {!collapsed && <span className="text-sm font-medium">Collapse</span>}
        </button>
      </div>
    </aside>
  )
}

export default Sidebar
