// ═══════════════════════════════════════════════════════════════
// FEATURE: TEMPERATURE PANEL
// Extracted from PrinterDetailPage — temperature control + history chart
// ═══════════════════════════════════════════════════════════════

import { useState, useEffect, useMemo } from 'react'
import { Thermometer } from 'lucide-react'
import {
  LineChart, Line, XAxis, YAxis, CartesianGrid,
  Tooltip as RechartsTooltip, ResponsiveContainer, Legend, ReferenceLine,
} from 'recharts'
import { clamp, getErrorMessage } from '@/utils/helpers'
import { printerApi } from '@/services/printer-api'
import { API_BASE_URL } from '@/utils/constants'
import type { Printer } from '@core/types/printer'

interface TempHistory {
  time: string; ts: number
  hotend: number; bed: number; chamber?: number
  hotendTarget: number; bedTarget: number
}

const TIME_RANGES = [
  { label: '1m',  ms:  1 * 60 * 1000 },
  { label: '5m',  ms:  5 * 60 * 1000 },
  { label: '30m', ms: 30 * 60 * 1000 },
  { label: '1h',  ms:  1 * 60 * 60 * 1000 },
  { label: '6h',  ms:  6 * 60 * 60 * 1000 },
  { label: '12h', ms: 12 * 60 * 60 * 1000 },
  { label: '24h', ms: 24 * 60 * 60 * 1000 },
  { label: '48h', ms: 48 * 60 * 60 * 1000 },
  { label: '72h', ms: 72 * 60 * 60 * 1000 },
] as const
type TimeRangeLabel = typeof TIME_RANGES[number]['label']

export function TemperaturePanel({ printer }: { printer: Printer }) {
  const temps = printer.liveState?.temperatures
  const hotend = temps?.hotend
  const bed = temps?.bed

  const [history, setHistory] = useState<TempHistory[]>([])
  const [historyLoaded, setHistoryLoaded] = useState(false)
  const [timeRange, setTimeRange] = useState<TimeRangeLabel>('1h')
  const [fetchedRange, setFetchedRange] = useState<TimeRangeLabel | null>(null)
  const [hotendInput, setHotendInput] = useState('')
  const [bedInput, setBedInput] = useState('')
  const [tempLoading, setTempLoading] = useState<'hotend' | 'bed' | null>(null)
  const [tempMsg, setTempMsg] = useState<{ type: 'success' | 'error'; text: string } | null>(null)
  const [optimisticHotend, setOptimisticHotend] = useState<number | null>(null)
  const [optimisticBed, setOptimisticBed] = useState<number | null>(null)
  const [pendingHotend, setPendingHotend] = useState<number | null>(null)
  const [pendingBed, setPendingBed] = useState<number | null>(null)

  const sendTemp = async (target: 'hotend' | 'bed', val: number) => {
    setTempLoading(target); setTempMsg(null); setPendingHotend(null); setPendingBed(null)
    try {
      await printerApi.sendCommand(printer.id, {
        type: target === 'hotend' ? 'set_hotend_temperature' : 'set_bed_temperature',
        params: { temperature: val },
      } as any)
      if (target === 'hotend') { setOptimisticHotend(val); setHotendInput('') }
      else { setOptimisticBed(val); setBedInput('') }
      setTempMsg({ type: 'success', text: `${target === 'hotend' ? 'Hotend' : 'Bed'} → ${val}°C` })
      setTimeout(() => setTempMsg(null), 3000)
    } catch (err) {
      setTempMsg({ type: 'error', text: `Error: ${getErrorMessage(err)}` })
    } finally { setTempLoading(null) }
  }

  const handleSetTemp = (target: 'hotend' | 'bed') => {
    const raw = target === 'hotend' ? hotendInput : bedInput
    const val = Number(raw)
    if (isNaN(val) || raw.trim() === '') return
    sendTemp(target, val)
  }

  const handlePreset = (target: 'hotend' | 'bed', val: number) => {
    if (target === 'hotend') {
      if (pendingHotend === val) sendTemp('hotend', val)
      else { setPendingHotend(val); setPendingBed(null) }
    } else {
      if (pendingBed === val) sendTemp('bed', val)
      else { setPendingBed(val); setPendingHotend(null) }
    }
  }

  const handleCoolDown = (target: 'hotend' | 'bed') => {
    const isPending = target === 'hotend' ? pendingHotend === 0 : pendingBed === 0
    if (isPending) sendTemp(target, 0)
    else {
      if (target === 'hotend') { setPendingHotend(0); setPendingBed(null) }
      else { setPendingBed(0); setPendingHotend(null) }
    }
  }

  useEffect(() => {
    const t = setTimeout(() => { setPendingHotend(null); setPendingBed(null) }, 4000)
    return () => clearTimeout(t)
  }, [pendingHotend, pendingBed])

  useEffect(() => { if ((hotend?.target ?? 0) > 0) setOptimisticHotend(null) }, [hotend?.target])
  useEffect(() => { if ((bed?.target ?? 0) > 0) setOptimisticBed(null) }, [bed?.target])

  const displayHotendTarget = optimisticHotend !== null ? optimisticHotend : (hotend?.target ?? 0)
  const displayBedTarget    = optimisticBed !== null ? optimisticBed : (bed?.target ?? 0)

  const filteredHistory = useMemo(() => {
    const rangeCfg = TIME_RANGES.find(r => r.label === timeRange)!
    const cutoff = Date.now() - rangeCfg.ms
    return history.filter(p => p.ts >= cutoff)
  }, [history, timeRange])

  // Load telemetry history
  useEffect(() => {
    const rangeCfg = TIME_RANGES.find(r => r.label === timeRange)!
    const prevIdx = fetchedRange ? TIME_RANGES.findIndex(r => r.label === fetchedRange) : -1
    const curIdx  = TIME_RANGES.findIndex(r => r.label === timeRange)
    if (fetchedRange !== null && curIdx <= prevIdx) return

    const count = Math.min(10000, Math.ceil(rangeCfg.ms / 1000 / 30) + 20)
    fetch(`${API_BASE_URL}/api/ai/printers/${printer.id}/telemetry?count=${count}`)
      .then(r => r.json())
      .then(data => {
        const points: TempHistory[] = (data?.data?.points ?? []).map((p: any) => {
          const d = new Date(p.timestamp)
          return {
            ts: d.getTime(),
            time: d.toLocaleTimeString('en-US', { hour12: false, hour: '2-digit', minute: '2-digit' }),
            hotend: p.temperatures?.hotend ?? 0, bed: p.temperatures?.bed ?? 0,
            chamber: p.temperatures?.chamber ?? undefined,
            hotendTarget: p.temperatures?.hotendTarget ?? 0, bedTarget: p.temperatures?.bedTarget ?? 0,
          }
        })
        if (points.length > 0) {
          setHistory(prev => {
            const fetchedTs = new Set(points.map(p => p.ts))
            const liveOnly = prev.filter(p => !fetchedTs.has(p.ts))
            return [...points, ...liveOnly].sort((a, b) => a.ts - b.ts)
          })
        }
        setFetchedRange(timeRange)
      })
      .catch(() => {})
      .finally(() => setHistoryLoaded(true))
  }, [printer.id, timeRange])

  // Append live readings
  useEffect(() => {
    if (!hotend || !bed) return
    const now = Date.now()
    const timeStr = new Date(now).toLocaleTimeString('en-US', { hour12: false, hour: '2-digit', minute: '2-digit' })
    setHistory(prev => {
      const last = prev[prev.length - 1]
      if (last && now - last.ts < 20_000) return prev
      return [...prev, {
        ts: now, time: timeStr,
        hotend: (hotend.actual ?? hotend.current) ?? 0, bed: (bed.actual ?? bed.current) ?? 0, chamber: temps?.chamber ? (temps.chamber.actual ?? temps.chamber.current) : undefined,
        hotendTarget: hotend.target ?? 0, bedTarget: bed.target ?? 0,
      }].slice(-10000)
    })
  }, [hotend?.actual ?? hotend?.current, bed?.actual ?? bed?.current])

  if (!temps || !hotend || !bed) {
    return (
      <div className="bg-gray-900/50 border border-gray-700 rounded-lg p-4">
        <h3 className="text-sm font-semibold text-gray-400 mb-2">Temperatures</h3>
        <p className="text-xs text-gray-500">No temperature data available</p>
      </div>
    )
  }

  const TempCard = ({ target, label, color, input, setInput, pending, onSet, onPreset, onCooldown, presets, progressColor }: {
    target: 'hotend' | 'bed'; label: string; color: string
    input: string; setInput: (v: string) => void
    pending: number | null; onSet: () => void
    onPreset: (v: number) => void; onCooldown: () => void
    presets: number[]; progressColor: string
  }) => {
    const isHotend = target === 'hotend'
    const current = isHotend ? ((hotend.actual ?? hotend.current) ?? 0) : ((bed.actual ?? bed.current) ?? 0)
    const displayTarget = isHotend ? displayHotendTarget : displayBedTarget

    return (
      <div className="bg-gray-800/50 rounded-lg p-2.5 space-y-2">
        <div className="text-[10px] text-gray-400 uppercase tracking-wide">{label}</div>
        <div className="flex items-baseline gap-1">
          <span className={`text-xl font-mono font-bold ${color}`}>{current.toFixed(1)}°</span>
          <span className="text-xs text-gray-500 font-mono">/ {displayTarget > 0 ? `${displayTarget}°C` : 'off'}</span>
        </div>
        {displayTarget > 0 && (
          <div className="h-1 bg-gray-700 rounded-full overflow-hidden">
            <div className={`h-full bg-gradient-to-r ${progressColor} rounded-full transition-all duration-500`}
              style={{ width: `${clamp((current / Math.max(1, displayTarget)) * 100, 0, 100)}%` }} />
          </div>
        )}
        <div className="flex gap-1">
          <input type="number" id={`temp-input-${target}`} name={`temp-input-${target}`} min={0} max={isHotend ? 350 : 150} value={input}
            onChange={e => setInput(e.target.value)}
            onKeyDown={e => e.key === 'Enter' && onSet()}
            placeholder="°C"
            className={`w-0 flex-1 px-1.5 py-1 bg-gray-900 border border-gray-600 rounded text-xs font-mono text-gray-200 placeholder-gray-600 focus:outline-none focus:border-${isHotend ? 'orange' : 'purple'}-500`}
          />
          <button onClick={onSet} disabled={tempLoading !== null || input === ''}
            className={`px-2 py-1 text-[10px] font-semibold bg-${isHotend ? 'orange' : 'purple'}-500/20 text-${isHotend ? 'orange' : 'purple'}-400 border border-${isHotend ? 'orange' : 'purple'}-500/40 rounded hover:bg-${isHotend ? 'orange' : 'purple'}-500/30 disabled:opacity-40`}>
            {tempLoading === target ? '…' : 'OK'}
          </button>
        </div>
        <div className="flex gap-1">
          {presets.map(t => (
            <button key={t} onClick={() => onPreset(t)} disabled={tempLoading !== null}
              className={`flex-1 py-0.5 text-[10px] rounded border transition-all ${pending === t
                ? `bg-${isHotend ? 'orange' : 'purple'}-500 text-white border-${isHotend ? 'orange' : 'purple'}-400 animate-pulse font-bold`
                : 'bg-gray-900 text-gray-400 border-gray-700 hover:text-gray-200'} disabled:opacity-40`}>
              {pending === t ? `✓${t}` : t}
            </button>
          ))}
        </div>
        <button onClick={onCooldown} disabled={tempLoading !== null}
          className={`w-full py-0.5 text-[10px] rounded border transition-all ${pending === 0
            ? 'bg-red-500/30 text-red-300 border-red-500 animate-pulse font-bold'
            : 'bg-gray-900 text-gray-500 border-gray-700 hover:text-red-400'} disabled:opacity-40`}>
          {pending === 0 ? 'Confirm → Reset?' : '❄ Reset'}
        </button>
      </div>
    )
  }

  return (
    <div className="bg-gray-900/50 border border-gray-700 rounded-lg p-4">
      <h3 className="flex items-center gap-2 text-sm font-semibold text-gray-200 mb-3">
        <Thermometer className="w-4 h-4 text-orange-400" />Temperatures
      </h3>

      <div className="grid grid-cols-2 gap-3 mb-3">
        <TempCard
          target="hotend" label="Hotend" color="text-orange-400"
          input={hotendInput} setInput={setHotendInput}
          pending={pendingHotend} onSet={() => handleSetTemp('hotend')}
          onPreset={v => handlePreset('hotend', v)} onCooldown={() => handleCoolDown('hotend')}
          presets={[150, 200, 220, 250]} progressColor="from-orange-500 to-red-500"
        />
        <TempCard
          target="bed" label="Bed" color="text-purple-400"
          input={bedInput} setInput={setBedInput}
          pending={pendingBed} onSet={() => handleSetTemp('bed')}
          onPreset={v => handlePreset('bed', v)} onCooldown={() => handleCoolDown('bed')}
          presets={[40, 60, 80, 100]} progressColor="from-purple-500 to-blue-500"
        />
        {temps?.chamber && (
          <div className="bg-gray-800/50 rounded-lg p-2.5 col-span-2">
            <div className="text-[10px] text-gray-400 uppercase tracking-wide mb-1">Chamber</div>
            <span className="text-lg font-mono font-bold text-cyan-400">{((temps.chamber.actual ?? temps.chamber.current) ?? 0).toFixed(1)}°</span>
            <span className="text-xs text-gray-500 ml-1">/ {temps.chamber.target}°C</span>
          </div>
        )}
      </div>

      {tempMsg && (
        <div className={`mb-2 text-xs px-2 py-1 rounded border ${tempMsg.type === 'success' ? 'bg-green-500/10 border-green-500/30 text-green-400' : 'bg-red-500/10 border-red-500/30 text-red-400'}`}>
          {tempMsg.type === 'success' ? '✓' : '✗'} {tempMsg.text}
        </div>
      )}

      {/* Temperature Chart */}
      <div className="border-t border-gray-700 pt-3">
        <div className="flex items-center justify-between mb-2">
          <span className="text-[10px] text-gray-500">
            {!historyLoaded && history.length === 0 ? 'Loading…' : `${filteredHistory.length} readings · ${timeRange}`}
          </span>
          <div className="flex gap-0.5">
            {TIME_RANGES.map(r => (
              <button key={r.label} onClick={() => setTimeRange(r.label)}
                className={`px-1.5 py-0.5 text-[10px] rounded transition-all ${timeRange === r.label
                  ? 'bg-cyan-500/20 text-cyan-400 border border-cyan-500/50'
                  : 'text-gray-500 hover:text-gray-300 border border-transparent'}`}>
                {r.label}
              </button>
            ))}
          </div>
        </div>
        {!historyLoaded && history.length === 0 && <div className="h-[180px] bg-gray-800/30 rounded animate-pulse" />}
        {historyLoaded && filteredHistory.length === 0 && (
          <div className="h-[180px] flex items-center justify-center text-xs text-gray-600">No data for this time range</div>
        )}
        {filteredHistory.length > 0 && (
          <ResponsiveContainer width="100%" height={180}>
            <LineChart data={filteredHistory} key={timeRange} margin={{ top: 5, right: 5, left: -20, bottom: 0 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#374151" />
              <XAxis dataKey="time" tick={{ fill: '#6B7280', fontSize: 10 }} interval={Math.max(0, Math.floor(filteredHistory.length / 6))} />
              <YAxis tick={{ fill: '#6B7280', fontSize: 10 }} domain={['dataMin - 5', 'dataMax + 10']} unit="°" />
              <RechartsTooltip
                contentStyle={{ backgroundColor: '#1F2937', border: '1px solid #374151', borderRadius: '8px', fontSize: '12px' }}
                labelStyle={{ color: '#9CA3AF' }}
                formatter={(value: number, name: string) => [`${value.toFixed(1)}°C`, name === 'hotend' ? 'Hotend' : name === 'bed' ? 'Bed' : 'Chamber']}
              />
              <Legend wrapperStyle={{ fontSize: '11px' }} formatter={(v: string) => v === 'hotend' ? 'Hotend' : v === 'bed' ? 'Bed' : 'Chamber'} />
              {displayHotendTarget > 0 && <ReferenceLine y={displayHotendTarget} stroke="#F97316" strokeDasharray="4 4" strokeOpacity={0.4} />}
              {displayBedTarget > 0 && <ReferenceLine y={displayBedTarget} stroke="#A855F7" strokeDasharray="4 4" strokeOpacity={0.4} />}
              <Line type="monotone" dataKey="hotend" stroke="#F97316" strokeWidth={2} dot={false} activeDot={{ r: 4 }} isAnimationActive={false} />
              <Line type="monotone" dataKey="bed"    stroke="#A855F7" strokeWidth={2} dot={false} activeDot={{ r: 4 }} isAnimationActive={false} />
              {temps?.chamber && <Line type="monotone" dataKey="chamber" stroke="#22D3EE" strokeWidth={2} dot={false} isAnimationActive={false} />}
            </LineChart>
          </ResponsiveContainer>
        )}
      </div>
    </div>
  )
}
