// ═══════════════════════════════════════════════════════════════
// PRESTIGE DASHBOARD - CONFIRM DIALOG COMPONENT
// ═══════════════════════════════════════════════════════════════

import React, { useState } from 'react'
import * as Dialog from '@radix-ui/react-dialog'
import { AlertTriangle, Info, CheckCircle, AlertCircle, X } from 'lucide-react'
import type { ConfirmDialogProps, VariantConfig } from './ConfirmDialog.types'

/**
 * Variant configurations
 */
const VARIANT_CONFIG: Record<string, VariantConfig> = {
  danger: {
    icon: '⚠️',
    color: '#ef4444',
    borderColor: 'rgba(239, 68, 68, 0.5)',
    backgroundColor: 'rgba(239, 68, 68, 0.1)',
    confirmButtonClass: 'bg-red-600 hover:bg-red-700 border-red-500 text-white',
  },
  warning: {
    icon: '⚡',
    color: '#f59e0b',
    borderColor: 'rgba(245, 158, 11, 0.5)',
    backgroundColor: 'rgba(245, 158, 11, 0.1)',
    confirmButtonClass: 'bg-amber-600 hover:bg-amber-700 border-amber-500 text-white',
  },
  info: {
    icon: 'ℹ️',
    color: '#3b82f6',
    borderColor: 'rgba(59, 130, 246, 0.5)',
    backgroundColor: 'rgba(59, 130, 246, 0.1)',
    confirmButtonClass: 'bg-blue-600 hover:bg-blue-700 border-blue-500 text-white',
  },
  success: {
    icon: '✅',
    color: '#10b981',
    borderColor: 'rgba(16, 185, 129, 0.5)',
    backgroundColor: 'rgba(16, 185, 129, 0.1)',
    confirmButtonClass: 'bg-green-600 hover:bg-green-700 border-green-500 text-white',
  },
}

/**
 * Size classes
 */
const SIZE_CLASSES = {
  sm: 'max-w-sm',
  md: 'max-w-md',
  lg: 'max-w-lg',
}

/**
 * Get icon component based on variant
 */
const getIconComponent = (variant: string): React.ReactNode => {
  const iconClass = 'w-6 h-6'
  
  switch (variant) {
    case 'danger':
      return <AlertTriangle className={iconClass} />
    case 'warning':
      return <AlertCircle className={iconClass} />
    case 'info':
      return <Info className={iconClass} />
    case 'success':
      return <CheckCircle className={iconClass} />
    default:
      return <Info className={iconClass} />
  }
}

/**
 * ConfirmDialog Component
 * 
 * A reusable confirmation dialog built with Radix UI.
 * Supports different variants (danger, warning, info, success) for different use cases.
 * 
 * @example
 * ```tsx
 * <ConfirmDialog
 *   open={isOpen}
 *   title="Delete Printer"
 *   description="Are you sure you want to delete this printer? This action cannot be undone."
 *   variant="danger"
 *   confirmLabel="Delete"
 *   onConfirm={handleDelete}
 *   onCancel={() => setIsOpen(false)}
 * />
 * ```
 */
export const ConfirmDialog: React.FC<ConfirmDialogProps> = ({
  open,
  title,
  description,
  confirmLabel = 'Confirm',
  cancelLabel = 'Cancel',
  variant = 'info',
  size = 'md',
  showIcon = true,
  icon,
  loading = false,
  closeOnOverlayClick = false,
  closeOnEscape = true,
  onConfirm,
  onCancel,
  onOpenChange,
  className = '',
  footer,
  disableConfirm = false,
  disableCancel = false,
}) => {
  const [isConfirming, setIsConfirming] = useState(false)
  
  const config = VARIANT_CONFIG[variant]

  /**
   * Handle confirm click
   */
  const handleConfirm = async () => {
    try {
      setIsConfirming(true)
      await onConfirm()
    } catch (error) {
      console.error('Confirmation action failed:', error)
    } finally {
      setIsConfirming(false)
    }
  }

  /**
   * Handle dialog open change
   */
  const handleOpenChange = (newOpen: boolean) => {
    if (!newOpen && !isConfirming && !loading) {
      onCancel()
    }
    onOpenChange?.(newOpen)
  }

  /**
   * Handle cancel click
   */
  const handleCancel = () => {
    if (!isConfirming && !loading) {
      onCancel()
    }
  }

  return (
    <Dialog.Root open={open} onOpenChange={handleOpenChange}>
      <Dialog.Portal>
        {/* Overlay */}
        <Dialog.Overlay 
          className="fixed inset-0 z-[9999] bg-black/80 backdrop-blur-sm data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0"
        />

        {/* Content */}
        <Dialog.Content
          className={`
            fixed left-[50%] top-[50%] z-[10000] 
            translate-x-[-50%] translate-y-[-50%]
            w-full ${SIZE_CLASSES[size]} mx-4
            rounded-lg border-2 bg-gray-900 shadow-2xl
            data-[state=open]:animate-in data-[state=closed]:animate-out 
            data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 
            data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 
            data-[state=closed]:slide-out-to-left-1/2 data-[state=closed]:slide-out-to-top-[48%] 
            data-[state=open]:slide-in-from-left-1/2 data-[state=open]:slide-in-from-top-[48%]
            ${className}
          `}
          style={{
            borderColor: config.borderColor,
            boxShadow: `0 0 40px ${config.borderColor}`,
          }}
          onPointerDownOutside={(e) => {
            if (!closeOnOverlayClick) {
              e.preventDefault()
            }
          }}
          onEscapeKeyDown={(e) => {
            if (!closeOnEscape) {
              e.preventDefault()
            }
          }}
        >
          {/* Header */}
          <div className="flex items-start gap-4 p-6 pb-4">
            {/* Icon */}
            {showIcon && (
              <div 
                className="flex-shrink-0 flex items-center justify-center w-12 h-12 rounded-full border-2"
                style={{
                  backgroundColor: config.backgroundColor,
                  borderColor: config.borderColor,
                  color: config.color,
                }}
              >
                {icon ? (
                  typeof icon === 'string' ? (
                    <span className="text-2xl">{icon}</span>
                  ) : (
                    icon
                  )
                ) : (
                  <div style={{ color: config.color }}>
                    {getIconComponent(variant)}
                  </div>
                )}
              </div>
            )}

            {/* Title and Close */}
            <div className="flex-1 min-w-0">
              <div className="flex items-start justify-between gap-4">
                <Dialog.Title className="text-xl font-bold text-white leading-tight">
                  {title}
                </Dialog.Title>
                
                <Dialog.Close
                  className="flex-shrink-0 rounded-md p-1 text-gray-400 hover:text-gray-200 hover:bg-gray-800 transition-colors disabled:opacity-50"
                  disabled={isConfirming || loading}
                  onClick={handleCancel}
                >
                  <X className="w-5 h-5" />
                  <span className="sr-only">Close</span>
                </Dialog.Close>
              </div>
            </div>
          </div>

          {/* Description */}
          <div className="px-6 pb-6">
            <Dialog.Description className="text-gray-300 leading-relaxed">
              {description}
            </Dialog.Description>
          </div>

          {/* Footer */}
          <div className="flex flex-col gap-3 px-6 pb-6">
            {footer}
            
            {/* Actions */}
            <div className="flex items-center gap-3 justify-end">
              <button
                type="button"
                onClick={handleCancel}
                disabled={isConfirming || loading || disableCancel}
                className="px-4 py-2 rounded-lg border border-gray-700 bg-gray-800 text-gray-300 font-medium hover:bg-gray-750 hover:border-gray-600 transition-all disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {cancelLabel}
              </button>
              
              <button
                type="button"
                onClick={handleConfirm}
                disabled={isConfirming || loading || disableConfirm}
                className={`
                  px-4 py-2 rounded-lg border-2 font-medium transition-all 
                  disabled:opacity-50 disabled:cursor-not-allowed
                  ${config.confirmButtonClass}
                `}
              >
                {isConfirming || loading ? (
                  <span className="flex items-center gap-2">
                    <span className="inline-block w-4 h-4 border-2 border-white/20 border-t-white rounded-full animate-spin" />
                    Processing...
                  </span>
                ) : (
                  confirmLabel
                )}
              </button>
            </div>
          </div>
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  )
}

ConfirmDialog.displayName = 'ConfirmDialog'

export default ConfirmDialog
