import { motion } from 'framer-motion'

interface PageTransitionProps {
  children: React.ReactNode
  routeKey: string
}

const variants = {
  initial: {
    opacity: 0,
    y: 14,
    scale: 0.98,
    filter: 'blur(4px)',
  },
  animate: {
    opacity: 1,
    y: 0,
    scale: 1,
    filter: 'blur(0px)',
    transition: {
      duration: 0.3,
      ease: [0.25, 0.46, 0.45, 0.94],
    },
  },
  exit: {
    opacity: 0,
    y: -8,
    scale: 0.98,
    filter: 'blur(2px)',
    transition: {
      duration: 0.18,
      ease: [0.55, 0, 1, 0.45],
    },
  },
}

export function PageTransition({ children, routeKey }: PageTransitionProps) {
  return (
    <motion.div
      key={routeKey}
      variants={variants}
      initial="initial"
      animate="animate"
      exit="exit"
      className="h-full w-full"
    >
      {children}
    </motion.div>
  )
}
