// ── Healthy baseline constants ────────────────────────────────
const HEALTHY_BASELINE = {
  hotendVarianceDegC:     0.5,
  bedVarianceDegC:        1.0,
  pidOvershootDegC:       2.0,
  thermalRunaway:         false,
  resonanceFreqMin:       30,
  resonanceFreqMax:       80,
  residualVibrationsPct:  5,
  axesNoise:              100,
  skippedSteps:           0,
  flowConsistencyPct:     95,
  clogRiskPct:            15,
  pressureDeltaBar:       0.05,
  pressureAdvance:        0.05,
  stringing:              'none',
  retractionMm:           1.0,
} as const

// ── Scoring engine ────────────────────────────────────────────
function scoreAgainstBaseline(
  testId: string,
  analysis: AnalysisResult | null
): { score: number; status: DiagnosticTestResult['status']; metrics: DiagnosticTestResult['metrics']; details: string } {
  const h     = analysis?.healthScore     ?? 80
  const q     = analysis?.qualityScore    ?? 80
  const clog  = (analysis?.clogRisk       ?? 0.10) * 100
  const failR = (analysis?.failureRisk    ?? 0.05) * 100
  const wear  = analysis?.wearSeverity    ?? 'ok'
  const motor = analysis?.motorLoadSeverity ?? 'ok'

  const estHotendVariance = h >= 95 ? 0.3 : h >= 80 ? 0.6 : h >= 65 ? 1.2 : 2.5
  const estBedVariance    = h >= 90 ? 0.5 : h >= 75 ? 1.1 : 2.0
  const estResonanceFreq  = 40 + (h - 80) * 0.3
  const estVibrations     = h >= 90 ? 2.5 : h >= 80 ? 4.5 : h >= 65 ? 9 : 18
  const estFlowConsist    = 100 - clog * 0.7
  const estPressureDelta  = clog * 0.04 / 100
  const estPA             = q >= 85 ? 0.04 : q >= 70 ? 0.06 : 0.10
  const estStringing      = q >= 88 ? 'None' : q >= 75 ? 'Minimal' : q >= 60 ? 'Moderate' : 'High'

  const wearBad   = wear  === 'critical' || wear  === 'warning'
  const motorBad  = motor === 'critical' || motor === 'warning'

  if (testId === 'extrusion') {
    const flowOk   = estFlowConsist >= HEALTHY_BASELINE.flowConsistencyPct
    const clogOk   = clog           <  HEALTHY_BASELINE.clogRiskPct
    const pressOk  = estPressureDelta < HEALTHY_BASELINE.pressureDeltaBar
    const score    = Math.round(
      (estFlowConsist / 100) * 50 +
      Math.max(0, (HEALTHY_BASELINE.clogRiskPct - clog) / HEALTHY_BASELINE.clogRiskPct) * 30 +
      (pressOk ? 20 : Math.max(0, 20 - estPressureDelta * 200))
    )
    const status: DiagnosticTestResult['status'] = clog > 50 ? 'fail' : clog > 25 || !flowOk ? 'warning' : 'pass'
    return {
      score: Math.min(100, Math.max(0, score)), status,
      details:
        `Extrusion flow analysis based on telemetry data (${analysis?.telemetryPoints ?? 0} data points).\n` +
        `Flow consistency: ${estFlowConsist.toFixed(1)}% — healthy standard: >=95%.\n` +
        `Clog risk: ${clog.toFixed(1)}% — healthy standard: <${HEALTHY_BASELINE.clogRiskPct}% (industry typical 20-25%).\n` +
        (clog < 15 ? 'Extrusion path is clean. No action needed.' :
          clog < 30 ? 'Slight flow inconsistency detected. Monitor and consider a cold pull.' :
          'High clog risk. Perform a cold pull or nozzle replacement.'),
      metrics: [
        { label: 'Flow Consistency',        value: `${estFlowConsist.toFixed(1)}%`,     status: flowOk ? 'ok' : 'warn' },
        { label: 'Healthy Standard',         value: `>=95%`,                            status: 'ok' },
        { label: 'Clog Risk',               value: `${clog.toFixed(1)}%`,               status: clogOk ? 'ok' : clog < 30 ? 'warn' : 'bad' },
        { label: 'Healthy Standard (Clog)', value: `<${HEALTHY_BASELINE.clogRiskPct}%`, status: 'ok' },
        { label: 'Pressure Delta',          value: `${(estPressureDelta * 1000).toFixed(0)} mbar`, status: pressOk ? 'ok' : 'warn' },
        { label: 'Healthy Standard',        value: `<50 mbar`,                           status: 'ok' },
      ],
    }
  }

  if (testId === 'movement') {
    const freqOk  = estResonanceFreq >= HEALTHY_BASELINE.resonanceFreqMin && estResonanceFreq <= HEALTHY_BASELINE.resonanceFreqMax
    const vibOk   = estVibrations    <= HEALTHY_BASELINE.residualVibrationsPct
    const wearOk  = !wearBad
    const motorOk = !motorBad
    const score   = Math.round(
      (freqOk ? 30 : 15) +
      Math.max(0, 25 - Math.max(0, estVibrations - HEALTHY_BASELINE.residualVibrationsPct) * 2) +
      (wearOk ? 25 : 10) +
      (motorOk ? 20 : 8)
    )
    const status: DiagnosticTestResult['status'] =
      !wearOk || estVibrations > 15 ? 'fail' :
      !freqOk || !vibOk || !motorOk ? 'warning' : 'pass'
    return {
      score: Math.min(100, Math.max(0, score)), status,
      details:
        `Movement and resonance analysis using ${analysis?.telemetryPoints ?? 0} telemetry points.\n` +
        `Estimated resonance: ~${estResonanceFreq.toFixed(0)} Hz — healthy range: ${HEALTHY_BASELINE.resonanceFreqMin}-${HEALTHY_BASELINE.resonanceFreqMax} Hz (Klipper docs).\n` +
        `Residual vibrations: ~${estVibrations.toFixed(1)}% — healthy with MZV shaper: <${HEALTHY_BASELINE.residualVibrationsPct}%.\n` +
        (wearBad ? `Component wear detected (${wear}). Inspect belts, rails, and lead screws.` :
          motorBad ? `High motor load detected. Check for binding or overtightened belts.` :
          'Motion system within healthy parameters.'),
      metrics: [
        { label: 'Est. Resonance Freq.',   value: `${estResonanceFreq.toFixed(0)} Hz`,      status: freqOk ? 'ok' : 'warn' },
        { label: 'Healthy Range',          value: `${HEALTHY_BASELINE.resonanceFreqMin}-${HEALTHY_BASELINE.resonanceFreqMax} Hz`, status: 'ok' },
        { label: 'Residual Vibrations',    value: `${estVibrations.toFixed(1)}%`,            status: vibOk ? 'ok' : estVibrations < 12 ? 'warn' : 'bad' },
        { label: 'Healthy Standard',       value: `<${HEALTHY_BASELINE.residualVibrationsPct}% (Klipper MZV)`, status: 'ok' },
        { label: 'Component Wear',         value: wear.charAt(0).toUpperCase() + wear.slice(1), status: wearOk ? 'ok' : wearBad ? 'bad' : 'warn' },
        { label: 'Motor Load',             value: motor.charAt(0).toUpperCase() + motor.slice(1), status: motorOk ? 'ok' : 'warn' },
      ],
    }
  }

  if (testId === 'temperature') {
    const hotOk  = estHotendVariance <= HEALTHY_BASELINE.hotendVarianceDegC
    const bedOk  = estBedVariance    <= HEALTHY_BASELINE.bedVarianceDegC
    const score  = Math.round(
      Math.max(0, 50 - (estHotendVariance - HEALTHY_BASELINE.hotendVarianceDegC) * 20) +
      Math.max(0, 30 - (estBedVariance - HEALTHY_BASELINE.bedVarianceDegC) * 10) +
      (h >= 85 ? 20 : h >= 70 ? 12 : 5)
    )
    const status: DiagnosticTestResult['status'] =
      estHotendVariance > 2.0 ? 'fail' : !hotOk || !bedOk ? 'warning' : 'pass'
    return {
      score: Math.min(100, Math.max(0, score)), status,
      details:
        `Temperature stability analysis from heater telemetry.\n` +
        `Hotend variance: +/-${estHotendVariance.toFixed(1)}C — healthy standard: +/-${HEALTHY_BASELINE.hotendVarianceDegC}C (Klipper PID docs).\n` +
        `Bed variance: +/-${estBedVariance.toFixed(1)}C — healthy standard: +/-${HEALTHY_BASELINE.bedVarianceDegC}C.\n` +
        (!hotOk ? 'Hotend PID needs re-tuning. Run PID_CALIBRATE HEATER=extruder TARGET=215' :
          'Temperature control is stable and within healthy parameters.'),
      metrics: [
        { label: 'Hotend Variance',        value: `+/-${estHotendVariance.toFixed(1)}C`, status: hotOk ? 'ok' : estHotendVariance < 1.5 ? 'warn' : 'bad' },
        { label: 'Healthy Standard',       value: `+/-${HEALTHY_BASELINE.hotendVarianceDegC}C`,  status: 'ok' },
        { label: 'Bed Variance',           value: `+/-${estBedVariance.toFixed(1)}C`,    status: bedOk ? 'ok' : 'warn' },
        { label: 'Healthy Standard',       value: `+/-${HEALTHY_BASELINE.bedVarianceDegC}C`,    status: 'ok' },
        { label: 'PID Tuning Quality',     value: hotOk ? 'Excellent' : estHotendVariance < 1.0 ? 'Good' : 'Needs tuning', status: hotOk ? 'ok' : 'warn' },
        { label: 'Thermal Runaway',        value: 'Protected',                    status: 'ok' },
      ],
    }
  }

  if (testId === 'retraction') {
    const strOk  = estStringing === 'None' || estStringing === 'Minimal'
    const paOk   = estPA <= HEALTHY_BASELINE.pressureAdvance * 2
    const score  = Math.round(
      (q / 100) * 60 +
      (strOk ? 25 : estStringing === 'Moderate' ? 12 : 0) +
      (paOk ? 15 : 5)
    )
    const status: DiagnosticTestResult['status'] = estStringing === 'High' ? 'fail' : !strOk ? 'warning' : 'pass'
    return {
      score: Math.min(100, Math.max(0, score)), status,
      details:
        `Retraction and pressure advance analysis.\n` +
        `Stringing level: ${estStringing} — healthy: None or Minimal.\n` +
        `Est. Pressure Advance: ${estPA.toFixed(3)} — healthy calibrated range: ${HEALTHY_BASELINE.pressureAdvance - 0.03}-0.08.\n` +
        (strOk ? 'Retraction and pressure advance are well tuned.' :
          'Consider adjusting retraction distance and re-tuning Pressure Advance.'),
      metrics: [
        { label: 'Stringing Level',        value: estStringing,                       status: strOk ? 'ok' : estStringing === 'Moderate' ? 'warn' : 'bad' },
        { label: 'Healthy Standard',       value: 'None / Minimal',                  status: 'ok' },
        { label: 'Est. Pressure Advance',  value: estPA.toFixed(3),                  status: paOk ? 'ok' : 'warn' },
        { label: 'Healthy Range (PA)',     value: '0.02-0.08',                        status: 'ok' },
        { label: 'Print Quality Score',    value: `${q.toFixed(0)}/100`,             status: q >= 80 ? 'ok' : q >= 60 ? 'warn' : 'bad' },
        { label: 'Quality Standard',      value: '>=80/100',                          status: 'ok' },
      ],
    }
  }

  if (testId === 'printer_status') {
    const isOnline     = h >= 40
    const sensorsOk    = h >= 50
    const homingEst    = h >= 85 ? 35 : h >= 70 ? 25 : h >= 55 ? 14 : 5
    const consoleScore = isOnline ? 25 : 0
    const sensorScore  = sensorsOk ? 25 : isOnline ? 15 : 0
    const score        = Math.min(100, Math.max(0, consoleScore + homingEst + sensorScore + 15))
    const status: DiagnosticTestResult['status'] = !isOnline ? 'fail' : h < 60 || !sensorsOk ? 'warning' : 'pass'
    return {
      score: Math.min(100, Math.max(0, score)), status,
      details:
        `Printer status check using ${analysis?.telemetryPoints ?? 0} telemetry data points.\n` +
        `Connection: ${isOnline ? 'Responding' : 'Not responding'}.\n` +
        `Sensors: ${sensorsOk ? 'Hotend and bed sensors readable' : 'Sensor data limited'}.\n` +
        `Health score: ${h.toFixed(0)}/100 — estimated motion system reliability: ${h >= 85 ? 'Excellent' : h >= 70 ? 'Good' : 'Needs attention'}.\n` +
        (!isOnline ? 'Printer not responding. Check Klipper/Moonraker connection.' :
          h < 60 ? 'Health score low. Run while idle for a full live GCode check (M115 + G28 + M105).' :
          'Printer appears operational. Run while idle for a complete hardware verification.'),
      metrics: [
        { label: 'Connection Status',   value: isOnline ? 'Responding' : 'Offline',          status: isOnline ? 'ok' : 'bad' },
        { label: 'GCode Console',       value: isOnline ? 'Reachable' : 'No response',        status: isOnline ? 'ok' : 'bad' },
        { label: 'Sensor Readings',     value: sensorsOk ? 'Available' : 'Limited',           status: sensorsOk ? 'ok' : 'warn' },
        { label: 'Health Score',        value: `${h.toFixed(0)}/100`,                         status: h >= 80 ? 'ok' : h >= 60 ? 'warn' : 'bad' },
        { label: 'Healthy Standard',    value: '>=80/100',                                    status: 'ok' },
        { label: 'Motion Reliability',  value: h >= 85 ? 'Excellent' : h >= 70 ? 'Good' : 'Needs attention', status: h >= 85 ? 'ok' : h >= 70 ? 'warn' : 'bad' },
      ],
    }
  }

  // full composite
  const ext  = scoreAgainstBaseline('extrusion',   analysis)
  const mov  = scoreAgainstBaseline('movement',    analysis)
  const temp = scoreAgainstBaseline('temperature', analysis)
  const ret  = scoreAgainstBaseline('retraction',  analysis)
  const composite = Math.round(ext.score * 0.3 + mov.score * 0.25 + temp.score * 0.25 + ret.score * 0.2)
  const anyFail = [ext, mov, temp, ret].some(r => r.status === 'fail')
  const anyWarn = [ext, mov, temp, ret].some(r => r.status === 'warning')
  return {
    score: composite,
    status: anyFail ? 'fail' : anyWarn ? 'warning' : 'pass',
    details:
      `Full system diagnostic complete. Composite score: ${composite}/100 vs healthy printer standard (100/100).\n` +
      `Extrusion: ${ext.score}/100 | Movement: ${mov.score}/100 | Temp: ${temp.score}/100 | Retraction: ${ret.score}/100.\n` +
      (composite >= 85 ? 'Printer is in excellent condition — meets or exceeds all healthy standards.' :
        composite >= 70 ? 'Minor deviations from healthy standards. Review individual test results.' :
        'Significant issues found. Maintenance or calibration recommended.'),
    metrics: [
      { label: 'Extrusion Score',   value: `${ext.score}/100`,   status: ext.status === 'pass' ? 'ok' : ext.status === 'warning' ? 'warn' : 'bad' },
      { label: 'Movement Score',    value: `${mov.score}/100`,   status: mov.status === 'pass' ? 'ok' : mov.status === 'warning' ? 'warn' : 'bad' },
      { label: 'Temperature Score', value: `${temp.score}/100`,  status: temp.status === 'pass' ? 'ok' : temp.status === 'warning' ? 'warn' : 'bad' },
      { label: 'Retraction Score',  value: `${ret.score}/100`,   status: ret.status === 'pass' ? 'ok' : ret.status === 'warning' ? 'warn' : 'bad' },
      { label: 'Composite',         value: `${composite}/100`,   status: composite >= 85 ? 'ok' : composite >= 65 ? 'warn' : 'bad' },
      { label: 'Healthy Standard',  value: '>=85/100',           status: 'ok' },
    ],
  }
}

// ── Purge position mini-form ──────────────────────────────────
function PurgePositionConfig({ printerId }: { printerId: string }) {
  const [x, setX] = useState<number | ''>(10)
  const [y, setY] = useState<number | ''>(10)
  const [saved, setSaved] = useState(false)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    fetch(`/api/printers/${printerId}/purge-position`)
      .then(r => r.json())
      .then(d => { const pos = d?.data ?? d; setX(pos?.x ?? 10); setY(pos?.y ?? 10) })
      .catch(() => {})
      .finally(() => setLoading(false))
  }, [printerId])

  const save = async () => {
    const res = await fetch(`/api/printers/${printerId}/purge-position`, {
      method: 'PUT', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ x: Number(x) || 10, y: Number(y) || 10 }),
    })
    if (res.ok) { setSaved(true); setTimeout(() => setSaved(false), 2500) }
  }

  if (loading) return null

  return (
    <div className="rounded-lg border border-gray-700/60 bg-gray-900/40 px-4 py-3">
      <div className="flex items-center gap-2 mb-2">
        <Move className="w-3.5 h-3.5 text-blue-400" />
        <span className="text-xs font-semibold text-gray-300">Purge / Safe Position for Extrusion Test</span>
        <span className="text-[10px] text-gray-500 ml-1">— toolhead moves here before extruding</span>
      </div>
      <div className="flex items-center gap-3">
        <label htmlFor="purge-pos-x" className="flex items-center gap-1.5 text-xs text-gray-400">
          X
          <input id="purge-pos-x" name="purge-pos-x" type="number" min={0} max={500} step={1} value={x}
            onChange={e => setX(e.target.value === '' ? '' : Number(e.target.value))}
            className="w-16 rounded bg-gray-800 border border-gray-600 text-gray-100 text-xs px-2 py-1 text-center focus:outline-none focus:border-cyan-500" />
          mm
        </label>
        <label htmlFor="purge-pos-y" className="flex items-center gap-1.5 text-xs text-gray-400">
          Y
          <input id="purge-pos-y" name="purge-pos-y" type="number" min={0} max={500} step={1} value={y}
            onChange={e => setY(e.target.value === '' ? '' : Number(e.target.value))}
            className="w-16 rounded bg-gray-800 border border-gray-600 text-gray-100 text-xs px-2 py-1 text-center focus:outline-none focus:border-cyan-500" />
          mm
        </label>
        <button onClick={save}
          className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold bg-blue-500/20 text-blue-400 border border-blue-500/30 hover:bg-blue-500/30 transition-colors active:scale-95">
          {saved ? <><CheckCircle className="w-3 h-3" /> Saved</> : 'Save'}
        </button>
        <span className="text-[10px] text-gray-500">Default: X10 Y10 (front-left)</span>
      </div>
    </div>
  )
}

// ── Main DiagnosticsTab component ─────────────────────────────
export interface AIDiagnosticsTabProps {
  printerId: string
  lastAnalysis: AnalysisResult | null
  autoRunTestId?: string
  onRefresh: () => void
}

export function AIDiagnosticsTab({ printerId, lastAnalysis: lastAnalysisProp, autoRunTestId, onRefresh }: AIDiagnosticsTabProps) {
  const [localAnalysis, setLocalAnalysis] = useState<AnalysisResult | null>(lastAnalysisProp)
  const lastAnalysis = localAnalysis ?? lastAnalysisProp

  useEffect(() => {
    if (lastAnalysisProp) setLocalAnalysis(lastAnalysisProp)
  }, [lastAnalysisProp])

  const [results, setResults] = useState<Record<string, DiagnosticTestResult>>({})
  const [running, setRunning] = useState<string | null>(null)
  const [benchmark, setBenchmark] = useState<GlobalBenchmark | null>(null)
  const [benchmarkLoading, setBenchmarkLoading] = useState(false)
  const [expandedTest, setExpandedTest] = useState<string | null>(null)
  const [completedTest, setCompletedTest] = useState<{ id: string; status: DiagnosticTestResult['status']; score: number; flashKey: number } | null>(null)
  const [flashTest, setFlashTest] = useState<string | null>(null)
  const completedNotifRef = useRef<HTMLDivElement>(null)

  const [klipperState, setKlipperState] = useState<{ state: string; message: string } | null>(null)
  const klipperReady = !klipperState || klipperState.state === 'ready'

  useEffect(() => {
    let cancelled = false
    const check = async () => {
      try {
        const res = await fetch(`/api/ai/printers/${printerId}/klipper-state`)
        if (!res.ok) return
        const d = await res.json()
        const info = d?.data ?? d
        if (!cancelled) setKlipperState({ state: info?.klipperState ?? 'unknown', message: info?.stateMessage ?? '' })
      } catch { /* silent */ }
    }
    check()
    const interval = setInterval(check, 8_000)
    return () => { cancelled = true; clearInterval(interval) }
  }, [printerId])

  const printerIsOnline = usePrinterStore(state => {
    const p = state.printers[printerId]
    if (!p) return false
    const s = (p.status ?? '').toLowerCase()
    return s === 'idle' || s === 'printing' || s === 'paused' || s === 'online' || s === 'connected' || s === 'ready' || s === 'operational'
  })

  // Load saved results: first from backend (persistent), then merge with localStorage
  useEffect(() => {
    const loadSavedResults = async () => {
      try {
        // 1. Load from backend disk (survives page close/server restart)
        const res = await fetch(`/api/ai/printers/${printerId}/diagnostics/results`)
        if (res.ok) {
          const d = await res.json()
          const backendResults: Record<string, DiagnosticTestResult> = d?.data?.results ?? d?.results ?? {}
          if (Object.keys(backendResults).length > 0) {
            setResults(backendResults)
            // Sync to localStorage so offline fallback is also up to date
            try { localStorage.setItem(`prestige_diag_${printerId}`, JSON.stringify(backendResults)) } catch {}
            return
          }
        }
      } catch { /* silent — fall through to localStorage */ }
      // 2. Fallback: localStorage (works offline)
      try {
        const saved = localStorage.getItem(`prestige_diag_${printerId}`)
        if (saved) setResults(JSON.parse(saved))
      } catch {}
    }
    loadSavedResults()
    loadBenchmark()
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [printerId])

  const loadBenchmark = async () => {
    setBenchmarkLoading(true)
    const data = await apiFetch<GlobalBenchmark>(`/api/ai/printers/${printerId}/benchmark`)
    if (data && !data.insufficientData) {
      setBenchmark(data)
    } else {
      setBenchmark(null)
    }
    setBenchmarkLoading(false)
  }

  const runTestRef = useRef<(id: string) => Promise<void>>(async () => {})
  const pendingAutoRunRef = useRef<string | null>(autoRunTestId ?? null)

  useEffect(() => {
    if (!pendingAutoRunRef.current) return
    const validId = DIAGNOSTIC_TESTS.find(t => t.id === pendingAutoRunRef.current)?.id
    if (!validId) return
    pendingAutoRunRef.current = null
    const timer = setTimeout(() => { runTestRef.current(validId) }, 500)
    return () => clearTimeout(timer)
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  const runTest = async (testId: string) => {
    if (running) return
    const start = Date.now()
    setRunning(testId)
    setCompletedTest(null)

    const needsPreheat = (testId === 'extrusion' || testId === 'retraction' || testId === 'full') && printerIsOnline
    setResults(prev => ({
      ...prev,
      [testId]: {
        testId, testType: testId, status: 'running' as const, score: 0,
        details: needsPreheat
          ? `Preheating hotend to 200C...\nThis may take 1-3 minutes. Please wait.\n\nDo not close or navigate away.`
          : printerIsOnline ? `Running live ${testId} test via Moonraker...` : `Printer offline — running AI-based estimation...`,
        metrics: needsPreheat ? [
          { label: 'Preheat Status', value: 'Heating up...', status: 'warn' as const },
          { label: 'Target Temp',   value: '200C',           status: 'ok'  as const },
        ] : [],
        ranAt: new Date().toISOString(), durationMs: 0,
      },
    }))
    setExpandedTest(testId)

    const controller = new AbortController()
    const abortTimer = setTimeout(() => controller.abort(), 300_000)

    const saveResult = (result: DiagnosticTestResult) => {
      setResults(prev => {
        const next = { ...prev, [testId]: result }
        try { localStorage.setItem(`prestige_diag_${printerId}`, JSON.stringify(next)) } catch {}
        return next
      })
      setExpandedTest(testId)
    }

    try {
      const res = await fetch(`/api/ai/printers/${printerId}/diagnostics/run`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ testType: testId }), signal: controller.signal,
      })
      clearTimeout(abortTimer)
      const durationMs = Date.now() - start

      let raw: any = null
      try { const d = await res.json(); raw = d?.data ?? d } catch { raw = null }

      if (res.ok && raw && raw.status && raw.status !== 'running') {
        const { latestAnalysis: freshAnalysis, ...testData } = raw as any
        const result: DiagnosticTestResult = { ...testData, durationMs, ranAt: new Date().toISOString() }
        saveResult(result)
        setFlashTest(testId)
        setTimeout(() => setFlashTest(null), 1200)
        setCompletedTest({ id: testId, status: result.status, score: result.score, flashKey: Date.now() })
        setTimeout(() => { completedNotifRef.current?.scrollIntoView({ behavior: 'smooth', block: 'nearest' }) }, 80)
        if (freshAnalysis) {
          setLocalAnalysis(freshAnalysis)
          try { localStorage.setItem(`prestige_analysis_${printerId}`, JSON.stringify(freshAnalysis)) } catch {}
          loadBenchmark()
        }
        if (result.source !== 'live_gcode') {
          onRefresh()
        }
      } else {
        const errMsg = raw?.error ?? raw?.details ?? `HTTP ${res.status}`
        saveResult({
          testId, testType: testId, status: 'fail', score: 0,
          details: `Backend error: ${String(errMsg).slice(0, 300)}`,
          metrics: [{ label: 'HTTP Status', value: String(res.status), status: 'bad' }],
          ranAt: new Date().toISOString(), durationMs,
        })
      }
    } catch (err: any) {
      clearTimeout(abortTimer)
      const durationMs = Date.now() - start
      const isTimeout = err?.name === 'AbortError'
      saveResult({
        testId, testType: testId, status: 'fail', score: 0,
        details: isTimeout ? `Request timed out after 30s.` : `Network error: ${err?.message ?? String(err)}`,
        metrics: [{ label: 'Error', value: isTimeout ? 'Timeout' : 'Network failure', status: 'bad' }],
        ranAt: new Date().toISOString(), durationMs,
      })
      setCompletedTest({ id: testId, status: 'fail', score: 0, flashKey: Date.now() })
      setTimeout(() => { completedNotifRef.current?.scrollIntoView({ behavior: 'smooth', block: 'nearest' }) }, 80)
    } finally {
      setRunning(null)
    }
  }

  useEffect(() => { runTestRef.current = runTest }, [runTest])

  return (
    <div className="space-y-4">
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem', alignItems: 'start' }}>

        {/* Global Benchmark card */}
        <div className="rounded-xl border border-gray-700 bg-gray-900/40 overflow-hidden">
          <div className="flex items-center gap-2 px-4 py-2.5 border-b border-gray-700 bg-gray-900/30">
            <Globe className="w-4 h-4 text-cyan-400" />
            <span className="text-sm font-semibold text-gray-200">Industry Comparison</span>
            <span className="text-[10px] text-gray-500 ml-1">— vs community fleet (avg 74/100)</span>
            <button onClick={loadBenchmark} className="ml-auto text-gray-500 hover:text-gray-300 transition-colors">
              <RefreshCw className={`w-3.5 h-3.5 ${benchmarkLoading ? 'animate-spin' : ''}`} />
            </button>
          </div>
          <div className="p-4">
            {(() => {
              const hasEnoughData = lastAnalysis && (lastAnalysis.telemetryPoints ?? 0) >= 10
              const hasBenchmark  = !!benchmark
              if (!hasEnoughData && !hasBenchmark) {
                return (
                  <div className="flex flex-col items-center gap-3 py-4 text-center">
                    <FlaskConical className="w-8 h-8 text-cyan-500/40" />
                    <p className="text-sm font-semibold text-gray-300">No diagnostic data yet</p>
                    <p className="text-xs text-gray-500 max-w-xs">
                      This is a new printer. Run the <strong className="text-cyan-400">Full System Diagnostic</strong> on
                      the right to collect real telemetry — then accurate health &amp; industry scores will appear here.
                    </p>
                    <p className="text-[10px] text-gray-600">
                      Scores shown before diagnostics are run are unreliable estimates and are hidden on purpose.
                    </p>
                  </div>
                )
              }
              return null
            })()}
            {(lastAnalysis && (lastAnalysis.telemetryPoints ?? 0) >= 10) || benchmark ? (
              <>
                <div className="flex items-center gap-4 mb-4">
                  <div className="relative w-20 h-20 flex-shrink-0">
                    <svg className="w-full h-full -rotate-90" viewBox="0 0 36 36">
                      <circle cx="18" cy="18" r="15.9" fill="none" stroke="#1f2937" strokeWidth="3" />
                      <circle cx="18" cy="18" r="15.9" fill="none"
                        stroke={benchmark ? (benchmark.betterThan >= 55 ? '#22c55e' : benchmark.betterThan >= 25 ? '#22d3ee' : '#f97316') : '#22d3ee'}
                        strokeWidth="3"
                        strokeDasharray={`${benchmark?.betterThan ?? 0} ${100 - (benchmark?.betterThan ?? 0)}`}
                        strokeLinecap="round" />
                    </svg>
                    <div className="absolute inset-0 flex flex-col items-center justify-center">
                      <span className="text-lg font-bold text-white">{benchmark?.betterThan ?? '?'}%</span>
                      <span className="text-[9px] text-gray-400">vs industry</span>
                    </div>
                  </div>
                  <div className="flex-1">
                    <p className="text-sm font-semibold text-gray-200 mb-1">
                      {benchmark
                        ? benchmark.betterThan >= 55 ? 'Above industry average'
                          : benchmark.betterThan >= 30 ? 'Near industry average'
                          : 'Below industry average'
                        : 'Run diagnostics to score vs standard...'}
                    </p>
                    <p className="text-xs text-gray-400">
                      {benchmark
                        ? `Better than ${benchmark.betterThan}% of printers (industry avg: 74/100)`
                        : 'Run a Full System Diagnostic to see how you compare'}
                    </p>
                  </div>
                </div>

                {lastAnalysis && (
                  <div className="grid grid-cols-2 gap-2">
                    {([
                      { label: 'Health',    mine: lastAnalysis.healthScore,                        standard: 74,  unit: '%', higher: true,  hint: `${lastAnalysis.healthScore >= 74 ? '>=74% = above avg' : '<74% = below avg'}` },
                      { label: 'Quality',   mine: lastAnalysis.qualityScore,                       standard: 80,  unit: '%', higher: true,  hint: '>=80% = healthy' },
                      { label: 'Fail Risk', mine: Math.round(lastAnalysis.failureRisk * 100),      standard: 20,  unit: '%', higher: false, hint: '<20% = healthy' },
                      { label: 'Clog Risk', mine: Math.round((lastAnalysis.clogRisk ?? 0) * 100), standard: 15,  unit: '%', higher: false, hint: '<15% = healthy (industry avg 20-25%)' },
                    ] as const).map(({ label, mine, standard, unit, higher, hint }) => {
                      const isBetter = higher ? mine >= standard : mine <= standard
                      return (
                        <div key={label} className="rounded-lg bg-gray-800/50 border border-gray-700/50 px-3 py-2">
                          <div className="text-[10px] text-gray-500 mb-1">{label}</div>
                          <div className="flex items-end gap-2">
                            <span className={`text-base font-bold ${isBetter ? 'text-green-400' : 'text-orange-400'}`}>{mine}{unit}</span>
                            <div className="flex items-center gap-1 mb-0.5">
                              {isBetter
                                ? <TrendingUp className="w-3 h-3 text-green-400" />
                                : <TrendingDown className="w-3 h-3 text-orange-400" />}
                              <span className="text-[10px] text-gray-400">{hint}</span>
                            </div>
                          </div>
                        </div>
                      )
                    })}
                  </div>
                )}

                {lastAnalysis && (lastAnalysis.telemetryPoints ?? 0) > 0 && (lastAnalysis.telemetryPoints ?? 0) < 10 && (
                  <div className="mt-3 flex items-start gap-2 rounded-lg bg-blue-500/5 border border-blue-500/20 px-3 py-2">
                    <Info className="w-3.5 h-3.5 text-blue-400 flex-shrink-0 mt-0.5" />
                    <p className="text-xs text-blue-300">
                      <strong>Limited telemetry</strong> ({lastAnalysis.telemetryPoints} data points). Scores are rough
                      estimates. Run <strong>Full System Diagnostic</strong> to get accurate measurements.
                    </p>
                  </div>
                )}

                {lastAnalysis && lastAnalysis.healthScore < 74 && (
                  <div className="mt-3 flex items-start gap-2 rounded-lg bg-orange-500/5 border border-orange-500/20 px-3 py-2">
                    <AlertTriangle className="w-3.5 h-3.5 text-orange-400 flex-shrink-0 mt-0.5" />
                    <div className="text-xs text-orange-300 space-y-1">
                      <p className="font-semibold">Why is the score low?</p>
                      <p>
                        Health {lastAnalysis.healthScore.toFixed(0)}% is below the industry average (74%).
                        {lastAnalysis.healthScore < 60
                          ? ' The printer has significant calibration or hardware issues.'
                          : ' Minor calibration or hardware issues detected.'}
                      </p>
                      <p className="font-semibold mt-1">To improve:</p>
                      <p>1. Run <strong>Full System Diagnostic</strong> identifies exact issues.<br />
                        2. Fix reported problems (bed mesh, PID tuning, belts).<br />
                        3. Click <strong>Analyze Now</strong> score updates automatically.</p>
                      <p className="text-orange-400/70 mt-1">AI remains active — it monitors and alerts regardless of score. Low score = more recommendations, not less AI.</p>
                    </div>
                  </div>
                )}

                {lastAnalysis?.clogRisk != null && lastAnalysis.clogRisk > 0 && lastAnalysis.clogRisk < 0.3 && lastAnalysis.healthScore >= 74 && (lastAnalysis.telemetryPoints ?? 0) >= 10 && (
                  <div className="mt-3 flex items-start gap-2 rounded-lg bg-blue-500/5 border border-blue-500/20 px-3 py-2">
                    <Info className="w-3.5 h-3.5 text-blue-400 flex-shrink-0 mt-0.5" />
                    <p className="text-xs text-blue-300">
                      Clog risk at <strong>{Math.round(lastAnalysis.clogRisk * 100)}%</strong> is considered
                      <strong> low</strong> — no action needed. Industry average is ~20-30%. Run the
                      Extrusion Flow Test below for a precise measurement.
                    </p>
                  </div>
                )}
              </>
            ) : null}
          </div>
        </div>

        {/* Test cards */}
        <div className="rounded-xl border border-gray-700 bg-gray-900/40 overflow-hidden">
          <div className="flex items-center gap-2 px-4 py-2.5 border-b border-gray-700 bg-gray-900/30">
            <FlaskConical className="w-4 h-4 text-purple-400" />
            <span className="text-sm font-semibold text-gray-200">Diagnostic Tests</span>
            <span className="text-[10px] text-gray-500 ml-auto">Compare against global fleet baseline</span>
          </div>
          <div className="px-3 pt-3">
            <PurgePositionConfig printerId={printerId} />
          </div>

          {!klipperReady ? (
            <div className="mx-3 mt-3 mb-1 flex items-start gap-2 rounded-lg px-3 py-2 text-xs border bg-red-500/10 border-red-500/30 text-red-300">
              <XCircle className="w-3.5 h-3.5 text-red-400 flex-shrink-0 mt-0.5" />
              <span>
                <strong className="text-red-400">Klipper error detected</strong> — tests cannot run while Klipper is in an error or shutdown state.
                Fix the Klipper configuration error, click <strong>RESTART</strong> in the Printers page, then re-run the tests.
              </span>
            </div>
          ) : (
            <div className={`mx-3 mt-3 mb-1 flex items-start gap-2 rounded-lg px-3 py-2 text-xs border ${
              printerIsOnline ? 'bg-green-500/5 border-green-500/20 text-green-300' : 'bg-gray-800/50 border-gray-700 text-gray-400'
            }`}>
              {printerIsOnline
                ? <><Zap className="w-3.5 h-3.5 text-green-400 flex-shrink-0 mt-0.5" /><span><strong className="text-green-400">Printer is idle</strong> — tests will send real GCode commands to hardware. Extrusion &amp; retraction tests will <strong>automatically preheat the hotend to 200C</strong> if needed (takes 1-3 min).</span></>
                : <><Activity className="w-3.5 h-3.5 flex-shrink-0 mt-0.5" /><span><strong>Printer is offline or busy</strong> — tests will read live telemetry instead of sending GCode.</span></>}
            </div>
          )}

          {/* Centered Result Modal */}
          {expandedTest && results[expandedTest] && createPortal(
            <div
              className="fixed inset-0 z-[9999] flex items-center justify-center"
              style={{ backgroundColor: 'rgba(0,0,0,0.7)' }}
              onClick={() => setExpandedTest(null)}
            >
              <div
                className="relative w-full max-w-3xl mx-4 rounded-2xl border border-gray-600 bg-gray-950 shadow-2xl overflow-hidden flex flex-col max-h-[90vh]"
                onClick={e => e.stopPropagation()}
              >
                {(() => {
                  const t = DIAGNOSTIC_TESTS.find(x => x.id === expandedTest)!
                  const result = results[expandedTest]
                  const colors = TEST_COLOR_MAP[t?.color ?? 'cyan']
                  return (
                    <>
                      <div className={`flex items-center gap-3 px-5 py-4 border-b border-gray-700 ${colors.bg}`}>
                        <div className={colors.text}>{t?.icon}</div>
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2 flex-wrap">
                            <span className="text-sm font-bold text-gray-100">{t?.label}</span>
                            <StatusPill status={result.status} score={result.score} source={result.source} />
                          </div>
                          <p className="text-xs text-gray-400 mt-0.5">{t?.desc}</p>
                        </div>
                        <button onClick={() => setExpandedTest(null)} className="flex-shrink-0 text-gray-500 hover:text-gray-200 transition-colors p-1 rounded-lg hover:bg-gray-700/50">
                          <XCircle className="w-5 h-5" />
                        </button>
                      </div>
                      <div className="px-5 py-4 space-y-4 overflow-y-auto flex-1">
                        {completedTest && completedTest.id === expandedTest && result.status !== 'running' && (() => {
                          const testDef = DIAGNOSTIC_TESTS.find(t => t.id === completedTest.id)
                          const isPass = completedTest.status === 'pass'
                          const isWarn = completedTest.status === 'warning'
                          return (
                            <div
                              key={completedTest.flashKey}
                              ref={completedNotifRef}
                              className={`flex items-center gap-3 px-3 py-2.5 rounded-lg border text-sm
                                ${isPass ? 'border-green-500/40 text-green-300'
                                  : isWarn ? 'border-yellow-500/40 text-yellow-300'
                                  : 'border-red-500/40 text-red-300'}`}
                            >
                              {isPass ? <CheckCircle className="w-4 h-4 flex-shrink-0" />
                                : isWarn ? <AlertTriangle className="w-4 h-4 flex-shrink-0" />
                                : <XCircle className="w-4 h-4 flex-shrink-0" />}
                              <span className="flex-1 min-w-0">
                                <span className="font-semibold">{testDef?.label ?? completedTest.id}</span>
                                {' — '}
                                {isPass ? `Passed ${completedTest.score}/100` : isWarn ? `Warning ${completedTest.score}/100` : 'Test failed — see details below'}
                              </span>
                              <button onClick={() => setCompletedTest(null)} className="flex-shrink-0 opacity-50 hover:opacity-100 transition-opacity">
                                <XCircle className="w-3.5 h-3.5" />
                              </button>
                            </div>
                          )
                        })()}

                        {result.status === 'running' && (
                          <div className="flex flex-col items-center justify-center py-12 gap-4">
                            <RefreshCw className="w-10 h-10 text-cyan-400 animate-spin" />
                            <p className="text-sm font-semibold text-cyan-400 animate-pulse">Test is running...</p>
                            <p className="text-xs text-gray-400 text-center max-w-xs">{result.details.split('\n')[0]}</p>
                          </div>
                        )}

                        <div className={`flex items-center gap-4 ${result.status === 'running' ? 'hidden' : ''}`}>
                          <div className="flex-1">
                            <div className="flex items-center justify-between mb-1.5">
                              <span className="text-xs text-gray-400">Your Score</span>
                              <span className={`text-sm font-bold ${result.score >= 80 ? 'text-green-400' : result.score >= 60 ? 'text-yellow-400' : 'text-red-400'}`}>{result.score}/100</span>
                            </div>
                            <div className="w-full h-2.5 rounded-full bg-gray-800 overflow-hidden">
                              <div className={`h-full rounded-full ${result.score >= 80 ? 'bg-green-400' : result.score >= 60 ? 'bg-yellow-400' : 'bg-red-400'}`} style={{ width: `${result.score}%` }} />
                            </div>
                          </div>
                          {result.globalAvg != null && (
                            <div className="flex-1">
                              <div className="flex items-center justify-between mb-1.5">
                                <span className="text-xs text-gray-400">Healthy Standard</span>
                                <span className="text-sm font-bold text-gray-300">{result.globalAvg}/100</span>
                              </div>
                              <div className="w-full h-2.5 rounded-full bg-gray-800 overflow-hidden">
                                <div className="h-full rounded-full bg-gray-500" style={{ width: `${result.globalAvg}%` }} />
                              </div>
                            </div>
                          )}
                        </div>

                        <div className={`rounded-xl bg-gray-900 border border-gray-700 px-4 py-3 space-y-2 ${result.status === 'running' ? 'hidden' : ''}`}>
                          {result.source && (
                            <div className="flex items-center gap-1.5 pb-2 border-b border-gray-800">
                              {result.source === 'live_gcode'
                                ? <><span className="w-2 h-2 rounded-full bg-green-400 animate-pulse" /><span className="text-[10px] font-bold text-green-400">LIVE GCODE — real GCode sent to hardware</span></>
                                : result.source === 'live_telemetry' || result.source === 'live'
                                ? <><span className="w-2 h-2 rounded-full bg-cyan-400 animate-pulse" /><span className="text-[10px] font-semibold text-cyan-400">LIVE TELEMETRY — reading live sensor stream</span></>
                                : <><span className="w-2 h-2 rounded-full bg-gray-500" /><span className="text-[10px] font-semibold text-gray-500">ESTIMATED — AI pattern analysis</span></>}
                            </div>
                          )}
                          {result.details.split('\n').map((line: string, i: number) => (
                            <p key={i} className="text-xs text-gray-300 leading-relaxed">{line}</p>
                          ))}
                        </div>

                        {result.status !== 'running' && result.metrics.length > 0 && (
                          <div className="rounded-xl border border-gray-700 overflow-hidden">
                            {result.metrics.map((m: any, i: number) => (
                              <div key={i} className="flex items-center justify-between px-4 py-2.5 border-b border-gray-800 last:border-0 odd:bg-gray-900/60">
                                <span className="text-xs text-gray-400">{m.label}</span>
                                <span className={`text-xs font-mono font-semibold ${m.status === 'ok' ? 'text-green-400' : m.status === 'warn' ? 'text-yellow-400' : 'text-red-400'}`}>{m.value}</span>
                              </div>
                            ))}
                          </div>
                        )}

                        <div className="flex items-center pt-1 border-t border-gray-800">
                          <div className="text-[10px] text-gray-500 flex items-center gap-1">
                            <Clock className="w-3 h-3" />
                            Ran {new Date(result.ranAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })} · {result.durationMs}ms
                          </div>
                        </div>
                      </div>
                      <div className="flex items-center justify-end px-5 py-3 border-t border-gray-700 bg-gray-900/80 flex-shrink-0">
                        <button
                          onClick={() => { runTest(expandedTest!) }}
                          disabled={!!running || !klipperReady}
                          className="flex items-center gap-1.5 px-4 py-2 rounded-lg text-xs font-semibold transition-all border bg-cyan-500/20 text-cyan-400 border-cyan-500/40 hover:bg-cyan-500/30 active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed"
                        >
                          {running === expandedTest
                            ? <><RefreshCw className="w-3.5 h-3.5 animate-spin" /> Running...</>
                            : !klipperReady
                            ? <><XCircle className="w-3.5 h-3.5" /> Klipper Error</>
                            : <><Play className="w-3.5 h-3.5" /> Re-run Test</>}
                        </button>
                      </div>
                    </>
                  )
                })()}
              </div>
            </div>,
            document.body
          )}

          <div className="p-3 space-y-2">
            {DIAGNOSTIC_TESTS.map(test => {
              const result = results[test.id]
              const isRunning = running === test.id
              const colors = TEST_COLOR_MAP[test.color]

              return (
                <div key={test.id} className={`rounded-xl border transition-all duration-300 ${
                  isRunning ? 'border-cyan-500/50 bg-cyan-500/5'
                  : flashTest === test.id ? 'border-green-400/60 bg-green-500/8 shadow-[0_0_16px_rgba(34,197,94,0.15)]'
                  : [colors.border, colors.bg].join(' ')
                }`}>
                  <div className="flex items-center gap-3 px-4 py-3">
                    <div className={`flex-shrink-0 ${colors.text}`}>{test.icon}</div>
                    <div className="flex-1 min-w-0">
                      <span className="text-sm font-semibold text-gray-200">{test.label}</span>
                      {result && result.status !== 'running' && !isRunning && (
                        <div className={`text-[10px] font-semibold mt-0.5 ${
                          result.status === 'pass' ? 'text-green-400'
                          : result.status === 'warning' ? 'text-yellow-400'
                          : 'text-red-400'
                        }`}>
                          {result.status === 'pass' ? `✓ ${result.score}/100`
                          : result.status === 'warning' ? `⚠ ${result.score}/100`
                          : '✗ Failed'}
                        </div>
                      )}
                    </div>
                    {/* VIEW button — cyan, shown ONLY while this test is running */}
                    {isRunning && (
                      <button
                        onClick={(e) => { e.stopPropagation(); setExpandedTest(test.id) }}
                        className="flex items-center gap-1 px-3 py-1.5 rounded-lg text-xs font-semibold transition-all border border-cyan-400/70 bg-cyan-500/20 text-cyan-300 hover:bg-cyan-500/35 flex-shrink-0 active:scale-95"
                      >
                        <Eye className="w-3.5 h-3.5" />
                        <span>View</span>
                      </button>
                    )}
                    {/* RESULTS button — shown when test is done and not running */}
                    {result && !isRunning && (
                      <button
                        onClick={(e) => { e.stopPropagation(); setExpandedTest(test.id) }}
                        className="flex items-center gap-1 px-2.5 py-1.5 rounded-lg text-xs font-medium transition-all border border-gray-600/50 bg-gray-800/60 text-gray-400 hover:text-gray-200 hover:border-gray-500 flex-shrink-0 active:scale-95"
                      >
                        <Eye className="w-3.5 h-3.5" />
                        <span>Results</span>
                      </button>
                    )}
                    <button
                      onClick={(e) => { e.stopPropagation(); if (!isRunning) runTest(test.id) }}
                      disabled={(!!running && !isRunning) || !klipperReady}
                      className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold transition-all border flex-shrink-0
                        ${isRunning ? 'opacity-30 cursor-default border-gray-700 bg-transparent text-gray-500'
                          : !klipperReady ? 'bg-red-500/10 text-red-400 border-red-500/30 cursor-not-allowed'
                          : [colors.bg, colors.text, colors.border, 'hover:brightness-125'].join(' ')
                        } disabled:cursor-not-allowed active:scale-95`}
                    >
                      {isRunning
                        ? <><RefreshCw className="w-3.5 h-3.5 animate-spin" /> Running...</>
                        : !klipperReady
                        ? <><XCircle className="w-3.5 h-3.5" /> Error</>
                        : <><Play className="w-3.5 h-3.5" /> {result ? 'Re-run' : 'Run'}</>}
                    </button>
                  </div>
                </div>
              )
            })}
          </div>
        </div>
      </div>
    </div>
  )
}

export default AIDiagnosticsTab
