import { useParams, useNavigate } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import * as Tabs from '@radix-ui/react-tabs'
import { Settings, Brain, Database, Monitor } from 'lucide-react'
import { GeneralSettings, AISettings, BackupSettings, SystemSettings } from '@features/settings'

type SettingsSection = 'general' | 'ai' | 'backup' | 'system'

export default function SettingsPage() {
  const { section = 'general' } = useParams<{ section: SettingsSection }>()
  const navigate = useNavigate()
  const { t } = useTranslation()

  const handleTabChange = (value: string) => {
    navigate(`/settings/${value}`)
  }

  const tabs = [
    { id: 'general', label: t('settings.tabs.general', 'General'), icon: Settings },
    { id: 'ai', label: t('settings.tabs.ai', 'AI Settings'), icon: Brain },
    { id: 'backup', label: t('settings.tabs.backup', 'Backup'), icon: Database },
    { id: 'system', label: t('settings.tabs.system', 'System'), icon: Monitor },
  ]

  return (
    <div className="space-y-6">
      {/* Page Header */}
      <div className="mb-2">
        <h1 className="text-2xl font-bold text-text">{t('settings.title', 'Settings')}</h1>
        <p className="mt-1 text-sm text-text-muted">{t('settings.subtitle', 'Manage your dashboard preferences and system configuration')}</p>
      </div>

      {/* Tabs */}
      <Tabs.Root value={section} onValueChange={handleTabChange}>
        <Tabs.List className="flex gap-1 p-1 bg-surface rounded-lg border border-border mb-6">
          {tabs.map((tab) => (
            <Tabs.Trigger
              key={tab.id}
              value={tab.id}
              className={`
                flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium
                transition-all duration-200
                data-[state=active]:bg-primary/10 data-[state=active]:text-primary
                data-[state=inactive]:text-text-muted data-[state=inactive]:hover:text-text
              `}
            >
              <tab.icon className="w-4 h-4" />
              {tab.label}
            </Tabs.Trigger>
          ))}
        </Tabs.List>

        <Tabs.Content value="general" className="space-y-6">
          <GeneralSettings />
        </Tabs.Content>

        <Tabs.Content value="ai" className="space-y-6">
          <AISettings />
        </Tabs.Content>

        <Tabs.Content value="backup" className="space-y-6">
          <BackupSettings />
        </Tabs.Content>

        <Tabs.Content value="system" className="space-y-6">
          <SystemSettings />
        </Tabs.Content>
      </Tabs.Root>
    </div>
  )
}


