// PRESTIGE DASHBOARD - BED MESH HEATMAP
// SPEC: mapju struktura.txt — features/bed-mesh/
// 2D heatmap visualization of bed mesh data
// ═══════════════════════════════════════════════════════════════

import { useMemo } from 'react'

interface BedMeshHeatmapProps {
  /** 2D array of Z-offset values (rows × cols) */
  meshData: number[][]
  /** Min position [x, y] */
  meshMin?: [number, number]
  /** Max position [x, y] */
  meshMax?: [number, number]
  /** Show numeric values on cells */
  showValues?: boolean
  /** Size of the heatmap */
  size?: number
}

// Color interpolation: blue (low) → green (level) → red (high)
function zToColor(value: number, min: number, max: number): string {
  const range = Math.max(max - min, 0.001)
  // Normalize to 0..1 where 0.5 = zero point
  const zeroNorm = Math.max(0, Math.min(1, (0 - min) / range))
  const norm = Math.max(0, Math.min(1, (value - min) / range))

  // Below zero: blue → green
  if (norm <= zeroNorm) {
    const t = zeroNorm > 0 ? norm / zeroNorm : 0
    const r = Math.round(0 + t * 0)
    const g = Math.round(80 + t * 175)
    const b = Math.round(220 - t * 170)
    return `rgb(${r}, ${g}, ${b})`
  }
  // Above zero: green → yellow → red
  const t = zeroNorm < 1 ? (norm - zeroNorm) / (1 - zeroNorm) : 1
  if (t < 0.5) {
    const t2 = t * 2
    const r = Math.round(0 + t2 * 255)
    const g = Math.round(255)
    const b = Math.round(50 - t2 * 50)
    return `rgb(${r}, ${g}, ${b})`
  }
  const t2 = (t - 0.5) * 2
  const r = 255
  const g = Math.round(255 - t2 * 200)
  const b = Math.round(0)
  return `rgb(${r}, ${g}, ${b})`
}

export function BedMeshHeatmap({
  meshData,
  meshMin = [0, 0],
  meshMax = [220, 220],
  showValues = true,
  size = 320,
}: BedMeshHeatmapProps) {
  const { rows, cols, min, max, range } = useMemo(() => {
    const r = meshData.length
    const c = r > 0 ? meshData[0].length : 0
    let mn = Infinity, mx = -Infinity
    meshData.forEach(row => row.forEach(v => { mn = Math.min(mn, v); mx = Math.max(mx, v) }))
    if (!isFinite(mn)) { mn = 0; mx = 0 }
    return { rows: r, cols: c, min: mn, max: mx, range: mx - mn }
  }, [meshData])

  if (rows === 0 || cols === 0) {
    return (
      <div className="flex items-center justify-center text-text-muted text-sm" style={{ width: size, height: size }}>
        No mesh data
      </div>
    )
  }

  const cellW = size / cols
  const cellH = size / rows
  const fontSize = Math.max(8, Math.min(12, cellW / 4))

  return (
    <div className="space-y-3">
      {/* Heatmap grid */}
      <div className="relative rounded-lg overflow-hidden border border-border" style={{ width: size, height: size }}>
        <svg viewBox={`0 0 ${size} ${size}`} width={size} height={size}>
          {meshData.map((row, ri) =>
            row.map((val, ci) => {
              const x = ci * cellW
              // Flip Y so row 0 = bottom (front of bed)
              const y = (rows - 1 - ri) * cellH
              const color = zToColor(val, min, max)
              return (
                <g key={`${ri}-${ci}`}>
                  <rect x={x} y={y} width={cellW} height={cellH} fill={color} stroke="rgba(0,0,0,0.2)" strokeWidth={0.5} />
                  {showValues && (
                    <text
                      x={x + cellW / 2}
                      y={y + cellH / 2}
                      textAnchor="middle"
                      dominantBaseline="central"
                      fill={Math.abs(val) > range * 0.6 ? '#fff' : '#000'}
                      fontSize={fontSize}
                      fontFamily="monospace"
                      fontWeight="bold"
                    >
                      {val.toFixed(3)}
                    </text>
                  )}
                </g>
              )
            })
          )}
        </svg>
        {/* Axis labels */}
        <div className="absolute bottom-0.5 left-1 text-[9px] font-mono text-text-muted opacity-60">Front</div>
        <div className="absolute top-0.5 left-1 text-[9px] font-mono text-text-muted opacity-60">Back</div>
        <div className="absolute bottom-0.5 right-1 text-[9px] font-mono text-text-muted opacity-60">
          {meshMax[0]}mm
        </div>
      </div>

      {/* Legend */}
      <div className="flex items-center gap-2 text-xs text-text-muted">
        <span>Low ({min.toFixed(3)}mm)</span>
        <div className="flex-1 h-3 rounded-sm overflow-hidden flex">
          {Array.from({ length: 20 }, (_, i) => {
            const t = i / 19
            const val = min + t * range
            return <div key={i} className="flex-1" style={{ backgroundColor: zToColor(val, min, max) }} />
          })}
        </div>
        <span>High ({max.toFixed(3)}mm)</span>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-3 gap-2 text-xs">
        <div className="text-center p-2 rounded bg-surface">
          <div className="text-text-muted">Min</div>
          <div className="font-mono font-bold text-blue-400">{min.toFixed(3)}mm</div>
        </div>
        <div className="text-center p-2 rounded bg-surface">
          <div className="text-text-muted">Range</div>
          <div className="font-mono font-bold text-text">{range.toFixed(3)}mm</div>
        </div>
        <div className="text-center p-2 rounded bg-surface">
          <div className="text-text-muted">Max</div>
          <div className="font-mono font-bold text-red-400">{max.toFixed(3)}mm</div>
        </div>
      </div>
    </div>
  )
}

export default BedMeshHeatmap
