// ═══════════════════════════════════════════════════════════════
// PRESTIGE DASHBOARD - ENHANCED PROGRESS BAR COMPONENT
// FE-08: Print progress with ETA and layer info
// ═══════════════════════════════════════════════════════════════

import React, { useMemo } from 'react'
import type {
  ProgressBarProps,
  ProgressBarSize,
  ProgressBarVariant,
  ProgressBarStatus,
  ProgressData,
  StatusColorConfig,
} from './ProgressBar.types'

/**
 * Size configuration
 */
const SIZE_CONFIG: Record<ProgressBarSize, { height: string; text: string; gap: string }> = {
  xs: {
    height: 'h-1',
    text: 'text-xs',
    gap: 'gap-0.5',
  },
  sm: {
    height: 'h-1.5',
    text: 'text-xs',
    gap: 'gap-1',
  },
  md: {
    height: 'h-2',
    text: 'text-sm',
    gap: 'gap-1.5',
  },
  lg: {
    height: 'h-3',
    text: 'text-sm',
    gap: 'gap-2',
  },
  xl: {
    height: 'h-4',
    text: 'text-base',
    gap: 'gap-2',
  },
}

/**
 * Status color configuration
 */
const STATUS_COLORS: Record<ProgressBarStatus, StatusColorConfig> = {
  idle: {
    bg: 'rgba(107, 114, 128, 0.1)',
    fill: '#6b7280',
    glow: 'rgba(107, 114, 128, 0.3)',
    text: '#9ca3af',
  },
  printing: {
    bg: 'rgba(0, 217, 255, 0.1)',
    fill: '#00d9ff',
    glow: 'rgba(0, 217, 255, 0.5)',
    text: '#00d9ff',
  },
  paused: {
    bg: 'rgba(251, 191, 36, 0.1)',
    fill: '#fbbf24',
    glow: 'rgba(251, 191, 36, 0.5)',
    text: '#fbbf24',
  },
  complete: {
    bg: 'rgba(34, 197, 94, 0.1)',
    fill: '#22c55e',
    glow: 'rgba(34, 197, 94, 0.5)',
    text: '#22c55e',
  },
  error: {
    bg: 'rgba(239, 68, 68, 0.1)',
    fill: '#ef4444',
    glow: 'rgba(239, 68, 68, 0.5)',
    text: '#ef4444',
  },
}

/**
 * Format time (seconds to readable string)
 */
const formatTime = (seconds: number): string => {
  if (seconds < 60) {
    return `${Math.round(seconds)}s`
  }
  
  const hours = Math.floor(seconds / 3600)
  const minutes = Math.floor((seconds % 3600) / 60)

  if (hours > 0) {
    return `${hours}h ${minutes}m`
  }
  return `${minutes}m`
}

/**
 * Format ETA
 */
const formatETA = (eta: string | Date | undefined): string => {
  if (!eta) return 'N/A'
  
  const date = typeof eta === 'string' ? new Date(eta) : eta
  
  // If today, show time only
  const now = new Date()
  const isToday = date.toDateString() === now.toDateString()
  
  if (isToday) {
    return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
  }
  
  // Otherwise show date and time
  return date.toLocaleString([], {
    month: 'short',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  })
}

/**
 * Normalize progress input
 */
const normalizeProgress = (progress: number | ProgressData): ProgressData => {
  if (typeof progress === 'number') {
    return { percentage: progress }
  }
  return progress
}

/**
 * Enhanced ProgressBar Component
 * 
 * Features:
 * - Multiple size variants (xs to xl)
 * - Multiple style variants (default, gradient, striped, glow)
 * - Status-based color coding
 * - Percentage display inside or outside bar
 * - Time info (elapsed, remaining, ETA)
 * - Layer/value counting
 * - Smooth animations
 * - Pulse effect for active states
 * - Gradient and glow effects
 */
export const ProgressBar: React.FC<ProgressBarProps> = ({
  progress,
  size = 'md',
  variant = 'gradient',
  status = 'printing',
  showPercentage = true,
  showLabel = false,
  showTime = false,
  showValues = false,
  color,
  glowColor,
  animated = true,
  animationDuration = 500,
  pulse = false,
  className = '',
  onClick,
}) => {
  const sizeConfig = SIZE_CONFIG[size]
  const statusColors = STATUS_COLORS[status]
  
  // Normalize progress data
  const data = useMemo(() => normalizeProgress(progress), [progress])
  
  // Clamp percentage to 0-100
  const percentage = Math.max(0, Math.min(100, data.percentage))

  // Determine colors (custom or status-based)
  const fillColor = color || statusColors.fill
  const fillGlow = glowColor || statusColors.glow
  const bgColor = statusColors.bg
  const textColor = statusColors.text

  // Build gradient for variant
  const getFillStyle = (): React.CSSProperties => {
    const baseStyle: React.CSSProperties = {
      width: `${percentage}%`,
      transition: animated ? `width ${animationDuration}ms ease-in-out` : undefined,
    }

    if (variant === 'gradient') {
      return {
        ...baseStyle,
        background: `linear-gradient(90deg, ${fillColor} 0%, ${fillColor}dd 50%, ${fillColor} 100%)`,
        boxShadow: `0 0 12px ${fillGlow}`,
      }
    }

    if (variant === 'glow') {
      return {
        ...baseStyle,
        backgroundColor: fillColor,
        boxShadow: `0 0 16px ${fillGlow}, inset 0 0 8px ${fillGlow}`,
      }
    }

    if (variant === 'striped') {
      return {
        ...baseStyle,
        backgroundImage: `linear-gradient(
          45deg,
          ${fillColor} 25%,
          transparent 25%,
          transparent 50%,
          ${fillColor} 50%,
          ${fillColor} 75%,
          transparent 75%,
          transparent
        )`,
        backgroundSize: '1rem 1rem',
        animation: pulse ? 'stripe-move 1s linear infinite' : undefined,
      }
    }

    // Default
    return {
      ...baseStyle,
      backgroundColor: fillColor,
      boxShadow: `0 0 8px ${fillGlow}`,
    }
  }

  return (
    <div
      className={`flex flex-col ${sizeConfig.gap} ${className}`}
      onClick={onClick}
      style={{ cursor: onClick ? 'pointer' : 'default' }}
    >
      {/* Top info row (label, filename, current/total) */}
      {(showLabel || data.filename || showValues) && (
        <div className="flex items-center justify-between">
          {/* Left: Label or filename */}
          <div className="flex-1 min-w-0">
            {data.filename && (
              <span className={`${sizeConfig.text} text-gray-300 truncate block font-medium`}>
                {data.filename}
              </span>
            )}
            {!data.filename && data.label && (
              <span className={`${sizeConfig.text} text-gray-400 truncate block`}>
                {data.label}
              </span>
            )}
          </div>

          {/* Right: Current/Total or Percentage */}
          {showValues && data.current !== undefined && data.total !== undefined && (
            <span className={`${sizeConfig.text} font-mono font-medium`} style={{ color: textColor }}>
              {data.current} / {data.total}
            </span>
          )}
          {!showValues && showPercentage && (
            <span className={`${sizeConfig.text} font-mono font-bold`} style={{ color: textColor }}>
              {percentage.toFixed(1)}%
            </span>
          )}
        </div>
      )}

      {/* Progress bar container */}
      <div
        className={`relative ${sizeConfig.height} rounded-full overflow-hidden`}
        style={{
          backgroundColor: bgColor,
          border: `1px solid ${statusColors.fill}33`,
        }}
      >
        {/* Fill bar */}
        <div
          className={`absolute inset-y-0 left-0 rounded-full ${pulse ? 'animate-pulse' : ''}`}
          style={getFillStyle()}
        >
          {/* Percentage text inside bar (for larger sizes) */}
          {showPercentage && !showValues && size !== 'xs' && size !== 'sm' && percentage > 15 && (
            <div className="absolute inset-0 flex items-center justify-center">
              <span 
                className="text-xs font-bold font-mono"
                style={{
                  color: 'white',
                  textShadow: '0 1px 2px rgba(0, 0, 0, 0.8)',
                }}
              >
                {percentage.toFixed(0)}%
              </span>
            </div>
          )}
        </div>
      </div>

      {/* Bottom info row (time info) */}
      {showTime && (data.timeElapsed !== undefined || data.timeRemaining !== undefined || data.eta) && (
        <div className="flex items-center justify-between text-xs text-gray-500">
          {/* Left: Elapsed */}
          {data.timeElapsed !== undefined && (
            <span>
              Elapsed: {formatTime(data.timeElapsed)}
            </span>
          )}

          {/* Center: Speed (if available) */}
          {data.speed !== undefined && (
            <span className="text-gray-600">
              {data.speed.toFixed(1)} mm/s
            </span>
          )}

          {/* Right: Remaining or ETA */}
          {data.timeRemaining !== undefined && (
            <span style={{ color: textColor }}>
              {formatTime(data.timeRemaining)} left
            </span>
          )}
          {!data.timeRemaining && data.eta && (
            <span style={{ color: textColor }}>
              ETA: {formatETA(data.eta)}
            </span>
          )}
        </div>
      )}
    </div>
  )
}

ProgressBar.displayName = 'ProgressBar'

export default ProgressBar
