// ═══════════════════════════════════════════════════════════════
// PRESTIGE DASHBOARD - Auth Store (Zustand + persist)
// Mirrors backend auth/types.ts logic on the client side
// ═══════════════════════════════════════════════════════════════

import { create } from 'zustand'
import { persist } from 'zustand/middleware'
import {
  supabaseAuth,
  supabaseDB,
  generateHWID,
} from '@/services/supabase'
import type {
  SupabaseSession,
  SupabaseUser,
  Profile,
  Subscription,
} from '@/services/supabase'

// ─── State interface ──────────────────────────────────────────

interface AuthState {
  session:      SupabaseSession | null
  user:         SupabaseUser | null
  profile:      Profile | null
  subscription: Subscription | null
  hwid:         string | null

  isLoading:     boolean
  error:         string | null
  isInitialized: boolean

  // Actions
  signUp:           (email: string, password: string, fullName?: string) => Promise<{ error: string | null }>
  signIn:           (email: string, password: string)                    => Promise<{ error: string | null }>
  signOut:          ()                                                    => Promise<void>
  loadProfile:      ()                                                    => Promise<void>
  loadSubscription: ()                                                    => Promise<void>
  clearError:       ()                                                    => void
  initialize:       ()                                                    => Promise<void>
}

// ─── Helpers ──────────────────────────────────────────────────

function isSessionExpired(session: SupabaseSession): boolean {
  const now        = Math.floor(Date.now() / 1000)
  const expiresAt  = session.expires_at ?? 0
  return now >= expiresAt - 60 // 60 s buffer
}

// ─── Store ────────────────────────────────────────────────────

export const useAuthStore = create<AuthState>()(
  persist(
    (set, get) => ({
      session:       null,
      user:          null,
      profile:       null,
      subscription:  null,
      hwid:          null,
      isLoading:     false,
      error:         null,
      isInitialized: false,

      clearError: () => set({ error: null }),

      // ── Sign Up ─────────────────────────────────────────────
      signUp: async (email, password, fullName) => {
        set({ isLoading: true, error: null })

        const { data, error } = await supabaseAuth.signUp(email, password, fullName)

        if (error) {
          set({ isLoading: false, error: error.message })
          return { error: error.message }
        }

        // Supabase may require email confirmation — no session yet
        if (!data.session || !data.user) {
          set({ isLoading: false })
          return { error: null } // caller checks for email-confirm flow
        }

        const token = data.session.access_token
        const hwid  = generateHWID()

        // Create profile row (upsert — safe if triggers already created it)
        await supabaseDB.upsertProfile(
          {
            id:         data.user.id,
            email,
            full_name:  fullName ?? null,
            created_at: new Date().toISOString(),
            updated_at: new Date().toISOString(),
          },
          token,
        )

        // Bind HWID (matches backend license.service.ts _validateOrBindHWID)
        await supabaseDB.bindHWID(data.user.id, hwid, token)

        const { data: sub } = await supabaseDB.getSubscription(data.user.id, token)

        set({
          session:      data.session,
          user:         data.user,
          subscription: sub,
          hwid,
          isLoading:    false,
        })

        return { error: null }
      },

      // ── Sign In ─────────────────────────────────────────────
      signIn: async (email, password) => {
        set({ isLoading: true, error: null })

        const { data, error } = await supabaseAuth.signIn(email, password)

        if (error) {
          set({ isLoading: false, error: error.message })
          return { error: error.message }
        }

        if (!data.session || !data.user) {
          set({ isLoading: false, error: 'No session returned. Please try again.' })
          return { error: 'No session returned. Please try again.' }
        }

        const token = data.session.access_token
        const hwid  = generateHWID()

        // Update HWID last_seen (or insert if new device)
        await supabaseDB.bindHWID(data.user.id, hwid, token)

        const [{ data: profile }, { data: sub }] = await Promise.all([
          supabaseDB.getProfile(data.user.id, token),
          supabaseDB.getSubscription(data.user.id, token),
        ])

        set({
          session:      data.session,
          user:         data.user,
          profile:      profile ?? null,
          subscription: sub ?? null,
          hwid,
          isLoading:    false,
        })

        return { error: null }
      },

      // ── Sign Out ────────────────────────────────────────────
      signOut: async () => {
        const { session } = get()
        if (session) await supabaseAuth.signOut(session.access_token)
        set({
          session:      null,
          user:         null,
          profile:      null,
          subscription: null,
          hwid:         null,
        })
      },

      // ── Load Profile ────────────────────────────────────────
      loadProfile: async () => {
        const { session, user } = get()
        if (!session || !user) return
        const { data } = await supabaseDB.getProfile(user.id, session.access_token)
        if (data) set({ profile: data })
      },

      // ── Load Subscription ───────────────────────────────────
      loadSubscription: async () => {
        const { session, user } = get()
        if (!session || !user) return
        const { data } = await supabaseDB.getSubscription(user.id, session.access_token)
        set({ subscription: data ?? null })
      },

      // ── Initialize (app boot) ───────────────────────────────
      initialize: async () => {
        const { session } = get()

        if (!session) {
          set({ isInitialized: true })
          return
        }

        // Refresh if expired
        if (isSessionExpired(session)) {
          const { data, error } = await supabaseAuth.refreshSession(
            session.refresh_token,
          )
          if (error || !data.session) {
            set({
              session:       null,
              user:          null,
              profile:       null,
              subscription:  null,
              isInitialized: true,
            })
            return
          }
          set({ session: data.session, user: data.user })
        }

        // Re-fetch fresh data
        const cur = get()
        if (cur.session && cur.user) {
          const token = cur.session.access_token
          const hwid  = generateHWID()

          const [{ data: profile }, { data: sub }] = await Promise.all([
            supabaseDB.getProfile(cur.user.id, token),
            supabaseDB.getSubscription(cur.user.id, token),
          ])

          // Update HWID last_seen silently
          void supabaseDB.bindHWID(cur.user.id, hwid, token)

          set({
            profile:      profile ?? cur.profile,
            subscription: sub ?? null,
            hwid,
          })
        }

        set({ isInitialized: true })
      },
    }),

    // Only persist auth tokens + user identity — never subscription (re-fetch on boot)
    {
      name: 'prestige-auth-v1',
      partialize: (s) => ({
        session: s.session,
        user:    s.user,
        profile: s.profile,
        hwid:    s.hwid,
      }),
    },
  ),
)

export default useAuthStore
