// ═══════════════════════════════════════════════════════════════
// PRESTIGE DASHBOARD - G-CODE PAGE
// Route: /gcode — G-Code console + 3D Viewer with tabs
// ═══════════════════════════════════════════════════════════════

import { useState, useMemo } from 'react'
import { Terminal, Printer as PrinterIcon, Box } from 'lucide-react'
import type { Printer } from '@core/types'
import { usePrinterStore, selectPrintersArray } from '@core/state/printerStore'
import { GCodeConsole } from '@features/gcode-console'
import { GCodeViewer } from '@features/gcode-viewer'

type GCodeTab = 'console' | 'viewer'

export default function GCodePage() {
  const printers = usePrinterStore(selectPrintersArray)
  const [selectedPrinterId, setSelectedPrinterId] = useState<string | null>(
    printers.length > 0 ? printers[0]?.id ?? null : null
  )
  const [activeTab, setActiveTab] = useState<GCodeTab>('console')

  const selectedPrinter = useMemo(
    () => printers.find((p: any) => p.id === selectedPrinterId),
    [printers, selectedPrinterId]
  )

  return (
    <div className="p-6 flex flex-col gap-4 h-full">
      {/* Header */}
      <div className="flex items-center justify-between flex-shrink-0">
        <div>
          <h1 className="text-2xl font-display font-bold text-text flex items-center gap-3">
            <Terminal className="w-7 h-7 text-green-400" />
            G-Code
          </h1>
          <p className="text-sm text-text-muted mt-1">
            Console commands and 3D toolpath viewer
          </p>
        </div>
      </div>

      {/* Printer selector */}
      {printers.length > 1 && (
        <div className="flex items-center gap-3 flex-shrink-0">
          <PrinterIcon className="w-4 h-4 text-text-muted" />
          <span className="text-sm text-text-muted">Printer:</span>
          <div className="flex gap-1 flex-wrap">
            {printers.map((p: Printer) => (
              <button
                key={p.id}
                onClick={() => setSelectedPrinterId(p.id)}
                className={`px-3 py-1.5 rounded-md text-sm font-medium transition-all ${
                  selectedPrinterId === p.id
                    ? 'bg-primary text-primary-foreground'
                    : 'bg-surface text-text-muted hover:text-text border border-border'
                }`}
              >
                {p.name || p.id}
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Tabs */}
      <div className="flex gap-1 p-1 bg-surface rounded-lg border border-border flex-shrink-0">
        <button
          onClick={() => setActiveTab('console')}
          className={`flex items-center gap-1.5 flex-1 px-3 py-2.5 rounded-md text-sm font-medium transition-all ${
            activeTab === 'console' ? 'bg-primary/10 text-primary' : 'text-text-muted hover:text-text'
          }`}
        >
          <Terminal className="w-3.5 h-3.5" /> Console
        </button>
        <button
          onClick={() => setActiveTab('viewer')}
          className={`flex items-center gap-1.5 flex-1 px-3 py-2.5 rounded-md text-sm font-medium transition-all ${
            activeTab === 'viewer' ? 'bg-primary/10 text-primary' : 'text-text-muted hover:text-text'
          }`}
        >
          <Box className="w-3.5 h-3.5" /> 3D Viewer
        </button>
      </div>

      {/* Tab content */}
      <div className="flex-1 min-h-0">
        {activeTab === 'console' && (
          printers.length === 0 ? (
            <div className="text-center py-16 text-text-muted">
              <Terminal className="w-12 h-12 mx-auto mb-3 opacity-30" />
              <p className="text-lg">No printers connected</p>
              <p className="text-sm mt-1">Connect a printer to use the G-Code console</p>
            </div>
          ) : (
            <GCodeConsole printerId={selectedPrinterId || undefined} />
          )
        )}

        {activeTab === 'viewer' && (
          <GCodeViewer className="h-full" printerId={selectedPrinterId || undefined} />
        )}
      </div>
    </div>
  )
}
