// ═══════════════════════════════════════════════════════════════
// PRESTIGE — AI PREDICTIONS TAB
// Failure risk analysis using AIPredictionCard components
// ═══════════════════════════════════════════════════════════════

import React from 'react'
import { Shield, RefreshCw, AlertTriangle, XCircle } from 'lucide-react'
import { AIPredictionCard } from './AIPredictionCard'
import { Section, EmptyMessage } from './AIPagePrimitives'
import type { FailurePredictionResult } from './ai-types'
import { RISK_COLOR } from './ai-types'

export interface AIPredictionsTabProps {
  failurePred: FailurePredictionResult | null
  printerId: string
  onRefresh: () => void
}

export function AIPredictionsTab({ failurePred, printerId, onRefresh }: AIPredictionsTabProps) {
  const overallRiskColor = RISK_COLOR[failurePred?.overallRisk ?? 'minimal'] ?? 'text-green-400'
  const riskPct = failurePred ? Math.round(failurePred.overallProbability * 100) : 0

  return (
    <div className="space-y-4">
      <Section
        title="Failure Risk Analysis"
        icon={<Shield className="w-4 h-4 text-orange-400" />}
        action={<button onClick={onRefresh} className="text-gray-500 hover:text-gray-300"><RefreshCw className="w-3.5 h-3.5" /></button>}
      >
        {!failurePred ? (
          <EmptyMessage>No failure prediction data yet — run Analyze Now</EmptyMessage>
        ) : (
          <>
            {/* Overall risk gauge */}
            <div className="flex items-center gap-4 p-3 rounded-lg bg-gray-900/50 border border-gray-700">
              <div className="relative w-16 h-16 flex-shrink-0">
                <svg className="w-full h-full -rotate-90" viewBox="0 0 36 36">
                  <circle cx="18" cy="18" r="15.9" fill="none" stroke="#1f2937" strokeWidth="3" />
                  <circle cx="18" cy="18" r="15.9" fill="none"
                    stroke={riskPct > 70 ? '#ef4444' : riskPct > 40 ? '#f97316' : riskPct > 20 ? '#eab308' : '#22c55e'}
                    strokeWidth="3" strokeDasharray={`${riskPct} ${100 - riskPct}`} strokeLinecap="round" />
                </svg>
                <div className={`absolute inset-0 flex items-center justify-center text-sm font-bold ${overallRiskColor}`}>
                  {riskPct}%
                </div>
              </div>
              <div className="flex-1">
                <div className="flex items-center gap-2 mb-1">
                  <span className="text-sm font-semibold text-gray-200">Overall Failure Risk</span>
                  <span className={`text-xs font-bold uppercase ${overallRiskColor}`}>{failurePred.overallRisk}</span>
                </div>
                {failurePred.shouldAbort && (
                  <div className="text-xs font-bold text-red-400 flex items-center gap-1">
                    <XCircle className="w-3.5 h-3.5" /> ABORT RECOMMENDED
                  </div>
                )}
                {failurePred.shouldPause && !failurePred.shouldAbort && (
                  <div className="text-xs font-bold text-orange-400 flex items-center gap-1">
                    <AlertTriangle className="w-3.5 h-3.5" /> PAUSE RECOMMENDED
                  </div>
                )}
                {!failurePred.shouldAbort && !failurePred.shouldPause && (
                  <div className="text-xs text-gray-400">No immediate action required</div>
                )}
                <div className="text-[10px] text-gray-500 mt-1">{failurePred.analyzedPoints} data points analyzed</div>
              </div>
            </div>

            {/* Per-failure-type predictions using AIPredictionCard */}
            {failurePred.predictions.length === 0 ? (
              <EmptyMessage>No specific failure risks detected</EmptyMessage>
            ) : (
              <div className="space-y-2">
                {failurePred.predictions.map((fp, i) => (
                  <AIPredictionCard key={i} prediction={{
                    id: `${fp.type}-${i}`,
                    printerId: printerId,
                    type: fp.type.includes('maintenance') || fp.type.includes('wear') ? 'maintenance'
                        : fp.type.includes('quality') || fp.type.includes('stringing') || fp.type.includes('performance') ? 'quality'
                        : 'failure',
                    description: fp.description,
                    probability: fp.probability,
                    confidence: fp.confidence,
                    timeframe: fp.estimatedTimeToFailure
                      ? `~${fp.estimatedTimeToFailure} min`
                      : fp.riskLevel.charAt(0).toUpperCase() + fp.riskLevel.slice(1) + ' risk',
                    predictedAt: failurePred.analyzedAt,
                    createdAt: failurePred.analyzedAt,
                    preventiveMeasures: fp.mitigationActions,
                  }} />
                ))}
              </div>
            )}
          </>
        )}
      </Section>
    </div>
  )
}

export default AIPredictionsTab
