// ═══════════════════════════════════════════════════════════════
// PRESTIGE DASHBOARD - SYSTEM STORE (Zustand)
// ═══════════════════════════════════════════════════════════════

import { create } from 'zustand'
import { devtools } from 'zustand/middleware'
import type { SystemHealth, WSConnectionStatus } from '@core/types'

// ═══════════════════════════════════════════════════════════════
// TYPES
// ═══════════════════════════════════════════════════════════════

interface BackupInfo {
  lastBackup: string | null
  nextScheduledBackup: string | null
  backupInProgress: boolean
  backupError: string | null
}

interface SystemState {
  // Connection
  connectionStatus: WSConnectionStatus
  reconnectAttempts: number
  lastConnected: string | null
  
  // Health
  health: SystemHealth | null
  
  // Backend info
  backendVersion: string | null
  backendUrl: string
  
  // Backup
  backup: BackupInfo
  
  // Errors
  errors: Array<{
    id: string
    message: string
    timestamp: string
    acknowledged: boolean
  }>
  
  // Feature flags (from backend)
  features: {
    aiEnabled: boolean
    multiPrinter: boolean
    backupEnabled: boolean
    cameraSupport: boolean
  }
}

interface SystemActions {
  // Connection
  setConnectionStatus: (status: WSConnectionStatus) => void
  incrementReconnectAttempts: () => void
  resetReconnectAttempts: () => void
  setLastConnected: (timestamp: string) => void
  
  // Health
  setHealth: (health: SystemHealth) => void
  updateHealth: (health: Partial<SystemHealth>) => void
  setSystemStatus: (status: SystemHealth['status']) => void
  
  // Backend
  setBackendVersion: (version: string) => void
  setBackendUrl: (url: string) => void
  
  // Backup
  setBackupInfo: (info: Partial<BackupInfo>) => void
  setBackupInProgress: (inProgress: boolean) => void
  
  // Errors
  addError: (message: string) => void
  acknowledgeError: (id: string) => void
  clearErrors: () => void
  
  // Features
  setFeatures: (features: Partial<SystemState['features']>) => void
  
  // Reset
  reset: () => void
}

type SystemStore = SystemState & SystemActions

// ═══════════════════════════════════════════════════════════════
// INITIAL STATE
// ═══════════════════════════════════════════════════════════════

const initialState: SystemState = {
  connectionStatus: 'disconnected',
  reconnectAttempts: 0,
  lastConnected: null,
  health: null,
  backendVersion: null,
  backendUrl: import.meta.env.VITE_API_URL || 'http://localhost:3002',
  backup: {
    lastBackup: null,
    nextScheduledBackup: null,
    backupInProgress: false,
    backupError: null,
  },
  errors: [],
  features: {
    aiEnabled: true,
    multiPrinter: true,
    backupEnabled: true,
    cameraSupport: true,
  },
}

// ═══════════════════════════════════════════════════════════════
// HELPERS
// ═══════════════════════════════════════════════════════════════

const generateErrorId = () => `error-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`

// ═══════════════════════════════════════════════════════════════
// STORE
// ═══════════════════════════════════════════════════════════════

export const useSystemStore = create<SystemStore>()(
  devtools(
    (set, get) => ({
      ...initialState,

      // ─────────────────────────────────────────────────────────
      // Connection
      // ─────────────────────────────────────────────────────────
      
      setConnectionStatus: (status) => {
        set({ connectionStatus: status })
        if (status === 'connected') {
          set({ 
            lastConnected: new Date().toISOString(),
            reconnectAttempts: 0,
          })
        }
      },

      incrementReconnectAttempts: () => {
        set((state) => ({ reconnectAttempts: state.reconnectAttempts + 1 }))
      },

      resetReconnectAttempts: () => {
        set({ reconnectAttempts: 0 })
      },

      setLastConnected: (timestamp) => {
        set({ lastConnected: timestamp })
      },

      // ─────────────────────────────────────────────────────────
      // Health
      // ─────────────────────────────────────────────────────────
      
      setHealth: (health) => {
        set({ health })
      },

      updateHealth: (healthUpdate) => {
        set((state) => ({
          health: state.health 
            ? { ...state.health, ...healthUpdate }
            : healthUpdate as SystemHealth,
        }))
      },

      setSystemStatus: (status) => {
        get().updateHealth({ status })
      },

      // ─────────────────────────────────────────────────────────
      // Backend
      // ─────────────────────────────────────────────────────────
      
      setBackendVersion: (version) => {
        set({ backendVersion: version })
      },

      setBackendUrl: (url) => {
        set({ backendUrl: url })
      },

      // ─────────────────────────────────────────────────────────
      // Backup
      // ─────────────────────────────────────────────────────────
      
      setBackupInfo: (info) => {
        set((state) => ({
          backup: { ...state.backup, ...info },
        }))
      },

      setBackupInProgress: (inProgress) => {
        set((state) => ({
          backup: { ...state.backup, backupInProgress: inProgress },
        }))
      },

      // ─────────────────────────────────────────────────────────
      // Errors
      // ─────────────────────────────────────────────────────────
      
      addError: (message) => {
        const error = {
          id: generateErrorId(),
          message,
          timestamp: new Date().toISOString(),
          acknowledged: false,
        }
        set((state) => ({
          errors: [error, ...state.errors].slice(0, 50), // Keep last 50 errors
        }))
      },

      acknowledgeError: (id) => {
        set((state) => ({
          errors: state.errors.map((e) =>
            e.id === id ? { ...e, acknowledged: true } : e
          ),
        }))
      },

      clearErrors: () => {
        set({ errors: [] })
      },

      // ─────────────────────────────────────────────────────────
      // Features
      // ─────────────────────────────────────────────────────────
      
      setFeatures: (features) => {
        set((state) => ({
          features: { ...state.features, ...features },
        }))
      },

      // ─────────────────────────────────────────────────────────
      // Reset
      // ─────────────────────────────────────────────────────────
      
      reset: () => {
        set(initialState)
      },
    }),
    { name: 'system-store' }
  )
)

// ═══════════════════════════════════════════════════════════════
// SELECTORS
// ═══════════════════════════════════════════════════════════════

export const selectConnectionStatus = (state: SystemStore) => state.connectionStatus
export const selectIsConnected = (state: SystemStore) => state.connectionStatus === 'connected'
export const selectReconnectAttempts = (state: SystemStore) => state.reconnectAttempts
export const selectLastConnected = (state: SystemStore) => state.lastConnected
export const selectHealth = (state: SystemStore) => state.health
export const selectBackendVersion = (state: SystemStore) => state.backendVersion
export const selectBackendUrl = (state: SystemStore) => state.backendUrl
export const selectBackupInfo = (state: SystemStore) => state.backup
export const selectFeatures = (state: SystemStore) => state.features

// Errors
export const selectErrors = (state: SystemStore) => state.errors
export const selectUnacknowledgedErrors = (state: SystemStore) =>
  state.errors.filter((e) => !e.acknowledged)
export const selectHasUnacknowledgedErrors = (state: SystemStore) =>
  state.errors.some((e) => !e.acknowledged)

// Health status
export const selectSystemStatus = (state: SystemStore) => {
  if (!state.health) return 'unknown'
  return state.health.status
}

export const selectIsSystemHealthy = (state: SystemStore) => {
  if (!state.health) return false
  return state.health.status === 'healthy'
}

// Combined status
export const selectOverallStatus = (state: SystemStore) => {
  if (state.connectionStatus !== 'connected') return 'disconnected'
  if (!state.health) return 'unknown'
  if (state.health.status === 'critical') return 'critical'
  if (state.health.status === 'degraded') return 'degraded'
  if (state.errors.some((e) => !e.acknowledged)) return 'warning'
  return 'healthy'
}

export default useSystemStore
