// ─── Calculator logic ─────────────────────────────────────────

interface PlanCost {
  plan:      PlanDef
  monthly:   number   // effective monthly cost
  total:     number   // total for billing period
  extra:     number   // extra printer cost per period
  savings:   number   // vs BASIC monthly
  isOptimal: boolean
}

function calcPlanCost(plan: PlanDef, printers: number): PlanCost {
  // Clamp to plan's hard cap
  const effectivePrinters = Math.min(printers, plan.printerLimit)
  const extraPrinters     = Math.max(0, effectivePrinters - plan.printerBase)

  let monthly: number
  let total:   number
  let extra:   number

  if (plan.id === 'ULTRA') {
    // Fixed 6-month price, no per-printer overage (all 50 included)
    total   = plan.price
    monthly = total / plan.months
    extra   = 0
  } else if (plan.id === 'ANNUAL') {
    // Fixed 12-month price, no per-printer overage (all 50 included)
    total   = plan.price
    monthly = total / plan.months
    extra   = 0
  } else {
    // BASIC / PRO — monthly rolling
    extra   = extraPrinters * plan.printerCost
    monthly = plan.price + extra
    total   = monthly
  }

  return { plan, monthly, total, extra, savings: 0, isOptimal: false }
}

function recommendPlan(printers: number): { costs: PlanCost[]; optimal: PlanDef } {
  const costs = PLANS.map((p) => calcPlanCost(p, printers))

  // Lowest effective monthly cost wins
  const sorted = [...costs].sort((a, b) => a.monthly - b.monthly)
  costs.forEach((c) => {
    if (c.plan.id === sorted[0].plan.id) c.isOptimal = true
  })

  // Savings vs BASIC
  const basicMonthly = costs.find((c) => c.plan.id === 'BASIC')!.monthly
  costs.forEach((c) => { c.savings = Math.max(0, basicMonthly - c.monthly) })

  return { costs, optimal: sorted[0].plan }
}

// ─── Status badge ─────────────────────────────────────────────

function StatusBadge({ status }: { status: string }) {
  const map: Record<string, { label: string; cls: string }> = {
    active:    { label: 'Active',      cls: 'bg-green-500/15 text-green-400 border-green-500/30' },
    trial:     { label: 'Trial',       cls: 'bg-cyan-500/15 text-cyan-400 border-cyan-500/30' },
    expired:   { label: 'Expired',     cls: 'bg-red-500/15 text-red-400 border-red-500/30' },
    cancelled: { label: 'Cancelled',   cls: 'bg-gray-500/15 text-gray-400 border-gray-500/30' },
    inactive:  { label: 'Inactive',    cls: 'bg-yellow-500/15 text-yellow-400 border-yellow-500/30' },
    past_due:  { label: 'Past Due',    cls: 'bg-orange-500/15 text-orange-400 border-orange-500/30' },
  }
  const cfg = map[status] ?? map.inactive
  return (
    <span className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-medium border ${cfg.cls}`}>
      <span className="w-1.5 h-1.5 rounded-full bg-current" />
      {cfg.label}
    </span>
  )
}

