// ═══════════════════════════════════════════════════════════════
// FEATURE: KLIPPER STATUS PANEL
// Extracted from PrinterDetailPage
// ═══════════════════════════════════════════════════════════════

import { useState, useEffect, useRef } from 'react'
import { AlertTriangle, RefreshCw } from 'lucide-react'
import { API_BASE_URL } from '@/utils/constants'
import type { Printer } from '@core/types/printer'

interface KlipperAnnouncement {
  entry_id: string; url: string; title: string; description: string
  priority: 'critical' | 'high' | 'normal' | 'optional'
  date: number; dismissed: boolean; source: string; component?: string
}

export function KlipperStatusPanel({ printer }: { printer: Printer }) {
  const [klipperState, setKlipperState] = useState('ready')
  const [stateMessage, setStateMessage] = useState('')
  const [announcements, setAnnouncements] = useState<KlipperAnnouncement[]>([])
  const [loading, setLoading] = useState<string | null>(null)
  const [dismissedIds, setDismissedIds] = useState<Set<string>>(new Set())
  const [actionStatus, setActionStatus] = useState<{ step: string; type: 'progress' | 'ok' | 'err'; label: string } | null>(null)
  const waitingForReady = useRef(false)
  const waitingTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const prevKlipperState = useRef('__init__')

  useEffect(() => {
    const fetchAll = async () => {
      try {
        const infoRes = await fetch(`${API_BASE_URL}/api/printers/${printer.id}/printer-info`)
        if (infoRes.ok) {
          const data = await infoRes.json()
          const result = data?.result ?? data
          setKlipperState(result?.state ?? 'unknown')
          setStateMessage(result?.state_message ?? '')
        }
      } catch {}
    }
    fetchAll()
    const interval = setInterval(fetchAll, 5000)
    return () => clearInterval(interval)
  }, [printer.id])

  useEffect(() => {
    if (!waitingForReady.current) return
    if (['startup', 'shutdown', 'unknown', ''].includes(klipperState)) return
    if (klipperState === prevKlipperState.current) return
    if (klipperState === 'ready') {
      setActionStatus(prev => prev
        ? { ...prev, step: `${prev.label} complete — Klipper ready!`, type: 'ok' }
        : { step: 'Klipper is ready!', type: 'ok', label: 'Done' }
      )
      waitingForReady.current = false
      if (waitingTimeoutRef.current) clearTimeout(waitingTimeoutRef.current)
      setTimeout(() => { window.location.href = `/ai?tab=diagnostics&printer=${printer.id}&autorun=printer_status` }, 1500)
    } else {
      waitingForReady.current = false
      if (waitingTimeoutRef.current) clearTimeout(waitingTimeoutRef.current)
      setActionStatus({ step: 'Klipper error state. Fix config and restart.', type: 'err', label: actionStatus?.label ?? 'Restart' })
      setTimeout(() => { setActionStatus(null); setLoading(null) }, 4000)
    }
  }, [klipperState])

  const sendGcodeDirect = async (gcode: string): Promise<boolean> => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/printers/${printer.id}/gcode-direct`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ gcode }),
      })
      return res.ok
    } catch { return false }
  }

  const startWaiting = (label: string, timeoutMs = 20_000) => {
    prevKlipperState.current = klipperState
    waitingForReady.current = true
    setActionStatus({ step: `${label} sent — waiting for Klipper…`, type: 'progress', label })
    if (waitingTimeoutRef.current) clearTimeout(waitingTimeoutRef.current)
    waitingTimeoutRef.current = setTimeout(() => {
      if (waitingForReady.current) {
        waitingForReady.current = false
        setActionStatus({ step: 'Timed out. Fix config and try again.', type: 'err', label })
        setTimeout(() => { setActionStatus(null); setLoading(null) }, 4000)
      }
    }, timeoutMs)
  }

  const handleRestart = async () => {
    setLoading('restart')
    setActionStatus({ step: 'Sending restart…', type: 'progress', label: 'Restart' })
    const ok = await fetch(`${API_BASE_URL}/api/printers/${printer.id}/gcode-direct`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ gcode: 'RESTART' }),
    }).then(r => r.ok).catch(() => false)
    if (ok) startWaiting('Restart')
    else { setActionStatus({ step: 'Restart failed', type: 'err', label: 'Restart' }); setTimeout(() => { setActionStatus(null); setLoading(null) }, 4000) }
  }

  const handleFirmwareRestart = async () => {
    setLoading('firmware')
    setActionStatus({ step: 'Sending FIRMWARE_RESTART…', type: 'progress', label: 'Firmware Restart' })
    const ok = await sendGcodeDirect('FIRMWARE_RESTART')
    if (ok) startWaiting('Firmware Restart')
    else { setActionStatus({ step: 'FIRMWARE_RESTART failed', type: 'err', label: 'Firmware Restart' }); setTimeout(() => { setActionStatus(null); setLoading(null) }, 4000) }
  }

  const dismissAnnouncement = async (entryId: string) => {
    setDismissedIds(prev => new Set(prev).add(entryId))
    try {
      await fetch('/moonraker/server/announcements/dismiss', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ entry_id: entryId, wake_time: 0 }),
      })
    } catch {}
  }

  const stateInfo = (() => {
    switch (klipperState) {
      case 'error':    return { label: 'ERROR',   color: 'text-red-400',    border: 'border-red-500/50',    bg: 'bg-red-950/60' }
      case 'shutdown': return { label: 'SHUTDOWN', color: 'text-red-400',    border: 'border-red-500/50',    bg: 'bg-red-950/60' }
      case 'startup':  return { label: 'STARTING', color: 'text-yellow-400', border: 'border-yellow-500/50', bg: 'bg-yellow-950/40' }
      case 'ready':    return { label: 'READY',    color: 'text-green-400',  border: 'border-green-500/30',  bg: 'bg-green-950/20' }
      default:         return { label: klipperState.toUpperCase(), color: 'text-gray-400', border: 'border-gray-700', bg: 'bg-gray-900/50' }
    }
  })()

  const visibleAnnouncements = announcements.filter(a => !a.dismissed && !dismissedIds.has(a.entry_id))
  const hasNonReady = klipperState !== 'ready' && klipperState !== 'unknown'

  const priorityInfo: Record<string, { color: string; bg: string; border: string; icon: string }> = {
    critical: { color: 'text-red-400',    bg: 'bg-red-950/60',    border: 'border-red-500/50',    icon: '🚨' },
    high:     { color: 'text-orange-400', bg: 'bg-orange-950/50', border: 'border-orange-500/50', icon: '⚠️' },
    normal:   { color: 'text-yellow-400', bg: 'bg-yellow-950/30', border: 'border-yellow-600/40', icon: '📢' },
    optional: { color: 'text-blue-400',   bg: 'bg-blue-950/30',   border: 'border-blue-600/40',   icon: 'ℹ️' },
  }

  return (
    <div className="space-y-3">
      {hasNonReady && !actionStatus && (
        <div className={`${stateInfo.bg} border ${stateInfo.border} rounded-xl p-4`}>
          <div className={`flex items-center gap-2 mb-3 ${stateInfo.color}`}>
            <AlertTriangle className="w-4 h-4 flex-shrink-0" />
            <span className="text-sm font-bold font-mono">Klipper: {stateInfo.label}</span>
          </div>
          {stateMessage && (
            <pre className={`text-xs font-mono ${stateInfo.color}/90 bg-black/30 rounded-lg p-3 mb-4 whitespace-pre-wrap leading-relaxed`}>
              {stateMessage}
            </pre>
          )}
          <div className="grid grid-cols-2 gap-2">
            {[
              { label: 'RESTART', handler: handleRestart, key: 'restart' },
              { label: 'KLIPPER LOG', handler: () => window.open('/moonraker/server/files/logs/klippy.log', '_blank'), key: 'log' },
              { label: 'FIRMWARE RESTART', handler: handleFirmwareRestart, key: 'firmware' },
              { label: 'MOONRAKER LOG', handler: () => window.open('/moonraker/server/files/logs/moonraker.log', '_blank'), key: 'mlog' },
            ].map(btn => (
              <button key={btn.key} onClick={btn.handler} disabled={loading !== null && btn.key !== 'log' && btn.key !== 'mlog'}
                className={`flex items-center justify-center gap-2 px-3 py-2 text-xs font-semibold ${stateInfo.bg} ${stateInfo.color} border ${stateInfo.border} rounded-lg hover:opacity-80 disabled:opacity-50`}>
                <RefreshCw className={`w-3.5 h-3.5 ${loading === btn.key ? 'animate-spin' : ''}`} />
                {btn.label}
              </button>
            ))}
          </div>
        </div>
      )}

      {actionStatus && (
        <div className={`rounded-xl border p-4 ${
          actionStatus.type === 'progress' ? 'bg-gray-900/80 border-gray-600' :
          actionStatus.type === 'ok'       ? 'bg-green-950/60 border-green-500/50' :
                                             'bg-red-950/60 border-red-500/50'
        }`}>
          <div className="flex items-center gap-3">
            {actionStatus.type === 'progress' && <RefreshCw className="w-5 h-5 text-cyan-400 animate-spin flex-shrink-0" />}
            {actionStatus.type === 'ok'       && <span className="text-green-400 text-lg">✓</span>}
            {actionStatus.type === 'err'      && <span className="text-red-400 text-lg">✗</span>}
            <div>
              <div className={`text-xs font-bold font-mono ${actionStatus.type === 'progress' ? 'text-cyan-400' : actionStatus.type === 'ok' ? 'text-green-400' : 'text-red-400'}`}>{actionStatus.label.toUpperCase()}</div>
              <div className={`text-xs font-mono mt-0.5 ${actionStatus.type === 'progress' ? 'text-gray-300' : actionStatus.type === 'ok' ? 'text-green-300' : 'text-red-300'}`}>{actionStatus.step}</div>
            </div>
          </div>
        </div>
      )}

      {visibleAnnouncements.length > 0 && (
        <div className="space-y-2">
          {visibleAnnouncements.map(ann => {
            const pi = priorityInfo[ann.priority] ?? priorityInfo.normal
            return (
              <div key={ann.entry_id} className={`${pi.bg} border ${pi.border} rounded-xl p-3`}>
                <div className="flex items-start justify-between gap-2 mb-1">
                  <div className="flex items-center gap-2 min-w-0">
                    <span className="text-sm flex-shrink-0">{pi.icon}</span>
                    <span className={`text-xs font-bold ${pi.color} font-mono`}>{ann.title}</span>
                  </div>
                  <button onClick={() => dismissAnnouncement(ann.entry_id)}
                    className={`flex-shrink-0 text-[10px] px-2 py-0.5 rounded border ${pi.border} ${pi.color} opacity-60 hover:opacity-100`}>✕</button>
                </div>
                {ann.description && <p className={`text-[11px] ${pi.color}/70 mb-2`}>{ann.description}</p>}
                <div className="flex items-center justify-between gap-2">
                  <span className="text-[9px] text-gray-600">{ann.source}{ann.component ? ` · ${ann.component}` : ''}</span>
                  {ann.url && <a href={ann.url} target="_blank" rel="noopener noreferrer" className={`text-[10px] ${pi.color} underline`}>Details →</a>}
                </div>
              </div>
            )
          })}
        </div>
      )}
    </div>
  )
}
