// ═══════════════════════════════════════════════════════════════
// PRESTIGE DASHBOARD - AI STORE (Zustand)
// ═══════════════════════════════════════════════════════════════

import { create } from 'zustand'
import { devtools, persist } from 'zustand/middleware'
import type {
  AIStatus,
  AIAutonomyLevel,
  AIRecommendationStatus,
  AIPrediction,
  AISettings,
} from '@core/types'
import type { Recommendation as AIRecommendation, BackendAnomaly as Anomaly } from '@features/ai-panel/ai-types'

// ── Executed action shape (from WebSocket ai.action.executed payload) ─
export interface ExecutedAction {
  id: string
  printerId: string
  actionType: string
  reason: string
  executedAt: string
  acknowledged?: boolean
  result?: string
  params?: Record<string, unknown>
}

// ═══════════════════════════════════════════════════════════════
// TYPES
// ═══════════════════════════════════════════════════════════════

interface AIState {
  // Status
  isEnabled: boolean
  status: AIStatus | null

  // Per-printer AI levels (0=Passive, 1=Recommend, 2=Automatic)
  printerLevels: Record<string, number>
  
  // Recommendations
  recommendations: AIRecommendation[]
  
  // Executed actions
  executedActions: ExecutedAction[]
  
  // Anomalies
  anomalies: Anomaly[]
  
  // Predictions
  predictions: AIPrediction[]
  
  // Settings
  settings: AISettings
  
  // Loading
  isLoading: boolean
  isAnalyzing: boolean
  error: string | null
}

interface AIActions {
  // Status
  toggleAI: () => void
  setAIEnabled: (enabled: boolean) => void
  setAIStatus: (status: AIStatus | null) => void
  updateAIStatus: (status: Partial<AIStatus>) => void

  // Per-printer AI level
  setPrinterLevel: (printerId: string, level: number) => void
  getPrinterLevel: (printerId: string) => number
  
  // Recommendations
  addRecommendation: (recommendation: AIRecommendation) => void
  updateRecommendationStatus: (id: string, status: AIRecommendationStatus, note?: string) => void
  removeRecommendation: (id: string) => void
  clearExpiredRecommendations: () => void
  
  // Actions
  addExecutedAction: (action: ExecutedAction) => void
  acknowledgeAction: (actionId: string) => void
  
  // Anomalies
  addAnomaly: (anomaly: Anomaly) => void
  resolveAnomaly: (id: string) => void
  clearResolvedAnomalies: () => void
  
  // Predictions
  setPredictions: (predictions: AIPrediction[]) => void
  addPrediction: (prediction: AIPrediction) => void
  
  // Settings
  updateSettings: (settings: Partial<AISettings>) => void
  updateAISettings: (settings: Partial<AISettings>) => void // Alias for updateSettings
  setAutonomyLevel: (level: AIAutonomyLevel) => void
  
  // Loading
  setLoading: (isLoading: boolean) => void
  setAnalyzing: (isAnalyzing: boolean) => void
  setError: (error: string | null) => void
  
  // Reset
  reset: () => void
}

type AIStore = AIState & AIActions

// ═══════════════════════════════════════════════════════════════
// DEFAULT SETTINGS
// ═══════════════════════════════════════════════════════════════

const defaultSettings: AISettings = {
  enabled: true,
  autonomyLevel: 'L1',
  modules: {
    anomalyDetection: true,
    qualityAssessment: true,
    maintenancePrediction: true,
    failurePrediction: true,
    optimizationSuggestions: true,
  },
  thresholds: {
    anomalySensitivity: 'medium',
    qualityThreshold: 70,
    maintenanceWarningDays: 7,
  },
  notifications: {
    emailOnCritical: false,
    pushNotifications: true,
  },
  autoAcceptRecommendations: false,
  predictiveAlerts: true,
  dataRetentionDays: 90,
}

// ═══════════════════════════════════════════════════════════════
// LIMITS
// ═══════════════════════════════════════════════════════════════

const MAX_RECOMMENDATIONS = 50

// ═══════════════════════════════════════════════════════════════
// INITIAL STATE
// ═══════════════════════════════════════════════════════════════

const initialState: AIState = {
  isEnabled: true,
  status: null,
  printerLevels: {},
  recommendations: [],
  executedActions: [],
  anomalies: [],
  predictions: [],
  settings: defaultSettings,
  isLoading: false,
  isAnalyzing: false,
  error: null,
}

// ═══════════════════════════════════════════════════════════════
// STORE
// ═══════════════════════════════════════════════════════════════

export const useAIStore = create<AIStore>()(
  devtools(
    persist(
      (set, get) => ({
        ...initialState,

        // ─────────────────────────────────────────────────────────
        // Status
        // ─────────────────────────────────────────────────────────
        
        setPrinterLevel: (printerId, level) => {
          set((state) => ({
            printerLevels: { ...state.printerLevels, [printerId]: level },
          }))
        },

        getPrinterLevel: (printerId) => {
          return get().printerLevels[printerId] ?? 1
        },

        toggleAI: () => {
          set((state) => ({ isEnabled: !state.isEnabled }))
        },

        setAIEnabled: (enabled) => {
          set({ isEnabled: enabled })
        },

        setAIStatus: (status) => {
          set({ status })
        },

        updateAIStatus: (statusUpdate) => {
          set((state) => ({
            status: state.status 
              ? { ...state.status, ...statusUpdate }
              : statusUpdate as AIStatus,
          }))
        },

        // ─────────────────────────────────────────────────────────
        // Recommendations
        // ─────────────────────────────────────────────────────────
        
        addRecommendation: (recommendation) => {
          const now = new Date().toISOString()
          set((state) => {
            const withoutExpired = state.recommendations.filter(
              (r) => !r.expiresAt || r.expiresAt > now
            )
            const trimmed = [recommendation, ...withoutExpired].slice(0, MAX_RECOMMENDATIONS)
            return { recommendations: trimmed }
          })
        },

        updateRecommendationStatus: (id, status, note) => {
          set((state) => ({
            recommendations: state.recommendations.map((r) =>
              r.id === id
                ? {
                    ...r,
                    status,
                    responseNote: note,
                    respondedAt: new Date().toISOString(),
                  }
                : r
            ),
          }))
        },

        removeRecommendation: (id) => {
          set((state) => ({
            recommendations: state.recommendations.filter((r) => r.id !== id),
          }))
        },

        clearExpiredRecommendations: () => {
          const now = new Date().toISOString()
          set((state) => ({
            recommendations: state.recommendations.filter(
              (r) => !r.expiresAt || r.expiresAt > now
            ),
          }))
        },

        // ─────────────────────────────────────────────────────────
        // Executed Actions
        // ─────────────────────────────────────────────────────────
        
        addExecutedAction: (action) => {
          set((state) => ({
            executedActions: [action, ...state.executedActions],
          }))
        },

        acknowledgeAction: (actionId) => {
          set((state) => ({
            executedActions: state.executedActions.map((a) =>
              a.id === actionId ? { ...a, acknowledged: true } : a
            ),
          }))
        },

        // ─────────────────────────────────────────────────────────
        // Anomalies
        // ─────────────────────────────────────────────────────────
        
        addAnomaly: (anomaly) => {
          set((state) => ({
            anomalies: [anomaly, ...state.anomalies],
          }))
        },

        resolveAnomaly: (id) => {
          set((state) => ({
            anomalies: state.anomalies.map((a) =>
              a.id === id
                ? { ...a, resolvedAt: new Date().toISOString() }
                : a
            ),
          }))
        },

        clearResolvedAnomalies: () => {
          set((state) => ({
            anomalies: state.anomalies.filter((a) => a.resolvedAt === null),
          }))
        },

        // ─────────────────────────────────────────────────────────
        // Predictions
        // ─────────────────────────────────────────────────────────
        
        setPredictions: (predictions) => {
          set({ predictions })
        },

        addPrediction: (prediction) => {
          set((state) => ({
            predictions: [prediction, ...state.predictions],
          }))
        },

        // ─────────────────────────────────────────────────────────
        // Settings
        // ─────────────────────────────────────────────────────────
        
        updateSettings: (settingsUpdate) => {
          set((state) => ({
            settings: { ...state.settings, ...settingsUpdate },
          }))
        },

        updateAISettings: (settingsUpdate) => {
          get().updateSettings(settingsUpdate)
        },

        setAutonomyLevel: (level) => {
          set((state) => ({
            settings: { ...state.settings, autonomyLevel: level },
          }))
        },

        // ─────────────────────────────────────────────────────────
        // Loading
        // ─────────────────────────────────────────────────────────
        
        setLoading: (isLoading) => {
          set({ isLoading })
        },

        setAnalyzing: (isAnalyzing) => {
          set({ isAnalyzing })
        },

        setError: (error) => {
          set({ error, isLoading: false, isAnalyzing: false })
        },

        // ─────────────────────────────────────────────────────────
        // Reset
        // ─────────────────────────────────────────────────────────
        
        reset: () => {
          set(initialState)
        },
      }),
      {
        name: 'ai-store',
        partialize: (state) => ({
          settings: state.settings,
          isEnabled: state.isEnabled,
          printerLevels: state.printerLevels,
        }),
      }
    ),
    { name: 'ai-store' }
  )
)

// ═══════════════════════════════════════════════════════════════
// SELECTORS
// ═══════════════════════════════════════════════════════════════

export const selectAIEnabled = (state: AIStore) => state.isEnabled
export const selectAIStatus = (state: AIStore) => state.status
export const selectAISettings = (state: AIStore) => state.settings
export const selectAutonomyLevel = (state: AIStore) => state.settings.autonomyLevel

// Recommendations
export const selectAllRecommendations = (state: AIStore) => state.recommendations
export const selectPendingRecommendations = (state: AIStore) =>
  state.recommendations.filter((r) => !r.acknowledged && !r.dismissed)
export const selectRecommendationsByPriority = (priority: AIRecommendation['priority']) =>
  (state: AIStore) => state.recommendations.filter((r) => r.priority === priority)
export const selectUrgentRecommendations = (state: AIStore) =>
  state.recommendations.filter((r) => r.priority === 'urgent' && !r.acknowledged && !r.dismissed)

// Anomalies
export const selectAllAnomalies = (state: AIStore) => state.anomalies
export const selectActiveAnomalies = (state: AIStore) =>
  state.anomalies.filter((a) => a.resolvedAt === null)
export const selectCriticalAnomalies = (state: AIStore) =>
  state.anomalies.filter((a) => a.severity === 'critical' && a.resolvedAt === null)
export const selectAnomaliesByPrinter = (printerId: string) => (state: AIStore) =>
  state.anomalies.filter((a) => a.printerId === printerId)

// Predictions
export const selectAllPredictions = (state: AIStore) => state.predictions
export const selectPredictionsByPrinter = (printerId: string) => (state: AIStore) =>
  state.predictions.filter((p) => p.printerId === printerId)
export const selectHighProbabilityPredictions = (state: AIStore) =>
  state.predictions.filter((p) => p.probability >= 0.7)

// Stats
export const selectAIStats = (state: AIStore) => ({
  totalRecommendations: state.recommendations.length,
  pendingRecommendations: state.recommendations.filter((r) => !r.acknowledged && !r.dismissed).length,
  activeAnomalies: state.anomalies.filter((a) => a.resolvedAt === null).length,
  criticalAnomalies: state.anomalies.filter((a) => a.severity === 'critical' && a.resolvedAt === null).length,
  predictions: state.predictions.length,
})

export default useAIStore
