// ═══════════════════════════════════════════════════════════════
// PRESTIGE DASHBOARD - AI ACTION PANEL
// Shows pending AI recommendations with approve/reject actions
// ═══════════════════════════════════════════════════════════════

import React, { useState } from 'react'
import {
  useAIStore,
  selectAIEnabled,
  selectAutonomyLevel,
  selectPendingRecommendations,
  selectAllRecommendations,
} from '@core/state/aiStore'
import {
  Activity, CheckCircle, XCircle, Clock, Zap, AlertTriangle,
  ChevronDown, ChevronUp, Brain, Info,
} from 'lucide-react'

export interface AIActionPanelProps {
  className?: string
}

export const AIActionPanel: React.FC<AIActionPanelProps> = ({ className = '' }) => {
  const aiEnabled = useAIStore(selectAIEnabled)
  const autonomyLevel = useAIStore(selectAutonomyLevel)
  const pendingRecommendations = useAIStore(selectPendingRecommendations)
  const allRecommendations = useAIStore(selectAllRecommendations)
  const { updateRecommendationStatus } = useAIStore()

  const [expandedId, setExpandedId] = useState<string | null>(null)
  const [loadingId, setLoadingId] = useState<string | null>(null)

  // No global recommendations endpoint — data comes from per-printer fetches via store

  const handleApprove = async (id: string) => {
    setLoadingId(id)
    try {
      const res = await fetch(`/api/ai/recommendations/${id}/approve`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ approved: true }),
      })
      if (res.ok) {
        updateRecommendationStatus(id, 'approved')
      }
    } catch { /* graceful */ }
    setLoadingId(null)
  }

  const handleReject = async (id: string) => {
    setLoadingId(id)
    try {
      const res = await fetch(`/api/ai/recommendations/${id}/reject`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ approved: false }),
      })
      if (res.ok) {
        updateRecommendationStatus(id, 'rejected')
      }
    } catch { /* graceful */ }
    setLoadingId(null)
  }

  // ─── Level label helper ────────────────────────────────────────
  const levelLabel = typeof autonomyLevel === 'number'
    ? ['L0 — Passive', 'L1 — Recommend', 'L2 — Automatic'][autonomyLevel as number] ?? `L${autonomyLevel}`
    : String(autonomyLevel)

  // ─── Priority color helper ─────────────────────────────────────
  const priorityColor = (priority?: string) => {
    switch (priority) {
      case 'urgent':   return 'text-red-400 bg-red-500/10 border-red-500/30'
      case 'high':     return 'text-orange-400 bg-orange-500/10 border-orange-500/30'
      case 'medium':   return 'text-yellow-400 bg-yellow-500/10 border-yellow-500/30'
      default:         return 'text-cyan-400 bg-cyan-500/10 border-cyan-500/30'
    }
  }

  return (
    <div className={`space-y-4 ${className}`}>
      {/* Header strip */}
      <div className="flex items-center justify-between px-1">
        <div className="flex items-center gap-2">
          <Brain className="w-5 h-5 text-cyan-400" />
          <span className="text-base font-semibold text-white">AI Recommendations</span>
          {pendingRecommendations.length > 0 && (
            <span className="px-2 py-0.5 rounded-full text-xs font-bold bg-cyan-500/20 text-cyan-400 border border-cyan-500/30">
              {pendingRecommendations.length} pending
            </span>
          )}
        </div>
        <div className="flex items-center gap-2 text-xs text-gray-400">
          <span className="px-2 py-0.5 rounded bg-gray-800 border border-gray-700">
            {levelLabel}
          </span>
          {!aiEnabled && (
            <span className="px-2 py-0.5 rounded bg-red-500/10 text-red-400 border border-red-500/30">
              AI Disabled
            </span>
          )}
        </div>
      </div>

      {/* AI disabled state */}
      {!aiEnabled && (
        <div className="rounded-lg border border-gray-700 bg-gray-900/50 p-8 text-center">
          <Brain className="w-12 h-12 mx-auto mb-3 text-gray-600" />
          <p className="text-white font-semibold mb-1">AI System is Disabled</p>
          <p className="text-sm text-gray-400">
            Enable the AI system in{' '}
            <span className="text-cyan-400">AI Settings</span>{' '}
            to start receiving recommendations.
          </p>
        </div>
      )}

      {/* Empty state */}
      {aiEnabled && pendingRecommendations.length === 0 && (
        <div className="rounded-lg border border-gray-700 bg-gray-900/50 p-8 text-center">
          <CheckCircle className="w-12 h-12 mx-auto mb-3 text-green-400/40" />
          <p className="text-white font-semibold mb-1">No Pending Recommendations</p>
          <p className="text-sm text-gray-400">
            The AI is monitoring your printers. Recommendations will appear here when action is needed.
          </p>
          {typeof autonomyLevel === 'number' && (autonomyLevel as number) === 2 && (
            <div className="mt-4 flex items-center justify-center gap-2 text-xs text-yellow-300/80">
              <Zap className="w-3.5 h-3.5 text-yellow-400" />
              L2 Automatic mode: low-risk actions are executed without approval
            </div>
          )}
        </div>
      )}

      {/* Recommendation cards */}
      {aiEnabled && pendingRecommendations.map((rec) => {
        const isExpanded = expandedId === rec.id
        const isLoading = loadingId === rec.id
        const pColor = priorityColor(rec.priority)

        return (
          <div
            key={rec.id}
            className="rounded-lg border border-gray-700 bg-gray-900/50 overflow-hidden"
          >
            {/* Card header */}
            <div className="flex items-start gap-3 p-4">
              <div className={`mt-0.5 px-1.5 py-0.5 rounded text-[10px] font-bold uppercase border ${pColor} flex-shrink-0`}>
                {rec.priority ?? 'low'}
              </div>

              <div className="flex-1 min-w-0">
                <div className="flex items-start justify-between gap-2">
                  <div>
                    <p className="text-sm font-semibold text-white leading-snug">
                      {rec.type ?? 'AI Recommendation'}
                    </p>
                    <p className="text-xs text-gray-400 mt-0.5 line-clamp-2">
                      {rec.reasoning ?? rec.description ?? ''}
                    </p>
                  </div>
                  {rec.confidence != null && (
                    <span className="flex-shrink-0 text-xs font-mono font-bold text-cyan-400">
                      {Math.round((rec.confidence <= 1 ? rec.confidence * 100 : rec.confidence))}%
                    </span>
                  )}
                </div>

                {/* Confidence bar */}
                {rec.confidence != null && (
                  <div className="mt-2 h-1.5 rounded-full bg-gray-800 overflow-hidden">
                    <div
                      className="h-full rounded-full bg-cyan-500 transition-all"
                      style={{ width: `${Math.round(rec.confidence <= 1 ? rec.confidence * 100 : rec.confidence)}%` }}
                    />
                  </div>
                )}

                {/* Meta */}
                <div className="flex items-center gap-3 mt-2 text-[11px] text-gray-500">
                  {rec.printerId && <span>Printer: {rec.printerId}</span>}
                  {rec.createdAt && (
                    <span className="flex items-center gap-1">
                      <Clock className="w-3 h-3" />
                      {new Date(rec.createdAt).toLocaleString(undefined, {
                        month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit',
                      })}
                    </span>
                  )}
                </div>
              </div>
            </div>

            {/* Expand / collapse details */}
            {(rec.suggestedActions?.length > 0) && (
              <button
                onClick={() => setExpandedId(isExpanded ? null : rec.id)}
                className="w-full flex items-center gap-1 px-4 pb-1 text-[11px] text-gray-500 hover:text-gray-300 transition-colors"
              >
                <Info className="w-3 h-3" />
                {isExpanded ? 'Hide details' : 'Show details'}
                {isExpanded ? <ChevronUp className="w-3 h-3 ml-auto" /> : <ChevronDown className="w-3 h-3 ml-auto" />}
              </button>
            )}

            {isExpanded && (
              <div className="px-4 pb-3 text-xs text-gray-400 bg-gray-950/50 border-t border-gray-700 pt-2">
                <pre className="whitespace-pre-wrap break-all">
                  {JSON.stringify(rec.suggestedActions, null, 2)}
                </pre>
              </div>
            )}

            {/* Action buttons */}
            <div className="flex items-center gap-2 px-4 pb-4 pt-2 border-t border-gray-800">
              <button
                onClick={() => handleApprove(rec.id)}
                disabled={isLoading}
                className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold bg-green-500/20 text-green-400 border border-green-500/30 hover:bg-green-500/30 transition-colors disabled:opacity-50"
              >
                <CheckCircle className="w-3.5 h-3.5" />
                {isLoading ? 'Processing…' : 'Approve'}
              </button>
              <button
                onClick={() => handleReject(rec.id)}
                disabled={isLoading}
                className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold bg-red-500/10 text-red-400 border border-red-500/30 hover:bg-red-500/30 transition-colors disabled:opacity-50"
              >
                <XCircle className="w-3.5 h-3.5" />
                Reject
              </button>
              {rec.expiresAt && (
                <span className="ml-auto text-[11px] text-gray-500 flex items-center gap-1">
                  <AlertTriangle className="w-3 h-3 text-yellow-500" />
                  expires {new Date(rec.expiresAt).toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit' })}
                </span>
              )}
            </div>
          </div>
        )
      })}
    </div>
  )
}

export default AIActionPanel
