// ─── File Icon ────────────────────────────────────────────────
function getFileIcon(filename: string, color: string) {
  const ext = filename.split('.').pop()?.toLowerCase()
  if (ext === 'cfg' || ext === 'conf') return <FileCode className={`w-3.5 h-3.5 text-${color}-400`} />
  if (ext === 'log') return <ScrollText className="w-3.5 h-3.5 text-orange-400" />
  return <FileText className="w-3.5 h-3.5 text-gray-400" />
}

// ═══════════════════════════════════════════════════════════════
// EDITOR MODAL
// ═══════════════════════════════════════════════════════════════
function EditorModal({
  printerId, filename, root, readOnly = false,
  onClose, onSaved, toast,
}: {
  printerId: string
  filename: string
  root: string
  readOnly?: boolean
  onClose: () => void
  onSaved: () => void
  toast: (type: Toast['type'], msg: string) => void
}) {
  const [content, setContent]   = useState('')
  const [original, setOriginal] = useState('')
  const [loading, setLoading]   = useState(true)
  const [saving, setSaving]     = useState(false)
  const [searchOpen, setSearchOpen]     = useState(false)
  const [query, setQuery]               = useState('')
  const [matchCount, setMatchCount]     = useState(0)
  const [matchIndex, setMatchIndex]     = useState(0)
  const textareaRef    = useRef<HTMLTextAreaElement>(null)
  const searchInputRef = useRef<HTMLInputElement>(null)

  useEffect(() => {
    ;(async () => {
      setLoading(true)
      try {
        const res = await fetch(
          `${BASE_URL}/api/printers/${printerId}/file-content?root=${encodeURIComponent(root)}&filename=${encodeURIComponent(filename)}`
        )
        const t = await res.text()
        setContent(t); setOriginal(t)
      } catch {
        toast('error', `Failed to load ${filename}`); onClose()
      } finally { setLoading(false) }
    })()
  }, [])

  useEffect(() => {
    const h = (e: KeyboardEvent) => {
      if ((e.ctrlKey || e.metaKey) && e.key === 'f') {
        e.preventDefault(); setSearchOpen(true)
        setTimeout(() => searchInputRef.current?.focus(), 60)
      }
      if (e.key === 'Escape' && searchOpen) { setSearchOpen(false); setQuery('') }
    }
    window.addEventListener('keydown', h)
    return () => window.removeEventListener('keydown', h)
  }, [searchOpen])

  useEffect(() => {
    if (!query.trim()) { setMatchCount(0); setMatchIndex(0); return }
    const re = new RegExp(escapeRe(query), 'gi')
    const m = [...content.matchAll(re)]
    setMatchCount(m.length); setMatchIndex(0)
  }, [query, content])

  const jumpTo = useCallback((n: number) => {
    if (!query.trim() || matchCount === 0 || !textareaRef.current) return
    const re = new RegExp(escapeRe(query), 'gi')
    const matches = [...content.matchAll(re)]
    const idx = ((n % matches.length) + matches.length) % matches.length
    const m = matches[idx]
    const start = m.index ?? 0
    const end = start + m[0].length
    textareaRef.current.focus()
    textareaRef.current.setSelectionRange(start, end)
    const linesBefore = content.slice(0, start).split('\n').length
    textareaRef.current.scrollTop = Math.max(0, (linesBefore - 5) * 18)
    setMatchIndex(idx)
  }, [query, content, matchCount])

  const next = () => jumpTo(matchIndex + 1)
  const prev = () => jumpTo(matchIndex - 1)

  const handleSave = async () => {
    setSaving(true)
    try {
      await api.post(`/api/printers/${printerId}/config-file-save`, { filename, content })
      toast('success', `${filename} saved`); setOriginal(content); onSaved()
    } catch (e: any) {
      toast('error', e?.message ?? `Failed to save ${filename}`)
    } finally { setSaving(false) }
  }

  const isDirty = content !== original

  return (
    <div style={{ position: 'fixed', inset: 0, zIndex: 9999, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
      <div className="absolute inset-0 bg-black/70 backdrop-blur-sm" onClick={onClose} />
      <motion.div
        initial={{ opacity: 0, scale: 0.97 }}
        animate={{ opacity: 1, scale: 1 }}
        className="relative z-10 bg-gray-900 border border-cyan-500/30 rounded-xl w-[880px] max-w-[96vw] h-[84vh] flex flex-col shadow-2xl overflow-hidden"
      >
        <div className="flex items-center gap-2 px-4 py-3 border-b border-gray-700 flex-shrink-0">
          <FileCode className="w-4 h-4 text-cyan-400 flex-shrink-0" />
          <span className="text-sm font-bold text-gray-100 truncate">{filename}</span>
          {readOnly && <span className="text-[10px] bg-gray-700 text-gray-400 border border-gray-600 px-1.5 py-0.5 rounded ml-1">READ ONLY</span>}
          {isDirty && !readOnly && <span className="text-[10px] bg-yellow-500/20 text-yellow-400 border border-yellow-500/40 px-1.5 py-0.5 rounded ml-1">Unsaved</span>}
          <div className="flex items-center gap-1.5 ml-auto">
            <button
              onClick={() => { setSearchOpen(v => !v); setTimeout(() => searchInputRef.current?.focus(), 60) }}
              className={`flex items-center gap-1.5 px-2.5 py-1.5 text-xs rounded-lg border transition-colors ${searchOpen ? 'bg-cyan-500/20 border-cyan-500/40 text-cyan-300' : 'border-gray-700 text-gray-400 hover:bg-gray-800 hover:text-gray-200'}`}
            >
              <Search className="w-3.5 h-3.5" /><span>Search</span>
            </button>
            {!readOnly && (
              <button onClick={handleSave} disabled={saving || !isDirty}
                className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-semibold text-cyan-400 border border-cyan-500/50 bg-cyan-500/15 rounded-lg hover:bg-cyan-500/25 transition-colors disabled:opacity-40">
                {saving ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Save className="w-3.5 h-3.5" />}
                {saving ? 'Saving…' : 'Save'}
              </button>
            )}
            <button onClick={onClose} className="p-1.5 rounded-lg text-gray-500 hover:text-gray-200 hover:bg-gray-800 transition-colors">
              <X className="w-4 h-4" />
            </button>
          </div>
        </div>

        <AnimatePresence>
          {searchOpen && (
            <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }}
              transition={{ duration: 0.15 }} className="flex-shrink-0 overflow-hidden border-b border-gray-700/60">
              <div className="flex items-center gap-2 px-4 py-2">
                <Search className="w-3.5 h-3.5 text-gray-500 flex-shrink-0" />
                <input ref={searchInputRef} id="editor-search" name="editor-search" value={query}
                  onChange={e => { setQuery(e.target.value); if (e.target.value) setTimeout(() => jumpTo(0), 60) }}
                  onKeyDown={e => { if (e.key === 'Enter') { e.shiftKey ? prev() : next() }; if (e.key === 'Escape') { setSearchOpen(false); setQuery('') } }}
                  placeholder="Search… (Enter = next, Shift+Enter = prev)"
                  className="flex-1 bg-transparent text-sm text-gray-100 placeholder-gray-500 focus:outline-none" />
                {query && <span className={`text-xs flex-shrink-0 tabular-nums ${matchCount === 0 ? 'text-red-400' : 'text-gray-400'}`}>{matchCount === 0 ? 'No results' : `${matchIndex + 1} / ${matchCount}`}</span>}
                <div className="flex items-center gap-0.5 flex-shrink-0">
                  <button onClick={prev} disabled={matchCount === 0} className="w-7 h-7 flex items-center justify-center rounded border border-gray-700 text-gray-400 hover:bg-gray-800 disabled:opacity-30"><ChevronDown className="w-3.5 h-3.5 rotate-180" /></button>
                  <button onClick={next} disabled={matchCount === 0} className="w-7 h-7 flex items-center justify-center rounded border border-gray-700 text-gray-400 hover:bg-gray-800 disabled:opacity-30"><ChevronDown className="w-3.5 h-3.5" /></button>
                  <button onClick={() => { setSearchOpen(false); setQuery('') }} className="w-7 h-7 flex items-center justify-center rounded border border-gray-700 text-gray-400 hover:bg-gray-800 ml-0.5"><X className="w-3 h-3" /></button>
                </div>
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        <div className="flex-1 overflow-hidden">
          {loading ? (
            <div className="flex items-center justify-center h-full text-gray-500">
              <Loader2 className="w-5 h-5 animate-spin mr-2" />Loading {filename}…
            </div>
          ) : (
            <textarea ref={textareaRef} value={content} onChange={e => !readOnly && setContent(e.target.value)}
              readOnly={readOnly} spellCheck={false}
              className={`w-full h-full resize-none bg-gray-950 text-gray-200 text-xs font-mono p-4 focus:outline-none leading-relaxed ${readOnly ? 'cursor-default' : ''}`}
              style={{ tabSize: 2 }} />
          )}
        </div>
      </motion.div>
    </div>
  )
}

// ─── Input Modal ─────────────────────────────────────────────
function InputModal({ title, label, placeholder, confirmLabel, icon, onConfirm, onClose }: {
  title: string; label: string; placeholder: string; confirmLabel: string
  icon: React.ReactNode; onConfirm: (v: string) => Promise<void>; onClose: () => void
}) {
  const [value, setValue] = useState('')
  const [busy, setBusy] = useState(false)
  const ref = useRef<HTMLInputElement>(null)
  useEffect(() => { ref.current?.focus() }, [])
  const go = async () => { if (!value.trim()) return; setBusy(true); try { await onConfirm(value.trim()) } finally { setBusy(false) } }
  return (
    <div style={{ position: 'fixed', inset: 0, zIndex: 9999, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={onClose} />
      <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }}
        className="relative z-10 bg-gray-900 border border-gray-700 rounded-xl w-[400px] max-w-[95vw] shadow-2xl overflow-hidden">
        <div className="flex items-center gap-3 px-5 py-4 border-b border-gray-700">
          <div className="w-8 h-8 rounded-lg bg-cyan-500/15 border border-cyan-500/30 flex items-center justify-center text-cyan-400">{icon}</div>
          <span className="text-sm font-bold text-gray-100">{title}</span>
          <button onClick={onClose} className="ml-auto text-gray-500 hover:text-gray-200 p-1 rounded hover:bg-gray-800"><X className="w-4 h-4" /></button>
        </div>
        <div className="px-5 py-4 flex flex-col gap-4">
          <div className="flex flex-col gap-1.5">
            <label className="text-xs text-gray-400 font-medium">{label}</label>
            <input ref={ref} id="input-modal-value" name="input-modal-value" value={value} onChange={e => setValue(e.target.value)}
              onKeyDown={e => { if (e.key === 'Enter') go(); if (e.key === 'Escape') onClose() }}
              placeholder={placeholder}
              className="bg-gray-800 border border-gray-600 rounded-lg px-3 py-2 text-sm text-gray-100 placeholder-gray-500 focus:outline-none focus:border-cyan-500/60" />
          </div>
          <div className="flex justify-end gap-2">
            <button onClick={onClose} className="px-4 py-2 text-xs text-gray-400 border border-gray-700 rounded-lg hover:bg-gray-800">Cancel</button>
            <button onClick={go} disabled={!value.trim() || busy}
              className="flex items-center gap-1.5 px-4 py-2 text-xs font-semibold text-cyan-400 border border-cyan-500/50 bg-cyan-500/15 rounded-lg hover:bg-cyan-500/25 disabled:opacity-40">
              {busy ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : icon}
              {busy ? 'Working…' : confirmLabel}
            </button>
          </div>
        </div>
      </motion.div>
    </div>
  )
}

// ─── Confirm Delete ──────────────────────────────────────────
function ConfirmDeleteModal({ filename, onConfirm, onClose }: {
  filename: string; onConfirm: () => Promise<void>; onClose: () => void
}) {
  const [busy, setBusy] = useState(false)
  const go = async () => { setBusy(true); try { await onConfirm() } finally { setBusy(false) } }
  return (
    <div style={{ position: 'fixed', inset: 0, zIndex: 9999, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={onClose} />
      <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }}
        className="relative z-10 bg-gray-900 border border-red-500/30 rounded-xl w-[400px] max-w-[95vw] shadow-2xl overflow-hidden">
        <div className="flex items-center gap-3 px-5 py-4 border-b border-gray-700">
          <div className="w-8 h-8 rounded-lg bg-red-500/15 border border-red-500/30 flex items-center justify-center text-red-400"><Trash2 className="w-4 h-4" /></div>
          <span className="text-sm font-bold text-gray-100">Delete File</span>
          <button onClick={onClose} className="ml-auto text-gray-500 hover:text-gray-200 p-1 rounded hover:bg-gray-800"><X className="w-4 h-4" /></button>
        </div>
        <div className="px-5 py-4 flex flex-col gap-4">
          <p className="text-sm text-gray-300">Delete <span className="font-mono text-red-400 font-semibold">{filename}</span>? This cannot be undone.</p>
          <div className="flex justify-end gap-2">
            <button onClick={onClose} className="px-4 py-2 text-xs text-gray-400 border border-gray-700 rounded-lg hover:bg-gray-800">Cancel</button>
            <button onClick={go} disabled={busy}
              className="flex items-center gap-1.5 px-4 py-2 text-xs font-semibold text-red-400 border border-red-500/50 bg-red-500/15 rounded-lg hover:bg-red-500/25 disabled:opacity-40">
              {busy ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Trash2 className="w-3.5 h-3.5" />}
              {busy ? 'Deleting…' : 'Delete'}
            </button>
          </div>
        </div>
      </motion.div>
    </div>
  )
}

// ═══════════════════════════════════════════════════════════════
// FILE BROWSER PANEL
// ═══════════════════════════════════════════════════════════════
export function FileBrowserPanel({ printer, toast }: {
  printer: PrinterType
  toast: (type: Toast['type'], msg: string) => void
}) {
  const [currentRoot, setCurrentRoot] = useState<FileRoot>(FILE_ROOTS[0])
  const [rootDropOpen, setRootDropOpen]   = useState(false)
  const [showHidden, setShowHidden]       = useState(false)
  const [hideBackups, setHideBackups]     = useState(true)
  const [settingsOpen, setSettingsOpen]   = useState(false)
  const [files, setFiles]                 = useState<BrowseFile[]>([])
  const [loading, setLoading]             = useState(false)
  const [error, setError]                 = useState<string | null>(null)
  const [search, setSearch]               = useState('')
  const [selectedFile, setSelectedFile]   = useState<BrowseFile | null>(null)
  const [content, setContent]             = useState('')
  const [contentLoading, setCLoading]     = useState(false)
  const [lineSearch, setLineSearch]       = useState('')
  const [wordWrap, setWordWrap]           = useState(false)
  const [autoScroll, setAutoScroll]       = useState(true)
  const [tailMode, setTailMode]           = useState(true)
  const [modal, setModal]                 = useState<'createFile' | 'createFolder' | 'delete' | 'editor' | null>(null)
  const [deleteTarget, setDeleteTarget]   = useState<string | null>(null)
  const logRef       = useRef<HTMLDivElement>(null)
  const fileInputRef = useRef<HTMLInputElement>(null)
  const rootDropRef  = useRef<HTMLDivElement>(null)
  const settingsRef  = useRef<HTMLDivElement>(null)

  useEffect(() => {
    const h = (e: MouseEvent) => {
      if (rootDropRef.current && !rootDropRef.current.contains(e.target as Node)) setRootDropOpen(false)
      if (settingsRef.current && !settingsRef.current.contains(e.target as Node)) setSettingsOpen(false)
    }
    document.addEventListener('mousedown', h)
    return () => document.removeEventListener('mousedown', h)
  }, [])

  const fetchFiles = useCallback(async () => {
    setLoading(true); setError(null); setSelectedFile(null); setContent('')
    try {
      const res = await fetch(`${BASE_URL}/api/printers/${printer.id}/files?root=${encodeURIComponent(currentRoot.id)}`)
      if (!res.ok) throw new Error(`HTTP ${res.status}`)
      const json = await res.json()
      const raw: BrowseFile[] = Array.isArray(json?.data ?? json) ? (json?.data ?? json) : []
      raw.sort((a, b) => {
        if (a.filename === 'printer.cfg') return -1
        if (b.filename === 'printer.cfg') return 1
        return currentRoot.isLog ? b.modified - a.modified : a.filename.localeCompare(b.filename)
      })
      setFiles(raw)
    } catch (e: any) { setError(e?.message ?? 'Failed to load') }
    finally { setLoading(false) }
  }, [printer.id, currentRoot.id])

  useEffect(() => { fetchFiles() }, [fetchFiles])

  useEffect(() => {
    if (autoScroll && logRef.current && content) logRef.current.scrollTop = logRef.current.scrollHeight
  }, [content, autoScroll])

  const fetchContent = useCallback(async (file: BrowseFile) => {
    setCLoading(true); setContent(''); setLineSearch('')
    try {
      const tail = currentRoot.isLog && tailMode ? 200000 : 0
      const res = await fetch(
        `${BASE_URL}/api/printers/${printer.id}/file-content?root=${encodeURIComponent(currentRoot.id)}&filename=${encodeURIComponent(file.filename)}&tail=${tail}`
      )
      if (!res.ok) throw new Error(`HTTP ${res.status}`)
      setContent(await res.text())
    } catch { toast('error', `Failed to load ${file.filename}`) }
    finally { setCLoading(false) }
  }, [printer.id, currentRoot.id, currentRoot.isLog, tailMode])

  useEffect(() => { if (selectedFile) fetchContent(selectedFile) }, [selectedFile])

  const filteredLines = useCallback(() => {
    if (!lineSearch.trim()) return content
    return content.split('\n').filter(l => l.toLowerCase().includes(lineSearch.toLowerCase())).join('\n')
  }, [content, lineSearch])

  const visible = files.filter(f => {
    if (!showHidden && isHidden(f.filename)) return false
    if (hideBackups && isBackup(f.filename)) return false
    if (search && !f.filename.toLowerCase().includes(search.toLowerCase())) return false
    return true
  })

  const handleUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]; if (!file) return
    e.target.value = ''
    try {
      const body = JSON.stringify({ filename: file.name, content: await file.text() })
      const res = await fetch(`${BASE_URL}/api/printers/${printer.id}/config-file-save`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body })
      const json = await res.json()
      if (!res.ok) throw new Error(json?.error ?? `HTTP ${res.status}`)
      toast('success', `${file.name} uploaded`); fetchFiles()
    } catch (e: any) { toast('error', e?.message ?? 'Upload failed') }
  }

  const handleCreateFile = async (filename: string) => {
    try {
      const res = await fetch(`${BASE_URL}/api/printers/${printer.id}/config-file-save`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ filename, content: '' }),
      })
      const json = await res.json()
      if (!res.ok) throw new Error(json?.error ?? `HTTP ${res.status}`)
      toast('success', `${filename} created`); setModal(null); fetchFiles()
    } catch (e: any) { toast('error', e?.message ?? 'Create failed') }
  }

  const handleCreateFolder = async (dirname: string) => {
    try {
      const res = await fetch(`${BASE_URL}/api/printers/${printer.id}/config-mkdir`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ dirname }),
      })
      const json = await res.json()
      if (!res.ok) throw new Error(json?.error ?? `HTTP ${res.status}`)
      toast('success', `Folder '${dirname}' created`); setModal(null); fetchFiles()
    } catch (e: any) { toast('error', e?.message ?? 'Create folder failed') }
  }

  const handleDelete = async () => {
    if (!deleteTarget) return
    try {
      const res = await fetch(`${BASE_URL}/api/printers/${printer.id}/config-file-delete`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ filename: deleteTarget }),
      })
      const json = await res.json()
      if (!res.ok) throw new Error(json?.error ?? `HTTP ${res.status}`)
      toast('success', `${deleteTarget} deleted`)
      setModal(null); setDeleteTarget(null); setSelectedFile(null); setContent(''); fetchFiles()
    } catch (e: any) { toast('error', e?.message ?? 'Delete failed') }
  }

  const IC = ({ onClick, title, active, children }: { onClick: () => void; title: string; active?: boolean; children: React.ReactNode }) => (
    <button onClick={onClick} title={title}
      className={`w-8 h-8 flex items-center justify-center rounded-lg border transition-all ${active
        ? 'bg-cyan-500/20 border-cyan-500/50 text-cyan-400'
        : 'border-gray-700 bg-gray-800/60 text-gray-400 hover:bg-gray-700 hover:text-gray-100 hover:border-gray-600'}`}>
      {children}
    </button>
  )

  const rc = currentRoot.color

  return (
    <div className="h-full flex overflow-hidden">
      {/* ── LEFT SIDEBAR ── */}
      <div className="w-60 flex-shrink-0 flex flex-col gap-2 pr-3 border-r border-gray-700/60 overflow-hidden">
        {/* Root dropdown */}
        <div ref={rootDropRef} className="relative flex-shrink-0">
          <button onClick={() => setRootDropOpen(o => !o)}
            className="w-full flex items-center gap-2 px-3 py-2 rounded-lg border border-gray-700 bg-gray-800/60 hover:bg-gray-800 transition-colors">
            <FolderOpen className={`w-4 h-4 text-${rc}-400 flex-shrink-0`} />
            <span className={`flex-1 text-sm font-semibold text-${rc}-300`}>{currentRoot.label}</span>
            <ChevronDown className={`w-3.5 h-3.5 text-gray-500 transition-transform ${rootDropOpen ? 'rotate-180' : ''}`} />
          </button>
          <AnimatePresence>
            {rootDropOpen && (
              <motion.div initial={{ opacity: 0, y: -4 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -4 }}
                className="absolute top-full left-0 right-0 mt-1 bg-gray-900 border border-gray-700 rounded-lg shadow-2xl z-50 overflow-hidden">
                {FILE_ROOTS.map(root => (
                  <button key={root.id} onClick={() => { setCurrentRoot(root); setRootDropOpen(false) }}
                    className={`w-full flex items-center gap-2.5 px-3 py-2.5 text-left hover:bg-gray-800 transition-colors ${currentRoot.id === root.id ? 'bg-gray-800/80' : ''}`}>
                    <FolderOpen className={`w-3.5 h-3.5 text-${root.color}-400 flex-shrink-0`} />
                    <span className="text-sm text-gray-200">{root.label}</span>
                    {!root.writable && <span className="ml-auto text-[9px] text-gray-600 border border-gray-700 px-1 rounded">RO</span>}
                    {currentRoot.id === root.id && <span className={`ml-auto w-1.5 h-1.5 rounded-full bg-${root.color}-400`} />}
                  </button>
                ))}
              </motion.div>
            )}
          </AnimatePresence>
        </div>

        {/* Search */}
        <div className="relative flex-shrink-0">
          <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-gray-500 pointer-events-none" />
          <input id="file-browser-search" name="file-browser-search" value={search} onChange={e => setSearch(e.target.value)} placeholder="Filter files…"
            className="w-full bg-gray-900 border border-gray-700 rounded-lg pl-8 pr-3 py-1.5 text-xs text-gray-100 placeholder-gray-500 focus:outline-none focus:border-cyan-500/50" />
        </div>

        {/* Action row */}
        <div className="flex items-center gap-1 flex-shrink-0">
          {currentRoot.writable && (
            <>
              <input ref={fileInputRef} id="file-browser-upload" name="file-browser-upload" type="file" className="hidden" onChange={handleUpload} />
              <IC onClick={() => fileInputRef.current?.click()} title="Upload file"><FolderUp className="w-3.5 h-3.5" /></IC>
              <IC onClick={() => setModal('createFile')} title="New file"><FilePlus className="w-3.5 h-3.5" /></IC>
              <IC onClick={() => setModal('createFolder')} title="New folder"><FolderPlus className="w-3.5 h-3.5" /></IC>
            </>
          )}
          <IC onClick={fetchFiles} title="Refresh"><RefreshCw className={`w-3.5 h-3.5 ${loading ? 'animate-spin' : ''}`} /></IC>

          <div ref={settingsRef} className="relative ml-auto">
            <IC onClick={() => setSettingsOpen(o => !o)} title="Settings" active={settingsOpen}>
              <Settings className="w-3.5 h-3.5" />
            </IC>
            <AnimatePresence>
              {settingsOpen && (
                <motion.div initial={{ opacity: 0, scale: 0.95, y: -4 }} animate={{ opacity: 1, scale: 1, y: 0 }} exit={{ opacity: 0, scale: 0.95, y: -4 }}
                  className="absolute right-0 top-full mt-1.5 bg-gray-900 border border-gray-700 rounded-xl shadow-2xl z-50 w-52 overflow-hidden">
                  <div className="px-3 py-2 border-b border-gray-800">
                    <span className="text-[10px] text-gray-500 uppercase tracking-wide font-semibold">Display Settings</span>
                  </div>
                  <div className="p-2 flex flex-col gap-0.5">
                    {[
                      { label: 'Show hidden files', value: showHidden, set: setShowHidden },
                      { label: 'Hide backup files', value: hideBackups, set: setHideBackups },
                    ].map(({ label, value, set }) => (
                      <label key={label} className="flex items-center gap-3 px-2 py-2.5 rounded-lg hover:bg-gray-800 cursor-pointer"
                        onClick={() => set(v => !v)}>
                        <div className={`w-4 h-4 rounded border flex items-center justify-center flex-shrink-0 ${value ? 'bg-cyan-500 border-cyan-500' : 'bg-transparent border-gray-600'}`}>
                          {value && <CheckCircle className="w-3 h-3 text-white" style={{ strokeWidth: 3 }} />}
                        </div>
                        <span className="text-xs text-gray-300">{label}</span>
                      </label>
                    ))}
                  </div>
                </motion.div>
              )}
            </AnimatePresence>
          </div>
        </div>

        {!loading && visible.length > 0 && (
          <div className="flex items-center gap-3 text-[10px] text-gray-600 px-0.5 flex-shrink-0">
            <span>{visible.length} files</span><span>·</span>
            <span>{formatFileSize(visible.reduce((s, f) => s + f.size, 0))}</span>
          </div>
        )}

        {error && (
          <div className="flex items-start gap-2 bg-red-500/10 border border-red-500/30 rounded-lg px-2.5 py-2 text-[11px] text-red-400 flex-shrink-0">
            <AlertCircle className="w-3.5 h-3.5 flex-shrink-0 mt-0.5" />{error}
          </div>
        )}

        {/* File list */}
        <div className="flex-1 overflow-auto flex flex-col gap-1 min-h-0">
          {loading ? (
            <div className="flex items-center justify-center py-10 text-gray-500">
              <Loader2 className="w-4 h-4 animate-spin mr-2" /><span className="text-xs">Loading…</span>
            </div>
          ) : visible.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-10 text-gray-600">
              <FolderOpen className="w-7 h-7 mb-1.5 opacity-30" />
              <span className="text-xs">{search ? 'No matches' : 'Empty'}</span>
            </div>
          ) : visible.map(file => {
            const isSel = selectedFile?.filename === file.filename
            return (
              <button key={file.filename} onClick={() => setSelectedFile(file)}
                className={`w-full text-left px-2.5 py-2 rounded-lg border transition-all ${isSel
                  ? `bg-${rc}-500/15 border-${rc}-500/50`
                  : 'bg-gray-800/30 border-gray-700/60 hover:bg-gray-800 hover:border-gray-600'}`}>
                <div className="flex items-center gap-2 mb-0.5">
                  {getFileIcon(file.filename, rc)}
                  <span className={`text-xs font-medium truncate flex-1 ${isSel ? `text-${rc}-300` : 'text-gray-200'}`}>{file.filename}</span>
                  {file.filename === 'printer.cfg' && <span className="text-[8px] bg-cyan-500/20 text-cyan-400 border border-cyan-500/30 px-1 rounded flex-shrink-0">MAIN</span>}
                </div>
                <div className="flex items-center gap-2 pl-5 text-[10px] text-gray-600">
                  <span>{formatFileSize(file.size)}</span><span>·</span><span>{formatDate(file.modified)}</span>
                </div>
              </button>
            )
          })}
        </div>
      </div>

      {/* ── RIGHT VIEWER ── */}
      <div className="flex-1 min-w-0 flex flex-col gap-2 pl-4 overflow-hidden">
        {!selectedFile ? (
          <div className="flex flex-col items-center justify-center h-full text-gray-600">
            <FolderOpen className="w-12 h-12 mb-3 opacity-20" />
            <p className="text-sm">Select a file to view</p>
            <p className="text-xs mt-1 opacity-60">{visible.length} files in {currentRoot.label}</p>
          </div>
        ) : (
          <>
            <div className="flex items-center gap-1.5 flex-shrink-0 flex-wrap">
              <div className="flex items-center gap-1.5 bg-gray-800/70 border border-gray-700 rounded-lg px-2.5 h-8 flex-1 min-w-[160px]">
                <Search className="w-3 h-3 text-gray-500 flex-shrink-0" />
                <input id="file-browser-line-search" name="file-browser-line-search" value={lineSearch} onChange={e => setLineSearch(e.target.value)} placeholder="Search in file…"
                  className="flex-1 bg-transparent text-xs text-gray-100 placeholder-gray-500 focus:outline-none" />
                {lineSearch && <button onClick={() => setLineSearch('')} className="text-gray-500 hover:text-gray-300"><X className="w-3 h-3" /></button>}
              </div>
              {currentRoot.isLog && (
                <>
                  <button onClick={() => setTailMode(t => !t)}
                    className={`px-2.5 h-8 text-[11px] rounded-lg border transition-colors ${tailMode ? 'bg-cyan-500/15 border-cyan-500/40 text-cyan-400' : 'bg-gray-800 border-gray-700 text-gray-400 hover:text-gray-200'}`}>
                    {tailMode ? 'Tail' : 'Full'}
                  </button>
                  <button onClick={() => setAutoScroll(a => !a)}
                    className={`flex items-center gap-1 px-2.5 h-8 text-[11px] rounded-lg border transition-colors ${autoScroll ? 'bg-cyan-500/15 border-cyan-500/40 text-cyan-400' : 'bg-gray-800 border-gray-700 text-gray-400'}`}>
                    <ArrowDown className="w-3 h-3" />Auto-scroll
                  </button>
                </>
              )}
              <button onClick={() => setWordWrap(w => !w)}
                className={`flex items-center gap-1 px-2.5 h-8 text-[11px] rounded-lg border transition-colors ${wordWrap ? 'bg-cyan-500/15 border-cyan-500/40 text-cyan-400' : 'bg-gray-800 border-gray-700 text-gray-400'}`}>
                <WrapText className="w-3 h-3" />Wrap
              </button>
              <button onClick={() => fetchContent(selectedFile)} disabled={contentLoading}
                className="flex items-center gap-1 px-2.5 h-8 text-[11px] text-gray-400 border border-gray-700 rounded-lg hover:bg-gray-800 disabled:opacity-50">
                <RefreshCw className={`w-3 h-3 ${contentLoading ? 'animate-spin' : ''}`} />Reload
              </button>
              {currentRoot.writable ? (
                <button onClick={() => setModal('editor')}
                  className="flex items-center gap-1 px-2.5 h-8 text-[11px] text-cyan-400 bg-cyan-500/10 border border-cyan-500/30 rounded-lg hover:bg-cyan-500/20">
                  <Edit3 className="w-3 h-3" />Edit
                </button>
              ) : (
                <button onClick={() => setModal('editor')}
                  className="flex items-center gap-1 px-2.5 h-8 text-[11px] text-gray-400 border border-gray-700 rounded-lg hover:bg-gray-800">
                  <Eye className="w-3 h-3" />View
                </button>
              )}
              {currentRoot.writable && selectedFile.filename !== 'printer.cfg' && (
                <button onClick={() => { setDeleteTarget(selectedFile.filename); setModal('delete') }}
                  className="flex items-center gap-1 px-2.5 h-8 text-[11px] text-red-400 bg-red-500/10 border border-red-500/30 rounded-lg hover:bg-red-500/20">
                  <Trash2 className="w-3 h-3" />
                </button>
              )}
            </div>

            <div className="flex items-center gap-2 text-[11px] text-gray-500 flex-shrink-0 flex-wrap">
              {getFileIcon(selectedFile.filename, rc)}
              <span className="font-medium text-gray-300">{selectedFile.filename}</span>
              <span>·</span><span>{formatFileSize(selectedFile.size)}</span>
              <span>·</span><span>{formatDate(selectedFile.modified)}</span>
              {content && <>
                <span>·</span><span>{content.split('\n').length} lines</span>
                {lineSearch && <><span>·</span><span className="text-cyan-400">{filteredLines().split('\n').filter(Boolean).length} matches</span></>}
                {currentRoot.isLog && tailMode && <><span>·</span><span className="text-yellow-500/70">last 200KB</span></>}
              </>}
            </div>

            <div ref={logRef} className="flex-1 min-h-0 overflow-auto bg-gray-950 border border-gray-700/80 rounded-xl">
              {contentLoading ? (
                <div className="flex items-center justify-center h-full text-gray-500">
                  <Loader2 className="w-5 h-5 animate-spin mr-2" />Loading {selectedFile.filename}…
                </div>
              ) : content ? (
                <pre className={`text-[11px] font-mono text-gray-300 p-4 leading-relaxed min-h-full ${wordWrap ? 'whitespace-pre-wrap break-all' : 'whitespace-pre'}`}>
                  {lineSearch
                    ? filteredLines().split('\n').map((line, i, arr) => {
                        const lo = line.toLowerCase(), q = lineSearch.toLowerCase()
                        const idx = lo.indexOf(q)
                        if (idx === -1) return <span key={i}>{line}{i < arr.length - 1 ? '\n' : ''}</span>
                        return (
                          <span key={i}>
                            {line.slice(0, idx)}
                            <mark className="bg-yellow-400/30 text-yellow-200 rounded-sm">{line.slice(idx, idx + lineSearch.length)}</mark>
                            {line.slice(idx + lineSearch.length)}
                            {i < arr.length - 1 ? '\n' : ''}
                          </span>
                        )
                      })
                    : content}
                </pre>
              ) : (
                <div className="flex items-center justify-center h-full text-gray-600 text-sm">Empty file</div>
              )}
            </div>
          </>
        )}
      </div>

      {/* Modals */}
      {modal === 'editor' && selectedFile && (
        <EditorModal printerId={printer.id} filename={selectedFile.filename} root={currentRoot.id}
          readOnly={!currentRoot.writable}
          onClose={() => setModal(null)}
          onSaved={() => { setModal(null); fetchContent(selectedFile) }}
          toast={toast} />
      )}
      {modal === 'createFile' && (
        <InputModal title="New File" label="File name" placeholder="e.g. macros.cfg" confirmLabel="Create"
          icon={<FilePlus className="w-4 h-4" />} onConfirm={handleCreateFile} onClose={() => setModal(null)} />
      )}
      {modal === 'createFolder' && (
        <InputModal title="New Folder" label="Folder name" placeholder="e.g. includes" confirmLabel="Create"
          icon={<FolderPlus className="w-4 h-4" />} onConfirm={handleCreateFolder} onClose={() => setModal(null)} />
      )}
      {modal === 'delete' && deleteTarget && (
        <ConfirmDeleteModal filename={deleteTarget} onConfirm={handleDelete}
          onClose={() => { setModal(null); setDeleteTarget(null) }} />
      )}
    </div>
  )
}
