import type { KnowledgeEntry, MatchResult } from './types'

// ── Imports ──────────────────────────────────────────────────
import printerZOffset        from './knowledge/printer/z-offset'
import printerPidTuning      from './knowledge/printer/pid-tuning'
import printerPressureAdvance from './knowledge/printer/pressure-advance'
import printerInputShaper    from './knowledge/printer/input-shaper'
import printerBedMesh        from './knowledge/printer/bed-mesh'
import printerMacros         from './knowledge/printer/macros'
import printerWebcam         from './knowledge/printer/webcam'

import filamentChange        from './knowledge/filament/filament-change'
import filamentStringing     from './knowledge/filament/stringing'

import errorsConnection      from './knowledge/errors/connection'
import errorsKlipper         from './knowledge/errors/klipper-errors'

import dashboardSettings     from './knowledge/dashboard/settings'

import printMonitoring       from './knowledge/print/monitoring'

import backupBackup          from './knowledge/backup/backup'

import gettingStartedAbout   from './knowledge/getting-started/about'

// ── Combine all entries ───────────────────────────────────────
export const knowledgeBase: KnowledgeEntry[] = [
  ...gettingStartedAbout,
  ...printerZOffset,
  ...printerPidTuning,
  ...printerPressureAdvance,
  ...printerInputShaper,
  ...printerBedMesh,
  ...printerMacros,
  ...printerWebcam,
  ...filamentChange,
  ...filamentStringing,
  ...errorsConnection,
  ...errorsKlipper,
  ...dashboardSettings,
  ...printMonitoring,
  ...backupBackup,
]

// ── Stop words (ignored during matching) ─────────────────────
const STOP_WORDS = new Set([
  'a', 'an', 'the', 'is', 'it', 'in', 'on', 'at', 'to', 'do', 'i',
  'my', 'me', 'we', 'how', 'why', 'what', 'when', 'where', 'can',
  'does', 'did', 'will', 'are', 'was', 'be', 'of', 'and', 'or',
  'for', 'with', 'not', 'get', 'this', 'that', 'from', 'have', 'has',
])

function tokenize(text: string): string[] {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9āčēģīķļņšūž\s-]/g, ' ')
    .split(/\s+/)
    .filter((w) => w.length > 1 && !STOP_WORDS.has(w))
}

/**
 * Returns the best matching knowledge entry for a query,
 * or null if nothing scores above the confidence threshold.
 */
export function findLocalAnswer(query: string, threshold = 0.25): MatchResult | null {
  const tokens = tokenize(query)
  if (tokens.length === 0) return null

  let best: MatchResult | null = null

  for (const entry of knowledgeBase) {
    let score = 0

    for (const token of tokens) {
      for (const kw of entry.keywords) {
        if (kw === token) {
          score += 2           // exact keyword match
        } else if (kw.includes(token) || token.includes(kw)) {
          score += 1           // partial match
        }
      }
    }

    // Normalise by token count so short queries don't get an unfair boost
    const normalised = score / tokens.length

    if (normalised > (best?.score ?? 0)) {
      best = { entry, score: normalised }
    }
  }

  return best && best.score >= threshold ? best : null
}
