// ═══════════════════════════════════════════════════════════════
// PRESTIGE — PRINTER DETAIL PAGE (shell only)
// All heavy panels live in @features/printer-detail/
//   TemperaturePanel, FanControlPanel, KlipperStatusPanel
//   PrinterAIPanel, MovementsPanel, AIMaintStatusPanel
//   PrinterInfoPanel, PrintProgressPanel, ControlPanel
// ═══════════════════════════════════════════════════════════════

import { useState, useEffect } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import {
  ArrowLeft, Box, Layers, FolderOpen, Clock,
  AlertTriangle, Settings, Activity, Wifi, WifiOff,
  Send, RefreshCw, Wind, Move, History,
} from 'lucide-react'
import { usePrinterStore } from '@core/state/printerStore'
import { useShallow } from 'zustand/react/shallow'
import { printerApi } from '@services/printer-api'
import { DeletePrinterButton } from '@core/components/DeletePrinterDialog'
import { BedMeshView } from '@features/bed-mesh/BedMeshView'
import { FileBrowserPanel } from '@features/file-browser'
import { GCodeViewer } from '@features/gcode-viewer/GCodeViewer'
import { GCodeConsole } from '@features/gcode-console'
import { ManualChangeForm } from '@features/maintenance/ManualChangeForm'
import { HistoryList } from '@features/history/HistoryList'
import { useToast } from '@core/hooks/useToast'
import { PageToasts } from '@core/components/PageToasts'
import { parseConnectionHost } from '@core/types/printer'
import {
  AIMaintStatusPanel,
  PrinterInfoPanel,
  PrintProgressPanel,
  ControlPanel,
  TemperaturePanel,
  FanControlPanel,
  KlipperStatusPanel,
  PrinterAIPanel,
  MovementsPanel,
} from '@features/printer-detail'

// ─── Tab definitions ──────────────────────────────────────────
type DetailTab = 'overview' | 'bed-mesh' | 'gcode' | 'gcode3d' | 'maintenance' | 'history' | 'fans' | 'movements' | 'files'

const DETAIL_TABS: { id: DetailTab; label: string; icon: React.ElementType }[] = [
  { id: 'overview',    label: 'Overview',    icon: Activity },
  { id: 'bed-mesh',    label: 'Bed Mesh',    icon: Layers },
  { id: 'gcode',       label: 'G-Code',      icon: Send },
  { id: 'gcode3d',     label: '3D View',     icon: Box },
  { id: 'fans',        label: 'Fans',        icon: Wind },
  { id: 'movements',   label: 'Movements',   icon: Move },
  { id: 'maintenance', label: 'Maintenance', icon: Settings },
  { id: 'history',     label: 'History',     icon: Clock },
  { id: 'files',       label: 'Files',       icon: FolderOpen },
]

const STATUS_COLORS: Record<string, string> = {
  idle:         'text-green-400 bg-green-500/10 border-green-500/30',
  printing:     'text-blue-400 bg-blue-500/10 border-blue-500/30',
  paused:       'text-yellow-400 bg-yellow-500/10 border-yellow-500/30',
  error:        'text-red-400 bg-red-500/10 border-red-500/30',
  disconnected: 'text-gray-400 bg-gray-500/10 border-gray-500/30',
  maintenance:  'text-orange-400 bg-orange-500/10 border-orange-500/30',
  ai_action:    'text-violet-400 bg-violet-500/10 border-violet-500/30',
}

function MaintTab({ printer }: { printer: any }) {
  const [refreshKey, setRefreshKey] = useState(0)
  return (
    <div className="flex-1 min-h-0 overflow-auto space-y-4">
      <AIMaintStatusPanel printerId={printer.id} refreshKey={refreshKey} />
      <div className="bg-gray-900/50 border border-gray-700 rounded-lg p-4">
        <div className="flex items-center gap-2 mb-3">
          <Settings className="w-4 h-4 text-cyan-400" />
          <h3 className="text-sm font-semibold text-gray-200">Register Maintenance</h3>
        </div>
        <ManualChangeForm
          printerId={printer.id}
          printerName={printer.name}
          onSuccess={() => setRefreshKey(k => k + 1)}
        />
      </div>
    </div>
  )
}

// ═══════════════════════════════════════════════════════════════
// MAIN PAGE
// ═══════════════════════════════════════════════════════════════
export default function PrinterDetailPage() {
  const { id } = useParams<{ id: string }>()
  const navigate = useNavigate()
  const [activeTab, setActiveTab] = useState<DetailTab>('overview')
  const { toasts, add: toast } = useToast()

  const printer = usePrinterStore(useShallow(state => id ? state.printers[id] : undefined))
  const [loadingPrinter, setLoadingPrinter] = useState(!printer)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    if (printer || !id) { setLoadingPrinter(false); return }
    printerApi.getById(id)
      .then(data => { usePrinterStore.getState().addPrinter(data); setLoadingPrinter(false) })
      .catch(err => { setError(err instanceof Error ? err.message : 'Failed to load printer'); setLoadingPrinter(false) })
  }, [id, printer])

  if (loadingPrinter) return (
    <div className="flex items-center justify-center h-full">
      <RefreshCw className="w-8 h-8 text-cyan-400 animate-spin mr-3" />
      <p className="text-sm text-gray-400">Loading printer...</p>
    </div>
  )

  if (error || !printer) return (
    <div className="flex items-center justify-center h-full">
      <div className="text-center max-w-md">
        <AlertTriangle className="w-12 h-12 text-red-400 mx-auto mb-3" />
        <h2 className="text-lg font-bold text-gray-200 mb-2">Printer Not Found</h2>
        <p className="text-sm text-gray-400 mb-4">{error || 'The requested printer could not be found.'}</p>
        <button onClick={() => navigate('/printers')}
          className="inline-flex items-center gap-2 px-4 py-2 text-sm bg-cyan-500/20 text-cyan-400 border border-cyan-500/50 rounded-lg hover:bg-cyan-500/30">
          <ArrowLeft className="w-4 h-4" />Back to Printers
        </button>
      </div>
    </div>
  )

  return (
    <div className="flex flex-col h-full gap-1 p-1">
      {/* Header */}
      <div className="flex items-center justify-between flex-shrink-0">
        <div className="flex items-center gap-2">
          <button onClick={() => navigate('/printers')} className="p-1.5 text-gray-400 hover:text-gray-200 hover:bg-gray-800 rounded">
            <ArrowLeft className="w-4 h-4" />
          </button>
          <div>
            <h1 className="text-base font-display font-bold text-gray-100">{printer.name}</h1>
            <div className="flex items-center gap-2 mt-0.5">
              <span className={`inline-flex items-center gap-1 px-2 py-0.5 text-xs font-medium rounded-full border ${STATUS_COLORS[printer.status] ?? STATUS_COLORS.idle}`}>
                {printer.status === 'printing' && <Activity className="w-3 h-3" />}
                {printer.status.charAt(0).toUpperCase() + printer.status.slice(1)}
              </span>
              <span className="text-xs text-gray-500">{printer.adapterType}</span>
              <span className="flex items-center gap-1 text-xs text-gray-500">
                {printer.connectionUrl
                  ? <><Wifi className="w-3 h-3 text-green-400" /> {parseConnectionHost(printer.connectionUrl)}</>
                  : <><WifiOff className="w-3 h-3 text-gray-500" /> No connection</>}
              </span>
            </div>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <DeletePrinterButton printerId={printer.id} printerName={printer.name} navigateAfter variant="icon" />
          <button onClick={() => navigate('/settings')} className="p-1.5 text-gray-400 hover:text-gray-200 hover:bg-gray-800 rounded">
            <Settings className="w-4 h-4" />
          </button>
        </div>
      </div>

      {/* Tab Bar */}
      <div className="flex gap-0.5 p-0 bg-surface rounded border border-border overflow-x-auto flex-shrink-0">
        {DETAIL_TABS.map(tab => {
          const TabIcon = tab.icon
          return (
            <button key={tab.id} onClick={() => setActiveTab(tab.id)}
              className={`flex items-center gap-1 px-2 py-0.5 rounded text-xs font-medium whitespace-nowrap transition-all ${activeTab === tab.id ? 'bg-primary/10 text-primary' : 'text-text-muted hover:text-text'}`}>
              <TabIcon className="w-3 h-3" />{tab.label}
            </button>
          )
        })}
      </div>

      {/* Tab Content */}
      {activeTab === 'overview' && (
        <div className="flex-1 min-h-0 overflow-auto">
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-4">
            <div className="lg:col-span-7 space-y-4">
              <TemperaturePanel printer={printer} />
              <PrintProgressPanel printer={printer} />
            </div>
            <div className="lg:col-span-5 space-y-4">
              <KlipperStatusPanel printer={printer} />
              <PrinterInfoPanel printer={printer} />
              <ControlPanel printer={printer} />
              <PrinterAIPanel printer={printer} />
            </div>
          </div>
        </div>
      )}
      {activeTab === 'fans' && <div className="flex-1 min-h-0 overflow-auto"><FanControlPanel printer={printer} /></div>}
      {activeTab === 'bed-mesh' && <div className="flex-1 min-h-0 overflow-auto"><BedMeshView printerId={printer.id} printerName={printer.name} /></div>}
      {activeTab === 'gcode' && <div className="flex-1 min-h-0 overflow-auto"><GCodeConsole printerId={printer.id} /></div>}
      {activeTab === 'maintenance' && <MaintTab printer={printer} />}
      {activeTab === 'gcode3d' && <div className="flex-1 min-h-0 overflow-hidden"><GCodeViewer printerId={printer.id} /></div>}
      {activeTab === 'movements' && <div className="flex-1 min-h-0 overflow-auto"><MovementsPanel printer={printer} /></div>}
      {activeTab === 'history' && <div className="flex-1 min-h-0 overflow-auto"><HistoryList printerId={printer.id} /></div>}
      {activeTab === 'files' && (
        <div className="flex-1 min-h-0 overflow-hidden">
          <FileBrowserPanel key={printer.id} printer={printer as any} toast={(type, msg) => toast(msg, type)} />
        </div>
      )}

      <PageToasts toasts={toasts} />
    </div>
  )
}
