// PRESTIGE — AI PANEL SHARED TYPES
// Single source of truth for types used across AI tab components
// ═══════════════════════════════════════════════════════════════

export interface BackendAIStatus {
  enabled: boolean; healthy: boolean; lastAnalysisAt: string | null
  activePrinters: number; pendingRecommendations: number; activeAnomalies: number
  uptime: number; memoryUsage: number
}

export interface SuggestedAction {
  id: string; action: string; description: string
  automated: boolean; requiresConfirmation: boolean
  gcode: string | null; estimatedDuration: number | null
}

export interface Recommendation {
  id: string; printerId: string; jobId: string | null
  type: string; priority: 'low' | 'medium' | 'high' | 'urgent'
  title: string; description: string; reasoning: string
  suggestedActions: SuggestedAction[]
  confidence: number; source: string
  acknowledged: boolean; acknowledgedAt: string | null
  dismissed: boolean; dismissedAt: string | null; dismissReason: string | null
  createdAt: string; expiresAt: string | null
}

export interface BackendAnomaly {
  id: string; printerId: string; type: string
  severity: 'low' | 'medium' | 'high' | 'critical'
  confidence: number; description: string; metric: string
  expectedValue: number; actualValue: number; deviation: number
  detectedAt: string; resolvedAt: string | null
}

export interface RiskFactor {
  name: string; riskContribution: number
  currentValue: number | string; threshold: number | string
  status: 'ok' | 'warning' | 'danger'; description: string
}

export interface FailurePrediction {
  type: string; probability: number; confidence: number
  riskLevel: 'minimal' | 'low' | 'moderate' | 'high' | 'critical'
  description: string; factors: RiskFactor[]
  mitigationActions: string[]; estimatedTimeToFailure: number | null
}

export interface FailurePredictionResult {
  printerId: string; jobId: string | null; analyzedPoints: number
  overallRisk: 'minimal' | 'low' | 'moderate' | 'high' | 'critical'
  overallProbability: number; predictions: FailurePrediction[]
  riskFactors: RiskFactor[]; shouldPause: boolean; shouldAbort: boolean
  warnings: string[]; analyzedAt: string
}

export interface AnalysisResult {
  printerId: string; timestamp: string; telemetryPoints: number
  anomalyCount: number; healthScore: number; qualityScore: number
  qualityGrade: string; recommendationCount: number; failureRisk: number
  clogRisk?: number
  wearSeverity?: 'ok' | 'watch' | 'warning' | 'critical'
  motorLoadSeverity?: 'ok' | 'watch' | 'warning' | 'critical'
}

export interface DiagnosticTestResult {
  testId: string
  testType: string
  status: 'pass' | 'warning' | 'fail' | 'running'
  score: number
  globalAvg?: number
  details: string
  metrics: { label: string; value: string; status: 'ok' | 'warn' | 'bad' }[]
  ranAt: string
  durationMs: number
  source?: 'live_gcode' | 'live_telemetry' | 'estimated' | 'live' | 'running'
}

export interface GlobalBenchmark {
  fleetSize: number
  avgHealthScore: number
  avgQualityScore: number
  avgFailureRisk: number
  avgClogRisk: number
  percentileRank: number
  betterThan: number
  /** Backend signals that there is not enough data to compute a reliable benchmark */
  insufficientData?: boolean
  reason?: 'no_telemetry' | 'no_diagnostic_run'
}

// ── Shared helper ────────────────────────────────────────────
export async function apiFetch<T>(url: string, options?: RequestInit): Promise<T | null> {
  try {
    const res = await fetch(url, options)
    if (!res.ok) return null
    const data = await res.json()
    return (data?.data ?? data) as T
  } catch { return null }
}

