import React, { useMemo, useState, useRef, useEffect, useCallback } from 'react'
import type { Printer, PrinterStatus } from '../../types/printer'
import type {
  PrinterGridProps,
  ViewModeConfig,
  GridColumns,
  FilterOption,
  SortOption,
} from './PrinterGrid.types'
import { VIEW_MODES } from './PrinterGrid.types'
import { PrinterCardMemo } from '../PrinterCard'

// ─── Progressive-load constants ─────────────────────────────────────────────
/** How many cards to show on first render (one screenful at ~4 cols). */
const INITIAL_PAGE_SIZE = 24
/** Cards to add each time the scroll sentinel becomes visible. */
const PAGE_INCREMENT    = 24
/**
 * Threshold at which we switch from "render everything" to progressive mode.
 * Below this number all cards render normally; above it we lazy-load.
 */
const VIRTUAL_THRESHOLD = 20

/**
 * useProgressiveLoad — returns the slice of items currently visible
 * plus an IntersectionObserver sentinel ref.
 *
 * When the grid has <= VIRTUAL_THRESHOLD items it returns the full array.
 * Above that threshold it starts with INITIAL_PAGE_SIZE items and expands
 * by PAGE_INCREMENT every time the sentinel scrolls into view.
 */
function useProgressiveLoad<T>(items: T[]) {
  const [visibleCount, setVisibleCount] = useState(INITIAL_PAGE_SIZE)
  const sentinelRef = useRef<HTMLDivElement | null>(null)

  // Reset when the list changes (search / filter)
  useEffect(() => {
    setVisibleCount(INITIAL_PAGE_SIZE)
  }, [items.length])

  const loadMore = useCallback(() => {
    setVisibleCount((prev) => Math.min(prev + PAGE_INCREMENT, items.length))
  }, [items.length])

  useEffect(() => {
    if (items.length <= VIRTUAL_THRESHOLD) return
    const el = sentinelRef.current
    if (!el) return
    const observer = new IntersectionObserver(
      (entries) => { if (entries[0]?.isIntersecting) loadMore() },
      { rootMargin: '200px' },
    )
    observer.observe(el)
    return () => observer.disconnect()
  }, [items.length, loadMore])

  const visibleItems = items.length <= VIRTUAL_THRESHOLD ? items : items.slice(0, visibleCount)
  const hasMore      = items.length > VIRTUAL_THRESHOLD && visibleCount < items.length

  return { visibleItems, hasMore, sentinelRef }
}

/**
 * Get grid columns CSS class
 */
const getGridColumnsClass = (columns: GridColumns): string => {
  if (columns === 'auto') {
    return 'grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4'
  }
  const colMap: Record<number, string> = {
    1: 'grid-cols-1',
    2: 'grid-cols-1 lg:grid-cols-2',
    3: 'grid-cols-1 md:grid-cols-2 lg:grid-cols-3',
    4: 'grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4',
  }
  return colMap[columns as number] || colMap[3]
}

/**
 * Filter printers based on filters
 */
const filterPrinters = (printers: Printer[], filters: PrinterGridProps['filters'], searchQuery: string): Printer[] => {
  // Safety check: ensure printers is an array
  if (!Array.isArray(printers)) {
    return []
  }
  
  let filtered = [...printers]

  // Search filter
  if (searchQuery) {
    const query = searchQuery.toLowerCase()
    filtered = filtered.filter(
      (p) =>
        p.name.toLowerCase().includes(query) ||
        p.adapterType.toLowerCase().includes(query) ||
        (p.printerModel ?? '').toLowerCase().includes(query) ||
        p.id.toLowerCase().includes(query)
    )
  }

  // Status filter
  if (filters?.status && filters.status.length > 0) {
    filtered = filtered.filter((p) => filters.status!.includes(p.status))
  }

  // Type filter (matches adapterType now)
  if (filters?.type && filters.type.length > 0) {
    filtered = filtered.filter((p) => filters.type!.includes(p.adapterType))
  }

  // Tags filter
  if (filters?.tags && filters.tags.length > 0) {
    filtered = filtered.filter((p) =>
      filters.tags!.some((tag) => p.tags?.includes(tag))
    )
  }

  return filtered
}

/**
 * Sort printers
 */
const sortPrinters = (printers: Printer[], sort?: PrinterGridProps['sort']): Printer[] => {
  if (!sort || !Array.isArray(printers)) return printers

  const sorted = [...printers]

  sorted.sort((a, b) => {
    let compareResult = 0

    switch (sort.field) {
      case 'name':
        compareResult = a.name.localeCompare(b.name)
        break
      case 'status':
        compareResult = a.status.localeCompare(b.status)
        break
      case 'type':
        compareResult = a.adapterType.localeCompare(b.adapterType)
        break
      case 'lastSeenAt':
        compareResult = new Date(a.lastSeenAt || 0).getTime() - new Date(b.lastSeenAt || 0).getTime()
        break
      case 'qualityScore':
        compareResult = (a.qualityScore || 0) - (b.qualityScore || 0)
        break
      default:
        compareResult = 0
    }

    return sort.direction === 'asc' ? compareResult : -compareResult
  })

  return sorted
}

/**
 * Get status filter options
 */
const getStatusFilterOptions = (printers: Printer[]): FilterOption[] => {
  if (!Array.isArray(printers)) {
    return []
  }
  
  const statusCounts = printers.reduce((acc, printer) => {
    acc[printer.status] = (acc[printer.status] || 0) + 1
    return acc
  }, {} as Record<PrinterStatus, number>)

  const statuses: PrinterStatus[] = ['idle', 'printing', 'paused', 'error', 'disconnected', 'maintenance', 'ai_action']

  return statuses.map((status) => ({
    label: status.charAt(0).toUpperCase() + status.slice(1).replace('_', ' '),
    value: status,
    count: statusCounts[status] || 0,
  }))
}

/**
 * PrinterGrid Component
 * Container for displaying multiple printer cards with filtering and sorting
 * 
 * ENHANCED: Now passes all enhanced props to PrinterCard
 */
export const PrinterGrid: React.FC<PrinterGridProps> = ({
  printers = [],
  viewMode = VIEW_MODES.grid_standard,
  filters,
  sort,
  actions,
  loading = false,
  emptyMessage = 'No printers found',
  showFilters = false,
  showSort = false,
  showSearch = true,
  onFiltersChange,
  onSortChange,
  className = '',
}) => {
  const [searchQuery, setSearchQuery] = useState('')
  const [activeFilters, setActiveFilters] = useState<string[]>([])

  // Process printers
  const processedPrinters = useMemo(() => {
    let result = printers || []
    result = filterPrinters(result, filters, searchQuery)
    result = sortPrinters(result, sort)
    return result
  }, [printers, filters, searchQuery, sort])

  // Status filter options
  const statusOptions = useMemo(() => getStatusFilterOptions(printers || []), [printers])

  // Phase 4: Progressive load for 20+ printers
  const { visibleItems: visiblePrinters, hasMore, sentinelRef } = useProgressiveLoad(processedPrinters)

  // Sort options
  const sortOptions: SortOption[] = [
    { label: 'Name', value: 'name', direction: 'asc', icon: '🔤', active: sort?.field === 'name' },
    { label: 'Status', value: 'status', direction: 'asc', icon: '📊', active: sort?.field === 'status' },
    { label: 'Quality', value: 'qualityScore', direction: 'desc', icon: '⭐', active: sort?.field === 'qualityScore' },
    { label: 'Recent', value: 'lastSeenAt', direction: 'desc', icon: '🕐', active: sort?.field === 'lastSeenAt' },
  ]

  // Handle filter toggle
  const handleFilterToggle = (statusValue: string) => {
    const newFilters = activeFilters.includes(statusValue)
      ? activeFilters.filter((f) => f !== statusValue)
      : [...activeFilters, statusValue]

    setActiveFilters(newFilters)

    if (onFiltersChange) {
      onFiltersChange({
        ...filters,
        status: newFilters as PrinterStatus[],
      })
    }
  }

  // Handle sort change
  const handleSortChange = (option: SortOption) => {
    if (onSortChange) {
      onSortChange({
        field: option.value as any,
        direction: option.direction,
      })
    }
  }

  // Grid columns class
  const gridClass = getGridColumnsClass(viewMode.columns)

  // Loading state
  if (loading) {
    const skeletonCount = typeof viewMode.columns === 'number' ? viewMode.columns : 3
    return (
      <div className={`grid ${gridClass} gap-4 ${className}`}>
        {Array.from({ length: skeletonCount }).map((_, i) => (
          <div key={i} className="bg-gray-900/50 border border-gray-800 rounded-xl p-4 flex flex-col gap-3 animate-pulse">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-gray-800 rounded-lg" />
              <div className="h-4 bg-gray-800 rounded flex-1 max-w-[60%]" />
            </div>
            <div className="h-2 bg-gray-800 rounded w-full" />
            <div className="h-2 bg-gray-800 rounded w-3/4" />
          </div>
        ))}
      </div>
    )
  }

  return (
    <div className={`flex flex-col gap-4 ${className}`}>
      {/* Toolbar */}
      {(showSearch || showFilters || showSort) && (
        <div className="flex flex-col gap-3 p-4 rounded-lg bg-gray-900/50 border border-gray-800">
          {/* Search */}
          {showSearch && (
            <div className="relative">
              <input
                id="printer-grid-search"
                name="printer-grid-search"
                type="text"
                placeholder="Search printers..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full px-4 py-2 pl-10 bg-gray-800 border border-gray-700 rounded-lg text-gray-200 placeholder-gray-500 focus:outline-none focus:border-cyan-500 focus:ring-1 focus:ring-cyan-500 transition-all"
              />
              <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-500">
                🔍
              </span>
              {searchQuery && (
                <button
                  onClick={() => setSearchQuery('')}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-500 hover:text-gray-300 transition-colors"
                >
                  ✕
                </button>
              )}
            </div>
          )}

          {/* Filters and Sort */}
          <div className="flex flex-wrap items-center gap-3">
            {/* Status Filters */}
            {showFilters && (
              <div className="flex items-center gap-2 flex-wrap">
                <span className="text-sm text-gray-400">Status:</span>
                {statusOptions.map((option) => (
                  <button
                    key={option.value}
                    onClick={() => handleFilterToggle(option.value)}
                    className={`px-3 py-1 rounded-full text-xs font-medium transition-all ${
                      activeFilters.includes(option.value)
                        ? 'bg-cyan-500/20 border border-cyan-500/50 text-cyan-400'
                        : 'bg-gray-800 border border-gray-700 text-gray-400 hover:border-gray-600'
                    }`}
                  >
                    {option.label} {option.count > 0 && `(${option.count})`}
                  </button>
                ))}
              </div>
            )}

            {/* Sort Options */}
            {showSort && (
              <div className="flex items-center gap-2 flex-wrap ml-auto">
                <span className="text-sm text-gray-400">Sort:</span>
                {sortOptions.map((option) => (
                  <button
                    key={option.value}
                    onClick={() => handleSortChange(option)}
                    className={`flex items-center gap-1 px-3 py-1 rounded-full text-xs font-medium transition-all ${
                      option.active
                        ? 'bg-cyan-500/20 border border-cyan-500/50 text-cyan-400'
                        : 'bg-gray-800 border border-gray-700 text-gray-400 hover:border-gray-600'
                    }`}
                  >
                    <span>{option.icon}</span>
                    <span>{option.label}</span>
                  </button>
                ))}
              </div>
            )}
          </div>
        </div>
      )}

      {/* Results count */}
      <div className="flex items-center justify-between px-2">
        <span className="text-sm text-gray-400">
          {processedPrinters.length} {processedPrinters.length === 1 ? 'printer' : 'printers'}
          {searchQuery && ` matching "${searchQuery}"`}
        </span>
        {(printers || []).length !== processedPrinters.length && (
          <button
            onClick={() => {
              setSearchQuery('')
              setActiveFilters([])
              if (onFiltersChange) {
                onFiltersChange({})
              }
            }}
            className="text-xs text-cyan-400 hover:text-cyan-300 transition-colors"
          >
            Clear filters
          </button>
        )}
      </div>

      {/* Grid */}
      {processedPrinters.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-16 text-gray-500">
          <span className="text-4xl mb-3">🔍</span>
          <p className="text-sm font-medium text-gray-400">
            {searchQuery ? `No printers matching "${searchQuery}"` : emptyMessage}
          </p>
          {(searchQuery || activeFilters.length > 0) && (
            <button
              onClick={() => {
                setSearchQuery('')
                setActiveFilters([])
                if (onFiltersChange) onFiltersChange({})
              }}
              className="mt-3 text-xs text-cyan-400 hover:text-cyan-300 transition-colors"
            >
              Clear filters
            </button>
          )}
        </div>
      ) : (
        <>
          <div className={`grid ${gridClass} gap-4 p-2`}>
            {visiblePrinters.map((printer) => (
              <PrinterCardMemo
                key={printer.id}
                printer={printer}
                size={viewMode.cardSize}
                layout={viewMode.cardLayout}
                actions={actions}
                showTemperatures={true}
                showProgress={true}
                showQualityScore={true}
                showActions={true}
              />
            ))}
          </div>

          {/* Phase 4: scroll sentinel — triggers next page when it enters the viewport */}
          {hasMore && (
            <div ref={sentinelRef} className="flex items-center justify-center py-6 text-gray-500">
              <div className="flex items-center gap-2 text-sm">
                <svg className="animate-spin w-4 h-4 text-cyan-500" viewBox="0 0 24 24" fill="none">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z" />
                </svg>
                <span>Loading {Math.min(PAGE_INCREMENT, processedPrinters.length - visiblePrinters.length)} more…</span>
              </div>
            </div>
          )}

          {/* Show total count when all cards are rendered */}
          {!hasMore && processedPrinters.length > VIRTUAL_THRESHOLD && (
            <p className="text-center text-xs text-gray-600 pb-2">
              Showing all {processedPrinters.length} printers
            </p>
          )}
        </>
      )}
    </div>
  )
}

PrinterGrid.displayName = 'PrinterGrid'

export default PrinterGrid
