import { useState } from 'react'
import { ChevronDown, ChevronUp } from 'lucide-react'
import type { FAQ } from './faqData'

export function FAQItem({ faq }: { faq: FAQ }) {
  const [open, setOpen] = useState(false)

  return (
    <div className={`border rounded-xl overflow-hidden transition-colors ${
      open ? 'border-cyan-500/40 bg-gray-900' : 'border-gray-800 bg-gray-900'
    }`}>
      <button
        onClick={() => setOpen((p) => !p)}
        className="w-full flex items-center justify-between px-4 py-3.5 text-left hover:bg-gray-800/60 transition-colors group"
      >
        <span className="text-sm font-medium text-white group-hover:text-cyan-400 transition-colors pr-4">
          {faq.question}
        </span>
        {open
          ? <ChevronUp size={16} className="text-cyan-400 shrink-0" />
          : <ChevronDown size={16} className="text-gray-500 shrink-0" />
        }
      </button>

      {open && (
        <div className="px-4 pb-4 border-t border-gray-800/60 bg-gray-800/20 space-y-4">
          <p className="pt-4 text-sm text-gray-300 leading-relaxed">{faq.answer}</p>

          {faq.steps && faq.steps.length > 0 && (
            <div className="space-y-2">
              <p className="text-xs font-semibold text-gray-500 uppercase tracking-widest">Steps</p>
              <ol className="space-y-2">
                {faq.steps.map((step, i) => (
                  <li key={i} className="flex items-start gap-3">
                    <span className="shrink-0 w-5 h-5 rounded-full bg-cyan-500/20 text-cyan-400 text-[10px] font-bold flex items-center justify-center mt-0.5">
                      {i + 1}
                    </span>
                    <span className="text-sm text-gray-300 leading-relaxed font-mono text-xs bg-gray-800 rounded-lg px-2.5 py-1.5 w-full">
                      {step}
                    </span>
                  </li>
                ))}
              </ol>
            </div>
          )}

          {faq.tip && (
            <div className="flex items-start gap-2.5 p-3 bg-cyan-500/5 border border-cyan-500/20 rounded-lg">
              <span className="text-cyan-400 text-xs font-bold uppercase tracking-widest shrink-0 mt-0.5">Tip</span>
              <p className="text-xs text-cyan-300/80 leading-relaxed">{faq.tip}</p>
            </div>
          )}
        </div>
      )}
    </div>
  )
}
