/**
 * API configuration
 */
const API_CONFIG = {
  baseURL: '',
  timeout: 30000, // 30 seconds - increased for Raspberry Pi network latency
  headers: {
    'Content-Type': 'application/json',
  },
}

/**
 * API Error class
 */
export class ApiError extends Error {
  constructor(
    message: string,
    public statusCode?: number,
    public code?: string,
    public details?: unknown
  ) {
    super(message)
    this.name = 'ApiError'
  }
}

/**
 * API Response wrapper
 */
export interface ApiResponse<T = unknown> {
  success: boolean
  data?: T
  error?: {
    message: string
    code?: string
    details?: unknown
  }
  meta?: {
    timestamp: string
    requestId?: string
  }
}

/**
 * Request options
 */
export interface RequestOptions extends RequestInit {
  timeout?: number
  params?: Record<string, string | number | boolean>
}

/**
 * Build URL with query parameters
 */
const buildURL = (endpoint: string, params?: Record<string, string | number | boolean>): string => {
  const url = new URL(endpoint, API_CONFIG.baseURL || window.location.origin)

  if (params) {
    Object.entries(params).forEach(([key, value]) => {
      url.searchParams.append(key, String(value))
    })
  }

  return url.toString()
}

/**
 * Fetch with timeout
 */
const fetchWithTimeout = async (url: string, options: RequestOptions): Promise<Response> => {
  const timeout = options.timeout || API_CONFIG.timeout
  const controller = new AbortController()

  const timeoutId = setTimeout(() => controller.abort(), timeout)

  try {
    const response = await fetch(url, {
      ...options,
      signal: controller.signal,
    })
    clearTimeout(timeoutId)
    return response
  } catch (error) {
    clearTimeout(timeoutId)
    if (error instanceof Error && error.name === 'AbortError') {
      throw new ApiError('Request timeout', 408, 'TIMEOUT')
    }
    throw error
  }
}

/**
 * Handle API response
 */
const handleResponse = async <T>(response: Response): Promise<T> => {
  const contentType = response.headers.get('content-type')
  const isJson = contentType?.includes('application/json')

  // 204 / 205 — No Content: body is empty, nothing to parse
  if (response.status === 204 || response.status === 205) {
    return undefined as unknown as T
  }

  if (!response.ok) {
    let errorMessage = `HTTP ${response.status}: ${response.statusText}`
    let errorCode = `HTTP_${response.status}`
    let errorDetails: unknown

    if (isJson) {
      try {
        const errorData = await response.json()
        errorMessage = errorData.error?.message || errorData.message || errorMessage
        errorCode = errorData.error?.code || errorCode
        errorDetails = errorData.error?.details || errorData.details
      } catch {
        // Failed to parse error JSON
      }
    }

    throw new ApiError(errorMessage, response.status, errorCode, errorDetails)
  }

  if (!isJson) {
    throw new ApiError('Expected JSON response', response.status, 'INVALID_RESPONSE')
  }

  const data = await response.json()

  // Handle ApiResponse wrapper format
  if (typeof data === 'object' && data !== null && 'success' in data) {
    if (!data.success) {
      throw new ApiError(
        data.error?.message || 'Unknown error',
        response.status,
        data.error?.code,
        data.error?.details
      )
    }
    return data.data as T
  }

  return data as T
}

/**
 * Base request function
 */
const request = async <T>(endpoint: string, options: RequestOptions = {}): Promise<T> => {
  const { params, timeout, ...fetchOptions } = options

  const url = buildURL(endpoint, params)

  const defaultHeaders = { ...API_CONFIG.headers }
  const headers: Record<string, string> = { ...defaultHeaders, ...(fetchOptions.headers as Record<string, string>) }

  // Don't send Content-Type when there's no body — servers (Express, Fastify) reject
  // "Content-Type: application/json" with an empty body with HTTP 400.
  if (!fetchOptions.body) {
    delete headers['Content-Type']
  }

  try {
    const response = await fetchWithTimeout(url, {
      ...fetchOptions,
      headers,
      timeout,
    })

    return await handleResponse<T>(response)
  } catch (error) {
    
    if (error instanceof ApiError) {
      throw error
    }

    if (error instanceof Error) {
      throw new ApiError(error.message, undefined, 'NETWORK_ERROR', error)
    }

    throw new ApiError('Unknown error occurred', undefined, 'UNKNOWN_ERROR')
  }
}

/**
 * API client
 */
export const api = {
  /**
   * GET request
   */
  get: <T>(endpoint: string, options?: RequestOptions): Promise<T> => {
    return request<T>(endpoint, { ...options, method: 'GET' })
  },

  /**
   * POST request
   */
  post: <T>(endpoint: string, body?: unknown, options?: RequestOptions): Promise<T> => {
    return request<T>(endpoint, {
      ...options,
      method: 'POST',
      body: body ? JSON.stringify(body) : undefined,
    })
  },

  /**
   * PUT request
   */
  put: <T>(endpoint: string, body?: unknown, options?: RequestOptions): Promise<T> => {
    return request<T>(endpoint, {
      ...options,
      method: 'PUT',
      body: body ? JSON.stringify(body) : undefined,
    })
  },

  /**
   * PATCH request
   */
  patch: <T>(endpoint: string, body?: unknown, options?: RequestOptions): Promise<T> => {
    return request<T>(endpoint, {
      ...options,
      method: 'PATCH',
      body: body ? JSON.stringify(body) : undefined,
    })
  },

  /**
   * DELETE request
   */
  delete: <T>(endpoint: string, options?: RequestOptions): Promise<T> => {
    return request<T>(endpoint, { ...options, method: 'DELETE' })
  },

  /**
   * Get base URL
   */
  getBaseURL: (): string => {
    return API_CONFIG.baseURL
  },

  /**
   * Set base URL (for testing or dynamic configuration)
   */
  setBaseURL: (url: string): void => {
    API_CONFIG.baseURL = url
  },
}

export default api
