// SHARED: PRINTER SELECTOR BAR
// Reusable printer selector strip used across BedMesh, GCode, Maintenance pages
// ═══════════════════════════════════════════════════════════════

import { Printer } from 'lucide-react'

interface PrinterSelectorBarProps {
  printers: Array<{ id: string; name?: string }>
  selected: string
  onSelect: (id: string) => void
  showAll?: boolean
  label?: string
}

export function PrinterSelectorBar({
  printers,
  selected,
  onSelect,
  showAll = false,
  label = 'Printer:',
}: PrinterSelectorBarProps) {
  if (printers.length === 0) return null
  if (printers.length === 1 && !showAll) return null

  return (
    <div className="flex flex-wrap items-center gap-3">
      <Printer className="w-4 h-4 text-text-muted" />
      <span className="text-sm text-text-muted font-medium">{label}</span>
      <div className="flex gap-1 flex-wrap">
        {showAll && (
          <button
            onClick={() => onSelect('all')}
            className={`px-3 py-1.5 rounded-md text-sm font-medium transition-all ${
              selected === 'all'
                ? 'bg-primary text-primary-foreground'
                : 'bg-surface text-text-muted hover:text-text border border-border'
            }`}
          >
            All
          </button>
        )}
        {printers.map((p) => (
          <button
            key={p.id}
            onClick={() => onSelect(p.id)}
            className={`px-3 py-1.5 rounded-md text-sm font-medium transition-all ${
              selected === p.id
                ? 'bg-primary text-primary-foreground'
                : 'bg-surface text-text-muted hover:text-text border border-border'
            }`}
          >
            {p.name || p.id}
          </button>
        ))}
      </div>
    </div>
  )
}
