import { useMemo, useState } from 'react'
import { Layers, Eye, EyeOff, ChevronDown } from 'lucide-react'

interface GCodeMove {
  x: number
  y: number
  z: number
  extrude: boolean
  speed: number
  layer: number
  featureType: string
}

interface FeatureStats {
  type: string
  distance: number
  extrusionDistance: number
  time: number // seconds
  percentage: number
  color: string
  visible: boolean
}

interface LayerInfoProps {
  moves: GCodeMove[]
  currentLayer: number
  layerMax: number
  onFeatureVisibilityChange?: (feature: string, visible: boolean) => void
}

const FEATURE_COLORS: Record<string, string> = {
  'Perimeter': '#00d4ff',
  'Infill': '#ff8800',
  'Support': '#ff44aa',
  'Top/Bottom': '#44ff88',
  'Skirt/Brim': '#ffff00',
  'Travel': '#6b7280',
}

// Filament properties (1.75mm diameter)
const FILAMENT_AREA = Math.PI * Math.pow(1.75 / 2, 2) // mm²
const EXTRUSION_WIDTH = 0.4 // mm (typical)
const LAYER_HEIGHT = 0.2 // mm (typical)

function formatTime(seconds: number): string {
  const hours = Math.floor(seconds / 3600)
  const minutes = Math.floor((seconds % 3600) / 60)
  const secs = Math.floor(seconds % 60)
  
  if (hours > 0) {
    return `${hours}h${minutes}m${secs}s`
  } else if (minutes > 0) {
    return `${minutes}m${secs}s`
  } else {
    return `${secs}s`
  }
}

export function LayerInfo({ moves, currentLayer, layerMax, onFeatureVisibilityChange }: LayerInfoProps) {
  const [visibleFeatures, setVisibleFeatures] = useState<Record<string, boolean>>({
    'Perimeter': true,
    'Infill': true,
    'Support': true,
    'Top/Bottom': true,
    'Skirt/Brim': true,
    'Travel': false
  })
  
  const [showTotals, setShowTotals] = useState(true)

  const { layerStats, totalStats } = useMemo(() => {
    const layerFeatures: Record<string, FeatureStats> = {}
    const allFeatures: Record<string, { distance: number; extrusionDistance: number; time: number }> = {}
    
    let totalExtrusionDistance = 0
    let totalTime = 0
    let layerExtrusionDistance = 0
    let layerTime = 0
    
    for (let i = 0; i < moves.length - 1; i++) {
      const move = moves[i]
      const nextMove = moves[i + 1]
      
      const key = move.extrude ? move.featureType : 'Travel'
      
      // Calculate distance
      const dx = nextMove.x - move.x
      const dy = nextMove.y - move.y
      const dz = nextMove.z - move.z
      const dist = Math.sqrt(dx * dx + dy * dy + dz * dz)
      
      // Calculate time (speed is in mm/min)
      const time = (dist / move.speed) * 60 // convert to seconds
      
      // For current layer
      if (move.layer === currentLayer) {
        if (!layerFeatures[key]) {
          layerFeatures[key] = {
            type: key,
            distance: 0,
            extrusionDistance: 0,
            time: 0,
            percentage: 0,
            color: FEATURE_COLORS[key] || '#888888',
            visible: visibleFeatures[key] ?? true
          }
        }
        
        layerFeatures[key].distance += dist
        layerFeatures[key].time += time
        
        if (move.extrude) {
          layerFeatures[key].extrusionDistance += dist
          layerExtrusionDistance += dist
          layerTime += time
        }
      }
      
      // For totals
      if (!allFeatures[key]) {
        allFeatures[key] = { distance: 0, extrusionDistance: 0, time: 0 }
      }
      allFeatures[key].distance += dist
      allFeatures[key].time += time
      
      if (move.extrude) {
        allFeatures[key].extrusionDistance += dist
        totalExtrusionDistance += dist
        totalTime += time
      }
    }
    
    // Calculate percentages for layer
    Object.values(layerFeatures).forEach(feature => {
      if (layerExtrusionDistance > 0 && feature.extrusionDistance > 0) {
        feature.percentage = (feature.extrusionDistance / layerExtrusionDistance) * 100
      }
    })
    
    // Sort by extrusion distance
    const layerStatsArray = Object.values(layerFeatures).sort((a, b) => b.extrusionDistance - a.extrusionDistance)
    
    // Calculate total filament usage (approximate)
    // Volume = distance * extrusion_width * layer_height
    const extrusionVolume = totalExtrusionDistance * EXTRUSION_WIDTH * LAYER_HEIGHT // mm³
    const filamentLength = extrusionVolume / FILAMENT_AREA // mm
    const filamentWeight = (extrusionVolume / 1000) * 1.24 // grams (PLA density)
    
    // Estimate cost (assuming €20/kg for PLA)
    const cost = (filamentWeight / 1000) * 20
    
    return {
      layerStats: layerStatsArray,
      totalStats: {
        features: allFeatures,
        totalExtrusionDistance,
        totalTime,
        filamentLength,
        filamentWeight,
        cost,
        prepareTime: 60 // 1 minute estimate
      }
    }
  }, [moves, currentLayer, visibleFeatures])

  const toggleFeatureVisibility = (feature: string) => {
    setVisibleFeatures(prev => {
      const newVisibility = { ...prev, [feature]: !prev[feature] }
      onFeatureVisibilityChange?.(feature, newVisibility[feature])
      return newVisibility
    })
  }

  if (!moves.length || currentLayer < 0) {
    return null
  }

  return (
    <div className="w-80 bg-[#1e2230]/95 backdrop-blur-sm border-l border-gray-700/50 flex flex-col overflow-hidden">
      {/* Header */}
      <div className="px-4 py-3 border-b border-gray-700/50">
        <div className="flex items-center gap-2">
          <Layers className="w-4 h-4 text-cyan-400" />
          <h3 className="text-sm font-semibold text-gray-100">Line Type</h3>
        </div>
        <div className="mt-1 text-xs text-gray-400">
          Layer {currentLayer} of {layerMax}
        </div>
      </div>

      {/* Stats Table Header */}
      <div className="px-4 py-2 border-b border-gray-700/30 bg-gray-800/40">
        <div className="grid grid-cols-[1fr,60px,35px,60px,24px] gap-2 text-[10px] font-medium text-gray-400">
          <div>Line Type</div>
          <div className="text-right">Time</div>
          <div className="text-right">%</div>
          <div className="text-right">Usage</div>
          <div></div>
        </div>
      </div>

      {/* Feature breakdown */}
      <div className="flex-1 overflow-y-auto">
        {layerStats.length === 0 ? (
          <div className="text-xs text-gray-500 text-center py-8">
            No data for this layer
          </div>
        ) : (
          <div className="px-4 py-2">
            {layerStats.map((feature) => (
              <div 
                key={feature.type}
                className="grid grid-cols-[1fr,60px,35px,60px,24px] gap-2 items-center py-1.5 hover:bg-gray-800/40 rounded transition-colors"
              >
                {/* Feature name with color indicator */}
                <div className="flex items-center gap-2 min-w-0">
                  <div 
                    className="w-2.5 h-2.5 rounded-sm flex-shrink-0"
                    style={{ backgroundColor: feature.color }}
                  />
                  <span className="text-xs text-gray-200 truncate">
                    {feature.type}
                  </span>
                </div>
                
                {/* Time */}
                <div className="text-[11px] text-gray-400 font-mono text-right">
                  {formatTime(feature.time)}
                </div>
                
                {/* Percentage */}
                <div className="text-[11px] text-gray-400 font-mono text-right">
                  {feature.percentage > 0 ? feature.percentage.toFixed(1) : '-'}
                </div>
                
                {/* Usage (extrusion distance) */}
                <div className="text-[11px] text-gray-400 font-mono text-right">
                  {feature.extrusionDistance > 0 
                    ? `${(feature.extrusionDistance / 1000).toFixed(2)}m`
                    : '-'
                  }
                </div>
                
                {/* Visibility toggle */}
                <button
                  onClick={() => toggleFeatureVisibility(feature.type)}
                  className="p-0.5 hover:bg-gray-700/50 rounded transition-colors"
                  title={feature.visible ? 'Hide' : 'Show'}
                >
                  {feature.visible ? (
                    <Eye className="w-3.5 h-3.5 text-cyan-400" />
                  ) : (
                    <EyeOff className="w-3.5 h-3.5 text-gray-600" />
                  )}
                </button>
              </div>
            ))}
          </div>
        )}

        {/* Total Estimation */}
        <div className="px-4 pt-2 pb-4 border-t border-gray-700/40">
          <button
            onClick={() => setShowTotals(!showTotals)}
            className="flex items-center justify-between w-full text-xs font-medium text-gray-300 mb-2 hover:text-cyan-400 transition-colors"
          >
            <span>Total Estimation</span>
            <ChevronDown className={`w-3.5 h-3.5 transition-transform ${showTotals ? '' : '-rotate-90'}`} />
          </button>
          
          {showTotals && (
            <div className="space-y-1.5">
              <div className="flex justify-between text-xs">
                <span className="text-gray-400">Total Filament:</span>
                <span className="text-cyan-400 font-mono font-semibold">
                  {(totalStats.filamentLength / 1000).toFixed(2)}m
                </span>
              </div>
              <div className="flex justify-between text-xs">
                <span className="text-gray-400">Model Filament:</span>
                <span className="text-cyan-400 font-mono font-semibold">
                  {(totalStats.filamentLength / 1000).toFixed(2)}m
                </span>
              </div>
              <div className="flex justify-between text-xs">
                <span className="text-gray-400"></span>
                <span className="text-cyan-400 font-mono font-semibold">
                  {totalStats.filamentWeight.toFixed(1)}g
                </span>
              </div>
              <div className="flex justify-between text-xs">
                <span className="text-gray-400">Cost:</span>
                <span className="text-orange-400 font-mono font-semibold">
                  €{totalStats.cost.toFixed(2)}
                </span>
              </div>
              <div className="flex justify-between text-xs">
                <span className="text-gray-400">Prepare time:</span>
                <span className="text-gray-300 font-mono">
                  {formatTime(totalStats.prepareTime)}
                </span>
              </div>
              <div className="flex justify-between text-xs">
                <span className="text-gray-400">Model printing time:</span>
                <span className="text-gray-300 font-mono">
                  {formatTime(totalStats.totalTime)}
                </span>
              </div>
              <div className="flex justify-between text-xs pt-1 border-t border-gray-700/40">
                <span className="text-gray-300 font-medium">Total time:</span>
                <span className="text-cyan-400 font-mono font-semibold">
                  {formatTime(totalStats.totalTime + totalStats.prepareTime)}
                </span>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}
