// ═══════════════════════════════════════════════════════════════
// PRESTIGE DASHBOARD - useThrottledCallback Hook
// Throttles a callback — useful for refresh buttons, backup triggers
// ═══════════════════════════════════════════════════════════════

import { useCallback, useEffect, useRef } from 'react'

/**
 * Returns a throttled version of the callback.
 * The callback fires at most once per `interval` ms.
 *
 * @param callback - Function to throttle
 * @param interval - Minimum interval in ms (default 5000)
 */
export function useThrottledCallback<T extends (...args: any[]) => any>(
  callback: T,
  interval = 5000
): T {
  const callbackRef = useRef(callback)
  const lastCallRef = useRef(0)
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  useEffect(() => {
    callbackRef.current = callback
  }, [callback])

  useEffect(() => {
    return () => {
      if (timerRef.current) clearTimeout(timerRef.current)
    }
  }, [])

  return useCallback(
    ((...args: Parameters<T>) => {
      const now = Date.now()
      const remaining = interval - (now - lastCallRef.current)

      if (remaining <= 0) {
        if (timerRef.current) {
          clearTimeout(timerRef.current)
          timerRef.current = null
        }
        lastCallRef.current = now
        callbackRef.current(...args)
      } else if (!timerRef.current) {
        timerRef.current = setTimeout(() => {
          lastCallRef.current = Date.now()
          timerRef.current = null
          callbackRef.current(...args)
        }, remaining)
      }
    }) as T,
    [interval]
  )
}

export default useThrottledCallback
