// PRESTIGE DASHBOARD - PRINTER CARD METRICS COMPONENT  
// FE-02: Uses TemperatureGauge (FE-07) and ProgressBar (FE-08)
// ═══════════════════════════════════════════════════════════════

import React from 'react'
import { Layers } from 'lucide-react'
import { TemperatureGauge } from '../TemperatureGauge'
import { ProgressBar } from '../ProgressBar'
import type { TemperatureReading, PrintProgress } from '../../types/printer'

interface PrinterCardMetricsProps {
  temperatures?: {
    hotend?: TemperatureReading
    bed?: TemperatureReading
  }
  progress?: PrintProgress
  showTemperatures?: boolean
  showProgress?: boolean
}

/**
 * Format time (seconds to readable string)
 */
const formatTime = (seconds: number): string => {
  const hours = Math.floor(seconds / 3600)
  const minutes = Math.floor((seconds % 3600) / 60)

  if (hours > 0) {
    return `${hours}h ${minutes}m`
  }
  if (minutes > 0) {
    return `${minutes}m`
  }
  return `<1m`
}

/**
 * PrinterCardMetrics Component
 * Now uses TemperatureGauge and ProgressBar components from FE-07 and FE-08
 */
export const PrinterCardMetrics: React.FC<PrinterCardMetricsProps> = ({
  temperatures,
  progress,
  showTemperatures = true,
  showProgress = true,
}) => {
  const hasTemps = temperatures && (temperatures.hotend || temperatures.bed)
  const hasProgress = progress && progress.percentage > 0

  if (!hasTemps && !hasProgress) {
    return null
  }

  return (
    <div className="space-y-3">
      {/* Temperature Section - Using TemperatureGauge (FE-07) */}
      {showTemperatures && hasTemps && (
        <div className="space-y-2">
          {temperatures.hotend && (
            <TemperatureGauge
              type="hotend"
              reading={temperatures.hotend}
              mode="compact"
              size="sm"
            />
          )}
          {temperatures.bed && (
            <TemperatureGauge
              type="bed"
              reading={temperatures.bed}
              mode="compact"
              size="sm"
            />
          )}
        </div>
      )}

      {/* Progress Section - Using ProgressBar (FE-08) */}
      {showProgress && hasProgress && progress && (
        <div className="space-y-2">
          {/* Print job name */}
          {progress.filename && (
            <div className="flex items-center gap-2">
              <Layers className="w-4 h-4 text-cyan-400" />
              <span className="text-xs text-gray-300 truncate flex-1">
                {progress.filename}
              </span>
            </div>
          )}

          {/* Progress bar - Using ProgressBar component */}
          <ProgressBar
            progress={{
              percentage: progress.percentage || 0,
              current: progress.currentLayer,
              total: progress.totalLayers,
              timeRemaining: progress.timeRemaining || 0,
              filename: progress.filename,
            }}
            size="sm"
            variant="glow"
            status="printing"
            showPercentage={true}
            showLabel={false}
          />

          {/* Time and layer info */}
          <div className="flex items-center justify-between text-xs">
            <span className="text-gray-500">
              ETA: {formatTime(progress.timeRemaining || 0)}
            </span>
            {progress.currentLayer !== undefined && (
              <span className="text-gray-500 flex items-center gap-1">
                <Layers className="w-3 h-3" />
                {progress.currentLayer}
                {progress.totalLayers && ` / ${progress.totalLayers}`}
              </span>
            )}
          </div>
        </div>
      )}
    </div>
  )
}

PrinterCardMetrics.displayName = 'PrinterCardMetrics'

export default PrinterCardMetrics
