// ═══════════════════════════════════════════════════════════════
// PRESTIGE DASHBOARD - AI CONTROL TOGGLE
// ═══════════════════════════════════════════════════════════════

import { useState, useCallback } from 'react'
import { Brain, Eye, MessageSquare, Zap, Shield, AlertTriangle } from 'lucide-react'
import { useAsyncAction } from '@core/hooks/useAsyncAction'

interface AIControlToggleProps {
  currentLevel: number
  printerId?: string
  onLevelChange?: (level: number) => void
  compact?: boolean
  skipApiCall?: boolean
}

const LEVELS = [
  {
    level: 0,
    name: 'Passive',
    shortName: 'L0',
    description: 'AI observes and learns only. No alerts or actions.',
    icon: Eye,
    activeText: 'text-yellow-400',
    activeBg: 'bg-yellow-500/20',
    activeBorder: 'border-yellow-500/50',
    confirmTitle: 'Switch to Passive Mode?',
    confirmDesc: 'AI will stop sending alerts and recommendations. Monitoring only.',
    confirmBtn: 'Set L0 — Passive',
    confirmColor: 'cyan',
  },
  {
    level: 1,
    name: 'Recommend',
    shortName: 'L1',
    description: 'AI sends recommendations. You decide what to do.',
    icon: MessageSquare,
    activeText: 'text-yellow-400',
    activeBg: 'bg-yellow-500/20',
    activeBorder: 'border-yellow-500/50',
    badge: 'Default',
    confirmTitle: 'Switch to Recommend Mode?',
    confirmDesc: 'AI will send recommendations, but you approve every action manually.',
    confirmBtn: 'Set L1 — Recommend',
    confirmColor: 'cyan',
  },
  {
    level: 2,
    name: 'Automatic',
    shortName: 'L2',
    description: 'AI automatically executes safe, reversible actions.',
    icon: Zap,
    activeText: 'text-yellow-400',
    activeBg: 'bg-yellow-500/20',
    activeBorder: 'border-yellow-500/50',
    confirmTitle: 'Enable Automatic Mode?',
    confirmDesc: 'AI will automatically execute safe, reversible actions without your approval. All actions include snapshots and can be reverted at any time.',
    confirmBtn: 'Enable L2 — Automatic',
    confirmColor: 'yellow',
  },
]

export function AIControlToggle({
  currentLevel,
  printerId,
  onLevelChange,
  compact = false,
  skipApiCall = false,
}: AIControlToggleProps) {
  const [showConfirm, setShowConfirm] = useState<number | null>(null)

  const updateLevel = useAsyncAction(async (newLevel: number) => {
    if (!skipApiCall) {
      const isPerPrinter = !!printerId && printerId !== 'global'
      const url = isPerPrinter
        ? `/api/printers/${printerId}/ai-level`
        : '/api/ai/settings'
      const body = isPerPrinter
        ? { level: newLevel }
        : { autonomyLevel: newLevel }

      const res = await fetch(url, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      })
      if (!res.ok) throw new Error(`Failed to update AI level`)
    }
    onLevelChange?.(newLevel)
    return newLevel
  })

  const handleSelect = useCallback((level: number) => {
    if (level === currentLevel) return
    // Always show confirmation dialog for any level change
    setShowConfirm(level)
  }, [currentLevel])

  const confirmLevel = useCallback(() => {
    if (showConfirm !== null) {
      updateLevel.execute(showConfirm)
      setShowConfirm(null)
    }
  }, [showConfirm, updateLevel])

  const cancelConfirm = useCallback(() => setShowConfirm(null), [])

  const pendingLevel = showConfirm !== null ? LEVELS.find(l => l.level === showConfirm) : null

  if (compact) {
    return (
      <div className="flex items-center gap-1 rounded-lg border border-gray-700 p-1 bg-gray-900/50">
        {LEVELS.map(l => {
          const Icon = l.icon
          const isActive = currentLevel === l.level
          return (
            <button
              key={l.level}
              onClick={() => handleSelect(l.level)}
              disabled={updateLevel.loading}
              className={`flex items-center gap-1 px-2 py-1 rounded text-xs font-semibold transition-all border ${
                isActive
                  ? `${l.activeBg} ${l.activeText} ${l.activeBorder}`
                  : 'text-gray-400 border-transparent hover:text-white'
              }`}
              title={`${l.name}: ${l.description}`}
            >
              <Icon className="w-3 h-3" />
              {l.shortName}
            </button>
          )
        })}
      </div>
    )
  }

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Brain className="w-5 h-5 text-cyan-400" />
          <h3 className="text-sm font-semibold text-white">AI Autonomy Level</h3>
        </div>
        {updateLevel.loading && (
          <span className="text-[11px] text-cyan-400 animate-pulse">Saving…</span>
        )}
        {updateLevel.error && (
          <span className="text-[11px] text-red-400">Failed to save</span>
        )}
      </div>

      <div className="space-y-2">
        {LEVELS.map(l => {
          const Icon = l.icon
          const isActive = currentLevel === l.level
          const isPending = showConfirm === l.level
          return (
            <button
              key={l.level}
              onClick={() => handleSelect(l.level)}
              disabled={updateLevel.loading}
              className={`w-full flex items-start gap-3 p-3 rounded-lg border-2 transition-all text-left disabled:opacity-60 ${
                isPending
                  ? 'border-orange-500/60 bg-orange-500/10'
                  : isActive
                  ? `${l.activeBg} ${l.activeBorder}`
                  : 'border-gray-700 bg-gray-900/50 hover:border-gray-500 hover:bg-gray-800/40'
              }`}
            >
              <Icon className={`w-5 h-5 mt-0.5 flex-shrink-0 ${isActive ? l.activeText : isPending ? 'text-orange-400' : 'text-gray-400'}`} />
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2">
                  <span className={`text-sm font-semibold ${isActive ? l.activeText : isPending ? 'text-orange-400' : 'text-white'}`}>
                    {l.shortName} — {l.name}
                  </span>
                  {l.badge && (
                    <span className="text-[10px] px-1.5 py-0.5 rounded bg-cyan-500/20 text-cyan-400 font-semibold">
                      {l.badge}
                    </span>
                  )}
                  {isActive && !isPending && (
                    <span className="text-[10px] px-1.5 py-0.5 rounded bg-green-500/20 text-green-400 font-semibold ml-auto">
                      Active
                    </span>
                  )}
                  {isPending && (
                    <span className="text-[10px] px-1.5 py-0.5 rounded bg-orange-500/20 text-orange-400 font-semibold ml-auto animate-pulse">
                      Pending…
                    </span>
                  )}
                </div>
                <p className="text-xs text-gray-400 mt-0.5">{l.description}</p>
              </div>
            </button>
          )
        })}
      </div>

      {/* Active level info banner — shown for all levels */}
      {showConfirm === null && currentLevel === 0 && (
        <div className="flex items-start gap-2 p-2.5 rounded-lg bg-yellow-500/10 border border-yellow-500/30 text-xs">
          <Eye className="w-3.5 h-3.5 text-yellow-400 mt-0.5 flex-shrink-0" />
          <div className="text-yellow-300/80">
            <span className="font-semibold text-yellow-400">L0 Active:</span> AI is observing and learning only. No alerts or automatic actions will be taken.
          </div>
        </div>
      )}
      {showConfirm === null && currentLevel === 1 && (
        <div className="flex items-start gap-2 p-2.5 rounded-lg bg-yellow-500/10 border border-yellow-500/30 text-xs">
          <MessageSquare className="w-3.5 h-3.5 text-yellow-400 mt-0.5 flex-shrink-0" />
          <div className="text-yellow-300/80">
            <span className="font-semibold text-yellow-400">L1 Active:</span> AI will send recommendations for your review. You approve every action manually.
          </div>
        </div>
      )}
      {showConfirm === null && currentLevel === 2 && (
        <div className="flex items-start gap-2 p-2.5 rounded-lg bg-yellow-500/10 border border-yellow-500/30 text-xs">
          <Shield className="w-3.5 h-3.5 text-yellow-400 mt-0.5 flex-shrink-0" />
          <div className="text-yellow-300/80">
            <span className="font-semibold text-yellow-400">L2 Active:</span> AI will automatically execute safe, reversible actions. All actions can be reverted.
          </div>
        </div>
      )}

      {/* Confirmation dialog — same style for all levels (yellow/orange) */}
      {showConfirm !== null && pendingLevel && (
        <div className="p-3 rounded-lg border-2 border-yellow-500/50 bg-yellow-500/10 space-y-2">
          <div className="flex items-center gap-2 text-sm font-semibold text-yellow-400">
            <AlertTriangle className="w-4 h-4" />
            {pendingLevel.confirmTitle}
          </div>
          <p className="text-xs text-gray-400">
            {pendingLevel.confirmDesc}
          </p>
          <div className="flex gap-2 pt-1">
            <button
              onClick={confirmLevel}
              disabled={updateLevel.loading}
              className="px-3 py-1.5 text-xs font-semibold rounded transition-colors disabled:opacity-50 bg-yellow-500/20 text-yellow-400 hover:bg-yellow-500/30"
            >
              {updateLevel.loading ? 'Saving…' : pendingLevel.confirmBtn}
            </button>
            <button
              onClick={cancelConfirm}
              disabled={updateLevel.loading}
              className="px-3 py-1.5 text-xs rounded text-gray-400 hover:text-white transition-colors disabled:opacity-50"
            >
              Cancel
            </button>
          </div>
        </div>
      )}
    </div>
  )
}

export default AIControlToggle
