// ═══════════════════════════════════════════════════════════════
// PRESTIGE DASHBOARD - Header Component (NO TEXT CURSOR)
// ═══════════════════════════════════════════════════════════════

import { useState, useEffect } from 'react'
import { Printer, RefreshCw, Bell, Settings } from 'lucide-react'
import { useSystemStore, usePrinterStore } from '@core/state'
import { useNavigate, useLocation } from 'react-router-dom'

const PAGE_META: Record<string, { title: string; subtitle: string }> = {
  '/':           { title: 'Dashboard',         subtitle: 'Multi-printer monitoring and control' },
  '/dashboard':  { title: 'Dashboard',         subtitle: 'Multi-printer monitoring and control' },
  '/printers':   { title: 'Printers',          subtitle: 'Manage and monitor your 3D printers' },
  '/ai':         { title: 'AI Control Center', subtitle: 'Manage AI recommendations and actions' },
  '/backup':     { title: 'Backup & Restore',  subtitle: 'Create and manage system backups' },
  '/monitoring': { title: 'Monitoring',        subtitle: 'Live system and printer telemetry' },
  '/history':    { title: 'History',           subtitle: 'Print job history and statistics' },
  '/gcode':      { title: 'G-Code',            subtitle: 'Manage and send G-code files' },
  '/console':    { title: 'G-Code Console',    subtitle: 'Direct printer terminal access' },
  '/settings':   { title: 'Settings',          subtitle: 'Configure dashboard preferences' },
  '/maintenance':{ title: 'Maintenance',       subtitle: 'Scheduled maintenance and tasks' },
  '/bed-mesh':   { title: 'Bed Mesh',          subtitle: 'Bed leveling visualization' },
}

export function Header() {
  const navigate = useNavigate()
  const location = useLocation()
  const connectionStatus = useSystemStore((state) => state.connectionStatus)
  const printersArray = usePrinterStore((state) => Object.values(state.printers))
  const [tick, setTick] = useState(0)

  const isConnected = connectionStatus === 'connected'
  const totalPrinters = printersArray.length

  const basePath = '/' + location.pathname.split('/')[1]
  const meta = PAGE_META[basePath] ?? PAGE_META[location.pathname]

  // Clock tick for scan-line animation
  useEffect(() => {
    const id = setInterval(() => setTick(t => t + 1), 4000)
    return () => clearInterval(id)
  }, [])

  return (
    <>
      {/* Ambient glow matching dashboard */}
      <div
        className="sticky top-0 z-40"
        style={{ 
          filter: 'drop-shadow(0 4px 20px rgba(0,212,255,0.08))',
          cursor: 'default',
        }}
      >
        {/* Main header bar - MATCHING SIDEBAR */}
        <header
          className="relative h-16 px-6 flex items-center overflow-hidden backdrop-blur-xl bg-gray-900 border-b border-gray-800"
          style={{
            boxShadow: `
              0 1px 0 rgba(0,212,255,0.08),
              inset 0 1px 0 rgba(255,255,255,0.03),
              0 4px 20px rgba(0,0,0,0.4)
            `,
            cursor: 'default',
          }}
        >
          {/* Animated scan line */}
          <div
            className="pointer-events-none absolute inset-x-0 h-px top-0"
            style={{
              background: 'linear-gradient(90deg, transparent 0%, rgba(0,212,255,0.4) 50%, transparent 100%)',
              animation: 'scanline 4s cubic-bezier(0.4, 0, 0.6, 1) infinite',
              opacity: 0.6,
            }}
          />

          {/* Corner accents */}
          <div className="pointer-events-none absolute top-0 left-0 w-16 h-12 overflow-hidden opacity-60">
            <div style={{
              position: 'absolute', top: 0, left: 0,
              width: 24, height: 1,
              background: 'linear-gradient(90deg, rgba(0,212,255,0.7), transparent)',
            }} />
            <div style={{
              position: 'absolute', top: 0, left: 0,
              width: 1, height: 16,
              background: 'linear-gradient(180deg, rgba(0,212,255,0.7), transparent)',
            }} />
          </div>
          <div className="pointer-events-none absolute top-0 right-0 w-16 h-12 overflow-hidden opacity-60">
            <div style={{
              position: 'absolute', top: 0, right: 0,
              width: 24, height: 1,
              background: 'linear-gradient(270deg, rgba(0,212,255,0.7), transparent)',
            }} />
            <div style={{
              position: 'absolute', top: 0, right: 0,
              width: 1, height: 16,
              background: 'linear-gradient(180deg, rgba(0,212,255,0.7), transparent)',
            }} />
          </div>

          {/* Subtle grid overlay */}
          <div
            className="pointer-events-none absolute inset-0 opacity-[0.015]"
            style={{
              backgroundImage: `
                repeating-linear-gradient(0deg, rgba(0,212,255,1) 0px, rgba(0,212,255,1) 1px, transparent 1px, transparent 32px),
                repeating-linear-gradient(90deg, rgba(0,212,255,1) 0px, rgba(0,212,255,1) 1px, transparent 1px, transparent 32px)
              `,
            }}
          />

          {/* ── LEFT: Page title ── */}
          <div className="flex items-center gap-4 flex-1 min-w-0" style={{ cursor: 'default' }}>
            {meta && (
              <div className="flex items-center gap-3.5 min-w-0">
                {/* Accent bar matching dashboard cyan */}
                <div style={{
                  width: 3, height: 36, flexShrink: 0,
                  background: 'linear-gradient(180deg, rgba(0,212,255,0.9) 0%, rgba(99,102,241,0.5) 100%)',
                  borderRadius: 1.5,
                  boxShadow: '0 0 10px rgba(0,212,255,0.3)',
                }} />
                <div className="min-w-0" style={{ cursor: 'default', userSelect: 'none' }}>
                  <h1
                    className="text-[17px] font-extrabold tracking-wide uppercase truncate"
                    style={{
                      color: '#ffffff',
                      textShadow: '0 0 16px rgba(0,212,255,0.4), 0 2px 4px rgba(0,0,0,0.7)',
                      letterSpacing: '0.15em',
                      fontFamily: "'Rajdhani', 'Orbitron', sans-serif",
                      fontWeight: 800,
                      lineHeight: 1.2,
                      cursor: 'default',
                      userSelect: 'none',
                    }}
                  >
                    {meta.title}
                  </h1>
                  <p
                    className="text-[10px] truncate mt-1"
                    style={{
                      color: 'rgba(0,212,255,0.8)',
                      letterSpacing: '0.12em',
                      textTransform: 'uppercase',
                      fontFamily: "'Share Tech Mono', monospace",
                      fontWeight: 500,
                      textShadow: '0 0 8px rgba(0,212,255,0.25)',
                      cursor: 'default',
                      userSelect: 'none',
                    }}
                  >
                    {meta.subtitle}
                  </p>
                </div>
              </div>
            )}
          </div>

          {/* ── CENTER: Status indicators (EQUAL HEIGHT) ── */}
          <div className="absolute left-1/2 -translate-x-1/2 flex items-center gap-3" style={{ cursor: 'default' }}>
            {/* Connection status pill */}
            <div
              className="px-3.5 py-2 rounded-lg transition-all duration-300"
              style={{
                background: isConnected
                  ? 'linear-gradient(135deg, rgba(0,255,120,0.08), rgba(0,255,120,0.04))'
                  : 'linear-gradient(135deg, rgba(255,60,60,0.08), rgba(255,60,60,0.04))',
                border: `1px solid ${isConnected ? 'rgba(0,255,120,0.2)' : 'rgba(255,60,60,0.2)'}`,
                boxShadow: isConnected
                  ? '0 0 10px rgba(0,255,120,0.08), inset 0 1px 0 rgba(255,255,255,0.03)'
                  : '0 0 10px rgba(255,60,60,0.08)',
                cursor: 'default',
              }}
            >
              <div className="flex items-center gap-2">
                {/* Status indicator dot */}
                <div className="relative w-1.5 h-1.5">
                  <div
                    className="absolute inset-0 rounded-full"
                    style={{
                      background: isConnected ? '#00ff78' : '#ff3c3c',
                      boxShadow: isConnected 
                        ? '0 0 6px rgba(0,255,120,0.6)' 
                        : '0 0 6px rgba(255,60,60,0.6)',
                    }}
                  />
                  {isConnected && (
                    <div
                      className="absolute inset-0 rounded-full"
                      style={{
                        background: '#00ff78',
                        animation: 'pulse-ring 2s cubic-bezier(0.4, 0, 0.6, 1) infinite',
                      }}
                    />
                  )}
                </div>
                <span
                  className="text-[10px] font-bold tracking-wide"
                  style={{
                    color: isConnected ? '#00ff78' : '#ff3c3c',
                    textShadow: isConnected 
                      ? '0 0 6px rgba(0,255,120,0.4)' 
                      : '0 0 6px rgba(255,60,60,0.4)',
                    fontFamily: "'Share Tech Mono', monospace",
                    letterSpacing: '0.08em',
                    fontWeight: 600,
                    cursor: 'default',
                    userSelect: 'none',
                  }}
                >
                  {isConnected ? 'ONLINE' : 'OFFLINE'}
                </span>
              </div>
            </div>

            {/* Divider */}
            <div style={{ 
              width: 1, 
              height: 20, 
              background: 'linear-gradient(180deg, transparent, rgba(0,212,255,0.2), transparent)' 
            }} />

            {/* Printer count badge */}
            <button
              onClick={() => navigate('/printers')}
              className="group px-3.5 py-2 rounded-lg transition-all duration-200"
              style={{
                background: 'rgba(0,212,255,0.06)',
                border: '1px solid rgba(0,212,255,0.2)',
                cursor: 'pointer',
              }}
            >
              <div className="flex items-center gap-2">
                <Printer 
                  style={{ 
                    width: 12, 
                    height: 12, 
                    color: 'rgba(0,212,255,0.85)',
                    transition: 'all 0.2s ease',
                  }} 
                  className="group-hover:scale-110"
                />
                <span
                  className="text-[10px] font-bold tracking-wide"
                  style={{
                    color: 'rgba(0,212,255,0.85)',
                    fontFamily: "'Share Tech Mono', monospace",
                    letterSpacing: '0.08em',
                    fontWeight: 600,
                    textShadow: '0 0 6px rgba(0,212,255,0.3)',
                    userSelect: 'none',
                  }}
                >
                  <span style={{ color: '#ffffff', fontWeight: 700 }}>{totalPrinters}</span>
                  {' '}PRINTERS
                </span>
              </div>
            </button>
          </div>

          {/* ── RIGHT: Action buttons ── */}
          <div className="flex items-center gap-2 flex-1 justify-end">
            {/* Refresh */}
            <HudButton onClick={() => window.location.reload()} title="Refresh">
              <RefreshCw style={{ width: 15, height: 15 }} />
            </HudButton>

            {/* Notifications */}
            <HudButton onClick={() => {}} title="Notifications">
              <Bell style={{ width: 15, height: 15 }} />
            </HudButton>

            {/* Settings */}
            <HudButton
              onClick={() => location.pathname === '/settings' ? navigate(-1) : navigate('/settings')}
              title="Settings"
              active={location.pathname === '/settings'}
            >
              <Settings style={{ width: 15, height: 15 }} />
            </HudButton>
          </div>
        </header>

        {/* Bottom accent line matching dashboard */}
        <div
          className="h-px w-full"
          style={{
            background: 'linear-gradient(90deg, transparent 0%, rgba(0,212,255,0.15) 20%, rgba(99,102,241,0.2) 50%, rgba(0,212,255,0.15) 80%, transparent 100%)',
          }}
        />
      </div>

      <style>{`
        @keyframes scanline {
          0%   { transform: translateX(-100%); opacity: 0; }
          15%  { opacity: 0.6; }
          85%  { opacity: 0.6; }
          100% { transform: translateX(100%); opacity: 0; }
        }
        
        @keyframes pulse-ring {
          0%   { transform: scale(1); opacity: 0.6; }
          50%  { transform: scale(2.5); opacity: 0; }
          100% { transform: scale(2.5); opacity: 0; }
        }
        
        @keyframes tooltipSlideIn {
          0%   { opacity: 0; transform: translateX(-50%) translateY(4px) scale(0.92); }
          100% { opacity: 1; transform: translateX(-50%) translateY(0) scale(1); }
        }
        
        /* Disable text cursor everywhere in header */
        header, header * {
          cursor: default !important;
        }
        
        header button, header button * {
          cursor: pointer !important;
        }
      `}</style>
    </>
  )
}

// ── HUD Button with Bright Visible Tooltip ──
function HudButton({
  children, 
  onClick, 
  title, 
  active = false,
}: {
  children: React.ReactNode
  onClick: () => void
  title?: string
  active?: boolean
}) {
  const [hovered, setHovered] = useState(false)

  return (
    <div style={{ position: 'relative' }}>
      <button
        onClick={onClick}
        onMouseEnter={() => setHovered(true)}
        onMouseLeave={() => setHovered(false)}
        style={{
          position: 'relative',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          width: 38,
          height: 38,
          borderRadius: 8,
          border: active || hovered
            ? '1px solid rgba(0,212,255,0.35)'
            : '1px solid rgba(255,255,255,0.05)',
          background: active
            ? 'linear-gradient(135deg, rgba(0,212,255,0.15), rgba(0,212,255,0.06))'
            : hovered
              ? 'rgba(0,212,255,0.08)'
              : 'rgba(255,255,255,0.02)',
          color: active || hovered 
            ? 'rgba(0,212,255,0.95)' 
            : 'rgba(160,180,200,0.7)',
          boxShadow: active 
            ? '0 0 14px rgba(0,212,255,0.12), inset 0 1px 0 rgba(0,212,255,0.1)' 
            : hovered
              ? '0 0 10px rgba(0,212,255,0.08)'
              : 'none',
          transition: 'all 0.2s cubic-bezier(0.4, 0, 0.2, 1)',
          cursor: 'pointer',
          transform: hovered ? 'translateY(-1px)' : 'translateY(0)',
        }}
      >
        {/* Active indicator line */}
        {active && (
          <div style={{
            position: 'absolute', 
            bottom: 0, 
            left: '20%', 
            right: '20%', 
            height: 2,
            borderRadius: '2px 2px 0 0',
            background: 'linear-gradient(90deg, transparent, rgba(0,212,255,0.85), transparent)',
            boxShadow: '0 0 8px rgba(0,212,255,0.5)',
          }} />
        )}
        <div style={{
          transition: 'transform 0.2s ease',
          transform: hovered ? 'scale(1.15)' : 'scale(1)',
        }}>
          {children}
        </div>
      </button>

      {/* Bright Visible Tooltip - ABOVE BUTTON */}
      {hovered && title && (
        <div
          style={{
            position: 'absolute',
            bottom: 'calc(100% + 8px)',
            left: '50%',
            transform: 'translateX(-50%)',
            padding: '6px 12px',
            borderRadius: 7,
            background: 'linear-gradient(145deg, rgba(0,212,255,0.15), rgba(0,150,200,0.12))',
            backgroundColor: 'rgba(10, 20, 35, 0.98)',
            border: '1px solid rgba(0,212,255,0.4)',
            boxShadow: `
              0 0 20px rgba(0,212,255,0.2),
              0 4px 16px rgba(0,0,0,0.6),
              inset 0 1px 0 rgba(0,212,255,0.3),
              inset 0 -1px 0 rgba(0,212,255,0.15)
            `,
            backdropFilter: 'blur(16px) saturate(180%)',
            whiteSpace: 'nowrap',
            zIndex: 1000,
            animation: 'tooltipSlideIn 0.25s cubic-bezier(0.34, 1.56, 0.64, 1)',
            pointerEvents: 'none',
            cursor: 'default',
          }}
        >
          {/* Bright top glow */}
          <div style={{
            position: 'absolute',
            top: 0,
            left: '10%',
            right: '10%',
            height: 2,
            borderRadius: '7px 7px 0 0',
            background: 'linear-gradient(90deg, transparent, rgba(0,212,255,0.8) 30%, rgba(0,255,255,0.9) 50%, rgba(0,212,255,0.8) 70%, transparent)',
            boxShadow: '0 0 8px rgba(0,212,255,0.6)',
          }} />
          
          {/* Arrow pointer DOWN - more visible */}
          <div style={{
            position: 'absolute',
            bottom: -5,
            left: '50%',
            transform: 'translateX(-50%) rotate(45deg)',
            width: 9,
            height: 9,
            background: 'rgba(10, 20, 35, 0.98)',
            border: '1px solid rgba(0,212,255,0.4)',
            borderTop: 'none',
            borderLeft: 'none',
            boxShadow: '2px 2px 6px rgba(0,0,0,0.4)',
          }} />
          
          {/* Inner radial glow */}
          <div style={{
            position: 'absolute',
            inset: 1,
            borderRadius: 6,
            background: 'radial-gradient(circle at 50% 0%, rgba(0,212,255,0.12), transparent 70%)',
            pointerEvents: 'none',
          }} />
          
          <span style={{
            position: 'relative',
            fontSize: 12,
            fontFamily: "'Rajdhani', 'Inter', sans-serif",
            fontWeight: 700,
            color: '#ffffff',
            letterSpacing: '0.04em',
            textShadow: '0 0 12px rgba(0,212,255,0.6), 0 2px 4px rgba(0,0,0,0.8)',
            display: 'block',
            cursor: 'default',
            userSelect: 'none',
          }}>
            {title}
          </span>
        </div>
      )}
    </div>
  )
}

export default Header
