// ─── AIMaintStatusPanel ────────────────────────────────────────
// AI maintenance status + history panel for a single printer.
// Used in PrinterDetailPage > MaintTab.

import { useState, useEffect } from 'react'
import { AlertTriangle, Clock, Info, RefreshCw, Wrench, Gauge, History } from 'lucide-react'

const BASE_URL = (() => {
  try { return import.meta.env.VITE_API_URL || 'http://localhost:3002' } catch { return 'http://localhost:3002' }
})()

// ─── Types ─────────────────────────────────────────────────────
interface MaintenanceRecord {
  id: string; printerId: string; type: string; description: string
  performedAt: string; duration: number | null; notes: string | null
}
interface ComponentMaintenanceStatus {
  component: string; lastMaintenance: string | null
  printHoursSince: number; urgency: 'none' | 'scheduled' | 'due' | 'overdue'
}
interface MaintenanceStatus {
  printerId: string; totalPrintHours: number
  printHoursSinceLastMaintenance: number
  overdueItems: string[]; dueItems: string[]; scheduledItems: string[]
  componentStatus: ComponentMaintenanceStatus[]; healthScore: number
}

// ─── Sub-components ─────────────────────────────────────────────
function AiSection({ title, icon, children, action }: {
  title: string; icon?: React.ReactNode; children: React.ReactNode; action?: React.ReactNode
}) {
  return (
    <div className="rounded-xl border border-gray-700 bg-gray-900/40 overflow-hidden">
      <div className="flex items-center justify-between px-4 py-2.5 border-b border-gray-700 bg-gray-900/30">
        <div className="flex items-center gap-2 text-sm font-semibold text-gray-200">{icon}{title}</div>
        {action}
      </div>
      <div className="p-4">{children}</div>
    </div>
  )
}

function AiInfoCard({ label, value, color }: { label: string; value: string; color: 'red' | 'green' | 'yellow' | 'cyan' }) {
  const c = { red: 'text-red-400', green: 'text-green-400', yellow: 'text-yellow-400', cyan: 'text-cyan-400' }[color]
  return (
    <div className="rounded-lg bg-gray-900/60 border border-gray-700 px-3 py-2 text-center">
      <div className={`text-base font-bold ${c}`}>{value}</div>
      <div className="text-[10px] text-gray-500 mt-0.5">{label}</div>
    </div>
  )
}

const URGENCY_COLOR: Record<string, string> = {
  none: 'text-green-400', scheduled: 'text-blue-400', due: 'text-yellow-400', overdue: 'text-red-400',
}
const URGENCY_BG: Record<string, string> = {
  none: '', scheduled: 'bg-blue-500/5 border-blue-500/20',
  due: 'bg-yellow-500/5 border-yellow-500/20', overdue: 'bg-red-500/5 border-red-500/20',
}

// ─── Main export ─────────────────────────────────────────────
export function AIMaintStatusPanel({ printerId, refreshKey }: { printerId: string; refreshKey?: number }) {
  const [maintStatus, setMaintStatus] = useState<MaintenanceStatus | null>(null)
  const [maintHistory, setMaintHistory] = useState<MaintenanceRecord[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  const fetchData = () => {
    setLoading(true)
    setError(null)
    Promise.all([
      fetch(`${BASE_URL}/api/ai/printers/${printerId}/maintenance/stats`).then(r => r.ok ? r.json() : null),
      fetch(`${BASE_URL}/api/ai/printers/${printerId}/maintenance?limit=20`).then(r => r.ok ? r.json() : null),
    ]).then(([stats, history]) => {
      if (stats) setMaintStatus(stats)
      if (history) setMaintHistory(history.records ?? [])
    }).catch(() => setError('Failed to load maintenance data'))
      .finally(() => setLoading(false))
  }

  useEffect(() => { fetchData() }, [printerId, refreshKey])

  if (loading) return <div className="text-xs text-gray-500 py-4 text-center">Loading AI maintenance data…</div>
  if (error) return <div className="text-xs text-red-400 py-4 text-center">{error}</div>

  return (
    <div className="space-y-4">
      {maintStatus && (
        <AiSection
          title="AI Maintenance Status"
          icon={<Gauge className="w-4 h-4 text-cyan-400" />}
          action={<button onClick={fetchData} className="text-gray-500 hover:text-gray-300"><RefreshCw className="w-3.5 h-3.5" /></button>}
        >
          <div className="grid grid-cols-3 gap-2 mb-3">
            <AiInfoCard label="Health Score" value={`${maintStatus.healthScore ?? 0}%`} color={(maintStatus.healthScore ?? 100) < 60 ? 'red' : 'green'} />
            <AiInfoCard label="Print Hours" value={(maintStatus.totalPrintHours ?? 0).toFixed(0) + 'h'} color="cyan" />
            <AiInfoCard label="Since Maint" value={(maintStatus.printHoursSinceLastMaintenance ?? 0).toFixed(0) + 'h'} color="yellow" />
          </div>
          {((maintStatus.overdueItems ?? []).length > 0 || (maintStatus.dueItems ?? []).length > 0 || (maintStatus.scheduledItems ?? []).length > 0) && (
            <div className="space-y-1 mb-2">
              {(maintStatus.overdueItems ?? []).map((item, i) => (
                <div key={i} className="flex items-center gap-2 text-xs text-red-400 bg-red-500/5 border border-red-500/20 rounded px-2 py-1">
                  <AlertTriangle className="w-3 h-3 flex-shrink-0" /><span className="font-semibold">OVERDUE:</span> {item}
                </div>
              ))}
              {(maintStatus.dueItems ?? []).map((item, i) => (
                <div key={i} className="flex items-center gap-2 text-xs text-yellow-400 bg-yellow-500/5 border border-yellow-500/20 rounded px-2 py-1">
                  <Clock className="w-3 h-3 flex-shrink-0" /><span className="font-semibold">DUE:</span> {item}
                </div>
              ))}
              {(maintStatus.scheduledItems ?? []).map((item, i) => (
                <div key={i} className="flex items-center gap-2 text-xs text-blue-400 bg-blue-500/5 border border-blue-500/20 rounded px-2 py-1">
                  <Info className="w-3 h-3 flex-shrink-0" /><span className="font-semibold">UPCOMING:</span> {item}
                </div>
              ))}
            </div>
          )}
          <div className="space-y-1">
            {(maintStatus.componentStatus ?? []).filter(c => c.urgency !== 'none').map(c => (
              <div key={c.component} className={`flex items-center justify-between rounded px-2 py-1 border text-xs ${URGENCY_BG[c.urgency] ?? ''}`}>
                <span className="text-gray-300 capitalize">{c.component.replace(/_/g, ' ')}</span>
                <span className={`font-semibold ${URGENCY_COLOR[c.urgency] ?? 'text-gray-400'}`}>
                  {c.urgency.toUpperCase()} · {c.printHoursSince.toFixed(0)}h
                </span>
              </div>
            ))}
          </div>
        </AiSection>
      )}

      <AiSection title="AI Maintenance History" icon={<History className="w-4 h-4 text-gray-400" />}>
        {maintHistory.length === 0 ? (
          <p className="text-xs text-gray-500 text-center py-4">No maintenance records yet</p>
        ) : (
          <div className="space-y-2">
            {maintHistory.map(rec => (
              <div key={rec.id} className="flex items-start gap-3 p-2.5 rounded-lg bg-gray-900/40 border border-gray-700">
                <Wrench className="w-3.5 h-3.5 text-gray-500 flex-shrink-0 mt-0.5" />
                <div className="flex-1 min-w-0">
                  <div className="flex items-center justify-between gap-2">
                    <span className="text-xs font-medium text-gray-200 capitalize">{rec.type.replace(/_/g, ' ')}</span>
                    <span className="text-[10px] text-gray-500 flex-shrink-0">{new Date(rec.performedAt).toLocaleDateString()}</span>
                  </div>
                  <p className="text-xs text-gray-400 mt-0.5 truncate">{rec.description}</p>
                  {rec.notes && <p className="text-[10px] text-gray-500 mt-0.5">{rec.notes}</p>}
                </div>
              </div>
            ))}
          </div>
        )}
      </AiSection>
    </div>
  )
}
