import { useState, useCallback } from 'react'

/**
 * Simple local toast for components that need lightweight in-component toasts.
 * Distinct from uiStore's Toast (@core/types) which is app-global and richer.
 * Named LocalToast to avoid import confusion.
 */
export interface LocalToast {
  id: string
  msg: string
  type: 'success' | 'error' | 'info'
}

/** @deprecated Use LocalToast. This alias kept for backward compat. */
export type Toast = LocalToast

export function useToast() {
  const [toasts, setToasts] = useState<LocalToast[]>([])

  const add = useCallback((msg: string, type: LocalToast['type'] = 'info') => {
    const id = crypto.randomUUID()
    setToasts(prev => [...prev, { id, msg, type }])
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 3500)
  }, [])

  return { toasts, add }
}
