import React, { useState } from 'react'
import { X, ChevronDown, ChevronUp, ExternalLink } from 'lucide-react'
import { NODES, EDGES, ROUTES, GROUP_COLORS, methodColor, critColor } from './arch-data'

interface Props {
  nodeId:  string
  onClose: () => void
}

const GROUP_ICON: Record<string, string> = {
  external: '⬡',
  backend:  '◈',
  frontend: '◇',
  ai:       '◉',
}

export function NodeDetailPanel({ nodeId, onClose }: Props) {
  const [expandedRoute, setExpandedRoute] = useState<string | null>(null)

  const node = NODES.find(n => n.id === nodeId)
  if (!node) return null

  const incoming     = EDGES.filter(e => e.to   === nodeId)
  const outgoing     = EDGES.filter(e => e.from === nodeId)
  const nodeMap      = Object.fromEntries(NODES.map(n => [n.id, n]))
  const relatedRoutes = ROUTES.filter(r => node.relatedRouteIds?.includes(r.id))
  const gc           = GROUP_COLORS[node.group]

  return (
    <div style={{
      width: '100%', height: '100%',
      background: '#060e1a',
      borderLeft: `1px solid ${node.color}35`,
      display: 'flex', flexDirection: 'column',
      overflow: 'hidden',
      fontFamily: "'Consolas','Fira Code',monospace",
    }}>

      {/* ── Header ──────────────────────────────────────────────────────────── */}
      <div style={{
        padding: '14px 16px 12px',
        borderBottom: `1px solid ${node.color}25`,
        flexShrink: 0,
        background: `linear-gradient(135deg, ${node.color}0a, transparent)`,
      }}>
        {/* Group badge */}
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '8px' }}>
          <span style={{
            fontSize: '9px', color: gc.label,
            background: gc.bg, border: `1px solid ${gc.border}`,
            borderRadius: '5px', padding: '2px 8px',
            letterSpacing: '0.15em', fontWeight: 'bold',
            display: 'flex', alignItems: 'center', gap: '5px',
          }}>
            <span>{GROUP_ICON[node.group]}</span>
            {node.group.toUpperCase()}
          </span>
          <button onClick={onClose} style={{
            background: '#0a1830', border: '1px solid #1a3550',
            borderRadius: '6px', cursor: 'pointer',
            color: '#475569', padding: '4px 6px',
            display: 'flex', alignItems: 'center',
            transition: 'all 0.15s',
          }}>
            <X size={13} />
          </button>
        </div>

        {/* Node name */}
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '4px' }}>
          <div style={{
            width: 10, height: 10, borderRadius: '50%',
            background: node.color, flexShrink: 0,
            boxShadow: `0 0 8px ${node.color}`,
          }} />
          <span style={{
            color: node.color, fontWeight: 'bold',
            fontSize: '14px', letterSpacing: '0.06em',
          }}>
            {node.label}
          </span>
        </div>
        <div style={{ color: '#5a7a9a', fontSize: '10.5px', paddingLeft: '18px' }}>
          {node.sub}
        </div>
      </div>

      {/* ── Body ────────────────────────────────────────────────────────────── */}
      <div style={{ flex: 1, overflowY: 'auto', padding: '14px 16px' }}>

        {/* RESPONSIBILITIES */}
        <Section label="RESPONSIBILITIES" color={node.color}>
          {node.details.map((d, i) => (
            <div key={i} style={{
              display: 'flex', gap: '8px', marginBottom: '5px', alignItems: 'flex-start',
            }}>
              <span style={{ color: node.color, opacity: 0.7, flexShrink: 0, marginTop: '2px', fontSize: '10px' }}>▸</span>
              <span style={{ color: '#8ab0cc', fontSize: '11px', lineHeight: 1.55 }}>{d}</span>
            </div>
          ))}
        </Section>

        {/* SOURCE FILES */}
        {node.files.length > 0 && (
          <Section label="SOURCE FILES" color={node.color}>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
              {node.files.map(f => (
                <div key={f} style={{
                  background: '#0a1a2e', border: '1px solid #1a3550',
                  borderRadius: '5px', padding: '4px 10px',
                  display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                  gap: '6px',
                }}>
                  <code style={{ fontSize: '10px', color: '#38bdf8', flex: 1 }}>{f}</code>
                  <ExternalLink size={10} color="#1e3a5f" />
                </div>
              ))}
            </div>
          </Section>
        )}

        {/* CONNECTIONS */}
        {(incoming.length > 0 || outgoing.length > 0) && (
          <Section label={`CONNECTIONS (${outgoing.length + incoming.length})`} color={node.color}>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '3px' }}>
              {outgoing.map((e, i) => {
                const other = nodeMap[e.to]
                return (
                  <div key={`out-${i}`} style={{
                    display: 'flex', alignItems: 'center', gap: '7px',
                    background: '#080f1c', borderRadius: '5px', padding: '5px 8px',
                    border: `1px solid ${e.color}20`,
                  }}>
                    <span style={{
                      color: e.color, fontSize: '12px', width: '16px',
                      textAlign: 'center', flexShrink: 0,
                    }}>→</span>
                    <span style={{
                      color: other?.color ?? '#94a3b8', fontSize: '10.5px',
                      fontWeight: 'bold', minWidth: '90px',
                    }}>
                      {other?.label ?? e.to}
                    </span>
                    <span style={{
                      color: '#4a6b8a', fontSize: '9.5px',
                      background: '#0a1525', border: '1px solid #1a3550',
                      borderRadius: '3px', padding: '1px 6px',
                      flex: 1,
                    }}>{e.label}</span>
                    {e.dashed && (
                      <span style={{
                        color: '#334155', fontSize: '8px',
                        background: '#0a1525', borderRadius: '3px',
                        padding: '1px 4px',
                      }}>sekundāra</span>
                    )}
                  </div>
                )
              })}
              {incoming.map((e, i) => {
                const other = nodeMap[e.from]
                return (
                  <div key={`in-${i}`} style={{
                    display: 'flex', alignItems: 'center', gap: '7px',
                    background: '#080f1c', borderRadius: '5px', padding: '5px 8px',
                    border: `1px solid ${e.color}15`,
                    opacity: 0.8,
                  }}>
                    <span style={{
                      color: e.color, fontSize: '12px', width: '16px',
                      textAlign: 'center', flexShrink: 0, opacity: 0.7,
                    }}>←</span>
                    <span style={{
                      color: other?.color ?? '#94a3b8', fontSize: '10.5px',
                      fontWeight: 'bold', minWidth: '90px',
                    }}>
                      {other?.label ?? e.from}
                    </span>
                    <span style={{
                      color: '#4a6b8a', fontSize: '9.5px',
                      background: '#0a1525', border: '1px solid #1a3550',
                      borderRadius: '3px', padding: '1px 6px',
                      flex: 1,
                    }}>{e.label}</span>
                  </div>
                )
              })}
            </div>
          </Section>
        )}

        {/* RELATED API ROUTES */}
        {relatedRoutes.length > 0 && (
          <Section label={`RELATED API ROUTES (${relatedRoutes.length})`} color={node.color}>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '5px' }}>
              {relatedRoutes.map(route => {
                const isExp = expandedRoute === route.id
                const mc    = methodColor(route.method)
                const cc    = critColor(route.criticality)
                return (
                  <div key={route.id} style={{
                    background: '#08111e',
                    border: `1px solid ${isExp ? cc + '50' : '#162030'}`,
                    borderRadius: '7px', overflow: 'hidden',
                    transition: 'border-color 0.15s',
                  }}>
                    {/* Route header */}
                    <div
                      onClick={() => setExpandedRoute(isExp ? null : route.id)}
                      style={{
                        padding: '8px 10px', display: 'flex',
                        alignItems: 'center', gap: '7px', cursor: 'pointer',
                        background: isExp ? '#0a1525' : 'transparent',
                      }}
                    >
                      <span style={{
                        padding: '2px 7px', borderRadius: '4px',
                        fontSize: '9px', fontWeight: 'bold',
                        background: `${mc}22`, color: mc, flexShrink: 0,
                        letterSpacing: '0.05em',
                      }}>
                        {route.method}
                      </span>
                      <span style={{
                        padding: '2px 6px', borderRadius: '3px',
                        fontSize: '8.5px', background: `${cc}18`, color: cc,
                        flexShrink: 0,
                      }}>
                        {route.criticality}
                      </span>
                      <code style={{
                        color: route.criticality === 'REMOVED' ? '#2a3a4a' : '#b0cce0',
                        flex: 1, fontSize: '10.5px',
                        textDecoration: route.criticality === 'REMOVED' ? 'line-through' : 'none',
                        overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
                      }}>
                        {route.path}
                      </code>
                      {route.warnings?.length ? (
                        <span style={{ color: '#f59e0b', fontSize: '11px', flexShrink: 0 }}>⚠</span>
                      ) : null}
                      {isExp
                        ? <ChevronUp size={11} color="#2a4a6a" />
                        : <ChevronDown size={11} color="#2a4a6a" />
                      }
                    </div>

                    {/* Expanded route body */}
                    {isExp && (
                      <div style={{ borderTop: '1px solid #0d1e30', padding: '10px' }}>
                        <div style={{
                          color: '#5a7a9a', fontSize: '10.5px',
                          marginBottom: '10px', lineHeight: 1.6,
                        }}>
                          {route.description}
                        </div>

                        {route.frontendPages && (
                          <div style={{ marginBottom: '8px', display: 'flex', gap: '6px', alignItems: 'baseline' }}>
                            <span style={{ fontSize: '8px', color: '#2a4a6a', flexShrink: 0, letterSpacing: '0.15em' }}>PAGES</span>
                            <span style={{ color: '#38bdf8', fontSize: '10px' }}>{route.frontendPages.join(', ')}</span>
                          </div>
                        )}

                        {/* Request cycle */}
                        <div style={{
                          background: '#050c18', borderRadius: '6px',
                          border: '1px solid #0f2035', overflow: 'hidden',
                        }}>
                          {route.cycle.map((step, i) => (
                            <div key={i} style={{
                              display: 'grid',
                              gridTemplateColumns: '64px 1fr',
                              gap: '8px', padding: '5px 10px',
                              borderBottom: i < route.cycle.length - 1 ? '1px solid #0a1830' : 'none',
                              background: step.warning ? 'rgba(245,158,11,0.04)' : 'transparent',
                            }}>
                              <span style={{
                                fontSize: '8px',
                                color: step.warning ? '#f59e0b' : '#2a4a6a',
                                textTransform: 'uppercase',
                                letterSpacing: '0.06em',
                                paddingTop: 2,
                                fontWeight: 'bold',
                              }}>
                                {step.layer}
                              </span>
                              <div>
                                <span style={{ fontSize: '10.5px', color: step.warning ? '#f59e0b' : '#8ab0cc' }}>
                                  {step.detail}
                                </span>
                                {step.file && (
                                  <div style={{ fontSize: '8.5px', color: '#0369a1', marginTop: '1px' }}>
                                    {step.file}
                                  </div>
                                )}
                              </div>
                            </div>
                          ))}
                        </div>

                        {/* Warnings */}
                        {route.warnings?.length ? (
                          <div style={{
                            marginTop: '8px', padding: '8px 10px',
                            background: 'rgba(245,158,11,0.06)',
                            border: '1px solid rgba(245,158,11,0.2)',
                            borderRadius: '5px',
                          }}>
                            <div style={{
                            fontSize: '8px', color: '#d97706',
                            letterSpacing: '0.15em', marginBottom: '5px', fontWeight: 'bold',
                            }}>⚠ WARNINGS</div>
                            {route.warnings.map((w, i) => (
                              <div key={i} style={{
                                fontSize: '10.5px', color: '#f59e0b',
                                marginBottom: '3px', lineHeight: 1.5,
                              }}>
                                • {w}
                              </div>
                            ))}
                          </div>
                        ) : null}
                      </div>
                    )}
                  </div>
                )
              })}
            </div>
          </Section>
        )}
      </div>
    </div>
  )
}

// ─── Helper: section header ────────────────────────────────────────────────────
function Section({
  label, color, children,
}: { label: string; color: string; children: React.ReactNode }) {
  return (
    <div style={{ marginBottom: '16px' }}>
      <div style={{
        fontSize: '8.5px', color: '#2e5070',
        letterSpacing: '0.2em', marginBottom: '8px',
        fontWeight: 'bold', display: 'flex', alignItems: 'center', gap: '8px',
      }}>
        <span style={{ display: 'block', width: '16px', height: '1px', background: color + '50' }} />
        {label}
      </div>
      {children}
    </div>
  )
}
