// ═══════════════════════════════════════════════════════════════
// PRESTIGE DASHBOARD - STATUS DOT COMPONENT
// Simple animated status dot with pulse effect
// ═══════════════════════════════════════════════════════════════

import React from 'react'
import type { StatusConfig } from './StatusIndicator.types'

interface StatusDotProps {
  config: StatusConfig
  size: 'sm' | 'md' | 'lg' | 'xl'
  pulse?: boolean
  animated?: boolean
}

const SIZE_MAP = {
  sm: 'w-2 h-2',
  md: 'w-3 h-3',
  lg: 'w-4 h-4',
  xl: 'w-5 h-5',
}

/**
 * StatusDot Component
 * Animated dot indicator with optional pulse
 */
export const StatusDot: React.FC<StatusDotProps> = ({
  config,
  size,
  pulse = false,
  animated = true,
}) => {
  const shouldPulse = animated && pulse
  const sizeClass = SIZE_MAP[size] || SIZE_MAP.md

  return (
    <div className="relative inline-flex items-center justify-center">
      {/* Main dot */}
      <div
        className={`rounded-full ${sizeClass} transition-all duration-300`}
        style={{
          backgroundColor: config.color,
          boxShadow: `0 0 ${shouldPulse ? '10px' : '6px'} ${config.color}`,
        }}
      />
      
      {/* Pulse ring */}
      {shouldPulse && (
        <>
          <span
            className="absolute inset-0 rounded-full animate-ping opacity-75"
            style={{
              backgroundColor: config.color,
              animationDuration: '2s',
            }}
          />
          <span
            className="absolute inset-0 rounded-full animate-pulse"
            style={{
              backgroundColor: config.color,
              opacity: 0.5,
            }}
          />
        </>
      )}
    </div>
  )
}

StatusDot.displayName = 'StatusDot'

export default StatusDot
