// ─── PrintProgressPanel ───────────────────────────────────────
// Shows current print progress bar, filename, elapsed/remaining time and layers.

import { Layers } from 'lucide-react'
import { formatDuration } from '@/utils/formatting'
import type { Printer } from '@core/types/printer'

export function PrintProgressPanel({ printer }: { printer: Printer }) {
  const progress = printer.liveState?.progress
  if (!progress) return null

  return (
    <div className="bg-gray-900/50 border border-blue-500/30 rounded-lg p-4">
      <h3 className="flex items-center gap-2 text-sm font-semibold text-gray-200 mb-3">
        <Layers className="w-4 h-4 text-blue-400" />
        Print Progress
      </h3>

      <div className="text-xs text-gray-400 mb-2 truncate">
        📄 {progress.filename || 'Unknown file'}
      </div>

      <div className="mb-3">
        <div className="flex items-center justify-between text-xs mb-1">
          <span className="text-gray-400">Progress</span>
          <span className="font-mono font-bold text-blue-400">{progress.percentage.toFixed(1)}%</span>
        </div>
        <div className="h-3 bg-gray-700 rounded-full overflow-hidden">
          <div
            className="h-full bg-gradient-to-r from-blue-500 to-cyan-400 rounded-full transition-all duration-1000"
            style={{ width: `${progress.percentage}%` }}
          />
        </div>
      </div>

      <div className="grid grid-cols-3 gap-3 text-center">
        <div>
          <div className="text-xs text-gray-500">Elapsed</div>
          <div className="text-sm font-mono text-gray-200">{formatDuration(progress.timeElapsed)}</div>
        </div>
        <div>
          <div className="text-xs text-gray-500">Remaining</div>
          <div className="text-sm font-mono text-cyan-400">{formatDuration(progress.timeRemaining)}</div>
        </div>
        <div>
          <div className="text-xs text-gray-500">Layers</div>
          <div className="text-sm font-mono text-gray-200">
            {progress.currentLayer ?? '?'} / {progress.totalLayers ?? '?'}
          </div>
        </div>
      </div>
    </div>
  )
}
