// ─── Helpers ──────────────────────────────────────────────────────────────────

export function critColor(c: string): string {
  const m: Record<string, string> = { CRITICAL: '#ef4444', OPTIONAL: '#f59e0b', DEPRECATED: '#475569', REMOVED: '#1f2937' }
  return m[c] ?? '#475569'
}
export function methodColor(m: string): string {
  const map: Record<string, string> = { GET: '#10b981', POST: '#06b6d4', PUT: '#f59e0b', PATCH: '#f59e0b', DELETE: '#ef4444', WS: '#a855f7' }
  return map[m] ?? '#64748b'
}
export function moduleColor(m: string): string {
  const map: Record<string, string> = { printer: '#06b6d4', 'printer-proxy': '#0891b2', health: '#10b981', ai: '#a855f7', websocket: '#8b5cf6', gcode: '#ef4444' }
  return map[m] ?? '#475569'
}
export function moduleLabel(m: string): string {
  const map: Record<string, string> = { printer: '🖨 Printer', 'printer-proxy': '🔀 Proxy', 'printer-files': '📁 Files', health: '💚 Health', ai: '🤖 AI', websocket: '⚡ WS', gcode: '⌨ GCode' }
  return map[m] ?? m
}

