// PRESTIGE DASHBOARD - STATUS ANIMATIONS
// Animation utilities and configurations for status indicators
// ═══════════════════════════════════════════════════════════════

/**
 * Animation timing configurations
 */
export const ANIMATION_TIMINGS = {
  fast: '1s',
  normal: '2s',
  slow: '3s',
  verySlow: '4s',
} as const

/**
 * Animation easing functions
 */
export const ANIMATION_EASINGS = {
  linear: 'linear',
  easeIn: 'ease-in',
  easeOut: 'ease-out',
  easeInOut: 'ease-in-out',
  bounce: 'cubic-bezier(0.68, -0.55, 0.265, 1.55)',
} as const

/**
 * Pulse animation styles
 */
export const getPulseAnimation = (color: string, speed: keyof typeof ANIMATION_TIMINGS = 'normal') => ({
  animation: `pulse-glow ${ANIMATION_TIMINGS[speed]} ease-in-out infinite`,
  '@keyframes pulse-glow': {
    '0%, 100%': {
      boxShadow: `0 0 8px ${color}`,
      opacity: 1,
    },
    '50%': {
      boxShadow: `0 0 20px ${color}`,
      opacity: 0.8,
    },
  },
})

/**
 * Breathing animation styles
 */
export const getBreathingAnimation = (speed: keyof typeof ANIMATION_TIMINGS = 'slow') => ({
  animation: `breathing ${ANIMATION_TIMINGS[speed]} ease-in-out infinite`,
  '@keyframes breathing': {
    '0%, 100%': {
      opacity: 1,
    },
    '50%': {
      opacity: 0.6,
    },
  },
})

/**
 * Ping animation styles (expanding ring)
 */
export const getPingAnimation = (speed: keyof typeof ANIMATION_TIMINGS = 'normal') => ({
  animation: `ping ${ANIMATION_TIMINGS[speed]} cubic-bezier(0, 0, 0.2, 1) infinite`,
  '@keyframes ping': {
    '0%': {
      transform: 'scale(1)',
      opacity: 1,
    },
    '75%, 100%': {
      transform: 'scale(2)',
      opacity: 0,
    },
  },
})

/**
 * Fade in animation
 */
export const getFadeInAnimation = (duration: string = '300ms') => ({
  animation: `fade-in ${duration} ease-out`,
  '@keyframes fade-in': {
    from: {
      opacity: 0,
      transform: 'translateY(4px)',
    },
    to: {
      opacity: 1,
      transform: 'translateY(0)',
    },
  },
})

/**
 * Scale in animation
 */
export const getScaleInAnimation = (duration: string = '200ms') => ({
  animation: `scale-in ${duration} ease-out`,
  '@keyframes scale-in': {
    from: {
      opacity: 0,
      transform: 'scale(0.9)',
    },
    to: {
      opacity: 1,
      transform: 'scale(1)',
    },
  },
})

/**
 * Shake animation (for errors)
 */
export const getShakeAnimation = (duration: string = '500ms') => ({
  animation: `shake ${duration} ease-in-out`,
  '@keyframes shake': {
    '0%, 100%': { transform: 'translateX(0)' },
    '10%, 30%, 50%, 70%, 90%': { transform: 'translateX(-4px)' },
    '20%, 40%, 60%, 80%': { transform: 'translateX(4px)' },
  },
})

/**
 * Get animation class name based on status and mode
 */
export const getStatusAnimation = (
  status: string,
  mode: 'dot' | 'badge' | 'pulse' | 'icon' = 'badge'
): string => {
  const animations: Record<string, Record<string, string>> = {
    printing: {
      dot: 'animate-pulse',
      badge: 'animate-pulse-slow',
      pulse: 'animate-ping',
      icon: 'animate-spin-slow',
    },
    paused: {
      dot: 'animate-breathing',
      badge: 'animate-breathing',
      pulse: 'animate-pulse-slow',
      icon: 'animate-pulse',
    },
    error: {
      dot: 'animate-pulse-fast',
      badge: 'animate-pulse-fast',
      pulse: 'animate-ping-fast',
      icon: 'animate-shake',
    },
    ai_action: {
      dot: 'animate-glow',
      badge: 'animate-glow',
      pulse: 'animate-ping',
      icon: 'animate-pulse',
    },
    idle: {
      dot: '',
      badge: '',
      pulse: '',
      icon: '',
    },
    disconnected: {
      dot: '',
      badge: 'opacity-60',
      pulse: '',
      icon: 'opacity-60',
    },
  }

  return animations[status]?.[mode] || ''
}

/**
 * Transition classes for smooth state changes
 */
export const TRANSITION_CLASSES = {
  colors: 'transition-colors duration-300 ease-in-out',
  transform: 'transition-transform duration-200 ease-out',
  opacity: 'transition-opacity duration-300 ease-in-out',
  shadow: 'transition-shadow duration-300 ease-in-out',
  all: 'transition-all duration-300 ease-in-out',
} as const

