// PRESTIGE DASHBOARD - AI ANOMALY CARD COMPONENT
// ═══════════════════════════════════════════════════════════════

import React from 'react'

/**
 * Anomaly severity type
 */
export type AnomalySeverity = 'low' | 'medium' | 'high' | 'critical'

/**
 * Anomaly interface
 */
export interface Anomaly {
  id: string
  type: string
  severity: AnomalySeverity
  description: string
  detectedAt: string
  confidence: number
  resolved: boolean
  affectedComponent?: string
  suggestedAction?: string
}

export interface AIAnomalyCardProps {
  anomaly: Anomaly
  onResolve?: (id: string) => void
  onInvestigate?: (id: string) => void
  compact?: boolean
  className?: string
}

/**
 * Get severity config
 */
const getSeverityConfig = (severity: AnomalySeverity) => {
  const configs = {
    low: {
      severity: 'low' as const,
      icon: 'ℹ',
      label: 'LOW',
      color: '#0ff',
      glow: 'rgba(0, 255, 255, 0.3)',
    },
    medium: {
      severity: 'medium' as const,
      icon: '⚠',
      label: 'MEDIUM',
      color: '#ff0',
      glow: 'rgba(255, 255, 0, 0.3)',
    },
    high: {
      severity: 'high' as const,
      icon: '⚠',
      label: 'HIGH',
      color: '#f80',
      glow: 'rgba(255, 136, 0, 0.3)',
    },
    critical: {
      severity: 'critical' as const,
      icon: '🔴',
      label: 'CRITICAL',
      color: '#f00',
      glow: 'rgba(255, 0, 0, 0.3)',
    },
  }
  return configs[severity]
}

/**
 * Get anomaly type icon
 */
const getTypeIcon = (type: string): string => {
  const lowerType = type.toLowerCase()
  
  if (lowerType.includes('temperature')) return '🌡️'
  if (lowerType.includes('vibration')) return '📳'
  if (lowerType.includes('speed')) return '⚡'
  if (lowerType.includes('quality')) return '⭐'
  if (lowerType.includes('layer')) return '📐'
  if (lowerType.includes('flow')) return '💧'
  if (lowerType.includes('power')) return '🔋'
  if (lowerType.includes('motion')) return '🔄'
  if (lowerType.includes('mcu') || lowerType.includes('overtemp')) return '🖥️'

  return '🔍'
}

/**
 * Format relative time
 */
const formatRelativeTime = (timestamp: string): string => {
  const date = new Date(timestamp)
  const now = new Date()
  const diff = Math.floor((now.getTime() - date.getTime()) / 1000)

  if (diff < 60) return 'just now'
  if (diff < 3600) return `${Math.floor(diff / 60)}m ago`
  if (diff < 86400) return `${Math.floor(diff / 3600)}h ago`
  return `${Math.floor(diff / 86400)}d ago`
}

/**
 * AIAnomalyCard Component
 * Displays detected anomalies
 */
export const AIAnomalyCard: React.FC<AIAnomalyCardProps> = ({
  anomaly,
  onResolve,
  onInvestigate,
  compact = false,
  className = '',
}) => {
  const severityConfig = getSeverityConfig(anomaly.severity)
  const typeIcon = getTypeIcon(anomaly.type)

  if (compact) {
    return (
      <div
        className={`flex items-start gap-3 p-3 rounded-lg border ${
          anomaly.resolved ? 'opacity-60' : ''
        } ${className}`}
        style={{
          borderColor: `${severityConfig.color}30`,
          backgroundColor: `${severityConfig.color}05`,
        }}
      >
        {/* Icon */}
        <div className="flex-shrink-0 text-xl">{typeIcon}</div>

        {/* Content */}
        <div className="flex-1 min-w-0">
          <div className="flex items-start justify-between gap-2 mb-1">
            <p className="text-sm font-medium text-white line-clamp-2">
              {anomaly.description}
            </p>
            {anomaly.resolved && (
              <span className="flex-shrink-0 text-xs bg-green-500/20 border border-green-500/50 text-green-400 px-2 py-0.5 rounded">
                ✓ Resolved
              </span>
            )}
          </div>

          <div className="flex items-center gap-3 text-xs">
            <span style={{ color: severityConfig.color }} className="font-bold">
              {severityConfig.label}
            </span>
            <span className="text-gray-400">
              {formatRelativeTime(anomaly.detectedAt)}
            </span>
            <span className="font-mono text-gray-500">
              {(anomaly.confidence * 100).toFixed(0)}%
            </span>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div
      className={`flex flex-col gap-4 p-4 rounded-lg border ${
        anomaly.resolved ? 'opacity-70' : ''
      } ${className}`}
      style={{
        borderColor: `${severityConfig.color}30`,
        backgroundColor: `${severityConfig.color}05`,
      }}
    >
      {/* Header */}
      <div className="flex items-start gap-3">
        {/* Icon */}
        <div
          className={`flex-shrink-0 w-10 h-10 rounded-lg flex items-center justify-center text-xl ${
            !anomaly.resolved && severityConfig.severity !== 'low' ? 'animate-pulse' : ''
          }`}
          style={{
            backgroundColor: `${severityConfig.color}20`,
            border: `1px solid ${severityConfig.color}50`,
          }}
        >
          {typeIcon}
        </div>

        {/* Title & Severity */}
        <div className="flex-1 min-w-0">
          <div className="flex items-start justify-between gap-2 mb-1">
            <div className="flex items-center gap-2">
              <span className="text-xs font-bold px-2 py-0.5 rounded" style={{ color: severityConfig.color }}>
                {severityConfig.icon} {severityConfig.label}
              </span>
              {anomaly.resolved && (
                <span className="text-xs bg-green-500/20 border border-green-500/50 text-green-400 px-2 py-0.5 rounded">
                  ✓ Resolved
                </span>
              )}
            </div>
          </div>
          <h4 className="font-bold text-white">{anomaly.type}</h4>
        </div>
      </div>

      {/* Description */}
      <p className="text-sm text-gray-300 leading-relaxed">
        {anomaly.description}
      </p>

      {/* Affected Component */}
      {anomaly.affectedComponent && (
        <div className="flex items-center gap-2 p-2 rounded bg-gray-800/50 border border-gray-700">
          <span className="text-xs text-gray-400">Component:</span>
          <span className="text-sm font-medium text-white">{anomaly.affectedComponent}</span>
        </div>
      )}

      {/* Suggested Action */}
      {anomaly.suggestedAction && (
        <div className="flex flex-col gap-2 p-3 rounded-lg bg-gray-800/50 border border-gray-700">
          <div className="text-xs font-medium text-gray-400">Suggested Action:</div>
          <div className="flex items-start gap-2">
            <span className="text-cyan-400 flex-shrink-0">→</span>
            <span className="text-sm text-gray-200">{anomaly.suggestedAction}</span>
          </div>
        </div>
      )}

      {/* Confidence & Time */}
      <div className="flex items-center justify-between text-xs">
        <div className="flex items-center gap-2">
          <span className="text-gray-400">Confidence:</span>
          <span className="font-mono font-bold text-purple-400">
            {(anomaly.confidence * 100).toFixed(0)}%
          </span>
        </div>
        <span className="text-gray-500">
          Detected {formatRelativeTime(anomaly.detectedAt)}
        </span>
      </div>

      {/* Actions */}
      {!anomaly.resolved && (onResolve || onInvestigate) && (
        <div className="flex items-center gap-2 pt-2 border-t border-gray-800">
          {onInvestigate && (
            <button
              onClick={() => onInvestigate(anomaly.id)}
              className="flex-1 px-4 py-2 rounded-lg text-sm font-medium border transition-all hover:bg-gray-800"
              style={{
                borderColor: `${severityConfig.color}50`,
                color: severityConfig.color,
              }}
            >
              Investigate
            </button>
          )}
          {onResolve && (
            <button
              onClick={() => onResolve(anomaly.id)}
              className="px-4 py-2 rounded-lg text-sm font-medium bg-green-500/20 border border-green-500/50 text-green-400 hover:bg-green-500/30 transition-all"
            >
              Mark Resolved
            </button>
          )}
        </div>
      )}
    </div>
  )
}

AIAnomalyCard.displayName = 'AIAnomalyCard'

export default AIAnomalyCard
