import React from 'react'

export interface SettingsSectionProps {
  title: string
  description?: string
  icon?: React.ReactNode
  children: React.ReactNode
  collapsible?: boolean
  defaultExpanded?: boolean
  className?: string
}

/**
 * SettingsSection Component
 * Container for grouped settings
 */
export const SettingsSection: React.FC<SettingsSectionProps> = ({
  title,
  description,
  icon,
  children,
  collapsible = false,
  defaultExpanded = true,
  className = '',
}) => {
  const [isExpanded, setIsExpanded] = React.useState(defaultExpanded)

  const toggleExpanded = () => {
    if (collapsible) {
      setIsExpanded(!isExpanded)
    }
  }

  return (
    <div
      className={`flex flex-col gap-4 p-5 rounded-lg border border-gray-800 bg-gray-900/50 ${className}`}
    >
      {/* Header */}
      <div
        className={`flex items-start justify-between ${collapsible ? 'cursor-pointer' : ''}`}
        onClick={toggleExpanded}
      >
        <div className="flex items-start gap-3">
          {icon && <div className="flex-shrink-0">{icon}</div>}
          <div>
            <h3 className="text-lg font-bold text-white">{title}</h3>
            {description && (
              <p className="text-sm text-gray-400 mt-1">{description}</p>
            )}
          </div>
        </div>

        {collapsible && (
          <button
            className="text-gray-400 hover:text-gray-200 transition-colors"
            aria-label={isExpanded ? 'Collapse' : 'Expand'}
          >
            <svg
              className={`w-5 h-5 transition-transform ${isExpanded ? 'rotate-180' : ''}`}
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M19 9l-7 7-7-7"
              />
            </svg>
          </button>
        )}
      </div>

      {/* Content */}
      {(!collapsible || isExpanded) && (
        <div className="flex flex-col gap-4 pt-2 border-t border-gray-800">
          {children}
        </div>
      )}
    </div>
  )
}

SettingsSection.displayName = 'SettingsSection'

export default SettingsSection
