/**
 * Printer connection status.
 *
 * Backend canonical states (printer.types.ts):
 *   disconnected | connecting | idle | printing | paused | error | maintenance
 *
 * Frontend-only states (never sent by backend, set locally):
 *   ai_action — used while an AI-initiated action is executing
 *
 * 'connecting' is normalised to 'idle' in useWebSocketIntegration STATUS_MAP
 * to avoid showing a transient state in the UI. If a connecting indicator
 * is needed, un-map it there and add UI handling.
 */
export type PrinterStatus =
  | 'idle'
  | 'printing'
  | 'paused'
  | 'error'
  | 'disconnected'
  | 'connecting'   // backend state — currently normalised to 'idle' in WS layer
  | 'maintenance'
  | 'ai_action'    // frontend-only — never sent by backend

/**
 * Printer sub-status — mirrors backend PrinterSubStatus exactly.
 *
 * NOTE: 'cancelling' here is a PRINTER sub-state (cancel command sent,
 * awaiting adapter confirmation) — NOT to be confused with JobStatus
 * 'cancelling' which is a job-level transient state.
 * Always check the source type before comparing: printer.subStatus vs job.status.
 */
export type PrinterSubStatus =
  // Disconnected
  | 'never_connected' | 'connection_lost' | 'user_disconnected'
  // Connecting
  | 'handshaking' | 'authenticating' | 'initializing'
  // Idle
  | 'ready' | 'heating' | 'cooling' | 'homing'
  // Printing
  | 'preparing' | 'in_progress' | 'finishing'
  // Paused — 'cancelling' = transient: cancel sent, waiting for adapter
  | 'user_paused' | 'filament_change' | 'awaiting_input' | 'cancelling'
  // Error
  | 'thermal_runaway' | 'communication_error' | 'firmware_error' | 'sensor_error' | 'print_error'
  // Maintenance
  | 'calibrating' | 'cleaning' | 'upgrading'

/**
 * Printer adapter type — must match backend AdapterType exactly.
 * 'prusalink' and 'custom' are UI-only aliases, never sent to backend.
 */
export type AdapterType = 'mock' | 'moonraker' | 'octoprint'

/**
 * Parse the hostname from a connectionUrl (e.g. "http://192.168.1.5:7125").
 * Falls back to the raw string if it is not a valid URL.
 */
export function parseConnectionHost(url: string | null | undefined): string {
  if (!url) return 'N/A'
  try { return new URL(url).hostname } catch { return url }
}

/**
 * Parse the port number from a connectionUrl.
 * Returns null when the URL has no explicit port.
 */
export function parseConnectionPort(url: string | null | undefined): number | null {
  if (!url) return null
  try {
    const p = new URL(url).port
    return p ? parseInt(p, 10) : null
  } catch { return null }
}

/**
 * Temperature reading for a component.
 *
 * Backend sends `actual` (Moonraker/Klipper native field name).
 * Frontend historically used `current` — both are accepted so that
 * REST responses and WebSocket payloads work without runtime coercion.
 * Prefer `actual` when reading; `current` is kept for backward compat.
 */
export interface TemperatureReading {
  /** Moonraker/backend native field — use this when reading */
  actual?: number
  /** Legacy alias — populated by WS layer from `actual` */
  current?: number
  target: number
  power?: number // 0-1 heater power
}

/**
 * Printer temperatures
 */
export interface PrinterTemperatures {
  hotend: TemperatureReading
  bed: TemperatureReading
  chamber?: TemperatureReading
}

/**
 * Printer position in 3D space
 */
export interface PrinterPosition {
  x: number
  y: number
  z: number
  e?: number // extruder position
}

/**
 * Print progress information
 */
export interface PrintProgress {
  percentage: number
  timeElapsed: number // seconds
  timeRemaining: number // seconds
  currentLayer?: number
  totalLayers?: number
  filename?: string
  filePath?: string
  thumbnailUrl?: string
}

/**
 * Fan speeds
 */
export interface PrinterFans {
  partCooling: number // 0-100
  hotendFan: number // 0-100
  exhaustFan?: number // 0-100
}

/**
 * Speed settings
 */
export interface PrinterSpeed {
  feedrate: number // percentage, 100 = normal
  flowrate: number // percentage, 100 = normal
}

/**
 * Printer capabilities
 */
export interface PrinterCapabilities {
  hasBedMesh: boolean
  hasFilamentSensor: boolean
  hasPowerControl: boolean
  hasCamera: boolean
  hasAccelerometer: boolean
  hasEnclosure: boolean
  maxHotendTemp: number
  maxBedTemp: number
  buildVolume: {
    x: number
    y: number
    z: number
  }
}

/**
 * Printer connection configuration
 */
export interface PrinterConnection {
  type: AdapterType
  host: string
  port: number
  apiKey?: string
  secure?: boolean
}

/**
 * Live printer state (real-time data)
 */
export interface PrinterLiveState {
  temperatures: PrinterTemperatures
  position: PrinterPosition
  progress?: PrintProgress
  fans: PrinterFans
  speed: PrinterSpeed
  isPowerOn?: boolean
  doorOpen?: boolean
  filamentDetected?: boolean
}

/**
 * Printer maintenance record
 */
export interface MaintenanceRecord {
  id: string
  type: 'belt_tension' | 'lubrication' | 'nozzle_change' | 'bed_level' | 'firmware' | 'other'
  description: string
  performedAt: string
  performedBy?: string
  notes?: string
}

/**
 * Printer settings
 */
export interface PrinterSettings {
  name?: string
  type?: string
  notes?: string
  tags?: string[]
  aiEnabled?: boolean
  [key: string]: unknown // Allow additional settings
}

/**
 * AI Configuration for printer
 */
export interface AIConfig {
  enabled: boolean
  level: number // 1-3: monitoring level
  autoAdjust?: boolean
  notifications?: boolean
}

/**
 * Full printer object — mirrors backend Printer + BaseEntity exactly.
 *
 * Backend fields (from prestige-backend/src/types/printer.types.ts):
 *   adapterType, connectionUrl, apiKey, subStatus, isLocked, lockReason,
 *   firmwareName, firmwareVersion, printerModel, enabled, autoReconnect,
 *   pollingIntervalMs, lastSeenAt
 *
 * Frontend-only fields (not in backend, populated by AI/UI layer):
 *   liveState, qualityScore, healthScore, capabilities, aiConfig,
 *   maintenanceHistory, nextMaintenanceDue, notes, tags
 *
 * REMOVED (were never in backend):
 *   type (was string like "Voron 2.4") → use adapterType
 *   connection: { type, host, port } → use connectionUrl + parseConnectionHost()
 *   lastSeen → renamed to lastSeenAt to match backend
 */
export interface Printer {
  // ── BaseEntity ────────────────────────────────────────────
  id: string
  createdAt: string
  updatedAt: string

  // ── Core (backend canonical fields) ───────────────────────
  name: string
  adapterType: AdapterType
  connectionUrl: string | null
  apiKey: string | null
  status: PrinterStatus
  subStatus: PrinterSubStatus | null  // typed — use PrinterSubStatus, not string
  isLocked: boolean
  lockReason: string | null

  // ── Hardware info ─────────────────────────────────────────
  firmwareName: string | null
  firmwareVersion: string | null
  printerModel: string | null

  // ── Config ───────────────────────────────────────────────
  enabled: boolean
  autoReconnect: boolean
  pollingIntervalMs: number

  // ── Timestamps ───────────────────────────────────────────
  lastSeenAt: string | null   // renamed from lastSeen — matches backend field

  // ── Runtime state (frontend-only, populated by WS) ────────
  liveState?: PrinterLiveState

  // ── AI / quality (frontend-only, populated by AI service) ─
  aiConfig?: AIConfig
  qualityScore?: number        // 0-100
  healthScore?: number         // 0-100
  capabilities?: PrinterCapabilities

  // ── Maintenance (frontend-only) ───────────────────────────
  maintenanceHistory?: MaintenanceRecord[]
  nextMaintenanceDue?: string

  // ── UI metadata (frontend-only) ───────────────────────────
  notes?: string
  tags?: string[]
}

/**
 * Printer event types
 */
export type PrinterEventType =
  | 'status_change'
  | 'temperature_update'
  | 'progress_update'
  | 'print_started'
  | 'print_completed'
  | 'print_failed'
  | 'print_paused'
  | 'print_resumed'
  | 'error'
  | 'warning'
  | 'filament_runout'
  | 'power_loss'
  | 'door_opened'

/**
 * Printer event
 */
export interface PrinterEvent {
  id: string
  printerId: string
  type: PrinterEventType
  message: string
  data?: Record<string, unknown>
  timestamp: string
  acknowledged?: boolean
}

/**
 * Printer command types — MUST match backend commandDispatch keys in printer.routes.ts.
 *
 * Backend canonical keys (dash-separated):
 *   home | home-x | home-y | home-z
 *   fan-on | fan-off | set_fan_speed | set_named_fan_speed
 *   pause | resume | cancel | emergency_stop | e-stop
 *   set_hotend_temperature | set_bed_temperature | gcode
 *
 * Backend ALIASES (normalised before dispatch, also accepted):
 *   home-all / home_all → home
 *   fan_on → fan-on | fan_off → fan-off
 *   set_temperature → set_hotend_temperature
 *
 * Frontend-only types (no backend handler — handled client-side or TODO):
 *   move | power_on | power_off | run_macro
 */
export type PrinterCommandType =
  // Homing — backend canonical keys
  | 'home'
  | 'home-x'
  | 'home-y'
  | 'home-z'
  // Homing aliases (accepted by backend ALIASES map)
  | 'home_x'
  | 'home_y'
  | 'home_z'
  // Fan control
  | 'fan-on'
  | 'fan-off'
  | 'set_fan_speed'
  | 'set_named_fan_speed'
  // Print control
  | 'pause'
  | 'resume'
  | 'cancel'
  | 'emergency_stop'
  | 'e-stop'
  // Temperature
  | 'set_hotend_temperature'
  | 'set_bed_temperature'
  | 'set_temperature'         // alias → set_hotend_temperature (backend ALIASES)
  // Free GCode
  | 'gcode'
  // Frontend-only (no backend handler yet)
  | 'move'
  | 'power_on'
  | 'power_off'
  | 'run_macro'

/**
 * Printer command
 */
export interface PrinterCommand {
  type?: PrinterCommandType
  action?: string // Alternative command field
  params?: Record<string, unknown>
  timestamp?: string // When the command was issued
}

/**
 * Printer filter options
 */
export interface PrinterFilters {
  status?: PrinterStatus[]
  type?: string[]
  tags?: string[]
  search?: string
}

/**
 * Print job — shared between printer-api.ts and HistoryList.tsx.
 * Single source of truth to avoid inline duplicate definitions.
 *
 * NOTE: 'cancelling' is a JOB-level transient state (job.types.ts JobStatus).
 * Not to be confused with printer.subStatus 'cancelling' (printer-level cancel).
 */
export interface PrintJob {
  id: string
  printerId: string
  printerName: string
  filename: string
  status: 'completed' | 'failed' | 'cancelled' | 'cancelling' | 'printing'
  startTime: string
  endTime?: string
  duration?: number   // seconds
  progress?: number   // 0-100
  filamentUsed?: number // mm
  metadata?: {
    layerHeight?: number
    totalLayers?: number
    estimatedTime?: number
  }
}

/**
 * Printer sort options
 */
export interface PrinterSort {
  field: 'name' | 'status' | 'type' | 'lastSeenAt' | 'qualityScore'
  direction: 'asc' | 'desc'
}
