// ═══════════════════════════════════════════════════════════════
// PRESTIGE DASHBOARD - BED MESH VIEW
// ═══════════════════════════════════════════════════════════════

import { useState, useEffect, useCallback } from 'react'
import { Grid3x3, RefreshCw, BarChart3, Layers, AlertTriangle, FlaskConical, Settings } from 'lucide-react'
import { BedMeshHeatmap } from './BedMeshHeatmap'
import { MeshHistoryChart } from './MeshHistoryChart'
import { useAsyncAction } from '@core/hooks/useAsyncAction'
import { useThrottledCallback } from '@core/hooks/useThrottledCallback'

interface BedMeshData {
  profileName: string
  meshMin: [number, number]
  meshMax: [number, number]
  probeCount: [number, number]
  meshMatrix: number[][]
  probedAt?: string
}

interface BedMeshViewProps {
  printerId: string
  printerName?: string
}

// ── Demo mesh: realistic 5×5 warped bed ──────────────────────
const DEMO_MESH: BedMeshData = {
  profileName: 'demo',
  meshMin: [20, 20],
  meshMax: [200, 200],
  probeCount: [5, 5],
  meshMatrix: [
    [-0.045, -0.032, -0.018,  0.012,  0.038],
    [-0.028, -0.012,  0.004,  0.021,  0.044],
    [-0.011,  0.003,  0.015,  0.028,  0.051],
    [ 0.008,  0.019,  0.031,  0.042,  0.063],
    [ 0.024,  0.038,  0.052,  0.067,  0.089],
  ],
  probedAt: new Date(Date.now() - 1000 * 60 * 60 * 3).toISOString(), // 3h ago
}

const DEMO_HISTORY = [
  { date: new Date(Date.now() - 1000 * 60 * 60 * 48).toISOString(), range: 0.142, mean: 0.021 },
  { date: new Date(Date.now() - 1000 * 60 * 60 * 24).toISOString(), range: 0.128, mean: 0.018 },
  { date: new Date(Date.now() - 1000 * 60 * 60 * 12).toISOString(), range: 0.118, mean: 0.015 },
  { date: new Date(Date.now() - 1000 * 60 * 60 * 3).toISOString(),  range: 0.134, mean: 0.019 },
]

export function BedMeshView({ printerId, printerName }: BedMeshViewProps) {
  const [meshData, setMeshData] = useState<BedMeshData | null>(null)
  const [isDemoData, setIsDemoData] = useState(false)
  // Load history from localStorage on mount
  const [meshHistory, setMeshHistory] = useState<Array<{ date: string; range: number; mean: number }>>(() => {
    try {
      const stored = localStorage.getItem(`bedMeshHistory_${printerId}`)
      return stored ? JSON.parse(stored) : []
    } catch {
      return []
    }
  })
  const [view, setView] = useState<'heatmap' | 'history'>('heatmap')
  const [showValues, setShowValues] = useState(true)
  const [calibrationStatus, setCalibrationStatus] = useState<string>('')

  const baseUrl = import.meta.env.VITE_API_URL || 'http://localhost:3002'

  // Helper: send gcode via backend direct proxy (bypasses connection check)
  const sendGcode = async (cmd: string): Promise<void> => {
    console.log(`[BedMeshView] Sending G-code: ${cmd}`)
    console.log(`[BedMeshView] API URL: ${baseUrl}/api/printers/${printerId}/gcode-direct`)
    
    try {
      const res = await fetch(`${baseUrl}/api/printers/${printerId}/gcode-direct`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ gcode: cmd }),
      })
      
      console.log(`[BedMeshView] Response status: ${res.status}`)
      
      if (!res.ok) {
        const data = await res.json().catch(() => ({}))
        console.error(`[BedMeshView] Error response:`, data)
        throw new Error(data.error || `HTTP ${res.status}`)
      }
      
      const data = await res.json()
      console.log(`[BedMeshView] Success response:`, data)
    } catch (error) {
      console.error(`[BedMeshView] sendGcode failed:`, error)
      throw error
    }
  }

  // Fetch current bed mesh via backend proxy (no Private Network Access)
  const fetchMesh = useAsyncAction(async () => {
    // Query Moonraker through backend proxy — no direct browser→printer request
    const res = await fetch(`${baseUrl}/api/printers/${printerId}/moonraker-query?objects=bed_mesh`)
    if (!res.ok) throw new Error(`HTTP ${res.status}`)
    const data = await res.json()
    if (data?.success === false) throw new Error(data.error || 'Backend proxy error')

    const bedMesh = data?.result?.status?.bed_mesh
    if (!bedMesh || !bedMesh.probed_matrix || bedMesh.probed_matrix.length === 0) {
      throw new Error('No bed mesh data available. Run BED_MESH_CALIBRATE first.')
    }

    const mesh: BedMeshData = {
      profileName: bedMesh.profile_name || 'default',
      meshMin: bedMesh.mesh_min || [0, 0],
      meshMax: bedMesh.mesh_max || [220, 220],
      probeCount: [
        bedMesh.probed_matrix?.[0]?.length || 0,
        bedMesh.probed_matrix?.length || 0,
      ],
      meshMatrix: bedMesh.probed_matrix,
      probedAt: new Date().toISOString(),
    }

    setMeshData(mesh)
    setIsDemoData(false)

    const allValues = mesh.meshMatrix.flat()
    const min = Math.min(...allValues)
    const max = Math.max(...allValues)
    const mean = allValues.reduce((a, b) => a + b, 0) / allValues.length

    setMeshHistory(prev => {
      const entry = { date: mesh.probedAt || new Date().toISOString(), range: max - min, mean }
      // Check if this is a duplicate based on timestamp (within 10 seconds) OR exact values
      const isDuplicate = prev.some(p => {
        const timeDiff = Math.abs(new Date(p.date).getTime() - new Date(entry.date).getTime())
        const isSameTime = timeDiff < 10000 // within 10 seconds
        const isSameValues = Math.abs(p.range - entry.range) < 0.0001 && Math.abs(p.mean - entry.mean) < 0.0001
        return isSameTime || (isSameValues && timeDiff < 60000) // same values within 1 min
      })
      
      if (isDuplicate) {
        console.log('[BedMeshView] Skipping duplicate history entry')
        return prev
      }
      
      const newHistory = [...prev, entry].slice(-20)
      console.log('[BedMeshView] Adding new history entry:', entry)
      // Save to localStorage
      try {
        localStorage.setItem(`bedMeshHistory_${printerId}`, JSON.stringify(newHistory))
      } catch (e) {
        console.warn('[BedMeshView] Failed to save history to localStorage:', e)
      }
      return newHistory
    })

    return mesh
  })

  // Trigger calibration via gcode-direct
  const calibrateAction = useAsyncAction(async () => {
    console.log(`[BedMeshView] Starting calibration for printer: ${printerId}`)
    setCalibrationStatus('Sending calibration command...')
    
    try {
      await sendGcode('BED_MESH_CALIBRATE')
      setCalibrationStatus('Calibration started. Please wait 2-3 minutes...')
      console.log(`[BedMeshView] Calibration command sent successfully`)
    } catch (error) {
      console.error(`[BedMeshView] Calibration failed:`, error)
      setCalibrationStatus('')
      throw error
    }
  })

  const throttledRefresh = useThrottledCallback(() => {
    fetchMesh.execute()
  }, 5000)

  // On mount: try real data, fall back to demo
  useEffect(() => {
    fetchMesh.execute().catch(() => {
      setMeshData(DEMO_MESH)
      setIsDemoData(true)
      setMeshHistory(DEMO_HISTORY)
    })
  }, [printerId])

  // Also show demo if fetch errored and no data yet
  useEffect(() => {
    if (fetchMesh.error && !meshData) {
      setMeshData(DEMO_MESH)
      setIsDemoData(true)
      setMeshHistory(DEMO_HISTORY)
    }
  }, [fetchMesh.error, meshData])

  const handleCalibrate = useCallback(async () => {
    console.log(`[BedMeshView] handleCalibrate called`)
    
    try {
      await calibrateAction.execute()
      
      // BED_MESH_CALIBRATE takes time — poll every 5s for up to 3 minutes
      let attempts = 0
      const maxAttempts = 36 // 3 minutes at 5s intervals
      
      const poll = setInterval(() => {
        attempts++
        console.log(`[BedMeshView] Poll attempt ${attempts}/${maxAttempts}`)
        
        setCalibrationStatus(`Checking for mesh data... (${attempts}/${maxAttempts})`)
        
        fetchMesh.execute()
          .then(() => {
            console.log(`[BedMeshView] Mesh data found, stopping poll`)
            setCalibrationStatus('Calibration complete!')
            clearInterval(poll)
            setTimeout(() => setCalibrationStatus(''), 3000)
          })
          .catch((err) => {
            console.log(`[BedMeshView] Poll attempt ${attempts} failed:`, err.message)
            if (attempts >= maxAttempts) {
              console.log(`[BedMeshView] Max attempts reached, stopping poll`)
              setCalibrationStatus('Calibration timed out. Please check printer status.')
              clearInterval(poll)
              setTimeout(() => setCalibrationStatus(''), 5000)
            }
          })
      }, 5000)
      
    } catch (error) {
      console.error(`[BedMeshView] handleCalibrate error:`, error)
      setCalibrationStatus(`Error: ${error instanceof Error ? error.message : 'Unknown error'}`)
    }
  }, [calibrateAction, fetchMesh])

  // Compute stats from current mesh
  const stats = meshData ? (() => {
    const all = meshData.meshMatrix.flat()
    const min = Math.min(...all)
    const max = Math.max(...all)
    const mean = all.reduce((a, b) => a + b, 0) / all.length
    const range = max - min
    const variance = all.reduce((sum, v) => sum + Math.pow(v - mean, 2), 0) / all.length
    const stdDev = Math.sqrt(variance)
    return { min, max, mean, range, stdDev, points: all.length }
  })() : null

  const qualityLabel = stats
    ? stats.range < 0.1 ? { text: 'Excellent', color: 'text-green-400' }
    : stats.range < 0.2 ? { text: 'Good', color: 'text-primary' }
    : stats.range < 0.4 ? { text: 'Fair', color: 'text-yellow-400' }
    : { text: 'Poor', color: 'text-state-error' }
    : null

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-3">
      {/* Main content area */}
      <div className="lg:col-span-7">
        {/* Bed Mesh Visualization Panel */}
        <div className="bg-gray-900/50 border border-gray-700 rounded-lg p-3">
          <div className="flex items-center justify-between mb-2">
            <h3 className="flex items-center gap-2 text-sm font-semibold text-gray-200">
              <Grid3x3 className="w-4 h-4 text-cyan-400" />
              Bed Mesh
              {meshData && (
                <span className="text-xs text-gray-400 bg-gray-800 px-2 py-0.5 rounded">
                  {meshData.profileName} — {meshData.probeCount[0]}×{meshData.probeCount[1]}
                </span>
              )}
            </h3>
            <div className="flex items-center gap-2">
              {/* View toggle */}
              <div className="flex rounded-lg border border-gray-600 overflow-hidden">
                <button
                  onClick={() => setView('heatmap')}
                  className={`px-2 py-1 text-xs flex items-center gap-1 transition-colors ${
                    view === 'heatmap' ? 'bg-cyan-500/20 text-cyan-400' : 'text-gray-400 hover:text-gray-200'
                  }`}
                >
                  <Layers className="w-3.5 h-3.5" /> Heatmap
                </button>
                <button
                  onClick={() => setView('history')}
                  className={`px-2 py-1 text-xs flex items-center gap-1 transition-colors ${
                    view === 'history' ? 'bg-cyan-500/20 text-cyan-400' : 'text-gray-400 hover:text-gray-200'
                  }`}
                >
                  <BarChart3 className="w-3.5 h-3.5" /> History
                </button>
              </div>

              <button
                onClick={throttledRefresh}
                disabled={fetchMesh.loading}
                className="p-1.5 rounded-lg border border-gray-600 text-gray-400 hover:text-cyan-400 hover:border-cyan-500 disabled:opacity-40 transition-colors"
              >
                <RefreshCw className={`w-4 h-4 ${fetchMesh.loading ? 'animate-spin' : ''}`} />
              </button>
            </div>
          </div>

          {/* Demo notice banner */}
          {isDemoData && (
            <div className="flex items-center gap-2 p-2 mb-2 rounded-lg bg-yellow-400/5 border border-yellow-400/20">
              <FlaskConical className="w-3.5 h-3.5 text-yellow-400 flex-shrink-0" />
              <span className="text-xs text-yellow-400/90">
                Showing demo data — no real bed mesh found. Run <code className="font-mono bg-yellow-400/10 px-1 rounded">BED_MESH_CALIBRATE</code> on your printer to load real data.
              </span>
            </div>
          )}

          {/* Calibration status banner */}
          {calibrationStatus && (
            <div className="flex items-center gap-2 p-2 mb-2 rounded-lg bg-blue-500/10 border border-blue-500/30">
              <RefreshCw className="w-3.5 h-3.5 text-blue-400 flex-shrink-0 animate-spin" />
              <span className="text-xs text-blue-400">{calibrationStatus}</span>
            </div>
          )}

          {/* Calibration error */}
          {calibrateAction.error && (
            <div className="flex items-center gap-2 p-2 mb-2 rounded-lg bg-red-500/10 border border-red-500/30">
              <AlertTriangle className="w-3.5 h-3.5 text-red-400 flex-shrink-0" />
              <span className="text-xs text-red-400">{calibrateAction.error}</span>
            </div>
          )}

          {/* Content */}
          {view === 'heatmap' && meshData && (
            <div className="flex justify-center">
              <BedMeshHeatmap
                meshData={meshData.meshMatrix}
                meshMin={meshData.meshMin}
                meshMax={meshData.meshMax}
                showValues={showValues}
                size={280}
              />
            </div>
          )}

          {view === 'history' && (
            <MeshHistoryChart history={meshHistory} />
          )}

          {fetchMesh.loading && !meshData && (
            <div className="text-center py-8 text-gray-400">
              <RefreshCw className="w-6 h-6 mx-auto mb-2 animate-spin opacity-30" />
              <p className="text-xs">Loading mesh data...</p>
            </div>
          )}
        </div>
      </div>

      {/* Sidebar */}
      <div className="lg:col-span-5 space-y-3">
        {/* Mesh Statistics Panel */}
        {stats && (
          <div className="bg-gray-900/50 border border-gray-700 rounded-lg p-2.5">
            <h3 className="flex items-center gap-2 text-sm font-semibold text-gray-200 mb-2">
              <BarChart3 className="w-4 h-4 text-cyan-400" />
              Mesh Statistics
              {isDemoData && <span className="ml-2 text-xs font-normal text-yellow-400/70">(demo)</span>}
            </h3>
            
            <div className="grid grid-cols-2 gap-2 mb-2">
              {[
                { label: 'MIN Z',   value: stats.min,    suffix: ' mm', color: 'text-blue-400' },
                { label: 'MAX Z',   value: stats.max,    suffix: ' mm', color: 'text-red-400' },
                { label: 'RANGE',   value: stats.range,  suffix: ' mm', color: isDemoData ? 'text-yellow-400' : (qualityLabel?.color || 'text-gray-200') },
                { label: 'MEAN',    value: stats.mean,   suffix: ' mm', color: 'text-gray-200' },
                { label: 'STD DEV', value: stats.stdDev, suffix: ' mm', color: 'text-gray-400' },
                { label: 'POINTS',  value: stats.points, suffix: '',    color: 'text-gray-400' },
              ].map(s => (
                <div key={s.label} className="bg-gray-800/50 rounded-lg p-2">
                  <div className="text-[10px] text-gray-400 mb-0.5">{s.label}</div>
                  <div className={`text-sm font-mono font-bold ${s.color}`}>
                    {typeof s.value === 'number' && s.suffix.includes('mm') 
                      ? s.value.toFixed(4) 
                      : s.value
                    }{s.suffix}
                  </div>
                </div>
              ))}
            </div>

            {qualityLabel && !isDemoData && (
              <div className="flex items-center justify-between p-2 rounded-lg bg-gray-800/50">
                <span className="text-xs text-gray-400">Mesh Quality</span>
                <span className={`text-xs font-bold ${qualityLabel.color}`}>
                  {qualityLabel.text}
                </span>
              </div>
            )}
          </div>
        )}

        {/* Mesh Info Panel */}
        {meshData && (
          <div className="bg-gray-900/50 border border-gray-700 rounded-lg p-2.5">
            <h3 className="text-sm font-semibold text-gray-200 mb-2">Mesh Info</h3>
            <div className="space-y-1.5 text-xs">
              <div className="flex justify-between">
                <span className="text-gray-400">Profile</span>
                <span className="text-gray-200 font-mono">{meshData.profileName}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-gray-400">Grid</span>
                <span className="text-gray-200 font-mono">{meshData.probeCount[0]} × {meshData.probeCount[1]}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-gray-400">Area X</span>
                <span className="text-gray-200 font-mono text-[10px]">{meshData.meshMin[0]}–{meshData.meshMax[0]} mm</span>
              </div>
              <div className="flex justify-between">
                <span className="text-gray-400">Area Y</span>
                <span className="text-gray-200 font-mono text-[10px]">{meshData.meshMin[1]}–{meshData.meshMax[1]} mm</span>
              </div>
              {meshData.probedAt && (
                <div className="flex justify-between">
                  <span className="text-gray-400">Probed</span>
                  <span className="text-gray-200 font-mono text-[9px]">{new Date(meshData.probedAt).toLocaleString()}</span>
                </div>
              )}
            </div>
          </div>
        )}

        {/* Controls Panel */}
        <div className="bg-gray-900/50 border border-gray-700 rounded-lg p-2.5">
          <h3 className="flex items-center gap-2 text-sm font-semibold text-gray-200 mb-2">
            <Settings className="w-4 h-4 text-gray-400" />
            Controls
          </h3>
          
          <div className="flex flex-wrap gap-2">
            <button
              onClick={handleCalibrate}
              disabled={calibrateAction.loading || !!calibrationStatus}
              className="flex items-center gap-1.5 px-3 py-1.5 text-sm bg-cyan-500/20 text-cyan-400 border border-cyan-500/50 rounded-lg hover:bg-cyan-500/30 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
            >
              <Grid3x3 className="w-4 h-4" />
              {calibrateAction.loading || calibrationStatus ? 'Calibrating...' : 'Calibrate'}
            </button>

            <label className="flex items-center gap-2 px-3 py-1.5 text-sm bg-gray-800 text-gray-300 border border-gray-600 rounded-lg cursor-pointer hover:bg-gray-700 transition-colors">
              <input
                id="bed-mesh-show-values"
                name="bed-mesh-show-values"
                type="checkbox"
                checked={showValues}
                onChange={e => setShowValues(e.target.checked)}
                className="rounded border-gray-600"
              />
              Show Values
            </label>
            
            {meshHistory.length > 0 && (
              <button
                onClick={() => {
                  if (confirm('Clear all mesh history? This cannot be undone.')) {
                    setMeshHistory([])
                    localStorage.removeItem(`bedMeshHistory_${printerId}`)
                    console.log('[BedMeshView] History cleared')
                  }
                }}
                className="px-3 py-1.5 text-sm bg-red-500/10 text-red-400 border border-red-500/30 rounded-lg hover:bg-red-500/20 transition-colors"
                title="Clear all mesh history"
              >
                Clear History
              </button>
            )}
          </div>
          
          {/* Debug info */}
          <div className="mt-2 p-2 bg-gray-800/50 rounded text-[9px] text-gray-500 font-mono">
            <div>PrinterID: {printerId}</div>
            <div>API: {baseUrl}</div>
          </div>
        </div>
      </div>
    </div>
  )
}

export default BedMeshView
