// ═══════════════════════════════════════════════════════════════
// PRESTIGE — AI RECOMMENDATIONS TAB
// Per-printer recommendations + active anomalies panel
// ═══════════════════════════════════════════════════════════════

import React, { useState } from 'react'
import { AlertCircle, CheckCircle, RefreshCw, ThumbsUp, ThumbsDown } from 'lucide-react'
import { AIAnomalyCard } from './AIAnomalyCard'
import type { Recommendation, BackendAnomaly } from './ai-types'
import { PRIORITY_STYLE } from './ai-types'

export interface AIRecommendationsTabProps {
  recommendations: Recommendation[]
  anomalies: BackendAnomaly[]
  onRefresh: () => void
  onAcknowledge: (printerId: string, id: string) => Promise<void>
  onDismiss: (printerId: string, id: string) => Promise<void>
}

export function AIRecommendationsTab({
  recommendations, anomalies, onRefresh, onAcknowledge, onDismiss
}: AIRecommendationsTabProps) {
  const [filter, setFilter] = useState<'pending' | 'all' | 'urgent'>('pending')
  const [loadingId, setLoadingId] = useState<string | null>(null)

  const filtered = recommendations.filter(r => {
    if (r.dismissed) return false
    if (filter === 'pending') return !r.acknowledged
    if (filter === 'urgent') return r.priority === 'urgent' || r.priority === 'high'
    return true
  })

  const activeAnoms = anomalies.filter(a => !a.resolvedAt)

  if (!recommendations.length && !anomalies.length) {
    return (
      <div className="py-16 text-center">
        <CheckCircle className="w-10 h-10 mx-auto mb-3 text-green-400/50" />
        <p className="text-base font-medium text-gray-200 mb-1">All Clear</p>
        <p className="text-sm text-gray-400 mb-4">No anomalies or recommendations detected</p>
        <button onClick={onRefresh} className="flex items-center gap-2 mx-auto px-3 py-1.5 rounded-lg bg-cyan-500/20 text-cyan-400 border border-cyan-500/30 text-sm hover:bg-cyan-500/30 transition-colors">
          <RefreshCw className="w-3.5 h-3.5" /> Refresh
        </button>
      </div>
    )
  }

  return (
    <div className="space-y-3">
      {/* Active anomalies */}
      {activeAnoms.length > 0 && (
        <div className="rounded-xl border border-orange-500/30 bg-orange-500/5 p-3 space-y-2">
          <div className="flex items-center gap-2">
            <AlertCircle className="w-4 h-4 text-orange-400" />
            <span className="text-sm font-semibold text-orange-300">
              {activeAnoms.length} Active {activeAnoms.length === 1 ? 'Anomaly' : 'Anomalies'}
            </span>
          </div>
          {activeAnoms.slice(0, 4).map(a => (
            <AIAnomalyCard key={a.id} compact anomaly={{
              id: a.id,
              type: a.type,
              severity: a.severity,
              description: a.description,
              detectedAt: a.detectedAt,
              confidence: a.confidence,
              resolved: !!a.resolvedAt,
              affectedComponent: a.metric,
            }} />
          ))}
          {activeAnoms.length > 4 && (
            <div className="text-[11px] text-gray-500">+{activeAnoms.length - 4} more anomalies</div>
          )}
        </div>
      )}

      {/* Filter */}
      <div className="flex items-center gap-2">
        {(['pending', 'all', 'urgent'] as const).map(f => (
          <button key={f} onClick={() => setFilter(f)}
            className={`px-3 py-1 rounded-lg text-xs font-medium transition-colors ${filter === f ? 'bg-cyan-500/20 text-cyan-400 border border-cyan-500/30' : 'text-gray-400 hover:text-gray-200'}`}>
            {f.charAt(0).toUpperCase() + f.slice(1)}
            {f === 'pending' && recommendations.filter(r => !r.acknowledged && !r.dismissed).length > 0 && (
              <span className="ml-1.5 bg-cyan-500 text-black rounded-full px-1 text-[10px] font-bold">
                {recommendations.filter(r => !r.acknowledged && !r.dismissed).length}
              </span>
            )}
          </button>
        ))}
        <button onClick={onRefresh} className="ml-auto text-gray-500 hover:text-gray-300 transition-colors">
          <RefreshCw className="w-4 h-4" />
        </button>
      </div>

      {filtered.length === 0 ? (
        <div className="py-8 text-center text-gray-500 text-sm">No {filter} recommendations</div>
      ) : (
        <div className="space-y-2">
          {filtered.map(rec => (
            <div key={rec.id} className={`rounded-xl border p-4 ${rec.acknowledged ? 'border-gray-700/40 bg-gray-900/20 opacity-60' : (PRIORITY_STYLE[rec.priority] ?? 'border-gray-700 bg-gray-900/50')}`}>
              <div className="flex items-start gap-3">
                <div className="flex-1 min-w-0">
                  <div className="flex flex-wrap items-center gap-2 mb-1">
                    <span className="text-sm font-semibold text-gray-100">{rec.title}</span>
                    <span className={`text-[10px] px-1.5 py-0.5 rounded border font-bold ${PRIORITY_STYLE[rec.priority] ?? ''}`}>{rec.priority.toUpperCase()}</span>
                    {rec.acknowledged && <span className="text-[10px] px-1.5 py-0.5 rounded bg-green-500/20 text-green-400 border border-green-500/30">ACK</span>}
                  </div>
                  <p className="text-xs text-gray-400">{rec.description}</p>
                  <p className="text-xs text-gray-500 mt-0.5 italic">{rec.reasoning}</p>

                  {rec.suggestedActions.length > 0 && (
                    <div className="flex flex-wrap gap-1 mt-2">
                      {rec.suggestedActions.map(a => (
                        <span key={a.id} className={`text-[10px] px-2 py-0.5 rounded border ${a.automated ? 'bg-cyan-500/10 text-cyan-400 border-cyan-500/30' : 'bg-gray-700/50 text-gray-400 border-gray-600'}`}>
                          {a.automated ? '⚡' : '🔧'} {a.description}
                          {a.gcode && <span className="ml-1 opacity-60 font-mono">{a.gcode.split('\n')[0]}</span>}
                        </span>
                      ))}
                    </div>
                  )}

                  <div className="flex items-center gap-3 mt-2 text-[10px] text-gray-500">
                    <span>{(rec.confidence * 100).toFixed(0)}% conf</span>
                    <span>{new Date(rec.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                    <span className="capitalize">{rec.source}</span>
                  </div>
                </div>

                {!rec.acknowledged && !rec.dismissed && (
                  <div className="flex gap-1 flex-shrink-0">
                    <button disabled={loadingId === rec.id}
                      onClick={async () => { setLoadingId(rec.id); await onAcknowledge(rec.printerId, rec.id); setLoadingId(null) }}
                      className="p-1.5 rounded-lg bg-green-500/20 text-green-400 hover:bg-green-500/30 transition-colors" title="Acknowledge">
                      <ThumbsUp className="w-3.5 h-3.5" />
                    </button>
                    <button disabled={loadingId === rec.id}
                      onClick={async () => { setLoadingId(rec.id); await onDismiss(rec.printerId, rec.id); setLoadingId(null) }}
                      className="p-1.5 rounded-lg bg-gray-700/50 text-gray-400 hover:bg-gray-700 transition-colors" title="Dismiss">
                      <ThumbsDown className="w-3.5 h-3.5" />
                    </button>
                  </div>
                )}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

export default AIRecommendationsTab
