// ═══════════════════════════════════════════════════════════════
// FEATURE: MOVEMENTS PANEL
// Extracted from PrinterDetailPage — XY/Z jog, extruder, position display
// ═══════════════════════════════════════════════════════════════

import { useState, useEffect } from 'react'
import {
  Move, Home, ArrowUp, ArrowDown, ArrowRight, ZoomIn, ZoomOut,
} from 'lucide-react'
import { clamp } from '@/utils/helpers'
import { API_BASE_URL } from '@/utils/constants'
import { websocketService } from '@/services/websocket'
import type { Printer } from '@core/types/printer'

const MOVE_STEPS = [0.005, 0.025, 0.1, 1, 5, 10, 50, 100]
const DEFAULT_BUILD = { x: 220, y: 220, z: 250 }

export function MovementsPanel({ printer }: { printer: Printer }) {
  const pos = printer.liveState?.position
  const [build, setBuild] = useState<{ x: number; y: number; z: number }>(printer.capabilities?.buildVolume ?? DEFAULT_BUILD)
  const [step, setStep] = useState<number>(1)
  const [extrudeLen, setExtrudeLen] = useState('5')
  const [extrudeSpeed, setExtrudeSpeed] = useState('300')
  const [sending, setSending] = useState<string | null>(null)
  const [msg, setMsg] = useState<{ type: 'ok' | 'err'; text: string } | null>(null)
  const [telemetryPos, setTelemetryPos] = useState<{ x: number; y: number; z: number; e: number } | null>(null)
  const [localHomedAxes, setLocalHomedAxes] = useState<Set<string>>(new Set())

  useEffect(() => {
    fetch(`${API_BASE_URL}/api/printers/${printer.id}/build-volume`)
      .then(r => r.json())
      .then(d => { if (d?.data?.buildVolume) setBuild(d.data.buildVolume) })
      .catch(() => {})

    fetch(`${API_BASE_URL}/api/printers/${printer.id}/state`)
      .then(r => r.json())
      .then(d => {
        const raw = d?.data?.homedAxes
        if (raw === undefined) return
        let parsed = ''
        if (typeof raw === 'string') parsed = raw.toUpperCase()
        else if (Array.isArray(raw)) parsed = raw.join('').toUpperCase()
        else if (typeof raw === 'object' && raw !== null) {
          parsed = Object.entries(raw).filter(([, v]) => v === true).map(([k]) => k.toUpperCase()).join('')
        }
        setLocalHomedAxes(new Set(parsed.split('').filter(c => 'XYZ'.includes(c))))
      })
      .catch(() => {})
  }, [printer.id])

  useEffect(() => {
    const unsub = websocketService.subscribe('printer_position' as any, (msg: any) => {
      const payload = msg.payload ?? msg
      if (payload?.printerId !== printer.id) return
      const p = payload.position
      if (p?.x !== undefined) setTelemetryPos({ x: p.x, y: p.y, z: p.z ?? 0, e: p.e ?? 0 })
    })
    return () => { unsub?.() }
  }, [printer.id])

  const livePos = telemetryPos ?? pos
  const effectiveHomedAxes = Array.from(localHomedAxes).join('')

  const sendGcode = async (gcode: string, label: string) => {
    setSending(label); setMsg(null)
    try {
      const res = await fetch(`${API_BASE_URL}/api/printers/${printer.id}/gcode-direct`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ gcode }),
      })
      setMsg({ type: res.ok ? 'ok' : 'err', text: res.ok ? `✓ ${label}` : `Error: ${label}` })
      setTimeout(() => setMsg(null), 2000)
    } catch { setMsg({ type: 'err', text: `Error: ${label}` }) }
    finally { setSending(null) }
  }

  const move = (axis: 'X' | 'Y' | 'Z', dir: 1 | -1) => {
    const dist = step * dir
    sendGcode(`G91\nG1 ${axis}${dist} F3000\nG90`, `${axis}${dist > 0 ? '+' : ''}${dist}mm`)
  }

  const homeAxis = (axes: string) => {
    const axisLetters = axes === '' ? ['X', 'Y', 'Z'] : axes.toUpperCase().split(/[\s,]+/).filter(a => 'XYZ'.includes(a))
    setTimeout(() => setLocalHomedAxes(prev => { const next = new Set(prev); axisLetters.forEach(a => next.add(a)); return next }), 4000)
    sendGcode(`G28 ${axes}`.trim(), `Home ${axes || 'All'}`)
  }

  const extrude = (dir: 1 | -1) => {
    const len = parseFloat(extrudeLen) || 5
    const spd = parseFloat(extrudeSpeed) || 300
    sendGcode(`M83\nG1 E${len * dir} F${spd}\nM82`, dir > 0 ? 'Extrude' : 'Retract')
  }

  const btnBase = 'flex items-center justify-center rounded border transition-colors disabled:opacity-40'

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-2 p-1">
      <div className="lg:col-span-8 space-y-2">
        {/* Live position */}
        <div className="bg-gray-900/50 border border-gray-700 rounded-lg p-2.5">
          <div className="flex items-center justify-between mb-1.5">
            <h3 className="flex items-center gap-1.5 text-xs font-semibold text-gray-300">
              <Move className="w-3 h-3 text-cyan-400" />Live Position
            </h3>
            <div className="flex items-center gap-2">
              <div className="flex gap-0.5">
                {['X', 'Y', 'Z'].map(a => (
                  <span key={a} className={`px-1 py-0.5 text-[9px] font-bold rounded border ${effectiveHomedAxes.includes(a) ? 'bg-green-500/15 border-green-500/40 text-green-400' : 'bg-gray-800 border-gray-700 text-gray-600'}`}>{a}</span>
                ))}
              </div>
              <span className={`w-1.5 h-1.5 rounded-full ${livePos ? 'bg-green-400 animate-pulse' : 'bg-gray-600'}`} />
            </div>
          </div>
          <div className="grid grid-cols-3 gap-1 mb-1.5">
            {(['x', 'y', 'z'] as const).map(axis => {
              const val = livePos?.[axis as keyof typeof livePos]
              const colors = { x: 'text-red-400', y: 'text-green-400', z: 'text-blue-400' }
              return (
                <div key={axis} className="bg-gray-800/60 border border-gray-700 rounded p-1.5 text-center">
                  <div className="text-[9px] text-gray-500 uppercase tracking-widest">{axis.toUpperCase()}</div>
                  <div className={`text-sm font-mono font-bold ${colors[axis]}`}>{val !== undefined ? (val as number).toFixed(2) : '—'}</div>
                  <div className="text-[9px] text-gray-700">mm</div>
                </div>
              )
            })}
          </div>
          <div className="flex gap-1.5">
            <div className="flex-1 flex items-center justify-between bg-gray-800/40 rounded px-2 py-1">
              <span className="text-[9px] text-gray-500">Speed</span>
              <span className="text-xs font-mono text-cyan-400">{printer.liveState?.speed?.feedrate ?? 100}%</span>
            </div>
            <div className="flex-1 flex items-center justify-between bg-gray-800/40 rounded px-2 py-1">
              <span className="text-[9px] text-gray-500">Flow</span>
              <span className="text-xs font-mono text-purple-400">{printer.liveState?.speed?.flowrate ?? 100}%</span>
            </div>
          </div>
        </div>

        {/* Toolhead movement */}
        <div className="bg-gray-900/50 border border-gray-700 rounded-lg p-2">
          <h3 className="text-xs font-semibold text-gray-300 mb-1">Toolhead Movement</h3>
          <div className="flex gap-1 mb-1 flex-wrap">
            {MOVE_STEPS.map(s => (
              <button key={s} onClick={() => setStep(s)}
                className={`flex-1 min-w-0 py-0.5 text-[9px] font-bold rounded border ${step === s ? 'bg-cyan-500/20 text-cyan-400 border-cyan-500/60' : 'bg-gray-800 text-gray-500 border-gray-700 hover:text-gray-300'}`}>
                {s}mm
              </button>
            ))}
          </div>
          <div className="flex gap-2 items-start">
            {/* XY D-pad */}
            <div className="flex-1">
              <div className="text-[10px] text-gray-400 text-center mb-0.5">X / Y</div>
              <div className="grid grid-cols-3 gap-0.5 w-28 mx-auto">
                <div />
                <button onClick={() => move('Y', 1)} disabled={!!sending} className={`${btnBase} aspect-square bg-green-500/15 border-green-500/40 text-green-400 hover:bg-green-500/30`}><ArrowUp className="w-4 h-4" /></button>
                <div />
                <button onClick={() => move('X', -1)} disabled={!!sending} className={`${btnBase} aspect-square bg-red-500/15 border-red-500/40 text-red-400 hover:bg-red-500/30`}><ArrowDown className="w-4 h-4 rotate-90" /></button>
                <button onClick={() => homeAxis('X Y')} disabled={!!sending} className={`${btnBase} aspect-square bg-gray-700 border-gray-500 text-gray-300 hover:bg-gray-600`}><Home className="w-3.5 h-3.5" /></button>
                <button onClick={() => move('X', 1)} disabled={!!sending} className={`${btnBase} aspect-square bg-red-500/15 border-red-500/40 text-red-400 hover:bg-red-500/30`}><ArrowRight className="w-4 h-4" /></button>
                <div />
                <button onClick={() => move('Y', -1)} disabled={!!sending} className={`${btnBase} aspect-square bg-green-500/15 border-green-500/40 text-green-400 hover:bg-green-500/30`}><ArrowDown className="w-4 h-4" /></button>
                <div />
              </div>
            </div>
            {/* Z column */}
            <div className="flex flex-col items-center gap-0">
              <div className="text-[10px] text-gray-400 mb-0">Z</div>
              <button onClick={() => move('Z', 1)} disabled={!!sending} className={`${btnBase} w-8 h-8 bg-blue-500/15 border-blue-500/40 text-blue-400 hover:bg-blue-500/30`}><ZoomIn className="w-4 h-4" /></button>
              <button onClick={() => homeAxis('Z')} disabled={!!sending} className={`${btnBase} w-8 h-8 bg-gray-700 border-gray-500 text-gray-300 hover:bg-gray-600`}><Home className="w-3.5 h-3.5" /></button>
              <button onClick={() => move('Z', -1)} disabled={!!sending} className={`${btnBase} w-8 h-8 bg-blue-500/15 border-blue-500/40 text-blue-400 hover:bg-blue-500/30`}><ZoomOut className="w-4 h-4" /></button>
              <div className="text-[9px] text-blue-400 font-mono font-bold">{livePos?.z !== undefined ? (livePos.z as number).toFixed(2) : '—'}</div>
              <button onClick={() => sendGcode('Z_TILT_ADJUST', 'Z Tilt')} disabled={!!sending}
                className={`${btnBase} w-8 h-8 flex-col bg-violet-500/15 border-violet-500/40 text-violet-400 hover:bg-violet-500/30`}>
                <span className="text-[9px] font-bold leading-none">Z</span><span className="text-[8px] leading-none">TILT</span>
              </button>
            </div>
          </div>

          {/* Extruder */}
          <div className="mt-2 pt-2 border-t border-gray-700">
            <div className="flex items-center gap-2 mb-1">
              <h3 className="text-xs font-semibold text-gray-300 mr-auto">Extruder</h3>
              <div className="flex items-center gap-1">
                <span className="text-[9px] text-gray-500">Len</span>
                <input type="number" id="extrude-len" name="extrude-len" min={1} max={500} value={extrudeLen} onChange={e => setExtrudeLen(e.target.value)}
                  className="w-14 px-1.5 py-0.5 bg-gray-900 border border-gray-600 rounded text-[10px] font-mono text-gray-200 focus:outline-none" />
              </div>
              <div className="flex items-center gap-1">
                <span className="text-[9px] text-gray-500">Spd</span>
                <input type="number" id="extrude-speed" name="extrude-speed" min={10} max={6000} value={extrudeSpeed} onChange={e => setExtrudeSpeed(e.target.value)}
                  className="w-16 px-1.5 py-0.5 bg-gray-900 border border-gray-600 rounded text-[10px] font-mono text-gray-200 focus:outline-none" />
              </div>
            </div>
            <div className="flex gap-1">
              <button onClick={() => extrude(1)} disabled={!!sending}
                className="flex-1 py-1 text-xs font-semibold bg-orange-500/15 border border-orange-500/40 rounded text-orange-400 hover:bg-orange-500/25 disabled:opacity-40">
                ⬇ Extrude {extrudeLen}mm
              </button>
              <button onClick={() => extrude(-1)} disabled={!!sending}
                className="flex-1 py-1 text-xs font-semibold bg-gray-800 border border-gray-700 rounded text-gray-400 hover:text-orange-400 disabled:opacity-40">
                ⬆ Retract {extrudeLen}mm
              </button>
            </div>
            <div className="mt-0.5 text-[9px] text-gray-600">E: <span className="font-mono text-orange-400">{livePos?.e !== undefined ? (livePos.e as number).toFixed(2) : '—'}</span> mm</div>
          </div>
        </div>

        {msg && <div className={`text-[10px] px-2 py-1 rounded border ${msg.type === 'ok' ? 'bg-green-500/10 border-green-500/30 text-green-400' : 'bg-red-500/10 border-red-500/30 text-red-400'}`}>{msg.text}</div>}
        {sending && <div className="text-[10px] text-gray-500 px-1 animate-pulse">⟳ {sending}…</div>}
      </div>

      {/* Right: build info */}
      <div className="lg:col-span-4">
        <div className="bg-gray-900/50 border border-gray-700 rounded-lg px-3 py-2">
          <div className="flex items-center justify-between">
            <span className="text-[9px] text-gray-500 uppercase">Bed size</span>
            <span className="text-xs font-mono text-cyan-400">{build.x}×{build.y}×{build.z}mm</span>
          </div>
        </div>
      </div>
    </div>
  )
}
