/**
 * Format time duration in seconds to human-readable string
 */
export const formatDuration = (seconds: number): string => {
  if (seconds < 0) return '0s'

  const hours = Math.floor(seconds / 3600)
  const minutes = Math.floor((seconds % 3600) / 60)
  const secs = Math.floor(seconds % 60)

  if (hours > 0) {
    return `${hours}h ${minutes}m`
  }
  if (minutes > 0) {
    return `${minutes}m ${secs}s`
  }
  return `${secs}s`
}

/**
 * Format time duration with full details
 */
export const formatDurationFull = (seconds: number): string => {
  if (seconds < 0) return '0 seconds'

  const days = Math.floor(seconds / 86400)
  const hours = Math.floor((seconds % 86400) / 3600)
  const minutes = Math.floor((seconds % 3600) / 60)
  const secs = Math.floor(seconds % 60)

  const parts: string[] = []
  if (days > 0) parts.push(`${days}d`)
  if (hours > 0) parts.push(`${hours}h`)
  if (minutes > 0) parts.push(`${minutes}m`)
  if (secs > 0 || parts.length === 0) parts.push(`${secs}s`)

  return parts.join(' ')
}

/**
 * Format timestamp to relative time (e.g., "2 hours ago")
 */
export const formatRelativeTime = (timestamp: string | Date): string => {
  const date = typeof timestamp === 'string' ? new Date(timestamp) : timestamp
  const now = new Date()
  const diff = Math.floor((now.getTime() - date.getTime()) / 1000)

  if (diff < 0) return 'in the future'
  if (diff < 60) return 'just now'
  if (diff < 3600) return `${Math.floor(diff / 60)}m ago`
  if (diff < 86400) return `${Math.floor(diff / 3600)}h ago`
  if (diff < 604800) return `${Math.floor(diff / 86400)}d ago`
  if (diff < 2592000) return `${Math.floor(diff / 604800)}w ago`
  if (diff < 31536000) return `${Math.floor(diff / 2592000)}mo ago`
  return `${Math.floor(diff / 31536000)}y ago`
}

/**
 * Format date to readable string
 */
export const formatDate = (timestamp: string | Date, includeTime = false): string => {
  const date = typeof timestamp === 'string' ? new Date(timestamp) : timestamp

  const options: Intl.DateTimeFormatOptions = {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
  }

  if (includeTime) {
    options.hour = '2-digit'
    options.minute = '2-digit'
  }

  return date.toLocaleDateString('en-US', options)
}

/**
 * Format file size in bytes to human-readable string
 */
export const formatFileSize = (bytes: number, decimals = 2): string => {
  if (bytes === 0) return '0 Bytes'
  if (bytes < 0) return 'Invalid size'

  const k = 1024
  const sizes = ['Bytes', 'KB', 'MB', 'GB', 'TB']
  const i = Math.floor(Math.log(bytes) / Math.log(k))

  return `${parseFloat((bytes / Math.pow(k, i)).toFixed(decimals))} ${sizes[i]}`
}

/**
 * Format number with thousand separators
 */
export const formatNumber = (value: number, decimals = 0): string => {
  return value.toLocaleString('en-US', {
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals,
  })
}

/**
 * Format percentage
 */
export const formatPercentage = (value: number, decimals = 1): string => {
  return `${value.toFixed(decimals)}%`
}

/**
 * Format temperature
 */
export const formatTemperature = (celsius: number, unit: 'C' | 'F' = 'C', decimals = 1): string => {
  if (unit === 'F') {
    const fahrenheit = (celsius * 9) / 5 + 32
    return `${fahrenheit.toFixed(decimals)}°F`
  }
  return `${celsius.toFixed(decimals)}°C`
}

/**
 * Format coordinates
 */
export const formatCoordinate = (value: number, decimals = 2): string => {
  return value.toFixed(decimals)
}

/**
 * Format position (X, Y, Z)
 */
export const formatPosition = (x: number, y: number, z: number, decimals = 2): string => {
  return `X:${x.toFixed(decimals)} Y:${y.toFixed(decimals)} Z:${z.toFixed(decimals)}`
}

/**
 * Format speed (mm/s to mm/min)
 */
export const formatSpeed = (mmPerSecond: number, decimals = 0): string => {
  return `${(mmPerSecond * 60).toFixed(decimals)} mm/min`
}

/**
 * Format flow rate
 */
export const formatFlowRate = (percentage: number, decimals = 0): string => {
  return `${percentage.toFixed(decimals)}%`
}

/**
 * Truncate string with ellipsis
 */
export const truncate = (str: string, maxLength: number, suffix = '...'): string => {
  if (str.length <= maxLength) return str
  return str.slice(0, maxLength - suffix.length) + suffix
}

/**
 * Format printer status to display label
 */
export const formatPrinterStatus = (status: string): string => {
  return status
    .split('_')
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ')
}

/**
 * Format boolean to Yes/No
 */
export const formatBoolean = (value: boolean): string => {
  return value ? 'Yes' : 'No'
}

/**
 * Format array to comma-separated string
 */
export const formatList = (items: string[], maxItems = 3): string => {
  if (items.length === 0) return 'None'
  if (items.length <= maxItems) return items.join(', ')
  return `${items.slice(0, maxItems).join(', ')} +${items.length - maxItems} more`
}

/**
 * Format currency (for cost calculations)
 */
export const formatCurrency = (amount: number, currency = 'USD', decimals = 2): string => {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency,
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals,
  }).format(amount)
}

/**
 * Format print quality grade
 */
export const formatQualityGrade = (score: number): string => {
  if (score >= 95) return 'S'
  if (score >= 85) return 'A'
  if (score >= 75) return 'B'
  if (score >= 65) return 'C'
  if (score >= 50) return 'D'
  return 'F'
}
