// ═══════════════════════════════════════════════════════════════
// PRESTIGE DASHBOARD - QUALITY SCORE COMPONENT
// ═══════════════════════════════════════════════════════════════

import React, { useMemo } from 'react'
import type {
  QualityScoreProps,
  QualityScoreSize,
  QualityScoreMode,
  QualityGrade,
  QualityColorConfig,
  QualityCategory,
} from './QualityScore.types'

/**
 * Get quality grade from score
 */
const getGrade = (score: number): QualityGrade => {
  if (score >= 95) return 'S'
  if (score >= 85) return 'A'
  if (score >= 75) return 'B'
  if (score >= 65) return 'C'
  if (score >= 50) return 'D'
  return 'F'
}

/**
 * Get color configuration based on score
 */
const getColorConfig = (score: number): QualityColorConfig => {
  const grade = getGrade(score)

  const configs: Record<QualityGrade, QualityColorConfig> = {
    S: {
      color: '#0ff',
      glowColor: 'rgba(0, 255, 255, 0.5)',
      bgColor: 'rgba(0, 255, 255, 0.1)',
      borderColor: 'rgba(0, 255, 255, 0.3)',
      grade: 'S',
      label: 'PERFECT',
      description: 'Outstanding quality',
    },
    A: {
      color: '#0f0',
      glowColor: 'rgba(0, 255, 0, 0.5)',
      bgColor: 'rgba(0, 255, 0, 0.1)',
      borderColor: 'rgba(0, 255, 0, 0.3)',
      grade: 'A',
      label: 'EXCELLENT',
      description: 'Excellent quality',
    },
    B: {
      color: '#ff0',
      glowColor: 'rgba(255, 255, 0, 0.5)',
      bgColor: 'rgba(255, 255, 0, 0.1)',
      borderColor: 'rgba(255, 255, 0, 0.3)',
      grade: 'B',
      label: 'GOOD',
      description: 'Good quality',
    },
    C: {
      color: '#f80',
      glowColor: 'rgba(255, 136, 0, 0.5)',
      bgColor: 'rgba(255, 136, 0, 0.1)',
      borderColor: 'rgba(255, 136, 0, 0.3)',
      grade: 'C',
      label: 'ACCEPTABLE',
      description: 'Acceptable quality',
    },
    D: {
      color: '#f00',
      glowColor: 'rgba(255, 0, 0, 0.5)',
      bgColor: 'rgba(255, 0, 0, 0.1)',
      borderColor: 'rgba(255, 0, 0, 0.3)',
      grade: 'D',
      label: 'POOR',
      description: 'Poor quality',
    },
    F: {
      color: '#a00',
      glowColor: 'rgba(160, 0, 0, 0.5)',
      bgColor: 'rgba(160, 0, 0, 0.1)',
      borderColor: 'rgba(160, 0, 0, 0.3)',
      grade: 'F',
      label: 'FAIL',
      description: 'Failed quality check',
    },
  }

  return configs[grade]
}

/**
 * Size configuration
 */
const SIZE_CONFIG: Record<
  QualityScoreSize,
  { circle: number; text: string; grade: string; container: string }
> = {
  sm: {
    circle: 60,
    text: 'text-xs',
    grade: 'text-lg',
    container: 'p-2',
  },
  md: {
    circle: 80,
    text: 'text-sm',
    grade: 'text-2xl',
    container: 'p-3',
  },
  lg: {
    circle: 100,
    text: 'text-base',
    grade: 'text-3xl',
    container: 'p-4',
  },
  xl: {
    circle: 120,
    text: 'text-lg',
    grade: 'text-4xl',
    container: 'p-5',
  },
}

/**
 * QualityScore Component
 * Displays AI-assessed quality score with visual indicators
 */
export const QualityScore: React.FC<QualityScoreProps> = ({
  score,
  size = 'md',
  mode = 'compact',
  showGrade = true,
  showLabel = true,
  breakdown,
  animated = true,
  className = '',
  onClick,
}) => {
  const colorConfig = useMemo(() => getColorConfig(score), [score])
  const sizeConfig = SIZE_CONFIG[size]

  // Clamp score to 0-100
  const clampedScore = Math.max(0, Math.min(100, score))
  const percentage = clampedScore / 100

  // SVG circle parameters
  const radius = (sizeConfig.circle - 8) / 2
  const circumference = 2 * Math.PI * radius
  const strokeDashoffset = circumference * (1 - percentage)

  // Compact mode (just circle with score)
  if (mode === 'compact') {
    return (
      <div
        className={`inline-flex items-center justify-center ${className}`}
        onClick={onClick}
        style={{ cursor: onClick ? 'pointer' : 'default' }}
      >
        <div className="relative" style={{ width: sizeConfig.circle, height: sizeConfig.circle }}>
          {/* Background circle */}
          <svg className="absolute top-0 left-0 transform -rotate-90" width="100%" height="100%">
            <circle
              cx="50%"
              cy="50%"
              r={radius}
              fill="none"
              stroke="rgba(255, 255, 255, 0.05)"
              strokeWidth="6"
            />
            {/* Progress circle */}
            <circle
              cx="50%"
              cy="50%"
              r={radius}
              fill="none"
              stroke={colorConfig.color}
              strokeWidth="6"
              strokeLinecap="round"
              strokeDasharray={circumference}
              strokeDashoffset={strokeDashoffset}
              style={{
                filter: `drop-shadow(0 0 8px ${colorConfig.glowColor})`,
                transition: animated ? 'stroke-dashoffset 1s ease-out' : 'none',
              }}
            />
          </svg>
          {/* Center content */}
          <div className="absolute inset-0 flex flex-col items-center justify-center">
            {showGrade ? (
              <span
                className={`font-bold ${sizeConfig.grade}`}
                style={{
                  color: colorConfig.color,
                  textShadow: `0 0 10px ${colorConfig.glowColor}`,
                }}
              >
                {colorConfig.grade}
              </span>
            ) : (
              <span
                className={`font-bold ${sizeConfig.text}`}
                style={{
                  color: colorConfig.color,
                  textShadow: `0 0 10px ${colorConfig.glowColor}`,
                }}
              >
                {clampedScore}
              </span>
            )}
            {showLabel && (
              <span className={`${sizeConfig.text} text-gray-400`}>{clampedScore}</span>
            )}
          </div>
        </div>
      </div>
    )
  }

  // Full mode (circle + info)
  if (mode === 'full') {
    return (
      <div
        className={`flex flex-col items-center gap-3 ${sizeConfig.container} rounded-lg border ${className}`}
        onClick={onClick}
        style={{
          backgroundColor: colorConfig.bgColor,
          borderColor: colorConfig.borderColor,
          cursor: onClick ? 'pointer' : 'default',
        }}
      >
        {/* Circle */}
        <div className="relative" style={{ width: sizeConfig.circle, height: sizeConfig.circle }}>
          <svg className="absolute top-0 left-0 transform -rotate-90" width="100%" height="100%">
            <circle
              cx="50%"
              cy="50%"
              r={radius}
              fill="none"
              stroke="rgba(255, 255, 255, 0.05)"
              strokeWidth="6"
            />
            <circle
              cx="50%"
              cy="50%"
              r={radius}
              fill="none"
              stroke={colorConfig.color}
              strokeWidth="6"
              strokeLinecap="round"
              strokeDasharray={circumference}
              strokeDashoffset={strokeDashoffset}
              style={{
                filter: `drop-shadow(0 0 10px ${colorConfig.glowColor})`,
                transition: animated ? 'stroke-dashoffset 1s ease-out' : 'none',
              }}
            />
          </svg>
          <div className="absolute inset-0 flex flex-col items-center justify-center">
            {showGrade && (
              <span
                className={`font-bold ${sizeConfig.grade}`}
                style={{
                  color: colorConfig.color,
                  textShadow: `0 0 12px ${colorConfig.glowColor}`,
                }}
              >
                {colorConfig.grade}
              </span>
            )}
            <span className={`font-mono font-bold ${sizeConfig.text} text-gray-300`}>
              {clampedScore}/100
            </span>
          </div>
        </div>

        {/* Label */}
        <div className="flex flex-col items-center gap-1">
          <span
            className={`font-bold ${sizeConfig.text}`}
            style={{ color: colorConfig.color }}
          >
            {colorConfig.label}
          </span>
          <span className="text-xs text-gray-500">{colorConfig.description}</span>
        </div>
      </div>
    )
  }

  // Detailed mode (with breakdown)
  return (
    <div
      className={`flex flex-col gap-3 ${sizeConfig.container} rounded-lg border ${className}`}
      onClick={onClick}
      style={{
        backgroundColor: colorConfig.bgColor,
        borderColor: colorConfig.borderColor,
        cursor: onClick ? 'pointer' : 'default',
      }}
    >
      {/* Header */}
      <div className="flex items-center justify-between">
        <span className={`font-medium ${sizeConfig.text} text-gray-300`}>Quality Score</span>
        <span
          className={`text-xs font-bold px-2 py-0.5 rounded`}
          style={{
            color: colorConfig.color,
            backgroundColor: colorConfig.bgColor,
            border: `1px solid ${colorConfig.borderColor}`,
          }}
        >
          {colorConfig.label}
        </span>
      </div>

      {/* Score display */}
      <div className="flex items-center gap-4">
        {/* Circle */}
        <div className="relative flex-shrink-0" style={{ width: sizeConfig.circle, height: sizeConfig.circle }}>
          <svg className="absolute top-0 left-0 transform -rotate-90" width="100%" height="100%">
            <circle
              cx="50%"
              cy="50%"
              r={radius}
              fill="none"
              stroke="rgba(255, 255, 255, 0.05)"
              strokeWidth="6"
            />
            <circle
              cx="50%"
              cy="50%"
              r={radius}
              fill="none"
              stroke={colorConfig.color}
              strokeWidth="6"
              strokeLinecap="round"
              strokeDasharray={circumference}
              strokeDashoffset={strokeDashoffset}
              style={{
                filter: `drop-shadow(0 0 10px ${colorConfig.glowColor})`,
                transition: animated ? 'stroke-dashoffset 1s ease-out' : 'none',
              }}
            />
          </svg>
          <div className="absolute inset-0 flex flex-col items-center justify-center">
            {showGrade && (
              <span
                className={`font-bold ${sizeConfig.grade}`}
                style={{
                  color: colorConfig.color,
                  textShadow: `0 0 12px ${colorConfig.glowColor}`,
                }}
              >
                {colorConfig.grade}
              </span>
            )}
            <span className={`font-mono font-bold text-xs text-gray-400`}>
              {clampedScore}/100
            </span>
          </div>
        </div>

        {/* Breakdown */}
        {breakdown && breakdown.length > 0 && (
          <div className="flex-1 flex flex-col gap-2">
            {breakdown.map((category, index) => {
              const categoryColor = getColorConfig(category.score)
              return (
                <div key={index} className="flex flex-col gap-1">
                  <div className="flex items-center justify-between text-xs">
                    <span className="flex items-center gap-1.5 text-gray-400">
                      {category.icon && <span>{category.icon}</span>}
                      <span>{category.name}</span>
                    </span>
                    <span
                      className="font-mono font-bold"
                      style={{ color: categoryColor.color }}
                    >
                      {category.score}
                    </span>
                  </div>
                  <div className="h-1 rounded-full overflow-hidden bg-gray-800">
                    <div
                      className="h-full transition-all duration-500"
                      style={{
                        width: `${category.score}%`,
                        backgroundColor: categoryColor.color,
                        boxShadow: `0 0 6px ${categoryColor.glowColor}`,
                      }}
                    />
                  </div>
                </div>
              )
            })}
          </div>
        )}
      </div>

      {/* Description */}
      <span className="text-xs text-gray-500">{colorConfig.description}</span>
    </div>
  )
}

QualityScore.displayName = 'QualityScore'

export default QualityScore
