// ═══════════════════════════════════════════════════════════════
// PRESTIGE DASHBOARD - PRINTERS PAGE
// ═══════════════════════════════════════════════════════════════

import { useState, useEffect } from 'react'
import { useNavigate } from 'react-router-dom'
import { Printer, FolderOpen } from 'lucide-react'
import { PrinterGrid } from '@core/components/PrinterGrid'
import { usePrinterStore, selectPrintersArray } from '@core/state/printerStore'
import { useToast } from '@core/hooks/useToast'
import { FileBrowserPanel } from '@features/file-browser'
import { PageToasts } from '@core/components/PageToasts'
import type { PrinterFilters, PrinterSort, Printer as PrinterType } from '@core/types/printer'

type ActiveTab = 'printers' | 'files'

// ─── Printer Selector ─────────────────────────────────────────
function PrinterSelector({ printers, selected, onSelect }: {
  printers: PrinterType[]; selected: PrinterType | null; onSelect: (p: PrinterType) => void
}) {
  return (
    <div className="flex flex-col gap-1.5 w-52 flex-shrink-0">
      <p className="text-[10px] text-gray-500 uppercase tracking-wide font-semibold px-1 mb-0.5">Printer</p>
      {printers.length === 0
        ? <div className="text-xs text-gray-600 px-2 py-4 text-center">No printers</div>
        : printers.map(p => {
          const sel = selected?.id === p.id
          return (
            <button key={p.id} onClick={() => onSelect(p)}
              className={`flex items-center gap-2.5 px-3 py-2.5 rounded-lg text-left border transition-all ${sel
                ? 'bg-cyan-500/15 border-cyan-500/50 text-cyan-300'
                : 'bg-gray-800/40 border-gray-700 text-gray-300 hover:bg-gray-800 hover:border-gray-600'}`}>
              <Printer className={`w-3.5 h-3.5 flex-shrink-0 ${sel ? 'text-cyan-400' : 'text-gray-500'}`} />
              <div className="flex-1 min-w-0">
                <p className="text-xs font-medium truncate">{p.name}</p>
                <p className="text-[10px] text-gray-500 capitalize">{p.adapterType}</p>
              </div>
            </button>
          )
        })}
    </div>
  )
}

// ═══════════════════════════════════════════════════════════════
// MAIN PAGE
// ═══════════════════════════════════════════════════════════════
export default function PrintersPage() {
  const navigate = useNavigate()
  const printers = usePrinterStore(selectPrintersArray)
  const [filters, setFilters]          = useState<PrinterFilters>({})
  const [sort, setSort]                = useState<PrinterSort>({ field: 'name', direction: 'asc' })
  const [activeTab, setActiveTab]      = useState<ActiveTab>('printers')
  const [selectedPrinter, setSelected] = useState<PrinterType | null>(null)
  const { toasts, add: toast }         = useToast()

  useEffect(() => {
    if (activeTab === 'files' && !selectedPrinter && printers.length > 0)
      setSelected(printers[0])
  }, [activeTab, printers, selectedPrinter])

  return (
    <div className="flex flex-col h-full overflow-hidden">
      {/* Tab Bar */}
      <div className="flex items-center gap-1 px-4 pt-3 pb-0 flex-shrink-0">
        {([
          { id: 'printers' as ActiveTab, label: 'Printers', icon: <Printer className="w-3.5 h-3.5" /> },
          { id: 'files'    as ActiveTab, label: 'Files',    icon: <FolderOpen className="w-3.5 h-3.5" /> },
        ] as const).map(tab => (
          <button key={tab.id} onClick={() => setActiveTab(tab.id)}
            className={`flex items-center gap-1.5 px-4 py-2 text-xs font-semibold rounded-t-lg border-b-2 transition-all ${
              activeTab === tab.id
                ? 'border-cyan-400 text-cyan-400 bg-cyan-500/5'
                : 'border-transparent text-gray-500 hover:text-gray-300 hover:border-gray-600'}`}>
            {tab.icon}{tab.label}
          </button>
        ))}
        <div className="flex-1 border-b border-gray-700" />
      </div>

      <div className="flex-1 min-h-0 overflow-hidden">
        {activeTab === 'printers' && (
          <div className="h-full overflow-auto p-4">
            <PrinterGrid
              printers={printers}
              showSearch showFilters showSort
              filters={filters} sort={sort}
              onFiltersChange={f => setFilters(f as PrinterFilters)}
              onSortChange={s => setSort(s as PrinterSort)}
              actions={{ onView: p => navigate(`/printers/${p.id}`) }}
            />
          </div>
        )}

        {activeTab === 'files' && (
          <div className="h-full flex gap-4 p-4 overflow-hidden">
            <PrinterSelector printers={printers} selected={selectedPrinter} onSelect={setSelected} />
            <div className="w-px bg-gray-700/60 flex-shrink-0" />
            <div className="flex-1 min-w-0 overflow-hidden">
              {selectedPrinter
                ? <FileBrowserPanel
                    key={selectedPrinter.id}
                    printer={selectedPrinter}
                    toast={(type, msg) => toast(msg, type)}
                  />
                : (
                  <div className="flex flex-col items-center justify-center h-full text-gray-500">
                    <Printer className="w-10 h-10 mb-3 opacity-20" />
                    <p className="text-sm">Select a printer to browse its files</p>
                  </div>
                )}
            </div>
          </div>
        )}
      </div>

      <PageToasts toasts={toasts} />
    </div>
  )
}
