import React, { useState, useRef, useCallback, useEffect, useMemo } from 'react'
import { NODES, EDGES, GROUP_COLORS, TIERS } from './arch-data'

// ─── Canvas dimensions ────────────────────────────────────────────────────────
const VW = 1600
const VH = 760

// ─── Arrow markers ────────────────────────────────────────────────────────────
const ARROW_DEFS = [
  { id: 'a-cyan',   fill: '#22d3ee' },
  { id: 'a-purple', fill: '#a855f7' },
  { id: 'a-slate',  fill: '#64748b' },
  { id: 'a-green',  fill: '#10b981' },
  { id: 'a-teal',   fill: '#0e7490' },
  { id: 'a-indigo', fill: '#6d28d9' },
  { id: 'a-blue',   fill: '#06b6d4' },
]

function arrowId(color: string): string {
  if (color === '#22d3ee') return 'a-cyan'
  if (color === '#a855f7' || color === '#8b5cf6' || color === '#7c3aed') return 'a-purple'
  if (color === '#10b981') return 'a-green'
  if (color === '#0e7490') return 'a-teal'
  if (color === '#64748b') return 'a-slate'
  if (color === '#6d28d9') return 'a-indigo'
  if (color === '#06b6d4' || color === '#0ea5e9' || color === '#0284c7') return 'a-blue'
  return 'a-cyan'
}

// ─── Edge geometry ────────────────────────────────────────────────────────────
function edgePath(
  fx: number, fy: number, fw: number, fh: number,
  tx: number, ty: number, tw: number, th: number,
): { d: string; lx: number; ly: number } {
  const fcx = fx + fw / 2; const fcy = fy + fh / 2
  const tcx = tx + tw / 2; const tcy = ty + th / 2
  const dx = tcx - fcx; const dy = tcy - fcy

  let ex = fcx; let ey = fcy
  if (Math.abs(dx) * fh > Math.abs(dy) * fw) {
    ex = dx > 0 ? fx + fw : fx; ey = fcy
  } else {
    ey = dy > 0 ? fy + fh : fy; ex = fcx
  }

  let ix = tcx; let iy = tcy
  if (Math.abs(dx) * th > Math.abs(dy) * tw) {
    ix = dx > 0 ? tx : tx + tw; iy = tcy
  } else {
    iy = dy > 0 ? ty : ty + th; ix = tcx
  }

  const cdx = (ix - ex) * 0.45; const cdy = (iy - ey) * 0.45
  return {
    d: `M${ex},${ey} C${ex + cdx},${ey + cdy} ${ix - cdx},${iy - cdy} ${ix},${iy}`,
    lx: (ex + ix) / 2,
    ly: (ey + iy) / 2,
  }
}

// ─── Group icons ──────────────────────────────────────────────────────────────
const GROUP_ICON: Record<string, string> = {
  external: '⬡',
  backend:  '◈',
  frontend: '◇',
  ai:       '◉',
}

interface Props {
  selectedId:  string | null
  onNodeClick: (id: string) => void
}

export function ArchDiagram({ selectedId, onNodeClick }: Props) {
  const [hovNode, setHovNode]     = useState<string | null>(null)
  const [hovEdge, setHovEdge]     = useState<number | null>(null)
  const [search, setSearch]       = useState('')
  const [pan, setPan]             = useState({ x: 0, y: 0 })
  const [scale, setScale]         = useState(0.85)
  const dragging                  = useRef(false)
  const dragStart                 = useRef({ mx: 0, my: 0, px: 0, py: 0 })
  const containerRef              = useRef<HTMLDivElement>(null)
  const searchRef                 = useRef<HTMLInputElement>(null)

  const MIN_SCALE = 0.3
  const MAX_SCALE = 2.0

  // ── Search matching ──────────────────────────────────────────────────────
  const matchedNodeIds = useMemo(() => {
    if (!search.trim()) return new Set<string>()
    const q = search.toLowerCase()
    return new Set(
      NODES
        .filter(n =>
          n.label.toLowerCase().includes(q) ||
          n.sub.toLowerCase().includes(q) ||
          n.group.toLowerCase().includes(q) ||
          n.details.some(d => d.toLowerCase().includes(q)) ||
          n.files.some(f => f.toLowerCase().includes(q))
        )
        .map(n => n.id)
    )
  }, [search])

  // ── Connected edges for hover highlight ──────────────────────────────────
  const connectedEdgeIds = useMemo(() => {
    if (!hovNode && !selectedId) return new Set<number>()
    const focusId = hovNode ?? selectedId
    return new Set(
      EDGES
        .map((e, i) => (e.from === focusId || e.to === focusId ? i : -1))
        .filter(i => i >= 0)
    )
  }, [hovNode, selectedId])

  // ── Pan handlers ─────────────────────────────────────────────────────────
  const onMouseDown = useCallback((e: React.MouseEvent) => {
    if ((e.target as SVGElement).closest('.arch-node')) return
    if ((e.target as HTMLElement).closest('.arch-search')) return
    dragging.current = true
    dragStart.current = { mx: e.clientX, my: e.clientY, px: pan.x, py: pan.y }
    e.preventDefault()
  }, [pan])

  const onMouseMove = useCallback((e: React.MouseEvent) => {
    if (!dragging.current) return
    setPan({
      x: dragStart.current.px + e.clientX - dragStart.current.mx,
      y: dragStart.current.py + e.clientY - dragStart.current.my,
    })
  }, [])

  const onMouseUp = useCallback(() => { dragging.current = false }, [])

  const onWheel = useCallback((e: WheelEvent) => {
    e.preventDefault()
    setScale(s => Math.min(MAX_SCALE, Math.max(MIN_SCALE, s - e.deltaY * 0.001)))
  }, [])

  useEffect(() => {
    const el = containerRef.current
    if (!el) return
    el.addEventListener('wheel', onWheel, { passive: false })
    return () => el.removeEventListener('wheel', onWheel)
  }, [onWheel])

  // Keyboard shortcut: Ctrl+F to focus search
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if ((e.ctrlKey || e.metaKey) && e.key === 'f') {
        e.preventDefault()
        searchRef.current?.focus()
      }
      if (e.key === 'Escape') {
        setSearch('')
        searchRef.current?.blur()
      }
    }
    window.addEventListener('keydown', handler)
    return () => window.removeEventListener('keydown', handler)
  }, [])

  const nodeMap = Object.fromEntries(NODES.map(n => [n.id, n]))

  const hasSearch    = search.trim().length > 0
  const hasSelection = selectedId !== null

  return (
    <div
      ref={containerRef}
      onMouseDown={onMouseDown}
      onMouseMove={onMouseMove}
      onMouseUp={onMouseUp}
      onMouseLeave={onMouseUp}
      style={{
        width: '100%', height: '100%',
        overflow: 'hidden',
        cursor: dragging.current ? 'grabbing' : 'grab',
        position: 'relative',
        background: '#030810',
      }}
    >
      {/* ── Search bar ────────────────────────────────────────────────────── */}
      <div
        className="arch-search"
        style={{
          position: 'absolute', top: 12, left: '50%',
          transform: 'translateX(-50%)',
          zIndex: 20, display: 'flex', alignItems: 'center', gap: '6px',
        }}
      >
        <div style={{ position: 'relative' }}>
          <span style={{
            position: 'absolute', left: '10px', top: '50%', transform: 'translateY(-50%)',
            color: '#334155', fontSize: '12px', pointerEvents: 'none',
          }}>🔍</span>
          <input
            ref={searchRef}
            value={search}
            onChange={e => setSearch(e.target.value)}
            placeholder="Meklēt mezglus... (Ctrl+F)"
            style={{
              background: '#0a1830',
              border: `1px solid ${hasSearch ? '#22d3ee60' : '#1a3550'}`,
              borderRadius: '8px',
              padding: '6px 12px 6px 30px',
              color: '#c8d8e8',
              fontFamily: "'Consolas','Fira Code',monospace",
              fontSize: '11px',
              outline: 'none',
              width: '240px',
              boxShadow: hasSearch ? '0 0 12px #22d3ee18' : 'none',
              transition: 'all 0.2s',
            }}
          />
          {hasSearch && (
            <span
              onClick={() => setSearch('')}
              style={{
                position: 'absolute', right: '8px', top: '50%',
                transform: 'translateY(-50%)',
                color: '#334155', cursor: 'pointer', fontSize: '12px',
                lineHeight: 1,
              }}
            >✕</span>
          )}
        </div>
        {hasSearch && (
          <div style={{
            background: '#0a1830', border: '1px solid #1a3550',
            borderRadius: '6px', padding: '5px 10px',
            color: '#22d3ee', fontSize: '10px', fontFamily: 'monospace',
            whiteSpace: 'nowrap',
          }}>
            {matchedNodeIds.size} atrasts
          </div>
        )}
      </div>

      {/* ── Zoom / Reset controls ─────────────────────────────────────────── */}
      <div style={{ position: 'absolute', bottom: 14, right: 14, display: 'flex', gap: '4px', zIndex: 20 }}>
        {[
          { label: '+',  title: 'Tuvināt',   action: () => setScale(s => Math.min(MAX_SCALE, s + 0.1)) },
          { label: '−',  title: 'Tālināt',   action: () => setScale(s => Math.max(MIN_SCALE, s - 0.1)) },
          { label: '⊡',  title: 'Atiestatīt', action: () => { setScale(0.85); setPan({ x: 0, y: 0 }) } },
        ].map(({ label, title, action }) => (
          <button key={label} onClick={action} title={title} style={{
            width: 32, height: 32,
            background: '#0a1525', border: '1px solid #1a3550',
            borderRadius: '7px', color: '#22d3ee', cursor: 'pointer',
            fontSize: label === '⊡' ? '14px' : '20px',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            fontFamily: 'monospace', transition: 'border-color 0.15s',
          }}>
            {label}
          </button>
        ))}
        <div style={{
          height: 32, padding: '0 10px',
          background: '#0a1525', border: '1px solid #1a3550',
          borderRadius: '7px', color: '#22d3ee80',
          fontSize: '10px', display: 'flex', alignItems: 'center',
          fontFamily: 'monospace', letterSpacing: '0.05em',
        }}>
          {Math.round(scale * 100)}%
        </div>
      </div>

      {/* ── Minimap ───────────────────────────────────────────────────────── */}
      <div style={{
        position: 'absolute', bottom: 14, left: 14,
        zIndex: 20, background: '#070f1c',
        border: '1px solid #1a3550', borderRadius: '8px',
        overflow: 'hidden',
        boxShadow: '0 4px 20px rgba(0,0,0,0.5)',
      }}>
        <div style={{ padding: '3px 8px', borderBottom: '1px solid #0f2035', fontSize: '8px', color: '#1e3a5f', letterSpacing: '0.15em', fontFamily: 'monospace' }}>
          MINIMAP
        </div>
        <svg width="192" height="91" viewBox={`0 0 ${VW} ${VH}`} style={{ display: 'block' }}>
          {/* Mini zone backgrounds */}
          {TIERS.map((t, i) => (
            <rect key={i} x="18" y={t.y} width={i < 5 ? 1564 : 1110} height={t.h}
              rx="6"
              fill={i === 5 ? GROUP_COLORS.ai.bg : i === 0 ? GROUP_COLORS.external.bg :
                i === 3 || i === 4 ? GROUP_COLORS.backend.bg : 'rgba(255,255,255,0.01)'}
              stroke={i === 5 ? GROUP_COLORS.ai.border : i === 0 ? GROUP_COLORS.external.border : '#1a3550'}
              strokeWidth="3"
            />
          ))}
          {/* Mini nodes */}
          {NODES.map(n => (
            <rect
              key={n.id}
              x={n.x} y={n.y} width={n.w} height={n.h}
              rx="6"
              fill={selectedId === n.id ? n.color : matchedNodeIds.has(n.id) ? n.color + '80' : n.color + '30'}
              stroke={n.color}
              strokeWidth={selectedId === n.id ? 4 : 2}
            />
          ))}
        </svg>
      </div>

      {/* ── Legend ────────────────────────────────────────────────────────── */}
      <div style={{
        position: 'absolute', top: 12, right: 14, zIndex: 20,
        background: '#070f1c', border: '1px solid #1a3550',
        borderRadius: '8px', padding: '8px 10px',
        fontFamily: 'monospace',
      }}>
        {Object.entries(GROUP_COLORS).map(([grp, c]) => (
          <div key={grp} style={{ display: 'flex', alignItems: 'center', gap: '6px', marginBottom: '3px' }}>
            <span style={{ fontSize: '12px', color: c.label, lineHeight: 1 }}>{GROUP_ICON[grp]}</span>
            <span style={{ fontSize: '9px', color: c.label, letterSpacing: '0.1em', textTransform: 'uppercase' }}>{grp}</span>
          </div>
        ))}
        <div style={{ borderTop: '1px solid #0f2035', marginTop: '5px', paddingTop: '5px' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '6px', marginBottom: '2px' }}>
            <svg width="24" height="8"><line x1="0" y1="4" x2="24" y2="4" stroke="#22d3ee" strokeWidth="2" /></svg>
            <span style={{ fontSize: '8px', color: '#334155' }}>galvenā plūsma</span>
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
            <svg width="24" height="8"><line x1="0" y1="4" x2="24" y2="4" stroke="#475569" strokeWidth="1.5" strokeDasharray="4 2" /></svg>
            <span style={{ fontSize: '8px', color: '#334155' }}>sekundārā</span>
          </div>
        </div>
      </div>

      {/* ── Main SVG ──────────────────────────────────────────────────────── */}
      <svg
        viewBox={`0 0 ${VW} ${VH}`}
        style={{
          width: VW * scale,
          height: VH * scale,
          display: 'block',
          transform: `translate(${pan.x}px, ${pan.y}px)`,
          transformOrigin: '0 0',
          fontFamily: "'Consolas','Fira Code',monospace",
          userSelect: 'none',
        }}
      >
        <defs>
          {ARROW_DEFS.map(a => (
            <marker key={a.id} id={a.id}
              markerWidth="10" markerHeight="10"
              refX="8" refY="4" orient="auto" markerUnits="strokeWidth"
            >
              <path d="M0,1 L0,7 L10,4 z" fill={a.fill} />
            </marker>
          ))}
          <filter id="glow-md" x="-50%" y="-50%" width="200%" height="200%">
            <feGaussianBlur stdDeviation="5" result="blur" />
            <feMerge><feMergeNode in="blur" /><feMergeNode in="SourceGraphic" /></feMerge>
          </filter>
          <filter id="glow-sm" x="-30%" y="-30%" width="160%" height="160%">
            <feGaussianBlur stdDeviation="3" result="blur" />
            <feMerge><feMergeNode in="blur" /><feMergeNode in="SourceGraphic" /></feMerge>
          </filter>
          {/* Stripe pattern for zone backgrounds */}
          <pattern id="stripe-backend" patternUnits="userSpaceOnUse" width="20" height="20" patternTransform="rotate(45)">
            <line x1="0" y1="0" x2="0" y2="20" stroke="#22d3ee" strokeWidth="0.4" strokeOpacity="0.06" />
          </pattern>
          <pattern id="stripe-frontend" patternUnits="userSpaceOnUse" width="20" height="20" patternTransform="rotate(45)">
            <line x1="0" y1="0" x2="0" y2="20" stroke="#06b6d4" strokeWidth="0.4" strokeOpacity="0.06" />
          </pattern>
          <pattern id="stripe-ai" patternUnits="userSpaceOnUse" width="20" height="20" patternTransform="rotate(45)">
            <line x1="0" y1="0" x2="0" y2="20" stroke="#a855f7" strokeWidth="0.4" strokeOpacity="0.10" />
          </pattern>
        </defs>

        {/* ── Tier row separators (horizontal grid lines) ─────────────────── */}
        {TIERS.slice(1).map((t, i) => (
          <line key={i}
            x1="18" y1={t.y} x2={VW - 18} y2={t.y}
            stroke="#0d1e30" strokeWidth="1.5"
          />
        ))}

        {/* ── Zone backgrounds ─────────────────────────────────────────────── */}

        {/* EXTERNAL zone */}
        <rect x="18" y="8" width="1564" height="100"
          rx="10" fill={GROUP_COLORS.external.bg}
          stroke={GROUP_COLORS.external.border} strokeWidth="1.5" strokeDasharray="6 3" />
        <rect x="18" y="8" width="1564" height="100"
          rx="10" fill="url(#stripe-backend)" opacity="0.3" />
        <text x="34" y="26" fill={GROUP_COLORS.external.label}
          fontSize="10" letterSpacing="3" fontWeight="bold" opacity="0.7">
          TIER 0 · EXTERNAL
        </text>

        {/* BACKEND zone */}
        <rect x="18" y="138" width="740" height="500"
          rx="10" fill={GROUP_COLORS.backend.bg}
          stroke={GROUP_COLORS.backend.border} strokeWidth="1.5" strokeDasharray="6 3" />
        <rect x="18" y="138" width="740" height="500"
          rx="10" fill="url(#stripe-backend)" />
        <text x="34" y="158" fill={GROUP_COLORS.backend.label}
          fontSize="10" letterSpacing="3" fontWeight="bold" opacity="0.7">
          BACKEND · Node.js + Express :3002
        </text>

        {/* FRONTEND zone */}
        <rect x="1090" y="138" width="492" height="370"
          rx="10" fill={GROUP_COLORS.frontend.bg}
          stroke={GROUP_COLORS.frontend.border} strokeWidth="1.5" strokeDasharray="6 3" />
        <rect x="1090" y="138" width="492" height="370"
          rx="10" fill="url(#stripe-frontend)" />
        <text x="1106" y="158" fill={GROUP_COLORS.frontend.label}
          fontSize="10" letterSpacing="3" fontWeight="bold" opacity="0.7">
          FRONTEND · React 18 + Vite
        </text>

        {/* AI boundary divider */}
        <line x1="18" y1="638" x2="1110" y2="638"
          stroke="#a855f7" strokeWidth="1.5" strokeDasharray="12 5" opacity="0.5" />
        <rect x="470" y="626" width="258" height="24"
          rx="6" fill="#06010e" stroke="#a855f7" strokeWidth="1.2" opacity="0.97" />
        <text x="599" y="642" fill="#a855f7" fontSize="9.5" textAnchor="middle"
          letterSpacing="2" fontWeight="bold">AI ↔ BACKEND BOUNDARY</text>

        {/* AI zone */}
        <rect x="18" y="640" width="1110" height="108"
          rx="10" fill={GROUP_COLORS.ai.bg}
          stroke={GROUP_COLORS.ai.border} strokeWidth="1.5" strokeDasharray="6 3" />
        <rect x="18" y="640" width="1110" height="108"
          rx="10" fill="url(#stripe-ai)" />
        <text x="34" y="660" fill={GROUP_COLORS.ai.label}
          fontSize="10" letterSpacing="3" fontWeight="bold" opacity="0.85">
          TIER 5 · AI MODULE · ai/
        </text>

        {/* Tier row labels (right margin) */}
        {[
          { label: 'T0', y: 59,  color: '#475569' },
          { label: 'T1', y: 191, color: '#22d3ee' },
          { label: 'T2', y: 320, color: '#22d3ee' },
          { label: 'T3', y: 450, color: '#0891b2' },
          { label: 'T4', y: 580, color: '#a855f7' },
          { label: 'T5', y: 695, color: '#a855f7' },
        ].map(({ label, y, color }) => (
          <g key={label}>
            <rect x={VW - 32} y={y - 14} width="28" height="20" rx="4"
              fill="#0a1525" stroke={color + '40'} strokeWidth="1" />
            <text x={VW - 18} y={y + 2} fill={color} fontSize="9"
              textAnchor="middle" fontWeight="bold" letterSpacing="0.5" opacity="0.8">
              {label}
            </text>
          </g>
        ))}

        {/* ── Edges ─────────────────────────────────────────────────────────── */}
        {EDGES.map((edge, i) => {
          const fn = nodeMap[edge.from]; const tn = nodeMap[edge.to]
          if (!fn || !tn) return null
          const { d, lx, ly } = edgePath(fn.x, fn.y, fn.w, fn.h, tn.x, tn.y, tn.w, tn.h)

          const isConnected = connectedEdgeIds.has(i)
          const isHov       = hovEdge === i
          const isSel       = selectedId === edge.from || selectedId === edge.to

          let op = 0.45
          if (isHov) op = 1
          else if (isConnected) op = 0.9
          else if (hasSearch) op = (matchedNodeIds.has(edge.from) || matchedNodeIds.has(edge.to)) ? 0.7 : 0.12
          else if (hasSelection) op = isSel ? 0.85 : 0.1

          const strokeW = isHov ? 2.5 : isConnected ? 2 : 1.5
          const aid = arrowId(edge.color)

          return (
            <g key={i}
              onMouseEnter={() => setHovEdge(i)}
              onMouseLeave={() => setHovEdge(null)}
              style={{ opacity: op, transition: 'opacity 0.18s' }}
            >
              {/* Fat invisible hit zone */}
              <path d={d} fill="none" stroke="transparent" strokeWidth="16" style={{ cursor: 'crosshair' }} />
              {/* Edge glow on hover */}
              {(isHov || isConnected) && (
                <path d={d} fill="none"
                  stroke={edge.color} strokeWidth={strokeW + 3}
                  strokeDasharray={edge.dashed ? '8 4' : undefined}
                  opacity="0.15" filter="url(#glow-sm)"
                />
              )}
              {/* Visible edge */}
              <path
                d={d} fill="none"
                stroke={isHov ? 'white' : edge.color}
                strokeWidth={strokeW}
                strokeDasharray={edge.dashed ? '8 4' : undefined}
                markerEnd={`url(#${aid})`}
              />
              {/* Edge label */}
              <g style={{ pointerEvents: 'none' }}>
                <rect
                  x={lx - 44} y={ly - 11}
                  width="88" height="20" rx="6"
                  fill="#070e1b"
                  stroke={isHov || isConnected ? edge.color : edge.color + '40'}
                  strokeWidth={isHov ? 1.2 : 0.8}
                  opacity="0.97"
                />
                <text
                  x={lx} y={ly + 3}
                  fill={isHov ? 'white' : isConnected ? edge.color : edge.color + 'cc'}
                  fontSize="9.5" textAnchor="middle"
                  fontWeight={isHov || isConnected ? 'bold' : 'normal'}
                  letterSpacing="0.03em"
                >
                  {edge.label}
                </text>
              </g>
            </g>
          )
        })}

        {/* ── Nodes ─────────────────────────────────────────────────────────── */}
        {NODES.map(node => {
          const isHov     = hovNode === node.id
          const isSel     = selectedId === node.id
          const isMatched = matchedNodeIds.has(node.id)
          const isConn    = connectedEdgeIds.size > 0 &&
            EDGES.some((e, i) => connectedEdgeIds.has(i) && (e.from === node.id || e.to === node.id))

          // Opacity logic: search dimming, selection dimming
          let dim = 1
          if (hasSearch) dim = isMatched ? 1 : 0.15
          else if (hasSelection && !isSel && !isConn) dim = 0.2

          return (
            <g
              key={node.id}
              className="arch-node"
              onClick={(e) => { e.stopPropagation(); onNodeClick(node.id) }}
              onMouseEnter={() => setHovNode(node.id)}
              onMouseLeave={() => setHovNode(null)}
              style={{ cursor: 'pointer', opacity: dim, transition: 'opacity 0.18s' }}
            >
              {/* Selection / match glow */}
              {(isSel || isMatched) && (
                <rect
                  x={node.x - 6} y={node.y - 6}
                  width={node.w + 12} height={node.h + 12}
                  rx="13" fill={node.color} opacity={isSel ? 0.18 : 0.10}
                  filter="url(#glow-md)"
                />
              )}

              {/* Node body */}
              <rect
                x={node.x} y={node.y}
                width={node.w} height={node.h}
                rx="10"
                fill={isSel ? `${node.color}20` : isHov ? `${node.color}15` : isMatched ? `${node.color}12` : '#0b1828'}
                stroke={node.color}
                strokeWidth={isSel ? 2.5 : isHov || isMatched ? 2 : 1.2}
              />

              {/* Top color accent bar */}
              <rect
                x={node.x + 2} y={node.y + 2}
                width={node.w - 4} height="5"
                rx="8" fill={node.color}
                opacity={isSel ? 0.9 : isHov ? 0.6 : 0.4}
              />

              {/* Group icon (top-left) */}
              <text
                x={node.x + 12} y={node.y + 26}
                fill={node.color} fontSize="11"
                opacity={isSel ? 0.9 : 0.45}
              >
                {GROUP_ICON[node.group]}
              </text>

              {/* Node label */}
              <text
                x={node.x + node.w / 2 + 4}
                y={node.y + 30}
                fill={isSel ? '#ffffff' : isHov ? '#ffffff' : isMatched ? '#ffffff' : node.color}
                fontSize="13"
                fontWeight="bold"
                textAnchor="middle"
                letterSpacing="0.9"
              >
                {node.label}
              </text>

              {/* Sublabel — much more visible now */}
              <text
                x={node.x + node.w / 2}
                y={node.y + 49}
                fill={isSel ? '#94a3b8' : isHov ? '#7fa8c8' : '#4a6b8a'}
                fontSize="10.5"
                textAnchor="middle"
                letterSpacing="0.2"
              >
                {node.sub}
              </text>

              {/* File count badge */}
              {node.files.length > 0 && (
                <g>
                  <rect
                    x={node.x + node.w - 28} y={node.y + node.h - 18}
                    width="26" height="12" rx="4"
                    fill="#0a1525" stroke={node.color + '40'} strokeWidth="1"
                  />
                  <text
                    x={node.x + node.w - 15} y={node.y + node.h - 8}
                    fill={node.color} fontSize="8" textAnchor="middle" opacity="0.7"
                  >
                    {node.files.length}f
                  </text>
                </g>
              )}

              {/* Hover hint */}
              {isHov && !isSel && (
                <text
                  x={node.x + node.w / 2}
                  y={node.y + node.h - 8}
                  fill={node.color} fontSize="8"
                  textAnchor="middle" opacity="0.75"
                >
                  klikšķini · details
                </text>
              )}

              {/* Selected indicator dot */}
              {isSel && (
                <circle
                  cx={node.x + node.w - 10} cy={node.y + 12}
                  r="4.5" fill={node.color}
                  filter="url(#glow-sm)"
                />
              )}

              {/* Search match indicator */}
              {isMatched && !isSel && (
                <rect
                  x={node.x + node.w - 10} y={node.y + 8}
                  width="8" height="8" rx="2"
                  fill="#22d3ee" opacity="0.9"
                  filter="url(#glow-sm)"
                />
              )}
            </g>
          )
        })}
      </svg>
    </div>
  )
}
