// ═══════════════════════════════════════════════════════════════
// PRESTIGE DASHBOARD - SYSTEM RESOURCES CARD
// Feature: system-resources
// Endpoint: GET /api/system/metrics (via systemApi.getMetrics())
// ═══════════════════════════════════════════════════════════════

import React, { useEffect, useState, useCallback } from 'react'
import { Cpu, MemoryStick, HardDrive, Wifi, RefreshCw, AlertTriangle } from 'lucide-react'
import { systemApi } from '@/services/system-api'
import type { SystemMetrics } from '@/services/system-api'

// ─── Types ────────────────────────────────────────────────────

interface ResourceBarProps {
  label: string
  value: number      // 0-100 percentage
  detail: string
  color: string      // Tailwind colour class
  icon: React.ReactNode
  warning?: boolean
}

// ─── Helpers ─────────────────────────────────────────────────

function formatUptime(seconds: number): string {
  const d = Math.floor(seconds / 86400)
  const h = Math.floor((seconds % 86400) / 3600)
  const m = Math.floor((seconds % 3600) / 60)
  if (d > 0) return `${d}d ${h}h ${m}m`
  if (h > 0) return `${h}h ${m}m`
  return `${m}m`
}

function formatGB(gb: number): string {
  return gb < 1 ? `${(gb * 1024).toFixed(0)} MB` : `${gb.toFixed(1)} GB`
}

function barColor(pct: number): string {
  if (pct >= 90) return 'bg-red-500'
  if (pct >= 75) return 'bg-amber-400'
  return 'bg-cyan-400'
}

function textColor(pct: number): string {
  if (pct >= 90) return 'text-red-400'
  if (pct >= 75) return 'text-amber-400'
  return 'text-cyan-400'
}

// ─── Resource Bar ────────────────────────────────────────────

const ResourceBar: React.FC<ResourceBarProps> = ({ label, value, detail, icon, warning }) => {
  const pct = Math.min(100, Math.max(0, value))
  const bColor = barColor(pct)
  const tColor = textColor(pct)

  return (
    <div className="space-y-2">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <span className={`${tColor}`}>{icon}</span>
          <span className="text-sm font-medium text-gray-200">{label}</span>
          {warning && <AlertTriangle className="w-3 h-3 text-amber-400" />}
        </div>
        <div className="flex items-center gap-2">
          <span className="text-xs text-gray-400">{detail}</span>
          <span className={`text-sm font-mono font-bold ${tColor}`}>{pct.toFixed(1)}%</span>
        </div>
      </div>
      <div className="h-2 bg-gray-800 rounded-full overflow-hidden">
        <div
          className={`h-full rounded-full transition-all duration-700 ${bColor}`}
          style={{ width: `${pct}%` }}
        />
      </div>
    </div>
  )
}

// ─── Stat Tile ────────────────────────────────────────────────

const StatTile: React.FC<{ label: string; value: string; sub?: string; color?: string }> = ({
  label, value, sub, color = 'text-cyan-400',
}) => (
  <div className="bg-gray-800/40 border border-gray-700/50 rounded-lg p-3">
    <div className="text-xs text-gray-500 uppercase tracking-wider mb-1">{label}</div>
    <div className={`text-lg font-mono font-bold ${color}`}>{value}</div>
    {sub && <div className="text-xs text-gray-500 mt-0.5">{sub}</div>}
  </div>
)

// ─── Main Component ───────────────────────────────────────────

export const SystemResourcesCard: React.FC = () => {
  const [metrics, setMetrics] = useState<SystemMetrics | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null)
  const [refreshing, setRefreshing] = useState(false)

  const fetchMetrics = useCallback(async (silent = false) => {
    if (!silent) setLoading(true)
    else setRefreshing(true)
    setError(null)

    try {
      const data = await systemApi.getMetrics()
      setMetrics(data)
      setLastUpdated(new Date())
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'Failed to fetch metrics'
      setError(msg)
    } finally {
      setLoading(false)
      setRefreshing(false)
    }
  }, [])

  // Initial load
  useEffect(() => {
    fetchMetrics()
  }, [fetchMetrics])

  // Auto-refresh every 10s
  useEffect(() => {
    const timer = setInterval(() => fetchMetrics(true), 10_000)
    return () => clearInterval(timer)
  }, [fetchMetrics])

  // ── Loading state ───────────────────────────────────────────
  if (loading) {
    return (
      <div className="bg-gray-900/60 border border-gray-700/50 rounded-xl p-6 animate-pulse">
        <div className="h-5 bg-gray-700 rounded w-40 mb-4" />
        <div className="space-y-4">
          {[1, 2, 3].map(i => (
            <div key={i} className="space-y-2">
              <div className="h-3 bg-gray-700 rounded w-full" />
              <div className="h-2 bg-gray-800 rounded-full w-full" />
            </div>
          ))}
        </div>
      </div>
    )
  }

  // ── Error state ─────────────────────────────────────────────
  if (error && !metrics) {
    return (
      <div className="bg-gray-900/60 border border-red-500/30 rounded-xl p-6">
        <div className="flex items-center gap-2 text-red-400 mb-3">
          <AlertTriangle className="w-5 h-5" />
          <span className="font-medium">Failed to load system metrics</span>
        </div>
        <p className="text-sm text-gray-400 mb-4">{error}</p>
        <button
          onClick={() => fetchMetrics()}
          className="px-4 py-2 bg-cyan-500/20 text-cyan-400 border border-cyan-500/40 rounded-lg text-sm hover:bg-cyan-500/30 transition-colors"
        >
          Retry
        </button>
      </div>
    )
  }

  if (!metrics) return null

  const diskNA = metrics.disk.total === 0

  return (
    <div className="bg-gray-900/60 border border-gray-700/50 rounded-xl p-6 space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-base font-semibold text-gray-100">System Resources</h2>
          {lastUpdated && (
            <p className="text-xs text-gray-500 mt-0.5">
              Updated {lastUpdated.toLocaleTimeString()}
            </p>
          )}
        </div>
        <button
          onClick={() => fetchMetrics(true)}
          disabled={refreshing}
          className="p-2 rounded-lg text-gray-400 hover:text-cyan-400 hover:bg-gray-800 transition-colors disabled:opacity-50"
          title="Refresh"
        >
          <RefreshCw className={`w-4 h-4 ${refreshing ? 'animate-spin' : ''}`} />
        </button>
      </div>

      {/* Resource bars */}
      <div className="space-y-5">
        <ResourceBar
          label="CPU"
          value={metrics.cpu.usage}
          detail={`${metrics.cpu.cores} cores · ${metrics.cpu.model.split(' ').slice(0, 3).join(' ')}`}
          color="cyan"
          icon={<Cpu className="w-4 h-4" />}
          warning={metrics.cpu.usage > 80}
        />

        <ResourceBar
          label="Memory"
          value={metrics.memory.percentage}
          detail={`${formatGB(metrics.memory.used)} / ${formatGB(metrics.memory.total)}`}
          color="purple"
          icon={<MemoryStick className="w-4 h-4" />}
          warning={metrics.memory.percentage > 85}
        />

        <ResourceBar
          label="Disk"
          value={diskNA ? 0 : metrics.disk.percentage}
          detail={diskNA ? 'N/A' : `${formatGB(metrics.disk.used)} / ${formatGB(metrics.disk.total)}`}
          color="green"
          icon={<HardDrive className="w-4 h-4" />}
          warning={!diskNA && metrics.disk.percentage > 90}
        />
      </div>

      {/* Stat tiles */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 pt-1 border-t border-gray-800">
        <StatTile
          label="Uptime"
          value={formatUptime(metrics.uptime)}
          color="text-cyan-400"
        />
        <StatTile
          label="CPU Cores"
          value={String(metrics.cpu.cores)}
          sub={metrics.cpu.model.split(' ').slice(0, 2).join(' ')}
          color="text-cyan-400"
        />
        <StatTile
          label="RAM Free"
          value={formatGB(metrics.memory.free)}
          sub={`${formatGB(metrics.memory.total)} total`}
          color={metrics.memory.percentage > 85 ? 'text-amber-400' : 'text-green-400'}
        />
        <StatTile
          label="Disk Free"
          value={diskNA ? 'N/A' : formatGB(metrics.disk.free)}
          sub={diskNA ? 'Unavailable' : `${formatGB(metrics.disk.total)} total`}
          color={!diskNA && metrics.disk.percentage > 90 ? 'text-red-400' : 'text-green-400'}
        />
      </div>

      {/* Network (shown only when data available) */}
      {(metrics.network.rx > 0 || metrics.network.tx > 0) && (
        <div className="pt-1 border-t border-gray-800">
          <div className="flex items-center gap-2 text-xs text-gray-400 mb-2">
            <Wifi className="w-3 h-3" />
            <span>Network</span>
          </div>
          <div className="grid grid-cols-2 gap-3">
            <StatTile label="RX" value={`${(metrics.network.rx / 1024).toFixed(1)} KB/s`} color="text-cyan-400" />
            <StatTile label="TX" value={`${(metrics.network.tx / 1024).toFixed(1)} KB/s`} color="text-cyan-400" />
          </div>
        </div>
      )}

      {/* Disk N/A notice */}
      {diskNA && (
        <p className="text-xs text-gray-600 italic">
          Disk stats unavailable (Node &lt; 18.15 or unsupported OS)
        </p>
      )}
    </div>
  )
}

export default SystemResourcesCard
