import { useMemo } from 'react'
import { Box } from 'lucide-react'

interface Triangle {
  v1: [number, number, number]
  v2: [number, number, number]
  v3: [number, number, number]
  normal: [number, number, number]
}

interface MeshData {
  triangles: Triangle[]
  bounds: { 
    min: [number, number, number]
    max: [number, number, number]
  }
}

interface ModelInfoProps {
  mesh: MeshData
  scale: number
}

export function ModelInfo({ mesh, scale }: ModelInfoProps) {
  const stats = useMemo(() => {
    const { triangles, bounds } = mesh
    
    // Calculate dimensions
    const width = (bounds.max[0] - bounds.min[0]) * scale
    const height = (bounds.max[1] - bounds.min[1]) * scale
    const depth = (bounds.max[2] - bounds.min[2]) * scale
    
    // Calculate surface area (approximate)
    let surfaceArea = 0
    for (const tri of triangles) {
      const v1 = tri.v1
      const v2 = tri.v2
      const v3 = tri.v3
      
      // Triangle area using Heron's formula
      const a = Math.sqrt(
        Math.pow(v2[0] - v1[0], 2) + 
        Math.pow(v2[1] - v1[1], 2) + 
        Math.pow(v2[2] - v1[2], 2)
      )
      const b = Math.sqrt(
        Math.pow(v3[0] - v2[0], 2) + 
        Math.pow(v3[1] - v2[1], 2) + 
        Math.pow(v3[2] - v2[2], 2)
      )
      const c = Math.sqrt(
        Math.pow(v1[0] - v3[0], 2) + 
        Math.pow(v1[1] - v3[1], 2) + 
        Math.pow(v1[2] - v3[2], 2)
      )
      
      const s = (a + b + c) / 2
      const area = Math.sqrt(s * (s - a) * (s - b) * (s - c))
      surfaceArea += area
    }
    
    surfaceArea *= Math.pow(scale, 2) // Apply scale to area
    
    // Estimate volume (using bounding box - rough estimate)
    const volume = width * height * depth
    
    // Estimate weight (assuming PLA density ~1.24 g/cm³)
    const volumeCm3 = volume / 1000 // mm³ to cm³
    const weightPLA = volumeCm3 * 1.24
    const weightABS = volumeCm3 * 1.04
    
    return {
      triangles: triangles.length,
      vertices: triangles.length * 3,
      width,
      height,
      depth,
      surfaceArea,
      volume,
      weightPLA,
      weightABS
    }
  }, [mesh, scale])

  return (
    <div className="w-72 bg-[#1e2230]/95 backdrop-blur-sm border-l border-gray-700/50 flex flex-col overflow-hidden">
      {/* Header */}
      <div className="px-4 py-3 border-b border-gray-700/50">
        <div className="flex items-center gap-2">
          <Box className="w-4 h-4 text-cyan-400" />
          <h3 className="text-sm font-semibold text-gray-100">Model Info</h3>
        </div>
        <div className="mt-1 text-xs text-gray-400">
          3D Mesh Statistics
        </div>
      </div>

      {/* Statistics */}
      <div className="flex-1 overflow-y-auto">
        {/* Geometry */}
        <div className="p-4">
          <div className="text-xs font-medium text-gray-400 mb-2">Geometry</div>
          <div className="space-y-2">
            <div className="flex justify-between items-center p-2 rounded bg-gray-800/40">
              <span className="text-xs text-gray-300">Triangles</span>
              <span className="text-xs text-cyan-400 font-mono font-semibold">
                {stats.triangles.toLocaleString()}
              </span>
            </div>
            <div className="flex justify-between items-center p-2 rounded bg-gray-800/40">
              <span className="text-xs text-gray-300">Vertices</span>
              <span className="text-xs text-cyan-400 font-mono font-semibold">
                {stats.vertices.toLocaleString()}
              </span>
            </div>
            <div className="flex justify-between items-center p-2 rounded bg-gray-800/40">
              <span className="text-xs text-gray-300">Surface Area</span>
              <span className="text-xs text-cyan-400 font-mono font-semibold">
                {stats.surfaceArea.toFixed(1)} mm²
              </span>
            </div>
          </div>
        </div>

        {/* Dimensions */}
        <div className="px-4 pb-4">
          <div className="text-xs font-medium text-gray-400 mb-2">Dimensions (mm)</div>
          <div className="space-y-2">
            <div className="flex justify-between items-center p-2 rounded bg-gray-800/40">
              <span className="text-xs text-gray-300">Width (X)</span>
              <span className="text-xs text-cyan-400 font-mono font-semibold">
                {stats.width.toFixed(2)}
              </span>
            </div>
            <div className="flex justify-between items-center p-2 rounded bg-gray-800/40">
              <span className="text-xs text-gray-300">Height (Y)</span>
              <span className="text-xs text-cyan-400 font-mono font-semibold">
                {stats.height.toFixed(2)}
              </span>
            </div>
            <div className="flex justify-between items-center p-2 rounded bg-gray-800/40">
              <span className="text-xs text-gray-300">Depth (Z)</span>
              <span className="text-xs text-cyan-400 font-mono font-semibold">
                {stats.depth.toFixed(2)}
              </span>
            </div>
            <div className="flex justify-between items-center p-2 rounded bg-cyan-500/10 border border-cyan-500/30">
              <span className="text-xs text-gray-300">Volume</span>
              <span className="text-xs text-cyan-400 font-mono font-semibold">
                {stats.volume.toFixed(1)} mm³
              </span>
            </div>
          </div>
        </div>

        {/* Weight estimates */}
        <div className="px-4 pb-4">
          <div className="text-xs font-medium text-gray-400 mb-2">Estimated Weight</div>
          <div className="text-[10px] text-gray-500 mb-2">
            Based on bounding box volume (approximate)
          </div>
          <div className="space-y-2">
            <div className="flex justify-between items-center p-2 rounded bg-gray-800/40">
              <span className="text-xs text-gray-300">PLA (1.24 g/cm³)</span>
              <span className="text-xs text-orange-400 font-mono font-semibold">
                {stats.weightPLA.toFixed(1)} g
              </span>
            </div>
            <div className="flex justify-between items-center p-2 rounded bg-gray-800/40">
              <span className="text-xs text-gray-300">ABS (1.04 g/cm³)</span>
              <span className="text-xs text-orange-400 font-mono font-semibold">
                {stats.weightABS.toFixed(1)} g
              </span>
            </div>
          </div>
        </div>

        {/* Info note */}
        <div className="px-4 pb-4">
          <div className="p-3 rounded bg-blue-500/10 border border-blue-500/30">
            <div className="text-xs text-blue-300 mb-1 font-medium">💡 Tip</div>
            <div className="text-[10px] text-gray-400 leading-relaxed">
              Weight estimates are approximate. For accurate material usage, slice the model in your slicer software.
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}
