// ═══════════════════════════════════════════════════════════════
// FEATURE: PRINTER AI PANEL
// Extracted from PrinterDetailPage — per-printer AI toggle + recommendations
// ═══════════════════════════════════════════════════════════════

import { useState, useEffect } from 'react'
import { useNavigate } from 'react-router-dom'
import { Cpu } from 'lucide-react'
import { useAIStore, selectAIEnabled, selectAllRecommendations } from '@core/state/aiStore'
import { API_BASE_URL } from '@/utils/constants'
import type { Printer } from '@core/types/printer'

const LEVEL_INFO: Record<number, { label: string; desc: string; color: string; border: string; bg: string }> = {
  0: { label: 'L0 – Passive',   desc: 'AI observes only.',          color: 'text-gray-400',   border: 'border-gray-700',      bg: 'bg-gray-800/40' },
  1: { label: 'L1 – Advisory',  desc: 'AI recommends. You decide.', color: 'text-cyan-400',   border: 'border-cyan-500/40',   bg: 'bg-cyan-500/10' },
  2: { label: 'L2 – Automatic', desc: 'AI executes safe actions.',  color: 'text-yellow-400', border: 'border-yellow-500/40', bg: 'bg-yellow-500/10' },
}

export function PrinterAIPanel({ printer }: { printer: Printer }) {
  const navigate = useNavigate()
  const isEnabled = useAIStore(selectAIEnabled)
  const allRecommendations = useAIStore(selectAllRecommendations)
  const setEnabled = useAIStore(s => s.setAIEnabled)
  const getPrinterLevel = useAIStore(s => s.getPrinterLevel)
  const setPrinterLevel = useAIStore(s => s.setPrinterLevel)
  const printerLevel = getPrinterLevel(printer.id)

  const [showDisableConfirm, setShowDisableConfirm] = useState(false)
  const [showActivatedToast, setShowActivatedToast] = useState(false)
  const [aiStatus, setAiStatus] = useState<{ anomalyCount?: number } | null>(null)

  const printerRecs = allRecommendations.filter(r => r.printerId === printer.id && !r.acknowledged && !r.dismissed)

  useEffect(() => {
    fetch(`${API_BASE_URL}/api/ai/status`)
      .then(r => r.json())
      .then(d => { const data = d?.data ?? d; if (data) setAiStatus({ anomalyCount: data.activeAnomalies ?? 0 }) })
      .catch(() => {})
    fetch(`${API_BASE_URL}/api/printers/${printer.id}/ai-level`)
      .then(r => r.json())
      .then(d => { const lvl = d?.data?.level ?? d?.level; if (typeof lvl === 'number') setPrinterLevel(printer.id, lvl) })
      .catch(() => {})
  }, [printer.id])

  const executeToggle = async (next: boolean) => {
    setEnabled(next)
    try { await fetch(`${API_BASE_URL}/api/ai/${next ? 'start' : 'stop'}`, { method: 'POST' }) } catch {}
    if (next) { setShowActivatedToast(true); setTimeout(() => setShowActivatedToast(false), 6000) }
  }

  return (
    <>
      {showDisableConfirm && (
        <div className="fixed inset-0 z-[9999] flex items-center justify-center bg-black/80 backdrop-blur-sm">
          <div className="max-w-md w-full mx-4 p-6 rounded-lg border bg-gray-900 border-gray-700 shadow-2xl">
            <div className="flex items-center gap-3 mb-4"><span className="text-3xl">⚠️</span><h3 className="text-xl font-bold text-white">Disable AI Monitoring</h3></div>
            <p className="text-gray-300 mb-6">This will stop all AI analysis for this printer. Continue?</p>
            <div className="flex gap-3">
              <button onClick={() => setShowDisableConfirm(false)} className="flex-1 px-4 py-2 rounded-lg border border-gray-700 bg-gray-800 text-gray-300 font-medium">Cancel</button>
              <button onClick={() => { setShowDisableConfirm(false); executeToggle(false) }} className="flex-1 px-4 py-2 rounded-lg border font-medium bg-violet-500/20 border-violet-500/50 text-violet-400">DISABLE AI</button>
            </div>
          </div>
        </div>
      )}

      {showActivatedToast && (
        <div className="fixed inset-0 z-[9999] flex items-center justify-center bg-black/80 backdrop-blur-sm pointer-events-none">
          <div className="max-w-md w-full mx-4 p-6 rounded-lg border bg-gray-900 border-gray-700 shadow-2xl">
            <div className="flex items-center gap-3 mb-4"><span className="text-3xl">🤖</span><h3 className="text-xl font-bold text-white">AI MONITORING ACTIVE</h3></div>
            <p className="text-gray-300">AI system is now monitoring this printer.</p>
            <div className="mt-5 h-1 rounded-full overflow-hidden bg-gray-700">
              <div className="h-full rounded-full" style={{ background: 'linear-gradient(90deg, #7c3aed, #a78bfa)', animation: 'drain 6s linear forwards', width: '100%' }} />
            </div>
            <style>{`@keyframes drain { from { width: 100% } to { width: 0% } }`}</style>
          </div>
        </div>
      )}

      <div className="bg-gray-900/50 border border-violet-500/30 rounded-lg p-4">
        <div className="flex items-center justify-between mb-3">
          <h3 className="flex items-center gap-2 text-sm font-semibold text-gray-200">
            <Cpu className={`w-4 h-4 ${isEnabled ? 'text-violet-400 animate-pulse' : 'text-gray-500'}`} />AI Monitoring
          </h3>
          <button
            onClick={() => isEnabled ? setShowDisableConfirm(true) : executeToggle(true)}
            className={`relative inline-flex h-5 w-9 items-center rounded-full transition-colors ${isEnabled ? 'bg-violet-500' : 'bg-gray-700'}`}
          >
            <span className={`inline-block h-3.5 w-3.5 rounded-full bg-white shadow-sm transition-transform ${isEnabled ? 'translate-x-5' : 'translate-x-0.5'}`} />
          </button>
        </div>

        <div className="space-y-2 text-xs">
          <div className="flex justify-between">
            <span className="text-gray-400">AI Enabled</span>
            <span className={isEnabled ? 'text-green-400 font-semibold' : 'text-gray-500'}>{isEnabled ? '● Active' : '○ Disabled'}</span>
          </div>
          <div className="pt-1">
            <div className="flex items-center justify-between mb-1.5">
              <span className="text-gray-400">Autonomy Level</span>
              <button onClick={() => navigate(`/ai?printer=${printer.id}&tab=settings`)} className="text-[10px] text-cyan-400 hover:text-cyan-300 underline">Change →</button>
            </div>
            <div className={`flex items-center gap-2 px-2.5 py-2 rounded-lg border ${LEVEL_INFO[printerLevel]?.border ?? 'border-gray-700'} ${LEVEL_INFO[printerLevel]?.bg ?? 'bg-gray-800/40'}`}>
              <span className={`text-xs font-bold ${LEVEL_INFO[printerLevel]?.color ?? 'text-gray-400'}`}>{LEVEL_INFO[printerLevel]?.label ?? 'Unknown'}</span>
              <span className="text-[10px] text-gray-500 ml-1">{LEVEL_INFO[printerLevel]?.desc}</span>
            </div>
          </div>
          {aiStatus?.anomalyCount !== undefined && (
            <div className="flex justify-between">
              <span className="text-gray-400">Active Anomalies</span>
              <span className={aiStatus.anomalyCount > 0 ? 'text-orange-400 font-bold' : 'text-gray-500'}>
                {aiStatus.anomalyCount > 0 ? `⚠ ${aiStatus.anomalyCount}` : '✓ None'}
              </span>
            </div>
          )}
        </div>

        <div className="mt-3 pt-3 border-t border-gray-700">
          {printerRecs.length > 0 ? (
            <div className="space-y-2">
              <div className="text-[10px] text-gray-400 uppercase tracking-wider font-semibold mb-1">Pending ({printerRecs.length})</div>
              {printerRecs.slice(0, 3).map(rec => (
                <div key={rec.id} className={`p-2 rounded border text-xs ${
                  rec.priority === 'urgent' ? 'bg-red-500/10 border-red-500/40 text-red-300' :
                  rec.priority === 'high'   ? 'bg-orange-500/10 border-orange-500/40 text-orange-300' :
                                              'bg-violet-500/10 border-violet-500/30 text-violet-300'}`}>
                  <div className="font-semibold truncate">{rec.title}</div>
                  {rec.description && <div className="text-[10px] opacity-70 mt-0.5 line-clamp-2">{rec.description}</div>}
                </div>
              ))}
              {printerRecs.length > 3 && <div className="text-[10px] text-gray-500 text-center">+{printerRecs.length - 3} more in AI page</div>}
            </div>
          ) : (
            <p className="text-xs text-gray-500">{isEnabled ? '✓ No pending recommendations.' : 'Enable AI monitoring to receive recommendations.'}</p>
          )}
        </div>
      </div>
    </>
  )
}
