// ═══════════════════════════════════════════════════════════════
// PRESTIGE DASHBOARD - AI ACTION HISTORY
// ═══════════════════════════════════════════════════════════════

import { useState, useEffect, useMemo } from 'react'
import { History, ChevronDown, ChevronRight, RotateCcw, CheckCircle, XCircle, Clock, Zap } from 'lucide-react'

interface AIAction {
  id: string
  timestamp: string
  printerId: string
  printerName: string
  type: 'speed_reduce' | 'acceleration_reduce' | 'jerk_reduce' | 'pause' | 'safe_mode' | 'fan_increase' | 'recommendation'
  status: 'pending' | 'executed' | 'reverted' | 'rejected' | 'expired'
  confidence: number
  reason: string
  details?: {
    beforeValue?: number
    afterValue?: number
    parameter?: string
    revertedAt?: string
    rejectedBy?: string
  }
}

interface AIActionHistoryProps {
  printerId?: string
}

const ACTION_LABELS: Record<string, string> = {
  speed_reduce: 'Speed Reduction',
  acceleration_reduce: 'Acceleration Reduction',
  jerk_reduce: 'Jerk Reduction',
  pause: 'Print Pause',
  safe_mode: 'Safe Mode',
  fan_increase: 'Fan Increase',
  recommendation: 'Recommendation',
}

const STATUS_CONFIG: Record<string, { icon: typeof CheckCircle; color: string; label: string }> = {
  executed: { icon: CheckCircle, color: 'text-green-400', label: 'Executed' },
  reverted: { icon: RotateCcw, color: 'text-yellow-400', label: 'Reverted' },
  rejected: { icon: XCircle, color: 'text-red-400', label: 'Rejected' },
  pending: { icon: Clock, color: 'text-gray-400', label: 'Pending' },
  expired: { icon: Clock, color: 'text-gray-400', label: 'Expired' },
}

export function AIActionHistory({ printerId }: AIActionHistoryProps) {
  const [actions, setActions] = useState<AIAction[]>([])
  const [loading, setLoading] = useState(true)
  const [expandedId, setExpandedId] = useState<string | null>(null)
  const [filter, setFilter] = useState<'all' | 'executed' | 'reverted' | 'rejected'>('all')

  useEffect(() => {
    const fetchHistory = async () => {
      setLoading(true)
      try {
        const url = printerId
          ? `/api/ai/actions?printerId=${printerId}`
          : '/api/ai/actions'
        const res = await fetch(url)
        if (res.ok) {
          const data = await res.json()
          const list = data.actions ?? data.data ?? data
          setActions(Array.isArray(list) ? list : [])
        }
      } catch {
        // Graceful
      } finally {
        setLoading(false)
      }
    }
    fetchHistory()
  }, [printerId])

  const filteredActions = useMemo(() => {
    if (filter === 'all') return actions
    return actions.filter(a => a.status === filter)
  }, [actions, filter])

  const stats = useMemo(() => ({
    total: actions.length,
    executed: actions.filter(a => a.status === 'executed').length,
    reverted: actions.filter(a => a.status === 'reverted').length,
    rejected: actions.filter(a => a.status === 'rejected').length,
    avgConfidence: actions.length > 0
      ? (actions.reduce((s, a) => s + a.confidence, 0) / actions.length * 100).toFixed(0)
      : '0',
  }), [actions])

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex items-center gap-2">
        <History className="w-5 h-5 text-cyan-400" />
        <h2 className="text-lg font-semibold text-white">AI Action History</h2>
        <span className="text-xs text-gray-400">({filteredActions.length})</span>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-4 gap-2">
        {[
          { label: 'Total', value: stats.total },
          { label: 'Executed', value: stats.executed },
          { label: 'Reverted', value: stats.reverted },
          { label: 'Avg Confidence', value: `${stats.avgConfidence}%` },
        ].map(s => (
          <div key={s.label} className="p-2 rounded-lg bg-gray-900/50 border border-cyan-500/30 text-center">
            <div className="text-[10px] text-cyan-400 uppercase tracking-wider">{s.label}</div>
            <div className="text-sm font-bold font-mono text-cyan-400">{s.value}</div>
          </div>
        ))}
      </div>

      {/* Filter tabs */}
      <div className="flex gap-1 border-b border-gray-700 pb-1">
        {(['all', 'executed', 'reverted', 'rejected'] as const).map(f => (
          <button
            key={f}
            onClick={() => setFilter(f)}
            className={`px-3 py-1.5 text-xs rounded-lg border transition-all ${
              filter === f
                ? 'bg-cyan-500/20 text-cyan-400 border-cyan-500/50'
                : 'bg-gray-800/50 text-gray-400 border-gray-700 hover:border-cyan-500/30'
            }`}
          >
            {f === 'all' ? 'All' : f.charAt(0).toUpperCase() + f.slice(1)}
          </button>
        ))}
      </div>

      {/* Action list */}
      {loading ? (
        <div className="py-8 text-center text-gray-400 text-sm">Loading history...</div>
      ) : filteredActions.length === 0 ? (
        <div className="py-8 text-center text-gray-400">
          <Zap className="w-10 h-10 mx-auto mb-2 opacity-20" />
          <p className="text-sm">No AI actions recorded yet</p>
          <p className="text-xs mt-1">Actions will appear here when AI makes decisions</p>
        </div>
      ) : (
        <div className="space-y-1">
          {filteredActions.map(action => {
            const statusCfg = STATUS_CONFIG[action.status] || STATUS_CONFIG.pending
            const StatusIcon = statusCfg.icon
            const isExpanded = expandedId === action.id

            return (
              <div key={action.id} className="rounded-lg border border-gray-700 bg-gray-900/50 overflow-hidden">
                <button
                  onClick={() => setExpandedId(isExpanded ? null : action.id)}
                  className="w-full flex items-center gap-3 px-3 py-2.5 hover:bg-gray-800/50 transition-colors"
                >
                  {isExpanded
                    ? <ChevronDown className="w-3.5 h-3.5 text-gray-400 flex-shrink-0" />
                    : <ChevronRight className="w-3.5 h-3.5 text-gray-400 flex-shrink-0" />
                  }
                  <StatusIcon className={`w-4 h-4 flex-shrink-0 ${statusCfg.color}`} />
                  <div className="flex-1 text-left">
                    <span className="text-sm text-white">{ACTION_LABELS[action.type] || action.type}</span>
                    <span className="text-xs text-gray-400 ml-2">— {action.printerName}</span>
                  </div>
                  <span className="text-xs text-gray-400 font-mono">
                    {(action.confidence * 100).toFixed(0)}%
                  </span>
                  <span className="text-xs text-gray-400">
                    {new Date(action.timestamp).toLocaleString(undefined, {
                      month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit',
                    })}
                  </span>
                </button>

                {isExpanded && (
                  <div className="px-4 pb-3 pt-1 border-t border-gray-700 space-y-2 text-xs">
                    <div className="text-gray-400">
                      <span className="font-semibold text-white">Reason: </span>
                      {action.reason}
                    </div>
                    {action.details?.beforeValue !== undefined && (
                      <div className="flex gap-4">
                        <span className="text-gray-400">
                          Before: <span className="font-mono text-white">{action.details.beforeValue}</span>
                        </span>
                        <span className="text-gray-400">
                          After: <span className="font-mono text-white">{action.details.afterValue}</span>
                        </span>
                        {action.details.parameter && (
                          <span className="text-gray-400">
                            Parameter: <span className="font-mono text-white">{action.details.parameter}</span>
                          </span>
                        )}
                      </div>
                    )}
                    {action.details?.revertedAt && (
                      <div className="text-yellow-400">
                        Reverted at {new Date(action.details.revertedAt).toLocaleString()}
                      </div>
                    )}
                    <div className="flex items-center gap-2 pt-1">
                      <span className={`px-2 py-0.5 rounded text-[10px] font-semibold ${statusCfg.color}`}>
                        {statusCfg.label}
                      </span>
                      <span className="text-gray-500">ID: {action.id}</span>
                    </div>
                  </div>
                )}
              </div>
            )
          })}
        </div>
      )}
    </div>
  )
}

export default AIActionHistory
