import React, { useState } from 'react'
import { ArchDiagram, NodeDetailPanel, RouteExplorer, NODES, ROUTES, GROUP_COLORS } from '@features/arch-admin'

type View = 'diagram' | 'routes'

function StatBadge({ label, value, color }: { label: string; value: string | number; color: string }) {
  return (
    <div style={{
      background: `${color}08`, border: `1px solid ${color}25`,
      borderRadius: '6px', padding: '4px 10px',
      fontSize: '10.5px', color,
      fontFamily: "'Consolas','Fira Code',monospace",
      whiteSpace: 'nowrap',
    }}>
      <span style={{ opacity: 0.55 }}>{label} </span>
      <span style={{ fontWeight: 'bold' }}>{value}</span>
    </div>
  )
}

export default function ArchitecturePage() {
  const [view, setView]               = useState<View>('diagram')
  const [selectedNode, setSelectedNode] = useState<string | null>(null)

  const handleNodeClick = (id: string) =>
    setSelectedNode(prev => prev === id ? null : id)

  const critCounts = {
    critical: ROUTES.filter(r => r.criticality === 'CRITICAL').length,
    warned:   ROUTES.filter(r => r.warnings?.length).length,
    total:    ROUTES.length,
  }

  return (
    <div style={{
      width: '100%', height: '100%',
      background: '#050a12', color: '#c8d8e8',
      fontFamily: "'Consolas','Fira Code',monospace",
      display: 'flex', flexDirection: 'column',
      overflow: 'hidden',
    }}>

      {/* ── Header ─────────────────────────────────────────────────────── */}
      <div style={{
        padding: '10px 20px',
        borderBottom: '1px solid #0f1e30',
        display: 'flex', alignItems: 'center',
        justifyContent: 'space-between', gap: '12px',
        flexShrink: 0,
      }}>
        <div style={{ minWidth: 0 }}>
          <div style={{ fontSize: '13px', fontWeight: 900, letterSpacing: '0.3em', color: '#22d3ee', textShadow: '0 0 18px rgba(34,211,238,0.35)', whiteSpace: 'nowrap' }}>
            ◈ PRESTIGE · ARCH ADMIN
          </div>
          <div style={{ fontSize: '9px', color: '#1e3a5f', letterSpacing: '0.14em', marginTop: '2px' }}>
            SYSTEM DIAGRAM + FULL API ROUTES
          </div>
        </div>
        <div style={{ display: 'flex', gap: '6px', flexWrap: 'wrap', justifyContent: 'flex-end' }}>
          <StatBadge label="NODES"    value={NODES.length}                 color="#22d3ee" />
          <StatBadge label="CRITICAL" value={critCounts.critical}          color="#ef4444" />
          <StatBadge label="⚠ WARN"   value={critCounts.warned}            color="#f59e0b" />
          <StatBadge label="TOTAL"    value={`${critCounts.total} routes`} color="#10b981" />
        </div>
      </div>

      {/* ── Tabs ────────────────────────────────────────────────────────── */}
      <div style={{ display: 'flex', borderBottom: '1px solid #0f1e30', flexShrink: 0 }}>
        {([
          ['diagram', '◈  SYSTEM DIAGRAM', '#22d3ee'],
          ['routes',  '⚡ API ROUTES',     '#a855f7'],
        ] as const).map(([v, label, color]) => (
          <button key={v} onClick={() => { setView(v); setSelectedNode(null) }} style={{
            background:   view === v ? `${color}10` : 'transparent',
            border: 'none',
            borderBottom: view === v ? `2px solid ${color}` : '2px solid transparent',
            color:        view === v ? color : '#334155',
            padding: '9px 22px', cursor: 'pointer',
            fontFamily: 'inherit', fontSize: '10.5px',
            fontWeight: view === v ? 'bold' : 'normal',
            letterSpacing: '0.1em', transition: 'all 0.15s', whiteSpace: 'nowrap',
          }}>
            {label}
          </button>
        ))}
      </div>

      {/* ── Content ─────────────────────────────────────────────────────── */}
      <div style={{ flex: 1, overflow: 'hidden', display: 'flex', flexDirection: 'column' }}>

        {/* ─ Diagram view ─ */}
        {view === 'diagram' && (
          <div style={{ flex: 1, display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>

            {/* Legend + hint bar */}
            <div style={{
              padding: '6px 16px',
              borderBottom: '1px solid #0a1525',
              display: 'flex', alignItems: 'center',
              gap: '14px', flexShrink: 0, flexWrap: 'wrap',
            }}>
              {Object.entries(GROUP_COLORS).map(([group, c]) => (
                <div key={group} style={{ display: 'flex', alignItems: 'center', gap: '5px' }}>
                  <div style={{ width: 10, height: 10, border: `1.5px solid ${c.label}`, borderRadius: '2px', background: c.bg }} />
                  <span style={{ fontSize: '9.5px', color: c.label, letterSpacing: '0.1em' }}>{group.toUpperCase()}</span>
                </div>
              ))}
              <div style={{ display: 'flex', alignItems: 'center', gap: '5px' }}>
                <svg width="22" height="2"><line x1="0" y1="1" x2="22" y2="1" stroke="#475569" strokeWidth="1" strokeDasharray="4 2" /></svg>
                <span style={{ fontSize: '9.5px', color: '#334155' }}>dashed = secondary flow</span>
              </div>
              <span style={{ fontSize: '9px', color: '#1e3a5f', marginLeft: 'auto' }}>
                Drag to pan · Scroll to zoom · Click node → details panel
              </span>
            </div>

            {/* Diagram + side panel */}
            <div style={{ flex: 1, display: 'flex', gap: '0', overflow: 'hidden', minHeight: 0 }}>

              {/* Diagram fills all space */}
              <div style={{ flex: 1, minWidth: 0, overflow: 'hidden', position: 'relative' }}>
                <ArchDiagram
                  selectedId={selectedNode}
                  onNodeClick={handleNodeClick}
                />
              </div>

              {/* Side panel — 300px, slides in */}
              {selectedNode && (
                <div style={{
                  width: '300px', flexShrink: 0,
                  borderLeft: '1px solid #1a3550',
                  background: '#070f1c',
                  overflow: 'hidden',
                  display: 'flex', flexDirection: 'column',
                }}>
                  <NodeDetailPanel
                    nodeId={selectedNode}
                    onClose={() => setSelectedNode(null)}
                  />
                </div>
              )}
            </div>
          </div>
        )}

        {/* ─ Routes view ─ */}
        {view === 'routes' && (
          <div style={{ flex: 1, overflow: 'hidden' }}>
            <RouteExplorer />
          </div>
        )}

      </div>
    </div>
  )
}
