// ═══════════════════════════════════════════════════════════════
// PRESTIGE DASHBOARD - PRINTER CARD AI STATUS COMPONENT
// Shows AI monitoring status with visual indicator
// ═══════════════════════════════════════════════════════════════

import React from 'react'
import { Bot, Brain, Eye, Zap } from 'lucide-react'

interface PrinterCardAIProps {
  aiEnabled?: boolean
  aiLevel?: number
  aiStatus?: 'monitoring' | 'analyzing' | 'action-pending' | 'action-taken' | 'disabled'
  compact?: boolean
}

/**
 * Get AI status configuration
 */
const getAIConfig = (status: PrinterCardAIProps['aiStatus'], level: number) => {
  switch (status) {
    case 'action-pending':
      return {
        icon: Zap,
        label: 'Action Pending',
        color: 'text-yellow-400',
        bgColor: 'bg-yellow-500/10',
        borderColor: 'border-yellow-500/30',
        glowColor: 'var(--glow-warning-sm)',
        pulse: true,
      }
    case 'action-taken':
      return {
        icon: Zap,
        label: 'AI Active',
        color: 'text-purple-400',
        bgColor: 'bg-purple-500/10',
        borderColor: 'border-purple-500/30',
        glowColor: 'var(--glow-purple-sm)',
        pulse: false,
      }
    case 'analyzing':
      return {
        icon: Brain,
        label: 'Analyzing',
        color: 'text-cyan-400',
        bgColor: 'bg-cyan-500/10',
        borderColor: 'border-cyan-500/30',
        glowColor: 'var(--glow-cyan-sm)',
        pulse: true,
      }
    case 'monitoring':
      return {
        icon: Eye,
        label: `Level ${level}`,
        color: 'text-purple-400',
        bgColor: 'bg-purple-500/10',
        borderColor: 'border-purple-500/20',
        glowColor: undefined,
        pulse: false,
      }
    case 'disabled':
    default:
      return {
        icon: Bot,
        label: 'Disabled',
        color: 'text-gray-500',
        bgColor: 'bg-gray-500/10',
        borderColor: 'border-gray-500/20',
        glowColor: undefined,
        pulse: false,
      }
  }
}

/**
 * PrinterCardAI Component
 */
export const PrinterCardAI: React.FC<PrinterCardAIProps> = ({
  aiEnabled = false,
  aiLevel = 0,
  aiStatus = 'disabled',
  compact = false,
}) => {
  // If AI is disabled or level is 0, show minimal indicator
  if (!aiEnabled || aiLevel === 0) {
    if (compact) return null
    
    return (
      <div className="flex items-center gap-2 px-2 py-1 rounded border border-gray-700/50 bg-gray-800/30">
        <Bot className="w-3 h-3 text-gray-500" />
        <span className="text-xs text-gray-500">AI Off</span>
      </div>
    )
  }

  const config = getAIConfig(aiStatus, aiLevel)
  const Icon = config.icon

  // Compact mode - just icon with color
  if (compact) {
    return (
      <div 
        className={`relative flex items-center justify-center w-8 h-8 rounded-lg border ${config.borderColor} ${config.bgColor}`}
        style={{ boxShadow: config.glowColor }}
      >
        <Icon className={`w-4 h-4 ${config.color}`} />
        {config.pulse && (
          <span className="absolute inset-0 rounded-lg border border-current animate-ping opacity-20" style={{ color: config.color }} />
        )}
      </div>
    )
  }

  // Full mode - icon + label
  return (
    <div 
      className={`relative flex items-center gap-2 px-3 py-1.5 rounded-lg border ${config.borderColor} ${config.bgColor} transition-all`}
      style={{ boxShadow: config.glowColor }}
    >
      <Icon className={`w-4 h-4 ${config.color}`} />
      <div className="flex flex-col">
        <span className={`text-xs font-medium ${config.color}`}>
          AI {config.label}
        </span>
        {aiStatus === 'monitoring' && (
          <span className="text-[10px] text-gray-500">
            Monitoring
          </span>
        )}
      </div>
      {config.pulse && (
        <span 
          className="absolute inset-0 rounded-lg border-2 animate-ping opacity-20" 
          style={{ borderColor: config.color.replace('text-', '') }}
        />
      )}
    </div>
  )
}

PrinterCardAI.displayName = 'PrinterCardAI'

export default PrinterCardAI
