// ═══════════════════════════════════════════════════════════════
// PRESTIGE — AI EXPLAIN TAB
// AI decision history with full reasoning and suggested actions
// ═══════════════════════════════════════════════════════════════

import React, { useState, useEffect, useRef } from 'react'
import { HelpCircle, RefreshCw, Zap, Wrench, ChevronDown, ChevronUp } from 'lucide-react'
import type { Recommendation } from './ai-types'
import { apiFetch, PRIORITY_STYLE } from './ai-types'

export interface AIExplainTabProps {
  printerId?: string
  printers: any[]
}

export function AIExplainTab({ printerId, printers }: AIExplainTabProps) {
  const [history, setHistory] = useState<Recommendation[]>([])
  const [loading, setLoading] = useState(true)
  const [expandedId, setExpandedId] = useState<string | null>(null)

  // Use a ref so that printers array reference changes (from Object.values)
  // don't cause this effect to re-fire on every WebSocket temperature update.
  const printersRef = useRef(printers)
  useEffect(() => { printersRef.current = printers }, [printers])

  useEffect(() => {
    setLoading(true)
    const load = async () => {
      if (printerId) {
        const d = await apiFetch<{ recommendations: Recommendation[] }>(`/api/ai/printers/${printerId}/recommendations/history?limit=25`)
        setHistory(d?.recommendations ?? [])
      } else {
        const all: Recommendation[] = []
        await Promise.all(printersRef.current.map(async (p: any) => {
          const d = await apiFetch<{ recommendations: Recommendation[] }>(`/api/ai/printers/${p.id}/recommendations/history?limit=10`)
          if (d?.recommendations) all.push(...d.recommendations)
        }))
        all.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime())
        setHistory(all.slice(0, 30))
      }
      setLoading(false)
    }
    load()
  // ✅ printers intentionally omitted — accessed via printersRef
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [printerId])

  if (loading) return (
    <div className="py-12 text-center">
      <RefreshCw className="w-7 h-7 mx-auto mb-2 text-cyan-400 animate-spin opacity-50" />
      <p className="text-gray-400 text-sm">Loading AI decision history...</p>
    </div>
  )

  if (!history.length) return (
    <div className="py-12 text-center">
      <HelpCircle className="w-10 h-10 mx-auto mb-3 text-gray-600" />
      <p className="text-base font-medium text-gray-200 mb-1">No AI Decisions Yet</p>
      <p className="text-sm text-gray-400 max-w-sm mx-auto">
        When AI makes recommendations, the detailed reasoning — confidence levels, triggering factors,
        and suggested actions — will appear here.
      </p>
    </div>
  )

  return (
    <div className="space-y-2">
      <div className="flex items-center gap-2 mb-3">
        <HelpCircle className="w-4 h-4 text-cyan-400" />
        <h2 className="text-base font-semibold text-gray-200">AI Decision History</h2>
        <span className="text-xs text-gray-500">({history.length})</span>
      </div>

      {history.map(rec => {
        const isExp = expandedId === rec.id
        return (
          <div key={rec.id} className="rounded-xl border border-gray-700 bg-gray-900/40 overflow-hidden">
            <button onClick={() => setExpandedId(isExp ? null : rec.id)}
              className="w-full flex items-center gap-3 px-4 py-3 hover:bg-gray-800/40 transition-colors text-left">
              <Zap className="w-4 h-4 text-yellow-400 flex-shrink-0" />
              <div className="flex-1 min-w-0">
                <div className="text-sm text-gray-200 truncate">{rec.title}</div>
                <div className="text-xs text-gray-400 truncate">{rec.description}</div>
              </div>
              <span className={`text-xs font-bold flex-shrink-0 ${PRIORITY_STYLE[rec.priority]?.split(' ')[0] ?? 'text-gray-400'}`}>
                {rec.priority.toUpperCase()}
              </span>
              <div className="flex-shrink-0 flex items-center gap-1">
                <div className="w-8 h-1.5 rounded-full bg-gray-800 overflow-hidden">
                  <div className={`h-full rounded-full ${rec.confidence >= 0.8 ? 'bg-green-400' : rec.confidence >= 0.6 ? 'bg-yellow-400' : 'bg-red-400'}`} style={{ width: `${rec.confidence * 100}%` }} />
                </div>
                <span className="text-xs font-mono text-gray-400">{(rec.confidence * 100).toFixed(0)}%</span>
              </div>
              <span className="text-[10px] text-gray-500 flex-shrink-0 hidden sm:block">
                {new Date(rec.createdAt).toLocaleString(undefined, { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' })}
              </span>
              {isExp ? <ChevronUp className="w-3.5 h-3.5 text-gray-500" /> : <ChevronDown className="w-3.5 h-3.5 text-gray-500" />}
            </button>

            {isExp && (
              <div className="px-4 pb-4 border-t border-gray-700 pt-3 space-y-3">
                <div className="p-2.5 rounded bg-gray-950 border border-gray-700">
                  <div className="text-[10px] text-gray-500 mb-0.5">Reasoning</div>
                  <p className="text-xs text-gray-300">{rec.reasoning}</p>
                </div>

                <div className="flex items-center gap-2">
                  <span className="text-[10px] text-gray-500 w-14">Confidence</span>
                  <div className="flex-1 h-1.5 rounded-full bg-gray-800 overflow-hidden">
                    <div className={`h-full rounded-full ${rec.confidence >= 0.8 ? 'bg-green-400' : rec.confidence >= 0.6 ? 'bg-yellow-400' : 'bg-red-400'}`} style={{ width: `${rec.confidence * 100}%` }} />
                  </div>
                  <span className="text-xs font-mono font-bold text-gray-200">{(rec.confidence * 100).toFixed(0)}%</span>
                </div>

                {rec.suggestedActions.length > 0 && (
                  <div className="space-y-1">
                    <div className="text-[10px] font-semibold text-gray-500 uppercase">Suggested Actions</div>
                    {rec.suggestedActions.map((a, i) => (
                      <div key={i} className="flex items-start gap-2 text-xs">
                        {a.automated
                          ? <Zap className="w-3 h-3 text-cyan-400 flex-shrink-0 mt-0.5" />
                          : <Wrench className="w-3 h-3 text-gray-400 flex-shrink-0 mt-0.5" />}
                        <span className="text-gray-300 flex-1">{a.description}</span>
                        {a.gcode && (
                          <code className="text-[10px] text-cyan-400 bg-cyan-500/10 px-1.5 rounded font-mono flex-shrink-0">
                            {a.gcode.split('\n')[0]}
                          </code>
                        )}
                      </div>
                    ))}
                  </div>
                )}

                <div className="flex items-center gap-3 text-[10px] text-gray-500 border-t border-gray-700 pt-2">
                  <span>Type: <span className="text-gray-300 capitalize">{rec.type.replace(/_/g, ' ')}</span></span>
                  <span>Source: <span className="text-gray-300 capitalize">{rec.source}</span></span>
                  {rec.acknowledged && <span className="text-green-400">✓ Acknowledged</span>}
                  {rec.dismissed && <span className="text-gray-500">✗ Dismissed{rec.dismissReason ? ': ' + rec.dismissReason : ''}</span>}
                </div>
              </div>
            )}
          </div>
        )
      })}
    </div>
  )
}

export default AIExplainTab
