// ═══════════════════════════════════════════════════════════════
// PRESTIGE — AI CONTROL PAGE
// Fully wired to /api/ai/* backend endpoints
// All tab logic lives in @features/ai-panel — this file is the
// layout shell + data fetching only.
// ═══════════════════════════════════════════════════════════════

import React, { useState, useEffect, useCallback, useRef } from 'react'
import { useLocation, useNavigate } from 'react-router-dom'
import {
  Activity, AlertTriangle, History, Sliders, HelpCircle,
  TrendingUp, FlaskConical, XCircle,
} from 'lucide-react'

import {
  AIActionHistory,
  AIActionPanel,
  AIStatusCard,
  AIStatusIndicator,
  AIRecommendationsTab,
  AIPredictionsTab,
  AISettingsTab,
  AIDiagnosticsTab,
  AIExplainTab,
  AISidebarAnalysisCard,
  Tab,
  PrinterItem,
} from '@features/ai-panel'
import type { AIAutonomyLevel } from '@core/types'
import type {
  BackendAIStatus,
  Recommendation,
  BackendAnomaly,
  FailurePredictionResult,
  AnalysisResult,
} from '@features/ai-panel'

import { usePrinterStore, selectPrintersArray } from '@core/state/printerStore'
import { useAIStore, selectAIEnabled, selectAutonomyLevel } from '@core/state/aiStore'
import { apiFetch } from '@features/ai-panel'
import { api } from '@services/api'

// ── Helpers ───────────────────────────────────────────────────

function autonomyToNumber(level: AIAutonomyLevel): number {
  const map: Record<AIAutonomyLevel, number> = { L0: 0, L1: 1, L2: 2 }
  return map[level] ?? 1
}

type AITab = 'panel' | 'predictions' | 'history' | 'settings' | 'explain' | 'diagnostics'

// ═══════════════════════════════════════════════════════════════
// PAGE
// ═══════════════════════════════════════════════════════════════

export default function AIControlPage() {
  const location = useLocation()
  const navigate = useNavigate()
  const sp = new URLSearchParams(location.search)
  const urlPrinter = sp.get('printer')
  const urlTab = sp.get('tab') as AITab | null
  const urlAutoRun = sp.get('autorun')

  const tabMap: Record<string, AITab> = {
    panel: 'panel', predictions: 'predictions',
    history: 'history', settings: 'settings', explain: 'explain', diagnostics: 'diagnostics',
  }

  const [activeTab, setActiveTab] = useState<AITab>(urlTab && tabMap[urlTab] ? tabMap[urlTab] : 'panel')
  const [selectedPrinter, setSelectedPrinter] = useState<string>(urlPrinter ?? 'all')

  // Update URL when printer or tab changes
  const updateUrl = useCallback((printer: string, tab: AITab) => {
    const params = new URLSearchParams()
    if (printer !== 'all') params.set('printer', printer)
    if (tab !== 'panel') params.set('tab', tab)
    const search = params.toString()
    navigate({ pathname: '/ai', search: search ? `?${search}` : '' }, { replace: true })
  }, [navigate])

  const handleSelectPrinter = useCallback((id: string) => {
    setSelectedPrinter(id)
    updateUrl(id, activeTab)
  }, [activeTab, updateUrl])

  const handleSetTab = useCallback((tab: AITab) => {
    setActiveTab(tab)
    updateUrl(selectedPrinter, tab)
  }, [selectedPrinter, updateUrl])

  // ── Store ─────────────────────────────────────────────────
  // ⚠️ Use a ref so printers never becomes a useCallback dependency.
  // selectPrintersArray returns a new array ref on every WebSocket update,
  // which would recreate fetchData on every temperature tick.
  const printers = usePrinterStore(selectPrintersArray)
  const printersRef = useRef(printers)
  useEffect(() => { printersRef.current = printers }, [printers])

  const isEnabled = useAIStore(selectAIEnabled)
  const autonomyLevel = useAIStore(selectAutonomyLevel)
  const getPrinterLevel = useAIStore(s => s.getPrinterLevel)

  const effectiveLevel = selectedPrinter !== 'all'
    ? getPrinterLevel(selectedPrinter)
    : autonomyToNumber(autonomyLevel)

  // ── Backend state ─────────────────────────────────────────
  const [backendStatus, setBackendStatus] = useState<BackendAIStatus | null>(null)
  const [recommendations, setRecommendations] = useState<Recommendation[]>([])
  const [anomalies, setAnomalies] = useState<BackendAnomaly[]>([])
  const [failurePred, setFailurePred] = useState<FailurePredictionResult | null>(null)
  const [lastAnalysis, setLastAnalysis] = useState<AnalysisResult | null>(null)
  const [analyzing, setAnalyzing] = useState(false)
  const [analyzeResult, setAnalyzeResult] = useState<{ found: number; anomalies: number } | null>(null)
  const [loadingPrimary, setLoadingPrimary] = useState(false)
  const [nextAnalyzeIn, setNextAnalyzeIn] = useState<number>(60)

  const pollRef = useRef<NodeJS.Timeout | null>(null)
  const autoAnalyzeRef = useRef<NodeJS.Timeout | null>(null)
  const countdownRef = useRef<NodeJS.Timeout | null>(null)
  const analyzingRef = useRef(false)
  const prevPrinterStatusesRef = useRef<Record<string, string>>({})
  const activePrinterRef = useRef(selectedPrinter)

  // ── Persist lastAnalysis across printer switches ───────────
  useEffect(() => {
    if (selectedPrinter === 'all') { setLastAnalysis(null); return }
    try {
      const saved = localStorage.getItem(`prestige_analysis_${selectedPrinter}`)
      setLastAnalysis(saved ? JSON.parse(saved) : null)
    } catch { setLastAnalysis(null) }
  }, [selectedPrinter])

  // ── 2-phase progressive fetch ─────────────────────────────
  const fetchData = useCallback(async (initial = false) => {
    const current = selectedPrinter
    activePrinterRef.current = current
    if (initial) setLoadingPrimary(true)

    // Status: fire-and-forget
    apiFetch<BackendAIStatus>('/api/ai/status').then(st => {
      if (activePrinterRef.current !== current) return
      if (st) setBackendStatus(st)
    })

    const currentPrinters = printersRef.current

    if (current === 'all') {
      const allRecs: Recommendation[] = []
      const allAnoms: BackendAnomaly[] = []
      await Promise.all(currentPrinters.map(async (p: any) => {
        const [r, a] = await Promise.all([
          apiFetch<{ recommendations: Recommendation[] }>(`/api/ai/printers/${p.id}/recommendations`),
          apiFetch<BackendAnomaly[]>(`/api/ai/printers/${p.id}/anomalies`),
        ])
        if (r) allRecs.push(...(Array.isArray(r) ? r : r.recommendations ?? []))
        if (a) allAnoms.push(...(Array.isArray(a) ? a : []))
      }))
      if (activePrinterRef.current !== current) return
      setRecommendations(allRecs)
      setAnomalies(allAnoms)
      setFailurePred(null)
      setLoadingPrimary(false)
      return
    }

    // Phase 1: fast critical data
    const [recs, anoms] = await Promise.all([
      apiFetch<{ recommendations: Recommendation[] }>(`/api/ai/printers/${current}/recommendations`),
      apiFetch<BackendAnomaly[]>(`/api/ai/printers/${current}/anomalies`),
    ])
    if (activePrinterRef.current !== current) return
    if (recs) setRecommendations(Array.isArray(recs) ? recs : recs.recommendations ?? [])
    if (anoms) setAnomalies(Array.isArray(anoms) ? anoms : [])
    setLoadingPrimary(false)

    // Phase 2: secondary data in background
    const [fp] = await Promise.all([
      apiFetch<FailurePredictionResult>(`/api/ai/printers/${current}/predictions/failure`),
    ])
    if (activePrinterRef.current !== current) return
    if (fp) setFailurePred(fp)
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedPrinter])

  // ── Auto-analyze countdown ────────────────────────────────
  const startCountdown = useCallback(() => {
    if (countdownRef.current) clearInterval(countdownRef.current)
    setNextAnalyzeIn(60)
    countdownRef.current = setInterval(() => {
      setNextAnalyzeIn(prev => {
        if (prev <= 1) { clearInterval(countdownRef.current!); return 0 }
        return prev - 1
      })
    }, 1000)
  }, [])

  useEffect(() => {
    setFailurePred(null)
    fetchData(true)
    if (pollRef.current) clearInterval(pollRef.current)
    pollRef.current = setInterval(() => fetchData(false), 20_000)
    if (autoAnalyzeRef.current) clearInterval(autoAnalyzeRef.current)
    if (countdownRef.current) clearInterval(countdownRef.current)
    if (selectedPrinter !== 'all') {
      autoAnalyzeRef.current = setInterval(() => {
        analyzeNowRef.current()
        startCountdown()
      }, 60_000)
      startCountdown()
    }
    return () => {
      if (pollRef.current) clearInterval(pollRef.current)
      if (autoAnalyzeRef.current) clearInterval(autoAnalyzeRef.current)
      if (countdownRef.current) clearInterval(countdownRef.current)
    }
  }, [fetchData, startCountdown])

  // ── Auto-start on printer connect ─────────────────────────
  useEffect(() => {
    const prev = prevPrinterStatusesRef.current
    const connected = ['online', 'connected', 'printing', 'idle', 'ready', 'operational']
    let shouldAnalyze = false

    printers.forEach((p: any) => {
      const wasConn = connected.some(s => (prev[p.id] ?? '').toLowerCase().includes(s))
      const isConn  = connected.some(s => (p.status ?? '').toLowerCase().includes(s))
      if (isConn && !wasConn) {
        fetchData(false)
        // Only auto-analyze on connect if this printer has prior analysis history.
        // Brand-new printers have no telemetry yet — auto-analyze would produce
        // misleading health/industry scores from near-zero data.
        const hasPriorAnalysis = !!localStorage.getItem(`prestige_analysis_${p.id}`)
        if (hasPriorAnalysis && (selectedPrinter === p.id || selectedPrinter === 'all')) shouldAnalyze = true
      }
    })

    prevPrinterStatusesRef.current = Object.fromEntries(
      printers.map((p: any) => [p.id, (p.status ?? '').toLowerCase()])
    )

    if (shouldAnalyze && !analyzingRef.current) {
      setTimeout(() => analyzeNowRef.current(), 2000)
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [printers])

  // ── Analyze now ───────────────────────────────────────────
  const analyzeNow = useCallback(async () => {
    if (selectedPrinter === 'all' || analyzingRef.current) return
    analyzingRef.current = true
    setAnalyzing(true)
    setAnalyzeResult(null)
    if (countdownRef.current) clearInterval(countdownRef.current)
    setNextAnalyzeIn(60)

    const recsBefore = recommendations.filter(r => !r.acknowledged && !r.dismissed).length
    try {
      const result = await api.post<any>(`/api/ai/printers/${selectedPrinter}/analyze`)
      if (result != null) {
        setLastAnalysis(result)
        startCountdown()
        try { localStorage.setItem(`prestige_analysis_${selectedPrinter}`, JSON.stringify(result)) } catch {}
        await fetchData(false)
        setAnalyzeResult({ found: result?.recommendationCount ?? 0, anomalies: result?.anomalyCount ?? 0 })
        if ((result?.recommendationCount ?? 0) > recsBefore) handleSetTab('panel')
        setTimeout(() => setAnalyzeResult(null), 8000)
      }
    } finally {
      setAnalyzing(false)
      analyzingRef.current = false
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedPrinter, fetchData, recommendations, startCountdown])

  const analyzeNowRef = useRef(analyzeNow)
  useEffect(() => { analyzeNowRef.current = analyzeNow }, [analyzeNow])

  // ── Derived counts ────────────────────────────────────────
  const pendingRecs = recommendations.filter(r => !r.acknowledged && !r.dismissed).length
  const selectedPrinterName = selectedPrinter === 'all'
    ? 'All Printers'
    : printers.find((p: any) => p.id === selectedPrinter)?.name ?? selectedPrinter

  const levelNames  = ['L0 — Passive', 'L1 — Recommend', 'L2 — Automatic']
  const levelColors = [
    'bg-gray-500/15 text-gray-300 border-gray-500/30',
    'bg-cyan-500/15 text-cyan-400 border-cyan-500/30',
    'bg-yellow-500/15 text-yellow-400 border-yellow-500/30',
  ]

  const showAbort = selectedPrinter !== 'all' && failurePred?.shouldAbort
  const showPause = selectedPrinter !== 'all' && !showAbort && failurePred?.shouldPause

  // ═════════════════════════════════════════════════════════
  // RENDER
  // ═════════════════════════════════════════════════════════

  return (
    <div className="flex h-full gap-4 overflow-hidden">

      {/* ─── SIDEBAR ──────────────────────────────────────── */}
      <div className="flex-shrink-0 w-60 flex flex-col gap-2 overflow-y-auto">

        {/* AI Status + level badge */}
        <div className="space-y-2">
          <AIStatusIndicator showLabel />

          {backendStatus && (
            <AIStatusCard compact status={backendStatus} />
          )}

          <div className="px-3 py-2 rounded-xl bg-gray-900/40 border border-gray-800/50 space-y-1.5">
            <div>
              <div className="text-[10px] text-gray-500 uppercase tracking-wider">PRINTER</div>
              <div className="text-sm font-bold text-white truncate">{selectedPrinterName}</div>
            </div>
            {backendStatus?.healthy && (
              <div className={`inline-flex items-center gap-1.5 px-2 py-1 rounded border text-xs font-semibold ${levelColors[effectiveLevel] ?? levelColors[1]}`}>
                <span className="w-1.5 h-1.5 rounded-full bg-current opacity-80" />
                {levelNames[effectiveLevel]}
              </div>
            )}
          </div>
        </div>

        {/* Last Analysis compact card */}
        {selectedPrinter !== 'all' && (
          <AISidebarAnalysisCard
            lastAnalysis={lastAnalysis}
            analyzing={analyzing}
            analyzeResult={analyzeResult}
            onAnalyze={analyzeNow}
            nextAnalyzeIn={nextAnalyzeIn}
          />
        )}

        {/* Printer list */}
        <div className="flex-1 flex flex-col min-h-0">
          <div className="text-[10px] font-semibold text-gray-500 uppercase tracking-wider mb-1.5">Printers</div>
          <div className="flex-1 overflow-y-auto space-y-1 pr-0.5">
            <PrinterItem label="All Printers" subtitle="View all" selected={selectedPrinter === 'all'} onClick={() => handleSelectPrinter('all')} />
            {printers.map((p: any) => (
              <PrinterItem key={p.id} label={p.name || p.id} subtitle={p.status || 'Idle'} selected={selectedPrinter === p.id} onClick={() => handleSelectPrinter(p.id)} />
            ))}
          </div>
        </div>
      </div>

      {/* ─── MAIN ─────────────────────────────────────────── */}
      <div className="flex-1 flex flex-col gap-3 overflow-y-auto min-w-0">

        {/* Alert banners */}
        {showAbort && (
          <div className="flex items-center gap-3 px-4 py-2.5 rounded-xl border border-red-500/40 bg-red-500/10 animate-pulse">
            <XCircle className="w-5 h-5 text-red-400 flex-shrink-0" />
            <div className="flex-1">
              <span className="text-red-400 font-bold text-sm">ABORT RECOMMENDED </span>
              <span className="text-red-300 text-xs">{failurePred?.warnings[0] ?? 'Critical failure risk detected'}</span>
            </div>
          </div>
        )}
        {showPause && (
          <div className="flex items-center gap-3 px-4 py-2.5 rounded-xl border border-orange-500/40 bg-orange-500/10">
            <AlertTriangle className="w-5 h-5 text-orange-400 flex-shrink-0" />
            <div className="flex-1">
              <span className="text-orange-400 font-bold text-sm">PAUSE RECOMMENDED </span>
              <span className="text-orange-300 text-xs">{failurePred?.warnings[0] ?? 'High failure risk — inspect printer'}</span>
            </div>
          </div>
        )}

        {/* Tabs */}
        <div className="flex items-center gap-2 flex-wrap">
          <Tab active={activeTab === 'panel'} onClick={() => handleSetTab('panel')} icon={<Activity className="w-3.5 h-3.5" />} label="Recommendations" badge={pendingRecs > 0 ? pendingRecs : undefined} />
          {selectedPrinter !== 'all' && (
            <>
              <Tab active={activeTab === 'predictions'} onClick={() => handleSetTab('predictions')} icon={<TrendingUp className="w-3.5 h-3.5" />} label="Predictions" badge={failurePred?.overallRisk === 'critical' || failurePred?.overallRisk === 'high' ? '!' : undefined} />
              <Tab active={activeTab === 'diagnostics'} onClick={() => handleSetTab('diagnostics')} icon={<FlaskConical className="w-3.5 h-3.5" />} label="Diagnostics" />
            </>
          )}
          <Tab active={activeTab === 'history'} onClick={() => handleSetTab('history')} icon={<History className="w-3.5 h-3.5" />} label="History" />
          <Tab active={activeTab === 'settings'} onClick={() => handleSetTab('settings')} icon={<Sliders className="w-3.5 h-3.5" />} label="Settings" />
          <Tab active={activeTab === 'explain'} onClick={() => handleSetTab('explain')} icon={<HelpCircle className="w-3.5 h-3.5" />} label="Explain" />
        </div>

        {/* Content */}
        <div className="flex-1">
          {loadingPrimary && (
            <div className="space-y-3 animate-pulse">
              {[1, 2, 3].map(i => (
                <div key={i} className="rounded-xl border border-gray-800 bg-gray-900/30 p-4">
                  <div className="flex items-center gap-3 mb-3">
                    <div className="w-3 h-3 rounded-full bg-gray-700" />
                    <div className="h-3 w-32 rounded bg-gray-700" />
                    <div className="h-3 w-12 rounded bg-gray-800 ml-auto" />
                  </div>
                  <div className="space-y-2">
                    <div className="h-2.5 w-full rounded bg-gray-800" />
                    <div className="h-2.5 w-4/5 rounded bg-gray-800" />
                  </div>
                </div>
              ))}
            </div>
          )}

          {!loadingPrimary && activeTab === 'panel' && selectedPrinter === 'all' && (
            <AIActionPanel />
          )}

          {!loadingPrimary && activeTab === 'panel' && selectedPrinter !== 'all' && (
            <AIRecommendationsTab
              recommendations={recommendations}
              anomalies={anomalies}
              onRefresh={fetchData}
              onAcknowledge={async (pid, id) => {
                await api.post(`/api/ai/printers/${pid}/recommendations/${id}/acknowledge`)
                fetchData(false)
              }}
              onDismiss={async (pid, id) => {
                await api.post(`/api/ai/printers/${pid}/recommendations/${id}/dismiss`)
                fetchData(false)
              }}
            />
          )}

          {!loadingPrimary && activeTab === 'predictions' && selectedPrinter !== 'all' && (
            <AIPredictionsTab
              failurePred={failurePred}
              printerId={selectedPrinter}
              onRefresh={() => fetchData(false)}
            />
          )}

          {!loadingPrimary && activeTab === 'history' && (
            <AIActionHistory printerId={selectedPrinter !== 'all' ? selectedPrinter : undefined} />
          )}

          {!loadingPrimary && activeTab === 'settings' && (
            <AISettingsTab
              selectedPrinter={selectedPrinter}
              currentLevel={effectiveLevel}
              isEnabled={isEnabled}
              printers={printers}
            />
          )}

          {!loadingPrimary && activeTab === 'diagnostics' && selectedPrinter !== 'all' && (
            <AIDiagnosticsTab
              printerId={selectedPrinter}
              lastAnalysis={lastAnalysis}
              autoRunTestId={urlAutoRun ?? undefined}
              onRefresh={async () => {
                try {
                  const saved = localStorage.getItem(`prestige_analysis_${selectedPrinter}`)
                  if (saved) setLastAnalysis(JSON.parse(saved))
                } catch {}
                await fetchData(false)
              }}
            />
          )}

          {!loadingPrimary && activeTab === 'explain' && (
            <AIExplainTab
              printerId={selectedPrinter !== 'all' ? selectedPrinter : undefined}
              printers={printers}
            />
          )}
        </div>
      </div>
    </div>
  )
}
