// PRESTIGE DASHBOARD - STATUS BADGE COMPONENT
// Badge-style status indicator with dot and label
// ═══════════════════════════════════════════════════════════════

import React from 'react'
import { StatusDot } from './StatusDot'
import type { StatusConfig } from './StatusIndicator.types'

interface StatusBadgeProps {
  config: StatusConfig
  size: 'sm' | 'md' | 'lg' | 'xl'
  showLabel?: boolean
  label?: string
  pulse?: boolean
  animated?: boolean
  onClick?: () => void
}

const SIZE_CONFIG = {
  sm: {
    container: 'gap-1.5 px-2 py-1',
    text: 'text-xs',
  },
  md: {
    container: 'gap-2 px-2.5 py-1.5',
    text: 'text-sm',
  },
  lg: {
    container: 'gap-2.5 px-3 py-2',
    text: 'text-base',
  },
  xl: {
    container: 'gap-3 px-4 py-2.5',
    text: 'text-lg',
  },
}

/**
 * StatusBadge Component
 * Badge with dot, label, and hover effects
 */
export const StatusBadge: React.FC<StatusBadgeProps> = ({
  config,
  size,
  showLabel = true,
  label,
  pulse = false,
  animated = true,
  onClick,
}) => {
  const sizeConfig = SIZE_CONFIG[size] || SIZE_CONFIG.md
  const isClickable = !!onClick

  return (
    <div
      className={`
        inline-flex items-center rounded-full border transition-all duration-200
        ${sizeConfig.container}
        ${isClickable ? 'cursor-pointer hover:scale-105 active:scale-95' : ''}
        ${animated ? 'hover:shadow-lg' : ''}
      `}
      title={config.description}
      onClick={onClick}
      style={{
        backgroundColor: config.bgColor,
        borderColor: config.borderColor,
        boxShadow: pulse ? `0 0 12px ${config.color}20` : undefined,
      }}
    >
      <StatusDot
        config={config}
        size={size}
        pulse={pulse}
        animated={animated}
      />
      
      {showLabel && (
        <span
          className={`font-medium ${sizeConfig.text} transition-colors duration-200`}
          style={{ color: config.textColor }}
        >
          {label || config.label}
        </span>
      )}
    </div>
  )
}

StatusBadge.displayName = 'StatusBadge'

export default StatusBadge
