// ═══════════════════════════════════════════════════════════════
// PRESTIGE DASHBOARD - i18n CONFIGURATION
// ═══════════════════════════════════════════════════════════════

import i18n from 'i18next'
import { initReactI18next } from 'react-i18next'
import LanguageDetector from 'i18next-browser-languagedetector'

// Import translations
import lv from './locales/lv.json'
import en from './locales/en.json'

// ═══════════════════════════════════════════════════════════════
// CONFIGURATION
// ═══════════════════════════════════════════════════════════════

const resources = {
  lv: {
    translation: lv,
  },
  en: {
    translation: en,
  },
}

i18n
  // Detect user language
  .use(LanguageDetector)
  // Pass the i18n instance to react-i18next
  .use(initReactI18next)
  // Initialize i18next
  .init({
    resources,
    
    // Default language
    fallbackLng: 'lv',
    
    // Supported languages
    supportedLngs: ['lv', 'en'],
    
    // Language detection options
    detection: {
      // Order of language detection
      order: ['localStorage', 'navigator'],
      
      // Cache user language
      caches: ['localStorage'],
      
      // localStorage key
      lookupLocalStorage: 'prestige_language',
    },
    
    // Interpolation options
    interpolation: {
      // React already escapes values
      escapeValue: false,
    },
    
    // React options
    react: {
      // Wait for translations to be loaded before rendering
      useSuspense: false,
    },
    
    // Debug mode (disable in production)
    debug: import.meta.env.DEV,
    
    // Namespace
    ns: ['translation'],
    defaultNS: 'translation',
    
    // Key separator (use dots)
    keySeparator: '.',
    
    // Nesting separator
    nsSeparator: ':',
    
    // Return empty string for missing keys in production
    returnEmptyString: !import.meta.env.DEV,
    
    // Return key if translation is missing in development
    returnNull: false,
  })

export default i18n

// ═══════════════════════════════════════════════════════════════
// HELPER FUNCTIONS
// ═══════════════════════════════════════════════════════════════

/**
 * Get current language
 */
export function getCurrentLanguage(): string {
  return i18n.language || 'lv'
}

/**
 * Change language
 */
export async function changeLanguage(lng: string): Promise<void> {
  await i18n.changeLanguage(lng)
}

/**
 * Get available languages
 */
export function getAvailableLanguages(): string[] {
  return ['lv', 'en']
}

/**
 * Check if language is supported
 */
export function isLanguageSupported(lng: string): boolean {
  return getAvailableLanguages().includes(lng)
}
