// PRESTIGE DASHBOARD - AI PREDICTION CARD COMPONENT
// ═══════════════════════════════════════════════════════════════

import React from 'react'
import type { AIPrediction } from '../../core/types/ai'

export interface AIPredictionCardProps {
  prediction: AIPrediction
  onViewDetails?: (id: string) => void
  compact?: boolean
  className?: string
}

/**
 * Get prediction type config
 */
const getPredictionConfig = (type: AIPrediction['type']) => {
  const configs = {
    maintenance: {
      icon: '🔧',
      label: 'Maintenance',
      color: '#f80',
      glow: 'rgba(255, 136, 0, 0.3)',
    },
    failure: {
      icon: '⚠',
      label: 'Failure Risk',
      color: '#f00',
      glow: 'rgba(255, 0, 0, 0.3)',
    },
    quality: {
      icon: '⭐',
      label: 'Quality Issue',
      color: '#ff0',
      glow: 'rgba(255, 255, 0, 0.3)',
    },
    wear: {
      icon: '📉',
      label: 'Component Wear',
      color: '#f80',
      glow: 'rgba(255, 136, 0, 0.3)',
    },
    performance: {
      icon: '📊',
      label: 'Performance',
      color: '#0ff',
      glow: 'rgba(0, 255, 255, 0.3)',
    },
  }
  return configs[type] || configs.maintenance
}

/**
 * Format timeframe
 */
const formatTimeframe = (timeframe: string): string => {
  // Parse timeframe like "3-5 days", "1 week", "2 months"
  return timeframe
}

/**
 * Get probability color
 */
const getProbabilityColor = (probability: number) => {
  if (probability >= 0.8) return '#f00' // High risk
  if (probability >= 0.5) return '#ff0' // Medium risk
  return '#0f0' // Low risk
}

/**
 * AIPredictionCard Component
 * Displays AI predictions for maintenance/failures
 */
export const AIPredictionCard: React.FC<AIPredictionCardProps> = ({
  prediction,
  onViewDetails,
  compact = false,
  className = '',
}) => {
  const config = getPredictionConfig(prediction.type)
  const probabilityColor = getProbabilityColor(prediction.probability)

  if (compact) {
    return (
      <div
        className={`flex items-start gap-3 p-3 rounded-lg border bg-gray-900/50 hover:bg-gray-900/70 transition-colors ${className}`}
        style={{
          borderColor: `${config.color}30`,
          backgroundColor: `${config.color}05`,
        }}
      >
        {/* Icon */}
        <div
          className="flex-shrink-0 w-8 h-8 rounded-lg flex items-center justify-center text-lg"
          style={{
            backgroundColor: `${config.color}20`,
            border: `1px solid ${config.color}50`,
          }}
        >
          {config.icon}
        </div>

        {/* Content */}
        <div className="flex-1 min-w-0">
          <div className="flex items-start justify-between gap-2 mb-1">
            <p className="text-sm font-medium text-white line-clamp-2">
              {prediction.description}
            </p>
          </div>

          <div className="flex items-center gap-3 text-xs">
            <span className="text-gray-400">
              {formatTimeframe(prediction.timeframe)}
            </span>
            <span className="font-mono font-bold" style={{ color: probabilityColor }}>
              {(prediction.probability * 100).toFixed(0)}%
            </span>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div
      className={`flex flex-col gap-4 p-4 rounded-lg border bg-gray-900/50 hover:bg-gray-900/70 transition-colors ${className}`}
      style={{
        borderColor: `${config.color}30`,
        backgroundColor: `${config.color}05`,
      }}
    >
      {/* Header */}
      <div className="flex items-start gap-3">
        {/* Icon */}
        <div
          className="flex-shrink-0 w-10 h-10 rounded-lg flex items-center justify-center text-xl"
          style={{
            backgroundColor: `${config.color}20`,
            border: `1px solid ${config.color}50`,
          }}
        >
          {config.icon}
        </div>

        {/* Title */}
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 mb-1">
            <span className="text-xs font-bold px-2 py-0.5 rounded" style={{ color: config.color }}>
              {config.label}
            </span>
          </div>
          <h4 className="font-bold text-white">{prediction.description}</h4>
        </div>
      </div>

      {/* Probability Meter */}
      <div className="flex flex-col gap-2">
        <div className="flex items-center justify-between text-sm">
          <span className="text-gray-400">Probability</span>
          <span className="font-mono font-bold" style={{ color: probabilityColor }}>
            {(prediction.probability * 100).toFixed(1)}%
          </span>
        </div>
        <div className="h-2 rounded-full overflow-hidden bg-gray-800">
          <div
            className="h-full transition-all duration-300"
            style={{
              width: `${prediction.probability * 100}%`,
              backgroundColor: probabilityColor,
              boxShadow: `0 0 8px ${probabilityColor}50`,
            }}
          />
        </div>
      </div>

      {/* Timeframe */}
      <div className="flex items-center gap-2 p-3 rounded-lg bg-gray-800/50 border border-gray-700">
        <span className="text-xs text-gray-400">Expected in:</span>
        <span className="text-sm font-medium text-white">
          {formatTimeframe(prediction.timeframe)}
        </span>
      </div>

      {/* Preventive Measures */}
      {prediction.preventiveMeasures && prediction.preventiveMeasures.length > 0 && (
        <div className="flex flex-col gap-2">
          <div className="text-xs font-medium text-gray-400">Preventive Measures:</div>
          <ul className="space-y-1">
            {prediction.preventiveMeasures.map((measure, index) => (
              <li key={index} className="flex items-start gap-2 text-sm text-gray-300">
                <span className="text-cyan-400 flex-shrink-0">→</span>
                <span>{measure}</span>
              </li>
            ))}
          </ul>
        </div>
      )}

      {/* Confidence */}
      <div className="flex items-center gap-2">
        <span className="text-xs text-gray-400">Confidence:</span>
        <div className="flex-1 h-1.5 rounded-full overflow-hidden bg-gray-800">
          <div
            className="h-full transition-all duration-300"
            style={{
              width: `${prediction.confidence * 100}%`,
              backgroundColor: '#8B5CF6',
              boxShadow: '0 0 6px rgba(139, 92, 246, 0.3)',
            }}
          />
        </div>
        <span className="text-xs font-mono font-bold text-purple-400">
          {(prediction.confidence * 100).toFixed(0)}%
        </span>
      </div>

      {/* Actions */}
      {onViewDetails && (
        <button
          onClick={() => onViewDetails(prediction.id)}
          className="w-full px-4 py-2 rounded-lg text-sm font-medium border transition-all hover:bg-gray-800"
          style={{
            borderColor: `${config.color}50`,
            color: config.color,
          }}
        >
          View Details
        </button>
      )}

      {/* Timestamp */}
      <div className="text-xs text-gray-500">
        Predicted {new Date(prediction.predictedAt).toLocaleString()}
      </div>
    </div>
  )
}

AIPredictionCard.displayName = 'AIPredictionCard'

export default AIPredictionCard
