// ═══════════════════════════════════════════════════════════════
// PRESTIGE DASHBOARD - WebSocket Store Integration
// ═══════════════════════════════════════════════════════════════

import React, { useEffect, useRef } from 'react'
import { websocketService } from '@/services/websocket'
import { usePrinterStore } from '@core/state/printerStore'
import { useAIStore } from '@core/state/aiStore'
import type { ExecutedAction } from '@core/state/aiStore'
import { useSystemStore } from '@core/state/systemStore'
import { useUIStore } from '@core/state/uiStore'
import type { WebSocketMessage } from '@core/types'
import { normalizePrinterStatus as normalizeStatus } from '@core/utils/normalizePrinterStatus'

// ─────────────────────────────────────────────────────────────
// Backend sends payload field, not data field.
// ─────────────────────────────────────────────────────────────
function getPayload(message: any): any {
  return message.payload ?? message.data ?? {}
}

// ─────────────────────────────────────────────────────────────
// Throttle — max one temp update per printer per 1.5s.
// Accepts the ref map so no module-level state is needed.
// ─────────────────────────────────────────────────────────────
const TEMP_THROTTLE_MS = 1500

function shouldUpdateTemp(
  printerId: string,
  lastTempUpdate: Record<string, number>
): boolean {
  const now  = Date.now()
  const last = lastTempUpdate[printerId] ?? 0
  if (now - last < TEMP_THROTTLE_MS) return false
  lastTempUpdate[printerId] = now
  return true
}

// ─────────────────────────────────────────────────────────────
// Disconnect debounce — 3s window to absorb reconnect flicker.
// Accepts the ref map so cleanup is owned by the hook.
// ─────────────────────────────────────────────────────────────
const DISCONNECT_DEBOUNCE_MS = 3000

function scheduleDisconnect(
  printerId: string,
  pendingDisconnects: Record<string, ReturnType<typeof setTimeout>>,
  cb: () => void
): void {
  cancelDisconnect(printerId, pendingDisconnects)
  pendingDisconnects[printerId] = setTimeout(() => {
    delete pendingDisconnects[printerId]
    cb()
  }, DISCONNECT_DEBOUNCE_MS)
}

function cancelDisconnect(
  printerId: string,
  pendingDisconnects: Record<string, ReturnType<typeof setTimeout>>
): void {
  if (pendingDisconnects[printerId]) {
    clearTimeout(pendingDisconnects[printerId])
    delete pendingDisconnects[printerId]
  }
}

// ─────────────────────────────────────────────────────────────
// parseTemps — normalizes backend { actual, target } format.
// Populates both `actual` and `current` for component compat.
// ─────────────────────────────────────────────────────────────
function parseTemps(temps: any) {
  if (!temps) return null
  const norm = (t: any) => {
    if (!t) return undefined
    const value = t.actual ?? t.current ?? 0
    return { actual: value, current: value, target: t.target ?? 0, ...(t.power != null && { power: t.power }) }
  }
  return {
    hotend: norm(temps.hotend),
    bed:    norm(temps.bed),
    ...(temps.chamber && { chamber: norm(temps.chamber) }),
  }
}

export function useWebSocketIntegration() {
  const printerStore = usePrinterStore()
  const aiStore      = useAIStore()
  const systemStore  = useSystemStore()
  const uiStore      = useUIStore()

  const printerStoreRef = useRef(printerStore)
  const aiStoreRef      = useRef(aiStore)
  const systemStoreRef  = useRef(systemStore)
  const uiStoreRef      = useRef(uiStore)

  printerStoreRef.current = printerStore
  aiStoreRef.current      = aiStore
  systemStoreRef.current  = systemStore
  uiStoreRef.current      = uiStore

  // ── Per-instance state (not module-level) ─────────────────
  // Owned by this hook instance — cleaned up on unmount.
  // Keyed by printerId; stale entries are harmless (O(n) numbers/timers)
  // but pending timers are explicitly cancelled in cleanup below.
  const lastTempUpdateRef    = useRef<Record<string, number>>({})
  const pendingDisconnectsRef = useRef<Record<string, ReturnType<typeof setTimeout>>>({})

  useEffect(() => {
    const lastTempUpdate    = lastTempUpdateRef.current
    const pendingDisconnects = pendingDisconnectsRef.current
    let previousStatus: string | null = null

    // ─────────────────────────────────────────────────────────
    // CONNECTION STATUS
    // ─────────────────────────────────────────────────────────
    const unsubscribeState = websocketService.onStateChange((state) => {
      const statusMap = {
        connected:    'connected'    as const,
        connecting:   'connecting'   as const,
        disconnected: 'disconnected' as const,
        reconnecting: 'reconnecting' as const,
        error:        'error'        as const,
      }
      const prevStatus = previousStatus
      previousStatus = state

      systemStoreRef.current.setConnectionStatus(statusMap[state] || 'disconnected')
      if (state === 'connected' && prevStatus !== null && prevStatus !== 'connected' && prevStatus !== 'reconnecting') {
        uiStoreRef.current.addNotification({ type: 'success', title: 'Connected', message: 'Connected to backend', duration: 2000 })
      } else if (state === 'disconnected' && prevStatus === 'connected') {
        uiStoreRef.current.addNotification({ type: 'warning', title: 'Disconnected', message: 'Connection to backend lost', duration: 4000 })
      }
    })

    // ─────────────────────────────────────────────────────────
    // WILDCARD HANDLER — listens to ALL backend messages
    // ─────────────────────────────────────────────────────────
    const unsubscribeAll = websocketService.subscribe('*' as any, (message: any) => {
      const type: string = message.type
      const payload = getPayload(message)

      switch (type) {

        // ── PRINTER_STATE ──────────────────────────────────────
        case 'printer_state': {
          const eventType: string = payload.eventType ?? ''
          const printerId: string = payload.printerId
          if (!printerId) break

          if (eventType === 'printer.temperature_changed' || payload.temperatures) {
            const parsed = parseTemps(payload.temperatures)
            if (parsed && shouldUpdateTemp(printerId, lastTempUpdate)) {
              printerStoreRef.current.updatePrinter(printerId, {
                liveState: { temperatures: parsed } as any,
              })
            }
          }

          if (eventType === 'printer.status_updated' || payload.status) {
            const statusData = payload.status
            if (statusData) {
              if (statusData.state) {
                printerStoreRef.current.updatePrinterStatus(printerId, normalizeStatus(statusData.state))
              }
              if (statusData.temperatures && shouldUpdateTemp(printerId, lastTempUpdate)) {
                const parsed = parseTemps(statusData.temperatures)
                if (parsed) {
                  printerStoreRef.current.updatePrinter(printerId, {
                    liveState: {
                      temperatures: parsed,
                      ...(statusData.progress != null && {
                        progress: {
                          percentage:    statusData.progress,
                          filename:      statusData.currentFile,
                          timeElapsed:   0,
                          timeRemaining: 0,
                        },
                      }),
                    } as any,
                  })
                }
              }
            }
          }

          if (eventType === 'printer.connected') {
            cancelDisconnect(printerId, pendingDisconnects)
            printerStoreRef.current.updatePrinterStatus(printerId, 'idle')
          }
          if (eventType === 'printer.disconnected') {
            scheduleDisconnect(printerId, pendingDisconnects, () => {
              printerStoreRef.current.updatePrinterStatus(printerId, 'disconnected')
            })
          }
          if (eventType === 'printer.state_changed' && payload.newState) {
            cancelDisconnect(printerId, pendingDisconnects)
            printerStoreRef.current.updatePrinterStatus(printerId, normalizeStatus(payload.newState))
          }

          if (payload.position || payload.status?.position) {
            const pos = payload.position ?? payload.status?.position
            if (pos?.x !== undefined) {
              printerStoreRef.current.updatePrinter(printerId, {
                liveState: {
                  position: { x: pos.x ?? 0, y: pos.y ?? 0, z: pos.z ?? 0, e: pos.e ?? 0 },
                } as any,
              })
            }
          }

          if (eventType === 'printer.print_started') {
            printerStoreRef.current.updatePrinterStatus(printerId, 'printing')
            uiStoreRef.current.addNotification({ type: 'info', title: 'Print Started', message: `Print started: ${payload.filename || ''}` })
          }
          if (eventType === 'printer.print_completed') {
            printerStoreRef.current.updatePrinterStatus(printerId, 'idle')
            uiStoreRef.current.addNotification({ type: 'success', title: 'Print Completed', message: 'Print finished successfully' })
          }
          if (eventType === 'printer.print_cancelled') printerStoreRef.current.updatePrinterStatus(printerId, 'idle')
          if (eventType === 'printer.print_paused')    printerStoreRef.current.updatePrinterStatus(printerId, 'paused')
          if (eventType === 'printer.print_resumed')   printerStoreRef.current.updatePrinterStatus(printerId, 'printing')
          if (eventType === 'printer.error') {
            printerStoreRef.current.updatePrinterStatus(printerId, 'error')
            uiStoreRef.current.addNotification({ type: 'error', title: 'Printer Error', message: payload.message || `Printer ${printerId} error`, priority: 'high' })
          }
          break
        }

        // ── PRINTER_STATUS ─────────────────────────────────────
        case 'printer_status': {
          const { printerId, status } = payload
          if (printerId && status) printerStoreRef.current.updatePrinterStatus(printerId, normalizeStatus(status))
          break
        }

        // ── PRINTER_TEMPERATURE ────────────────────────────────
        case 'printer_temperature': {
          const { printerId } = payload
          const parsed = parseTemps(payload.temperatures)
          if (printerId && parsed && shouldUpdateTemp(printerId, lastTempUpdate)) {
            printerStoreRef.current.updatePrinter(printerId, {
              liveState: { temperatures: parsed } as any,
            })
          }
          break
        }

        // ── PRINTER_PROGRESS ───────────────────────────────────
        case 'printer_progress': {
          const { printerId, progress } = payload
          if (printerId && progress != null) {
            printerStoreRef.current.updatePrinter(printerId, {
              liveState: {
                progress: {
                  percentage:    progress.progressPercent ?? progress.percentage ?? 0,
                  filename:      progress.filename,
                  timeElapsed:   progress.elapsedSeconds   ?? 0,
                  timeRemaining: progress.remainingSeconds ?? 0,
                  currentLayer:  progress.currentLayer,
                  totalLayers:   progress.totalLayers,
                },
              } as any,
            })
          }
          break
        }

        // ── PRINTER_POSITION ───────────────────────────────────
        case 'printer_position': {
          const { printerId, position } = payload
          if (!printerId || !position) break
          printerStoreRef.current.updatePrinter(printerId, {
            liveState: {
              position: { x: position.x ?? 0, y: position.y ?? 0, z: position.z ?? 0, e: position.e ?? 0 },
              ...(position.homedAxes !== undefined && { homedAxes: position.homedAxes }),
            } as any,
          })
          break
        }

        // ── BACKWARD COMPAT ────────────────────────────────────
        case 'state': {
          if (payload.printers) printerStoreRef.current.setPrinters(payload.printers)
          else if (payload.printer) printerStoreRef.current.updatePrinter(payload.printer.id, payload.printer)
          break
        }

        case 'event': {
          const { printerId, event, data } = payload || {}
          if (!printerId || !event) break
          if (event === 'print_started')   uiStoreRef.current.addNotification({ type: 'info',    title: 'Print Started',   message: `Printer ${data?.printerName || printerId} started` })
          if (event === 'print_completed') uiStoreRef.current.addNotification({ type: 'success', title: 'Print Completed', message: `Printer ${data?.printerName || printerId} finished` })
          if (event === 'print_failed')    uiStoreRef.current.addNotification({ type: 'error',   title: 'Print Failed',    message: `Printer ${data?.printerName || printerId} error`, priority: 'high' })
          break
        }

        // ── AI EVENTS ──────────────────────────────────────────

        // ── Phase 4: CUSUM anomaly from SmartRecorder ─────────────
        case 'ai.anomaly': {
          const { printerId, type, direction, metric, value, target, score, severity, detectedAt } = payload || {}
          if (!printerId || !type) break

          // Build a BackendAnomaly-compatible object and push to store
          const anomalyId = `cusum-${printerId}-${Date.now()}`
          aiStoreRef.current.addAnomaly({
            id:            anomalyId,
            printerId,
            type,
            severity:      severity ?? 'warning',
            confidence:    typeof score === 'number' ? Math.min(1, score) : 0.5,
            description:   `CUSUM ${type}: ${metric} is ${direction} (value=${typeof value === 'number' ? value.toFixed(2) : value}${target !== undefined ? `, target=${target}` : ''})`,
            metric:        metric ?? '',
            expectedValue: target ?? 0,
            actualValue:   value  ?? 0,
            deviation:     typeof value === 'number' && typeof target === 'number' ? Math.abs(value - target) : 0,
            detectedAt:    detectedAt ?? new Date().toISOString(),
            resolvedAt:    null,
          })

          const isCritical = severity === 'critical'
          const typeLabels: Record<string, string> = {
            thermal_anomaly:   '🌡️ Thermal Runaway',
            bed_stability:     '🛏️ Bed Instability',
            extruder_pressure: '⚙️ Possible Clog',
          }
          uiStoreRef.current.addNotification({
            type:     isCritical ? 'error' : 'warning',
            title:    typeLabels[type] ?? 'AI Anomaly',
            message:  `Printer ${printerId.slice(0, 8)}: ${metric} is ${direction} (score ${typeof score === 'number' ? (score * 100).toFixed(0) : '?'}%)`,
            priority: isCritical ? 'critical' : 'high',
            duration: isCritical ? 0 : 10_000,
          })
          break
        }

        case 'ai.recommendation': {
          const rec = payload.recommendation
          if (!rec) break
          aiStoreRef.current.addRecommendation(rec)
          const pMap: Record<string, any> = { critical: 'critical', high: 'high', medium: 'medium', normal: 'medium', low: 'low' }
          uiStoreRef.current.addNotification({ type: 'info', title: 'AI Recommendation', message: rec.title || 'New recommendation', priority: pMap[rec.priority] || 'medium', duration: rec.priority === 'critical' ? 0 : 8000 })
          break
        }

        case 'ai.action.executed': {
          const action = payload.action as ExecutedAction | undefined
          if (!action) break
          aiStoreRef.current.addExecutedAction(action)
          uiStoreRef.current.addNotification({
            type: 'warning', title: 'AI Action Executed', message: `${action.actionType}: ${action.reason}`, priority: 'high',
            actions: [
              { label: 'Revert',       onClick: () => websocketService.send({ type: 'ai.action.response', data: { actionId: action.id, response: 'revert' } }) },
              { label: 'Acknowledge',  onClick: () => aiStoreRef.current.acknowledgeAction(action.id) },
            ],
          })
          break
        }

        // ── SYSTEM STATUS ──────────────────────────────────────
        case 'system.status': {
          const { health, version } = payload || {}
          if (health)   systemStoreRef.current.setHealth({ ...health, status: health.status === 'unhealthy' ? 'critical' : health.status } as any)
          if (version)  systemStoreRef.current.setBackendVersion(version)
          break
        }

        // ── ERRORS ─────────────────────────────────────────────
        case 'error': {
          const msg = payload.error || payload.message || 'Unknown error'
          systemStoreRef.current.addError(msg)
          uiStoreRef.current.addNotification({ type: 'error', title: 'Error', message: msg, priority: 'high' })
          break
        }

        // ── IGNORE ─────────────────────────────────────────────
        case 'pong':
        case 'welcome':
        case 'subscribed':
        case 'unsubscribed':
        case 'system_event':
          break

        default:
          break
      }
    })

    return () => {
      unsubscribeState()
      unsubscribeAll()

      // Cancel every pending disconnect timer and wipe both maps.
      // This covers: hook unmount, printer deletion, app teardown.
      Object.keys(pendingDisconnects).forEach((id) => {
        clearTimeout(pendingDisconnects[id])
        delete pendingDisconnects[id]
      })
      // lastTempUpdate holds plain numbers — no cleanup needed beyond GC,
      // but we clear it to release printerId string keys from memory.
      Object.keys(lastTempUpdate).forEach((id) => delete lastTempUpdate[id])
    }
  }, [])
}

export function WebSocketProvider({ children }: { children: React.ReactNode }) {
  useWebSocketIntegration()
  return <>{children}</>
}

export default useWebSocketIntegration
