// PRESTIGE DASHBOARD - MESH HISTORY CHART
// SPEC: features/bed-mesh/ — MeshHistoryChart
// Shows bed mesh range/mean trends over time using recharts
// ═══════════════════════════════════════════════════════════════

import { useMemo } from 'react'
import { TrendingUp, TrendingDown, Minus } from 'lucide-react'

interface MeshHistoryEntry {
  date: string
  range: number
  mean: number
}

interface MeshHistoryChartProps {
  history: MeshHistoryEntry[]
}

export function MeshHistoryChart({ history }: MeshHistoryChartProps) {
  // Calculate trend
  const trend = useMemo(() => {
    if (history.length < 2) return 'stable'
    const recent = history.slice(-3)
    const older = history.slice(-6, -3)
    if (older.length === 0) return 'stable'
    const recentAvg = recent.reduce((s, h) => s + h.range, 0) / recent.length
    const olderAvg = older.reduce((s, h) => s + h.range, 0) / older.length
    if (recentAvg > olderAvg * 1.1) return 'worsening'
    if (recentAvg < olderAvg * 0.9) return 'improving'
    return 'stable'
  }, [history])

  if (history.length === 0) {
    return (
      <div className="text-center py-12 text-text-muted">
        <p className="text-sm">No mesh history yet</p>
        <p className="text-xs mt-1">History is recorded each time bed mesh is loaded</p>
      </div>
    )
  }

  // Simple bar chart without recharts dependency
  const maxRange = Math.max(...history.map(h => h.range), 0.1)

  return (
    <div className="space-y-4">
      {/* Trend indicator */}
      <div className="flex items-center gap-3">
        <h3 className="text-sm font-semibold text-text">Mesh Variance Trend</h3>
        <div className={`flex items-center gap-1 text-xs font-semibold px-2 py-0.5 rounded ${
          trend === 'improving' ? 'bg-green-500/10 text-green-400'
          : trend === 'worsening' ? 'bg-red-500/10 text-state-error'
          : 'bg-surface text-text-muted'
        }`}>
          {trend === 'improving' && <><TrendingDown className="w-3 h-3" /> Improving</>}
          {trend === 'worsening' && <><TrendingUp className="w-3 h-3" /> Worsening</>}
          {trend === 'stable' && <><Minus className="w-3 h-3" /> Stable</>}
        </div>
      </div>

      {/* Bar chart */}
      <div className="space-y-1">
        {history.map((entry, i) => {
          const widthPct = Math.max(4, (entry.range / maxRange) * 100)
          const barColor = entry.range < 0.1 ? 'bg-green-500'
            : entry.range < 0.2 ? 'bg-primary'
            : entry.range < 0.4 ? 'bg-yellow-500'
            : 'bg-red-500'

          return (
            <div key={i} className="flex items-center gap-2 text-xs">
              <span className="w-32 text-text-muted font-mono flex-shrink-0 text-right text-[10px]">
                {new Date(entry.date).toLocaleString(undefined, { 
                  month: 'short', 
                  day: 'numeric',
                  hour: '2-digit',
                  minute: '2-digit'
                })}
              </span>
              <div className="flex-1 h-5 bg-surface rounded overflow-hidden relative">
                <div
                  className={`h-full ${barColor} rounded transition-all duration-300`}
                  style={{ width: `${widthPct}%` }}
                />
                <span className="absolute right-2 top-0.5 text-[10px] font-mono text-text-muted">
                  {entry.range.toFixed(3)}mm
                </span>
              </div>
            </div>
          )
        })}
      </div>

      {/* Summary */}
      <div className="grid grid-cols-3 gap-3 text-xs">
        <div className="p-2 rounded-lg bg-surface border border-border text-center">
          <div className="text-text-muted">Best</div>
          <div className="font-mono font-bold text-green-400">
            {Math.min(...history.map(h => h.range)).toFixed(3)}mm
          </div>
        </div>
        <div className="p-2 rounded-lg bg-surface border border-border text-center">
          <div className="text-text-muted">Average</div>
          <div className="font-mono font-bold text-text">
            {(history.reduce((s, h) => s + h.range, 0) / history.length).toFixed(3)}mm
          </div>
        </div>
        <div className="p-2 rounded-lg bg-surface border border-border text-center">
          <div className="text-text-muted">Latest</div>
          <div className="font-mono font-bold text-primary">
            {history[history.length - 1].range.toFixed(3)}mm
          </div>
        </div>
      </div>
    </div>
  )
}

export default MeshHistoryChart
