// ═══════════════════════════════════════════════════════════════

import { useEffect } from 'react'
import { Header } from './Header'
import { Sidebar } from './Sidebar'
import { ToastContainer } from '@core/components/ToastContainer'
import { VirtualAssistant } from '@core/components/VirtualAssistant'
import { useUIStore, selectSidebarCollapsed, selectIsMobile } from '@core/state'
import { useSystemStore } from '@core/state'
import { usePrinterStore } from '@core/state'
import type { EmergencyControlHandlers } from '@core/components/EmergencyControls/EmergencyControls.types'

interface AppShellProps {
  children: React.ReactNode
}

export function AppShell({ children }: AppShellProps) {
  const sidebarCollapsed = useUIStore(selectSidebarCollapsed)
  const isMobile = useUIStore(selectIsMobile)
  const { setIsMobile } = useUIStore()
  const connectionStatus = useSystemStore((state) => state.connectionStatus)
  const isConnected = connectionStatus === 'connected'
  const { pauseAllPrinters, resumeAllPrinters, emergencyStopAll } = usePrinterStore()

  // Emergency control handlers
  const emergencyHandlers: EmergencyControlHandlers = {
    onEmergencyStop: async (printerId?: string) => {
      if (printerId) {
        // Emergency stop single printer - would need to implement in store
        console.log('Emergency stop printer:', printerId)
      } else {
        emergencyStopAll()
      }
    },
    onPauseAll: async () => {
      pauseAllPrinters()
    },
    onResumeAll: async () => {
      resumeAllPrinters()
    },
    onHaltAll: async () => {
      emergencyStopAll()
    },
    onCancelAll: async () => {
      // Would need to implement cancel all in store
      console.log('Cancel all printers')
    },
  }

  // Detect mobile on mount and resize
  useEffect(() => {
    const checkMobile = () => {
      setIsMobile(window.innerWidth < 1024)
    }

    checkMobile()
    window.addEventListener('resize', checkMobile)
    return () => window.removeEventListener('resize', checkMobile)
  }, [setIsMobile])

  // Calculate main content margin based on sidebar state
  const sidebarWidth = isMobile ? 0 : sidebarCollapsed ? 72 : 280

  return (
    <div className="h-screen overflow-hidden bg-background">
      {/* Background grid pattern */}
      <div className="fixed inset-0 bg-grid-pattern bg-grid opacity-50 pointer-events-none" />

      {/* Prestige background image */}
      <div
        className="fixed inset-0 pointer-events-none"
        style={{
          backgroundImage: 'url(/prestige_bg_heatmap_quality_4096x2731.png)',
          backgroundSize: 'cover',
          backgroundPosition: 'bottom right',
          backgroundRepeat: 'no-repeat',
          opacity: 0.18,
          zIndex: 0,
        }}
      />

      {/* Sidebar */}
      <Sidebar isConnected={isConnected} emergencyHandlers={emergencyHandlers} />

      {/* Main content area */}
      <div
        className="flex flex-col h-screen transition-all duration-300"
        style={{ marginLeft: sidebarWidth }}
      >
        {/* Header */}
        <Header />

        {/* Page content */}
        <main className="flex-1 min-h-0 overflow-hidden relative z-0">
          <div className="w-full h-full">
            {children}
          </div>
        </main>

        {/* Footer - UPDATED 2026 */}
        <footer className="px-6 py-3 border-t border-gray-800 bg-gray-900/50 backdrop-blur-sm">
          <div className="flex items-center justify-between text-xs">
            <span 
              className="font-semibold tracking-wide"
              style={{
                color: 'rgba(0,212,255,0.7)',
                fontFamily: "'Share Tech Mono', monospace",
              }}
            >
              PRESTIGE Dashboard v1.0.0
            </span>
            <span 
              className="font-medium"
              style={{
                color: 'rgba(148,163,184,0.8)',
                fontFamily: "'Inter', sans-serif",
              }}
            >
              © 2026 - Multi-Printer AI Monitoring
            </span>
          </div>
        </footer>
      </div>

      {/* Toast Notifications */}
      <ToastContainer />

      {/* Virtual Assistant floating widget */}
      <VirtualAssistant />
    </div>
  )
}

export default AppShell
