// SPEC: PAPILDINĀJUMS — MANUĀLĀS IZMAIŅAS §7 — MaintenanceHistory
// Per-printer chronological log of all manual changes
// ═══════════════════════════════════════════════════════════════

import { useState, useEffect } from 'react'
import { ClipboardList, Calendar, CheckCircle, ChevronDown, ChevronRight, Clock } from 'lucide-react'
import { getChangeTypeDefinition } from './ManualChangeTypes'

interface MaintenanceEvent {
  id: string
  printerId: string
  timestamp: string
  changeType: string
  category: string
  description?: string
  affectedComponents: string[]
  aiStatus?: 'baseline_reset' | 'learning' | 'complete'
  aiLearningProgress?: number
}

interface MaintenanceHistoryProps {
  printerId?: string
  printerName?: string
}

export function MaintenanceHistory({ printerId, printerName }: MaintenanceHistoryProps) {
  const [events, setEvents] = useState<MaintenanceEvent[]>([])
  const [loading, setLoading] = useState(true)
  const [expandedId, setExpandedId] = useState<string | null>(null)

  useEffect(() => {
    const fetchHistory = async () => {
      if (!printerId) { setLoading(false); return }
      setLoading(true)
      try {
        const baseUrl = import.meta.env.VITE_API_URL || 'http://localhost:3002'
        const res = await fetch(`${baseUrl}/api/ai/printers/${printerId}/maintenance?limit=50`)
        if (res.ok) {
          const data = await res.json()
          // Map AI maintenance records → MaintenanceEvent shape
          const records: any[] = data?.data?.records ?? data?.records ?? []
          setEvents(records.map((r: any) => ({
            id: r.id,
            printerId: r.printerId,
            timestamp: r.performedAt ?? r.timestamp,
            changeType: r.type ?? 'other',
            category: 'MAINTENANCE',
            description: r.description,
            affectedComponents: [],
            aiStatus: 'complete' as const,
          })))
        }
      } catch {
        // Graceful fallback
      } finally {
        setLoading(false)
      }
    }
    fetchHistory()
  }, [printerId])

  const aiStatusBadge = (event: MaintenanceEvent) => {
    const status = event.aiStatus || 'complete'
    switch (status) {
      case 'baseline_reset':
        return <span className="text-[10px] px-1.5 py-0.5 rounded bg-yellow-500/20 text-yellow-400 font-semibold">Baseline Reset</span>
      case 'learning':
        return (
          <span className="text-[10px] px-1.5 py-0.5 rounded bg-cyan-500/20 text-cyan-400 font-semibold">
            Learning {event.aiLearningProgress !== undefined ? `${event.aiLearningProgress}%` : ''}
          </span>
        )
      case 'complete':
        return <span className="text-[10px] px-1.5 py-0.5 rounded bg-green-500/20 text-green-400 font-semibold">✓ Baseline Stable</span>
      default:
        return null
    }
  }

  return (
    <div className="bg-gray-900/50 border border-gray-700 rounded-lg p-4">
      {/* Header */}
      <div className="flex items-center gap-2 mb-4">
        <ClipboardList className="w-4 h-4 text-cyan-400" />
        <h2 className="text-sm font-semibold text-gray-200">Maintenance History</h2>
      </div>

      {/* Timeline */}
      {loading ? (
        <div className="py-8 text-center text-gray-400 text-sm">Loading history...</div>
      ) : events.length === 0 ? (
        <div className="py-8 text-center text-gray-400">
          <ClipboardList className="w-10 h-10 mx-auto mb-2 opacity-20" />
          <p className="text-sm">No maintenance events recorded</p>
          <p className="text-xs mt-1">Register manual changes to help AI learn faster</p>
        </div>
      ) : (
        <div className="space-y-3">
          {events.map((event, i) => {
            const def = getChangeTypeDefinition(event.changeType)
            const isExpanded = expandedId === event.id
            const date = new Date(event.timestamp)

            return (
              <div key={event.id} className="relative">
                {/* Timeline connector */}
                {i < events.length - 1 && (
                  <div className="absolute left-[19px] top-10 bottom-0 w-px bg-gray-700" />
                )}

                <div className="flex items-start gap-3">
                  {/* Timeline dot */}
                  <div className="flex-shrink-0 w-10 h-10 rounded-full border-2 border-cyan-500 bg-gray-800 flex items-center justify-center text-lg">
                    {event.category === 'MAINTENANCE' ? '🔧'
                      : event.category === 'COMPONENT_REPLACEMENT' ? '🔄'
                      : event.category === 'UPGRADE' ? '⬆️'
                      : '📋'
                    }
                  </div>

                  {/* Content */}
                  <div className="flex-1 rounded-lg border border-gray-700 bg-gray-800/50 overflow-hidden">
                    <button
                      onClick={() => setExpandedId(isExpanded ? null : event.id)}
                      className="w-full flex items-center justify-between px-3 py-2.5 hover:bg-gray-800 transition-colors text-left"
                    >
                      <div className="flex-1">
                        <div className="flex items-center gap-2">
                          <span className="text-sm font-semibold text-gray-200">
                            {def?.label || event.changeType}
                          </span>
                          {aiStatusBadge(event)}
                        </div>
                        <div className="flex items-center gap-2 mt-0.5 text-xs text-gray-400">
                          <Calendar className="w-3 h-3" />
                          {date.toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' })}
                          <Clock className="w-3 h-3 ml-1" />
                          {date.toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit' })}
                        </div>
                      </div>
                      {isExpanded
                        ? <ChevronDown className="w-4 h-4 text-gray-400 flex-shrink-0" />
                        : <ChevronRight className="w-4 h-4 text-gray-400 flex-shrink-0" />
                      }
                    </button>

                    {isExpanded && (
                      <div className="px-3 pb-3 border-t border-gray-700 pt-2 space-y-2 text-xs">
                        {event.description && (
                          <div>
                            <span className="text-gray-400">Description: </span>
                            <span className="text-gray-200">{event.description}</span>
                          </div>
                        )}
                        {event.affectedComponents.length > 0 && (
                          <div>
                            <span className="text-gray-400">Affected AI models: </span>
                            <span className="font-mono text-cyan-400">{event.affectedComponents.join(', ')}</span>
                          </div>
                        )}
                        {def && (
                          <div>
                            <span className="text-gray-400">Learning estimate: </span>
                            <span className="text-gray-200">~{def.learningHours} print hours</span>
                          </div>
                        )}
                        <div>
                          <span className="text-gray-400">Category: </span>
                          <span className="text-gray-200">{event.category}</span>
                        </div>
                        <div>
                          <span className="text-gray-400">Event ID: </span>
                          <span className="font-mono text-gray-500">{event.id}</span>
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            )
          })}
        </div>
      )}
    </div>
  )
}

export default MaintenanceHistory
