// ═══════════════════════════════════════════════════════════════
// FEATURE: FAN CONTROL PANEL
// Extracted from PrinterDetailPage
// ═══════════════════════════════════════════════════════════════

import { useState, useEffect, useRef } from 'react'
import { Wind } from 'lucide-react'
import { clamp } from '@/utils/helpers'
import { API_BASE_URL } from '@/utils/constants'
import type { Printer } from '@core/types/printer'

interface FanDef { id: string; label: string; type: string }

export function FanControlPanel({ printer }: { printer: Printer }) {
  const [fans, setFans] = useState<FanDef[]>([])
  const [speeds, setSpeeds] = useState<Record<string, number>>({})
  const [sending, setSending] = useState<Set<string>>(new Set())
  const [msg, setMsg] = useState<{ type: 'ok' | 'err'; text: string } | null>(null)
  const debounceRef = useRef<Record<string, ReturnType<typeof setTimeout>>>({})

  useEffect(() => {
    fetch(`${API_BASE_URL}/api/printers/${printer.id}/fans`)
      .then(r => r.json())
      .then(d => {
        const list: FanDef[] = d?.data?.fans ?? [{ id: 'fan', label: 'Part Fan', type: 'fan' }]
        setFans(list)
        const init: Record<string, number> = {}
        list.forEach(f => { init[f.id] = 0 })
        setSpeeds(init)
      })
      .catch(() => {
        setFans([{ id: 'fan', label: 'Part Fan', type: 'fan' }])
        setSpeeds({ fan: 0 })
      })
  }, [printer.id])

  const buildFanGcode = (fanId: string, speed: number): string => {
    const type = fans.find(f => f.id === fanId)?.type ?? 'fan'
    if (fanId === 'fan') return speed === 0 ? 'M107' : `M106 S${Math.round(speed / 100 * 255)}`
    const val = (speed / 100).toFixed(4)
    const name = fanId.split(' ').slice(1).join(' ') || fanId
    return `SET_FAN_SPEED FAN=${name} SPEED=${val}`
  }

  const sendGcodeViaBackend = async (gcode: string): Promise<boolean> => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/printers/${printer.id}/gcode-direct`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ gcode }),
      })
      return res.ok
    } catch { return false }
  }

  const sendFanCommand = async (fanId: string, speed: number): Promise<boolean> =>
    sendGcodeViaBackend(buildFanGcode(fanId, speed))

  const handleSliderChange = (fanId: string, speed: number) => {
    setSpeeds(prev => ({ ...prev, [fanId]: speed }))
    if (debounceRef.current[fanId]) clearTimeout(debounceRef.current[fanId])
    debounceRef.current[fanId] = setTimeout(() => sendFanSpeedToApi(fanId, speed), 300)
  }

  const sendFanSpeedToApi = async (fanId: string, speed: number) => {
    setSending(prev => new Set(prev).add(fanId))
    setMsg(null)
    const label = fanId === 'fan' ? 'Part Fan' : fanId.split(' ').pop() ?? fanId
    const ok = await sendFanCommand(fanId, speed)
    setMsg({ type: ok ? 'ok' : 'err', text: ok ? `${label} → ${speed}%` : 'Failed — check connection' })
    setTimeout(() => setMsg(null), 2000)
    setSending(prev => { const s = new Set(prev); s.delete(fanId); return s })
  }

  const stepFan = (fanId: string, delta: number) =>
    handleSliderChange(fanId, clamp((speeds[fanId] ?? 0) + delta, 0, 100))

  const sendAll = async (speed: number) => {
    const next: Record<string, number> = {}
    fans.forEach(f => { next[f.id] = speed })
    setSpeeds(next)
    setMsg(null)
    const results = await Promise.all(fans.map(f => sendFanCommand(f.id, speed)))
    const allOk = results.every(Boolean)
    setMsg({ type: allOk ? 'ok' : 'err', text: allOk ? `All fans → ${speed}%` : 'Some commands failed' })
    setTimeout(() => setMsg(null), 2000)
  }

  const isControllable = (type: string) => type === 'fan' || type === 'fan_generic'

  return (
    <div className="bg-gray-900/50 border border-gray-700 rounded-lg p-4">
      <div className="flex items-center justify-between mb-4">
        <h3 className="text-sm font-semibold text-gray-200 flex items-center gap-2">
          <Wind className="w-4 h-4 text-cyan-400" />Fans
        </h3>
        <div className="flex gap-1.5">
          <button onClick={() => sendAll(100)} className="px-3 py-1 text-xs font-medium bg-cyan-500/20 text-cyan-400 border border-cyan-500/40 rounded hover:bg-cyan-500/30">All 100%</button>
          <button onClick={() => sendAll(0)} className="px-3 py-1 text-xs font-medium bg-gray-800 text-gray-400 border border-gray-700 rounded hover:text-red-400">All Off</button>
        </div>
      </div>

      <div className="space-y-3">
        {fans.map(fan => {
          const spd = speeds[fan.id] ?? 0
          const isSending = sending.has(fan.id)
          const controllable = isControllable(fan.type)
          return (
            <div key={fan.id} className={`border rounded-lg px-3 py-2.5 ${controllable ? 'bg-gray-800/60 border-gray-700/50' : 'bg-gray-900/40 border-gray-700/30 opacity-70'}`}>
              <div className="flex items-center justify-between mb-2">
                <span className="text-xs text-gray-300 font-medium flex items-center gap-1.5">
                  {fan.type === 'heater_fan' ? '🔥' : fan.type === 'controller_fan' ? '🖥️' : '💨'}
                  {fan.label}
                  {!controllable && <span className="text-[9px] text-gray-500 border border-gray-700 rounded px-1">auto</span>}
                  {isSending && <span className="w-1.5 h-1.5 rounded-full bg-cyan-400 animate-pulse" />}
                </span>
                <span className={`text-xs font-mono font-bold tabular-nums w-10 text-right ${spd === 0 ? 'text-gray-500' : 'text-cyan-400'}`}>
                  {spd > 0 ? `${spd}%` : controllable ? '0%' : '—'}
                </span>
              </div>
              {controllable ? (
                <div className="flex items-center gap-2">
                  <button onClick={() => stepFan(fan.id, -5)} disabled={spd === 0}
                    className="w-5 h-5 flex items-center justify-center rounded bg-gray-700/80 text-gray-400 hover:bg-gray-600 disabled:opacity-30 text-xs font-bold flex-shrink-0">−</button>
                  <div className="flex-1">
                    <input type="range" id={`fan-speed-${fan.id}`} name={`fan-speed-${fan.id}`} min={0} max={100} step={1} value={spd}
                      onChange={e => handleSliderChange(fan.id, Number(e.target.value))}
                      className="w-full appearance-none cursor-pointer"
                      style={{ background: `linear-gradient(to right, ${spd === 0 ? '#374151' : '#06b6d4'} 0%, ${spd === 0 ? '#374151' : '#06b6d4'} ${spd}%, #1f2937 ${spd}%, #1f2937 100%)` }}
                    />
                  </div>
                  <button onClick={() => stepFan(fan.id, 5)} disabled={spd === 100}
                    className="w-5 h-5 flex items-center justify-center rounded bg-gray-700/80 text-gray-400 hover:bg-gray-600 disabled:opacity-30 text-xs font-bold flex-shrink-0">+</button>
                </div>
              ) : (
                <div className="flex items-center justify-between">
                  <p className="text-[10px] text-gray-600">Auto (temp. controlled)</p>
                  <div className="flex gap-1">
                    <button onClick={() => sendFanCommand(fan.id, 100).then(ok => setMsg({ type: ok ? 'ok' : 'err', text: ok ? `${fan.label} → 100%` : 'Error' }))}
                      className="px-2 py-0.5 text-[10px] bg-orange-500/20 text-orange-400 border border-orange-500/40 rounded">Force ON</button>
                    <button onClick={() => sendFanCommand(fan.id, 0).then(ok => setMsg({ type: ok ? 'ok' : 'err', text: ok ? `${fan.label} → OFF` : 'Error' }))}
                      className="px-2 py-0.5 text-[10px] bg-gray-800 text-gray-400 border border-gray-700 rounded hover:text-red-400">Force OFF</button>
                  </div>
                </div>
              )}
            </div>
          )
        })}
      </div>

      {msg && (
        <div className={`mt-3 text-xs px-3 py-1.5 rounded border ${msg.type === 'ok' ? 'bg-green-500/10 border-green-500/30 text-green-400' : 'bg-red-500/10 border-red-500/30 text-red-400'}`}>
          {msg.type === 'ok' ? '✓' : '✗'} {msg.text}
        </div>
      )}
    </div>
  )
}
