// ═══════════════════════════════════════════════════════════════
// PRESTIGE — AI SIDEBAR ANALYSIS CARD
// Compact sidebar widget showing last analysis results + Analyze Now
// ═══════════════════════════════════════════════════════════════

import React from 'react'
import { AlertTriangle, CheckCircle, RefreshCw, Sparkles, Wrench, TestTube2 } from 'lucide-react'
import type { AnalysisResult } from './ai-types'

export interface AISidebarAnalysisCardProps {
  lastAnalysis: AnalysisResult | null
  analyzing: boolean
  analyzeResult: { found: number; anomalies: number } | null
  onAnalyze: () => void
  nextAnalyzeIn: number
}

export function AISidebarAnalysisCard({
  lastAnalysis, analyzing, analyzeResult, onAnalyze, nextAnalyzeIn
}: AISidebarAnalysisCardProps) {
  const scoreColor = (v: number) =>
    v >= 80 ? 'text-green-400' : v >= 60 ? 'text-yellow-400' : v >= 40 ? 'text-orange-400' : 'text-red-400'

  const timeStr = lastAnalysis?.timestamp
    ? new Date(lastAnalysis.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })
    : null

  return (
    <div className="bg-gray-900/40 rounded-xl border border-gray-800/50 overflow-hidden">
      {/* Header */}
      <div className="flex items-center gap-1.5 px-3 py-2 border-b border-gray-800/60">
        <TestTube2 className="w-3 h-3 text-cyan-400 flex-shrink-0" />
        <span className="text-[11px] font-semibold text-gray-300 flex-1">Last Analysis</span>
        {timeStr && <span className="text-[9px] text-gray-500">{timeStr}</span>}
      </div>

      {/* Body */}
      <div className="px-3 py-2 space-y-2">
        {!lastAnalysis && !analyzing && (
          <p className="text-[10px] text-gray-500 italic">No data — click Analyze Now</p>
        )}

        {analyzing && (
          <div className="flex items-center gap-1.5 text-[10px] text-cyan-400 animate-pulse">
            <RefreshCw className="w-3 h-3 animate-spin" /> Analyzing...
          </div>
        )}

        {lastAnalysis && (
          <div className={`space-y-1.5 ${analyzing ? 'opacity-50' : ''}`}>
            <div className="grid grid-cols-2 gap-1">
              <div className="rounded bg-gray-800/60 px-2 py-1">
                <div className="text-[9px] text-gray-500">Health</div>
                <div className={`text-sm font-bold leading-none ${scoreColor(lastAnalysis.healthScore ?? 0)}`}>
                  {(lastAnalysis.healthScore ?? 0).toFixed(0)}<span className="text-[10px] opacity-70">%</span>
                </div>
              </div>
              <div className="rounded bg-gray-800/60 px-2 py-1">
                <div className="text-[9px] text-gray-500">Quality</div>
                {lastAnalysis.qualityGrade === 'insufficient_data' || lastAnalysis.qualityScore == null ? (
                  <div className="text-sm font-bold leading-none text-gray-500" title="Not enough telemetry data yet">—</div>
                ) : (
                  <div className={`text-sm font-bold leading-none ${scoreColor(lastAnalysis.qualityScore)}`}>
                    {lastAnalysis.qualityScore.toFixed(0)}<span className="text-[10px] opacity-70">%</span>
                  </div>
                )}
              </div>
              <div className="rounded bg-gray-800/60 px-2 py-1">
                <div className="text-[9px] text-gray-500">Fail Risk</div>
                <div className={`text-sm font-bold leading-none ${
                  (lastAnalysis.failureRisk ?? 0) <= 0.2 ? 'text-green-400' : (lastAnalysis.failureRisk ?? 0) <= 0.5 ? 'text-yellow-400' : 'text-red-400'
                }`}>
                  {((lastAnalysis.failureRisk ?? 0) * 100).toFixed(0)}<span className="text-[10px] opacity-70">%</span>
                </div>
              </div>
              <div className="rounded bg-gray-800/60 px-2 py-1">
                <div className="text-[9px] text-gray-500">Anomalies</div>
                <div className={`text-sm font-bold leading-none ${lastAnalysis.anomalyCount > 0 ? 'text-orange-400' : 'text-green-400'}`}>
                  {lastAnalysis.anomalyCount}
                </div>
              </div>
            </div>

            {(lastAnalysis.clogRisk != null && lastAnalysis.clogRisk > 0.1) && (
              <div className="text-[9px] text-yellow-400 bg-yellow-500/10 border border-yellow-500/20 rounded px-2 py-0.5 flex items-center gap-1">
                <AlertTriangle className="w-2.5 h-2.5" /> Clog {(lastAnalysis.clogRisk * 100).toFixed(0)}%
              </div>
            )}
            {lastAnalysis.wearSeverity && lastAnalysis.wearSeverity !== 'ok' && (
              <div className="text-[9px] text-orange-400 bg-orange-500/10 border border-orange-500/20 rounded px-2 py-0.5 flex items-center gap-1">
                <Wrench className="w-2.5 h-2.5" /> Wear: {lastAnalysis.wearSeverity}
              </div>
            )}
          </div>
        )}

        {analyzeResult && !analyzing && (
          <div className="text-[9px] text-green-400 flex items-center gap-1">
            <CheckCircle className="w-3 h-3" /> {analyzeResult.found} recs · {analyzeResult.anomalies} anom
          </div>
        )}

        <div className="flex items-center gap-1.5 pt-1 border-t border-gray-800/60">
          <button
            onClick={onAnalyze}
            disabled={analyzing}
            className="flex-1 flex items-center justify-center gap-1 py-1.5 rounded-lg text-[10px] font-semibold
              bg-cyan-500/15 text-cyan-400 border border-cyan-500/30 hover:bg-cyan-500/25
              transition-all active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {analyzing
              ? <><RefreshCw className="w-3 h-3 animate-spin" /> Analyzing...</>
              : <><Sparkles className="w-3 h-3" /> Analyze Now</>}
          </button>
          {!analyzing && (
            <span className="text-[9px] text-gray-500 whitespace-nowrap">{nextAnalyzeIn}s</span>
          )}
        </div>
      </div>
    </div>
  )
}

export default AISidebarAnalysisCard
