import { api } from './api'

/**
 * System API endpoints
 */
const ENDPOINTS = {
  health: '/api/health',
  metrics: '/api/system/metrics',
}

/**
 * System health response
 */
export interface SystemHealth {
  status: 'healthy' | 'degraded' | 'critical'
  uptime: number
  version: string
  timestamp: string
  services: {
    database: boolean
    websocket: boolean
    ai: boolean
  }
  metrics: SystemMetrics
}

/**
 * System metrics (CPU, RAM, Disk)
 */
export interface SystemMetrics {
  cpu: {
    usage: number
    temperature: number
    cores: number
    model: string
    user: number
    system: number
    idle: number
  }
  memory: {
    total: number // GB
    used: number // GB
    free: number // GB
    percentage: number
    available: number // GB
  }
  disk: {
    total: number // GB
    used: number // GB
    free: number // GB
    percentage: number
  }
  network: {
    rx: number // bytes
    tx: number // bytes
  }
  uptime: number // seconds
}

/**
 * System API service
 */
export const systemApi = {
  /**
   * Get system health
   */
  getHealth: async (): Promise<SystemHealth> => {
    return api.get<SystemHealth>(ENDPOINTS.health)
  },

  /**
   * Get system metrics (CPU, RAM, Disk)
   */
  getMetrics: async (): Promise<SystemMetrics> => {
    return api.get<SystemMetrics>(ENDPOINTS.metrics)
  },
}

export default systemApi
