// PRESTIGE DASHBOARD - PRINTER GRID TYPES
// ═══════════════════════════════════════════════════════════════

import type { Printer, PrinterFilters, PrinterSort } from '../../types/printer'
import type { PrinterCardLayout, PrinterCardSize, PrinterCardActions } from '../PrinterCard'

/**
 * Grid layout mode
 */
export type GridLayout = 'grid' | 'list' | 'compact'

/**
 * Grid columns configuration
 */
export type GridColumns = 1 | 2 | 3 | 4 | 'auto'

/**
 * View mode configuration
 */
export interface ViewModeConfig {
  layout: GridLayout
  cardSize: PrinterCardSize
  cardLayout: PrinterCardLayout
  columns: GridColumns
}

/**
 * Printer grid props
 */
export interface PrinterGridProps {
  printers: Printer[]
  viewMode?: ViewModeConfig
  filters?: PrinterFilters
  sort?: PrinterSort
  actions?: PrinterCardActions
  loading?: boolean
  emptyMessage?: string
  showFilters?: boolean
  showSort?: boolean
  showSearch?: boolean
  onFiltersChange?: (filters: PrinterFilters) => void
  onSortChange?: (sort: PrinterSort) => void
  className?: string
}

/**
 * Filter option
 */
export interface FilterOption {
  label: string
  value: string
  count?: number
  active?: boolean
}

/**
 * Sort option
 */
export interface SortOption {
  label: string
  value: string
  direction: 'asc' | 'desc'
  icon: string
  active?: boolean
}

/**
 * Default view modes
 */
export const VIEW_MODES: Record<string, ViewModeConfig> = {
  grid_standard: {
    layout: 'grid',
    cardSize: 'md',
    cardLayout: 'standard',
    columns: 'auto',
  },
  grid_compact: {
    layout: 'grid',
    cardSize: 'sm',
    cardLayout: 'compact',
    columns: 'auto',
  },
  grid_detailed: {
    layout: 'grid',
    cardSize: 'lg',
    cardLayout: 'detailed',
    columns: 2,
  },
  list: {
    layout: 'list',
    cardSize: 'md',
    cardLayout: 'standard',
    columns: 1,
  },
  compact: {
    layout: 'compact',
    cardSize: 'sm',
    cardLayout: 'compact',
    columns: 'auto',
  },
}
