// ─── Context ─────────────────────────────────────────────────

const ThemeContext = createContext<ThemeContextType>({
  theme: 'cyberpunk',
  setTheme: () => {},
  themes: AVAILABLE_THEMES,
})

export const useTheme = () => useContext(ThemeContext)

// ─── Provider ────────────────────────────────────────────────

const STORAGE_KEY = 'prestige-theme'

export const ThemeProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [theme] = useState<ThemeName>('cyberpunk')

  const applyTheme = useCallback((themeName: ThemeName) => {
    const root = document.documentElement
    const vars = THEME_VARIABLES[themeName]

    // Remove all overrides first
    Object.keys(vars).forEach(key => root.style.removeProperty(key))

    // Apply theme variables
    Object.entries(vars).forEach(([key, value]) => {
      root.style.setProperty(key, value)
    })

    // Set data attribute for CSS selectors
    root.setAttribute('data-theme', themeName)
    root.classList.remove('light')
    root.classList.add('dark')
  }, [])

  const setTheme = useCallback((newTheme: ThemeName) => {
    localStorage.setItem(STORAGE_KEY, newTheme)
    applyTheme(newTheme)
  }, [applyTheme])

  // Apply on mount
  useEffect(() => {
    applyTheme(theme)
  }, [theme, applyTheme])

  return (
    <ThemeContext.Provider value={{ theme, setTheme, themes: AVAILABLE_THEMES }}>
      {children}
    </ThemeContext.Provider>
  )
}

export default ThemeProvider
