import React from 'react'
import { ChevronDown, ChevronUp } from 'lucide-react'
import type { ApiRoute } from './arch-types'
import { methodColor, critColor, moduleColor } from './arch-data'

interface Props {
  route:    ApiRoute
  expanded: boolean
  onToggle: () => void
}

export function RouteCard({ route, expanded, onToggle }: Props) {
  const mc = methodColor(route.method)
  const cc = critColor(route.criticality)
  const modC = moduleColor(route.module)

  return (
    <div style={{
      background: expanded ? '#0d1e30' : '#0a1525',
      border: `1px solid ${expanded ? cc + '45' : '#1a3550'}`,
      borderRadius: '7px',
      marginBottom: '4px',
      overflow: 'hidden',
      transition: 'background 0.15s, border-color 0.15s',
    }}>
      {/* Row header */}
      <div
        onClick={onToggle}
        style={{ padding: '8px 12px', display: 'flex', alignItems: 'center', gap: '7px', cursor: 'pointer', userSelect: 'none' }}
      >
        <span style={{ color: '#334155', fontSize: '9px', width: 10, flexShrink: 0 }}>
          {expanded ? '▼' : '▶'}
        </span>
        <span style={{ padding: '1px 7px', borderRadius: '4px', fontSize: '9px', fontWeight: 'bold', background: `${mc}20`, color: mc, flexShrink: 0 }}>
          {route.method}
        </span>
        <span style={{ padding: '1px 5px', borderRadius: '3px', fontSize: '8.5px', background: `${cc}15`, color: cc, flexShrink: 0 }}>
          {route.criticality}
        </span>
        <span style={{ padding: '1px 5px', borderRadius: '3px', fontSize: '8px', background: `${modC}10`, color: modC, flexShrink: 0 }}>
          {route.module}
        </span>
        <code style={{
          color: route.criticality === 'REMOVED' ? '#1f2937' : '#c8d8e8',
          flex: 1, fontSize: '11px',
          textDecoration: route.criticality === 'REMOVED' ? 'line-through' : 'none',
          overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
        }}>
          {route.path}
        </code>
        {route.warnings?.length ? <span style={{ color: '#f59e0b', flexShrink: 0, fontSize: '11px' }}>⚠</span> : null}
        {route.criticality === 'REMOVED' ? <span style={{ flexShrink: 0 }}>🚫</span> : null}
        <span style={{ color: '#334155', flexShrink: 0 }}>
          {expanded ? <ChevronUp size={12} /> : <ChevronDown size={12} />}
        </span>
      </div>

      {/* Expanded body */}
      {expanded && (
        <div style={{ padding: '0 12px 12px', borderTop: '1px solid #0f2035' }}>
          <div style={{ padding: '7px 0', color: '#64748b', fontSize: '11px', borderBottom: '1px solid #0f2035' }}>
            {route.description}
          </div>

          {/* Meta row */}
          <div style={{ display: 'flex', gap: '16px', padding: '7px 0', flexWrap: 'wrap', borderBottom: '1px solid #0f2035' }}>
            {route.frontendService && (
              <div>
                <div style={{ fontSize: '8px', color: '#1e3a5f', letterSpacing: '0.15em', marginBottom: '3px' }}>FE SERVICE</div>
                <code style={{ color: '#06b6d4', fontSize: '10.5px' }}>{route.frontendService}</code>
                {route.frontendServiceFile && (
                  <span style={{ fontSize: '9px', color: '#0369a1', marginLeft: 6 }}>{route.frontendServiceFile}</span>
                )}
              </div>
            )}
            {route.frontendPages?.length ? (
              <div>
                <div style={{ fontSize: '8px', color: '#1e3a5f', letterSpacing: '0.15em', marginBottom: '3px' }}>PAGES</div>
                <div style={{ color: '#38bdf8', fontSize: '10.5px' }}>{route.frontendPages.join(', ')}</div>
              </div>
            ) : null}
            {route.deprecated_by && (
              <div>
                <div style={{ fontSize: '8px', color: '#ef4444', letterSpacing: '0.15em', marginBottom: '3px' }}>REPLACED BY</div>
                <code style={{ color: '#f87171', fontSize: '10.5px' }}>{route.deprecated_by}</code>
              </div>
            )}
          </div>

          {/* Request cycle */}
          <div style={{ marginTop: '10px' }}>
            <div style={{ fontSize: '8px', color: '#1e3a5f', letterSpacing: '0.15em', marginBottom: '6px' }}>REQUEST CYCLE</div>
            <div style={{ background: '#060e18', borderRadius: '5px', border: '1px solid #0f2035' }}>
              {route.cycle.map((step, i) => (
                <div key={i} style={{
                  display: 'grid', gridTemplateColumns: '68px 1fr', gap: '8px',
                  padding: '5px 8px',
                  borderBottom: i < route.cycle.length - 1 ? '1px solid #0a1830' : 'none',
                  color: step.warning ? '#f59e0b' : '#c8d8e8',
                }}>
                  <div style={{ fontSize: '8px', color: step.warning ? '#f59e0b' : '#334155', textTransform: 'uppercase', letterSpacing: '0.08em', paddingTop: 2 }}>
                    {step.layer}
                  </div>
                  <div>
                    <span style={{ fontSize: '11px' }}>{step.detail}</span>
                    {step.file && (
                      <span style={{ fontSize: '9px', color: '#0369a1', marginLeft: 6 }}>{step.file}</span>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Command types */}
          {route.commandTypes && (
            <div style={{ marginTop: '8px' }}>
              <div style={{ fontSize: '8px', color: '#1e3a5f', marginBottom: '5px', letterSpacing: '0.12em' }}>COMMAND TYPES</div>
              <div style={{ display: 'flex', gap: '4px', flexWrap: 'wrap' }}>
                {route.commandTypes.map(t => (
                  <code key={t} style={{ background: '#0a1525', border: '1px solid #1a3550', borderRadius: '3px', padding: '2px 6px', fontSize: '9.5px', color: '#06b6d4' }}>{t}</code>
                ))}
              </div>
            </div>
          )}

          {/* Aliases */}
          {route.aliases && (
            <div style={{ marginTop: '8px' }}>
              <div style={{ fontSize: '8px', color: '#1e3a5f', marginBottom: '5px', letterSpacing: '0.12em' }}>ALIASES</div>
              <div style={{ display: 'flex', gap: '4px', flexWrap: 'wrap' }}>
                {route.aliases.map(a => (
                  <code key={a} style={{ background: '#120800', border: '1px solid #f59e0b20', borderRadius: '3px', padding: '2px 6px', fontSize: '9.5px', color: '#f59e0b' }}>{a}</code>
                ))}
              </div>
            </div>
          )}

          {/* Notes */}
          {route.notes && (
            <div style={{ marginTop: '8px', padding: '7px 9px', background: '#0a1525', borderRadius: '4px', fontSize: '10.5px', color: '#475569', lineHeight: 1.6 }}>
              ℹ️ {route.notes}
            </div>
          )}

          {/* Warnings */}
          {route.warnings?.length ? (
            <div style={{ background: 'rgba(245,158,11,0.05)', border: '1px solid rgba(245,158,11,0.18)', borderRadius: '5px', padding: '8px 10px', marginTop: '8px' }}>
              <div style={{ fontSize: '8.5px', color: '#f59e0b', letterSpacing: '0.12em', marginBottom: '5px' }}>⚠️ WARNINGS</div>
              {route.warnings.map((w, i) => (
                <div key={i} style={{ fontSize: '10.5px', color: '#f59e0b', marginBottom: '3px', lineHeight: 1.5 }}>• {w}</div>
              ))}
            </div>
          ) : null}
        </div>
      )}
    </div>
  )
}
