// ═══════════════════════════════════════════════════════════════
// PRESTIGE DASHBOARD - Virtual Assistant (Local-only)
// ═══════════════════════════════════════════════════════════════

import React, { useState, useRef, useEffect } from 'react'
import {
  Bot, User, Send, Trash2,
  X, Minus, ChevronUp, Zap,
} from 'lucide-react'
import { useUIStore, selectAssistantOpen } from '@core/state'
import { findLocalAnswer } from './localKnowledge'

interface Message {
  id: string
  role: 'user' | 'assistant'
  content: string
}

let _id = 0
function uid() { return String(++_id) }

function md(text: string) {
  return text
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/`([^`\n]+)`/g, '<code style="background:rgba(6,182,212,0.15);padding:1px 5px;border-radius:4px;font-family:monospace;font-size:11px;color:#67e8f9">$1</code>')
    .replace(/\n/g, '<br/>')
}

const WELCOME: Message = {
  id: 'w',
  role: 'assistant',
  content: "Hi! I'm the **PRESTIGE Assistant**. I can instantly answer questions about your dashboard, printers, Klipper, calibration, and more — all from built-in local knowledge.",
}

const SUGGESTIONS = [
  'Why is my printer offline?',
  'How do I add a printer?',
  'What does AI Insights do?',
  'How do I restore a backup?',
  'How do I fix stringing?',
  'How do I pause a print?',
]

const NOT_FOUND_ANSWERS = [
  `I don't have a specific answer for that in my knowledge base yet. Try rephrasing your question, or check the **FAQ** section on the Support page for a full list of covered topics.`,
  `That one's outside my current knowledge base. You might find the answer in the **Support → FAQ** section, or open a GitHub Discussion for community help.`,
  `I couldn't find a match for that question. Try different keywords, or head to **Support → FAQ** for the full guide.`,
]

function notFoundAnswer(): string {
  return NOT_FOUND_ANSWERS[Math.floor(Math.random() * NOT_FOUND_ANSWERS.length)]
}

export function VirtualAssistant() {
  const open  = useUIStore(selectAssistantOpen)
  const close = useUIStore((s) => s.closeAssistant)

  const [msgs,    setMsgs]    = useState<Message[]>([WELCOME])
  const [input,   setInput]   = useState('')
  const [thinking, setThinking] = useState(false)
  const [mini,    setMini]    = useState(false)

  const bottomRef = useRef<HTMLDivElement>(null)
  const inputRef  = useRef<HTMLInputElement>(null)

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' })
  }, [msgs, thinking])

  useEffect(() => {
    if (open && !mini) setTimeout(() => inputRef.current?.focus(), 100)
  }, [open, mini])

  useEffect(() => {
    if (open) setMini(false)
  }, [open])

  // ─────────────────────────────────────────────────────────────
  async function send(text: string) {
    const q = text.trim()
    if (!q || thinking) return

    const userMsg: Message = { id: uid(), role: 'user', content: q }
    setMsgs((prev) => [...prev, userMsg])
    setInput('')
    setThinking(true)

    // Small delay so the UI feels responsive, not instant-robotic
    await new Promise((r) => setTimeout(r, 180))

    const local = findLocalAnswer(q)
    const reply = local ? local.entry.answer : notFoundAnswer()

    setMsgs((prev) => [
      ...prev,
      { id: uid(), role: 'assistant', content: reply },
    ])
    setThinking(false)
  }
  // ─────────────────────────────────────────────────────────────

  function clear() {
    setMsgs([WELCOME])
    setInput('')
  }

  if (!open) return null

  const s: Record<string, React.CSSProperties> = {
    root: {
      position: 'fixed', bottom: 80, right: 24, zIndex: 9999,
      width: 384, height: mini ? 56 : 520,
      display: 'flex', flexDirection: 'column',
      borderRadius: 20, overflow: 'hidden',
      background: '#0d1117',
      border: '1px solid rgba(255,255,255,0.1)',
      boxShadow: '0 24px 64px rgba(0,0,0,0.8), 0 0 0 1px rgba(6,182,212,0.12)',
      transition: 'height .25s ease',
      fontFamily: 'inherit',
    },
    header: {
      height: 56, minHeight: 56, flexShrink: 0,
      display: 'flex', alignItems: 'center', justifyContent: 'space-between',
      padding: '0 14px',
      background: 'rgba(255,255,255,0.03)',
      borderBottom: '1px solid rgba(255,255,255,0.07)',
    },
    iconWrap: {
      width: 32, height: 32, borderRadius: 10, flexShrink: 0,
      background: 'linear-gradient(135deg,#06b6d4,#3b82f6)',
      display: 'flex', alignItems: 'center', justifyContent: 'center',
      boxShadow: '0 4px 14px rgba(6,182,212,0.35)',
      position: 'relative',
    },
    dot: {
      position: 'absolute', bottom: -2, right: -2,
      width: 9, height: 9, borderRadius: '50%',
      background: '#4ade80', border: '2px solid #0d1117',
    },
    btn: {
      width: 28, height: 28, borderRadius: 7, border: 'none',
      background: 'transparent', cursor: 'pointer', color: '#64748b',
      display: 'flex', alignItems: 'center', justifyContent: 'center',
    },
    messages: {
      flex: 1, overflowY: 'auto',
      padding: '12px 12px 4px',
      display: 'flex', flexDirection: 'column', gap: 10,
    },
    inputArea: {
      padding: '10px 12px 12px', flexShrink: 0,
      borderTop: '1px solid rgba(255,255,255,0.06)',
      background: 'rgba(0,0,0,0.25)',
    },
    input: {
      flex: 1, padding: '9px 13px', borderRadius: 11,
      border: '1px solid rgba(255,255,255,0.1)',
      background: 'rgba(255,255,255,0.05)',
      color: '#f1f5f9', fontSize: 13, outline: 'none',
    },
    sendBtn: {
      width: 38, height: 38, borderRadius: 10, border: 'none',
      background: 'linear-gradient(135deg,#06b6d4,#3b82f6)',
      display: 'flex', alignItems: 'center', justifyContent: 'center',
      flexShrink: 0,
      boxShadow: '0 4px 12px rgba(6,182,212,0.3)',
    },
  }

  return (
    <div style={s.root}>

      {/* ── Header ── */}
      <div style={s.header}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
          <div style={{ position: 'relative', flexShrink: 0 }}>
            <div style={s.iconWrap}><Bot size={16} color="white" /></div>
            <span style={s.dot} />
          </div>
          <div>
            <div style={{ fontSize: 13, fontWeight: 600, color: '#f1f5f9' }}>PRESTIGE Assistant</div>
            <div style={{ fontSize: 10, color: 'rgba(74,222,128,0.8)', marginTop: 1, display: 'flex', alignItems: 'center', gap: 3 }}>
              <Zap size={8} /> local · instant · no internet needed
            </div>
          </div>
        </div>
        <div style={{ display: 'flex', gap: 2 }}>
          {msgs.length > 1 && !mini && (
            <button style={s.btn} onClick={clear} title="Clear chat">
              <Trash2 size={13} color="#64748b" />
            </button>
          )}
          <button style={s.btn} onClick={() => setMini((p) => !p)}>
            {mini ? <ChevronUp size={14} color="#64748b" /> : <Minus size={14} color="#64748b" />}
          </button>
          <button style={s.btn} onClick={() => { close(); setMini(false) }}>
            <X size={14} color="#64748b" />
          </button>
        </div>
      </div>

      {/* ── Body ── */}
      {!mini && (
        <>
          {/* Messages */}
          <div style={s.messages}>
            {msgs.map((m) => (
              <div key={m.id} style={{ display: 'flex', flexDirection: m.role === 'user' ? 'row-reverse' : 'row', alignItems: 'flex-end', gap: 7 }}>
                <div style={{
                  width: 24, height: 24, borderRadius: 7, flexShrink: 0,
                  background: m.role === 'assistant' ? 'linear-gradient(135deg,#06b6d4,#3b82f6)' : '#1e293b',
                  display: 'flex', alignItems: 'center', justifyContent: 'center',
                }}>
                  {m.role === 'assistant' ? <Bot size={12} color="white" /> : <User size={12} color="#94a3b8" />}
                </div>
                <div style={{ maxWidth: '80%' }}>
                  <div
                    dangerouslySetInnerHTML={{ __html: md(m.content) }}
                    style={{
                      padding: '9px 13px',
                      borderRadius: m.role === 'assistant' ? '14px 14px 14px 3px' : '14px 14px 3px 14px',
                      fontSize: 13, lineHeight: 1.55,
                      color: m.role === 'assistant' ? '#e2e8f0' : '#ecfeff',
                      background: m.role === 'assistant'
                        ? 'rgba(255,255,255,0.06)'
                        : 'linear-gradient(135deg,rgba(6,182,212,0.22),rgba(59,130,246,0.18))',
                      border: m.role === 'user' ? '1px solid rgba(6,182,212,0.2)' : 'none',
                    }}
                  />
                </div>
              </div>
            ))}

            {/* Suggestions — shown only on the welcome screen */}
            {msgs.length === 1 && !thinking && SUGGESTIONS.map((q) => (
              <button key={q} onClick={() => send(q)} style={{
                textAlign: 'left', padding: '8px 12px', borderRadius: 11, cursor: 'pointer',
                background: 'rgba(6,182,212,0.06)', border: '1px solid rgba(6,182,212,0.18)',
                color: 'rgba(103,232,249,0.85)', fontSize: 12,
                display: 'flex', alignItems: 'center', gap: 8,
              }}>
                <Zap size={10} color="rgba(251,191,36,0.7)" style={{ flexShrink: 0 }} />
                {q}
              </button>
            ))}

            {/* Thinking indicator */}
            {thinking && (
              <div style={{ display: 'flex', alignItems: 'flex-end', gap: 7 }}>
                <div style={{ width: 24, height: 24, borderRadius: 7, background: 'linear-gradient(135deg,#06b6d4,#3b82f6)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                  <Bot size={12} color="white" />
                </div>
                <div style={{ background: 'rgba(255,255,255,0.06)', borderRadius: '14px 14px 14px 3px', padding: '12px 16px', display: 'flex', alignItems: 'center', gap: 6 }}>
                  {[0, 1, 2].map((i) => (
                    <span key={i} style={{
                      width: 6, height: 6, borderRadius: '50%',
                      background: '#06b6d4', display: 'inline-block',
                      animation: `pulse 1.2s ease-in-out ${i * 0.2}s infinite`,
                    }} />
                  ))}
                </div>
              </div>
            )}

            <div ref={bottomRef} style={{ height: 4 }} />
          </div>

          {/* Input */}
          <div style={s.inputArea}>
            <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
              <input
                ref={inputRef}
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => { if (e.key === 'Enter') { e.preventDefault(); send(input) } }}
                placeholder="Ask anything about PRESTIGE…"
                disabled={thinking}
                style={{ ...s.input, opacity: thinking ? 0.5 : 1 }}
                onFocus={(e) => (e.target.style.borderColor = 'rgba(6,182,212,0.5)')}
                onBlur={(e) => (e.target.style.borderColor = 'rgba(255,255,255,0.1)')}
              />
              <button
                onClick={() => send(input)}
                disabled={thinking || !input.trim()}
                style={{ ...s.sendBtn, cursor: thinking || !input.trim() ? 'not-allowed' : 'pointer', opacity: thinking || !input.trim() ? 0.35 : 1 }}
              >
                <Send size={15} color="white" />
              </button>
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: 6, fontSize: 10, color: 'rgba(100,116,139,0.7)' }}>
              <span style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
                <Zap size={8} color="rgba(74,222,128,0.5)" /> runs fully local · no API
              </span>
              <span>Enter to send</span>
            </div>
          </div>
        </>
      )}

      <style>{`
        @keyframes pulse {
          0%, 80%, 100% { transform: scale(0.7); opacity: 0.4; }
          40% { transform: scale(1); opacity: 1; }
        }
      `}</style>
    </div>
  )
}

export default VirtualAssistant
