/**
 * Get Lucide icon component
 */
const getIconComponent = (iconName: string) => {
  const icons: Record<string, React.ComponentType<any>> = {
    check: CheckCircle2,
    play: Play,
    pause: Pause,
    alert: AlertTriangle,
    'wifi-off': WifiOff,
    wrench: Wrench,
    bot: Bot,
    circle: Circle,
    clock: Clock,
    activity: Activity,
  }
  return icons[iconName] || Circle
}

