/**
 * Enhanced StatusIndicator Component
 * 
 * New Features (FE-03):
 * - Lucide React icons instead of emoji
 * - 4 display variants: dot, badge, pulse, icon
 * - Status-specific colors with glow effects
 * - Smooth transition animations
 * - Pulsing for active states
 * - Hover effects
 */
export const StatusIndicator: React.FC<StatusIndicatorProps> = ({
  status,
  variant,
  size = 'md',
  mode = 'badge',
  showLabel = true,
  label,
  pulse,
  animated = true,
  className = '',
  onClick,
}) => {
  // Determine config from status or variant
  const config = variant
    ? VARIANT_CONFIG[variant] || VARIANT_CONFIG.muted
    : status
      ? STATUS_CONFIG[status] || STATUS_CONFIG.disconnected
      : VARIANT_CONFIG.muted

  const sizeConfig = SIZE_CONFIG[size] || SIZE_CONFIG.md
  const shouldPulse = animated && (pulse !== undefined ? pulse : config.pulse)
  const IconComponent = getIconComponent(config.icon)
  const animationClass = animated && status ? getStatusAnimation(status, mode) : ''

  // Dot mode - simple colored dot
  if (mode === 'dot') {
    return (
      <div
        className={`inline-flex items-center ${className}`}
        title={`${config.label}: ${config.description}`}
        onClick={onClick}
        style={{ cursor: onClick ? 'pointer' : 'default' }}
      >
        <StatusDot
          config={config}
          size={size}
          pulse={shouldPulse}
          animated={animated}
        />
      </div>
    )
  }

  // Pulse mode - dot with prominent pulse effect
  if (mode === 'pulse') {
    return (
      <div
        className={`relative inline-flex items-center justify-center ${className}`}
        title={`${config.label}: ${config.description}`}
        onClick={onClick}
        style={{ cursor: onClick ? 'pointer' : 'default' }}
      >
        <div
          className={`rounded-full ${sizeConfig.dot} ${TRANSITION_CLASSES.all}`}
          style={{
            backgroundColor: config.color,
            boxShadow: `0 0 12px ${config.color}`,
          }}
        />
        {shouldPulse && (
          <>
            <span
              className="absolute inset-0 rounded-full animate-ping"
              style={{
                backgroundColor: config.color,
                animationDuration: '2s',
              }}
            />
            <span
              className="absolute -inset-1 rounded-full animate-ping"
              style={{
                backgroundColor: config.color,
                opacity: 0.4,
                animationDuration: '2s',
                animationDelay: '1s',
              }}
            />
          </>
        )}
      </div>
    )
  }

  // Icon mode - just the icon with color
  if (mode === 'icon') {
    return (
      <div
        className={`inline-flex items-center ${className} ${animationClass} ${TRANSITION_CLASSES.colors}`}
        title={`${config.label}: ${config.description}`}
        onClick={onClick}
        style={{
          color: config.color,
          cursor: onClick ? 'pointer' : 'default',
        }}
      >
        <IconComponent
          className={`${sizeConfig.icon} ${shouldPulse ? 'animate-pulse' : ''}`}
          strokeWidth={2.5}
        />
      </div>
    )
  }

  // Badge mode (default) - dot + label in badge
  return (
    <StatusBadge
      config={config}
      size={size}
      showLabel={showLabel}
      label={label}
      pulse={shouldPulse}
      animated={animated}
      onClick={onClick}
    />
  )
}

StatusIndicator.displayName = 'StatusIndicator'

export default StatusIndicator
